class _ResponsiveComposeWorkbenchDialog(QDialog):
    """Non-modal compose workbench that coalesces resize layout updates."""

    def __init__(self, parent: QWidget, on_resize: Callable[[], None]):
        super().__init__(parent)
        self._on_compose_resize = on_resize

    def resizeEvent(self, event) -> None:
        super().resizeEvent(event)
        # The splitter hierarchy needs the dialog's final viewport size.  Queue
        # one update so interactive resize remains responsive instead of
        # recalculating geometry for every native resize event.
        QTimer.singleShot(0, self._on_compose_resize)


class _ComposeSetupGroupBox(QGroupBox):
    """Compose setup box that distinguishes authored floors from layout floors."""

    def __init__(self, title: str = "", parent: QWidget | None = None):
        super().__init__(title, parent)
        self._compose_derived_height_update = False
        self._compose_explicit_minimum_height = 0

    def setMinimumHeight(self, height: int) -> None:  # noqa: N802 - Qt API
        value = max(0, int(height))
        if not self._compose_derived_height_update:
            self._compose_explicit_minimum_height = value
        super().setMinimumHeight(value)

    def set_derived_minimum_height(self, height: int) -> None:
        self._compose_derived_height_update = True
        try:
            super().setMinimumHeight(max(0, int(height)))
        finally:
            self._compose_derived_height_update = False

    @property
    def explicit_minimum_height(self) -> int:
        return max(0, int(self._compose_explicit_minimum_height))


class _FontBoundedLineEdit(QLineEdit):
    """Single-line editor whose compact width follows the active font."""

    def __init__(self, *, display_columns: int, max_length: int, parent: QWidget | None = None):
        self._display_columns = max(1, int(display_columns))
        super().__init__(parent)
        self.setMaxLength(max(1, int(max_length)))
        self.setSizePolicy(QSizePolicy.Fixed, QSizePolicy.Fixed)
        self._refresh_font_width()

    def _refresh_font_width(self) -> None:
        metrics = self.fontMetrics()
        width = metrics.horizontalAdvance("0" * self._display_columns) + metrics.horizontalAdvance("MM")
        self.setMinimumWidth(width)
        self.setMaximumWidth(width)

    def event(self, event) -> bool:
        handled = super().event(event)
        if event.type() in {QEvent.FontChange, QEvent.ApplicationFontChange, QEvent.StyleChange}:
            self._refresh_font_width()
        return handled

