def _fallback_custom_form_labels(fields: Mapping[str, str]) -> List[Tuple[str, str]]:
    keys = {str(k or "").strip().upper() for k in fields}
    if {"L05", "L06"}.issubset(keys):
        return [
            ("L01", "To"),
            ("L02", "From"),
            ("L03", "Precedence"),
            ("L04", "Date/Msg ID"),
            ("L05", "Subject"),
            ("L06", "Message"),
        ]
    if {"L01", "L02", "L03", "L04"}.issubset(keys):
        return [
            ("L01", "To"),
            ("L02", "From"),
            ("L03", "Subject"),
            ("L04", "Message"),
        ]
    return []


def _strip_html_text(text: str) -> str:
    if not text:
        return ""
    text = re.sub(r"<[^>]+>", " ", text)
    return re.sub(r"\s+", " ", text).strip()


def _extract_template_title_text(template: str) -> str:
    if not template:
        return ""
    m = re.search(r"<title>(.*?)</title>", template, flags=re.IGNORECASE | re.DOTALL)
    return _strip_html_text(m.group(1)) if m else ""


