class _ComposeStageWorker(QObject):
    """Run one immutable compose stage/sign/publish request off the GUI thread."""

    finished = Signal(object)

    def __init__(self, request: ComposeStageRequest, summary_context=None):
        super().__init__()
        self._request = request
        self._summary_context = summary_context

    def run(self) -> None:
        try:
            if self._summary_context is not None:
                from freqinout.core.traffic_summary_stage import stage_summary_request
                result = stage_summary_request(self._request, self._summary_context)
            else:
                result = stage_compose_request(self._request)
        except Exception as exc:
            result = ComposeStageResult(
                generation=self._request.generation,
                problems=(f"Compose staging failed: {exc}",),
            )
        self.finished.emit(result)


class _ComposeJs8SendWorker(QObject):
    """Perform guarded JS8 API preflight/send without blocking the GUI thread."""

    finished = Signal(object)

    def __init__(
        self,
        *,
        endpoint: JS8ApiEndpoint,
        command: str,
        generation: int,
        allow_uncertain_target_state: bool,
    ):
        super().__init__()
        self._endpoint = endpoint
        self._command = command
        self._generation = int(generation)
        self._allow_uncertain = bool(allow_uncertain_target_state)

    def run(self) -> None:
        try:
            client = JS8ApiClientRegistry.get(self._endpoint, timeout_s=1.0, auto_reconnect=True)
            result = send_js8_message_guarded(
                client,
                self._command,
                timeout_s=0.6,
                allow_uncertain_target_state=self._allow_uncertain,
                clear_selected_target=True,
            )
            payload = {
                "generation": self._generation,
                "endpoint": self._endpoint,
                "command": self._command,
                "allow_uncertain": self._allow_uncertain,
                "result": result,
                "error": "",
            }
        except Exception as exc:
            payload = {
                "generation": self._generation,
                "endpoint": self._endpoint,
                "command": self._command,
                "allow_uncertain": self._allow_uncertain,
                "result": None,
                "error": str(exc),
            }
        self.finished.emit(payload)


class _ComposeJs8SelectedTargetWorker(QObject):
    """Read or clear one JS8Call UI target selection outside the GUI thread."""

    finished = Signal(object)

    def __init__(self, *, endpoint: JS8ApiEndpoint, context: Mapping[str, object]):
        super().__init__()
        self._endpoint = endpoint.normalized()
        self._context = dict(context)
        self._cancel_event = threading.Event()

    def cancel(self) -> None:
        """Fence a queued clear before the endpoint helper mutates selection."""
        self._cancel_event.set()

    def _cancelled(self) -> bool:
        return self._cancel_event.is_set()

    def run(self) -> None:
        payload = dict(self._context)
        if self._cancelled():
            if str(self._context.get("action", "refresh") or "refresh") == "clear":
                payload.update(
                    {
                        "result": None,
                        "status": "cancelled",
                        "cleared": False,
                        "supported": False,
                        "target": "",
                        "error": "Selection clear cancelled before endpoint access.",
                    }
                )
            self.finished.emit(payload)
            return
        try:
            client = JS8ApiClientRegistry.get(self._endpoint, timeout_s=0.8, auto_reconnect=True)
            if str(self._context.get("action", "refresh") or "refresh") == "clear":
                result = clear_js8_selected_target(
                    client,
                    self._context.get("expected_target", ""),
                    timeout_s=0.8,
                    cancelled=self._cancelled,
                )
                state = result.state
                payload.update(
                    {
                        "result": result,
                        "status": str(result.status or "failed"),
                        "cleared": bool(result.cleared),
                        "supported": bool(state.available),
                        "target": state.target,
                        "error": str(result.detail or state.detail or ""),
                    }
                )
            else:
                state = query_js8_selected_target(client, timeout_s=0.6)
                payload.update(
                    {
                        "supported": bool(state.available),
                        "target": state.target,
                        "error": state.detail,
                    }
                )
        except Exception as exc:
            payload.update({"supported": False, "target": "", "error": str(exc)})
        self.finished.emit(payload)


class _ComposeCatalogDiscoveryWorker(QObject):
    """Discover and parse bounded compose catalogs without using Qt widgets."""

    finished = Signal(object)

    def __init__(
        self,
        *,
        generation: int,
        mode: str,
        settings_snapshot: Mapping[str, object],
        spotter_candidates: Sequence[str],
    ):
        super().__init__()
        self._generation = int(generation)
        self._mode = str(mode or "nbems")
        self._settings = dict(settings_snapshot)
        self._spotter_candidates = tuple(str(value or "").strip() for value in spotter_candidates if str(value or "").strip())

    def run(self) -> None:
        entries: List[dict] = []
        parsed: Dict[str, Dict[str, object]] = {}
        problems: List[str] = []
        try:
            if self._mode != "spotter":
                entries.append({"kind": "standard", "key": "STANDARD", "label": "Standard Blank"})
                for family in discover_form_families(self._settings):
                    templates = discover_forms_for_family(family)
                    entries.append(
                        {
                            "kind": "family",
                            "key": family.key,
                            "label": family.label,
                            "family": family,
                            "templates": templates,
                        }
                    )
                    for template in templates:
                        key = str(template.path)
                        try:
                            text_value = template.path.read_text(encoding="utf-8", errors="replace")
                            parsed[key] = {
                                "title": extract_compose_template_title(text_value),
                                "menu_item": extract_compose_menu_item(text_value),
                                "rows": parse_compose_template_fields(text_value),
                            }
                        except Exception as exc:
                            problems.append(f"{template.path.name}: {exc}")
            else:
                forms = []
                if self._spotter_candidates:
                    # The caller has already applied global > legacy-radio >
                    # bundled precedence. Discovery is the worker boundary;
                    # it never probes alternate sources after an explicit
                    # choice is missing or empty.
                    forms = discover_effective_spotter_forms(self._spotter_candidates[0])
                entries.append(
                    {
                        "kind": "spotter",
                        "key": "JS8SPOTTER",
                        "label": "CommsPlan Spotter Forms",
                        "forms": forms,
                    }
                )
                for form in forms:
                    key = str(getattr(form, "path", "") or "")
                    if not key:
                        continue
                    try:
                        text_value = Path(key).read_text(encoding="utf-8", errors="replace")
                        parsed[key] = {
                            "spotter_rows": parse_spotter_form_fields(text_value),
                            "spotter_guidance": parse_spotter_form_guidance(text_value),
                        }
                    except Exception as exc:
                        problems.append(f"{Path(key).name}: {exc}")
        except Exception as exc:
            problems.append(str(exc))
        self.finished.emit(
            {
                "generation": self._generation,
                "mode": self._mode,
                "entries": entries,
                "parsed": parsed,
                "problems": problems,
            }
        )


class _ComposeMeshDiscoveryWorker(QObject):
    """Read the bounded Mesh model without blocking navigation or selection."""

    finished = Signal(object)

    def __init__(self, generation: int, values: dict, db_path: Path):
        super().__init__()
        self.generation, self.values, self.db_path = generation, values, db_path

    def run(self) -> None:
        result = {"generation": self.generation, "configs": [], "health": {}, "destinations": {}, "favorites": {}}
        try:
            configs = [config for config in load_mesh_connection_configs(self.values)
                       if config.enabled and config.send_enabled
                       and mesh_outbound_capability(config.protocol, config.connection_type).supported]
            result["configs"] = configs
            if configs:
                result["health"] = {str(row.get("adapter_id") or ""): dict(row)
                                   for row in list_mesh_health(self.db_path, read_only=True)}
            for config in configs:
                if QThread.currentThread().isInterruptionRequested():
                    break
                try:
                    favorites = list_contact_favorites(self.db_path, config.adapter_id)
                    result["favorites"][config.adapter_id] = tuple(favorites)
                    result["destinations"][config.adapter_id] = (
                        list_mesh_channel_policies(self.db_path, adapter_id=config.adapter_id, read_only=True),
                        list_mesh_nodes(self.db_path, adapter_id=config.adapter_id, limit=200, read_only=True),
                    )
                except Exception as exc:
                    result["error"] = str(exc)
        except Exception as exc:
            result["error"] = str(exc)
        self.finished.emit(result)


