class _ComposeTargetGuidanceWorker(QObject):
    """Resolve target-scoped RF guidance and MsgAuth keys off the GUI thread."""

    finished = Signal(object)

    def __init__(
        self,
        *,
        generation: int,
        db_path: str,
        target: str,
        target_is_group: bool,
        operator_callsign: str,
        cutoff_ts: float,
        now_utc: datetime.datetime,
        radio_options: Sequence[ComposeRadioOption],
        selected_radio_id: int,
        last_heard: ComposeLastHeard | None,
        load_auth_keys: bool,
    ):
        super().__init__()
        self._generation = int(generation)
        self._db_path = str(db_path or "")
        self._target = str(target or "").strip().upper()
        self._target_is_group = bool(target_is_group)
        self._operator_callsign = str(operator_callsign or "").strip().upper()
        self._cutoff_ts = float(cutoff_ts)
        self._now_utc = now_utc
        self._radio_options = tuple(radio_options)
        self._selected_radio_id = int(selected_radio_id or 0)
        self._last_heard = last_heard
        self._load_auth_keys = bool(load_auth_keys)

    @staticmethod
    def _minutes(value: object) -> int | None:
        match = re.match(r"^(\d{1,2}):(\d{2})", str(value or "").strip())
        if not match:
            return None
        hour, minute = int(match.group(1)), int(match.group(2))
        return hour * 60 + minute if hour <= 23 and minute <= 59 else None

    def _minutes_to_end(self, day_utc: object, start_min: int, end_min: int) -> int | None:
        day = str(day_utc or "ALL").strip().upper()
        aliases = {
            "MONDAY": "MON", "TUESDAY": "TUE", "WEDNESDAY": "WED",
            "THURSDAY": "THU", "FRIDAY": "FRI", "SATURDAY": "SAT", "SUNDAY": "SUN",
        }
        day = aliases.get(day, day[:3] if len(day) > 3 else day)
        weekday = self._now_utc.strftime("%a").upper()[:3]
        if day not in {"", "ALL", "ANY", "*", weekday}:
            return None
        now_min = self._now_utc.hour * 60 + self._now_utc.minute
        if end_min <= start_min:
            if now_min >= start_min or now_min < end_min:
                return (end_min - now_min) % (24 * 60) or 24 * 60
            return None
        return end_min - now_min if start_min <= now_min < end_min else None

    def _peer_schedule(self, conn: sqlite3.Connection) -> ComposePeerSchedule | None:
        if not self._target or self._target_is_group:
            return None
        has_view = conn.execute(
            "SELECT 1 FROM sqlite_master WHERE type='view' AND name='peer_hf_schedule_effective'"
        ).fetchone()
        table_name = "peer_hf_schedule_effective" if has_view else "peer_hf_schedule"
        try:
            rows = conn.execute(
                f"SELECT owner_callsign, day_utc, start_utc, end_utc, band, mode, frequency "
                f"FROM {table_name} WHERE UPPER(owner_callsign)=?",
                (self._target,),
            ).fetchall()
        except sqlite3.Error:
            return None
        best: ComposePeerSchedule | None = None
        for cs, day_utc, start_utc, end_utc, band, mode, freq in rows:
            start_min, end_min = self._minutes(start_utc), self._minutes(end_utc)
            if start_min is None or end_min is None:
                continue
            minutes_to_end = self._minutes_to_end(day_utc, start_min, end_min)
            if minutes_to_end is None:
                continue
            try:
                frequency = float(str(freq or "").strip())
            except Exception:
                frequency = None
            if frequency is not None and frequency > 1000:
                frequency /= 1_000_000.0
            candidate = ComposePeerSchedule(
                callsign=str(cs or self._target).strip().upper(),
                band=str(band or "").strip().upper(),
                frequency_mhz=frequency,
                mode=str(mode or "").strip().upper(),
                minutes_to_end=int(minutes_to_end),
            )
            if best is None or candidate.minutes_to_end < best.minutes_to_end:
                best = candidate
        return best

    @staticmethod
    def _base_call(value: object) -> str:
        raw = str(value or "").strip().upper().lstrip("@")
        return re.sub(r"/(P|M|MM|QRP|SOTA|ROVER|[A-Z0-9]{1,4})$", "", raw) if raw else ""

    @staticmethod
    def _age_label(ts_value: object) -> str:
        try:
            age = max(0.0, time.time() - float(ts_value or 0.0))
        except Exception:
            return ""
        if age < 90:
            return "just now"
        if age < 3600:
            return f"{int(age // 60)}m ago"
        if age < 86400:
            return f"{age / 3600.0:.1f}h ago"
        return f"{age / 86400.0:.1f}d ago"

    def _path_evidence(self, conn: sqlite3.Connection) -> ComposePathEvidence | None:
        target_call = self._base_call(self._target)
        my_call = self._base_call(self._operator_callsign)
        if not target_call or not my_call or target_call == my_call or self._target_is_group:
            return None
        try:
            direct = conn.execute(
                """
                SELECT ts, snr, band, source_radio_id FROM js8_links
                 WHERE ts >= ? AND ((UPPER(origin)=? AND UPPER(destination)=?)
                    OR (UPPER(origin)=? AND UPPER(destination)=?))
                 ORDER BY ts DESC LIMIT 1
                """,
                (self._cutoff_ts, my_call, target_call, target_call, my_call),
            ).fetchone()
        except sqlite3.Error:
            return None
        if direct:
            ts, snr, band, radio_id = direct
            try:
                radio_id_int = int(radio_id or 0)
            except Exception:
                radio_id_int = 0
            return ComposePathEvidence(
                kind="direct", radio_id=radio_id_int,
                band=str(band or "").strip().upper(), source="JS8Call",
                age_label=self._age_label(ts), snr=float(snr) if snr is not None else None,
            )
        try:
            relay = conn.execute(
                """
                WITH recent AS (
                    SELECT ts, origin, destination, snr, band FROM js8_links
                     WHERE ts >= ? AND origin IS NOT NULL AND destination IS NOT NULL
                ), mine AS (
                    SELECT CASE WHEN UPPER(origin)=? THEN UPPER(destination) ELSE UPPER(origin) END relay,
                           MAX(ts) ts, band FROM recent
                     WHERE UPPER(origin)=? OR UPPER(destination)=? GROUP BY relay
                ), theirs AS (
                    SELECT CASE WHEN UPPER(origin)=? THEN UPPER(destination) ELSE UPPER(origin) END relay,
                           MAX(ts) ts, band FROM recent
                     WHERE UPPER(origin)=? OR UPPER(destination)=? GROUP BY relay
                )
                SELECT mine.relay, MAX(mine.ts, theirs.ts), COALESCE(theirs.band, mine.band, '')
                  FROM mine JOIN theirs ON theirs.relay=mine.relay
                 WHERE mine.relay NOT IN (?, ?) ORDER BY 2 DESC LIMIT 1
                """,
                (self._cutoff_ts, my_call, my_call, my_call, target_call, target_call, target_call, my_call, target_call),
            ).fetchone()
        except sqlite3.Error:
            return None
        if not relay:
            return None
        relay_call, ts, band = relay
        return ComposePathEvidence(
            kind="relay", band=str(band or "").strip().upper(), source="JS8Call",
            relay=str(relay_call or "").strip().upper(), age_label=self._age_label(ts),
        )

    def run(self) -> None:
        peer_schedule: ComposePeerSchedule | None = None
        path_evidence: ComposePathEvidence | None = None
        if self._db_path and Path(self._db_path).exists() and self._target and not self._target_is_group:
            try:
                conn = connect_sqlite_readonly(Path(self._db_path), timeout=1.0)
                try:
                    peer_schedule = self._peer_schedule(conn)
                    if peer_schedule is None:
                        path_evidence = self._path_evidence(conn)
                finally:
                    conn.close()
            except Exception as exc:
                log.debug("MessageViewer: compose guidance worker lookup failed: %s", exc)
        recommendation = recommend_compose_send_path(
            self._radio_options,
            peer_schedule=peer_schedule,
            path_evidence=path_evidence,
            last_heard=self._last_heard,
            selected_radio_id=self._selected_radio_id,
        )
        auth_rows = []
        auth_error = ""
        if self._load_auth_keys and self._target and self._operator_callsign:
            try:
                auth_rows = load_msg_auth_keys(
                    group_name=normalize_group_name(self._target),
                    callsign=self._operator_callsign,
                    key_scope=MSG_AUTH_SCOPE_SIGNING,
                )
            except Exception as exc:
                auth_error = str(exc)
        self.finished.emit(
            {
                "generation": self._generation,
                "target": self._target,
                "recommendation": recommendation,
                "auth_rows": auth_rows,
                "auth_error": auth_error,
            }
        )


class _BbsAutoArchiveWorker(QObject):
    finished = Signal(object)

    def __init__(
        self,
        *,
        bbs_dir: str,
        archive_dir: str,
        days: int,
        allowed_exts: List[str],
        reason: str,
        archive_context: str = "live",
        archive_jobs: Optional[List[Dict[str, object]]] = None,
    ):
        super().__init__()
        self._bbs_dir = Path(str(bbs_dir or ""))
        self._archive_dir = Path(str(archive_dir or ""))
        try:
            self._days = max(1, int(days or 1))
        except Exception:
            self._days = 1
        self._allowed_exts = {
            str(ext or "").strip().lower()
            for ext in (allowed_exts or [])
            if str(ext or "").strip()
        }
        self._reason = str(reason or "").strip() or "timer"
        self._archive_context = str(archive_context or "live").strip() or "live"
        self._archive_jobs = [dict(job) for job in (archive_jobs or []) if isinstance(job, dict)]

    def _archive_destination(self, src: Path, *, source_root: Path, archive_context: str) -> Path:
        try:
            rel = src.relative_to(source_root)
        except Exception:
            rel = Path(src.name)
        dst = self._archive_dir / archive_context / rel
        dst.parent.mkdir(parents=True, exist_ok=True)
        if not dst.exists():
            return dst
        stamp = datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d_%H%M%S")
        dst = dst.parent / f"{src.stem}_{stamp}{src.suffix}"
        attempt = 2
        while dst.exists():
            dst = dst.parent / f"{src.stem}_{stamp}_{attempt}{src.suffix}"
            attempt += 1
        return dst

    def _normalized_archive_jobs(self) -> List[Dict[str, object]]:
        if self._archive_jobs:
            jobs = []
            for job in self._archive_jobs:
                root_txt = str(job.get("bbs_dir", "") or "").strip()
                if not root_txt:
                    continue
                try:
                    days = max(1, int(job.get("days", self._days) or self._days))
                except Exception:
                    days = self._days
                context = str(job.get("archive_context", self._archive_context) or self._archive_context).strip()
                jobs.append(
                    {
                        "bbs_dir": Path(root_txt),
                        "days": days,
                        "archive_context": context or self._archive_context,
                    }
                )
            return jobs
        return [
            {
                "bbs_dir": self._bbs_dir,
                "days": self._days,
                "archive_context": self._archive_context,
            }
        ]

    def run(self) -> None:
        started_ts = time.time()
        completed_ts = started_ts
        scanned_count = 0
        eligible_count = 0
        moved_count = 0
        error_count = 0
        moved_items: List[tuple[str, str]] = []
        errors: List[str] = []
        try:
            for job in self._normalized_archive_jobs():
                source_root = job["bbs_dir"]
                if not isinstance(source_root, Path) or not source_root.exists() or not source_root.is_dir():
                    continue
                days = max(1, int(job.get("days", self._days) or self._days))
                archive_context = str(job.get("archive_context", self._archive_context) or self._archive_context).strip()
                cutoff_ts = started_ts - (float(days) * 86400.0)
                for src in sorted(source_root.rglob("*"), key=lambda item: str(item).lower()):
                    try:
                        if not src.is_file():
                            continue
                        scanned_count += 1
                        suffix = src.suffix.lower()
                        if self._allowed_exts and suffix not in self._allowed_exts:
                            continue
                        st = src.stat()
                        if float(st.st_mtime) > cutoff_ts:
                            continue
                        dst = self._archive_destination(src, source_root=source_root, archive_context=archive_context)
                        eligible_count += 1
                        shutil.move(str(src), str(dst))
                        moved_count += 1
                        moved_items.append((str(src), str(dst)))
                    except Exception as e:
                        error_count += 1
                        errors.append(str(e))
                        continue
        except Exception as e:
            completed_ts = time.time()
            self.finished.emit(
                {
                    "reason": self._reason,
                    "started_ts": started_ts,
                    "completed_ts": completed_ts,
                    "days": self._days,
                    "bbs_dir": str(self._bbs_dir),
                    "archive_dir": str(self._archive_dir),
                    "scanned_count": scanned_count,
                    "eligible_count": eligible_count,
                    "moved_count": moved_count,
                    "error_count": error_count + 1,
                    "moved_items": moved_items,
                    "errors": errors + [str(e)],
                    "fatal_error": str(e),
                }
            )
            return
        completed_ts = time.time()
        self.finished.emit(
            {
                "reason": self._reason,
                "started_ts": started_ts,
                "completed_ts": completed_ts,
                "days": self._days,
                "bbs_dir": str(self._bbs_dir),
                "archive_dir": str(self._archive_dir),
                "scanned_count": scanned_count,
                "eligible_count": eligible_count,
                "moved_count": moved_count,
                "error_count": error_count,
                "moved_items": moved_items,
                "errors": errors,
                "fatal_error": "",
            }
        )


class _RowsBuildWorker(QObject):
    finished = Signal(object)

    def __init__(
        self,
        *,
        js8_messages: List[JS8Message],
        spotter_messages: List[SpotterMessage],
        varac_messages: List["VarACMessage"],
        sitrep_messages: List["SitrepMessage"],
        commstat_messages: List["CommStatArtifact"],
        files: Dict[str, List[FileRecord]],
        file_metadata_map: Dict[tuple, Dict[str, object]],
        read_state_map: Dict[tuple, tuple[str, float, int]],
        signature_state_map: Dict[tuple, Dict[str, object]],
        spotter_auth_state_map: Dict[int, Dict[str, object]],
        spotter_expect_state_map: Dict[int, Dict[str, object]],
        sender_cache_seed: Dict[tuple, str],
        form_titles: Dict[str, str],
        custom_forms_path: str,
        message_form_codes: Optional[set[str]],
        alert_form_codes: Optional[set[str]],
        show_local_time: bool,
        tz_name: str,
        sitrep_dedupe_enabled: bool,
        sitrep_show_raw_duplicates: bool,
        force: bool,
        generation: int,
        observation_messages: List[Observation] | None = None,
    ):
        super().__init__()
        self._js8_messages = list(js8_messages)
        self._spotter_messages = list(spotter_messages)
        self._varac_messages = list(varac_messages)
        self._sitrep_messages = list(sitrep_messages)
        self._commstat_messages = list(commstat_messages)
        self._observation_messages = list(observation_messages or [])
        self._files = {
            "varac": list(files.get("varac", [])),
            "flmsg": list(files.get("flmsg", [])),
            "flamp": list(files.get("flamp", [])),
            "bbs": list(files.get("bbs", [])),
        }
        self._file_metadata_map = dict(file_metadata_map or {})
        self._read_state_map = dict(read_state_map)
        self._signature_state_map = dict(signature_state_map or {})
        self._spotter_auth_state_map = dict(spotter_auth_state_map or {})
        self._spotter_expect_state_map = dict(spotter_expect_state_map or {})
        self._sender_cache_seed = dict(sender_cache_seed)
        self._sender_cache_updates: Dict[tuple, str] = {}
        self._form_titles = {str(k): str(v or "") for k, v in (form_titles or {}).items()}
        self._custom_forms_path = str(custom_forms_path or "").strip()
        self._custom_form_meta_cache: Dict[str, Tuple[str, List[Tuple[str, str]]]] = {}
        self._message_form_codes = set(message_form_codes) if message_form_codes is not None else None
        self._alert_form_codes = set(alert_form_codes) if alert_form_codes is not None else None
        self._show_local_time = bool(show_local_time)
        self._tz_name = str(tz_name or "UTC")
        self._sitrep_dedupe_enabled = bool(sitrep_dedupe_enabled)
        self._sitrep_show_raw_duplicates = bool(sitrep_show_raw_duplicates)
        self._force = bool(force)
        self._generation = int(generation)

    def _form_visible_in_messages(self, msg_type: object) -> bool:
        text = str(msg_type or "").strip()
        if not text.upper().startswith("F!"):
            return True
        return form_id_enabled(text, self._message_form_codes)

    def _form_is_alert(self, msg_type: object) -> bool:
        text = str(msg_type or "").strip()
        if not text.upper().startswith("F!"):
            return False
        return form_id_enabled(text, self._alert_form_codes)

    def _format_rcv_display(self, rcv_ts: float, utc_str: Optional[str]) -> str:
        if self._show_local_time:
            try:
                if rcv_ts:
                    dt = datetime.datetime.fromtimestamp(float(rcv_ts), tz=datetime.timezone.utc)
                elif utc_str:
                    dt = datetime.datetime.strptime(str(utc_str), "%Y-%m-%d %H:%M:%S").replace(
                        tzinfo=datetime.timezone.utc
                    )
                else:
                    return ""
                tz = get_timezone(self._tz_name)
                return dt.astimezone(tz).strftime("%Y-%m-%d %H:%M:%S")
            except Exception:
                return str(utc_str or "")
        if utc_str:
            return str(utc_str)
        if rcv_ts:
            try:
                return datetime.datetime.fromtimestamp(float(rcv_ts), tz=datetime.timezone.utc).strftime(
                    "%Y-%m-%d %H:%M:%S"
                )
            except Exception:
                return ""
        return ""

    @staticmethod
    def _trim_title(value: object, *, limit: int = 60) -> str:
        text = str(value or "").strip()
        if len(text) > limit:
            return text[: max(0, limit - 3)].rstrip() + "..."
        return text

    @staticmethod
    def _display_target(target: object, report_group: object = "") -> str:
        group = str(report_group or "").strip()
        if group:
            return group.lstrip("@")
        return str(target or "").strip().lstrip("@")

    @staticmethod
    def _canonicalize_value(value: object) -> str:
        txt = str(value or "").strip().lower()
        if not txt:
            return "not_reported"
        if txt in {"red", "yellow", "green", "unknown", "not_reported"}:
            return txt
        if txt in {"3", "r"}:
            return "red"
        if txt in {"2", "y"}:
            return "yellow"
        if txt in {"1", "g"}:
            return "green"
        if txt in {"4", "u", "5"}:
            return "unknown"
        return "unknown"

    @staticmethod
    def _canonical_scope(value: object) -> str:
        txt = str(value or "").strip()
        if not txt:
            return ""
        low = txt.lower()
        if low in {"1", "my location"}:
            return "My Location"
        if low in {"2", "my community"}:
            return "My Community"
        if low in {"3", "my county"}:
            return "My County"
        if low in {"4", "my region"}:
            return "My Region"
        if low in {"5", "other", "other location"}:
            return "Other Location"
        return txt

    @staticmethod
    def _aggregate_status(values: List[str]) -> str:
        order = {"red": 5, "yellow": 4, "green": 3, "unknown": 2, "not_reported": 1}
        best = "not_reported"
        score = order[best]
        for val in values:
            key = _RowsBuildWorker._canonicalize_value(val)
            cur = order.get(key, 2)
            if cur > score:
                best = key
                score = cur
        return best

    @staticmethod
    def _spotter_subtype(msg_type: str) -> str:
        form = str(msg_type or "").strip().upper()
        if form == "F!104":
            return "SPOTTER_104"
        if form == "F!301":
            return "SPOTTER_301"
        if form == "F!304":
            return "SPOTTER_304"
        if form == "F!701B":
            return "SPOTTER_701B"
        if form == "F!701C":
            return "SPOTTER_701C"
        return ""

    @staticmethod
    def _parse_form_responses(raw_text: str) -> str:
        text = str(raw_text or "").strip()
        if not text:
            return ""
        parts = text.split()
        if len(parts) < 2:
            return ""
        if not str(parts[0]).upper().startswith("F!"):
            return ""
        return str(parts[1] or "").strip()

    @staticmethod
    def _spotter_304_fields(digits: str) -> Dict[str, str]:
        out = {
            "overall_status": "not_reported",
            "power": "not_reported",
            "water": "not_reported",
            "medical": "not_reported",
            "communications": "not_reported",
            "internet": "not_reported",
            "travel": "not_reported",
            "food": "not_reported",
            "fuel": "not_reported",
            "crime": "not_reported",
            "civil_unrest": "not_reported",
            "political": "not_reported",
        }
        d = [ch for ch in str(digits or "").strip() if ch.isdigit()]
        if len(d) < 6:
            return out
        out["communications"] = _RowsBuildWorker._canonicalize_value(d[1] if len(d) > 1 else "")
        out["internet"] = _RowsBuildWorker._canonicalize_value(d[3] if len(d) > 3 else "")
        out["water"] = _RowsBuildWorker._canonicalize_value(d[4] if len(d) > 4 else "")
        out["power"] = _RowsBuildWorker._canonicalize_value(d[5] if len(d) > 5 else "")
        out["overall_status"] = _RowsBuildWorker._aggregate_status(
            [out["communications"], out["internet"], out["water"], out["power"]]
        )
        return out

    @staticmethod
    def _status_signature(fields: Dict[str, str]) -> str:
        dims = (
            "overall_status",
            "power",
            "water",
            "medical",
            "communications",
            "internet",
            "travel",
            "food",
            "fuel",
            "crime",
            "civil_unrest",
            "political",
        )
        return "|".join(_RowsBuildWorker._canonicalize_value(fields.get(k, "not_reported")) for k in dims)

    @staticmethod
    def _semantic_report_key(
        *,
        subtype: str,
        from_call: str,
        target: str,
        grid: str,
        scope: str,
        event_ts: float,
        fields: Dict[str, str],
        bucket_seconds: int = 60,
    ) -> str:
        call = str(from_call or "").strip().upper()
        if not call:
            return ""
        bucket = int(bucket_seconds or 60)
        if bucket <= 0:
            bucket = 60
        ts_bucket = int(float(event_ts or 0.0) // float(bucket)) if float(event_ts or 0.0) > 0 else 0
        base = "|".join(
            [
                call,
                str(target or "").strip().upper(),
                str(grid or "").strip().upper(),
                str(scope or "").strip(),
                str(subtype or "").strip().upper(),
                str(ts_bucket),
                _RowsBuildWorker._status_signature(fields),
            ]
        )
        return hashlib.sha1(base.encode("utf-8")).hexdigest()

    @staticmethod
    def _spotter_message_report_key(msg: SpotterMessage) -> str:
        subtype = _RowsBuildWorker._spotter_subtype(msg.msg_type)
        if not subtype:
            return ""
        responses = _RowsBuildWorker._parse_form_responses(msg.raw_text)
        fields = {
            "overall_status": "not_reported",
            "power": "not_reported",
            "water": "not_reported",
            "medical": "not_reported",
            "communications": "not_reported",
            "internet": "not_reported",
            "travel": "not_reported",
            "food": "not_reported",
            "fuel": "not_reported",
            "crime": "not_reported",
            "civil_unrest": "not_reported",
            "political": "not_reported",
        }
        scope = ""
        if subtype == "SPOTTER_104":
            first = str(responses or "")[:1]
            fields["overall_status"] = _RowsBuildWorker._canonicalize_value(first)
        elif subtype == "SPOTTER_301":
            digits = [ch for ch in str(responses or "").strip() if ch.isdigit()]
            if digits:
                scope = _RowsBuildWorker._canonical_scope(digits[0])
                mapped = _RowsBuildWorker._spotter_304_fields("".join(digits[1:9]))
                fields.update(mapped)
        elif subtype == "SPOTTER_304":
            mapped = _RowsBuildWorker._spotter_304_fields(responses)
            fields.update(mapped)
        elif subtype in {"SPOTTER_701B", "SPOTTER_701C"}:
            form_id = subtype.removeprefix("SPOTTER_")
            status_key, _label, _evidence = classify_spotter_status(form_id, responses)
            fields["overall_status"] = status_key
        return _RowsBuildWorker._semantic_report_key(
            subtype=subtype,
            from_call=(msg.from_call or "").strip().upper(),
            target=(msg.to_call or "").strip().upper(),
            grid="",
            scope=scope,
            event_ts=float(msg.utc_ts or 0.0),
            fields=fields,
        )

    @staticmethod
    def _sitrep_message_report_key(msg: "SitrepMessage") -> str:
        key = str(msg.report_key or "").strip().lower()
        if key:
            return key
        return _RowsBuildWorker._sitrep_message_semantic_key(msg, bucket_seconds=60)

    @staticmethod
    def _sitrep_message_semantic_key(msg: "SitrepMessage", *, bucket_seconds: int = 60) -> str:
        fields = {
            "overall_status": _RowsBuildWorker._canonicalize_value(msg.overall_status),
            "power": _RowsBuildWorker._canonicalize_value(msg.power),
            "water": _RowsBuildWorker._canonicalize_value(msg.water),
            "medical": _RowsBuildWorker._canonicalize_value(msg.medical),
            "communications": _RowsBuildWorker._canonicalize_value(msg.communications),
            "internet": _RowsBuildWorker._canonicalize_value(msg.internet),
            "travel": _RowsBuildWorker._canonicalize_value(msg.travel),
            "food": _RowsBuildWorker._canonicalize_value(msg.food),
            "fuel": _RowsBuildWorker._canonicalize_value(msg.fuel),
            "crime": _RowsBuildWorker._canonicalize_value(msg.crime),
            "civil_unrest": _RowsBuildWorker._canonicalize_value(msg.civil_unrest),
            "political": _RowsBuildWorker._canonicalize_value(msg.political),
        }
        return _RowsBuildWorker._semantic_report_key(
            subtype=str(msg.subtype or "").strip().upper(),
            from_call=(msg.from_call or "").strip().upper(),
            target=(msg.target or "").strip().upper(),
            grid=(msg.grid or "").strip().upper(),
            scope=_RowsBuildWorker._canonical_scope(msg.scope),
            event_ts=float(msg.event_ts or 0.0),
            fields=fields,
            bucket_seconds=int(bucket_seconds or 60),
        )

    @staticmethod
    def _read_file_head(path: Path, limit: int = 4096) -> str:
        return _read_text_head(path, limit)

    def _template_labels_for_custom_form(self, form_name: str) -> List[Tuple[str, str]]:
        return list(self._template_meta_for_custom_form(form_name)[1])

    def _template_title_for_custom_form(self, form_name: str) -> str:
        return self._template_meta_for_custom_form(form_name)[0]

    def _template_meta_for_custom_form(self, form_name: str) -> Tuple[str, List[Tuple[str, str]]]:
        form_name = str(form_name or "").strip()
        if not form_name or not self._custom_forms_path:
            return "", []
        cache_key = str(Path(form_name).name).lower()
        cached = self._custom_form_meta_cache.get(cache_key)
        if cached is not None:
            return cached
        path = Path(self._custom_forms_path) / Path(form_name).name
        if not path.exists():
            self._custom_form_meta_cache[cache_key] = ("", [])
            return "", []
        try:
            template = path.read_text(encoding="utf-8", errors="replace")
            meta = (
                _extract_template_title_text(template),
                [(field.key, field.label) for field in parse_compose_template_fields(template)],
            )
        except Exception:
            meta = ("", [])
        self._custom_form_meta_cache[cache_key] = meta
        return meta

    def _extract_form_file_metadata(self, rec: FileRecord) -> Dict[str, str]:
        text = _read_text_head(rec.path, 131072)
        return _extract_form_metadata_from_text(
            text,
            rec.path,
            template_title_for_form=self._template_title_for_custom_form,
            template_labels_for_form=self._template_labels_for_custom_form,
        )

    def _extract_sender_from_file(self, rec: FileRecord) -> str:
        cache_key = (str(rec.path), float(rec.mtime or 0.0), int(rec.size or 0))
        if cache_key in self._sender_cache_updates:
            return self._sender_cache_updates.get(cache_key, "")
        if cache_key in self._sender_cache_seed:
            return self._sender_cache_seed.get(cache_key, "")
        text = self._read_file_head(rec.path)
        sender = _extract_sender_from_form_text(text, rec.path) if text else ""
        self._sender_cache_updates[cache_key] = sender
        return sender

    def _file_status(self, rec: FileRecord) -> str:
        key = (rec.origin, str(rec.path), float(rec.mtime), int(rec.size))
        state = self._read_state_map.get(key)
        if state and state[0]:
            return str(state[0]).upper()
        return "NEW"

    @staticmethod
    def _signature_key(rec: FileRecord) -> tuple:
        return (str(rec.origin or "").strip().lower(), str(rec.path), float(rec.mtime or 0.0), int(rec.size or 0))

    @staticmethod
    def _file_metadata_key(rec: FileRecord) -> tuple:
        return file_metadata_key(rec)

    @staticmethod
    def _is_auth_verifiable_file(rec: FileRecord) -> bool:
        return (
            str(rec.origin or "").strip().lower() in AUTH_VERIFIABLE_ORIGINS
            and str(rec.path.suffix or "").strip().lower() in FLAMP_AUTH_EXTS
        )

    @staticmethod
    def _is_flamp_auth_file(rec: FileRecord) -> bool:
        return _RowsBuildWorker._is_auth_verifiable_file(rec)

    def _signature_row_state(self, rec: FileRecord) -> tuple[str, str, bool]:
        if not self._is_auth_verifiable_file(rec):
            return "", "", False
        key = self._signature_key(rec)
        state = self._signature_state_map.get(key, {}) if isinstance(self._signature_state_map, dict) else {}
        if not isinstance(state, dict):
            return "", "", False
        status = str(state.get("status", "") or "").strip()
        detail = str(state.get("detail", "") or "").strip()
        trusted = bool(state.get("trusted", False))
        return status, detail, trusted

    def _spotter_auth_row_state(self, msg: SpotterMessage) -> tuple[str, str, bool]:
        try:
            msg_id = int(getattr(msg, "spotter_id", 0) or 0)
        except Exception:
            msg_id = 0
        if msg_id <= 0:
            return "", "", False
        state = self._spotter_auth_state_map.get(msg_id, {})
        if not isinstance(state, dict):
            return "", "", False
        status = str(state.get("status", "") or "").strip()
        detail = str(state.get("detail", "") or "").strip()
        trusted = bool(state.get("trusted", False))
        return status, detail, trusted

    def _spotter_expect_row_state(self, msg: SpotterMessage) -> tuple[str, str]:
        try:
            msg_id = int(getattr(msg, "spotter_id", 0) or 0)
        except Exception:
            msg_id = 0
        if msg_id <= 0:
            return "", ""
        state = self._spotter_expect_state_map.get(msg_id, {})
        if not isinstance(state, dict):
            return "", ""
        decision = str(state.get("decision", "") or "").strip()
        detail = str(state.get("detail", "") or "").strip()
        return decision, detail

    def run(self) -> None:
        start = time.perf_counter()
        rows: List[UnifiedMessage] = []
        file_metadata_hits = 0
        file_parse_count = 0
        dedupe_raw_spotter = bool(self._sitrep_dedupe_enabled and not self._sitrep_show_raw_duplicates)
        sitrep_report_keys: set[str] = set()
        sitrep_render_keys: set[str] = set()
        if dedupe_raw_spotter:
            for sitrep in self._sitrep_messages:
                key = self._sitrep_message_semantic_key(sitrep, bucket_seconds=60)
                if key:
                    sitrep_report_keys.add(key)

        for msg in self._js8_messages:
            presentation = js8_message_row_presentation(
                msg,
                form_title_lookup=self._form_titles,
                alert_predicate=self._form_is_alert,
            )
            if not self._form_visible_in_messages(presentation.msg_type):
                continue
            rcv_display = self._format_rcv_display(presentation.rcv_ts, msg.utc_str)
            rows.append(
                unified_message_from_presentation(
                    presentation,
                    payload=msg,
                    rcv_display=rcv_display,
                )
            )

        for msg in self._spotter_messages:
            if dedupe_raw_spotter:
                spotter_key = self._spotter_message_report_key(msg)
                if spotter_key and spotter_key in sitrep_report_keys:
                    continue
            presentation = spotter_message_row_presentation(
                msg,
                form_title_lookup=self._form_titles,
                alert_predicate=self._form_is_alert,
            )
            if not self._form_visible_in_messages(presentation.msg_type):
                continue
            rcv_display = self._format_rcv_display(presentation.rcv_ts, msg.utc_str)
            auth_state, auth_detail, auth_trusted = self._spotter_auth_row_state(msg)
            expect_decision, expect_detail = self._spotter_expect_row_state(msg)
            rows.append(
                unified_message_from_presentation(
                    presentation,
                    payload=msg,
                    rcv_display=rcv_display,
                    auth_state=auth_state,
                    auth_detail=auth_detail,
                    auth_trusted=auth_trusted,
                    expect_decision=expect_decision,
                    expect_detail=expect_detail,
                )
            )

        for msg in self._varac_messages:
            presentation = varac_message_row_presentation(msg)
            rcv_display = self._format_rcv_display(presentation.rcv_ts, None)
            rows.append(
                unified_message_from_presentation(
                    presentation,
                    payload=msg,
                    rcv_display=rcv_display,
                )
            )

        for msg in self._sitrep_messages:
            if dedupe_raw_spotter:
                ui_key = self._sitrep_message_semantic_key(msg, bucket_seconds=1)
                if ui_key and ui_key in sitrep_render_keys:
                    continue
                if ui_key:
                    sitrep_render_keys.add(ui_key)
            rcv_ts = float(getattr(msg, "event_ts", 0.0) or 0.0)
            rcv_display = self._format_rcv_display(rcv_ts, getattr(msg, "event_ts_utc", ""))
            from_call = str(getattr(msg, "from_call", "") or "").strip().upper()
            to_call = self._display_target(getattr(msg, "target", ""), getattr(msg, "report_group", ""))
            overall = str(getattr(msg, "overall_status", "") or "").strip().upper()
            title = self._trim_title(
                " | ".join(
                    part
                    for part in (
                        getattr(msg, "subtype_label", "") or getattr(msg, "subtype", ""),
                        getattr(msg, "scope", ""),
                        overall,
                    )
                    if str(part or "").strip()
                )
                or "SitRep"
            )
            search_detail = " ".join(
                part
                for part in (
                    title,
                    getattr(msg, "subtype_label", ""),
                    getattr(msg, "source_family_label", ""),
                    getattr(msg, "transport_label", ""),
                    getattr(msg, "report_group", ""),
                    getattr(msg, "state_code", ""),
                    getattr(msg, "grid", ""),
                    getattr(msg, "remarks_text", ""),
                    getattr(msg, "brevity_code", ""),
                    getattr(msg, "brevity_summary", ""),
                )
                if str(part or "").strip()
            )
            rows.append(
                UnifiedMessage(
                    msg_type="SitRep",
                    status="INFO",
                    from_call=from_call,
                    to_call=to_call,
                    rcv_ts=rcv_ts,
                    rcv_display=rcv_display,
                    title=title,
                    origin="sitrep",
                    payload=msg,
                    search_text=message_row_search_text("SitRep", "INFO", from_call, to_call, rcv_display, search_detail),
                )
            )

        for msg in self._commstat_messages:
            rcv_ts = float(getattr(msg, "event_ts", 0.0) or 0.0)
            rcv_display = self._format_rcv_display(rcv_ts, getattr(msg, "event_ts_utc", ""))
            from_call = str(getattr(msg, "from_call", "") or "").strip().upper()
            to_call = self._display_target(getattr(msg, "target", ""), getattr(msg, "report_group", ""))
            msg_type = artifact_kind_label(getattr(msg, "artifact_kind", ""))
            status = str(getattr(msg, "status_label", "") or "INFO").strip().upper() or "INFO"
            title = self._trim_title(getattr(msg, "title", "") or msg_type)
            search_detail = " ".join(
                part
                for part in (
                    title,
                    getattr(msg, "report_group", ""),
                    getattr(msg, "transport_label", ""),
                    getattr(msg, "reach_label", ""),
                    getattr(msg, "source_family_label", ""),
                    getattr(msg, "body_text", ""),
                    getattr(msg, "remarks_text", ""),
                    getattr(msg, "alert_color", ""),
                    getattr(msg, "status_label", ""),
                    getattr(msg, "grid", ""),
                    getattr(msg, "state_code", ""),
                )
                if str(part or "").strip()
            )
            rows.append(
                UnifiedMessage(
                    msg_type=msg_type,
                    status=status,
                    from_call=from_call,
                    to_call=to_call,
                    rcv_ts=rcv_ts,
                    rcv_display=rcv_display,
                    title=title,
                    origin="commstat",
                    payload=msg,
                    search_text=message_row_search_text(msg_type, status, from_call, to_call, rcv_display, search_detail),
                )
            )

        for observation in self._observation_messages:
            presentation = observation_message_row_presentation(observation)
            rcv_display = self._format_rcv_display(
                presentation.rcv_ts,
                str(getattr(observation, "received_utc", "") or getattr(observation, "event_utc", "") or ""),
            )
            rows.append(
                unified_message_from_presentation(
                    presentation,
                    payload=observation,
                    rcv_display=rcv_display,
                )
            )

        for origin, recs in self._files.items():
            for rec in recs:
                status = self._file_status(rec)
                is_image = rec.path.suffix.lower() in IMAGE_EXTS
                cached_meta = self._file_metadata_map.get(self._file_metadata_key(rec), {}) if not is_image else {}
                candidate = file_message_row_candidate(
                    rec,
                    origin,
                    status=status,
                    is_image=is_image,
                    is_transport_form=not is_image,
                    cached_meta=cached_meta,
                    form_meta_loader=lambda rec=rec: self._extract_form_file_metadata(rec),
                    fallback_from_loader=lambda rec=rec: self._extract_sender_from_file(rec),
                )
                if candidate.used_cache:
                    file_metadata_hits += 1
                elif not is_image:
                    file_parse_count += 1
                rcv_display = self._format_rcv_display(candidate.rcv_ts, None)
                auth_state, auth_detail, auth_trusted = self._signature_row_state(rec)
                rows.append(
                    unified_file_message_from_candidate(
                        candidate,
                        origin=origin,
                        payload=rec,
                        rcv_display=rcv_display,
                        auth_state=auth_state,
                        auth_detail=auth_detail,
                        auth_trusted=auth_trusted,
                    )
                )

        rows.sort(key=lambda r: r.rcv_ts, reverse=True)
        elapsed_ms = (time.perf_counter() - start) * 1000.0
        self.finished.emit(
            {
                "rows": rows,
                "elapsed_ms": elapsed_ms,
                "sender_cache_updates": dict(self._sender_cache_updates),
                "file_metadata_hits": file_metadata_hits,
                "file_parse_count": file_parse_count,
                "generation": self._generation,
                "force": self._force,
            }
        )


class _MessageProjectionWriteWorker(QObject):
    finished = Signal(object)

    def __init__(self, *, db_path: str, rows: List[object], generation: int, force: bool = False):
        super().__init__()
        self._db_path = str(db_path or "")
        self._rows = list(rows or [])
        self._generation = int(generation)
        self._force = bool(force)

    def run(self) -> None:
        started = time.perf_counter()
        projected = 0
        error = ""
        try:
            if self._db_path and self._rows:
                projected = project_unified_message_rows(self._db_path, self._rows, force=self._force)
        except Exception as exc:
            error = str(exc)
        elapsed_ms = (time.perf_counter() - started) * 1000.0
        self.finished.emit(
            {
                "generation": self._generation,
                "rows": len(self._rows),
                "projected": projected,
                "elapsed_ms": elapsed_ms,
                "error": error,
                "force": self._force,
            }
        )


class _NativeFileProjectionWorker(QObject):
    finished = Signal(object)

    def __init__(
        self,
        *,
        db_path: str,
        records: Dict[str, List[FileRecord]],
        generation: int,
        force: bool = False,
    ):
        super().__init__()
        self._db_path = str(db_path or "")
        self._records = {str(k or ""): list(v or []) for k, v in (records or {}).items()}
        self._generation = int(generation)
        self._force = bool(force)

    def run(self) -> None:
        started = time.perf_counter()
        projected = 0
        error = ""
        try:
            if self._db_path:
                projected = project_native_file_records(self._db_path, self._records, force=self._force)
        except Exception as exc:
            error = str(exc)
        elapsed_ms = (time.perf_counter() - started) * 1000.0
        self.finished.emit(
            {
                "generation": self._generation,
                "projected": projected,
                "elapsed_ms": elapsed_ms,
                "error": error,
                "force": self._force,
            }
        )


class _ProjectedMessageQueryWorker(QObject):
    """Run one bounded, read-only Inbox projection query away from the UI thread."""

    finished = Signal(object)

    def __init__(
        self,
        *,
        db_path: str,
        request_id: int,
        scope_key: tuple[object, ...],
        query: Mapping[str, object],
        traffic_context_inputs: tuple[object, ...] | None = None,
        filter_settings: Mapping[str, object] | None = None,
        selected_groups: tuple[str, ...] | None = None,
    ):
        super().__init__()
        self._db_path = str(db_path or "")
        self._request_id = int(request_id or 0)
        self._scope_key = tuple(scope_key or ())
        self._query = dict(query or {})
        self._traffic_context_inputs = traffic_context_inputs
        self._filter_settings = dict(filter_settings) if filter_settings is not None else None
        self._selected_groups = selected_groups

    def run(self) -> None:
        started = time.perf_counter()
        error = ""
        rows: list[dict[str, object]] = []
        refs: dict[str, list[dict[str, object]]] = {}
        total_count = 0
        generation = 0
        focus_counts: dict[str, int] = {}
        focus_counts_generation = 0
        bbs_published_counts: dict[str, int] = {}
        traffic_context = None
        traffic_summary = None
        commstat_groups = None
        group_families = None
        try:
            if self._filter_settings is not None:
                commstat_groups = load_commstat_group_state(self._filter_settings)
                group_families = load_operator_group_families(Path(self._db_path))
                if self._query.get("group_names"):
                    selected = self._selected_groups if self._selected_groups is not None else self._query["group_names"]
                    groups = tuple(sorted(expand_group_selection(set(selected), group_families)))
                    self._query["group_names"] = groups
                    if len(self._scope_key) >= 6:
                        self._scope_key = (*self._scope_key[:5], groups, *self._scope_key[6:])
            if self._traffic_context_inputs is not None:
                callsign, hf_groups, local_groups = self._traffic_context_inputs
                traffic_context = load_operator_traffic_context(
                    Path(self._db_path), callsign=str(callsign),
                    configured_operating_groups=hf_groups,
                    configured_local_groups=local_groups,
                )
            page = query_projected_message_page(
                self._db_path,
                page_size=200,
                include_total=True,
                **self._query,
            )
            rows = [dict(row) for row in page.rows]
            if "message_ids" in self._query:
                traffic_summary = build_traffic_action_summary(rows, traffic_context or OperatorTrafficContext())
            total_count = int(page.total_count or 0)
            generation = int(getattr(page, "generation", 0) or 0)
            message_ids = [str(row.get("message_id") or "") for row in rows]
            loaded_refs = load_projected_external_refs_for_messages(self._db_path, message_ids)
            refs = {
                message_id: [dict(ref) for ref in message_refs]
                for message_id, message_refs in loaded_refs.items()
            }
            external_paths = sorted(
                {
                    str(ref.get("external_path") or "").strip()
                    for message_refs in refs.values()
                    for ref in message_refs
                    if str(ref.get("external_path") or "").strip()
                }
            )
            if external_paths:
                try:
                    conn = connect_sqlite_readonly(self._db_path, timeout=1.0)
                    try:
                        has_artifacts = conn.execute(
                            "SELECT 1 FROM sqlite_master WHERE type='table' AND name='bbs_artifacts'"
                        ).fetchone()
                        has_memberships = conn.execute(
                            "SELECT 1 FROM sqlite_master WHERE type='table' AND name='bbs_location_artifacts'"
                        ).fetchone()
                        if has_artifacts and has_memberships:
                            for start in range(0, len(external_paths), 200):
                                chunk = external_paths[start : start + 200]
                                placeholders = ",".join("?" for _ in chunk)
                                published_rows = conn.execute(
                                    f"""
                                    SELECT a.source_path, COUNT(*)
                                      FROM bbs_artifacts a
                                      JOIN bbs_location_artifacts la ON la.artifact_id=a.artifact_id
                                     WHERE la.publish_enabled=1
                                       AND a.source_path IN ({placeholders})
                                     GROUP BY a.source_path
                                    """,
                                    tuple(chunk),
                                ).fetchall()
                                for source_path, count in published_rows:
                                    key = os.path.normcase(
                                        os.path.normpath(os.path.abspath(str(source_path or "")))
                                    )
                                    if key:
                                        bbs_published_counts[key] = max(0, int(count or 0))
                    finally:
                        conn.close()
                except Exception:
                    # Managed BBS is optional.  Its readiness snapshot must
                    # never make the primary Inbox projection fail.
                    bbs_published_counts = {}
            count_query = {
                key: self._query[key]
                for key in (
                    "group_name",
                    "group_names",
                    "received_after_ts",
                    "received_before_ts",
                )
                if key in self._query
            }
            if "message_ids" not in self._query:
                focus_snapshot = query_projected_inbox_focus_counts(
                    self._db_path,
                    **count_query,
                )
                focus_counts = {
                    str(key): max(0, int(value or 0))
                    for key, value in focus_snapshot.counts.items()
                }
                focus_counts_generation = int(focus_snapshot.generation or 0)
            else:
                focus_counts = None
        except Exception as exc:
            error = str(exc)
        self.finished.emit(
            {
                "request_id": self._request_id,
                "scope_key": self._scope_key,
                "rows": rows,
                "refs": refs,
                "total_count": total_count,
                "generation": generation,
                "focus_counts": focus_counts,
                "focus_counts_generation": focus_counts_generation,
                "bbs_published_counts": bbs_published_counts,
                "traffic_summary": traffic_summary,
                "traffic_context": traffic_context,
                "traffic_context_inputs": self._traffic_context_inputs,
                "filter_settings": self._filter_settings,
                "commstat_groups": commstat_groups,
                "group_families": group_families,
                "elapsed_ms": (time.perf_counter() - started) * 1000.0,
                "error": error,
            }
        )


@dataclass
class FileSignatureState:
    status: str = "unsigned"
    detail: str = ""
    signer_fingerprint: str = ""
    signer_uid: str = ""
    trusted: bool = False
    signature_path: str = ""
    signature_mtime: float = 0.0
    signature_size: int = 0
    hash_status: str = "unsigned"
    hash_detail: str = ""
    hash_algorithm: str = ""
    hash_expected: str = ""
    hash_actual: str = ""
    hash_path: str = ""
    hash_mtime: float = 0.0
    hash_size: int = 0
    local_hash_status: str = "unsigned"
    local_hash_detail: str = ""
    local_hash_algorithm: str = ""
    local_hash_expected: str = ""
    local_hash_actual: str = ""
    local_hash_label: str = ""
    local_hash_set_sig: str = ""
    verified_ts: float = 0.0


class _SignatureVerifyWorker(QObject):
    finished = Signal(object)

    def __init__(
        self,
        records: List[FileRecord],
        *,
        verify_signature: bool,
        verify_hash: bool,
        inline_sig_name_suffixes: List[str],
        trusted_hash_entries: List[dict],
        trusted_hash_sig: str,
        gpg_path: str,
        trusted_signers: set[str],
        generation: int,
    ):
        super().__init__()
        self._records = list(records)
        self._verify_signature = bool(verify_signature)
        self._verify_hash = bool(verify_hash)
        self._inline_sig_name_suffixes = [str(v or "").strip().lower() for v in (inline_sig_name_suffixes or []) if str(v or "").strip()]
        self._trusted_hash_entries = list(trusted_hash_entries or [])
        self._trusted_hash_sig = str(trusted_hash_sig or "")
        self._gpg_path = str(gpg_path or "").strip()
        self._trusted_signers = set(trusted_signers)
        self._generation = int(generation)

    @staticmethod
    def _cache_key(rec: FileRecord) -> tuple:
        return (str(rec.origin or "").strip().lower(), str(rec.path), float(rec.mtime or 0.0), int(rec.size or 0))

    def run(self) -> None:
        start = time.perf_counter()
        out: Dict[tuple, dict] = {}
        for rec in self._records:
            key = self._cache_key(rec)
            if self._verify_signature:
                sig_result = verify_file_with_discovery(
                    rec.path,
                    configured_path=self._gpg_path,
                    trusted_fingerprints=self._trusted_signers,
                    allow_inline_clearsigned=True,
                    inline_name_suffixes=self._inline_sig_name_suffixes,
                )
            else:
                sig_result = None
            if self._verify_hash:
                hash_result = verify_file_hash_with_discovery(rec.path)
                local_hash_result = verify_file_hash_against_registry(rec.path, self._trusted_hash_entries)
            else:
                hash_result = None
                local_hash_result = None

            sig_path = Path(sig_result.signature_path) if sig_result and sig_result.signature_path else None
            if sig_path is None:
                sig_path = rec.path if is_detached_signature_file(rec.path) else find_detached_signature(rec.path)
            sig_mtime = 0.0
            sig_size = 0
            sig_path_str = ""
            if sig_path is not None:
                sig_path_str = str(sig_path)
                try:
                    st = sig_path.stat()
                    sig_mtime = float(st.st_mtime)
                    sig_size = int(st.st_size)
                except Exception:
                    sig_mtime = 0.0
                    sig_size = 0
            hash_path_obj = Path(hash_result.checksum_path) if hash_result and hash_result.checksum_path else None
            hash_mtime = 0.0
            hash_size = 0
            hash_path_str = ""
            if hash_path_obj is not None:
                hash_path_str = str(hash_path_obj)
                try:
                    st = hash_path_obj.stat()
                    hash_mtime = float(st.st_mtime)
                    hash_size = int(st.st_size)
                except Exception:
                    hash_mtime = 0.0
                    hash_size = 0
            out[key] = {
                "status": str(sig_result.status or "unsigned") if sig_result else "unsigned",
                "detail": str(sig_result.detail or "") if sig_result else "Signature verification disabled.",
                "signer_fingerprint": str(sig_result.signer_fingerprint or "") if sig_result else "",
                "signer_uid": str(sig_result.signer_uid or "") if sig_result else "",
                "trusted": bool(sig_result.trusted) if sig_result else False,
                "signature_path": sig_path_str,
                "signature_mtime": float(sig_mtime),
                "signature_size": int(sig_size),
                "hash_status": str(hash_result.status or "unsigned") if hash_result else "unsigned",
                "hash_detail": str(hash_result.detail or "") if hash_result else "Checksum verification disabled.",
                "hash_algorithm": str(hash_result.algorithm or "") if hash_result else "",
                "hash_expected": str(hash_result.expected_hash or "") if hash_result else "",
                "hash_actual": str(hash_result.actual_hash or "") if hash_result else "",
                "hash_path": hash_path_str,
                "hash_mtime": float(hash_mtime),
                "hash_size": int(hash_size),
                "local_hash_status": str(local_hash_result.status or "unsigned") if local_hash_result else "unsigned",
                "local_hash_detail": str(local_hash_result.detail or "") if local_hash_result else "Local hash verification disabled.",
                "local_hash_algorithm": str(local_hash_result.algorithm or "") if local_hash_result else "",
                "local_hash_expected": str(local_hash_result.expected_hash or "") if local_hash_result else "",
                "local_hash_actual": str(local_hash_result.actual_hash or "") if local_hash_result else "",
                "local_hash_label": str(local_hash_result.entry_label or "") if local_hash_result else "",
                "local_hash_set_sig": str(self._trusted_hash_sig or ""),
                "verified_ts": float(time.time()),
            }
        elapsed_ms = (time.perf_counter() - start) * 1000.0
        self.finished.emit(
            {
                "generation": self._generation,
                "elapsed_ms": elapsed_ms,
                "results": out,
            }
        )


