class MessageTableModel(QAbstractTableModel):
    def __init__(self, rows: List[UnifiedMessage]):
        super().__init__()
        self._rows = list(rows[:200])
        self._projection_generation = 0
        self._selected_keys: set[tuple] = set()
        self._row_index_by_key: Dict[tuple, int] = {}
        self._select_column_index = 0
        self._display_profile = "triage"
        self._headers = ["", "Source", "Status", "From", "To", "Age", "Kind / Message", "Actions"]
        self._semantic_cache = self._build_semantic_cache(self._rows)

    @staticmethod
    def _build_semantic_cache(rows: Sequence[UnifiedMessage]) -> Dict[int, Tuple[str, str]]:
        """Prepare Source and Kind/Message labels once per bounded snapshot."""

        return {
            id(row): (message_row_source_label(row), message_row_narrative_label(row))
            for row in rows[:200]
        }

    def _semantic_labels_for_row(self, row: UnifiedMessage) -> Tuple[str, str]:
        labels = self._semantic_cache.get(id(row))
        if labels is None:
            labels = (message_row_source_label(row), message_row_narrative_label(row))
            self._semantic_cache[id(row)] = labels
        return labels

    def rowCount(self, parent: QModelIndex = QModelIndex()) -> int:
        if parent.isValid():
            return 0
        return len(self._rows)

    def columnCount(self, parent: QModelIndex = QModelIndex()) -> int:
        if parent.isValid():
            return 0
        return len(self._headers)

    def data(self, index: QModelIndex, role: int = Qt.DisplayRole):
        if not index.isValid():
            return None
        if index.row() < 0 or index.row() >= len(self._rows):
            return None
        if index.column() < 0 or index.column() >= len(self._headers):
            return None
        row = self._rows[index.row()]
        col = index.column()
        if role == Qt.CheckStateRole and col == 0:
            key = self._row_key(row)
            if key is None:
                return None
            return Qt.Checked if key in self._selected_keys else Qt.Unchecked
        if role == Qt.DisplayRole:
            if self._display_profile in {"field_report", "field_summary", "intel_report"}:
                if col == 1:
                    return self._field_report_form(row)
                if col == 2:
                    return self._field_report_status(row)
                if col == 3:
                    return row.from_call
                if col == 4:
                    return self._field_report_group(row)
                if col == 5:
                    if self._display_profile == "field_summary":
                        return row.title
                    return self._field_report_area(row)
                if col == 6:
                    return self._relative_age(row.rcv_ts)
            elif self._display_profile == "form_message":
                if col == 1:
                    return self._cell_text(row, "message")
                if col == 2:
                    return self._cell_text(row, "type")
                if col == 3:
                    return self._cell_text(row, "status")
                if col == 4:
                    return self._cell_text(row, "from")
                if col == 5:
                    return self._cell_text(row, "to")
                if col == 6:
                    return self._relative_age(row.rcv_ts)
            else:
                if col == 1:
                    return self._semantic_labels_for_row(row)[0]
                if col == 2:
                    return self._cell_text(row, "status")
                if col == 3:
                    return self._cell_text(row, "from")
                if col == 4:
                    return self._cell_text(row, "to")
                if col == 5:
                    return self._relative_age(row.rcv_ts)
                if col == 6:
                    return self._semantic_labels_for_row(row)[1]
            if col == 7:
                # The action delegate owns every visible label in this cell.
                # Returning fallback text lets native item painting draw a
                # second copy behind the chips on some platform styles.
                return ""
        if role == Qt.UserRole:
            return row
        if role == Qt.DecorationRole and col == 1:
            auth = str(getattr(row, "auth_state", "") or "").strip().lower()
            app = QApplication.instance()
            style = app.style() if app is not None else None
            if style is None:
                return None
            if auth == "valid":
                return style.standardIcon(QStyle.SP_DialogApplyButton)
            if auth in {"invalid", "error"}:
                return style.standardIcon(QStyle.SP_MessageBoxWarning)
            return None
        if role == Qt.ToolTipRole:
            age_column = 6 if self._display_profile in {"field_report", "field_summary", "intel_report", "form_message"} else 5
            if col == age_column:
                exact = str(getattr(row, "rcv_display", "") or "").strip()
                return f"Received: {exact}" if exact else None
        if role == Qt.ToolTipRole and col == 7:
            # The delegate provides the tooltip for the exact icon under the
            # pointer.  A cell-wide tooltip competes with that guidance and can
            # obscure neighboring actions in this dense column.
            return None
        if role == Qt.ToolTipRole and col in (1, 6):
            details = [
                str(row.title or "").strip() if col in (1, 6) else "",
                str(getattr(row, "auth_detail", "") or "").strip(),
                str(getattr(row, "expect_detail", "") or "").strip(),
            ]
            detail = "\n".join(part for part in details if part)
            if detail:
                return detail
        if role == Qt.ForegroundRole and col == 2:
            if row.status == "NEW":
                return QColor(Qt.red)
            payload = row.payload
            if isinstance(payload, ProjectedMessagePayload):
                severity = str(payload.severity or "").strip().lower()
                if severity == "critical":
                    return QColor("#d32f2f")
                if severity == "warning":
                    return QColor("#ed8b00")
                if severity == "watch":
                    return QColor(Qt.red)
            if isinstance(payload, CommStatArtifact):
                color = str(payload.alert_color or "").strip().lower()
                if color == "red":
                    return QColor("#d32f2f")
                if color == "yellow":
                    return QColor("#ed8b00")
                if color == "green":
                    return QColor("#2e7d32")
                status = str(payload.status_label or "").strip().upper()
                if status == "RED":
                    return QColor("#d32f2f")
                if status == "YELLOW":
                    return QColor("#ed8b00")
                if status == "GREEN":
                    return QColor("#2e7d32")
        return None

    def headerData(self, section: int, orientation: Qt.Orientation, role: int = Qt.DisplayRole):
        if role != Qt.DisplayRole:
            return None
        if orientation == Qt.Horizontal and 0 <= section < len(self._headers):
            return self._headers[section]
        return None

    def set_time_header(self, label: str) -> None:
        idx = 6 if self._display_profile in {"field_report", "field_summary", "intel_report"} else 5
        self._headers[idx] = "Age"
        self.headerDataChanged.emit(Qt.Horizontal, idx, idx)

    def set_display_profile(self, profile: str, time_label: str) -> None:
        profile, header_tuple = message_display_profile_headers(profile)
        headers = list(header_tuple)
        changed = profile != self._display_profile or headers != self._headers
        self._display_profile = profile
        if changed:
            self.beginResetModel()
            self._headers = headers
            self.endResetModel()

    def display_profile(self) -> str:
        return self._display_profile

    @staticmethod
    def _spotter_area(msg: SpotterMessage) -> str:
        fields = parse_spotter_bracket_fields(getattr(msg, "raw_text", ""))
        state = str(fields.get("ST", "") or "").strip().upper()
        grid = str(fields.get("GR", "") or "").strip().upper()
        county_or_country = str(fields.get("CC", "") or fields.get("CO", "") or "").strip()
        if state and grid:
            return f"{state} / {grid}"
        if state and county_or_country:
            return f"{state} / {county_or_country}"
        return grid or state or county_or_country

    @staticmethod
    def _sitrep_area(msg: SitrepMessage) -> str:
        state = str(msg.state_code or "").strip().upper()
        grid = str(msg.grid or "").strip().upper()
        scope = str(msg.scope or "").strip()
        if state and grid:
            return f"{state} / {grid}"
        if state and scope:
            return f"{state} / {scope}"
        return grid or state or scope

    @staticmethod
    def _field_report_form(row: UnifiedMessage) -> str:
        return field_report_form_label(row)

    @staticmethod
    def _field_report_status(row: UnifiedMessage) -> str:
        return field_report_status_label(row)

    @staticmethod
    def _field_report_group(row: UnifiedMessage) -> str:
        return field_report_group_label(row, MessageTableModel._display_to)

    @staticmethod
    def _display_to(row: UnifiedMessage, value: object = None) -> str:
        raw = row.to_call if value is None else value
        payload = getattr(row, "payload", None)
        return _js8_relay_route_display(
            raw,
            getattr(payload, "raw_text", ""),
            getattr(payload, "decoded_text", ""),
            getattr(payload, "body_text", ""),
            getattr(payload, "remarks_text", ""),
            row.title,
            row.search_text,
        )

    @staticmethod
    def _strip_group_marker(value: object) -> str:
        text = str(value or "").strip().upper()
        return text[1:] if text.startswith("@") else text

    @staticmethod
    def _strip_group_markers_in_display_text(value: object) -> str:
        return re.sub(r"@([A-Z0-9_-]{2,})", r"\1", str(value or ""))

    @staticmethod
    def _field_report_area(row: UnifiedMessage) -> str:
        return field_report_area_label(row)

    @staticmethod
    def _relative_age(ts: object) -> str:
        return relative_age_label(ts)

    def _cell_text(self, row: UnifiedMessage, field: str) -> str:
        if self._display_profile in {"field_report", "field_summary", "intel_report"}:
            if field == "type":
                return self._field_report_form(row)
            if field == "status":
                return self._field_report_status(row)
            if field == "from":
                return row.from_call
            if field == "to":
                return self._field_report_group(row)
            if field == "received":
                return row.rcv_display
            if field == "message":
                if self._display_profile == "field_summary":
                    return row.title
                return self._field_report_area(row)
        if field == "type":
            if self._display_profile == "form_message":
                return row.display_type or row.msg_type
            return row.msg_type
        if field == "status":
            return row.status
        if field == "from":
            return row.from_call
        if field == "to":
            return self._display_to(row)
        if field == "received":
            return row.rcv_display
        if field == "message":
            return row.title
        return ""

    def flags(self, index: QModelIndex) -> Qt.ItemFlags:
        if not index.isValid():
            return Qt.NoItemFlags
        if index.row() < 0 or index.row() >= len(self._rows):
            return Qt.NoItemFlags
        row = self._rows[index.row()]
        if index.column() == 0 and self._row_key(row) is not None:
            return Qt.ItemIsEnabled | Qt.ItemIsUserCheckable | Qt.ItemIsEditable
        return Qt.ItemIsEnabled | Qt.ItemIsSelectable

    def setData(self, index: QModelIndex, value, role: int = Qt.EditRole) -> bool:
        if not index.isValid():
            return False
        if index.row() < 0 or index.row() >= len(self._rows):
            return False
        if index.column() != 0 or role != Qt.CheckStateRole:
            return False
        row = self._rows[index.row()]
        key = self._row_key(row)
        if key is None:
            return False
        if value == Qt.Checked:
            self._selected_keys.add(key)
        else:
            self._selected_keys.discard(key)
        self.dataChanged.emit(index, index, [Qt.CheckStateRole])
        return True

    def set_rows(self, rows: List[UnifiedMessage]) -> None:
        rows = list(rows[:200])
        old_keys = [self._row_key(row) for row in self._rows]
        new_keys = [self._row_key(row) for row in rows]
        if len(rows) == len(self._rows) and all(old is new for old, new in zip(self._rows, rows)):
            return

        # The common ingest case keeps the same ordered identities and changes
        # only one or more row payloads. Preserve selection/scroll state and
        # avoid a full model reset for that path. Tail growth/removal is also
        # expressed as a bounded model diff; arbitrary sort changes may reset.
        if old_keys == new_keys:
            changed = [index for index, (old, new) in enumerate(zip(self._rows, rows)) if old != new]
            self._rows = rows
            if changed and self.columnCount() > 0:
                self.dataChanged.emit(
                    self.index(min(changed), 0),
                    self.index(max(changed), self.columnCount() - 1),
                    [],
                )
        elif len(rows) > len(self._rows) and new_keys[: len(old_keys)] == old_keys:
            first = len(self._rows)
            self.beginInsertRows(QModelIndex(), first, len(rows) - 1)
            self._rows = rows
            self.endInsertRows()
        elif len(rows) < len(self._rows) and old_keys[: len(new_keys)] == new_keys:
            first = len(rows)
            self.beginRemoveRows(QModelIndex(), first, len(self._rows) - 1)
            self._rows = rows
            self.endRemoveRows()
        else:
            self.beginResetModel()
            self._rows = rows
            self.endResetModel()

        row_index_by_key: Dict[tuple, int] = {}
        self._semantic_cache = self._build_semantic_cache(rows)
        for i, row in enumerate(rows):
            key = self._row_key(row)
            if key is not None and key not in row_index_by_key:
                row_index_by_key[key] = i
        self._row_index_by_key = row_index_by_key
        keep = {self._row_key(r) for r in rows if self._row_key(r) is not None}
        self._selected_keys = {k for k in self._selected_keys if k in keep}

    def set_rows_for_generation(self, rows: List[UnifiedMessage], generation: int) -> bool:
        """Apply one bounded committed snapshot and reject stale worker results."""

        try:
            requested = int(generation or 0)
        except Exception:
            requested = 0
        if requested and requested < self._projection_generation:
            return False
        self.set_rows(rows)
        if requested:
            self._projection_generation = requested
        return True

    def index_for_row(self, row: UnifiedMessage) -> int:
        key = self._row_key(row)
        if key is not None:
            idx = self._row_index_by_key.get(key)
            if idx is not None:
                return int(idx)
        for i, cur in enumerate(self._rows):
            if cur is row:
                return i
        return -1

    def mark_row_read(self, row: UnifiedMessage) -> bool:
        idx_row = self.index_for_row(row)
        if idx_row < 0:
            return False
        row.status = "READ"
        idx = self.index(idx_row, 2)
        self.dataChanged.emit(idx, idx, [Qt.DisplayRole, Qt.ForegroundRole])
        return True

    def rows(self) -> List[UnifiedMessage]:
        return list(self._rows)

    def selected_rows(self) -> List[UnifiedMessage]:
        out: List[UnifiedMessage] = []
        for row in self._rows:
            key = self._row_key(row)
            if key is not None and key in self._selected_keys:
                out.append(row)
        return out

    def clear_selection(self) -> None:
        if not self._selected_keys:
            return
        self._selected_keys.clear()
        if self.rowCount() > 0:
            self.dataChanged.emit(
                self.index(0, 0),
                self.index(self.rowCount() - 1, 0),
                [Qt.CheckStateRole],
            )

    def set_selected_for_rows(self, rows: List[UnifiedMessage], selected: bool) -> None:
        if not rows:
            return
        updated = False
        for row in rows:
            key = self._row_key(row)
            if key is None:
                continue
            if selected:
                if key not in self._selected_keys:
                    self._selected_keys.add(key)
                    updated = True
            else:
                if key in self._selected_keys:
                    self._selected_keys.discard(key)
                    updated = True
        if updated and self.rowCount() > 0:
            self.dataChanged.emit(
                self.index(0, self._select_column_index),
                self.index(self.rowCount() - 1, self._select_column_index),
                [Qt.CheckStateRole],
            )

    @staticmethod
    def _row_key(row: UnifiedMessage) -> tuple | None:
        return _core_message_row_identity(row)


@dataclass(frozen=True)
class MessageRowAction:
    """One cache-only direct action rendered in the Inbox action column."""

    key: str
    label: str
    tooltip: str
    icon: str
    enabled: bool = True
    active: bool = False
    role: str = "secondary"


class MessageActionDelegate(QStyledItemDelegate):
    def __init__(self, parent):
        super().__init__(parent)
        self._hovered_action: tuple[int, str] | None = None
        self._view = getattr(parent, "messages_table", None)
        if isinstance(self._view, QTableView):
            self._view.setMouseTracking(True)
            self._view.viewport().installEventFilter(self)

    @staticmethod
    def _is_live_bbs_file_row(row: UnifiedMessage | None) -> bool:
        return isinstance(getattr(row, "payload", None), FileRecord) and (
            (getattr(row, "origin", "") or "").strip().lower() == "bbs"
        )

    @staticmethod
    def _is_archived_bbs_file_row(row: UnifiedMessage | None) -> bool:
        return isinstance(getattr(row, "payload", None), FileRecord) and (
            (getattr(row, "origin", "") or "").strip().lower() == "bbs_archive"
        )

    @staticmethod
    def _supports_flag(row: UnifiedMessage | None, *, projected_file_row: bool) -> bool:
        return bool(
            projected_file_row
            or isinstance(
                getattr(row, "payload", None),
                (ProjectedMessagePayload, JS8Message, FileRecord, VarACMessage, SpotterMessage),
            )
        )

    @staticmethod
    def _file_origin(row: UnifiedMessage | None, rec: FileRecord | None) -> str:
        return str(
            getattr(rec, "origin", "")
            or getattr(row, "origin", "")
            or ""
        ).strip().lower()

    def _action_items(self, row: UnifiedMessage) -> list[MessageRowAction]:
        """Return source-aware actions without source, database, or filesystem I/O."""

        parent_widget = self.parent()
        items: list[MessageRowAction] = [
            MessageRowAction("view", "", "View message", "view")
        ]
        rec = None
        if hasattr(parent_widget, "_file_record_for_message_row"):
            rec = parent_widget._file_record_for_message_row(row, allow_detail_lookup=False)
        elif isinstance(getattr(row, "payload", None), FileRecord):
            rec = row.payload
        projected_file_row = isinstance(rec, FileRecord) and isinstance(
            getattr(row, "payload", None), ProjectedMessagePayload
        )
        origin = self._file_origin(row, rec)
        archived_bbs_row = origin == "bbs_archive" or self._is_archived_bbs_file_row(row)
        live_bbs_row = origin == "bbs" and not archived_bbs_row

        if live_bbs_row:
            items.append(MessageRowAction("archive", "", "Archive BBS message", "archive"))
        elif not archived_bbs_row and self._supports_flag(row, projected_file_row=projected_file_row):
            flag_state = int(getattr(row.payload, "flag_state", 0) or 0)
            items.append(
                MessageRowAction(
                    "flag",
                    "",
                    "Clear flag" if flag_state else "Flag for follow-up",
                    "flag",
                    active=flag_state > 0,
                )
            )

        if not live_bbs_row and not archived_bbs_row and isinstance(rec, FileRecord):
            if origin == "flamp" and str(rec.path.suffix or "").lower() in {".b2s", ".k2s"}:
                relay_present = bool(
                    hasattr(parent_widget, "_cached_row_in_flamp_relay")
                    and parent_widget._cached_row_in_flamp_relay(row)
                )
                items.append(
                    MessageRowAction(
                        "relay_remove" if relay_present else "relay",
                        "",
                        "Remove FLAMP Relay copy" if relay_present else "Add to FLAMP Relay",
                        "relay",
                        active=relay_present,
                    )
                )
            if origin in {"flmsg", "flamp", "varac"}:
                bbs_present = bool(
                    hasattr(parent_widget, "_cached_row_in_varac_bbs")
                    and parent_widget._cached_row_in_varac_bbs(row)
                )
                items.append(
                    MessageRowAction(
                        "bbs_remove" if bbs_present else "bbs",
                        "-BBS" if bbs_present else "+BBS",
                        "Remove from all Managed BBS locations"
                        if bbs_present
                        else "Add to Managed BBS",
                        "bbs",
                        active=bbs_present,
                    )
                )

        if isinstance(
            row.payload,
            (
                FileRecord,
                ProjectedMessagePayload,
                JS8Message,
                SpotterMessage,
                VarACMessage,
                SitrepMessage,
                CommStatArtifact,
            ),
        ):
            items.append(
                MessageRowAction(
                    "delete",
                    "",
                    "Delete message",
                    "trash",
                    role="danger",
                )
            )
        return items

    @classmethod
    def required_width(cls, font_metrics) -> int:
        """Font-derived width for the widest valid direct-action row."""

        padding, gap, margin, _height, _radius = action_chip_metrics(font_metrics)
        labels = ("", "", "", "+BBS", "")
        return int(
            (2 * margin)
            + sum(
                max(_height, font_metrics.horizontalAdvance(label) + padding)
                for label in labels
            )
            + (len(labels) - 1) * gap
        )

    def _chip_rects(
        self,
        option: QStyleOptionViewItem,
        items: Sequence[MessageRowAction],
    ) -> list[tuple[MessageRowAction, QRect]]:
        font_metrics = option.fontMetrics
        padding, gap, margin, natural_height, _radius = action_chip_metrics(font_metrics)
        height = min(natural_height, max(1, option.rect.height() - (2 * margin)))
        top = option.rect.top() + max(0, (option.rect.height() - height) // 2)
        left = option.rect.left() + margin
        result: list[tuple[MessageRowAction, QRect]] = []
        for item in items:
            width = max(height, font_metrics.horizontalAdvance(item.label) + padding)
            rect = QRect(left, top, width, height)
            result.append((item, rect))
            left = rect.right() + 1 + gap
        return result

    def paint(self, painter: QPainter, option: QStyleOptionViewItem, index: QModelIndex) -> None:
        if index.column() != 7:
            super().paint(painter, option, index)
            return
        background = QStyleOptionViewItem(option)
        self.initStyleOption(background, index)
        background.text = ""
        style = option.widget.style() if option.widget is not None else QApplication.style()
        style.drawControl(QStyle.CE_ItemViewItem, background, painter, option.widget)
        row = index.data(Qt.UserRole)
        if row is None:
            return
        theme = active_app_theme()
        _padding, _gap, _margin, _height, radius = action_chip_metrics(option.fontMetrics)
        chip_font = QFont(option.font)
        chip_font.setWeight(QFont.Weight.DemiBold)
        painter.save()
        painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        painter.setFont(chip_font)
        for action, rect in self._chip_rects(option, self._action_items(row)):
            hovered = self._hovered_action == (id(row), action.key)
            background_color, text_color, border_color = action_chip_colors(
                action.role,
                theme,
                enabled=action.enabled,
                active=action.active,
                hovered=hovered,
            )
            painter.setPen(QColor(border_color))
            painter.setBrush(QColor(background_color))
            painter.drawRoundedRect(rect, radius, radius)
            painter.setPen(QColor(text_color))
            if action.label:
                painter.drawText(rect, int(Qt.AlignCenter | Qt.TextSingleLine), action.label)
            else:
                self._paint_action_icon(painter, action, rect, QColor(text_color))
        painter.restore()

    @staticmethod
    def _paint_action_icon(
        painter: QPainter,
        action: MessageRowAction,
        rect: QRect,
        color: QColor,
    ) -> None:
        """Paint compact theme-colored icons without platform button chrome."""

        side = max(10, min(rect.width(), rect.height()) - max(8, rect.height() // 3))
        icon = QRect(
            rect.center().x() - side // 2,
            rect.center().y() - side // 2,
            side,
            side,
        )
        stroke = max(1, side // 8)
        pen = QPen(color, stroke)
        pen.setCapStyle(Qt.RoundCap)
        pen.setJoinStyle(Qt.RoundJoin)
        painter.setPen(pen)
        painter.setBrush(Qt.NoBrush)
        name = action.icon
        if name == "view":
            points = QPolygon(
                [
                    QPoint(icon.left(), icon.center().y()),
                    QPoint(icon.center().x(), icon.top() + 1),
                    QPoint(icon.right(), icon.center().y()),
                    QPoint(icon.center().x(), icon.bottom() - 1),
                ]
            )
            painter.drawPolygon(points)
            pupil = max(2, side // 5)
            painter.setBrush(color)
            painter.drawEllipse(icon.center(), pupil, pupil)
        elif name == "flag":
            pole_x = icon.left() + max(1, side // 5)
            painter.drawLine(pole_x, icon.top(), pole_x, icon.bottom())
            flag = QPolygon(
                [
                    QPoint(pole_x, icon.top() + 1),
                    QPoint(icon.right(), icon.top() + side // 4),
                    QPoint(pole_x, icon.center().y()),
                ]
            )
            if action.active:
                painter.setBrush(color)
            painter.drawPolygon(flag)
        elif name == "archive":
            body = icon.adjusted(1, side // 4, -1, -1)
            painter.drawRect(body)
            painter.drawLine(icon.left(), icon.top() + side // 4, icon.right(), icon.top() + side // 4)
            painter.drawLine(icon.center().x() - side // 6, body.top() + side // 4, icon.center().x() + side // 6, body.top() + side // 4)
        elif name == "relay":
            y1 = icon.top() + side // 3
            y2 = icon.bottom() - side // 3
            painter.drawLine(icon.left() + 1, y1, icon.right() - 2, y1)
            painter.drawLine(icon.right() - 2, y1, icon.right() - side // 4, y1 - side // 5)
            painter.drawLine(icon.right() - 2, y1, icon.right() - side // 4, y1 + side // 5)
            painter.drawLine(icon.right() - 1, y2, icon.left() + 2, y2)
            painter.drawLine(icon.left() + 2, y2, icon.left() + side // 4, y2 - side // 5)
            painter.drawLine(icon.left() + 2, y2, icon.left() + side // 4, y2 + side // 5)
            sign_x = icon.right() - side // 6
            sign_y = icon.bottom() - side // 6
            painter.drawLine(sign_x - side // 7, sign_y, sign_x + side // 7, sign_y)
            if not action.active:
                painter.drawLine(sign_x, sign_y - side // 7, sign_x, sign_y + side // 7)
        elif name == "trash":
            body = icon.adjusted(side // 4, side // 3, -side // 4, -1)
            painter.drawRoundedRect(body, max(1, stroke), max(1, stroke))
            painter.drawLine(icon.left() + side // 5, icon.top() + side // 4, icon.right() - side // 5, icon.top() + side // 4)
            painter.drawLine(icon.center().x() - side // 7, icon.top() + side // 8, icon.center().x() + side // 7, icon.top() + side // 8)
            painter.drawLine(body.left() + side // 7, body.top() + side // 6, body.left() + side // 7, body.bottom() - side // 8)
            painter.drawLine(body.right() - side // 7, body.top() + side // 6, body.right() - side // 7, body.bottom() - side // 8)

    def eventFilter(self, watched, event):
        view = self._view
        if not isinstance(view, QTableView) or watched is not view.viewport():
            return super().eventFilter(watched, event)
        hovered: tuple[int, str] | None = None
        if event.type() == QEvent.MouseMove:
            position = event.position().toPoint() if hasattr(event, "position") else event.pos()
            index = view.indexAt(position)
            if index.isValid() and index.column() == 7:
                row = index.data(Qt.UserRole)
                if row is not None:
                    option = QStyleOptionViewItem()
                    option.initFrom(view.viewport())
                    option.rect = view.visualRect(index)
                    option.font = view.font()
                    option.fontMetrics = view.fontMetrics()
                    for action, rect in self._chip_rects(
                        option,
                        self._action_items(row),
                    ):
                        if action.enabled and rect.contains(position):
                            hovered = (id(row), action.key)
                            if hovered != self._hovered_action:
                                QToolTip.showText(
                                    view.viewport().mapToGlobal(position),
                                    action.tooltip,
                                    view.viewport(),
                                    rect,
                                )
                            break
        if hovered != self._hovered_action:
            self._hovered_action = hovered
            view.viewport().setCursor(Qt.PointingHandCursor if hovered else Qt.ArrowCursor)
            if hovered is None:
                QToolTip.hideText()
            view.viewport().update()
        return super().eventFilter(watched, event)

    def _trigger_action(self, key: str, row: UnifiedMessage) -> bool:
        parent_widget = self.parent()
        entry = next((item for item in self._action_items(row) if item.key == key), None)
        if entry is None or not entry.enabled:
            return False
        if key == "view":
            parent_widget._on_view_message(row)
        elif key == "flag":
            parent_widget._cycle_row_flag_state(row)
        elif key == "relay":
            parent_widget._copy_row_to_flamp_relay(row)
        elif key == "relay_remove":
            parent_widget._remove_row_from_flamp_relay(row)
        elif key == "bbs":
            parent_widget._copy_row_to_varac_bbs(row)
        elif key == "bbs_remove":
            parent_widget._remove_row_from_varac_bbs(row)
        elif key == "archive":
            projected = isinstance(row.payload, ProjectedMessagePayload)
            if projected:
                parent_widget._archive_projected_file_message(row)
            else:
                parent_widget._archive_file_record(row.payload)
        elif key == "delete":
            if isinstance(row.payload, FileRecord):
                parent_widget._delete_file_record(row.payload)
            elif isinstance(row.payload, ProjectedMessagePayload) and (
                hasattr(parent_widget, "_file_record_for_message_row")
                and parent_widget._file_record_for_message_row(row, allow_detail_lookup=False) is not None
            ):
                parent_widget._delete_projected_file_message(row)
            elif isinstance(row.payload, JS8Message):
                parent_widget._delete_js8_message(row.payload)
            elif isinstance(row.payload, SpotterMessage):
                parent_widget._delete_spotter_message(row.payload)
            elif isinstance(row.payload, VarACMessage):
                parent_widget._delete_varac_message(row.payload)
            elif isinstance(row.payload, SitrepMessage):
                parent_widget._delete_sitrep_message(row.payload)
            elif isinstance(row.payload, CommStatArtifact):
                parent_widget._delete_commstat_message(row.payload)
            elif isinstance(row.payload, ProjectedMessagePayload):
                parent_widget._delete_projected_message(row)
            else:
                return False
        else:
            return False
        return True

    def editorEvent(self, event, model, option, index):
        if index.column() != 7:
            return False
        if event.type() != QEvent.MouseButtonRelease:
            return False
        if hasattr(event, "button") and event.button() != Qt.LeftButton:
            return False
        row = index.data(Qt.UserRole)
        if row is None:
            return False
        position = event.position().toPoint() if hasattr(event, "position") else event.pos()
        for action, rect in self._chip_rects(option, self._action_items(row)):
            if action.enabled and rect.contains(position):
                return self._trigger_action(action.key, row)
        return False


class MessageCheckboxDelegate(QStyledItemDelegate):
    def editorEvent(self, event, model, option, index):
        if index.column() != 0:
            return False
        if event.type() != QEvent.MouseButtonRelease:
            return False
        if hasattr(event, "button") and event.button() != Qt.LeftButton:
            return False
        state = model.data(index, Qt.CheckStateRole)
        if state is None:
            return False
        new_state = Qt.Unchecked if state == Qt.Checked else Qt.Checked
        model.setData(index, new_state, Qt.CheckStateRole)
        return True


class MessageHeaderWithCheckbox(QHeaderView):
    checkboxToggled = Signal(int)

    def __init__(self, orientation: Qt.Orientation, parent=None):
        super().__init__(orientation, parent)
        self._checkbox_state = Qt.Unchecked
        self._checkbox_enabled = False
        self.setSectionsClickable(True)
        self._select_all_button = QPushButton("Select all", self.viewport())
        self._select_all_button.setAccessibleName("Select all visible messages")
        self._select_all_button.setToolTip("Select all selectable messages currently visible in the Inbox.")
        self._select_all_button.clicked.connect(self._toggle_select_all)
        self.setMinimumHeight(button_height_for_font(self._select_all_button) + 4)
        self.sectionResized.connect(lambda *_args: self._position_select_all_button())
        self.sectionMoved.connect(lambda *_args: self._position_select_all_button())
        QTimer.singleShot(0, self._position_select_all_button)

    def select_button_width_hint(self) -> int:
        metrics = self._select_all_button.fontMetrics()
        return max(
            int(self._select_all_button.sizeHint().width()),
            int(metrics.horizontalAdvance("Clear all")) + int(metrics.horizontalAdvance("MM")) + 16,
        )

    def _position_select_all_button(self) -> None:
        if self.count() <= 0:
            self._select_all_button.hide()
            return
        section_x = self.sectionViewportPosition(0)
        section_width = self.sectionSize(0)
        margin = max(2, int(self.fontMetrics().height() // 6))
        height = max(1, self.height() - (2 * margin))
        self._select_all_button.setGeometry(
            section_x + margin,
            margin,
            max(1, section_width - (2 * margin)),
            height,
        )
        self._select_all_button.show()

    def resizeEvent(self, event) -> None:
        super().resizeEvent(event)
        self._position_select_all_button()

    def _toggle_select_all(self) -> None:
        if not self._checkbox_enabled:
            return
        state = Qt.Unchecked if self._checkbox_state == Qt.Checked else Qt.Checked
        self.set_checkbox_state(state)
        self.checkboxToggled.emit(int(state.value))

    def set_checkbox_state(self, state: Qt.CheckState, enabled: Optional[bool] = None) -> None:
        if enabled is not None:
            self._checkbox_enabled = bool(enabled)
        self._checkbox_state = state
        self._select_all_button.setEnabled(self._checkbox_enabled)
        self._select_all_button.setText("Clear all" if state == Qt.Checked else "Select all")
        self._select_all_button.setAccessibleName(
            "Clear selection for visible messages" if state == Qt.Checked else "Select all visible messages"
        )
        self._select_all_button.setToolTip(
            "Clear the visible message selection."
            if state == Qt.Checked
            else "Select all selectable messages currently visible in the Inbox."
        )
        self._position_select_all_button()

    def set_checkbox_colors(
        self, *, bg: QColor, border: QColor, accent: QColor, mark: QColor
    ) -> None:
        # Kept for callers that refresh screen-specific colors.  The real
        # QPushButton inherits the shared application theme automatically.
        del bg, border, accent, mark
        self._select_all_button.style().unpolish(self._select_all_button)
        self._select_all_button.style().polish(self._select_all_button)


class MessageViewerTab(QWidget):
    busyStateChanged = Signal(bool)
    meshSendRequested = Signal(object)
    # The endpoint worker is primary-owned.  The Compose UI only emits a
    # snapshot request and accepts a matching completed result; it never makes
    # a JS8 API call from a paint, preview, or editing path.
    composeJs8SelectedTargetRefreshRequested = Signal(object)

    """
    Message Viewer for VarAC / FLMSG / FLAMP inbox-like folders.

    - Watches configured folders by origin
    - Shows a unified messages table (JS8 + file-based) with a viewer
    - Scan interval selectable (1 / 15 / 30 / 60 minutes)
    """

    def __init__(self, parent=None, *, plan_context_service: Optional[PlanContextService] = None):
        super().__init__(parent)
        self.settings = SettingsManager()
        self._multi_radio_store = MultiRadioStore()
        self.plan_context_service = plan_context_service or PlanContextService()
        default_mode = (self.settings.get("display_time_mode", "LOCAL") or "LOCAL").upper()
        self._time_mode_override: str | None = None
        self._show_local_time = default_mode != "UTC"
        cfg = self.settings.get("message_viewer", {}) or {}
        self._excluded_msg_types: set[str] = self._normalize_excluded_msg_types(
            cfg.get("excluded_msg_types", [])
        )
        self._inbox_focus: str = str(cfg.get("inbox_focus", "all") or "all").strip().lower()
        if self._inbox_focus not in {"all", "new", "forms", "spotter", "commstat", "js8call", "mesh", "varac", "bbs"}:
            self._inbox_focus = "all"
        self._advanced_filters_visible: bool = bool(cfg.get("advanced_filters_visible", False))
        self._inbox_tools_visible: bool = bool(cfg.get("inbox_tools_visible", True))
        self._projection_primary_enabled: bool = self._is_truthy(
            cfg.get("projection_primary_enabled", True), True
        )
        self._available_type_filters: List[str] = []
        self._inbox_focus_unread_counts: Dict[str, int] = {}
        self._projection_focus_counts_available: bool = False
        self._focus_counts_generation: int = 0
        self._responsive_layout_mode = "wide"
        self._responsive_compact_width = 1200
        msg_paths = self.settings.get("message_paths", {}) or {}
        self.watch_dirs: List[Dict] = []
        for origin in ["js8", "varac", "flmsg", "flamp"]:
            p = msg_paths.get(origin, "")
            if p:
                self.watch_dirs.append({"path": p, "origin": origin})
        if not self.watch_dirs and not self._multi_radio_message_path_entries():
            self.watch_dirs = _default_message_watch_dirs()
        fldigi_log_path = (self.settings.get("fldigi_log_path", "") or "").strip()
        if fldigi_log_path:
            images_dir = Path(fldigi_log_path) / "images"
            if images_dir.exists():
                existing = {(w.get("origin"), w.get("path")) for w in self.watch_dirs}
                entry = ("flmsg", str(images_dir))
                if entry not in existing:
                    self.watch_dirs.append({"path": str(images_dir), "origin": "flmsg"})
        self.scan_minutes: int = cfg.get("scan_minutes") or 15
        if self.scan_minutes not in SCAN_CHOICES:
            self.scan_minutes = 15
        try:
            visible_check_raw = cfg.get("visible_check_seconds", 30)
            self._visible_check_interval_sec: int = 30 if visible_check_raw is None else int(visible_check_raw)
        except Exception:
            self._visible_check_interval_sec = 30
        valid_check_seconds = {int(seconds) for _label, seconds in MESSAGE_CHECK_CHOICES}
        if self._visible_check_interval_sec not in valid_check_seconds:
            self._visible_check_interval_sec = 30

        self.js8_messages: List[JS8Message] = []
        self.spotter_messages: List[SpotterMessage] = []
        self.varac_messages: List[VarACMessage] = []
        self.sitrep_messages: List[SitrepMessage] = []
        self.commstat_messages: List[CommStatArtifact] = []
        self.observation_messages: List[Observation] = []
        self.current_js8: JS8Message | None = None
        self.current_sitrep: SitrepMessage | None = None
        self.current_commstat: CommStatArtifact | None = None
        self.current_observation: Observation | None = None
        self._js8_timer: QTimer | None = None
        self._pending_timer: QTimer | None = None
        self._clock_timer: QTimer | None = None
        self._message_check_timer: QTimer | None = None
        self._file_system_watcher: QFileSystemWatcher | None = None
        self._file_watch_debounce_timer: QTimer | None = None
        self._projection_delete_queue_timer: QTimer | None = None
        self._pending_rows: List[Dict[str, str | float]] = []
        self._pending_rows_signature: str = ""
        self._form_cache: Dict[str, List[Dict]] = {}
        self._form_title_cache: Dict[str, str] = {}
        self.forms_path = (self.settings.get("js8_forms_path", "") or "").strip()
        self._messages_mode: str = "Inbox"
        self._compose_templates: List[ComposeFormTemplate] = []
        self._compose_template_kind: str = "custom"
        self._compose_summary_context = None
        self._traffic_summary_dialog = None
        self._compose_field_widgets: Dict[str, QWidget] = {}
        self._compose_field_rows: List[ComposeFieldDefinition] = []
        self._compose_spotter_fields: List[SpotterFormField] = []
        self._compose_spotter_guidance: tuple[str, ...] = ()
        self._compose_last_smart_defaults: Dict[str, str] = {}
        self._compose_template_title: str = ""
        self._compose_template_menu_item: str = ""
        self._compose_active_form_key: str = ""
        self._compose_form_draft_values: Dict[str, Dict[str, str]] = {}
        self._compose_form_draft_mode_keys: Dict[str, Set[str]] = {}
        self._compose_mode_drafts: Dict[str, Dict[str, object]] = {}
        self._compose_restoring_mode_draft: bool = False
        self._compose_mode: str = "nbems"
        # Expect responses are a bounded, activation-scoped source catalog for
        # Spotter Compose.  The selected row is copied into a local working
        # response; Compose never edits the Expect store from this surface.
        self._compose_spotter_expect_entries: List[Dict[str, object]] = []
        self._compose_spotter_expect_loaded: bool = False
        self._compose_spotter_expect_active_id: int = 0
