    def resizeEvent(self, event) -> None:
        super().resizeEvent(event)
        self._update_messages_responsive_layout()

    def changeEvent(self, event) -> None:
        super().changeEvent(event)
        if event.type() in {QEvent.FontChange, QEvent.PaletteChange, QEvent.StyleChange}:
            self._message_table_fit_signature = None
            self._queue_message_table_column_fit()
            self._refresh_compose_layout_geometry_if_needed(force=True)

    def _messages_responsive_mode_for_width(self, width: int) -> str:
        try:
            return "compact" if int(width) < int(self._responsive_compact_width) else "wide"
        except Exception:
            return "wide"

    def _update_messages_responsive_layout(self) -> None:
        layout = getattr(self, "_inbox_actions_layout", None)
        if layout is None:
            return
        mode = self._messages_responsive_mode_for_width(int(self.width() or 0))
        if mode == self._responsive_layout_mode and layout.count() > 0:
            self._apply_inbox_primary_height_guard()
            if hasattr(self, "compose_splitter"):
                compose_mode = str(getattr(self, "_compose_mode", "nbems") or "nbems")
                compose_sidebar = self._compose_sidebar_enabled(
                    compose_mode,
                    int(self.width() or 0),
                    in_workbench=bool(getattr(self, "_compose_in_workbench", False)),
                )
                if hasattr(self, "compose_body_splitter"):
                    desired_body = Qt.Horizontal if compose_sidebar else Qt.Vertical
                    if self.compose_body_splitter.orientation() != desired_body:
                        self.compose_body_splitter.setOrientation(desired_body)
                if self.compose_splitter.orientation() != Qt.Vertical:
                    self.compose_splitter.setOrientation(Qt.Vertical)
                # A native resize can be caused by the geometry pass itself.
                # Signature de-duplication is therefore mandatory on this
                # path; forcing here creates a resize -> layout -> resize loop.
                self._refresh_compose_layout_geometry_if_needed()
            return
        self._responsive_layout_mode = mode
        compact = mode == "compact"
        self._arrange_inbox_action_controls(compact=compact)
        self._apply_inbox_primary_height_guard()
        if hasattr(self, "compose_splitter"):
            compose_mode = str(getattr(self, "_compose_mode", "nbems") or "nbems")
            compose_sidebar = self._compose_sidebar_enabled(
                compose_mode,
                int(self.width() or 0),
                in_workbench=bool(getattr(self, "_compose_in_workbench", False)),
            )
            if hasattr(self, "compose_body_splitter"):
                desired_body = Qt.Horizontal if compose_sidebar else Qt.Vertical
                if self.compose_body_splitter.orientation() != desired_body:
                    self.compose_body_splitter.setOrientation(desired_body)
            if self.compose_splitter.orientation() != Qt.Vertical:
                self.compose_splitter.setOrientation(Qt.Vertical)
            self._refresh_compose_layout_geometry_if_needed(force=True)

    def _apply_inbox_primary_height_guard(self) -> None:
        """Reserve a usable Inbox list viewport without growing ancillary UI."""

        if str(getattr(self, "_messages_mode", "Inbox") or "Inbox") != "Inbox":
            return
        table = getattr(self, "messages_table", None)
        if table is None:
            return
        required_viewport = 240 if int(self.height() or 0) >= 700 else 160
        try:
            chrome = int(table.horizontalHeader().sizeHint().height()) + (table.frameWidth() * 2) + 4
            table.setMinimumHeight(required_viewport + chrome)
        except Exception:
            return

    def _arrange_inbox_action_controls(self, *, compact: bool) -> None:
        layout = getattr(self, "_inbox_actions_layout", None)
        if layout is None:
            return
        while layout.count():
            layout.takeAt(0)
        for col in range(4):
            layout.setColumnStretch(col, 0)
        self.message_check_status_label.setWordWrap(True)
        for widget in (
            self.refresh_btn,
            self.view_spotter_map_btn,
            self.more_actions_btn,
            self.bbs_status_btn,
            self.bbs_manage_btn,
            self.inbox_bbs_summary_label,
            self.time_toggle_btn,
            self.message_check_combo,
            self.type_filter,
            self.status_filter,
            self.from_filter,
            self.to_filter,
            self.exclude_types_btn,
        ):
            widget.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
            try:
                widget.setMinimumHeight(max(24, int(widget.sizeHint().height())))
            except Exception:
                pass
        placements = [
            (self.inbox_actions_heading, 0, 0, 1, 2),
            (self.refresh_btn, 1, 0),
            (self.message_check_combo, 1, 1),
            (self.view_spotter_map_btn, 2, 0, 1, 2),
            (self.more_actions_btn, 3, 0, 1, 2),
            (self.inbox_message_type_label, 4, 0),
            (self.type_filter, 4, 1),
            (self.inbox_status_label, 5, 0),
            (self.status_filter, 5, 1),
            (self.inbox_from_label, 6, 0),
            (self.from_filter, 6, 1),
            (self.inbox_to_label, 7, 0),
            (self.to_filter, 7, 1),
            (self.exclude_types_btn, 8, 0, 1, 2),
            (self.time_toggle_btn, 9, 0, 1, 2),
            (self.inbox_bbs_heading, 10, 0, 1, 2),
            (self.bbs_status_btn, 11, 0, 1, 2),
            (self.bbs_manage_btn, 12, 0, 1, 2),
            (self.inbox_bbs_summary_label, 13, 0, 1, 2),
            (self.message_check_status_label, 14, 0, 1, 2),
        ]
        for item in placements:
            widget, row, col, *span = item
            row_span, col_span = span if span else (1, 1)
            layout.addWidget(widget, row, col, row_span, col_span)
        layout.setColumnStretch(0, 0)
        layout.setColumnStretch(1, 1)
        layout.setRowStretch(23, 1)
        try:
            self.inbox_controls_panel.setMinimumHeight(max(420, int(layout.sizeHint().height())))
        except Exception:
            pass
        self._sync_advanced_filter_visibility()
        self._apply_inbox_tools_visibility()

    def _set_inbox_tools_visible(self, visible: bool) -> None:
        self._inbox_tools_visible = bool(visible)
        self._apply_inbox_tools_visibility()
        if hasattr(self, "messages_mode_stack"):
            self._save_settings()

    def _apply_inbox_tools_visibility(self) -> None:
        scroll = getattr(self, "inbox_controls_scroll", None)
        toggle = getattr(self, "inbox_tools_toggle_btn", None)
        visible = bool(getattr(self, "_inbox_tools_visible", True))
        compose_active = str(getattr(self, "_messages_mode", "Inbox") or "Inbox") == "Compose"
        if scroll is not None:
            scroll.setVisible(visible and not compose_active)
            if visible:
                scroll.setMinimumWidth(262)
                scroll.setMaximumWidth(352)
            else:
                scroll.setMinimumWidth(0)
                scroll.setMaximumWidth(0)
        if isinstance(toggle, QPushButton):
            toggle.blockSignals(True)
            toggle.setChecked(visible)
            toggle.setText("Hide Inbox Tools" if visible else "Show Inbox Tools")
            toggle.blockSignals(False)
            toggle.setVisible(not compose_active)
            try:
                toggle.setStyleSheet(button_style("muted", resolve_theme(self.settings)))
            except Exception:
                pass

    @staticmethod
    def _inbox_focus_options() -> List[Tuple[str, str, str]]:
        return [
            ("all", "All", "Show all message traffic."),
            ("new", "New", "Show unread or alerting traffic."),
            ("forms", "FLMSG/FLAMP", "Show Fast Light forms and FLAmp files."),
            ("spotter", "Spotter", "Show CommsPlan Spotter MCF forms."),
            ("commstat", "CommStat", "Show CommStat-derived messages and reports."),
            ("js8call", "JS8Call", "Show raw JS8Call messages that are not Spotter MCF forms."),
            ("mesh", "Mesh", "Show MeshCore and Meshtastic local mesh traffic."),
            ("varac", "VarAC", "Show VarAC messages."),
            ("bbs", "BBS", "Manage live BBS, managed library, incoming, outgoing, and archived BBS files."),
        ]

    def _set_inbox_focus(self, focus: str) -> None:
        left_ops_scope = self._leave_ops_traffic_scope()
        focus = str(focus or "all").strip().lower()
        valid = {key for key, _label, _tip in self._inbox_focus_options()}
        if focus not in valid:
            focus = "all"
        self._close_message_reader_for_scope_change()
        if focus == self._inbox_focus:
            self._sync_inbox_focus_buttons()
            self._sync_source_filter_for_inbox_focus(focus)
            if left_ops_scope and self._load_projected_messages_into_table():
                return
            if self._reload_projected_messages_for_scope_change():
                return
            return
        self._inbox_focus = focus
        self._intel_status_filter = ""
        self._intel_topic_filter = ""
        self._traffic_action_filter = ""
        if hasattr(self, "traffic_action_summary"):
            self.traffic_action_summary.set_active_bucket("")
        self._sync_inbox_focus_buttons()
        self._sync_source_filter_for_inbox_focus(focus)
        self._unfreeze_table()
        if self._reload_projected_messages_for_scope_change():
            self._save_settings()
            return
        self._apply_message_filters_light()
        self._save_settings()

    def _sync_inbox_focus_buttons(self) -> None:
        theme = resolve_theme(self.settings)
        labels = {key: label for key, label, _tip in self._inbox_focus_options()}
        for key, btn in getattr(self, "_inbox_focus_buttons", {}).items():
            active = key == self._inbox_focus
            count = int(getattr(self, "_inbox_focus_unread_counts", {}).get(key, 0))
            button_text = f"{labels.get(key, key.title())} {count}"
            btn.setText(button_text)
            try:
                btn.setMinimumWidth(max(100, int(btn.fontMetrics().horizontalAdvance(button_text) + 34)))
            except Exception:
                pass
            btn.blockSignals(True)
            btn.setChecked(active)
            btn.blockSignals(False)
            btn.setStyleSheet(button_style("primary" if active else "muted", theme))

    @staticmethod
    def _row_is_unread_for_focus_count(row: UnifiedMessage) -> bool:
        status = str(getattr(row, "status", "") or "").strip().upper()
        if status == "READ":
            return False
        if status in {"NEW", "UNREAD", "ALERT", "YELLOW", "RED"}:
            return True
        payload = getattr(row, "payload", None)
        read_state = str(getattr(payload, "read_state", "") or "").strip().lower()
        if read_state:
            return read_state in {"new", "unread", "alert"}
        return False

    def _refresh_inbox_focus_unread_counts(self, rows: Sequence[UnifiedMessage], *, now_ts: float) -> None:
        age_filter = self.received_filter.currentData() if hasattr(self, "received_filter") else 0
        selected_groups = self._expanded_selected_message_groups()
        configured_groups = self._configured_message_group_names()
        focus_keys = [key for key, _label, _tip in self._inbox_focus_options()]
        counts: Dict[str, int] = {key: 0 for key in focus_keys}
        for row in rows:
            if not _core_row_matches_workspace_scope(
                row,
                selected_sources=None,
                selected_groups=selected_groups,
                configured_groups=configured_groups,
            ):
                continue
            if not _core_row_matches_age_filter(row, age_filter, now_ts=now_ts):
                continue
            if not self._row_is_unread_for_focus_count(row):
                continue
            counts["all"] += 1
            for key in focus_keys:
                if key != "all" and _core_row_matches_inbox_focus(row, key):
                    counts[key] += 1
        self._inbox_focus_unread_counts = counts
        self._sync_inbox_focus_buttons()

    def _update_visible_message_scope_label(self) -> None:
        label = getattr(self, "message_scope_label", None)
        if label is None:
            return
        if getattr(self, "_ops_traffic_message_ids", None) is not None:
            summary = getattr(self, "_ops_traffic_summary", None)
            bucket = str(self._traffic_action_filter or "")
            count = None
            if summary is not None:
                count = summary.count(bucket) if bucket else len(summary.items)
            text = f"Ops Center traffic · {bucket.title() or 'All actions'} · "
            text += f"{count} available" if count is not None else "Loading…"
            expected = getattr(self, "_ops_traffic_count_at_click", 0)
            if count is not None and bucket == getattr(self, "_ops_traffic_clicked_bucket", "") and count != expected:
                text += f" ({expected} at click; traffic changed)"
            label.setText(text + " · Inbox filters suspended; change a filter to leave this view.")
            return
        age = str(self.received_filter.currentText() or "All time").strip()
        focus_labels = {key: value for key, value, _tip in self._inbox_focus_options()}
        focus = focus_labels.get(getattr(self, "_inbox_focus", "all"), "All")
        groups = str(self.operating_group_filter.text() or "Groups: Configured").strip()
        sources = str(self.source_filter.text() or "Sources: All").strip()
        label.setText(f"Showing: {age} · Focus {focus} · {groups} · {sources}")
        try:
            theme = resolve_theme(self.settings)
            label.setStyleSheet(f"font-weight: 600; color: {theme.get('text_muted', '#5b6875')};")
        except Exception:
            pass

    @staticmethod
    def _source_values_for_inbox_focus(focus: object) -> list[str]:
        return list(focus_source_values(focus))

    def _sync_source_filter_for_inbox_focus(self, focus: object) -> None:
        source_filter = getattr(self, "source_filter", None)
        if source_filter is None:
            return
        options = self._dropdown_option_values(source_filter)
        source_values = self._source_values_for_inbox_focus(focus)
        if not source_values:
            selected = sorted(options)
        else:
            selected = [value for value in source_values if value in options]
            if not selected:
                selected = sorted(options)
        try:
            source_filter.blockSignals(True)
            source_filter.set_selected_values(selected)
        finally:
            try:
                source_filter.blockSignals(False)
            except Exception:
                pass

    def _projected_source_families_for_current_scope(self) -> tuple[str, ...]:
        focus_values = self._source_values_for_inbox_focus(getattr(self, "_inbox_focus", "all"))
        selected = self._selected_message_sources()
        requested = list(focus_values or sorted(selected or []))
        if not requested:
            return ()
        expanded: set[str] = set()
        for value in requested:
            source = str(value or "").strip().lower()
            if not source:
                continue
            if source in {"mesh", "meshcore", "meshtastic"}:
                expanded.update({"mesh", "meshcore", "meshtastic"})
            elif source == "bbs":
                expanded.update({"bbs", "bbs_archive"})
            elif source in {"spotter", "commstat"}:
                # ``sitrep`` remains a projection/storage family containing
                # historical Spotter and CommStat records.  Query it for both
                # operator-facing scopes, then let the semantic row filter
                # keep the two sources separate in the Inbox.
                expanded.update({source, "sitrep"})
            else:
                expanded.add(source)
        return tuple(sorted(expanded))

    def _reload_projected_messages_for_scope_change(self) -> bool:
        if not self._projection_primary_enabled:
            return False
        if self._projected_scope_key() == getattr(self, "_projected_scope_load_key", None):
            return False
        self._unfreeze_table()
        return self._load_projected_messages_into_table(force=False)

    def _projected_scope_key(self) -> tuple[object, ...]:
        ids = getattr(self, "_ops_traffic_message_ids", None)
        if ids is not None:
            return ("ops-traffic", ids)
        age_bounds = _core_age_filter_bounds(
            self.received_filter.currentData() if hasattr(self, "received_filter") else 0
        )
        status = self.status_filter.currentText() if hasattr(self, "status_filter") else ""
        groups = self._expanded_selected_message_groups()
        return (
            str(getattr(self, "_inbox_focus", "all") or "all").strip().lower(),
            self._projected_source_families_for_current_scope(),
            age_bounds,
            (self.rcv_search.text() if hasattr(self, "rcv_search") else "").strip().lower(),
            status,
            tuple(sorted(groups or ())),
            self.type_filter.currentText() if hasattr(self, "type_filter") else "",
            self.from_filter.currentText() if hasattr(self, "from_filter") else "",
            self.to_filter.currentText() if hasattr(self, "to_filter") else "",
        )

    def _toggle_advanced_filters(self) -> None:
        self._advanced_filters_visible = bool(self.advanced_filters_btn.isChecked())
        self._sync_advanced_filter_visibility()
        self._save_settings()

    def _sync_advanced_filter_visibility(self) -> None:
        visible = bool(getattr(self, "_advanced_filters_visible", False))
        container = getattr(self, "message_funnel_widget", None)
        if container is not None:
            container.setUpdatesEnabled(False)
        try:
            if hasattr(self, "advanced_filters_btn"):
                self.advanced_filters_btn.blockSignals(True)
                self.advanced_filters_btn.setChecked(visible)
                self.advanced_filters_btn.blockSignals(False)
                self.advanced_filters_btn.setText("Advanced Filters")
                tooltip = (
                    "Hide detailed filters for time, type, status, sender, group, and source."
                    if visible
                    else "Show detailed filters for time, type, status, sender, group, and source."
                )
                self.advanced_filters_btn.setToolTip(tooltip)
                self.advanced_filters_btn.setStyleSheet(
                    button_style("secondary" if visible else "muted", resolve_theme(self.settings))
                )
            widgets = [
                getattr(self, "inbox_message_type_label", None),
                getattr(self, "type_filter", None),
                getattr(self, "inbox_status_label", None),
                getattr(self, "status_filter", None),
                getattr(self, "inbox_from_label", None),
                getattr(self, "from_filter", None),
                getattr(self, "inbox_to_label", None),
                getattr(self, "to_filter", None),
                getattr(self, "exclude_types_btn", None),
            ]
            for widget in widgets:
                if widget is not None:
                    widget.setVisible(visible)
            if hasattr(self, "clear_filters_btn"):
                self.clear_filters_btn.setVisible(True)
        finally:
            if container is not None:
                container.setUpdatesEnabled(True)
                container.updateGeometry()

    def _setup_clock_timer(self) -> None:
        if self._clock_timer is not None:
            self._clock_timer.stop()
        self._clock_timer = QTimer(self)
        self._clock_timer.timeout.connect(self._on_clock_tick)
        self._clock_timer.start(1000)
        self._update_clock_labels()

    def _on_clock_tick(self) -> None:
        self._update_clock_labels()
        self._update_message_check_status()

    def _update_clock_labels(self) -> None:
        if not hasattr(self, "utc_label") or not hasattr(self, "local_label"):
            return
        now_utc = datetime.datetime.now(datetime.timezone.utc)
        utc_day = now_utc.strftime("%a")
        self.utc_label.setText(now_utc.strftime(f"<b>UTC ({utc_day}):</b> %y%m%d %H:%M:%S Z"))

        tz_name = self.settings.get("timezone", "UTC") or "UTC"
        tz = get_timezone(tz_name)
        now_local = now_utc.astimezone(tz)
        fallback = now_local.tzname() or tz_name
        local_abbr = fallback or tz_name
        local_day = now_local.strftime("%a")
        self.local_label.setText(now_local.strftime(f"<b>Local ({local_day}):</b> %y%m%d %H:%M:%S {local_abbr}"))
        if hasattr(self, "time_toggle_btn"):
            self.time_toggle_btn.setText("Time Display: Local" if self._show_local_time else "Time Display: UTC")

