    def _refresh_compose_mode_selector_style(self) -> None:
        selector = getattr(self, "compose_mode_selector", None)
        if not isinstance(selector, QListWidget):
            return
        theme = resolve_theme(self.settings)
        selector.setStyleSheet(choice_chip_selector_style(selector.objectName(), theme))

    def _configure_compose_combo_width(self, combo: QComboBox, *, floor: int = 110) -> None:
        try:
            fm = combo.fontMetrics()
            item_w = 0
            for i in range(combo.count()):
                item_w = max(item_w, int(fm.horizontalAdvance(combo.itemText(i))))
            target = max(int(floor), item_w + 56)
        except Exception:
            target = int(floor)
        combo.setMinimumWidth(target)
        combo.setMinimumContentsLength(6)
        combo.setSizeAdjustPolicy(QComboBox.AdjustToContents)
        combo.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)

    def _set_compose_fixed_width(self, widget: QWidget, *, floor: int, ceiling: int) -> None:
        try:
            widget.setMinimumWidth(int(floor))
            widget.setMaximumWidth(int(ceiling))
            widget.setSizePolicy(QSizePolicy.Fixed, QSizePolicy.Fixed)
        except Exception:
            pass

    def _refresh_compose_splitter_handles(self) -> None:
        """Natural content sizing applies in both Compose hosts."""
        handle_width = 0
        for splitter_name in ("compose_body_splitter", "compose_splitter"):
            splitter = getattr(self, splitter_name, None)
            if isinstance(splitter, QSplitter):
                try:
                    splitter.setHandleWidth(handle_width)
                except Exception:
                    pass

    def _compose_layout_viewport(self) -> QWidget:
        """Return the widget that currently owns Compose's available geometry."""
        dialog = getattr(self, "_compose_workbench_dialog", None)
        if bool(getattr(self, "_compose_in_workbench", False)) and isinstance(dialog, QDialog):
            return dialog
        return self

    def _compose_workbench_available_geometry(self) -> QRect:
        """Use the owning screen's usable area so a workbench never opens off-screen."""
        screen = None
        try:
            screen = self.screen()
        except Exception:
            screen = None
        if screen is None:
            app = QApplication.instance()
            screen = app.primaryScreen() if app is not None else None
        if screen is not None:
            try:
                return screen.availableGeometry()
            except Exception:
                pass
        return QRect(0, 0, 1280, 800)

    @staticmethod
    def _compose_spotter_sidebar_width(viewport_width: int, *, in_workbench: bool) -> int:
        """Choose a readable Spotter setup width without starving the main pane."""
        width = max(1, int(viewport_width or 0))
        preferred = 520 if in_workbench else 480
        minimum = 440 if in_workbench else 420
        # Keep the form editor/preview area dominant even at the smallest
        # width that still qualifies as a sidebar layout.
        primary_minimum = 640
        available = max(minimum, width - primary_minimum)
        return min(preferred, available)

    def _compose_sidebar_enabled(
        self,
        mode: str,
        viewport_width: int,
        *,
        in_workbench: bool,
    ) -> bool:
        """Use a side setup rail only when both rail and work surface can read.

        The previous fixed 260px CommStat rail allowed the target cue and its
        two actions to compete for a few pixels, producing one-character
        wrapping.  Keep the setup rail readable and promote it above the work
        surface until the viewport can support both panes.
        """
        mode = str(mode or "nbems")
        width = max(1, int(viewport_width or 0))
        compact_threshold = 920 if in_workbench else int(self._responsive_compact_width)
        if width < compact_threshold or mode not in {"nbems", "js8", "spotter", "commstat_rf", "mesh"}:
            return False
        rail_minimum = self._compose_sidebar_readable_minimum_width(
            mode,
            in_workbench=in_workbench,
        )
        # The form/preview surface remains the dominant pane.  Add a small
        # handle/gutter allowance so the split never relies on child clipping.
        return width >= rail_minimum + 640 + 24

    def _compose_sidebar_readable_minimum_width(
        self,
        mode: str,
        *,
        in_workbench: bool,
    ) -> int:
        """Calculate a content-derived rail floor for the current font scale."""
        mode = str(mode or "nbems")
        base = {
            "spotter": 440 if in_workbench else 420,
            "commstat_rf": 440 if in_workbench else 420,
            "js8": 440 if in_workbench else 420,
            "nbems": 430 if in_workbench else 400,
            "mesh": 430 if in_workbench else 400,
        }.get(mode, 400)
        # The JS8 selection cue owns two actions on its second row.  Derive
        # their required width from the active theme/font rather than assuming
        # the default-text screenshot's button dimensions.  A scaled font can
        # therefore promote the setup above the form before clipping occurs.
        use_btn = getattr(self, "compose_js8_selected_target_use_btn", None)
        clear_btn = getattr(self, "compose_js8_selected_target_clear_btn", None)
        refresh_btn = getattr(self, "compose_js8_selected_target_refresh_btn", None)
        action_width = 0
        for button in (use_btn, clear_btn, refresh_btn):
            try:
                action_width += int(button.sizeHint().width())
            except Exception:
                continue
        if action_width:
            try:
                label_floor = max(
                    120,
                    int(self.fontMetrics().horizontalAdvance("Target selected in JS8Call") * 0.55),
                )
            except Exception:
                label_floor = 160
            action_width += label_floor + 32
        return max(base, action_width)

    @staticmethod
    def _set_compose_splitter_sizes_if_needed(splitter: QSplitter, sizes: Sequence[int]) -> None:
        """Avoid re-applying identical splitter geometry during signal bursts."""
        requested = [max(0, int(size)) for size in sizes]
        try:
            current = splitter.sizes()
            if len(current) == len(requested) and all(
                abs(int(current_size) - requested_size) <= 2
                for current_size, requested_size in zip(current, requested)
            ):
                return
            splitter.setSizes(requested)
        except Exception:
            pass

    def _refresh_compose_commstat_content_geometry(self) -> None:
        """Keep CommStat's scroll child at its content-derived readable height.

        A ``QScrollArea`` with ``widgetResizable`` may shrink its child to the
        child's minimum height.  CommStat has six status rows, so its former
        fixed 240px minimum allowed the grid to compress rows below the
        controls' readable height on Linux.  Derive the controls and scroll
        child's floor from the active font and layout instead; the scroll area
        owns any vertical overflow at compact heights.
        """
        row = getattr(self, "compose_commstat_row_widget", None)
        if not isinstance(row, QWidget):
            return
        layout = row.layout()
        if layout is None:
            return

        controls: List[QWidget] = []
        for name in (
            "compose_commstat_kind_combo",
            "compose_commstat_target_edit",
            "compose_commstat_grid_edit",
            "compose_commstat_scope_combo",
            "compose_commstat_report_id_edit",
            "compose_commstat_brevity_chk",
            "compose_commstat_brevity_edit",
            "compose_commstat_brevity_list_combo",
            "compose_commstat_brevity_event_combo",
            "compose_commstat_brevity_status_combo",
            "compose_commstat_brevity_impact_combo",
            "compose_commstat_brevity_public_combo",
            "compose_commstat_brevity_station_combo",
        ):
            widget = getattr(self, name, None)
            if isinstance(widget, QWidget):
                controls.append(widget)
        controls.extend(
            widget
            for widget in getattr(self, "compose_commstat_status_widgets", {}).values()
            if isinstance(widget, QWidget)
        )
        for control in controls:
            try:
                hint_height = max(
                    28,
                    int(control.sizeHint().height()),
                    int(control.minimumSizeHint().height()),
                )
                control.setMinimumHeight(
                    control_height_for_font(
                        control,
                        vertical_padding=10,
                        floor=hint_height,
                    )
                )
            except Exception:
                continue

        for label in list(getattr(self, "compose_commstat_status_labels", {}).values()):
            if not isinstance(label, QLabel):
                continue
            try:
                hint_height = max(
                    24,
                    int(label.sizeHint().height()),
                    int(label.minimumSizeHint().height()),
                )
                label.setMinimumHeight(
                    single_line_label_height(
                        label,
                        vertical_padding=6,
                        floor=hint_height,
                    )
                )
            except Exception:
                continue

        try:
            layout.activate()
            row.setMinimumHeight(
                max(int(layout.minimumSize().height()), int(row.minimumSizeHint().height()))
            )
            row.updateGeometry()
        except Exception:
            return

    def _refresh_compose_mode_selector_geometry(self) -> None:
        """Wrap compose modes using the active font and available width.

        The selector is part of the setup rail, so it must never widen that
        rail just because a translated or scaled mode label is longer.  Item
        widths and row heights are derived from the actual font metrics; the
        list then owns its calculated vertical extent and keeps horizontal
        scrolling disabled.
        """
        selector = getattr(self, "compose_mode_selector", None)
        if not isinstance(selector, QListWidget):
            return
        try:
            type_box = getattr(self, "compose_type_box", None)
            if isinstance(type_box, QGroupBox):
                # Release a stale aggregate floor before measuring.  Older
                # accessibility passes used the QListWidget's whole viewport
                # hint as a group-title floor; responsive geometry must be
                # able to recover in the same process after font/theme work.
                type_box.setMinimumHeight(0)
                type_box.setMaximumHeight(16777215)
            metrics = selector.fontMetrics()
            line_height = max(1, int(metrics.lineSpacing()))
            row_height = button_height_for_font(
                selector,
                vertical_padding=max(1, line_height // 2),
                floor=line_height,
            )
            item_gap = max(1, line_height // 3)
            widths: List[int] = []
            for index in range(selector.count()):
                item = selector.item(index)
                text = item.text() if item is not None else ""
                width = max(
                    line_height,
                    # The shared selector style adds horizontal padding and a
                    # trailing item margin. Reserve three line-heights so the
                    # delegate still owns the complete label on platform
                    # styles whose content rect is narrower than the item.
                    int(metrics.horizontalAdvance(text)) + 3 * line_height,
                )
                widths.append(width)
                if item is not None:
                    item.setSizeHint(QSize(width, row_height))
            selector.setTextElideMode(Qt.ElideNone)
            available = int(selector.viewport().width() or 0)
            if available <= 0:
                available = int(selector.width() or 0)
            if available <= 0:
                parent = selector.parentWidget()
                available = int(parent.width() or 0) if parent is not None else 0
            available = max(1, available)
            rows = 1
            # QListView's flow layout applies spacing on both adjacent item
            # edges. Account for those painted gutters and the outer gutters
            # when predicting wraps; using one spacing unit under-counted the
            # row width and let the final mode silently spill to another row.
            flow_gap = 2 * item_gap
            used = item_gap
            for width in widths:
                trailing = item_gap
                if used > item_gap and used + flow_gap + width + trailing > available:
                    rows += 1
                    used = item_gap + width
                else:
                    used += width if used == item_gap else flow_gap + width
            frame = max(1, int(selector.frameWidth()))
            height = rows * row_height + 2 * frame + 2 * rows * item_gap
            selector.setSpacing(item_gap)
            selector.setMinimumHeight(height)
            selector.setMaximumHeight(height)
            selector.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
            selector.setVerticalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
            selector.updateGeometry()
            if isinstance(type_box, QGroupBox):
                type_layout = type_box.layout()
                if type_layout is not None:
                    type_layout.activate()
                natural_height = max(
                    height + type_layout.contentsMargins().top() + type_layout.contentsMargins().bottom(),
                    int(type_box.sizeHint().height()),
                )
                type_box.setMinimumHeight(natural_height)
                type_box.setMaximumHeight(natural_height)
                type_box.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
                type_box.updateGeometry()
        except Exception:
            # Geometry refresh is best effort during construction; the next
            # queued resize pass will retry once the widget has a viewport.
            return

    @staticmethod
    def _set_compose_row_reflow(widget: QWidget, compact: bool) -> None:
        """Stack local setup controls when the setup rail is compact."""
        layout = widget.layout()
        if isinstance(layout, QBoxLayout):
            layout.setDirection(
                QBoxLayout.TopToBottom if compact else QBoxLayout.LeftToRight
            )
            if compact:
                widget.setMaximumHeight(16777215)
            else:
                widget.setMaximumHeight(
                    control_height_for_font(widget, vertical_padding=14, floor=1)
                )
        else:
            # A grid may intentionally own more than one row. The JS8 and
            # Spotter destination grid puts delivery mode below the target;
            # capping that grid to one control line makes the checkbox overlap
            # the destination editor at wide widths.
            widget.setMaximumHeight(16777215)
            if layout is not None:
                try:
                    widget.setMinimumHeight(0)
                    layout.activate()
                    widget.setMinimumHeight(max(0, int(layout.minimumSize().height())))
                except Exception:
                    pass
        widget.updateGeometry()

    @staticmethod
    def _set_compose_compact_width(widget: QWidget, compact: bool) -> None:
        """Temporarily release hard minimum widths inside a narrow setup rail."""
        if widget.property("composeOriginalMinimumWidth") is None:
            widget.setProperty(
                "composeOriginalMinimumWidth",
                int(widget.minimumWidth()),
            )
        if compact:
            widget.setMinimumWidth(0)
        else:
            original = widget.property("composeOriginalMinimumWidth")
            widget.setMinimumWidth(max(0, int(original or 0)))

    def _refresh_compose_responsive_setup(self, compact: bool) -> None:
        """Apply vertical reflow and release compact-only width constraints."""
        for name in (
            "compose_radio_row_widget",
            "compose_guidance_row_widget",
            "compose_context_row_widget",
            "compose_js8_target_row_widget",
            "compose_js8_auth_row_widget",
            "compose_operator_row_widget",
            "compose_bbs_location_row_widget",
        ):
            widget = getattr(self, name, None)
            if isinstance(widget, QWidget):
                self._set_compose_row_reflow(widget, compact)
        for name in (
            "compose_radio_combo",
            "compose_js8_target_edit",
            "compose_js8_auth_key_combo",
            "compose_commstat_kind_combo",
            "compose_commstat_target_edit",
            "compose_commstat_grid_edit",
            "compose_commstat_scope_combo",
            "compose_commstat_report_id_edit",
            "compose_commstat_brevity_edit",
            "compose_commstat_comment_edit",
            "compose_form_combo",
            "compose_operating_group_combo",
            "compose_spotter_category_combo",
            "compose_family_combo",
        ):
            widget = getattr(self, name, None)
            if isinstance(widget, QWidget):
                self._set_compose_compact_width(widget, compact)
        # CommStat's grid is data-entry content, not a wide data surface.  Its
        # controls can yield their minimum widths to the setup viewport.
        commstat_layout = getattr(self, "compose_commstat_layout", None)
        if commstat_layout is not None:
            try:
                commstat_layout.activate()
            except Exception:
                pass
        setup_box = getattr(self, "compose_setup_box", None)
        if isinstance(setup_box, QWidget):
            # A translated label or a fixed-width child must not establish a
            # horizontal size for the setup rail.  Restore the authored floors
            # when the rail becomes wide again.
            for child in setup_box.findChildren(QWidget):
                if child is not setup_box:
                    self._set_compose_compact_width(child, compact)

    @staticmethod
    def _refresh_compose_content_floor(widget: QWidget) -> None:
        """Use the active layout's hint as a widget floor, without pixel caps."""
        layout = widget.layout()
        if layout is None:
            return
        try:
            widget.setMinimumHeight(0)
            layout.activate()
            floor = max(
                int(widget.minimumSizeHint().height()),
                int(widget.sizeHint().height()),
                int(layout.minimumSize().height()),
            )
            widget.setMinimumHeight(max(0, floor))
            widget.updateGeometry()
        except Exception:
            return

    def _on_compose_output_options_toggled(self, *_args) -> None:
        self._update_compose_preview()
        self._refresh_compose_layout_geometry_if_needed(force=True)

    def _reveal_compose_editor(self, *_args) -> None:
        """An explicit form choice advances to writing, without changing drafts."""
        def reveal() -> None:
            if self._is_shutting_down:
                return
            top = self.compose_field_box.mapTo(self.compose_body_splitter, QPoint(0, 0)).y()
            self.compose_workflow_scroll.verticalScrollBar().setValue(
                max(0, top - self.fontMetrics().lineSpacing())
            )
        QTimer.singleShot(0, reveal)

    def _arrange_compose_setup_choices(self, width: int) -> None:
        """Keep everyday setup short enough to expose the message itself."""
        roomy = width >= self.fontMetrics().horizontalAdvance("M") * 75
        signature = (roomy, self._compose_mode)
        if signature == getattr(self, "_compose_choice_layout_signature", None):
            return
        self._compose_choice_layout_signature = signature
        form = self.compose_form_row_widget.layout()
        # Remove items without destroying controls; both modes reuse this grid.
        while form.count():
            form.takeAt(0)
        pairs = [(self.compose_operating_group_label, self.compose_operating_group_combo),
                 (self.compose_spotter_category_label, self.compose_spotter_category_combo),
                 (self.compose_family_label, self.compose_family_combo),
                 (self.compose_form_label, self.compose_form_combo)]
        for label, control in pairs[:2]:
            form.addWidget(label, 0, 0)
            form.addWidget(control, 0, 1)
        if roomy and self._compose_mode == "nbems":
            form.addWidget(self.compose_family_label, 0, 2)
            form.addWidget(self.compose_family_combo, 0, 3)
            form.addWidget(self.compose_form_label, 1, 0)
            form.addWidget(self.compose_form_combo, 1, 1, 1, 3)
        elif roomy and self._compose_mode == "spotter":
            form.addWidget(self.compose_family_label, 1, 0)
            form.addWidget(self.compose_family_combo, 1, 1)
            form.addWidget(self.compose_form_label, 0, 2)
            form.addWidget(self.compose_form_combo, 0, 3)
        else:
            form.addWidget(self.compose_family_label, 1, 0)
            form.addWidget(self.compose_family_combo, 1, 1)
            form.addWidget(self.compose_form_label, 2, 0)
            form.addWidget(self.compose_form_combo, 2, 1)
        form.setColumnStretch(1, 1)
        form.setColumnStretch(3, 1 if roomy else 0)
        destinations = self.compose_nbems_dest_row_widget.layout()
        for widget in (self.compose_copy_varac_label, self.compose_varac_target_chip_container,
                       self.compose_sign_flamp_chk, self.compose_publish_bbs_chk):
            destinations.removeWidget(widget)
        destinations.addWidget(self.compose_copy_varac_label, 0 if roomy else 1, 2 if roomy else 0)
        destinations.addWidget(self.compose_varac_target_chip_container, 0 if roomy else 1, 3 if roomy else 1)
        destinations.addWidget(self.compose_sign_flamp_chk, 1 if roomy else 2, 1)
        destinations.addWidget(self.compose_publish_bbs_chk, 1 if roomy else 3, 3 if roomy else 1)
        destinations.setColumnStretch(3, 1 if roomy else 0)
        header = self.compose_header_row_widget.layout()
        header.removeWidget(self.compose_zulu_label)
        header.removeWidget(self.compose_zulu_value)
        header.removeWidget(self.compose_refresh_time_btn)
        header.addWidget(self.compose_zulu_label, 1 if roomy else 2, 2 if roomy else 0)
        header.addWidget(self.compose_zulu_value, 1 if roomy else 2, 3 if roomy else 1)
        header.addWidget(self.compose_refresh_time_btn, 2, 2)

    @staticmethod
    def _compose_natural_height(widget: QWidget, width: int) -> int:
        """Measure content at its assigned width, ignoring derived widget floors."""
        layout = widget.layout()
        if layout is None:
            return max(1, widget.sizeHint().height(), widget.minimumSizeHint().height())
        layout.invalidate()
        layout.activate()
        height = layout.sizeHint().height()
        if layout.hasHeightForWidth():
            height = max(1, layout.heightForWidth(max(1, width)))
        height = max(1, height, layout.minimumSize().height())
        if isinstance(widget, QGroupBox):
            margins = widget.contentsMargins()
            height += margins.top() + margins.bottom()
        return height

    def _refresh_compose_layout_geometry(self) -> None:
        if not hasattr(self, "compose_workflow_scroll"):
            return
        mode = str(getattr(self, "_compose_mode", "nbems") or "nbems")
        in_workbench = bool(getattr(self, "_compose_in_workbench", False))
        viewport = self.compose_workflow_scroll.viewport()
        width = max(1, viewport.width())
        sidebar = self._compose_sidebar_enabled(mode, width, in_workbench=in_workbench)
        self._refresh_compose_mode_selector_geometry()
        # Stack short setup rows only when their controls actually need it.
        self._arrange_compose_setup_choices(width if not sidebar else self._compose_sidebar_readable_minimum_width(mode, in_workbench=in_workbench))
        self._refresh_compose_responsive_setup(width < self.fontMetrics().horizontalAdvance("M") * 60)
        self._set_compose_row_reflow(self.compose_form_row_widget, False)
        self._set_compose_row_reflow(self.compose_header_row_widget, False)
        self._refresh_compose_commstat_content_geometry()
        setup = self.compose_setup_box
        rail = self._compose_sidebar_readable_minimum_width(mode, in_workbench=in_workbench)
        if mode == "spotter":
            rail = max(rail, self._compose_spotter_sidebar_width(width, in_workbench=in_workbench))
        setup_width = rail if sidebar else width
        setup_layout = setup.layout()
        row_heights = []
        for index in range(setup_layout.count()):
            row = setup_layout.itemAt(index).widget()
            if row is None or row.isHidden():
                continue
            row_height = self._compose_natural_height(row, max(1, setup_width - 16))
            row.setFixedHeight(row_height)
            row_heights.append(row_height)
        margins = setup_layout.contentsMargins()
        frame = setup.contentsMargins()
        setup_height = max(
            sum(row_heights) + max(0, len(row_heights) - 1) * setup_layout.spacing()
            + margins.top() + margins.bottom() + frame.top() + frame.bottom(),
            int(getattr(setup, "explicit_minimum_height", 0)),
        )
        setup.set_derived_minimum_height(setup_height)
        setup.setMaximumHeight(setup_height)
        self.compose_setup_scroll.setVerticalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        self.compose_setup_scroll.setFixedHeight(setup_height)

        # Local scroll wrappers remain for widget ownership/API compatibility;
        # they expose their natural content and never compete with the workflow.
        active_scroll = (
            self.compose_js8_plain_scroll if mode == "js8" else
            self.compose_commstat_scroll if mode == "commstat_rf" else
            self.compose_mesh_scroll if mode == "mesh" else self.compose_field_scroll
        )
        editor_width = max(1, width - rail) if sidebar else width
        if mode in {"nbems", "spotter"}:
            self._refresh_compose_form_field_geometry(editor_width)
        for scroll in (self.compose_field_scroll, self.compose_js8_plain_scroll,
                       self.compose_commstat_scroll, self.compose_mesh_scroll):
            scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
            scroll.setVerticalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        content = active_scroll.widget()
        editor_height = self._compose_natural_height(content, editor_width) if content is not None else 1
        editor_height = max(editor_height, self.fontMetrics().lineSpacing() * 8)
        active_scroll.setFixedHeight(editor_height)
        if mode in {"js8", "commstat_rf", "mesh"}:
            self.compose_rf_fields_stack.setFixedHeight(editor_height)
        else:
            self.compose_rf_fields_stack.setMinimumHeight(0)
            self.compose_rf_fields_stack.setMaximumHeight(16777215)
        field_height = editor_height + self.fontMetrics().lineSpacing() * 2
        self.compose_field_box.setFixedHeight(field_height)
        review_height = self.fontMetrics().lineSpacing() * 12
        self.compose_preview_box.setFixedHeight(review_height)
        self.compose_preview_box.setMinimumWidth(0)
        self.compose_splitter.setOrientation(Qt.Vertical)
        self.compose_splitter.setHandleWidth(0)
        self.compose_splitter.setFixedHeight(field_height + review_height)
        self._set_compose_splitter_sizes_if_needed(self.compose_splitter, [field_height, review_height])
        body = self.compose_body_splitter
        body.setOrientation(Qt.Horizontal if sidebar else Qt.Vertical)
        body.setHandleWidth(0)
        body_height = max(setup_height, field_height + review_height) if sidebar else setup_height + field_height + review_height
        body.setFixedHeight(body_height)
        if sidebar:
            self._set_compose_splitter_sizes_if_needed(body, [rail, max(1, width - rail)])
        else:
            self._set_compose_splitter_sizes_if_needed(body, [setup_height, field_height + review_height])
        self._refresh_compose_footer_geometry()

    def _refresh_compose_footer_geometry(self) -> None:
        self.compose_output_box.setMinimumHeight(0)
        self.compose_output_box.setMaximumHeight(16777215)
        footer_height = self._compose_natural_height(self.compose_output_box, self.compose_output_box.width())
        self.compose_output_box.setFixedHeight(footer_height)

    def _refresh_compose_form_field_geometry(self, width: int) -> None:
        """Publish wrapped field heights at the width actually available."""
        container = self.compose_field_scroll.widget()
        layout = container.layout() if container is not None else None
        if not isinstance(layout, QGridLayout):
            return
        comment = self._compose_field_widgets.get(SPOTTER_COMMENTS_KEY)
        if self._compose_mode == "spotter" and isinstance(comment, QTextEdit):
            comment.setFixedHeight(max(comment.minimumSizeHint().height(), comment.fontMetrics().lineSpacing() * 4))
        margins = layout.contentsMargins()
        available = max(1, width - margins.left() - margins.right())
        for index in range(layout.count()):
            widget = layout.itemAt(index).widget()
            if widget is None:
                continue
            _row, _column, _rows, columns = layout.getItemPosition(index)
            field_width = available if columns == 2 else max(1, (available - layout.horizontalSpacing()) // 2)
            widget.setMinimumHeight(0)
            child_layout = widget.layout()
            if child_layout is not None:
                widget.setMinimumHeight(self._compose_natural_height(widget, field_width))
            elif widget.hasHeightForWidth():
                widget.setMinimumHeight(max(widget.minimumSizeHint().height(), widget.heightForWidth(field_width)))

    def _compose_embedded_needs_workbench(self) -> bool:
        if bool(getattr(self, "_compose_in_workbench", False)):
            return False
        try:
            width = int(self.width() or 0)
            height = int(self.height() or 0)
        except Exception:
            width = 0
            height = 0
        return width < 1180 or height < 720 or self._messages_responsive_mode_for_width(width) == "compact"

    def _refresh_compose_workbench_button_style(self) -> None:
        btn = getattr(self, "compose_workbench_btn", None)
        if not isinstance(btn, QPushButton):
            return
        text = "Full Workbench"
        style = button_style("secondary", resolve_theme(self.settings))
        if btn.text() != text:
            btn.setText(text)
        if btn.styleSheet() != style:
            btn.setStyleSheet(style)
        btn.setToolTip("Open the same draft in a separate, larger composing window.")

    def _refresh_compose_layout_geometry_if_needed(self, *, force: bool = False) -> None:
        mode = str(getattr(self, "_compose_mode", "nbems") or "nbems")
        in_workbench = bool(getattr(self, "_compose_in_workbench", False))
        viewport = self._compose_layout_viewport()
        viewport_width = max(1, int(viewport.width() or 0))
        viewport_height = max(1, int(viewport.height() or 0))
        compact = viewport_width < (920 if in_workbench else int(self._responsive_compact_width))
        signature = (
            mode,
            in_workbench,
            compact,
            viewport_width,
            viewport_height,
            self.font().toString(),
            getattr(self, "_compose_active_form_key", ""),
            self.compose_output_options_btn.isChecked(),
            self.compose_spotter_source_hint.text(),
            getattr(self, "_compose_js8_selected_target_state", "unknown"),
            bool(getattr(getattr(self, "compose_commstat_brevity_chk", None), "isChecked", lambda: False)()),
            bool(getattr(getattr(self, "compose_sign_flamp_chk", None), "isChecked", lambda: False)()),
            bool(
                hasattr(self, "compose_publish_bbs_chk")
                and self.compose_publish_bbs_chk.isChecked()
            ),
        )
        self._refresh_compose_workbench_button_style()
        if not force and signature == getattr(self, "_compose_layout_signature", None):
            return
        self._compose_layout_signature = signature
        if getattr(self, "_compose_layout_refresh_pending", False):
            return
        self._compose_layout_refresh_pending = True
        QTimer.singleShot(0, self._run_pending_compose_layout_geometry_refresh)

    def _run_pending_compose_layout_geometry_refresh(self) -> None:
        if not getattr(self, "_compose_layout_refresh_pending", False):
            return
        self._compose_layout_refresh_pending = False
        if getattr(self, "_compose_layout_refresh_running", False):
            return
        requested_signature = getattr(self, "_compose_layout_signature", None)
        self._compose_layout_refresh_running = True
        started = time.perf_counter()
        try:
            self._refresh_compose_layout_geometry()
            self._refresh_compose_workbench_button_style()
        finally:
            self._compose_layout_refresh_running = False
            emit_span("compose.layout", (time.perf_counter() - started) * 1000,
                      settings=self.settings, min_ms=16.0, meta={"mode": self._compose_mode})
        # If a real viewport bucket or mode change arrived while the pass was
        # running, honor it once on the next event turn. Same-signature native
        # resize feedback is intentionally discarded.
        if requested_signature != getattr(self, "_compose_layout_signature", None):
            if not getattr(self, "_compose_layout_refresh_pending", False):
                self._compose_layout_refresh_pending = True
                QTimer.singleShot(0, self._run_pending_compose_layout_geometry_refresh)

    def _open_compose_workbench_dialog(self) -> None:
        existing = getattr(self, "_compose_workbench_dialog", None)
        if isinstance(existing, QDialog):
            try:
                existing.show()
                existing.raise_()
                existing.activateWindow()
            except Exception:
                pass
            return

        def refresh_for_workbench_resize() -> None:
            if (
                getattr(self, "_compose_workbench_dialog", None) is dialog
                and bool(getattr(self, "_compose_in_workbench", False))
            ):
                self._refresh_compose_layout_geometry_if_needed()

        dialog = _ResponsiveComposeWorkbenchDialog(self, refresh_for_workbench_resize)
        self._compose_workbench_dialog = dialog
        self._compose_in_workbench = True
        self._refresh_compose_splitter_handles()
        dialog.setWindowTitle("Compose Workbench")
        dialog.setModal(False)
        available = self._compose_workbench_available_geometry()
        usable_width = max(1, int(available.width()) - 24)
        usable_height = max(1, int(available.height()) - 24)
        # Keep the workbench inside the usable desktop even on a 900x560
        # reduced window. Its workflow scroll area owns overflow;
        # the dialog itself must never extend beyond screen controls.
        dialog.setMinimumSize(min(760, usable_width), min(500, usable_height))
        dialog.setMaximumSize(usable_width, usable_height)
        dialog.resize(min(1280, usable_width), min(820, usable_height))

        layout = QVBoxLayout(dialog)
        layout.setContentsMargins(10, 10, 10, 10)
        layout.setSpacing(8)
        for widget_name in ("compose_type_box", "compose_workflow_scroll", "compose_output_box"):
            widget = getattr(self, widget_name, None)
            if widget is not None:
                layout.addWidget(widget, 1 if widget_name == "compose_workflow_scroll" else 0)

        close_row = QHBoxLayout()
        close_row.addStretch()
        reset_btn = QPushButton("Reset Draft")
        reset_btn.setToolTip("Reset the current compose draft while keeping the selected radio.")
        reset_btn.clicked.connect(lambda: self._reset_compose_draft())
        close_row.addWidget(reset_btn)
        close_btn = QPushButton("Close Workbench")
        close_btn.clicked.connect(dialog.close)
        close_row.addWidget(close_btn)
        layout.addLayout(close_row)

        def restore_compose_widgets() -> None:
            self._compose_in_workbench = False
            self._refresh_compose_splitter_handles()
            root = getattr(self, "compose_root_layout", None)
            if root is not None:
                for index, widget_name in enumerate(("compose_type_box", "compose_workflow_scroll", "compose_output_box"), start=1):
                    widget = getattr(self, widget_name, None)
                    if widget is not None:
                        root.insertWidget(index, widget, 1 if widget_name == "compose_workflow_scroll" else 0)
                try:
                    root.invalidate()
                except Exception:
                    pass
            self._compose_workbench_dialog = None
            self._compose_layout_signature = None
            self._refresh_compose_layout_geometry_if_needed(force=True)
            if hasattr(self, "compose_page"):
                self.compose_page.updateGeometry()
                self.compose_page.update()
            QTimer.singleShot(0, lambda: self._refresh_compose_layout_geometry_if_needed(force=True))
            QTimer.singleShot(0, self._update_messages_responsive_layout)

        dialog.finished.connect(lambda _result: restore_compose_widgets())
        self._refresh_compose_layout_geometry_if_needed(force=True)
        dialog.show()

    def _compose_operator_callsign(self) -> str:
        return str(
            (self.settings.get("operator_callsign", "") or self.settings.get("callsign", "") or "")
        ).strip().upper()

    def _compose_operator_state(self) -> str:
        return str(self.settings.get("operator_state", "") or "").strip().upper()

    def _compose_operator_grid(self) -> str:
        return str(self.settings.get("operator_grid6", "") or "").strip().upper()

    def _compose_zulu_text(self) -> str:
        return format_compose_zulu(self._compose_timestamp_utc)

    def _compose_commstat_brevity_catalog_dirs(self) -> List[Path]:
        paths: List[Path] = []
        selected = self._selected_compose_radio_target() if getattr(self, "_compose_radio_targets_loaded", False) else None
        selected_path = selected.profile.get("commstat_launch_path", "") if selected else ""
        configured = [selected_path] if selected_path else [self.settings.get(key, "") for key in (
            "commstat_path", "commstat_app_path", "commstat_config_path", "path_commstat",
            "commstat_launch_path", "commstat3_db_path", "commstat_db_path")]
        base_raw = str(self.settings.get("radio_apps_base_folder", "") or "").strip()
        base_roots = [Path(base_raw).expanduser()] if base_raw else []
        base_roots.append(Path.home() / "RadioTools" / "Programs")
        candidates: List[str | Path] = list(configured)
        if not any(str(value or "").strip() for value in configured):
            for root in base_roots:
                candidates.extend((root / "commstat-5.0", root / "commstat-4.7", root / "CommStat"))
            candidates.append(Path.home() / "RadioTools" / "commstat-5.0")
        for raw in candidates:
            text = str(raw or "").strip()
            if not text:
                continue
            path = Path(text).expanduser()
            if path.suffix.lower() in {".py", ".exe", ".ini", ".db", ".db3", ".sh", ".cmd"}:
                path = path.parent
            if path not in paths:
                paths.append(path)
        return paths

    def _compose_commstat_brevity_options(self) -> List[str]:
        options = []
        for prefix, name, data in self._compose_commstat_brevity_catalogs():
            values = {}
            for field in model_fields(data):
                entries = section_entries(field_section(data, field, values))
                letters = [key for key, value in entries.items() if value["name"].strip().lower() != "reserved"]
                if not letters:
                    break
                values[field["key"]] = sorted(letters)[0]
            try:
                sample = encode_brevity_code(prefix, values, data)
            except ValueError:
                continue
            options.append(f"{sample} - {name}")
        return options

    def _populate_compose_commstat_brevity_options(self) -> None:
        combo = getattr(self, "compose_commstat_brevity_edit", None)
        if not isinstance(combo, QComboBox):
            return
        draft = combo.currentText()
        combo.blockSignals(True)
        try:
            combo.clear()
            combo.addItem("")
            for label in self._compose_commstat_brevity_options():
                combo.addItem(label)
            combo.setEditText(draft)
        finally:
            combo.blockSignals(False)

    def _compose_commstat_brevity_catalogs(self) -> List[Tuple[str, str, Dict[str, object]]]:
        if getattr(self, "_is_shutting_down", False):
            return []
        folders = tuple(str(path) for path in self._compose_commstat_brevity_catalog_dirs())
        cache = getattr(self, "_compose_brevity_read_cache", None)
        if cache is None:
            cache = self._compose_brevity_read_cache = LatestReadCache("fio-compose-brevity")
        def reader_factory():
            def read():
                catalogs, seen = [], set()
                for folder in folders:
                    for prefix, data in load_catalogs(folder).items():
                        version_key = (prefix, len(model_fields(data)))
                        if version_key in seen:
                            continue
                        seen.add(version_key)
                        catalogs.append((prefix, data["_fio_filename"], data))
                return catalogs
            return read
        result = cache.read(folders, reader_factory, refresh_after_s=10.0)
        timer = getattr(self, "_compose_brevity_poll", None)
        if timer is None:
            timer = self._compose_brevity_poll = QTimer(self)
            timer.timeout.connect(self._on_compose_brevity_catalog_ready)
        enabled = bool(getattr(getattr(self, "compose_commstat_brevity_chk", None), "isChecked", lambda: False)())
        if cache._future is not None or enabled:
            timer.setInterval(100 if cache._future is not None else 5000)
            if not timer.isActive():
                timer.start()
        else:
            timer.stop()
        return list(result or [])

    def _on_compose_brevity_catalog_ready(self) -> None:
        catalogs = self._compose_commstat_brevity_catalogs()
        signature = (tuple(str(path) for path in self._compose_commstat_brevity_catalog_dirs()),
                     tuple((prefix, name, data.get("_fio_fingerprint")) for prefix, name, data in catalogs))
        if signature == getattr(self, "_compose_brevity_published_signature", None):
            return
        self._compose_brevity_published_signature = signature
        self._populate_compose_commstat_brevity_options()
        self._populate_compose_commstat_brevity_builder()
        self._update_compose_preview()

    @staticmethod
    def _commstat_brevity_code_items(section: object) -> List[Tuple[str, str]]:
        return sorted((code, entry["name"]) for code, entry in section_entries(section).items()
                      if entry["name"].strip().lower() != "reserved")

    def _populate_commstat_brevity_combo(self, combo: QComboBox, section: object, placeholder: str) -> None:
        combo.blockSignals(True)
        try:
            combo.clear()
            combo.addItem(placeholder, "")
            for code, name in self._commstat_brevity_code_items(section):
                combo.addItem(f"{code} - {name}", code)
        finally:
            combo.blockSignals(False)

    def _populate_compose_commstat_brevity_builder(self) -> None:
        list_combo = getattr(self, "compose_commstat_brevity_list_combo", None)
        if not isinstance(list_combo, QComboBox):
            return
        previous = list_combo.currentData()
        old_catalogs = getattr(self, "_compose_commstat_brevity_catalog_cache", ())
        old_key = None
        if isinstance(previous, int) and 0 <= previous < len(old_catalogs):
            old_key = (old_catalogs[previous][0], old_catalogs[previous][1])
        catalogs = self._compose_commstat_brevity_catalogs()
        self._compose_commstat_brevity_catalog_cache = catalogs
        list_combo.blockSignals(True)
        try:
            list_combo.clear()
            list_combo.addItem("Select event list" if catalogs else "Definitions unavailable", None)
            selected = 0
            for idx, (prefix, name, data) in enumerate(catalogs):
                if model_fields(data):
                    list_combo.addItem(f"{prefix} - {name}", idx)
                    if (prefix, name) == old_key:
                        selected = list_combo.count() - 1
            list_combo.setCurrentIndex(selected or (1 if list_combo.count() > 1 else 0))
        finally:
            list_combo.blockSignals(False)
        self._on_compose_commstat_brevity_list_changed(refresh_preview=False)

    def _on_compose_commstat_brevity_list_changed(self, *_args, refresh_preview: bool = True) -> None:
        list_combo = getattr(self, "compose_commstat_brevity_list_combo", None)
        if not isinstance(list_combo, QComboBox):
            return
        idx = list_combo.currentData()
        catalogs = getattr(self, "_compose_commstat_brevity_catalog_cache", []) or []
        data: Dict[str, object] = {}
        if isinstance(idx, int) and 0 <= idx < len(catalogs):
            _prefix, _name, raw_data = catalogs[idx]
            data = raw_data if isinstance(raw_data, dict) else {}
        old_values = {key: combo.currentData() for key, combo in getattr(self, "_compose_brevity_field_combos", {}).items()}
        for widget in getattr(self, "_compose_brevity_field_widgets", ()):
            self._compose_brevity_field_layout.removeWidget(widget)
            widget.deleteLater()
        combos, widgets = {}, []
        for pos, field in enumerate(model_fields(data)):
            combo, label = QComboBox(), QLabel(field["label"])
            label.setTextFormat(Qt.PlainText)
            label.setWordWrap(True)
            combo.setSizeAdjustPolicy(QComboBox.AdjustToMinimumContentsLengthWithIcon)
            combo.setMinimumContentsLength(8)
            combo.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
            self._populate_commstat_brevity_combo(combo, field_section(data, field, old_values), f"Select {field['label']}")
            current = combo.findData(old_values.get(field["key"], ""))
            combo.setCurrentIndex(max(0, current))
            combo.currentIndexChanged.connect(self._on_compose_commstat_brevity_builder_changed)
            row, col = 1 + pos // 2, (pos % 2) * 2
            self._compose_brevity_field_layout.addWidget(label, row, col)
            self._compose_brevity_field_layout.addWidget(combo, row, col + 1)
            combos[field["key"]] = combo
            widgets.extend((label, combo))
        self._compose_brevity_field_combos = combos
        self._compose_brevity_field_widgets = widgets
        if refresh_preview:
            self._update_compose_preview()

    def _compose_commstat_brevity_builder_code(self) -> str:
        idx = self.compose_commstat_brevity_list_combo.currentData()
        catalogs = getattr(self, "_compose_commstat_brevity_catalog_cache", ())
        if not isinstance(idx, int) or not 0 <= idx < len(catalogs):
            return ""
        prefix, _, data = catalogs[idx]
        values = {key: combo.currentData() for key, combo in self._compose_brevity_field_combos.items()}
        try:
            return encode_brevity_code(prefix, values, data)
        except ValueError:
            return ""

    def _on_compose_commstat_brevity_builder_changed(self, *_args, refresh_preview: bool = True) -> None:
        idx = self.compose_commstat_brevity_list_combo.currentData()
        catalogs = getattr(self, "_compose_commstat_brevity_catalog_cache", ())
        if isinstance(idx, int) and 0 <= idx < len(catalogs):
            data = catalogs[idx][2]
            values = {key: combo.currentData() for key, combo in self._compose_brevity_field_combos.items()}
            for field in model_fields(data):
                if field["key"] == "impact":
                    combo = self._compose_brevity_field_combos[field["key"]]
                    previous = combo.currentData()
                    self._populate_commstat_brevity_combo(combo, field_section(data, field, values), f"Select {field['label']}")
                    combo.blockSignals(True)
                    combo.setCurrentIndex(max(0, combo.findData(previous)))
                    combo.blockSignals(False)
        code = self._compose_commstat_brevity_builder_code()
        combo = getattr(self, "compose_commstat_brevity_edit", None)
        if isinstance(combo, QComboBox) and code:
            combo.blockSignals(True)
            try:
                combo.setEditText(code)
            finally:
                combo.blockSignals(False)
        if refresh_preview:
            self._update_compose_preview()

    def _compose_commstat_brevity_code(self) -> str:
        combo = getattr(self, "compose_commstat_brevity_edit", None)
        if isinstance(combo, QComboBox):
            text = combo.currentText()
        elif combo is not None and hasattr(combo, "text"):
            text = combo.text()
        else:
            text = ""
        candidates = code_candidates(text)
        if not candidates:
            return ""
        code = candidates[0]
        for prefix, _, catalog in self._compose_commstat_brevity_catalogs():
            if prefix == code[0]:
                records = analyze_brevity_codes(code, {prefix: catalog})
                if records and records[0]["status"] == "decoded":
                    return code
        return ""

    def _on_compose_commstat_brevity_enabled_changed(self) -> None:
        if bool(getattr(getattr(self, "compose_commstat_brevity_chk", None), "isChecked", lambda: False)()):
            list_combo = getattr(self, "compose_commstat_brevity_list_combo", None)
            if isinstance(list_combo, QComboBox) and list_combo.count() <= 1:
                self._populate_compose_commstat_brevity_builder()
        self._update_compose_preview()

    def _compose_rf_target_text(self, value: object) -> str:
        return str(value or "").strip().upper().lstrip("@")

    @staticmethod
    def _compose_js8_transport_target(value: object, known_groups: Sequence[str] = ()) -> str:
        """Return the exact first JS8 transport hop for cue matching.

        Group identity is retained (including ``@``), callsign suffixes stay
        intact, and native ``RELAY>DEST`` syntax compares on ``RELAY`` rather
        than silently treating the final recipient as the selected endpoint.
        """
        text = str(value or "").strip().upper()
        if not text:
            return ""
        first_hop = text.split(">", 1)[0].strip()
        groups = {str(group).strip().upper().lstrip("@") for group in known_groups}
        return f"@{first_hop}" if first_hop in groups else first_hop

    def _compose_target_completion_values(self) -> List[str]:
        values: set[str] = set()
        known_groups: set[str] = set()

        def add_group(value: object) -> None:
            text = str(value or "").strip().upper().lstrip("@")
            if re.fullmatch(r"[A-Z0-9][A-Z0-9_-]{1,15}", text):
                values.add(text)
                known_groups.add(text)

        def add_call(value: object) -> None:
            raw = str(value or "").strip().upper()
            if raw.startswith("@"):
                add_group(raw)
                return
            text = self._compose_base_callsign(raw)
            if text in known_groups:
                return
            if text and text != self._compose_base_callsign(self._compose_operator_callsign()):
                values.add(text)

        configured_groups = self._configured_message_group_names()
        for group in configured_groups:
            add_group(group)
        try:
            group_state = load_commstat_group_state(self.settings)
            for group in [*group_state.active_groups, *group_state.configured_groups]:
                add_group(group)
        except Exception:
            pass
        for collection_name in ("js8_messages", "spotter_messages", "varac_messages", "sitrep_messages", "commstat_messages"):
            for msg in list(getattr(self, collection_name, []) or []):
                for attr in ("from_call", "to_call", "target", "report_group"):
                    value = getattr(msg, attr, "")
                    if attr in {"target", "report_group"} and self._is_message_group_candidate(value, configured_groups=configured_groups):
                        add_group(value)
                    else:
                        add_call(value)
        self._compose_target_known_groups = frozenset(known_groups)
        return sorted(values)

    def _install_compose_target_completers(self) -> None:
        values = self._compose_target_completion_values()
        signature = tuple(values)
        if getattr(self, "_compose_target_completer_signature", ()) == signature:
            return
        self._compose_target_completer_signature = signature
        for widget_name in ("compose_js8_target_edit", "compose_commstat_target_edit"):
            widget = getattr(self, widget_name, None)
            if not isinstance(widget, QLineEdit):
                continue
            completer = QCompleter(values, widget)
            completer.setCaseSensitivity(Qt.CaseInsensitive)
            completer.setCompletionMode(QCompleter.PopupCompletion)
            try:
                completer.setFilterMode(Qt.MatchContains)
            except Exception:
                pass
            widget.setCompleter(completer)

    def _compose_blank_field_rows(self) -> List[ComposeFieldDefinition]:
        return standard_blank_field_definitions()

    @staticmethod
    def _spotter_form_number(form_code: object) -> int:
        match = re.search(r"(\d{3})", str(form_code or ""))
        if not match:
            return 0
        try:
            return int(match.group(1))
        except Exception:
            return 0

    def _spotter_form_category_key(self, form_code: object, title: object = "") -> str:
        num = self._spotter_form_number(form_code)
        purpose = str(factory_mapping_for_form(form_code, title).get("purpose", "") or "")
        if 100 <= num <= 199:
            return "100"
        if 300 <= num <= 399:
            return "300"
        if 500 <= num <= 599:
            return "500"
        if 700 <= num <= 799:
            return "700"
        if purpose:
            return purpose
        return "other"

    def _spotter_form_category_label(self, key: str) -> str:
        labels = {
            "all": "All Forms",
            "100": "100-199 Informational",
            "300": "300-399 Situation Reports",
            "500": "500-599 Supply / Weather",
            "700": "700-799 Group / Net",
            "other": "Other Forms",
        }
        return labels.get(str(key or ""), str(key or "Other Forms"))

    @staticmethod
    def _spotter_forms_dir_usable(path_text: object) -> str:
        text = str(path_text or "").strip()
        if not text:
            return ""
        path = Path(text).expanduser()
        try:
            if path.exists() and path.is_dir() and any(path.glob("MCF*.txt")):
                return str(path)
        except Exception:
            return ""
        return ""

    def _compose_spotter_forms_path(self, target: Optional[ComposeRadioTarget] = None) -> str:
        radio = target or self._selected_compose_radio_target()
        legacy = ""
        if radio is not None:
            legacy = (
                self._compose_profile_text(radio.profile, "js8_forms_path")
                or self._compose_profile_text(radio.profile, "forms_path")
            )
        global_path = str(self.settings.get("js8_forms_path", self.forms_path) or "").strip()
        return choose_effective_spotter_forms_catalog(global_path, legacy).path

    def _clear_spotter_form_caches(self) -> None:
        self._form_cache.clear()
        self._form_title_cache.clear()

    def _compose_family_entries(self) -> List[dict]:
        return list(getattr(self, "_compose_family_entries_cache", []) or [])

    def _refresh_spotter_category_options(self, forms: Sequence[object]) -> None:
        if not hasattr(self, "compose_spotter_category_combo"):
            return
        previous = self.compose_spotter_category_combo.currentData()
        categories: List[str] = ["all"]
        for form in forms:
            key = self._spotter_form_category_key(
                getattr(form, "form_code", ""),
                getattr(form, "title", ""),
            )
            if key and key not in categories:
                categories.append(key)
        ordered = [
            key
            for key in ("all", "100", "300", "500", "700")
            if key in categories
        ] + sorted(
            [key for key in categories if key not in {"all", "100", "300", "500", "700"}],
            key=lambda value: self._spotter_form_category_label(value).lower(),
        )
        self.compose_spotter_category_combo.blockSignals(True)
        try:
            self.compose_spotter_category_combo.clear()
            selected_index = 0
            for key in ordered:
                self.compose_spotter_category_combo.addItem(self._spotter_form_category_label(key), key)
                if previous and str(previous) == key:
                    selected_index = self.compose_spotter_category_combo.count() - 1
            if self.compose_spotter_category_combo.count():
                self.compose_spotter_category_combo.setCurrentIndex(selected_index)
        finally:
            self.compose_spotter_category_combo.blockSignals(False)

    def _on_compose_spotter_category_changed(self) -> None:
        data = self.compose_family_combo.currentData() if hasattr(self, "compose_family_combo") else None
        if isinstance(data, dict) and data.get("kind") == "spotter":
            self._populate_spotter_form_combo(list(data.get("forms") or []))

    def _populate_spotter_form_combo(self, forms: Sequence[object]) -> None:
        if not hasattr(self, "compose_form_combo"):
            return
        selected_category = "all"
        if hasattr(self, "compose_spotter_category_combo") and self.compose_spotter_category_combo.count():
            selected_category = str(self.compose_spotter_category_combo.currentData() or "all")
        filtered: List[object] = []
        for form in forms:
            key = self._spotter_form_category_key(getattr(form, "form_code", ""), getattr(form, "title", ""))
            if selected_category == "all" or key == selected_category:
                filtered.append(form)
        self.compose_form_combo.blockSignals(True)
        try:
            self.compose_form_combo.clear()
            if filtered:
                source_dirs = [Path(str(getattr(form, "path", "") or "")).parent for form in filtered if getattr(form, "path", "")]
                self._compose_last_source_dir = source_dirs[0] if source_dirs else self._compose_last_source_dir
                for form in filtered:
                    code = str(getattr(form, "form_code", "") or "").strip()
                    title = str(getattr(form, "title", "") or "").strip()
                    label = f"{code} - {title}" if title else code
                    self.compose_form_combo.addItem(
                        label,
                        {
                            "kind": "spotter_form",
                            "code": code,
                            "title": title,
                            "path": str(getattr(form, "path", "") or ""),
                        },
                    )
            else:
                self.compose_form_combo.addItem("No MCF forms in this category", None)
        finally:
            self.compose_form_combo.blockSignals(False)
        requested = str(getattr(self, "_compose_spotter_requested_form_code", "") or "").strip().upper()
        if requested:
            self._select_compose_spotter_form_code(requested, forms=forms)
        self._on_compose_form_changed()

    def _select_compose_spotter_form_code(
        self,
        form_code: object,
        *,
        forms: Sequence[object] | None = None,
    ) -> bool:
        """Select a handoff form from already-loaded Compose catalog data."""
        code = str(form_code or "").strip().upper()
        if not code or not hasattr(self, "compose_form_combo"):
            return False
        catalog = list(forms or [])
        if not catalog:
            family_data = self.compose_family_combo.currentData() if hasattr(self, "compose_family_combo") else None
            if isinstance(family_data, dict) and family_data.get("kind") == "spotter":
                catalog = list(family_data.get("forms") or [])
        matched = next(
            (form for form in catalog if str(getattr(form, "form_code", "") or "").strip().upper() == code),
            None,
        )
        if matched is not None and hasattr(self, "compose_spotter_category_combo"):
            category = self._spotter_form_category_key(
                getattr(matched, "form_code", ""), getattr(matched, "title", "")
            )
            category_index = self.compose_spotter_category_combo.findData(category)
            if category_index >= 0 and self.compose_spotter_category_combo.currentIndex() != category_index:
                self.compose_spotter_category_combo.setCurrentIndex(category_index)
        for index in range(self.compose_form_combo.count()):
            data = self.compose_form_combo.itemData(index)
            if isinstance(data, dict) and str(data.get("code", "") or "").strip().upper() == code:
                self.compose_form_combo.setCurrentIndex(index)
                self._compose_spotter_requested_form_code = ""
                return True
        return False

    @staticmethod
    def _compose_spotter_expect_response_parts(response: object, expect_key: object) -> tuple[str, str]:
        """Return ``(optional target, response without target)`` for a saved row.

        Expect responses are normally target-neutral (the destination is
        supplied by the requesting station), but older/imported rows may carry
        a destination prefix.  Keep that prefix out of the response command so
        the normal Compose target and guarded-send path remain authoritative.
        """
        text = " ".join(str(response or "").strip().split())
        key = str(expect_key or "").strip().upper()
        if not text or not key:
            return "", text
        tokens = text.split()
        key_index = -1
        for idx, token in enumerate(tokens[:3]):
            if token.upper() == key:
                key_index = idx
                break
        if key_index < 0:
            return "", text
        target = ""
        if key_index > 0:
            candidate = tokens[0].strip().upper()
            if candidate.startswith("@") or re.fullmatch(r"[A-Z]{1,2}\d[A-Z0-9]{1,5}(?:/[A-Z0-9]{1,4})?", candidate):
                target = candidate
        return target, " ".join(tokens[key_index:]).strip()

    @staticmethod
    def _compose_spotter_saved_values(
        response: object,
        expect_key: object,
        fields: Sequence[ComposeFieldDefinition],
    ) -> Dict[str, str]:
        """Decode choices, bracket prompts, and Comments as one round trip."""
        codec_fields = [
            SpotterFormField(
                key=field.key,
                label=field.label,
                options=tuple(
                    (str(option.value or ""), str(option.label or option.value or ""))
                    for option in field.options
                    if str(option.value or "")
                ),
                # Prompt rows also carry an empty placeholder option. Only
                # actual selectors consume compact answer tokens.
                kind="choice" if field.field_type == "select" else "prompt",
            )
            for field in fields
            if field.key != SPOTTER_COMMENTS_KEY
        ]
        parsed = parse_spotter_form_payload(
            response,
            codec_fields,
            expected_form_code=expect_key,
        )
        return {str(key): str(value or "") for key, value in parsed.values.items()}

    def _refresh_compose_spotter_expect_entries(self, *, force: bool = False) -> None:
        """Load at most 200 static Expect rows on activation/explicit refresh."""
        if self._compose_spotter_expect_loaded and not force:
            return
        try:
            rows = list_expect_entries(enabled_only=False, limit=200)
        except Exception as exc:
            log.debug("MessageViewer: failed loading saved Spotter Expect responses: %s", exc)
            rows = []
        bounded: List[Dict[str, object]] = []
        seen: set[tuple[str, str, str]] = set()
        for raw in rows:
            if not isinstance(raw, Mapping):
                continue
            key = str(raw.get("expect_key", "") or "").strip().upper()
            response = str(raw.get("response_text", "") or "").strip()
            # Dynamic Q is request-derived and has no generic manual payload.
            # All other static Expect responses can serve as saved messages;
            # MCForms additionally receive send-time date refresh below.
            if not key or key == "Q" or not response:
                continue
            identity = (str(raw.get("id", "") or ""), key, response)
            if identity in seen:
                continue
            seen.add(identity)
            bounded.append(dict(raw))
            if len(bounded) >= 200:
                break
        self._compose_spotter_expect_entries = bounded
        self._compose_spotter_expect_loaded = True
        self._apply_compose_spotter_source_options()

    def _apply_compose_spotter_source_options(self) -> None:
        combo = getattr(self, "compose_spotter_source_combo", None)
        if not isinstance(combo, QComboBox):
            return
        active_id = int(getattr(self, "_compose_spotter_expect_active_id", 0) or 0)
        combo.blockSignals(True)
        try:
            combo.clear()
            combo.addItem("Form catalog — new response", {"kind": "catalog"})
            selected = 0
            for row in self._compose_spotter_expect_entries:
                key = str(row.get("expect_key", "") or "").strip().upper()
                summary = " ".join(str(row.get("response_text", "") or "").split())
                if len(summary) > 56:
                    summary = summary[:53].rstrip() + "…"
                label = f"{key} — {summary}" if summary else key
                combo.addItem(label, {"kind": "saved_expect", "entry": dict(row)})
                try:
                    if int(row.get("id", 0) or 0) == active_id:
                        selected = combo.count() - 1
                except (TypeError, ValueError):
                    pass
            combo.setCurrentIndex(selected)
        finally:
            combo.blockSignals(False)

    def _refresh_compose_spotter_expect_entries_clicked(self) -> None:
        self._refresh_compose_spotter_expect_entries(force=True)
        self._set_compose_status("Saved Spotter responses refreshed. Select one to copy it into the draft.", role="info")
        self._update_compose_preview()

    def _clear_compose_spotter_working_response(self) -> None:
        self._compose_spotter_expect_active_id = 0
        self._compose_spotter_working_response = ""
        self._compose_spotter_working_response_dirty = False
        self._compose_spotter_decode_notice = ""
        self._compose_expect_view_editing = True
        apply_view_state = getattr(self, "_apply_compose_expect_view_state", None)
        if callable(apply_view_state):
            apply_view_state()

    def _expect_view_is_read_only(self) -> bool:
        intent = dict(getattr(self, "_compose_intent", {}) or {})
        return bool(
            intent.get("expect_view", False)
            and int(getattr(self, "_compose_spotter_expect_active_id", 0) or 0) > 0
            and not bool(getattr(self, "_compose_expect_view_editing", True))
        )

    def _apply_compose_expect_view_state(self) -> None:
        """Apply the explicit View/Edit boundary without rebuilding the form."""
        read_only = self._expect_view_is_read_only()
        for widget in (getattr(self, "_compose_field_widgets", {}) or {}).values():
            if isinstance(widget, (QLineEdit, QTextEdit, QPlainTextEdit)):
                widget.setReadOnly(read_only)
            elif isinstance(widget, QComboBox):
                widget.setEnabled(not read_only)
        if hasattr(self, "compose_edit_expect_copy_btn"):
            self.compose_edit_expect_copy_btn.setVisible(read_only)

    def _begin_editing_expect_copy(self) -> None:
        """Make an Expect View editable locally; this does not persist it."""
        self._compose_expect_view_editing = True
        apply_view_state = getattr(self, "_apply_compose_expect_view_state", None)
        if callable(apply_view_state):
            apply_view_state()
        if hasattr(self, "compose_spotter_source_hint"):
            self.compose_spotter_source_hint.setText(
                "Editing a local working copy. Access policy and automation remain unchanged until you explicitly save."
            )
        self._set_compose_status(
            "Working-copy editing enabled. Expect storage has not changed.",
            role="info",
        )
        self._update_compose_preview()

    def _queue_compose_spotter_scroll_reset(self) -> None:
        """Reset the Spotter setup scroll once after an activation/change.

        The queued turn lets the stacked page and splitter finish laying out
        before setting the scrollbar value.  A pending flag makes a mode/source
        cascade (which can rebuild the form) produce one reset, while ordinary
        preview and typing paths never call this method.
        """
        if str(getattr(self, "_compose_mode", "nbems") or "nbems") != "spotter":
            return
        if not hasattr(self, "compose_workflow_scroll"):
            return
        if bool(getattr(self, "_compose_spotter_scroll_reset_pending", False)):
            return
        self._compose_spotter_scroll_reset_pending = True
        QTimer.singleShot(0, self._run_compose_spotter_scroll_reset)

    def _run_compose_spotter_scroll_reset(self) -> None:
        self._compose_spotter_scroll_reset_pending = False
        if str(getattr(self, "_compose_mode", "nbems") or "nbems") != "spotter":
            return
        scroll = getattr(self, "compose_workflow_scroll", None)
        if scroll is None:
            return
        try:
            scroll.verticalScrollBar().setValue(0)
        except Exception:
            pass

    def _begin_compose_update(self) -> None:
        """Defer derived preview/layout work during one logical draft change."""

        self._compose_update_depth = max(0, int(getattr(self, "_compose_update_depth", 0) or 0)) + 1

    def _end_compose_update(self, *, flush: bool) -> None:
        depth = max(0, int(getattr(self, "_compose_update_depth", 0) or 0) - 1)
        self._compose_update_depth = depth
        if depth > 0:
            return
        pending = bool(getattr(self, "_compose_preview_update_pending", False))
        self._compose_preview_update_pending = False
        if flush and pending:
            self._update_compose_preview()

    def _on_compose_spotter_source_changed(self, *_args) -> bool:
        MessageViewerTab._begin_compose_update(self)
        completed = False
        try:
            MessageViewerTab._apply_compose_spotter_source_changed(self, *_args)
            completed = True
        except Exception as exc:
            log.exception("MessageViewer: failed loading saved Spotter working copy: %s", exc)
            self._set_compose_status(
                "This saved response could not be loaded completely. "
                "Choose it again or start a new CommsPlan Spotter draft.",
                role="warning",
            )
        finally:
            # A malformed or unavailable saved form must never leave Compose
            # permanently suppressing previews or carrying a loading flag.
            self._compose_spotter_source_loading = False
            MessageViewerTab._end_compose_update(self, flush=completed)
        return completed

    def _apply_compose_spotter_source_changed(self, *_args) -> None:
        combo = getattr(self, "compose_spotter_source_combo", None)
        data = combo.currentData() if isinstance(combo, QComboBox) else None
        if not isinstance(data, dict) or data.get("kind") != "saved_expect":
            self._clear_compose_spotter_working_response()
            if hasattr(self, "compose_spotter_source_hint"):
                self.compose_spotter_source_hint.setText("New response from the form catalog.")
            self._update_compose_preview()
            self._queue_compose_spotter_scroll_reset()
            return
        entry = dict(data.get("entry") or {})
        expect_key = str(entry.get("expect_key", "") or "").strip().upper()
        response = str(entry.get("response_text", "") or "").strip()
        self._compose_spotter_source_loading = True
        try:
            self._compose_spotter_expect_active_id = int(entry.get("id", 0) or 0)
        except (TypeError, ValueError):
            self._compose_spotter_expect_active_id = 0
        self._compose_spotter_working_response = response
        self._compose_spotter_working_response_dirty = False
        self._compose_spotter_decode_notice = ""
        view_intent = bool(dict(getattr(self, "_compose_intent", {}) or {}).get("expect_view", False))
        self._compose_expect_view_editing = not view_intent
        try:
            target, _body = self._compose_spotter_expect_response_parts(response, expect_key)
            if target and hasattr(self, "compose_js8_target_edit"):
                self.compose_js8_target_edit.setText(target)
            form_combo = getattr(self, "compose_form_combo", None)
            selected_index = -1
            if isinstance(form_combo, QComboBox):
                for idx in range(form_combo.count()):
                    item = form_combo.itemData(idx)
                    if isinstance(item, dict) and str(item.get("code", "") or "").strip().upper() == expect_key:
                        selected_index = idx
                        break
                if selected_index >= 0:
                    form_combo.setCurrentIndex(selected_index)
            values = self._compose_spotter_saved_values(response, expect_key, self._compose_field_rows)
            for key, value in values.items():
                self._compose_set_widget_value(key, value)
            if not self._compose_field_rows:
                self._compose_spotter_decode_notice = (
                    "The MCF form is not available in the current catalog. "
                    "The exact saved payload is retained for viewing and sending."
                )
            elif len(values) < len(self._compose_field_rows):
                self._compose_spotter_decode_notice = (
                    "Some saved fields could not be reconstructed safely. "
                    "The exact saved payload is retained; editing will create a new form payload."
                )
        finally:
            self._compose_spotter_source_loading = False
        if hasattr(self, "compose_spotter_source_hint"):
            hint = (
                f"Viewing the exact saved {expect_key} response; Expect storage is unchanged."
                if view_intent else
                f"Copied {expect_key} as an editable working copy; Expect policy is unchanged."
            )
            if self._compose_spotter_decode_notice:
                hint += f" {self._compose_spotter_decode_notice}"
            self.compose_spotter_source_hint.setText(hint)
        apply_view_state = getattr(self, "_apply_compose_expect_view_state", None)
        if callable(apply_view_state):
            apply_view_state()
        self._update_compose_preview()
        self._queue_compose_spotter_scroll_reset()

    def _on_compose_mode_tab_changed(self, index: int) -> None:
        with perf_span("compose.mode_switch", settings=self.settings, min_ms=16.0, meta={"index": index}):
            self._apply_compose_mode_tab_changed(index)

    def _apply_compose_mode_tab_changed(self, index: int) -> None:
        previous_mode = str(getattr(self, "_compose_mode", "nbems") or "nbems")
        positions = getattr(self, "_compose_workflow_positions", {})
        positions[previous_mode] = self.compose_workflow_scroll.verticalScrollBar().value()
        self._compose_workflow_positions = positions
        self._store_compose_form_draft()
        self._store_compose_mode_draft(previous_mode)
        idx = int(index or 0)
        self._compose_mode = (
            "js8" if idx == 1 else
            "spotter" if idx == 2 else
            "commstat_rf" if idx == 3 else
            "mesh" if idx == 4 else
            "nbems"
        )
        self._invalidate_compose_mesh_contact()
        self._compose_active_form_key = ""
        self._compose_last_stage_paths = []
        self._compose_radio_targets_loaded = False
        self._compose_restoring_mode_draft = True
        try:
            if self._compose_mode == "commstat_rf":
                self._refresh_compose_commstat_defaults()
            elif self._compose_mode == "spotter":
                self._refresh_compose_spotter_expect_entries()
            self._refresh_compose_setup_discovery(force=True)
            self._refresh_compose_forms()
            self._restore_compose_mode_draft(self._compose_mode)
        finally:
            self._compose_restoring_mode_draft = False
        self._update_compose_preview()
        self._queue_compose_spotter_scroll_reset()
        self._refresh_compose_js8_selected_target_cue()
        self.request_compose_js8_selected_target_refresh()
        selected_mode = self._compose_mode
        position = self._compose_workflow_positions.get(selected_mode, 0)
        QTimer.singleShot(0, lambda: self.compose_workflow_scroll.verticalScrollBar().setValue(position)
                          if self._compose_mode == selected_mode and not self._is_shutting_down else None)

    def _refresh_compose_mesh_targets(self, *, force: bool = False) -> None:
        """Single-flight discovery; keep the coherent previous model while loading."""
        self._compose_mesh_generation = int(getattr(self, "_compose_mesh_generation", 0)) + 1
        thread = getattr(self, "_compose_mesh_thread", None)
        if thread is not None and self._qt_thread_running(thread):
            self._compose_mesh_pending = True
            return
        self.compose_send_mesh_btn.setEnabled(False)
        self.compose_mesh_hint_label.setText("Loading mesh connections…")
        self._compose_mesh_loading = True
        for control in (self.compose_mesh_source_combo, self.compose_mesh_channel_combo,
                        self.compose_mesh_node_combo, self.compose_mesh_destination_kind_combo):
            control.setEnabled(False)
        thread = QThread(self)
        worker = _ComposeMeshDiscoveryWorker(
            self._compose_mesh_generation, dict(self.settings.all()), default_mesh_db_path()
        )
        self._compose_mesh_thread, self._compose_mesh_worker = thread, worker
        worker.moveToThread(thread)
        thread.started.connect(worker.run)
        worker.finished.connect(self._on_compose_mesh_discovered)
        worker.finished.connect(thread.quit)
        worker.finished.connect(worker.deleteLater)
        thread.finished.connect(self._on_compose_mesh_thread_finished)
        thread.finished.connect(thread.deleteLater)
        thread.start()

    def _on_compose_mesh_thread_finished(self) -> None:
        self._retain_finished_worker_refs(self._compose_mesh_thread, self._compose_mesh_worker)
        self._compose_mesh_thread = self._compose_mesh_worker = None
        if getattr(self, "_compose_mesh_pending", False) and not self._is_shutting_down:
            self._compose_mesh_pending = False
            pending_intent = getattr(self, "_compose_mesh_pending_intent", None)
            current_generation = self._compose_mesh_generation
            self._refresh_compose_mesh_targets(force=True)
            if pending_intent and pending_intent[0] == current_generation:
                self._compose_mesh_pending_intent = (self._compose_mesh_generation, pending_intent[1])

    def _on_compose_mesh_discovered(self, payload: object) -> None:
        if (self._is_shutting_down or not isinstance(payload, dict)
                or payload.get("generation") != getattr(self, "_compose_mesh_generation", 0)):
            return
        self._compose_mesh_loading = False
        for control in (self.compose_mesh_source_combo, self.compose_mesh_channel_combo,
                        self.compose_mesh_node_combo, self.compose_mesh_destination_kind_combo):
            control.setEnabled(True)
        if self._compose_mode != "mesh":
            return
        combo = self.compose_mesh_source_combo
        current = combo.currentData()
        previous_id = str(getattr(current, "adapter_id", "") or "")
        previous_channel = self.compose_mesh_channel_combo.currentData()
        previous_node = self.compose_mesh_node_combo.currentData()
        configs = payload.get("configs", [])
        health_by_adapter = payload.get("health", {})
        self._compose_mesh_destinations = payload.get("destinations", {})
        self._compose_mesh_configs = list(configs)
        self._compose_mesh_health_by_adapter = health_by_adapter
        self._compose_mesh_favorites_by_adapter = {
            str(adapter_id): tuple(tuple(identity) for identity in identities or () if isinstance(identity, (tuple, list)) and len(identity) == 4)
            for adapter_id, identities in dict(payload.get("favorites", {}) or {}).items()
        }
        blocked = combo.blockSignals(True)
        try:
            combo.clear()
            if not configs:
                combo.addItem("No send-enabled mesh connection", None)
            for config in configs:
                health = health_by_adapter.get(config.adapter_id, {})
                state = "Connected" if bool(health.get("connected")) else "Offline"
                label = f"{config.display_name} · {config.protocol.title()} · {state}"
                combo.addItem(label, config)
            selected_index = 0
            for index in range(combo.count()):
                item = combo.itemData(index)
                if previous_id and str(getattr(item, "adapter_id", "") or "") == previous_id:
                    selected_index = index
                    break
            combo.setCurrentIndex(selected_index)
        finally:
            combo.blockSignals(blocked)
        self._on_compose_mesh_source_changed()
        self._compose_set_combo_data(self.compose_mesh_channel_combo, previous_channel)
        self._compose_set_combo_data(self.compose_mesh_node_combo, previous_node)
        pending = getattr(self, "_compose_mesh_pending_intent", None)
        if pending and pending[0] == payload.get("generation"):
            self._compose_mesh_pending_intent = None
            data = pending[1]
            adapter_id = str(data.get("adapter_id") or "")
            if adapter_id:
                index = next((i for i in range(combo.count())
                              if str(getattr(combo.itemData(i), "adapter_id", "")) == adapter_id), -1)
                combo.setCurrentIndex(index)
            kind = str(data.get("destination_kind") or ("direct" if data.get("destination_id") else "channel"))
            self._compose_set_combo_data(self.compose_mesh_destination_kind_combo, kind)
            for control, key in ((self.compose_mesh_channel_combo, "channel_id"),
                                 (self.compose_mesh_node_combo, "destination_id")):
                value = str(data.get(key) or (data.get("node_id") if key == "destination_id" else "") or "")
                if value:
                    control.setCurrentIndex(control.findData(value))
            self._on_compose_mesh_destination_changed()
        if payload.get("error"):
            self.compose_mesh_hint_label.setText("Could not load mesh connections. Refresh to retry.")

    def _selected_compose_mesh_config(self):
        combo = getattr(self, "compose_mesh_source_combo", None)
        return combo.currentData() if isinstance(combo, QComboBox) else None

    def _on_compose_mesh_source_changed(self, *_args) -> None:
        self._invalidate_compose_mesh_contact()
        config = self._selected_compose_mesh_config()
        channel_combo = getattr(self, "compose_mesh_channel_combo", None)
        node_combo = getattr(self, "compose_mesh_node_combo", None)
        if not isinstance(channel_combo, QComboBox) or not isinstance(node_combo, QComboBox):
            return
        channel_combo.blockSignals(True)
        node_combo.blockSignals(True)
        try:
            channel_combo.clear()
            node_combo.clear()
            if config is None:
                channel_combo.addItem("No reviewed channel available", None)
                node_combo.addItem("No known node available", None)
            else:
                policies, nodes = getattr(self, "_compose_mesh_destinations", {}).get(config.adapter_id, ([], []))
                for policy in policies:
                    if str(policy.review_state or "").lower() != "accepted":
                        continue
                    if str(policy.channel_role or "").lower() == "direct":
                        continue
                    if str(policy.key_state or "").lower() in {"missing", "needed", "unknown"} and str(policy.channel_privacy or "").lower() not in {"public", "open"}:
                        continue
                    channel_combo.addItem(f"{policy.channel_name} · channel {policy.channel_id}", str(policy.channel_id))
                if not channel_combo.count():
                    channel_combo.addItem("No reviewed channel available", None)

                for node in nodes:
                    node_id = str(node.get("node_id") or "").strip()
                    public_key = str(node.get("public_key_or_hash") or "").strip()
                    destination_id = public_key if str(config.protocol).lower() == "meshcore" else node_id
                    if not destination_id:
                        continue
                    display = str(node.get("callsign") or node.get("short_name") or node.get("long_name") or node_id).strip()
                    suffix = destination_id[:12]
                    node_combo.addItem(f"{display} · {suffix}", destination_id)
                    if str(config.protocol).lower() == "meshcore":
                        identity = (str(config.adapter_id or ""), "meshcore", node_id, public_key.lower())
                        node_index = node_combo.count() - 1
                        node_combo.setItemData(node_index, identity, Qt.UserRole + 1)
                        node_combo.setItemData(node_index, display, Qt.UserRole + 2)
                        node_combo.setItemText(node_index, self._compose_mesh_contact_node_label(node_index))
                if not node_combo.count():
                    node_combo.addItem("No known node available", None)
        finally:
            channel_combo.blockSignals(False)
            node_combo.blockSignals(False)
        self._on_compose_mesh_destination_changed()

    def _on_compose_mesh_destination_changed(self, *_args) -> None:
        self._invalidate_compose_mesh_contact()
        kind = str(self._compose_combo_data(getattr(self, "compose_mesh_destination_kind_combo", None)) or "channel")
        config = self._selected_compose_mesh_config()
        meshtastic_direct = bool(
            kind == "direct" and str(getattr(config, "protocol", "") or "").strip().lower() == "meshtastic"
        )
        channel = getattr(self, "compose_mesh_channel_combo", None)
        node = getattr(self, "compose_mesh_node_combo", None)
        ack = getattr(self, "compose_mesh_ack_chk", None)
        if isinstance(channel, QComboBox):
            channel.setVisible(kind == "channel" or meshtastic_direct)
        if isinstance(node, QComboBox):
            node.setVisible(kind == "direct")
        if isinstance(ack, QCheckBox):
            ack.setVisible(kind == "direct")
        self._update_compose_preview()

    def _on_compose_mesh_contact_selection_changed(self, *_args) -> None:
        """Fence contact reads before repainting a newly selected node."""
        self._invalidate_compose_mesh_contact()
        self._update_compose_preview()

    def _selected_compose_mesh_contact_identity(self) -> tuple[str, str, str, str] | None:
        """Return only the exact MeshCore identity attached to the selected node item."""
        config = self._selected_compose_mesh_config()
        if config is None or str(getattr(config, "protocol", "") or "").lower() != "meshcore":
            return None
        kind = str(self._compose_combo_data(getattr(self, "compose_mesh_destination_kind_combo", None)) or "channel")
        if kind != "direct":
            return None
        combo = getattr(self, "compose_mesh_node_combo", None)
        if not isinstance(combo, QComboBox):
            return None
        raw = combo.itemData(combo.currentIndex(), Qt.UserRole + 1)
        if not isinstance(raw, (tuple, list)) or len(raw) != 4:
            return None
        if str(raw[0] or "").strip() != str(getattr(config, "adapter_id", "") or "").strip():
            return None
        if str(raw[1] or "").strip().lower() != str(getattr(config, "protocol", "") or "").strip().lower():
            return None
        return contact_identity(*raw)

    def _compose_mesh_contact_is_favorite(self, identity: tuple[str, str, str, str] | None) -> bool:
        if identity is None:
            return False
        return identity in tuple(self._compose_mesh_favorites_by_adapter.get(identity[0], ()) or ())

    def _compose_mesh_contact_node_label(self, index: int) -> str:
        combo = getattr(self, "compose_mesh_node_combo", None)
        if not isinstance(combo, QComboBox):
            return ""
        display = str(combo.itemData(index, Qt.UserRole + 2) or "").strip()
        destination = str(combo.itemData(index) or "").strip()
        identity = combo.itemData(index, Qt.UserRole + 1)
        is_favorite = self._compose_mesh_contact_is_favorite(tuple(identity) if isinstance(identity, (tuple, list)) else None)
        prefix = "★ " if is_favorite else ""
        node_id = str(identity[2] or "").strip() if isinstance(identity, (tuple, list)) and len(identity) == 4 else ""
        suffix = " · ".join(part for part in (node_id, destination[:12]) if part)
        return f"{prefix}{display} · {suffix}" if display and suffix else display or suffix

    def _refresh_compose_mesh_contact_node_labels(self) -> None:
        combo = getattr(self, "compose_mesh_node_combo", None)
        if not isinstance(combo, QComboBox):
            return
        blocked = combo.blockSignals(True)
        try:
            for index in range(combo.count()):
                if combo.itemData(index, Qt.UserRole + 1) is not None:
                    combo.setItemText(index, self._compose_mesh_contact_node_label(index))
        finally:
            combo.blockSignals(blocked)

    def _update_compose_mesh_contact_controls(self) -> None:
        history = getattr(self, "compose_mesh_contact_history_btn", None)
        favorite = getattr(self, "compose_mesh_contact_favorite_btn", None)
        row = getattr(self, "compose_mesh_contact_action_row", None)
        if not all(isinstance(widget, QWidget) for widget in (history, favorite, row)):
            return
        identity = self._selected_compose_mesh_contact_identity()
        eligible = bool(identity is not None and str(getattr(self, "_compose_mode", "") or "") == "mesh")
        pending = bool(getattr(self, "_compose_mesh_contact_pending", {}))
        row.setVisible(eligible)
        history.setEnabled(eligible and not pending)
        favorite.setEnabled(eligible and not pending)
        if eligible:
            is_favorite = self._compose_mesh_contact_is_favorite(identity)
            favorite.setText("Remove favorite" if is_favorite else "Add favorite")
            favorite.setToolTip(
                "Remove this exact MeshCore adapter, node, and full public-key identity from operator favorites."
                if is_favorite else
                "Save this exact MeshCore adapter, node, and full public-key identity as an operator favorite."
            )

    def _invalidate_compose_mesh_contact(self) -> None:
        self._compose_mesh_contact_generation = int(getattr(self, "_compose_mesh_contact_generation", 0)) + 1
        self._compose_mesh_contact_pending = {}
        lane = getattr(self, "_compose_mesh_contact_lane", None)
        if lane is not None:
            lane.invalidate()
        dialog = getattr(self, "_compose_mesh_contact_dialog", None)
        if isinstance(dialog, QDialog):
            dialog.close()
        status = getattr(self, "compose_mesh_contact_status_label", None)
        if isinstance(status, QLabel):
            status.setText("")
        self._update_compose_mesh_contact_controls()

    def _request_compose_mesh_contact(self, *, favorite: bool | None, action: str) -> None:
        identity = self._selected_compose_mesh_contact_identity()
        if (
            identity is None
            or self._is_shutting_down
            or not bool(getattr(self, "_has_active_view", False))
            or str(getattr(self, "_compose_mode", "") or "") != "mesh"
            or bool(getattr(self, "_compose_mesh_contact_pending", {}))
        ):
            return
        lane = getattr(self, "_compose_mesh_contact_lane", None)
        if lane is None:
            return
        db_path = default_mesh_db_path()
        generation = lane.request(db_path, identity, favorite=favorite)
        self._compose_mesh_contact_generation = int(generation)
        self._compose_mesh_contact_pending = {
            "generation": int(generation),
            "identity": identity,
            "action": str(action),
        }
        self.compose_mesh_contact_status_label.setText(
            "Saving MeshCore favorite…" if favorite is not None else "Reading bounded contact history…"
        )
        self._update_compose_mesh_contact_controls()

    def _inspect_compose_mesh_contact(self) -> None:
        self._request_compose_mesh_contact(favorite=None, action="history")

    def _toggle_compose_mesh_favorite(self) -> None:
        identity = self._selected_compose_mesh_contact_identity()
        if identity is None:
            return
        self._request_compose_mesh_contact(
            favorite=not self._compose_mesh_contact_is_favorite(identity),
            action="favorite",
        )

    def _show_compose_mesh_contact_snapshot(self, snapshot: ContactSnapshot) -> None:
        existing = getattr(self, "_compose_mesh_contact_dialog", None)
        if isinstance(existing, QDialog):
            existing.close()
        dialog = QDialog(self)
        dialog.setWindowTitle("MeshCore contact history")
        dialog.setModal(False)
        dialog.setAttribute(Qt.WA_DeleteOnClose, True)
        layout = QVBoxLayout(dialog)
        identity = snapshot.identity or ("", "", "", "")
        identity_label = QLabel(f"Adapter {identity[0]} · Node {identity[2]} · Key {identity[3]}")
        identity_label.setTextFormat(Qt.PlainText)
        identity_label.setWordWrap(True)
        layout.addWidget(identity_label)
        browser = QTextBrowser(dialog)
        browser.setOpenExternalLinks(False)
        lines = [
            "Exact retained contact history (up to 50 rows)",
            f"Favorite: {'Yes' if snapshot.favorite else 'No'}",
            "Contact-list matching is evidence of the observed identity, not sender authentication.",
            "A favorite does not grant trust or send permission.",
        ]
        if snapshot.coverage:
            lines.append(f"Coverage: {snapshot.coverage}")
        if snapshot.error:
            lines.append(f"Status: {snapshot.error}")
        if snapshot.history:
            lines.append("")
            for row in snapshot.history[:50]:
                lines.append(f"{row.received_utc} · {row.summary} · {row.canonical_key}")
        else:
            lines.append("No retained exact-identity history is available.")
        browser.setPlainText("\n".join(lines))
        layout.addWidget(browser, 1)
        buttons = QDialogButtonBox(QDialogButtonBox.Close, parent=dialog)
        buttons.setStyleSheet(button_style("secondary", resolve_theme(self.settings)))
        buttons.rejected.connect(dialog.close)
        layout.addWidget(buttons)
        line_height = max(1, dialog.fontMetrics().lineSpacing())
        width = max(520, min(900, dialog.fontMetrics().horizontalAdvance("0") * 110))
        height = max(320, min(700, line_height * 24 + buttons.sizeHint().height() + line_height * 4))
        dialog.resize(width, height)
        dialog.finished.connect(lambda *_args, current=dialog: self._clear_compose_mesh_contact_dialog(current))
        self._compose_mesh_contact_dialog = dialog
        dialog.show()

    def _clear_compose_mesh_contact_dialog(self, dialog: QDialog) -> None:
        if getattr(self, "_compose_mesh_contact_dialog", None) is dialog:
            self._compose_mesh_contact_dialog = None

    def _on_compose_mesh_contact_ready(self, generation: int, result: object) -> None:
        pending = dict(getattr(self, "_compose_mesh_contact_pending", {}) or {})
        if self._is_shutting_down or not pending or int(generation) != int(pending.get("generation", 0) or 0):
            return
        identity = pending.get("identity")
        current = self._selected_compose_mesh_contact_identity()
        if not isinstance(identity, tuple) or current != identity:
            self._compose_mesh_contact_pending = {}
            self._update_compose_mesh_contact_controls()
            return
        self._compose_mesh_contact_pending = {}
        if not isinstance(result, ContactSnapshot) or result.identity != identity:
            self.compose_mesh_contact_status_label.setText("MeshCore contact evidence is unavailable.")
            self._update_compose_mesh_contact_controls()
            return
        favorite_saved = getattr(result, "favorite_saved", None)
        favorite_commit_confirmed = favorite_saved is True
        if pending.get("action") == "favorite" and favorite_commit_confirmed:
            adapter = identity[0]
            existing = [item for item in self._compose_mesh_favorites_by_adapter.get(adapter, ()) if tuple(item) != identity]
            if result.favorite:
                existing.append(identity)
            self._compose_mesh_favorites_by_adapter[adapter] = tuple(existing)
            self._refresh_compose_mesh_contact_node_labels()
            self.compose_mesh_contact_status_label.setText(
                (
                    "MeshCore favorite saved; contact history is unavailable for this profile."
                    if result.error and result.favorite
                    else "MeshCore favorite saved." if result.favorite
                    else "MeshCore favorite removed."
                )
            )
        elif pending.get("action") == "history":
            if favorite_saved is True:
                adapter = identity[0]
                existing = [item for item in self._compose_mesh_favorites_by_adapter.get(adapter, ()) if tuple(item) != identity]
                if result.favorite:
                    existing.append(identity)
                self._compose_mesh_favorites_by_adapter[adapter] = tuple(existing)
                self._refresh_compose_mesh_contact_node_labels()
            self._show_compose_mesh_contact_snapshot(result)
            self.compose_mesh_contact_status_label.setText(
                (
                    "MeshCore favorite saved; contact history is unavailable for this profile."
                    if favorite_saved is True and result.error
                    else "Contact history loaded." if not result.error
                    else "Contact history is unavailable for this profile."
                )
            )
        elif result.error:
            self.compose_mesh_contact_status_label.setText(result.error)
        elif pending.get("action") == "favorite":
            self.compose_mesh_contact_status_label.setText("Favorite change was not confirmed. Refresh to review retained preferences.")
        self._update_compose_mesh_contact_controls()

    def _compose_mesh_request(self) -> MeshSendRequest | None:
        config = self._selected_compose_mesh_config()
        if config is None:
            return None
        kind = str(self._compose_combo_data(getattr(self, "compose_mesh_destination_kind_combo", None)) or "channel")
        channel_id = str(self._compose_combo_data(getattr(self, "compose_mesh_channel_combo", None)) or "")
        destination_id = str(self._compose_combo_data(getattr(self, "compose_mesh_node_combo", None)) or "")
        text_widget = getattr(self, "compose_mesh_text_edit", None)
        text = text_widget.toPlainText() if isinstance(text_widget, QTextEdit) else ""
        protocol = str(getattr(config, "protocol", "") or "").strip().lower()
        if (
            not text.strip()
            or (kind == "channel" and not channel_id)
            or (kind == "direct" and not destination_id)
            or (kind == "direct" and protocol == "meshtastic" and not channel_id)
        ):
            return None
        return MeshSendRequest(
            adapter_id=config.adapter_id,
            text=text,
            destination_kind=kind,
            destination_id=destination_id if kind == "direct" else "",
            channel_id=channel_id if kind == "channel" or protocol == "meshtastic" else "0",
            require_ack=bool(kind == "direct" and getattr(self, "compose_mesh_ack_chk", None).isChecked()),
        )

    def _send_compose_mesh_message(self) -> None:
        if getattr(self, "_compose_mesh_loading", False):
            self._set_compose_status("Wait for mesh connection verification before sending.", role="warning")
            return
        if self._compose_mesh_send_inflight:
            self._set_compose_status("A mesh send is already in progress.", role="info")
            return
        request = self._compose_mesh_request()
        config = self._selected_compose_mesh_config()
        if request is None or config is None:
            self._set_compose_status("Choose a connected mesh connection, destination, and message before sending.", role="warning")
            return
        health = self._compose_mesh_health_by_adapter.get(config.adapter_id, {})
        if not bool(health.get("connected")):
            self._set_compose_status("Connect the selected Local Mesh device before sending.", role="warning")
            return
        destination = (
            self.compose_mesh_node_combo.currentText()
            if request.destination_kind == "direct"
            else self.compose_mesh_channel_combo.currentText()
        )
        if request.destination_kind == "direct" and str(config.protocol).lower() == "meshtastic":
            destination = f"{destination} via {self.compose_mesh_channel_combo.currentText()}"
        answer = QMessageBox.question(
            self,
            "Send Mesh Message",
            f"Send through {config.display_name} to {destination}?\n\n{request.text}",
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No,
        )
        if answer != QMessageBox.Yes:
            self._set_compose_status("Mesh send cancelled.", role="info")
            return
        self._compose_mesh_send_inflight = True
        self._compose_mesh_request_id = request.request_id
        self._set_compose_status("Sending through the selected mesh connection…", role="info")
        self._update_compose_preview()
        self.meshSendRequested.emit(request)

    def on_mesh_send_result(self, result: object) -> None:
        if not isinstance(result, MeshSendResult):
            return
        if self._compose_mesh_request_id and result.request_id != self._compose_mesh_request_id:
            return
        self._compose_mesh_send_inflight = False
        self._compose_mesh_request_id = ""
        if result.accepted:
            evidence = {
                "acked": "Acknowledged by the destination node",
                "sent": "Completed by the mesh Companion",
                "accepted": "Accepted by the local mesh API",
            }.get(result.state, "Accepted")
            self._set_compose_status(f"{evidence}. {result.detail}".strip(), role="success")
        elif result.state == "cancelled":
            self._set_compose_status(f"Mesh send cancelled: {result.detail}", role="warning")
        else:
            self._set_compose_status(f"Mesh send failed: {result.detail}", role="warning")
        self._update_compose_preview()

    def on_mesh_health_ready(self, health: object) -> None:
        """Refresh Compose gating from the live worker without polling during render."""

        adapter_id = str(getattr(health, "adapter_id", "") or "").strip()
        if not adapter_id:
            return
        self._compose_mesh_health_by_adapter[adapter_id] = {
            "adapter_id": adapter_id,
            "connected": bool(getattr(health, "connected", False)),
            "transport": str(getattr(health, "transport", "") or ""),
            "last_error": str(getattr(health, "last_error", "") or ""),
        }
        combo = getattr(self, "compose_mesh_source_combo", None)
        if isinstance(combo, QComboBox):
            for index in range(combo.count()):
                config = combo.itemData(index)
                if str(getattr(config, "adapter_id", "") or "") != adapter_id:
                    continue
                state = "Connected" if bool(getattr(health, "connected", False)) else "Offline"
                combo.setItemText(
                    index,
                    f"{config.display_name} · {str(config.protocol).title()} · {state}",
                )
                break
        if str(getattr(self, "_compose_mode", "") or "") == "mesh":
            self._update_compose_preview()

    @staticmethod
    def _compose_combo_text(combo: object) -> str:
        return combo.currentText() if isinstance(combo, QComboBox) else ""

    @staticmethod
    def _compose_combo_data(combo: object) -> object:
        return combo.currentData() if isinstance(combo, QComboBox) else None

    @staticmethod
    def _compose_set_combo_text(combo: object, value: object) -> None:
        if not isinstance(combo, QComboBox):
            return
        index = combo.findText(str(value or ""))
        if index < 0:
            return
        blocked = combo.blockSignals(True)
        try:
            combo.setCurrentIndex(index)
        finally:
            combo.blockSignals(blocked)

    @staticmethod
    def _compose_set_combo_data(combo: object, value: object) -> None:
        if not isinstance(combo, QComboBox):
            return
        index = combo.findData(value)
        if index < 0:
            return
        blocked = combo.blockSignals(True)
        try:
            combo.setCurrentIndex(index)
        finally:
            combo.blockSignals(blocked)

    @staticmethod
    def _compose_set_line_text(widget: object, value: object) -> None:
        if not isinstance(widget, QLineEdit):
            return
        blocked = widget.blockSignals(True)
        try:
            widget.setText(str(value or ""))
        finally:
            widget.blockSignals(blocked)

    @staticmethod
    def _compose_set_checked(widget: object, checked: object) -> None:
        if not isinstance(widget, QCheckBox):
            return
        blocked = widget.blockSignals(True)
        try:
            widget.setChecked(bool(checked))
        finally:
            widget.blockSignals(blocked)

    def _compose_current_form_identity(self) -> str:
        combo = getattr(self, "compose_form_combo", None)
        return self._compose_form_identity(combo.currentData()) if isinstance(combo, QComboBox) else ""

    def _compose_store_mode_form_identity(self, draft: Dict[str, object]) -> None:
        draft["form_identity"] = self._compose_current_form_identity()

    def _store_compose_mode_draft(self, mode: str) -> None:
        """Retain widgets shared by Compose modes without persisting user drafts."""
        mode = str(mode or "nbems")
        draft: Dict[str, object] = {}
        if mode == "nbems":
            family_data = self._compose_combo_data(getattr(self, "compose_family_combo", None))
            bbs_selector = getattr(self, "compose_bbs_location_selector", None)
            draft = {
                "group": self._compose_combo_data(getattr(self, "compose_operating_group_combo", None)),
                "family_key": str(family_data.get("key", "") if isinstance(family_data, dict) else ""),
                "priority": self._compose_combo_text(getattr(self, "compose_priority_combo", None)),
                "report_title": getattr(getattr(self, "compose_report_title_edit", None), "text", lambda: "")(),
                "send_target": self._compose_combo_text(getattr(self, "compose_send_target_combo", None)),
                "varac_target": self._compose_combo_text(getattr(self, "compose_varac_target_combo", None)),
                "publish_bbs": bool(getattr(getattr(self, "compose_publish_bbs_chk", None), "isChecked", lambda: False)()),
                "bbs_targets": sorted(bbs_selector.selected_values())
                if isinstance(bbs_selector, DropdownChecklist)
                else [],
                "sign_flamp": bool(getattr(getattr(self, "compose_sign_flamp_chk", None), "isChecked", lambda: False)()),
                "signing_key": self._compose_combo_data(getattr(self, "compose_signing_key_combo", None)),
            }
            self._compose_store_mode_form_identity(draft)
        elif mode == "js8":
            draft = {
                "target": getattr(getattr(self, "compose_js8_target_edit", None), "text", lambda: "")(),
                "kind": self._compose_combo_text(getattr(self, "compose_js8_plain_kind_combo", None)),
                "text": getattr(getattr(self, "compose_js8_plain_text_edit", None), "toPlainText", lambda: "")(),
                "send_as_msg": bool(getattr(getattr(self, "compose_js8_send_as_msg_chk", None), "isChecked", lambda: False)()),
            }
        elif mode == "spotter":
            draft = {
                "target": getattr(getattr(self, "compose_js8_target_edit", None), "text", lambda: "")(),
                "category": self._compose_combo_data(getattr(self, "compose_spotter_category_combo", None)),
                "expect_active_id": int(getattr(self, "_compose_spotter_expect_active_id", 0) or 0),
                "sign": bool(getattr(getattr(self, "compose_js8_sign_chk", None), "isChecked", lambda: False)()),
                "date_code": bool(getattr(getattr(self, "compose_js8_auth_datecode_chk", None), "isChecked", lambda: False)()),
                "auth_key": self._compose_combo_data(getattr(self, "compose_js8_auth_key_combo", None)),
                "send_as_msg": bool(getattr(getattr(self, "compose_js8_send_as_msg_chk", None), "isChecked", lambda: False)()),
            }
            self._compose_store_mode_form_identity(draft)
        elif mode == "commstat_rf":
            draft = {
                "target": getattr(getattr(self, "compose_commstat_target_edit", None), "text", lambda: "")(),
                "grid": getattr(getattr(self, "compose_commstat_grid_edit", None), "text", lambda: "")(),
                "scope": self._compose_combo_data(getattr(self, "compose_commstat_scope_combo", None)),
                "report_id": getattr(getattr(self, "compose_commstat_report_id_edit", None), "text", lambda: "")(),
                "comment": getattr(getattr(self, "compose_commstat_comment_edit", None), "text", lambda: "")(),
                "brevity": bool(getattr(getattr(self, "compose_commstat_brevity_chk", None), "isChecked", lambda: False)()),
                "brevity_code": self._compose_combo_text(getattr(self, "compose_commstat_brevity_edit", None)),
                "status": {
                    key: self._compose_combo_text(combo)
                    for key, combo in (getattr(self, "compose_commstat_status_widgets", {}) or {}).items()
                },
                "brevity_builder": {
                    name: self._compose_combo_data(getattr(self, name, None))
                    for name in (
                        "compose_commstat_brevity_list_combo",
                        "compose_commstat_brevity_event_combo",
                        "compose_commstat_brevity_status_combo",
                        "compose_commstat_brevity_impact_combo",
                        "compose_commstat_brevity_public_combo",
                        "compose_commstat_brevity_station_combo",
                    )
                },
            }
        elif mode == "mesh":
            config = self._selected_compose_mesh_config()
            draft = {
                "adapter_id": str(getattr(config, "adapter_id", "") or ""),
                "destination_kind": self._compose_combo_data(getattr(self, "compose_mesh_destination_kind_combo", None)),
                "channel_id": self._compose_combo_data(getattr(self, "compose_mesh_channel_combo", None)),
                "destination_id": self._compose_combo_data(getattr(self, "compose_mesh_node_combo", None)),
                "require_ack": bool(getattr(getattr(self, "compose_mesh_ack_chk", None), "isChecked", lambda: False)()),
                "text": getattr(getattr(self, "compose_mesh_text_edit", None), "toPlainText", lambda: "")(),
            }
        self._compose_mode_drafts[mode] = draft

    def _restore_compose_form_identity(self, identity: object) -> None:
        if not identity or not hasattr(self, "compose_form_combo"):
            return
        for index in range(self.compose_form_combo.count()):
            if self._compose_form_identity(self.compose_form_combo.itemData(index)) == identity:
                blocked = self.compose_form_combo.blockSignals(True)
                try:
                    self.compose_form_combo.setCurrentIndex(index)
                finally:
                    self.compose_form_combo.blockSignals(blocked)
                self._on_compose_form_changed()
                return

    def _restore_compose_mode_draft(self, mode: str) -> None:
        draft = dict(self._compose_mode_drafts.get(str(mode or "nbems"), {}) or {})
        if not draft:
            if mode in {"js8", "spotter"}:
                self._compose_set_checked(getattr(self, "compose_js8_send_as_msg_chk", None), False)
            return
        if mode == "nbems":
            self._compose_set_combo_data(getattr(self, "compose_operating_group_combo", None), draft.get("group"))
            self._refresh_compose_forms()
            family_key = str(draft.get("family_key", "") or "")
            if family_key and hasattr(self, "compose_family_combo"):
                for index in range(self.compose_family_combo.count()):
                    data = self.compose_family_combo.itemData(index)
                    if isinstance(data, dict) and str(data.get("key", "") or "") == family_key:
                        blocked = self.compose_family_combo.blockSignals(True)
                        try:
                            self.compose_family_combo.setCurrentIndex(index)
                        finally:
                            self.compose_family_combo.blockSignals(blocked)
                        self._on_compose_family_changed()
                        break
            self._restore_compose_form_identity(draft.get("form_identity"))
            self._compose_set_combo_text(getattr(self, "compose_priority_combo", None), draft.get("priority"))
            self._compose_set_line_text(getattr(self, "compose_report_title_edit", None), draft.get("report_title"))
            self._compose_set_combo_text(getattr(self, "compose_send_target_combo", None), draft.get("send_target"))
            self._compose_set_combo_text(getattr(self, "compose_varac_target_combo", None), draft.get("varac_target"))
            self._compose_set_checked(getattr(self, "compose_publish_bbs_chk", None), draft.get("publish_bbs"))
            if bool(draft.get("publish_bbs")):
                self._refresh_compose_bbs_location_targets()
            bbs_selector = getattr(self, "compose_bbs_location_selector", None)
            if isinstance(bbs_selector, DropdownChecklist):
                valid_ids = {str(target.get("location_id", "") or "") for target in self._compose_bbs_targets_cache}
                selected_ids = [
                    str(value or "") for value in list(draft.get("bbs_targets", []) or [])
                    if str(value or "") in valid_ids
                ]
                blocked = bbs_selector.blockSignals(True)
                try:
                    bbs_selector.set_selected_values(selected_ids)
                finally:
                    bbs_selector.blockSignals(blocked)
            self._compose_set_checked(getattr(self, "compose_sign_flamp_chk", None), draft.get("sign_flamp"))
            self._compose_set_combo_data(getattr(self, "compose_signing_key_combo", None), draft.get("signing_key"))
        elif mode == "js8":
            self._compose_set_line_text(getattr(self, "compose_js8_target_edit", None), draft.get("target"))
            self._compose_set_combo_text(getattr(self, "compose_js8_plain_kind_combo", None), draft.get("kind"))
            widget = getattr(self, "compose_js8_plain_text_edit", None)
            if isinstance(widget, QTextEdit):
                blocked = widget.blockSignals(True)
                try:
                    widget.setPlainText(str(draft.get("text", "") or ""))
                finally:
                    widget.blockSignals(blocked)
            self._compose_set_checked(getattr(self, "compose_js8_send_as_msg_chk", None), draft.get("send_as_msg"))
        elif mode == "spotter":
            self._compose_set_line_text(getattr(self, "compose_js8_target_edit", None), draft.get("target"))
            active_id = int(draft.get("expect_active_id", 0) or 0)
            source_combo = getattr(self, "compose_spotter_source_combo", None)
            if isinstance(source_combo, QComboBox) and active_id > 0:
                for index in range(source_combo.count()):
                    data = source_combo.itemData(index)
                    entry = data.get("entry") if isinstance(data, dict) else None
                    try:
                        if isinstance(entry, dict) and int(entry.get("id", 0) or 0) == active_id:
                            source_combo.setCurrentIndex(index)
                            break
                    except (TypeError, ValueError):
                        continue
            self._compose_set_combo_data(getattr(self, "compose_spotter_category_combo", None), draft.get("category"))
            self._on_compose_spotter_category_changed()
            self._restore_compose_form_identity(draft.get("form_identity"))
            self._compose_set_checked(getattr(self, "compose_js8_sign_chk", None), draft.get("sign"))
            self._compose_set_checked(getattr(self, "compose_js8_auth_datecode_chk", None), draft.get("date_code"))
            self._compose_set_combo_data(getattr(self, "compose_js8_auth_key_combo", None), draft.get("auth_key"))
            self._compose_set_checked(getattr(self, "compose_js8_send_as_msg_chk", None), draft.get("send_as_msg"))
        elif mode == "commstat_rf":
            for widget_name, key in (
                ("compose_commstat_target_edit", "target"),
                ("compose_commstat_grid_edit", "grid"),
                ("compose_commstat_report_id_edit", "report_id"),
                ("compose_commstat_comment_edit", "comment"),
            ):
                self._compose_set_line_text(getattr(self, widget_name, None), draft.get(key))
            self._compose_set_combo_data(getattr(self, "compose_commstat_scope_combo", None), draft.get("scope"))
            self._compose_set_checked(getattr(self, "compose_commstat_brevity_chk", None), draft.get("brevity"))
            self._compose_set_combo_text(getattr(self, "compose_commstat_brevity_edit", None), draft.get("brevity_code"))
            for key, value in dict(draft.get("status", {}) or {}).items():
                self._compose_set_combo_text((getattr(self, "compose_commstat_status_widgets", {}) or {}).get(key), value)
            for name, value in dict(draft.get("brevity_builder", {}) or {}).items():
                self._compose_set_combo_data(getattr(self, name, None), value)
        elif mode == "mesh":
            source_combo = getattr(self, "compose_mesh_source_combo", None)
            adapter_id = str(draft.get("adapter_id") or "")
            if isinstance(source_combo, QComboBox) and adapter_id:
                for index in range(source_combo.count()):
                    config = source_combo.itemData(index)
                    if str(getattr(config, "adapter_id", "") or "") == adapter_id:
                        source_combo.setCurrentIndex(index)
                        break
            self._compose_set_combo_data(
                getattr(self, "compose_mesh_destination_kind_combo", None),
                draft.get("destination_kind"),
            )
            self._on_compose_mesh_source_changed()
            self._compose_set_combo_data(getattr(self, "compose_mesh_channel_combo", None), draft.get("channel_id"))
            self._compose_set_combo_data(getattr(self, "compose_mesh_node_combo", None), draft.get("destination_id"))
            self._compose_set_checked(getattr(self, "compose_mesh_ack_chk", None), draft.get("require_ack"))
            widget = getattr(self, "compose_mesh_text_edit", None)
            if isinstance(widget, QTextEdit):
                blocked = widget.blockSignals(True)
                try:
                    widget.setPlainText(str(draft.get("text") or ""))
                finally:
                    widget.blockSignals(blocked)

    def _refresh_compose_setup_discovery(self, *, force: bool = False) -> None:
        """Refresh setup-only sources outside local payload preview updates.

        This is intentionally synchronous for the current slice.  It is called
        only for explicit mode/radio/group/target setup changes; the primary
        responsiveness layer can replace these calls with cached worker results
        without changing payload rendering or action behavior.
        """
        mode = str(getattr(self, "_compose_mode", "nbems") or "nbems")
        if mode == "mesh":
            self._refresh_compose_mesh_targets(force=force)
            return
        self._refresh_compose_radio_targets(force=force)
        self._refresh_compose_message_folder_options(force=force)
        self._refresh_compose_destination_plans()
        self._install_compose_target_completers()
        bbs_selected = bool(
            mode == "nbems"
            and hasattr(self, "compose_publish_bbs_chk")
            and self.compose_publish_bbs_chk.isChecked()
        )
        if bbs_selected:
            self._refresh_compose_bbs_location_targets()
        if self._compose_sign_flamp_selected():
            self._refresh_compose_signing_keys(force=force)
        self._start_compose_target_guidance_worker()

    @staticmethod
    def _compose_js8_selected_target_modes() -> tuple[str, ...]:
        return ("js8", "spotter", "commstat_rf")

    def _compose_js8_selected_target_is_active(self) -> bool:
        return str(getattr(self, "_compose_mode", "nbems") or "nbems") in self._compose_js8_selected_target_modes()

    def _compose_js8_selected_target_endpoint_key(self, radio_target: Optional[ComposeRadioTarget]) -> str:
        """Return the UI's stable endpoint hint without opening or probing an endpoint."""
        if radio_target is None:
            return ""
        endpoint = js8_endpoint_from_radio_profile(
            radio_target.profile,
            fallback_settings=getattr(self, "settings", None),
        )
        return f"radio:{radio_target.radio_id}|endpoint:{endpoint.host}:{endpoint.port}"

    def _cancel_compose_js8_selected_target_worker(self) -> None:
        worker = getattr(self, "_compose_js8_selected_target_worker", None)
        if worker is not None:
            try:
                worker.cancel()
            except Exception:
                pass

    def compose_js8_selected_target_request_context(
        self,
        *,
        action: str = "refresh",
        expected_target: object = None,
    ) -> Optional[Dict[str, object]]:
        """Snapshot a selected-target lookup request for the endpoint worker.

        The caller must return this exact generation, radio ID, and endpoint
        identity to :meth:`apply_compose_js8_selected_target_result`; stale
        results are ignored by the UI.
        """
        action = str(action or "refresh").strip().lower()
        if action not in {"refresh", "clear"}:
            return None
        if action == "clear" and not str(expected_target or "").strip():
            return None
        # Cancel first, even when the new mode has no JS8 target surface. This
        # closes the navigation/shutdown fence before the active-mode checks.
        self._cancel_compose_js8_selected_target_worker()
        if not self._compose_js8_selected_target_is_active():
            return None
        radio_target = self._selected_compose_radio_target()
        if radio_target is None or "JS8Call" not in tuple(radio_target.capabilities):
            return None
        # A radio/mode/navigation change fences any queued clear before it can
        # reach the endpoint helper.  The worker's cancellation callback is
        # also checked immediately before the setter and during readback.
        self._compose_js8_selected_target_generation += 1
        self._compose_js8_selected_target_radio_id = int(radio_target.radio_id)
        self._compose_js8_selected_target_endpoint_identity = self._compose_js8_selected_target_endpoint_key(radio_target)
        self._compose_js8_selected_target_action = action
        self._compose_js8_selected_target_state = "clearing" if action == "clear" else "refreshing"
        if action != "clear":
            self._compose_js8_selected_target_value = ""
        self._compose_js8_selected_target_error = ""
        self._refresh_compose_js8_selected_target_cue()
        context: Dict[str, object] = {
            "generation": self._compose_js8_selected_target_generation,
            "radio_id": self._compose_js8_selected_target_radio_id,
            "endpoint_identity": self._compose_js8_selected_target_endpoint_identity,
            "radio_label": self._compose_radio_target_short_label(radio_target),
            "action": action,
        }
        if action == "clear":
            context["expected_target"] = str(expected_target or "").strip()
        return context

    def request_compose_js8_selected_target_refresh(self) -> Optional[Dict[str, object]]:
        """Request one explicit selected-target refresh without performing UI-thread I/O."""
        if self._is_shutting_down:
            return None
        context = self.compose_js8_selected_target_request_context()
        if context is not None:
            try:
                self.composeJs8SelectedTargetRefreshRequested.emit(dict(context))
            except RuntimeError:
                # Lightweight non-Qt construction is useful to focused callers;
                # a normal widget always has the signal available.
                pass
        return context

    def _clear_compose_js8_selected_target(self) -> Optional[Dict[str, object]]:
        """Request a verified clear for the exact observed target and radio."""
        if self._is_shutting_down:
            return None
        if str(getattr(self, "_compose_js8_selected_target_state", "")) != "selected":
            return None
        expected = str(getattr(self, "_compose_js8_selected_target_value", "") or "").strip()
        context = self.compose_js8_selected_target_request_context(
            action="clear",
            expected_target=expected,
        )
        if context is not None:
            try:
                self.composeJs8SelectedTargetRefreshRequested.emit(dict(context))
            except RuntimeError:
                pass
        return context

    def _queue_compose_js8_selected_target_refresh(self, context: object) -> None:
        """Serialize target observations so one slow endpoint cannot fan out work."""
        if self._is_shutting_down or not isinstance(context, Mapping):
            return
        request = dict(context)
        try:
            generation = int(request.get("generation", -1))
            requested_radio = int(request.get("radio_id", 0))
        except (TypeError, ValueError):
            return
        selected_radio = self._selected_compose_radio_target()
        if (
            generation != self._compose_js8_selected_target_generation
            or not self._compose_js8_selected_target_is_active()
            or selected_radio is None
            or requested_radio != int(selected_radio.radio_id)
        ):
            return
        if self._compose_js8_selected_target_thread is not None and self._qt_thread_running(
            self._compose_js8_selected_target_thread
        ):
            # Keep only the newest radio/action request.  In particular, a
            # refresh or radio switch replaces a queued clear before mutation.
            self._compose_js8_selected_target_pending_context = request
            return
        try:
            radio_id = int(request.get("radio_id", 0) or 0)
        except (TypeError, ValueError):
            return
        radio_target = next(
            (item for item in self._compose_radio_targets if int(item.radio_id) == radio_id),
            None,
        )
        if radio_target is None or "JS8Call" not in tuple(radio_target.capabilities):
            return
        endpoint = js8_endpoint_from_radio_profile(radio_target.profile, fallback_settings=self.settings)
        expected_identity = self._compose_js8_selected_target_endpoint_key(radio_target)
        if str(request.get("endpoint_identity", "") or "") != expected_identity:
            return
        self._compose_js8_selected_target_thread = QThread(self)
        self._compose_js8_selected_target_worker = _ComposeJs8SelectedTargetWorker(
            endpoint=endpoint,
            context=request,
        )
        self._compose_js8_selected_target_worker.moveToThread(self._compose_js8_selected_target_thread)
        self._compose_js8_selected_target_thread.started.connect(
            self._compose_js8_selected_target_worker.run
        )
        self._compose_js8_selected_target_worker.finished.connect(
            self.apply_compose_js8_selected_target_result
        )
        self._compose_js8_selected_target_worker.finished.connect(
            self._compose_js8_selected_target_thread.quit
        )
        self._compose_js8_selected_target_worker.finished.connect(
            self._compose_js8_selected_target_worker.deleteLater
        )
        self._compose_js8_selected_target_thread.finished.connect(
            self._on_compose_js8_selected_target_thread_finished
        )
        self._compose_js8_selected_target_thread.finished.connect(
            self._compose_js8_selected_target_thread.deleteLater
        )
        self._compose_js8_selected_target_thread.start()

    def _on_compose_js8_selected_target_thread_finished(self) -> None:
        self._retain_finished_worker_refs(
            self._compose_js8_selected_target_thread,
            self._compose_js8_selected_target_worker,
        )
        self._compose_js8_selected_target_thread = None
        self._compose_js8_selected_target_worker = None
        pending = dict(self._compose_js8_selected_target_pending_context)
        self._compose_js8_selected_target_pending_context = {}
        if self._is_shutting_down or not pending:
            return
        if int(pending.get("generation", 0) or 0) != self._compose_js8_selected_target_generation:
            return
        QTimer.singleShot(0, lambda request=pending: self._queue_compose_js8_selected_target_refresh(request))

    def apply_compose_js8_selected_target_result(self, result: Mapping[str, object]) -> bool:
        """Apply a worker result only if it still belongs to the active radio endpoint."""
        if self._is_shutting_down or not self._compose_js8_selected_target_is_active():
            return False
        try:
            generation = int(result.get("generation", 0) or 0)
            radio_id = int(result.get("radio_id", 0) or 0)
        except (AttributeError, TypeError, ValueError):
            return False
        endpoint_identity = str(result.get("endpoint_identity", "") or "")
        if (
            generation != self._compose_js8_selected_target_generation
            or radio_id != self._compose_js8_selected_target_radio_id
            or endpoint_identity != self._compose_js8_selected_target_endpoint_identity
        ):
            return False
        selected = self._selected_compose_radio_target()
        if selected is None or int(selected.radio_id) != radio_id:
            return False
        if self._compose_js8_selected_target_endpoint_key(selected) != endpoint_identity:
            return False

        action = str(result.get("action", self._compose_js8_selected_target_action) or "refresh").strip().lower()
        supported = bool(result.get("supported", True))
        target = str(result.get("target", "") or "").strip().upper()
        error = str(result.get("error", "") or "").strip()
        self._compose_js8_selected_target_error = error
        if action == "clear":
            clear_result = result.get("result")
            status = str(
                result.get("status", getattr(clear_result, "status", "failed")) or "failed"
            ).strip().lower()
            state_obj = getattr(clear_result, "state", None)
            state_available = bool(
                getattr(state_obj, "available", result.get("supported", False))
            )
            state_target = str(getattr(state_obj, "target", target) or target).strip().upper()
            if status in {"cleared", "already_empty"}:
                self._compose_js8_selected_target_state = "empty"
                self._compose_js8_selected_target_value = ""
            elif status == "changed":
                self._compose_js8_selected_target_state = "changed" if state_target else (
                    "empty" if state_available else "unknown"
                )
                self._compose_js8_selected_target_value = state_target
            elif status == "unsupported":
                self._compose_js8_selected_target_state = "unsupported"
                self._compose_js8_selected_target_value = ""
            elif status == "unavailable":
                self._compose_js8_selected_target_state = "unavailable"
                self._compose_js8_selected_target_value = state_target if state_available else ""
            elif status == "cancelled":
                self._compose_js8_selected_target_state = "cancelled"
                self._compose_js8_selected_target_value = state_target if state_available else ""
            else:
                self._compose_js8_selected_target_state = "failed"
                self._compose_js8_selected_target_value = state_target if state_available else ""
            self._compose_js8_selected_target_action = ""
        else:
            self._compose_js8_selected_target_action = ""
            if not supported:
                self._compose_js8_selected_target_state = "unsupported"
                self._compose_js8_selected_target_value = ""
            elif target:
                self._compose_js8_selected_target_state = "selected"
                self._compose_js8_selected_target_value = target
            else:
                self._compose_js8_selected_target_state = "empty"
                self._compose_js8_selected_target_value = ""
        self._refresh_compose_js8_selected_target_cue()
        return True

    def _refresh_compose_js8_selected_target_cue(self) -> None:
        row = getattr(self, "compose_js8_selected_target_row_widget", None)
        label = getattr(self, "compose_js8_selected_target_label", None)
        use_btn = getattr(self, "compose_js8_selected_target_use_btn", None)
        clear_btn = getattr(self, "compose_js8_selected_target_clear_btn", None)
        refresh_btn = getattr(self, "compose_js8_selected_target_refresh_btn", None)
        if any(widget is None for widget in (row, label, use_btn, clear_btn, refresh_btn)):
            return
        active = self._compose_js8_selected_target_is_active()
        radio = self._selected_compose_radio_target()
        radio_label = self._compose_radio_target_short_label(radio) or "the selected radio"
        state = str(getattr(self, "_compose_js8_selected_target_state", "unknown") or "unknown")
        target = str(getattr(self, "_compose_js8_selected_target_value", "") or "")
        mode = str(getattr(self, "_compose_mode", "nbems") or "nbems")
        draft_widget = (
            getattr(self, "compose_commstat_target_edit", None)
            if mode == "commstat_rf"
            else getattr(self, "compose_js8_target_edit", None)
        )
        intended_target = str(getattr(draft_widget, "text", lambda: "")() or "").strip().upper()
        known_groups = tuple(getattr(self, "_compose_target_known_groups", ()))
        draft_uses_target = bool(
            target
            and intended_target
            and self._compose_js8_transport_target(target, known_groups)
            == self._compose_js8_transport_target(intended_target, known_groups)
        )
        if state == "selected" and target:
            if draft_uses_target:
                text = f"Already selected in JS8Call on {radio_label}: {target} · This draft uses it."
            elif intended_target:
                text = f"Already selected in JS8Call on {radio_label}: {target} · Draft target: {intended_target}. Use Target to adopt it."
            else:
                text = f"Already selected in JS8Call on {radio_label}: {target} · Use Target to adopt it."
        elif state == "refreshing":
            text = f"Checking the target currently selected in JS8Call on {radio_label}…"
        elif state == "clearing":
            text = f"Verifying and clearing JS8Call selection {target or '…'} on {radio_label}…"
        elif state == "empty":
            text = f"No callsign or group is currently selected in JS8Call on {radio_label}."
        elif state == "unsupported":
            text = f"JS8Call selected-target lookup is unavailable on {radio_label}."
        elif state == "unavailable":
            text = f"JS8Call selected-target clear is unavailable on {radio_label}: {getattr(self, '_compose_js8_selected_target_error', '') or 'check the JS8Call window and deselect manually.'}"
        elif state == "changed":
            text = f"JS8Call selection changed on {radio_label}; review the newly selected target before clearing again."
        elif state == "cancelled":
            text = f"JS8Call selection clear was cancelled for {radio_label}; refresh before trying again."
        elif state == "failed":
            text = f"Could not verify a cleared JS8Call selection on {radio_label}: {getattr(self, '_compose_js8_selected_target_error', '') or 'deselect manually in JS8Call.'}"
        else:
            text = f"JS8Call selected target has not been checked on {radio_label}."
        label.setText(text)
        label.setTextFormat(Qt.PlainText)
        row.setVisible(active)
        use_btn.setVisible(active and state == "selected" and bool(target))
        use_btn.setText("Target in Use" if draft_uses_target else "Use Target")
        use_btn.setEnabled(active and state == "selected" and bool(target) and not draft_uses_target)
        clear_btn.setVisible(active and state == "selected" and bool(target))
        clear_btn.setEnabled(active and state == "selected" and bool(target))
        if state == "clearing":
            clear_btn.setVisible(active)
            clear_btn.setEnabled(False)
            use_btn.setEnabled(False)
        refresh_recovery = active and radio is not None and state != "selected"
        refresh_btn.setVisible(refresh_recovery)
        refresh_btn.setEnabled(refresh_recovery and state not in {"refreshing", "clearing"})
        try:
            theme = resolve_theme(self.settings)
            emphasized = state == "selected" and bool(target)
            border = theme.get("accent", "#2E6F9E") if emphasized else theme.get("border", "#D3D7DD")
            surface = theme.get("surface_alt", "#DDE1E6") if emphasized else "transparent"
            label_color = theme.get("text", "#1C1F21") if emphasized else theme.get("text_muted", "#5B6570")
            row.setStyleSheet(
                "QWidget#composeJs8SelectedTargetRow {"
                f"background: {surface}; border: 1px solid {border}; border-radius: 5px;"
                "}"
            )
            label.setStyleSheet(f"color: {label_color}; font-weight: {'700' if emphasized else '500'};")
            use_btn.setStyleSheet(button_style("secondary" if use_btn.isEnabled() else "muted", theme))
            clear_btn.setStyleSheet(button_style("secondary" if clear_btn.isEnabled() else "muted", theme))
            refresh_btn.setStyleSheet(button_style("muted", theme))
        except Exception:
            pass
        self._refresh_compose_layout_geometry_if_needed()

    def _use_compose_js8_selected_target(self) -> None:
        """Explicitly copy the observed JS8Call selection into the active mode draft."""
        target = str(getattr(self, "_compose_js8_selected_target_value", "") or "").strip()
        if not target or str(getattr(self, "_compose_js8_selected_target_state", "")) != "selected":
            return
        mode = str(getattr(self, "_compose_mode", "nbems") or "nbems")
        target_edit = (
            getattr(self, "compose_commstat_target_edit", None)
            if mode == "commstat_rf"
            else getattr(self, "compose_js8_target_edit", None)
        )
        if not isinstance(target_edit, QLineEdit):
            return
        target_edit.setText(target)
        self._refresh_compose_js8_selected_target_cue()
        self._set_compose_status(
            "Copied the target selected in JS8Call into this draft. Review the exact preview before sending.",
            role="info",
        )

    def _on_compose_rf_target_changed(self, *_args) -> None:
        """Keep payload preview immediate and coalesce target-scoped lookup work."""
        self._update_compose_preview()
        self._refresh_compose_js8_selected_target_cue()
        if getattr(self, "_compose_target_discovery_pending", False):
            return
        self._compose_target_discovery_pending = True
        QTimer.singleShot(180, self._run_pending_compose_target_discovery)

    def _run_pending_compose_target_discovery(self) -> None:
        self._compose_target_discovery_pending = False
        self._start_compose_target_guidance_worker()

    def _start_compose_target_guidance_worker(self) -> None:
        mode = str(getattr(self, "_compose_mode", "nbems") or "nbems")
        if mode not in {"js8", "spotter", "commstat_rf"}:
            self._compose_send_recommendation = ComposeSendRecommendation()
            if hasattr(self, "compose_guidance_row_widget"):
                self.compose_guidance_row_widget.setVisible(False)
            return
        self._compose_guidance_generation += 1
        if self._compose_guidance_thread is not None and self._qt_thread_running(self._compose_guidance_thread):
            self._compose_guidance_pending = True
            return
        radio_target = self._selected_compose_radio_target()
        selected_radio_id = radio_target.radio_id if radio_target is not None else 0
        target_text = self._compose_intent_target()
        configured_groups = self._configured_message_group_names()
        db_path = self._db_path()
        options = tuple(
            ComposeRadioOption(radio_id=item.radio_id, label=self._compose_radio_short_label(item.profile))
            for item in self._compose_radio_targets
            if "JS8Call" in tuple(item.capabilities)
        )
        self._compose_guidance_thread = QThread(self)
        self._compose_guidance_worker = _ComposeTargetGuidanceWorker(
            generation=self._compose_guidance_generation,
            db_path=str(db_path or ""),
            target=target_text,
            target_is_group=self._is_message_group_candidate(target_text, configured_groups=configured_groups),
            operator_callsign=self._compose_operator_callsign(),
            cutoff_ts=time.time() - self._compose_map_age_seconds(),
            now_utc=datetime.datetime.now(datetime.timezone.utc),
            radio_options=options,
            selected_radio_id=selected_radio_id,
            last_heard=self._compose_last_heard_from_intent(),
            load_auth_keys=mode == "spotter",
        )
        self._compose_guidance_worker.moveToThread(self._compose_guidance_thread)
        self._compose_guidance_thread.started.connect(self._compose_guidance_worker.run)
        self._compose_guidance_worker.finished.connect(self._on_compose_target_guidance_finished)
        self._compose_guidance_worker.finished.connect(self._compose_guidance_thread.quit)
        self._compose_guidance_worker.finished.connect(self._compose_guidance_worker.deleteLater)
        self._compose_guidance_thread.finished.connect(self._on_compose_target_guidance_thread_finished)
        self._compose_guidance_thread.finished.connect(self._compose_guidance_thread.deleteLater)
        self._compose_guidance_thread.start()

    def _on_compose_target_guidance_thread_finished(self) -> None:
        self._retain_finished_worker_refs(self._compose_guidance_thread, self._compose_guidance_worker)
        self._compose_guidance_thread = None
        self._compose_guidance_worker = None
        if self._compose_guidance_pending and not self._is_shutting_down:
            self._compose_guidance_pending = False
            QTimer.singleShot(0, self._start_compose_target_guidance_worker)

    def _on_compose_target_guidance_finished(self, payload: object) -> None:
        if self._is_shutting_down or not isinstance(payload, dict):
            return
        if int(payload.get("generation", 0) or 0) != self._compose_guidance_generation:
            return
        recommendation = payload.get("recommendation")
        if not isinstance(recommendation, ComposeSendRecommendation):
            recommendation = ComposeSendRecommendation()
        self._compose_send_recommendation = recommendation
        selected = self._selected_compose_radio_target()
        selected_radio_id = selected.radio_id if selected is not None else 0
        if recommendation.radio_id and recommendation.radio_id != selected_radio_id:
            self._select_compose_radio_id(recommendation.radio_id)
        target_text = str(payload.get("target", "") or "")
        text_value = self._compose_send_guidance_summary(recommendation, target=target_text)
        tooltip = self._compose_send_guidance_tooltip(recommendation, target=target_text)
        if hasattr(self, "compose_guidance_label"):
            self.compose_guidance_label.setText(text_value)
            self.compose_guidance_label.setToolTip(tooltip)
        if hasattr(self, "compose_guidance_row_widget"):
            self.compose_guidance_row_widget.setToolTip(tooltip)
            self.compose_guidance_row_widget.setVisible(True)
        if hasattr(self, "compose_tune_recommended_btn"):
            available = bool(recommendation.tune_available and recommendation.frequency_mhz)
            self.compose_tune_recommended_btn.setVisible(available)
            self.compose_tune_recommended_btn.setEnabled(bool(recommendation.radio_id and recommendation.frequency_mhz))
            self.compose_tune_recommended_btn.setStyleSheet(button_style("warning", resolve_theme(self.settings)))
        if str(getattr(self, "_compose_mode", "") or "") == "spotter":
            self._apply_compose_js8_auth_rows(
                list(payload.get("auth_rows", []) or []),
                target=target_text,
                error=str(payload.get("auth_error", "") or ""),
            )
        self._update_compose_preview()

    def _on_compose_varac_target_changed(self, *_args) -> None:
        self._refresh_compose_destination_plans()
        self._update_compose_preview()

    def _on_compose_flamp_options_changed(self, *_args) -> None:
        if self._compose_sign_flamp_selected():
            self._refresh_compose_signing_keys()
        self._refresh_compose_destination_plans()
        self._update_compose_preview()

    def _refresh_compose_commstat_defaults(self) -> None:
        if hasattr(self, "compose_commstat_grid_edit") and not self.compose_commstat_grid_edit.text().strip():
            self.compose_commstat_grid_edit.setText(self._compose_operator_grid())
        if hasattr(self, "compose_commstat_report_id_edit") and not self.compose_commstat_report_id_edit.text().strip():
            self.compose_commstat_report_id_edit.setText(generate_commstat_report_id(self._compose_timestamp_utc))
        if hasattr(self, "compose_commstat_target_edit") and not self.compose_commstat_target_edit.text().strip():
            try:
                group_state = load_commstat_group_state(self.settings)
                default_group = next(iter(sorted(group_state.active_groups or group_state.configured_groups)), "")
            except Exception:
                default_group = ""
            if default_group:
                self.compose_commstat_target_edit.setText(default_group)

    def _compose_commstat_kind(self) -> str:
        if not hasattr(self, "compose_commstat_kind_combo"):
            return "StatRep"
        return self.compose_commstat_kind_combo.currentText().strip() or "StatRep"

    def _compose_commstat_status_values(self) -> Dict[str, str]:
        out: Dict[str, str] = {}
        widgets = getattr(self, "compose_commstat_status_widgets", {}) or {}
        for key, combo in widgets.items():
            if isinstance(combo, QComboBox):
                out[str(key)] = combo.currentText().strip() or "Unknown"
        return out

    def _compose_commstat_target(self) -> str:
        if not hasattr(self, "compose_commstat_target_edit"):
            return ""
        return self._compose_rf_target_text(self.compose_commstat_target_edit.text())

    def _compose_commstat_rf_text(self) -> str:
        target = self._compose_commstat_target()
        comment = self.compose_commstat_comment_edit.text() if hasattr(self, "compose_commstat_comment_edit") else ""
        if bool(getattr(getattr(self, "compose_commstat_brevity_chk", None), "isChecked", lambda: False)()):
            brevity_code = self._compose_commstat_brevity_code()
            if not brevity_code:
                raise ValueError("Choose or enter a valid CommStat brevity code.")
            comment = " ".join(part for part in (f"#{brevity_code}", comment.strip()) if part)
        return build_commstat_statrep_rf_text(
            callsign=self._compose_operator_callsign(),
            group=target,
            grid=self.compose_commstat_grid_edit.text() if hasattr(self, "compose_commstat_grid_edit") else "",
            scope=self.compose_commstat_scope_combo.currentData() if hasattr(self, "compose_commstat_scope_combo") else "1",
            report_id=self.compose_commstat_report_id_edit.text() if hasattr(self, "compose_commstat_report_id_edit") else "",
            statuses=self._compose_commstat_status_values(),
            comment=comment,
            now=self._compose_timestamp_utc,
        )

    def _compose_plain_js8_kind(self) -> str:
        if not hasattr(self, "compose_js8_plain_kind_combo"):
            return "Directed Message"
        return self.compose_js8_plain_kind_combo.currentText().strip() or "Directed Message"

    def _compose_plain_js8_text(self) -> str:
        if not hasattr(self, "compose_js8_plain_text_edit"):
            return ""
        return self.compose_js8_plain_text_edit.toPlainText().strip()

    def _compose_send_as_msg(self) -> bool:
        return bool(
            hasattr(self, "compose_js8_send_as_msg_chk")
            and self.compose_js8_send_as_msg_chk.isChecked()
        )

    def _compose_plain_js8_command(self) -> str:
        target = self._compose_rf_target_text(self.compose_js8_target_edit.text()) if hasattr(self, "compose_js8_target_edit") else ""
        text = re.sub(r"\s+", " ", self._compose_plain_js8_text()).strip()
        if not text:
            return ""
        if (self._compose_plain_js8_kind() == "Directed Message" or self._compose_send_as_msg()) and not target:
            return ""
        if target:
            if self._compose_send_as_msg():
                if text.upper().startswith(f"{target} MSG "):
                    return text
                if text.upper().startswith(f"{target} "):
                    text = text[len(target):].strip()
                return f"{target} MSG {text}".strip()
            if text.upper().startswith(f"{target} "):
                return text
            return f"{target} {text}".strip()
        return text

    def _refresh_compose_forms(self) -> None:
        if not hasattr(self, "compose_family_combo"):
            return
        if self._compose_mode not in {"nbems", "spotter"}:
            self._compose_discovery_generation += 1
            return
        self._refresh_compose_operating_group_options()
        self._compose_discovery_generation += 1
        generation = self._compose_discovery_generation
        if self._compose_discovery_thread is not None and self._qt_thread_running(self._compose_discovery_thread):
            self._compose_discovery_pending = True
            return
        self.compose_family_combo.blockSignals(True)
        self.compose_family_combo.clear()
        self.compose_family_combo.addItem("Loading forms…", None)
        self.compose_family_combo.blockSignals(False)
        self.compose_form_combo.blockSignals(True)
        self.compose_form_combo.clear()
        self.compose_form_combo.addItem("Loading forms…", None)
        self.compose_form_combo.blockSignals(False)

        radio = self._selected_compose_radio_target()
        profile = radio.profile if radio is not None else {}
        legacy_path = (
            self._compose_profile_text(profile, "js8_forms_path")
            or self._compose_profile_text(profile, "forms_path")
        )
        global_path = str(self.settings.get("js8_forms_path", self.forms_path) or "").strip()
        # Pass one already chosen source to the worker.  It must not fall back
        # to another radio or bundled catalog after an explicit global choice.
        spotter_candidates = [choose_effective_spotter_forms_catalog(global_path, legacy_path).path]
        settings_snapshot = {
            "nbems_custom_forms_path": self.settings.get("nbems_custom_forms_path", ""),
            "message_paths": self.settings.get("message_paths", {}) or {},
        }
        self._compose_discovery_thread = QThread(self)
        self._compose_discovery_worker = _ComposeCatalogDiscoveryWorker(
            generation=generation,
            mode=str(getattr(self, "_compose_mode", "nbems") or "nbems"),
            settings_snapshot=settings_snapshot,
            spotter_candidates=spotter_candidates,
        )
        self._compose_discovery_worker.moveToThread(self._compose_discovery_thread)
        self._compose_discovery_thread.started.connect(self._compose_discovery_worker.run)
        self._compose_discovery_worker.finished.connect(self._on_compose_discovery_finished)
        self._compose_discovery_worker.finished.connect(self._compose_discovery_thread.quit)
        self._compose_discovery_worker.finished.connect(self._compose_discovery_worker.deleteLater)
        self._compose_discovery_thread.finished.connect(self._on_compose_discovery_thread_finished)
        self._compose_discovery_thread.finished.connect(self._compose_discovery_thread.deleteLater)
        self._compose_discovery_thread.start()

    def _on_compose_discovery_thread_finished(self) -> None:
        self._retain_finished_worker_refs(self._compose_discovery_thread, self._compose_discovery_worker)
        self._compose_discovery_thread = None
        self._compose_discovery_worker = None
        if self._compose_discovery_pending and not self._is_shutting_down:
            self._compose_discovery_pending = False
            QTimer.singleShot(0, self._refresh_compose_forms)

    def _on_compose_discovery_finished(self, payload: object) -> None:
        if self._is_shutting_down or not isinstance(payload, dict):
            return
        generation = int(payload.get("generation", 0) or 0)
        mode = str(payload.get("mode", "") or "")
        if generation != self._compose_discovery_generation or mode != self._compose_mode:
            return
        entries = [dict(value) for value in payload.get("entries", []) if isinstance(value, dict)]
        if not entries:
            entries = [{"kind": "standard", "key": "STANDARD", "label": "Standard Blank"}]
        self._compose_family_entries_cache = entries
        parsed = payload.get("parsed", {})
        self._compose_parsed_form_cache = dict(parsed) if isinstance(parsed, dict) else {}
        self._apply_compose_family_entries(entries)
        self._ensure_summary_blank_form()
        problems = [str(value or "").strip() for value in payload.get("problems", []) if str(value or "").strip()]
        if problems:
            self._set_compose_status(
                f"Forms loaded with {len(problems)} skipped file{'s' if len(problems) != 1 else ''}.",
                role="warning",
            )

    def _apply_compose_family_entries(self, entries: Sequence[dict]) -> None:
        if not hasattr(self, "compose_family_combo"):
            return
        previous_key = ""
        if self.compose_family_combo.count():
            previous = self.compose_family_combo.currentData()
            if isinstance(previous, dict):
                previous_key = str(previous.get("key", "") or "")
        self.compose_family_combo.blockSignals(True)
        self.compose_family_combo.clear()
        selected_index = 0
        fallback_custom_index = -1
        for idx, entry in enumerate(entries):
            self.compose_family_combo.addItem(str(entry.get("label", "")), entry)
            if str(entry.get("key", "")) == "CUSTOM" and fallback_custom_index < 0:
                fallback_custom_index = idx
            if previous_key and str(entry.get("key", "")) == previous_key:
                selected_index = idx
        if not previous_key and fallback_custom_index >= 0:
            selected_index = fallback_custom_index
        if not previous_key:
            preferred_family = self._compose_fastlight_preferred_form_family()
            if preferred_family:
                for idx in range(self.compose_family_combo.count()):
                    entry = self.compose_family_combo.itemData(idx)
                    if isinstance(entry, dict) and str(entry.get("key", "") or "").strip().upper() == preferred_family:
                        selected_index = idx
                        break
        self.compose_family_combo.setCurrentIndex(max(0, selected_index))
        self.compose_family_combo.blockSignals(False)
        self._on_compose_family_changed()

    def _refresh_compose_operating_group_options(self) -> None:
        combo = getattr(self, "compose_operating_group_combo", None)
        if not isinstance(combo, QComboBox):
            return
        previous = str(combo.currentData() or combo.currentText() or "").strip().upper().lstrip("@")
        values: List[str] = []
        seen: set[str] = set()

        def add_group(value: object) -> None:
            text = str(value or "").strip().upper().lstrip("@")
            if not text or text in seen:
                return
            values.append(text)
            seen.add(text)

        for group in self._configured_message_group_names():
            add_group(group)
        try:
            group_state = load_commstat_group_state(self.settings)
            for group in [*group_state.active_groups, *group_state.configured_groups]:
                add_group(group)
        except Exception:
            pass
        radio_target = self._selected_compose_radio_target()
        profile = radio_target.profile if radio_target is not None else {}
        if isinstance(profile, dict):
            for key in ("operating_group", "group", "group_name", "schedule_group"):
                add_group(profile.get(key))
        combo.blockSignals(True)
        try:
            combo.clear()
            combo.addItem("Auto", "")
            for group in sorted(values):
                combo.addItem(group, group)
            if previous:
                idx = combo.findData(previous)
                if idx < 0:
                    idx = combo.findText(previous)
                if idx >= 0:
                    combo.setCurrentIndex(idx)
        finally:
            combo.blockSignals(False)

    def _on_compose_operating_group_changed(self, *_args) -> None:
        self._install_compose_target_completers()
        self._refresh_compose_forms()

    def _on_compose_family_changed(self) -> None:
        if not hasattr(self, "compose_form_combo"):
            return
        data = self.compose_family_combo.currentData()
        self.compose_form_combo.blockSignals(True)
        self.compose_form_combo.clear()
        self._compose_templates = []
        self._compose_last_source_dir = None
        if isinstance(data, dict) and data.get("kind") == "standard":
            self.compose_form_combo.addItem("Standard Blank Form (.b2s)", {"kind": "standard"})
        elif isinstance(data, dict) and data.get("kind") == "spotter":
            forms = list(data.get("forms") or [])
            self._refresh_spotter_category_options(forms)
            self.compose_form_combo.blockSignals(False)
            self._populate_spotter_form_combo(forms)
            return
        elif isinstance(data, dict) and isinstance(data.get("family"), ComposeFormFamily):
            family = data.get("family")
            self._compose_last_source_dir = family.path
            self._compose_templates = [
                template for template in list(data.get("templates") or []) if isinstance(template, ComposeFormTemplate)
            ]
            if self._compose_templates:
                for template in self._compose_templates:
                    self.compose_form_combo.addItem(
                        template.display_name,
                        {"kind": "custom", "path": str(template.path), "label": template.display_name},
                    )
            else:
                self.compose_form_combo.addItem("No editable forms found", None)
        else:
            self.compose_form_combo.addItem("No forms available", None)
        self.compose_form_combo.blockSignals(False)
        self._on_compose_form_changed()

    def _on_compose_form_changed(self) -> None:
        if not hasattr(self, "compose_form_combo"):
            return
        if (
            str(getattr(self, "_compose_mode", "nbems") or "nbems") == "spotter"
            and not bool(getattr(self, "_compose_spotter_source_loading", False))
            and int(getattr(self, "_compose_spotter_expect_active_id", 0) or 0) > 0
        ):
            # Picking a different catalog form starts a new draft.  It must not
            # continue to send the previously selected saved response.
            data = self.compose_form_combo.currentData()
            code = str(data.get("code", "") or "").strip().upper() if isinstance(data, dict) else ""
            active = {}
            for row in self._compose_spotter_expect_entries:
                try:
                    if int(row.get("id", 0) or 0) == int(self._compose_spotter_expect_active_id):
                        active = row
                        break
                except (TypeError, ValueError):
                    continue
            active_key = str(active.get("expect_key", "") or "").strip().upper()
            if code != active_key:
                self._clear_compose_spotter_working_response()
                source_combo = getattr(self, "compose_spotter_source_combo", None)
                if isinstance(source_combo, QComboBox):
                    source_combo.blockSignals(True)
                    try:
                        source_combo.setCurrentIndex(0)
                    finally:
                        source_combo.blockSignals(False)
        self._store_compose_form_draft()
        data = self.compose_form_combo.currentData()
        form_identity = self._compose_form_identity(data)
        current_values = (
            self._compose_field_values()
            if form_identity == self._compose_active_form_key
            else dict(self._compose_form_draft_values.get(form_identity, {}))
        )
        rows: List[ComposeFieldDefinition] = []
        defaults: Dict[str, str] = {}
        smart_defaults: Dict[str, str] = {}
        self._compose_spotter_fields = []
        self._compose_spotter_guidance = ()
        self._compose_template_kind = "custom"
        self._compose_template_title = ""
        self._compose_template_menu_item = ""
        if isinstance(data, dict) and data.get("kind") == "standard":
            self._compose_template_kind = "blank"
            rows = self._compose_blank_field_rows()
            smart_defaults = self._compose_smart_defaults(rows)
            defaults = {
                field.key: current_values.get(field.key, smart_defaults.get(field.key, ""))
                for field in rows
            }
        elif isinstance(data, dict) and data.get("kind") == "custom":
            template_path = Path(str(data.get("path", "") or ""))
            self._compose_last_source_dir = template_path.parent
            cached = dict(self._compose_parsed_form_cache.get(str(template_path), {}) or {})
            self._compose_template_title = str(cached.get("title", "") or "")
            self._compose_template_menu_item = str(cached.get("menu_item", "") or "")
            rows = [row for row in list(cached.get("rows", []) or []) if isinstance(row, ComposeFieldDefinition)]
            smart_defaults = self._compose_smart_defaults(rows)
            defaults = {
                field.key: current_values.get(field.key, smart_defaults.get(field.key, ""))
                for field in rows
            }
        elif isinstance(data, dict) and data.get("kind") == "spotter_form":
            self._compose_template_kind = "spotter"
            code = str(data.get("code", "") or "").strip()
            title = str(data.get("title", "") or "").strip()
            path = Path(str(data.get("path", "") or ""))
            self._compose_template_title = f"{code} - {title}" if title else code
            if path:
                self._compose_last_source_dir = path.parent
            cached = dict(self._compose_parsed_form_cache.get(str(path), {}) or {})
            spotter_rows = list(cached.get("spotter_rows", []) or [])
            self._compose_spotter_fields = [
                field for field in spotter_rows if isinstance(field, SpotterFormField)
            ]
            self._compose_spotter_guidance = tuple(
                str(item or "").strip()
                for item in cached.get("spotter_guidance", ()) or ()
                if str(item or "").strip()
            )
            rows = [
                ComposeFieldDefinition(
                    key=field.key,
                    label=field.label,
                    field_type="select" if field.options else "text",
                    options=tuple(
                        [ComposeFieldOption(value="", label="Choose an answer…", selected=not bool(field.default_value))]
                        + [
                            ComposeFieldOption(
                                value=value,
                                label=label,
                                selected=str(value).upper() == str(field.default_value).upper(),
                            )
                            for value, label in field.options
                        ]
                    ),
                    allow_custom=not bool(field.options),
                    # The source guidance is rendered once above the form.
                    # Repeating it below each control makes long forms harder
                    # to scan and can associate trailing notes with the wrong
                    # question.
                    description="",
                )
                for field in spotter_rows
            ]
            rows.append(
                ComposeFieldDefinition(
                    key=SPOTTER_COMMENTS_KEY,
                    label="Comments (optional)",
                    description=f"Add brief context not captured by the form (up to {SPOTTER_COMMENTS_MAX_LENGTH} characters).",
                    field_type="textarea",
                    rows=3,
                    placeholder="Brief additional context",
                )
            )
            identity_values = {
                "callsign": self._compose_operator_callsign(),
                "state": self._compose_operator_state(),
                "grid": self._compose_operator_grid(),
            }
            defaults = {}
            for field in rows:
                if field.key in current_values:
                    defaults[field.key] = current_values[field.key]
                    continue
                source_field = next((item for item in self._compose_spotter_fields if item.key == field.key), None)
                if source_field is None:
                    defaults[field.key] = ""
                    continue
                if source_field.kind == "choice":
                    defaults[field.key] = source_field.default_value
                else:
                    default_kind = spotter_operator_autofill_kind(code, source_field.key)
                    defaults[field.key] = identity_values.get(default_kind, "")
        self._rebuild_compose_field_editor(rows, defaults)
        self._compose_last_smart_defaults = smart_defaults
        self._compose_active_form_key = form_identity
        self._update_compose_preview()
        if str(getattr(self, "_compose_mode", "nbems") or "nbems") == "spotter":
            category = ""
            category_combo = getattr(self, "compose_spotter_category_combo", None)
            if isinstance(category_combo, QComboBox):
                category = str(category_combo.currentData() or category_combo.currentText() or "")
            reset_key = (str(form_identity or ""), category)
            if reset_key != getattr(self, "_compose_spotter_last_scroll_reset_key", None):
                self._compose_spotter_last_scroll_reset_key = reset_key
                self._queue_compose_spotter_scroll_reset()

    @staticmethod
    def _compose_form_identity(data) -> str:
        if isinstance(data, dict):
            kind = str(data.get("kind", "") or "")
            if kind == "standard":
                return "standard"
            if kind == "custom":
                return str(data.get("path", "") or "")
            if kind == "spotter_form":
                return f"spotter:{data.get('path', '') or data.get('code', '')}"
        return ""

    def _store_compose_form_draft(self) -> None:
        form_key = str(getattr(self, "_compose_active_form_key", "") or "")
        if not form_key or not getattr(self, "_compose_field_widgets", None):
            return
        self._compose_form_draft_values[form_key] = self._compose_field_values()
        mode = str(getattr(self, "_compose_mode", "nbems") or "nbems")
        self._compose_form_draft_mode_keys.setdefault(mode, set()).add(form_key)

    def _compose_smart_defaults(self, rows: Sequence[ComposeFieldDefinition]) -> Dict[str, str]:
        defaults: Dict[str, str] = {}
        family_data = self.compose_family_combo.currentData() if hasattr(self, "compose_family_combo") else None
        family_key = ""
        if isinstance(family_data, dict):
            family_key = str(family_data.get("key", "") or "")
        form_data = self.compose_form_combo.currentData() if hasattr(self, "compose_form_combo") else None
        template_name = ""
        if isinstance(form_data, dict):
            template_name = Path(str(form_data.get("path", "") or "")).name
        for field in rows:
            defaults[field.key] = suggest_field_value(
                field.key,
                field.label,
                description=field.description,
                placeholder=field.placeholder,
                options=field.options,
                family_key=family_key,
                template_name=template_name,
                template_title=self._compose_template_title,
                menu_item=self._compose_template_menu_item,
                callsign=self._compose_operator_callsign(),
                state=self._compose_operator_state(),
                grid=self._compose_operator_grid(),
                zulu_timestamp=self._compose_zulu_text(),
                report_title=self.compose_report_title_edit.text().strip() if hasattr(self, "compose_report_title_edit") else "",
                priority_code=self.compose_priority_combo.currentText() if hasattr(self, "compose_priority_combo") else "RR",
            )
        return defaults

    def _compose_set_widget_value(self, key: str, value: str) -> None:
        widget = self._compose_field_widgets.get(key)
        if widget is None:
            return
        text = str(value or "")
        if isinstance(widget, QTextEdit):
            widget.blockSignals(True)
            widget.setPlainText(text)
            widget.blockSignals(False)
            return
        if isinstance(widget, QLineEdit):
            widget.blockSignals(True)
            widget.setText(text)
            widget.blockSignals(False)
            return
        if isinstance(widget, QComboBox):
            widget.blockSignals(True)
            match_index = -1
            for idx in range(widget.count()):
                item_data = widget.itemData(idx)
                if item_data is not None and str(item_data) == text:
                    match_index = idx
                    break
                if widget.itemText(idx).strip().upper() == text.strip().upper():
                    match_index = idx
                    break
            if match_index >= 0:
                widget.setCurrentIndex(match_index)
            elif widget.isEditable():
                widget.setEditText(text)
            elif not text and widget.count():
                widget.setCurrentIndex(0)
            widget.blockSignals(False)

    def _refresh_compose_smart_defaults(self) -> None:
        if not self._compose_field_rows:
            return
        new_defaults = self._compose_smart_defaults(self._compose_field_rows)
        current_values = self._compose_field_values()
        previous_defaults = dict(self._compose_last_smart_defaults)
        for field in self._compose_field_rows:
            key = field.key
            current_value = str(current_values.get(key, "") or "")
            previous_value = str(previous_defaults.get(key, "") or "")
            new_value = str(new_defaults.get(key, "") or "")
            if not current_value or current_value == previous_value:
                self._compose_set_widget_value(key, new_value)
        self._compose_last_smart_defaults = new_defaults

    def _on_compose_priority_changed(self) -> None:
        self._refresh_compose_smart_defaults()
        self._update_compose_preview()

    def _on_compose_report_title_changed(self) -> None:
        self._refresh_compose_smart_defaults()
        self._update_compose_preview()

    def _rebuild_compose_field_editor(self, rows: List[ComposeFieldDefinition], values: Dict[str, str]) -> None:
        self._compose_field_rows = list(rows)
        self._compose_field_widgets = {}
        mode = str(getattr(self, "_compose_mode", "nbems") or "nbems")
        spotter_mode = mode == "spotter"
        container = QWidget()
        container.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Preferred)
        layout = QGridLayout(container)
        layout.setContentsMargins(8, 8, 8, 8)
        layout.setHorizontalSpacing(14)
        layout.setVerticalSpacing(10)
        layout.setColumnStretch(0, 1)
        layout.setColumnStretch(1, 1)
        long_labels = {"MESSAGE", "NARRATIVE", "REMARK", "REMARKS", "SUMMARY", "BODY", "DETAILS", "COMMENTS"}
        grid_row = 0
        grid_col = 0
        if spotter_mode and self._compose_spotter_guidance:
            guidance = QLabel(
                "Form guidance\n"
                + "\n".join(f"• {line}" for line in self._compose_spotter_guidance)
            )
            guidance.setWordWrap(True)
            guidance.setMinimumWidth(0)
            guidance.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Minimum)
            guidance.setStyleSheet(label_style("info", resolve_theme(self.settings)))
            layout.addWidget(guidance, grid_row, 0, 1, 2)
            grid_row += 1
        for field in rows:
            initial = str(values.get(field.key, "") or "")
            upper_label = f"{field.label} {field.description}".upper()
            is_spotter_comment = spotter_mode and field.key == SPOTTER_COMMENTS_KEY
            is_long_field = (
                is_spotter_comment
                or (
                    field.field_type == "textarea"
                    or field.key == "MESSAGE"
                    or any(token in upper_label for token in long_labels)
                )
            )
            field_wrap = QWidget()
            field_wrap.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding if is_long_field else QSizePolicy.Fixed)
            field_layout = QVBoxLayout(field_wrap)
            field_layout.setContentsMargins(0, 0, 0, 0)
            field_layout.setSpacing(4)
            field_layout.setAlignment(Qt.AlignTop)
            label_widget = QLabel(field.label or field.key)
            label_widget.setWordWrap(True)
            field_layout.addWidget(label_widget)
            if field.description:
                desc_widget = QLabel(field.description)
                desc_widget.setWordWrap(True)
                desc_widget.setStyleSheet(
                    label_style("muted", resolve_theme(self.settings))
                )
                field_layout.addWidget(desc_widget)
            if field.field_type == "select":
                widget = QComboBox()
                if field.allow_custom:
                    widget.setEditable(True)
                for option in field.options:
                    widget.addItem(option.label or option.value, option.value)
                if field.placeholder and widget.isEditable() and widget.lineEdit() is not None:
                    widget.lineEdit().setPlaceholderText(field.placeholder)
                if spotter_mode:
                    widget.setMinimumWidth(140)
                    widget.setMinimumContentsLength(8)
                    widget.setSizeAdjustPolicy(QComboBox.AdjustToMinimumContentsLengthWithIcon)
                    widget.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
                else:
                    self._configure_compose_combo_width(widget, floor=160)
                widget.currentIndexChanged.connect(self._on_compose_form_field_changed)
                if widget.isEditable():
                    widget.editTextChanged.connect(self._on_compose_form_field_changed)
            elif is_long_field:
                widget = QTextEdit()
                line_height = max(1, int(widget.fontMetrics().lineSpacing()))
                requested_lines = max(3, int(field.rows or 0))
                widget.setMinimumHeight(
                    max(
                        int(widget.minimumSizeHint().height()),
                        line_height * (requested_lines + 1),
                    )
                )
                widget.setMaximumHeight(16777215)
                if is_spotter_comment:
                    widget.setMaximumHeight(widget.minimumHeight())
                widget.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.MinimumExpanding)
                widget.setPlaceholderText(field.placeholder)
                widget.setPlainText(initial)
                widget.textChanged.connect(self._on_compose_form_field_changed)
            else:
                widget = QLineEdit()
                widget.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
                widget.setPlaceholderText(field.placeholder)
                widget.setText(initial)
                widget.textChanged.connect(self._on_compose_form_field_changed)
            if not isinstance(widget, QComboBox):
                field_layout.addWidget(widget)
            else:
                field_layout.addWidget(widget)
            self._compose_field_widgets[field.key] = widget
            self._compose_set_widget_value(field.key, initial)
            if is_long_field or spotter_mode:
                if grid_col:
                    grid_row += 1
                    grid_col = 0
                layout.addWidget(field_wrap, grid_row, 0, 1, 2)
                if is_long_field:
                    layout.setRowStretch(grid_row, 0)
                grid_row += 1
            else:
                layout.addWidget(field_wrap, grid_row, grid_col)
                grid_col += 1
                if grid_col >= 2:
                    grid_row += 1
                    grid_col = 0
        layout.setRowStretch(grid_row + 1, 1)
        self.compose_field_scroll.setWidget(container)
        self._apply_compose_expect_view_state()

    def _on_compose_form_field_changed(self, *_args) -> None:
        if (
            str(getattr(self, "_compose_mode", "nbems") or "nbems") == "spotter"
            and not bool(getattr(self, "_compose_spotter_source_loading", False))
            and int(getattr(self, "_compose_spotter_expect_active_id", 0) or 0) > 0
        ):
            self._compose_spotter_working_response_dirty = True
        self._update_compose_preview()

    def _compose_field_values(self) -> Dict[str, str]:
        values: Dict[str, str] = {}
        for key, widget in self._compose_field_widgets.items():
            if isinstance(widget, QTextEdit):
                values[key] = widget.toPlainText()
            elif isinstance(widget, QLineEdit):
                values[key] = widget.text()
            elif isinstance(widget, QComboBox):
                data = widget.currentData()
                if widget.isEditable():
                    idx = widget.currentIndex()
                    if idx >= 0 and data is not None and widget.currentText().strip() == widget.itemText(idx).strip():
                        values[key] = str(data)
                    else:
                        values[key] = widget.currentText().strip()
                elif data is not None:
                    values[key] = str(data)
                else:
                    values[key] = widget.currentText().strip()
        return values

    def _compose_output_extension(self) -> str:
        return ".b2s" if self._compose_template_kind == "blank" else ".k2s"

    def _compose_fastlight_target_group(self) -> str:
        group_combo = getattr(self, "compose_operating_group_combo", None)
        if isinstance(group_combo, QComboBox):
            selected_group = str(group_combo.currentData() or group_combo.currentText() or "").strip().upper().lstrip("@")
            if selected_group and selected_group != "AUTO":
                return selected_group
        values = self._compose_field_values()
        raw = (
            values.get("TO")
            or values.get("To")
            or values.get("to")
            or values.get("REGION")
            or values.get("GROUP")
            or ""
        )
        target = str(raw or "").strip().upper().lstrip("@")
        if target:
            return target
        radio_target = self._selected_compose_radio_target()
        profile = radio_target.profile if radio_target is not None else {}
        for key in ("operating_group", "group", "group_name", "schedule_group"):
            candidate = str(profile.get(key, "") or "").strip().upper().lstrip("@")
            if candidate:
                return candidate
        return ""

    def _compose_fastlight_filename_policy(self):
        try:
            groups = self.settings.get("operating_groups", []) or []
        except Exception:
            groups = []
        return resolve_fastlight_filename_policy(groups if isinstance(groups, list) else [], self._compose_fastlight_target_group())

    def _compose_fastlight_preferred_form_family(self) -> str:
        try:
            groups = self.settings.get("operating_groups", []) or []
        except Exception:
            groups = []
        return resolve_fastlight_form_family(groups if isinstance(groups, list) else [], self._compose_fastlight_target_group())

    def _compose_fastlight_delimiter_guidance(self) -> str:
        target_group = self._compose_fastlight_target_group()
        policy = self._compose_fastlight_filename_policy()
        delimiter_label = "underscore" if policy.delimiter == "_" else "hyphen" if policy.delimiter == "-" else policy.delimiter
        if self._compose_template_kind == "blank":
            return (
                f"Standard blank form uses .b2s. Filename delimiter is {delimiter_label}"
                f" from {policy.source_label}."
            )
        unsigned_ext = policy.unsigned_extension or self._compose_output_extension()
        group_text = f" for {target_group}" if target_group else ""
        family_text = ""
        preferred_family = self._compose_fastlight_preferred_form_family()
        if preferred_family:
            family_text = f" Preferred form family for this group is {preferred_family}."
        return (
            f"Selected form stages as {unsigned_ext}{group_text}. Filename delimiter is "
            f"{delimiter_label} from {policy.source_label}.{family_text}"
        )

    def _compose_base_filename(self) -> str:
        target_group = self._compose_fastlight_target_group()
        filename_policy = self._compose_fastlight_filename_policy()
        return build_compose_filename(
            self._compose_operator_callsign(),
            self._compose_operator_state(),
            self.compose_priority_combo.currentText() if hasattr(self, "compose_priority_combo") else "RR",
            self._compose_timestamp_utc,
            self.compose_report_title_edit.text() if hasattr(self, "compose_report_title_edit") else "Report",
            extension=self._compose_output_extension(),
            filename_policy=filename_policy,
            operating_group=target_group,
        )

    def _compose_current_payload(self) -> str:
        values = self._compose_field_values()
        callsign = self._compose_operator_callsign()
        if self._compose_template_kind == "blank":
            return serialize_standard_blank_message(
                callsign=callsign,
                created_utc=self._compose_timestamp_utc,
                subject=values.get("SUBJECT", ""),
                message=values.get("MESSAGE", ""),
                to_name=values.get("TO", ""),
                from_name=callsign,
                precedence=self.compose_priority_combo.currentText(),
                dtg=self._compose_zulu_text(),
            )
        form_data = self.compose_form_combo.currentData()
        template_name = Path(str(form_data.get("path", "") or "")).name if isinstance(form_data, dict) else ""
        field_pairs = [(field.key, values.get(field.key, "")) for field in self._compose_field_rows]
        return serialize_custom_form_message(
            template_name,
            field_pairs,
            callsign=callsign,
            created_utc=self._compose_timestamp_utc,
        )

    def _compose_js8_auth_scope(self) -> tuple[str, str]:
        target = self.compose_js8_target_edit.text().strip().upper() if hasattr(self, "compose_js8_target_edit") else ""
        return normalize_group_name(target), self._compose_operator_callsign()

    def _compose_js8_msg_auth_selected(self) -> bool:
        return bool(hasattr(self, "compose_js8_sign_chk") and self.compose_js8_sign_chk.isChecked())

    def _refresh_compose_js8_auth_keys(self, *, force: bool = False) -> None:
        if not hasattr(self, "compose_js8_auth_key_combo"):
            return
        group, callsign = self._compose_js8_auth_scope()
        scope_sig = (group, callsign)
        if not force and getattr(self, "_compose_js8_auth_scope_sig", None) == scope_sig:
            return
        self._compose_js8_auth_scope_sig = scope_sig
        if not group or not callsign:
            rows = []
        else:
            try:
                rows = load_msg_auth_keys(group_name=group, callsign=callsign, key_scope=MSG_AUTH_SCOPE_SIGNING)
            except Exception as exc:
                rows = []
                log.debug("MessageViewer: failed to load compose MsgAuth keys: %s", exc)
        self._apply_compose_js8_auth_rows(rows, target=group)

    def _apply_compose_js8_auth_rows(
        self,
        rows: Sequence[object],
        *,
        target: str,
        error: str = "",
    ) -> None:
        if not hasattr(self, "compose_js8_auth_key_combo"):
            return
        group = normalize_group_name(target)
        callsign = self._compose_operator_callsign()
        previous_key = ""
        current = self.compose_js8_auth_key_combo.currentData()
        if isinstance(current, dict):
            previous_key = str(current.get("key", "") or "")
        self.compose_js8_auth_key_combo.blockSignals(True)
        try:
            self.compose_js8_auth_key_combo.clear()
            self._compose_js8_auth_key_count = 0
            selected_index = 0
            for key_row in rows:
                key_text = str(getattr(key_row, "key", "") or "")
                if not key_text:
                    continue
                label = str(getattr(key_row, "label", "") or "").strip() or f"{group} / {callsign}"
                data = {"label": label, "key": key_text}
                self.compose_js8_auth_key_combo.addItem(label, data)
                if previous_key and key_text == previous_key:
                    selected_index = self.compose_js8_auth_key_combo.count() - 1
                self._compose_js8_auth_key_count += 1
            if self._compose_js8_auth_key_count:
                self.compose_js8_auth_key_combo.setCurrentIndex(selected_index)
            elif error:
                self.compose_js8_auth_key_combo.addItem("MsgAuth key lookup unavailable", None)
                self.compose_js8_auth_key_combo.setToolTip(error)
            elif not group or not callsign:
                self.compose_js8_auth_key_combo.addItem("Set JS8 target and operator callsign", None)
            else:
                self.compose_js8_auth_key_combo.addItem(f"No key for {group} / {callsign}", None)
        finally:
            self.compose_js8_auth_key_combo.blockSignals(False)

    def _clear_compose_chip_layout(self, layout: QHBoxLayout, group: QButtonGroup) -> None:
        for button in list(group.buttons()):
            group.removeButton(button)
            button.deleteLater()
        while layout.count():
            item = layout.takeAt(0)
            widget = item.widget()
            if widget is not None:
                widget.deleteLater()

    def _compose_chip_button(self, text: str, *, tooltip: str = "", selected: bool = False) -> QPushButton:
        theme = resolve_theme(self.settings)
        chip = QPushButton(text)
        chip.setCheckable(True)
        chip.setChecked(selected)
        chip_h = button_height_for_font(chip)
        chip.setMinimumHeight(chip_h)
        chip.setMaximumHeight(chip_h)
        chip.setMaximumWidth(150)
        chip.setSizePolicy(QSizePolicy.Fixed, QSizePolicy.Fixed)
        if tooltip:
            chip.setToolTip(tooltip)
        chip.setStyleSheet(button_style("primary" if selected else "muted", theme))
        return chip

    def _build_compose_combo_chips(
        self,
        combo: QComboBox,
        layout: QHBoxLayout,
        group: QButtonGroup,
        *,
        labels: Optional[Mapping[str, str]] = None,
    ) -> None:
        self._clear_compose_chip_layout(layout, group)
        current = combo.currentText()
        for idx in range(combo.count()):
            value = combo.itemText(idx)
            text = str((labels or {}).get(value, value)).strip() or value
            chip = self._compose_chip_button(text, tooltip=value, selected=value == current)
            chip.clicked.connect(lambda _checked=False, index=idx: combo.setCurrentIndex(index))
            group.addButton(chip)
            layout.addWidget(chip)
        layout.addStretch(1)

    def _refresh_compose_static_choice_chips(self) -> None:
        if all(
            hasattr(self, name)
            for name in (
                "compose_send_target_combo",
                "compose_send_target_chip_layout",
                "compose_send_target_chip_group",
            )
        ):
            self._build_compose_combo_chips(
                self.compose_send_target_combo,
                self.compose_send_target_chip_layout,
                self.compose_send_target_chip_group,
            )
        if all(
            hasattr(self, name)
            for name in (
                "compose_varac_target_combo",
                "compose_varac_target_chip_layout",
                "compose_varac_target_chip_group",
            )
        ):
            self._build_compose_combo_chips(
                self.compose_varac_target_combo,
                self.compose_varac_target_chip_layout,
                self.compose_varac_target_chip_group,
            )
        if all(
            hasattr(self, name)
            for name in (
                "compose_js8_plain_kind_combo",
                "compose_js8_plain_kind_chip_layout",
                "compose_js8_plain_kind_chip_group",
            )
        ):
            self._build_compose_combo_chips(
                self.compose_js8_plain_kind_combo,
                self.compose_js8_plain_kind_chip_layout,
                self.compose_js8_plain_kind_chip_group,
                labels={"Directed Message": "Directed"},
            )

    def _sync_compose_combo_chips(self, combo: QComboBox, group: QButtonGroup) -> None:
        theme = resolve_theme(self.settings)
        current = combo.currentText()
        for button in group.buttons():
            selected = button.toolTip() == current
            button.setChecked(selected)
            button.setStyleSheet(button_style("primary" if selected else "muted", theme))

    def _sync_compose_static_choice_chips(self) -> None:
        if hasattr(self, "compose_send_target_combo") and hasattr(self, "compose_send_target_chip_group"):
            self._sync_compose_combo_chips(self.compose_send_target_combo, self.compose_send_target_chip_group)
        if hasattr(self, "compose_varac_target_combo") and hasattr(self, "compose_varac_target_chip_group"):
            self._sync_compose_combo_chips(self.compose_varac_target_combo, self.compose_varac_target_chip_group)
        if hasattr(self, "compose_js8_plain_kind_combo") and hasattr(self, "compose_js8_plain_kind_chip_group"):
            self._sync_compose_combo_chips(self.compose_js8_plain_kind_combo, self.compose_js8_plain_kind_chip_group)

    def _clear_compose_radio_chips(self) -> None:
        if not hasattr(self, "compose_radio_chip_layout"):
            return
        group = getattr(self, "compose_radio_chip_group", None)
        if isinstance(group, QButtonGroup):
            for button in list(group.buttons()):
                group.removeButton(button)
                button.deleteLater()
        while self.compose_radio_chip_layout.count():
            item = self.compose_radio_chip_layout.takeAt(0)
            widget = item.widget()
            if widget is not None:
                widget.deleteLater()

    def _refresh_compose_radio_chips(self) -> None:
        if not hasattr(self, "compose_radio_chip_layout") or not hasattr(self, "compose_radio_combo"):
            return
        self._clear_compose_radio_chips()
        theme = resolve_theme(self.settings)
        selected_id = 0
        try:
            selected_id = int(self.compose_radio_combo.currentData() or 0)
        except Exception:
            selected_id = 0
        for target in self._compose_radio_targets:
            label = self._compose_radio_short_label(target.profile) or target.label
            chip = QPushButton(label)
            chip.setCheckable(True)
            chip_h = button_height_for_font(chip)
            chip.setMinimumHeight(chip_h)
            chip.setMaximumHeight(chip_h)
            chip.setMaximumWidth(110)
            chip.setSizePolicy(QSizePolicy.Fixed, QSizePolicy.Fixed)
            chip.setToolTip(target.label)
            chip.setProperty("compose_radio_id", int(target.radio_id))
            chip.clicked.connect(lambda _checked=False, radio_id=target.radio_id: self._select_compose_radio_id(radio_id))
            chip.setStyleSheet(button_style("primary" if target.radio_id == selected_id else "muted", theme))
            if target.radio_id == selected_id:
                chip.setChecked(True)
            self.compose_radio_chip_group.addButton(chip)
            self.compose_radio_chip_layout.addWidget(chip)
        self.compose_radio_chip_layout.addStretch(1)
        if hasattr(self, "compose_radio_chip_container"):
            self.compose_radio_chip_container.setVisible(bool(self._compose_radio_targets))

    def _sync_compose_radio_chips(self) -> None:
        if not hasattr(self, "compose_radio_chip_group") or not hasattr(self, "compose_radio_combo"):
            return
        theme = resolve_theme(self.settings)
        try:
            selected_id = int(self.compose_radio_combo.currentData() or 0)
        except Exception:
            selected_id = 0
        for button in self.compose_radio_chip_group.buttons():
            try:
                radio_id = int(button.property("compose_radio_id") or 0)
            except Exception:
                radio_id = 0
            selected = radio_id == selected_id
            button.setChecked(selected)
            button.setStyleSheet(button_style("primary" if selected else "muted", theme))

    def _selected_compose_js8_msg_auth_key(self) -> Dict[str, str]:
        if not hasattr(self, "compose_js8_auth_key_combo"):
            return {}
        data = self.compose_js8_auth_key_combo.currentData()
        if isinstance(data, dict):
            key_text = str(data.get("key", "") or "").strip()
            if key_text:
                return {"label": str(data.get("label", "") or "").strip(), "key": key_text}
        return {}

    def _compose_spotter_command(self, *, refresh_datecode: bool = False) -> str:
        message_text = self._compose_spotter_message_text(
            sign_for_target=True,
            refresh_datecode=refresh_datecode,
        )
        target = self._compose_rf_target_text(self.compose_js8_target_edit.text()) if hasattr(self, "compose_js8_target_edit") else ""
        if self._compose_send_as_msg() and not target:
            return ""
        return " ".join(
            part for part in (target, "MSG" if self._compose_send_as_msg() else "", message_text) if part
        ).strip()

    def _compose_spotter_message_text(
        self,
        *,
        sign_for_target: bool = False,
        refresh_datecode: bool = False,
    ) -> str:
        form_data = self.compose_form_combo.currentData() if hasattr(self, "compose_form_combo") else None
        code = ""
        if not isinstance(form_data, dict) or form_data.get("kind") != "spotter_form":
            if (
                int(getattr(self, "_compose_spotter_expect_active_id", 0) or 0) > 0
                and str(getattr(self, "_compose_spotter_working_response", "") or "").strip()
            ):
                active_key = ""
                for row in getattr(self, "_compose_spotter_expect_entries", []) or []:
                    try:
                        if int(row.get("id", 0) or 0) == int(self._compose_spotter_expect_active_id):
                            active_key = str(row.get("expect_key", "") or "").strip().upper()
                            break
                    except (TypeError, ValueError):
                        continue
                if active_key:
                    code = active_key
            if not code:
                return ""
        else:
            code = str(form_data.get("code", "") or "").strip().upper()
        target = self._compose_rf_target_text(self.compose_js8_target_edit.text()) if hasattr(self, "compose_js8_target_edit") else ""
        if (
            int(getattr(self, "_compose_spotter_expect_active_id", 0) or 0) > 0
            and not bool(getattr(self, "_compose_spotter_working_response_dirty", False))
            and str(getattr(self, "_compose_spotter_working_response", "") or "").strip()
        ):
            _saved_target, message_text = self._compose_spotter_expect_response_parts(
                self._compose_spotter_working_response,
                code,
            )
        else:
            values = self._compose_field_values()
            if refresh_datecode:
                values = self._compose_spotter_refresh_date_fields(values, self._compose_timestamp_utc)
            message_text = serialize_spotter_form_payload(
                code,
                self._compose_spotter_fields,
                values,
                comments=values.get(SPOTTER_COMMENTS_KEY, ""),
            )
        if refresh_datecode:
            refreshed = update_mcform_response_datecode(
                message_text,
                code,
                moment=self._compose_timestamp_utc,
            )
            if refreshed:
                message_text = refreshed
        if sign_for_target and self._compose_js8_msg_auth_selected():
            selected_key = self._selected_compose_js8_msg_auth_key()
            if selected_key.get("key") and target and self._compose_operator_callsign():
                trailing_datecode = ""
                date_match = re.search(r"(?:^|\s)(#[A-Z0-9]{4})$", message_text, flags=re.IGNORECASE)
                if date_match:
                    trailing_datecode = date_match.group(1).upper()
                auth_message = message_text
                if trailing_datecode:
                    auth_message = message_text[: date_match.start(1)].rstrip()
                signed = sign_js8_text(
                    self._compose_operator_callsign(),
                    target,
                    auth_message,
                    selected_key.get("key", ""),
                    include_datecode=bool(
                        hasattr(self, "compose_js8_auth_datecode_chk") and self.compose_js8_auth_datecode_chk.isChecked()
                    ) and not bool(trailing_datecode),
                    datecode=trailing_datecode,
                )
                message_text = signed.signed_text
        return message_text

    @staticmethod
    def _compose_spotter_refresh_date_fields(
        values: Mapping[str, str],
        moment: datetime.datetime,
    ) -> Dict[str, str]:
        """Copy field values and refresh recognized MCForm date fields only.

        This helper never writes to widgets or the Expect store.  It is used
        for preview/send serialization so the UI draft remains operator-owned
        while an outgoing message gets a fresh date at final preparation.
        """
        updated = {str(key): str(value or "") for key, value in values.items()}
        date_value = format_compose_zulu(moment)
        for field_key, value in list(updated.items()):
            normalized = re.sub(r"[^A-Z0-9]", "", str(field_key or "").upper())
            if normalized in {"DA", "DATE", "DATEUTC", "DATETIME", "DTG", "TIMESTAMP"}:
                updated[field_key] = date_value
        return updated

    def _compose_has_valid_form_selection(self) -> bool:
        data = self.compose_form_combo.currentData() if hasattr(self, "compose_form_combo") else None
        if isinstance(data, dict) and data.get("kind") == "standard":
            return True
        if isinstance(data, dict) and data.get("kind") == "custom":
            return bool(str(data.get("path", "") or "").strip())
        if isinstance(data, dict) and data.get("kind") == "spotter_form":
            return bool(str(data.get("code", "") or "").strip())
        return False

    @staticmethod
    def _compose_profile_bool(profile: Dict[str, Any], key: str) -> bool:
        value = profile.get(key)
        if isinstance(value, bool):
            return value
        if isinstance(value, (int, float)):
            return int(value) != 0
        if isinstance(value, str):
            return value.strip().lower() in {"1", "true", "yes", "on"}
        return bool(value)

    @staticmethod
    def _compose_profile_text(profile: Dict[str, Any], key: str) -> str:
        return str(profile.get(key, "") or "").strip()

    def _compose_profile_capabilities(self, profile: Dict[str, Any]) -> Tuple[str, ...]:
        caps: List[str] = []
        if (
            self._compose_profile_bool(profile, "use_flmsg")
            or self._compose_profile_text(profile, "flmsg_path")
            or self._compose_profile_text(profile, "flmsg_message_path")
        ):
            caps.append("FLMsg")
        if (
            self._compose_profile_bool(profile, "use_flamp")
            or self._compose_profile_text(profile, "flamp_path")
            or self._compose_profile_text(profile, "flamp_message_path")
        ):
            caps.append("FLAmp")
        if (
            self._compose_profile_bool(profile, "use_varac")
            or self._compose_profile_text(profile, "varac_install_path")
            or self._compose_profile_text(profile, "varac_outbox_dir")
            or self._compose_profile_text(profile, "varac_bbs_dir")
            or self._compose_profile_bool(profile, "varac_bbs_vault_enabled")
        ):
            caps.append("VarAC")
        if (
            self._compose_profile_bool(profile, "use_js8call")
            or self._compose_profile_text(profile, "js8_host")
            or self._compose_profile_text(profile, "js8_port")
        ):
            caps.append("JS8Call")
        return tuple(caps)

    def _compose_radio_label(self, profile: Dict[str, Any], capabilities: Sequence[str]) -> str:
        name = self._compose_profile_text(profile, "name") or f"Radio {profile.get('id', '')}".strip()
        model_bits = [
            self._compose_profile_text(profile, "radio_manufacturer"),
            self._compose_profile_text(profile, "radio_model"),
        ]
        model = " ".join(bit for bit in model_bits if bit).strip()
        device_class = self._compose_profile_text(profile, "device_class")
        suffix: List[str] = []
        if model:
            suffix.append(model)
        if device_class and device_class != "tx_rx":
            suffix.append(device_class.replace("_", " ").title())
        if capabilities:
            suffix.append(", ".join(capabilities))
        return f"{name} - {' - '.join(suffix)}" if suffix else name

    def _compose_radio_short_label(self, profile: Dict[str, Any]) -> str:
        return self._compose_profile_text(profile, "name") or f"Radio {profile.get('id', '')}".strip()

    def _compose_radio_target_short_label(self, target: Optional[ComposeRadioTarget]) -> str:
        if target is None:
            return ""
        return self._compose_radio_short_label(target.profile) or target.label

    def _load_compose_radio_targets(self) -> List[ComposeRadioTarget]:
        try:
            profiles = list(self._multi_radio_store.list_device_profiles())
        except Exception:
            profiles = []
        targets: List[ComposeRadioTarget] = []
        for profile in profiles:
            if not self._compose_profile_bool(profile, "enabled"):
                continue
            # Observer / SDR profiles may own an isolated JS8Call instance for
            # receive ingestion and health reporting.  That ownership must not
            # make the receiver a Compose destination or confer transmit
            # authority through any other configured application path.
            if not js8_profile_allows_transmit(profile):
                continue
            try:
                radio_id = int(profile.get("id", 0) or 0)
            except Exception:
                radio_id = 0
            if radio_id <= 0:
                continue
            capabilities = self._compose_profile_capabilities(profile)
            if not capabilities:
                continue
            targets.append(
                ComposeRadioTarget(
                    radio_id=radio_id,
                    label=self._compose_radio_label(profile, capabilities),
                    profile=dict(profile),
                    capabilities=capabilities,
                )
            )
        return targets

    def _runtime_primary_radio_id(self) -> int:
        try:
            profile = self._multi_radio_store.get_runtime_primary_device_profile()
        except Exception:
            profile = None
        if not isinstance(profile, dict):
            return 0
        try:
            return int(profile.get("id", 0) or 0)
        except Exception:
            return 0

    def _refresh_compose_radio_targets(self, *, force: bool = False) -> None:
        if not hasattr(self, "compose_radio_combo"):
            return
        if self._compose_radio_targets_loaded and not force:
            return
        saved_id = 0
        try:
            saved_id = int(self.settings.get("messages_compose_radio_id", 0) or 0)
        except Exception:
            saved_id = 0
        current_id = 0
        data = self.compose_radio_combo.currentData()
        try:
            current_id = int(data or 0)
        except Exception:
            current_id = 0
        preferred_id = current_id or saved_id or self._runtime_primary_radio_id()
        targets = self._load_compose_radio_targets()
        js8_mode = str(getattr(self, "_compose_mode", "nbems") or "nbems") == "js8"
        spotter_mode = str(getattr(self, "_compose_mode", "nbems") or "nbems") == "spotter"
        commstat_mode = str(getattr(self, "_compose_mode", "nbems") or "nbems") == "commstat_rf"
        display_targets = (
            [target for target in targets if "JS8Call" in tuple(target.capabilities)]
            if js8_mode or spotter_mode or commstat_mode
            else list(targets)
        )
        if not display_targets:
            display_targets = list(targets)
        self.compose_radio_combo.blockSignals(True)
        try:
            self.compose_radio_combo.clear()
            selected_index = 0
            for target in display_targets:
                label = self._compose_radio_target_short_label(target)
                self.compose_radio_combo.addItem(label, target.radio_id)
                if preferred_id and target.radio_id == preferred_id:
                    selected_index = self.compose_radio_combo.count() - 1
            if self.compose_radio_combo.count():
                self.compose_radio_combo.setCurrentIndex(selected_index)
        finally:
            self.compose_radio_combo.blockSignals(False)
        self._compose_radio_targets = display_targets
        self._compose_radio_targets_loaded = True
        self._refresh_compose_radio_chips()

    def _refresh_compose_radios_clicked(self) -> None:
        self._cancel_compose_js8_selected_target_worker()
        self._compose_js8_selected_target_generation += 1
        self._compose_js8_selected_target_pending_context = {}
        self._compose_js8_selected_target_state = "unknown"
        self._compose_js8_selected_target_value = ""
        self._refresh_compose_js8_selected_target_cue()
        self._refresh_compose_setup_discovery(force=True)
        self._update_compose_preview()

    def _select_compose_radio_id(self, radio_id: object) -> bool:
        if not hasattr(self, "compose_radio_combo"):
            return False
        try:
            target_id = int(radio_id or 0)
        except Exception:
            target_id = 0
        if target_id <= 0:
            return False
        for idx in range(self.compose_radio_combo.count()):
            try:
                if int(self.compose_radio_combo.itemData(idx) or 0) == target_id:
                    self.compose_radio_combo.setCurrentIndex(idx)
                    return True
            except Exception:
                continue
        return False

    def _selected_compose_radio_target(self) -> Optional[ComposeRadioTarget]:
        # Selection reads are intentionally cache-only.  Preview rendering is
        # called on every edit and must never turn into a radio-store query.
        # Setup refreshes and explicit actions populate this cache first.
        if not self._compose_radio_targets_loaded:
            return None
        if not hasattr(self, "compose_radio_combo"):
            return None
        try:
            radio_id = int(self.compose_radio_combo.currentData() or 0)
        except Exception:
            radio_id = 0
        for target in self._compose_radio_targets:
            if target.radio_id == radio_id:
                return target
        return self._compose_radio_targets[0] if self._compose_radio_targets else None

    def _on_compose_radio_changed(self) -> None:
        target = self._selected_compose_radio_target()
        if target is not None:
            try:
                self.settings.set("messages_compose_radio_id", int(target.radio_id))
            except Exception:
                pass
        self._compose_message_folder_root_cache = None
        self._clear_spotter_form_caches()
        self._sync_compose_radio_chips()
        self._refresh_compose_message_folder_options(force=True)
        self._refresh_compose_destination_plans()
        if hasattr(self, "compose_publish_bbs_chk") and self.compose_publish_bbs_chk.isChecked():
            self._refresh_compose_bbs_location_targets()
        self._install_compose_target_completers()
        if str(getattr(self, "_compose_mode", "nbems") or "nbems") == "spotter":
            self._refresh_compose_forms()
        self._start_compose_target_guidance_worker()
        self._update_compose_preview()
        self.request_compose_js8_selected_target_refresh()

    @staticmethod
    def _compose_parse_hhmm_minutes(value: object) -> Optional[int]:
        text = str(value or "").strip()
        match = re.match(r"^(\d{1,2}):(\d{2})", text)
        if not match:
            return None
        hour = int(match.group(1))
        minute = int(match.group(2))
        if hour > 23 or minute > 59:
            return None
        return hour * 60 + minute

    @staticmethod
    def _compose_schedule_minutes_to_end(day_utc: object, now_utc: datetime.datetime, start_min: int, end_min: int) -> Optional[int]:
        day = str(day_utc or "ALL").strip().upper()
        weekday = now_utc.strftime("%a").upper()[:3]
        day_aliases = {
            "MONDAY": "MON",
            "TUESDAY": "TUE",
            "WEDNESDAY": "WED",
            "THURSDAY": "THU",
            "FRIDAY": "FRI",
            "SATURDAY": "SAT",
            "SUNDAY": "SUN",
        }
        day = day_aliases.get(day, day[:3] if len(day) > 3 else day)
        if day not in {"", "ALL", "ANY", "*", weekday}:
            return None
        now_min = now_utc.hour * 60 + now_utc.minute
        if end_min <= start_min:
            active = now_min >= start_min or now_min < end_min
            if not active:
                return None
            return (end_min - now_min) % (24 * 60) or 24 * 60
        if start_min <= now_min < end_min:
            return end_min - now_min
        return None

    def _compose_peer_schedule_for_callsign(self, callsign: object) -> Optional[ComposePeerSchedule]:
        target = str(callsign or "").strip().upper()
        if not target:
            return None
        db_path = self._db_path()
        if not db_path or not db_path.exists():
            return None
        now_utc = datetime.datetime.now(datetime.timezone.utc)
        try:
            conn = sqlite3.connect(db_path)
            cur = conn.cursor()
            has_effective_view = conn.execute(
                "SELECT name FROM sqlite_master WHERE type='view' AND name='peer_hf_schedule_effective'"
            ).fetchone()
            table_name = "peer_hf_schedule_effective" if has_effective_view else "peer_hf_schedule"
            cur.execute(
                f"""
                SELECT owner_callsign, day_utc, start_utc, end_utc, band, mode, frequency
                FROM {table_name}
                WHERE UPPER(owner_callsign) = ?
                """,
                (target,),
            )
            rows = cur.fetchall()
            conn.close()
        except Exception as exc:
            log.debug("MessageViewer: failed loading peer schedule for %s: %s", target, exc)
            return None
        best: Optional[ComposePeerSchedule] = None
        for cs, day_utc, start_utc, end_utc, band, mode, freq in rows:
            start_min = self._compose_parse_hhmm_minutes(start_utc)
            end_min = self._compose_parse_hhmm_minutes(end_utc)
            if start_min is None or end_min is None:
                continue
            minutes_to_end = self._compose_schedule_minutes_to_end(day_utc, now_utc, start_min, end_min)
            if minutes_to_end is None:
                continue
            try:
                frequency = float(str(freq or "").strip())
            except Exception:
                frequency = None
            if frequency is not None and frequency > 1000:
                frequency = frequency / 1_000_000.0
            candidate = ComposePeerSchedule(
                callsign=str(cs or target).strip().upper(),
                band=str(band or "").strip().upper(),
                frequency_mhz=frequency,
                mode=str(mode or "").strip().upper(),
                minutes_to_end=int(minutes_to_end),
            )
            if best is None or candidate.minutes_to_end < best.minutes_to_end:
                best = candidate
        return best

    def _compose_intent_target(self) -> str:
        mode = str(getattr(self, "_compose_mode", "nbems") or "nbems")
        if mode == "commstat_rf" and hasattr(self, "compose_commstat_target_edit"):
            return self._compose_rf_target_text(self.compose_commstat_target_edit.text())
        if mode in {"js8", "spotter"} and hasattr(self, "compose_js8_target_edit"):
            return self._compose_rf_target_text(self.compose_js8_target_edit.text())
        return str((getattr(self, "_compose_intent", {}) or {}).get("recipient_callsign") or "").strip().upper()

    def _compose_last_heard_from_intent(self) -> Optional[ComposeLastHeard]:
        intent = dict(getattr(self, "_compose_intent", {}) or {})
        try:
            radio_id = int(intent.get("last_heard_radio_id") or intent.get("radio_id") or 0)
        except Exception:
            radio_id = 0
        if radio_id <= 0:
            return None
        return ComposeLastHeard(
            radio_id=radio_id,
            radio_label=str(intent.get("last_heard_radio_label") or intent.get("radio_label") or "").strip(),
            band=str(intent.get("last_heard_band") or intent.get("band") or "").strip().upper(),
            source=str(intent.get("last_heard_source") or intent.get("source_label") or intent.get("source") or "").strip(),
            age_label=str(intent.get("last_heard_age_label") or intent.get("age_label") or "").strip(),
        )

    @staticmethod
    def _compose_base_callsign(value: object) -> str:
        raw = str(value or "").strip().upper().lstrip("@")
        if not raw:
            return ""
        return re.sub(r"/(P|M|MM|QRP|SOTA|ROVER|[A-Z0-9]{1,4})$", "", raw)

    @staticmethod
    def _compose_age_label(ts_value: object) -> str:
        try:
            age = max(0.0, time.time() - float(ts_value or 0.0))
        except Exception:
            return ""
        if age < 90:
            return "just now"
        if age < 3600:
            return f"{int(age // 60)}m ago"
        if age < 86400:
            return f"{age / 3600.0:.1f}h ago"
        return f"{age / 86400.0:.1f}d ago"

    def _compose_map_age_seconds(self) -> int:
        intent = dict(getattr(self, "_compose_intent", {}) or {})
        for key in ("age_filter_seconds", "recency_seconds"):
            try:
                value = int(intent.get(key) or 0)
            except Exception:
                value = 0
            if value > 0:
                return value
        return 24 * 60 * 60

    def _compose_path_evidence_for_target(self, target: object) -> Optional[ComposePathEvidence]:
        target_call = self._compose_base_callsign(target)
        my_call = self._compose_base_callsign(self._compose_operator_callsign())
        if not target_call or not my_call or target_call == my_call:
            return None
        db_path = self._db_path()
        if not db_path or not db_path.exists():
            return None
        cutoff = time.time() - self._compose_map_age_seconds()
        try:
            conn = sqlite3.connect(db_path)
            cur = conn.cursor()
            cur.execute(
                """
                SELECT ts, snr, band, source_radio_id
                  FROM js8_links
                 WHERE ts >= ?
                   AND ((UPPER(origin)=? AND UPPER(destination)=?)
                    OR  (UPPER(origin)=? AND UPPER(destination)=?))
                 ORDER BY ts DESC
                 LIMIT 1
                """,
                (cutoff, my_call, target_call, target_call, my_call),
            )
            direct = cur.fetchone()
            if direct:
                ts, snr, band, radio_id = direct
                conn.close()
                try:
                    radio_id_int = int(radio_id or 0)
                except Exception:
                    radio_id_int = 0
                return ComposePathEvidence(
                    kind="direct",
                    radio_id=radio_id_int,
                    band=str(band or "").strip().upper(),
                    source="JS8Call",
                    age_label=self._compose_age_label(ts),
                    snr=float(snr) if snr is not None else None,
                )
            cur.execute(
                """
                WITH recent AS (
                    SELECT ts, origin, destination, snr, band
                      FROM js8_links
                     WHERE ts >= ?
                       AND origin IS NOT NULL
                       AND destination IS NOT NULL
                ),
                mine AS (
                    SELECT CASE WHEN UPPER(origin)=? THEN UPPER(destination) ELSE UPPER(origin) END AS relay,
                           MAX(ts) AS ts,
                           band
                      FROM recent
                     WHERE UPPER(origin)=? OR UPPER(destination)=?
                     GROUP BY relay
                ),
                theirs AS (
                    SELECT CASE WHEN UPPER(origin)=? THEN UPPER(destination) ELSE UPPER(origin) END AS relay,
                           MAX(ts) AS ts,
                           band
                      FROM recent
                     WHERE UPPER(origin)=? OR UPPER(destination)=?
                     GROUP BY relay
                )
                SELECT mine.relay,
                       MAX(mine.ts, theirs.ts) AS last_ts,
                       COALESCE(theirs.band, mine.band, '') AS band
                  FROM mine
                  JOIN theirs ON theirs.relay = mine.relay
                 WHERE mine.relay NOT IN (?, ?)
                 ORDER BY last_ts DESC
                 LIMIT 1
                """,
                (cutoff, my_call, my_call, my_call, target_call, target_call, target_call, my_call, target_call),
            )
            relay = cur.fetchone()
            conn.close()
            if relay:
                relay_call, ts, band = relay
                return ComposePathEvidence(
                    kind="relay",
                    band=str(band or "").strip().upper(),
                    source="JS8Call",
                    relay=str(relay_call or "").strip().upper(),
                    age_label=self._compose_age_label(ts),
                )
        except Exception as exc:
            log.debug("MessageViewer: failed loading compose path evidence for %s: %s", target_call, exc)
            try:
                conn.close()
            except Exception:
                pass
        return None

    def _refresh_compose_context_label(self) -> None:
        intent = dict(getattr(self, "_compose_intent", {}) or {})
        source = str(intent.get("source", "") or "").strip().lower()
        expect_context = source in {
            "fio_spotter_expect",
            "fio_spotter_expect_view",
            "fio_spotter_expect_create",
            "fio_spotter_form_expect",
        }
        map_context = bool(source == "map" and (intent.get("recipient_callsign") or intent.get("title")))
        visible = bool(expect_context or map_context)
        if not visible:
            if hasattr(self, "compose_context_row_widget"):
                self.compose_context_row_widget.setVisible(False)
            if hasattr(self, "compose_return_expect_btn"):
                self.compose_return_expect_btn.setVisible(False)
            return
        if expect_context:
            key = str(intent.get("expect_key", "") or "").strip().upper()
            entry_id = int(intent.get("expect_entry_id", 0) or 0)
            is_view = bool(intent.get("expect_view", False) and entry_id)
            if entry_id:
                detail = f"saved entry {entry_id}"
            else:
                detail = "new response"
            text = f"Opened from Expect: {key or 'MCF form'} · {detail}"
            if is_view:
                text += (
                    " · editing a working copy"
                    if bool(getattr(self, "_compose_expect_view_editing", True)) else
                    " · view only"
                )
            if hasattr(self, "compose_context_label"):
                self.compose_context_label.setText(text)
            if hasattr(self, "compose_clear_context_btn"):
                self.compose_clear_context_btn.setVisible(False)
            if hasattr(self, "compose_return_expect_btn"):
                self.compose_return_expect_btn.setVisible(True)
            if hasattr(self, "compose_edit_expect_copy_btn"):
                self.compose_edit_expect_copy_btn.setVisible(self._expect_view_is_read_only())
            if hasattr(self, "compose_context_row_widget"):
                self.compose_context_row_widget.setVisible(True)
            return
        target = str(intent.get("recipient_callsign") or intent.get("target") or "").strip().upper()
        source = str(intent.get("source_label") or intent.get("last_heard_source") or "").strip()
        bits = [f"Opened from map: {target}" if target else "Opened from map"]
        if source:
            bits.append(source)
        age = str(intent.get("last_heard_age_label") or "").strip()
        if age:
            bits.append(age)
        if hasattr(self, "compose_context_label"):
            self.compose_context_label.setText(" | ".join(bits))
        if hasattr(self, "compose_context_row_widget"):
            self.compose_context_row_widget.setVisible(True)
        if hasattr(self, "compose_clear_context_btn"):
            self.compose_clear_context_btn.setVisible(True)
        if hasattr(self, "compose_return_expect_btn"):
            self.compose_return_expect_btn.setVisible(False)
        if hasattr(self, "compose_edit_expect_copy_btn"):
            self.compose_edit_expect_copy_btn.setVisible(False)

    def _return_to_expect(self) -> None:
        """Return to Expect without persisting the Compose working copy."""
        intent = dict(getattr(self, "_compose_intent", {}) or {})
        entry_id = int(intent.get("expect_entry_id", 0) or 0)
        expect_key = str(intent.get("expect_key", "") or "").strip().upper()
        host = self.window()
        callback = getattr(host, "open_fio_spotter_expect", None)
        if callable(callback):
            callback(entry_id=entry_id, expect_key=expect_key)
            return
        self._set_compose_status(
            "Return to Expect is unavailable in this window; the working copy remains unsaved.",
            role="warning",
        )

    def _clear_compose_intent(self) -> None:
        self._compose_intent = {}
        self._update_compose_preview()

    def _compose_send_guidance_summary(
        self, recommendation: ComposeSendRecommendation, *, target: str = ""
    ) -> str:
        radio_label = str(recommendation.radio_label or "").strip()
        if not radio_label:
            return "No JS8 radio configured"
        band = str(recommendation.band or "").strip()
        if recommendation.frequency_mhz:
            band_suffix = f" {band}" if band else ""
            return f"Tune {radio_label}: {recommendation.frequency_mhz:.3f} MHz{band_suffix}"
        if recommendation.path_kind:
            if band:
                return f"Use {radio_label}: path on {band}"
            return f"Use {radio_label}: path found"
        if band:
            return f"Use {radio_label}: last heard on {band}"
        if target:
            return f"Use {radio_label} for {target}"
        return f"Using {radio_label}"

    def _compose_send_guidance_tooltip(
        self, recommendation: ComposeSendRecommendation, *, target: str = ""
    ) -> str:
        parts: List[str] = []
        if target:
            parts.append(f"To {target}")
        if recommendation.radio_label:
            parts.append(f"Send from {recommendation.radio_label}")
        if recommendation.frequency_mhz:
            freq = f"{recommendation.frequency_mhz:.3f} MHz"
            band = f" {recommendation.band}" if recommendation.band else ""
            parts.append(f"Peer schedule now: {freq}{band}".strip())
        elif recommendation.band:
            parts.append(f"Band: {recommendation.band}")
        if recommendation.reason:
            parts.append(recommendation.reason)
        return "\n".join(parts) if parts else "Choose a JS8Call radio before sending."

    def _compose_refresh_send_guidance(self) -> ComposeSendRecommendation:
        mode = str(getattr(self, "_compose_mode", "nbems") or "nbems")
        if mode not in {"js8", "spotter", "commstat_rf"}:
            if hasattr(self, "compose_guidance_row_widget"):
                self.compose_guidance_row_widget.setVisible(False)
            self._compose_send_recommendation = ComposeSendRecommendation()
            return self._compose_send_recommendation
        radio_target = self._selected_compose_radio_target()
        selected_radio_id = radio_target.radio_id if radio_target is not None else 0
        target = self._compose_intent_target()
        if self._is_message_group_candidate(target, configured_groups=self._configured_message_group_names()):
            peer_schedule = None
        else:
            peer_schedule = self._compose_peer_schedule_for_callsign(target)
        options = [
            ComposeRadioOption(radio_id=target.radio_id, label=self._compose_radio_short_label(target.profile))
            for target in self._compose_radio_targets
            if "JS8Call" in tuple(target.capabilities)
        ]
        recommendation = recommend_compose_send_path(
            options,
            peer_schedule=peer_schedule,
            path_evidence=None if peer_schedule else self._compose_path_evidence_for_target(target),
            last_heard=self._compose_last_heard_from_intent(),
            selected_radio_id=selected_radio_id,
        )
        self._compose_send_recommendation = recommendation
        if recommendation.radio_id and recommendation.radio_id != selected_radio_id:
            self._select_compose_radio_id(recommendation.radio_id)
        text = self._compose_send_guidance_summary(recommendation, target=target)
        tooltip = self._compose_send_guidance_tooltip(recommendation, target=target)
        if hasattr(self, "compose_guidance_label"):
            self.compose_guidance_label.setText(text)
            self.compose_guidance_label.setToolTip(tooltip)
        if hasattr(self, "compose_guidance_row_widget"):
            self.compose_guidance_row_widget.setToolTip(tooltip)
            self.compose_guidance_row_widget.setVisible(True)
        if hasattr(self, "compose_tune_recommended_btn"):
            self.compose_tune_recommended_btn.setVisible(bool(recommendation.tune_available and recommendation.frequency_mhz))
            self.compose_tune_recommended_btn.setEnabled(bool(recommendation.radio_id and recommendation.frequency_mhz))
            self.compose_tune_recommended_btn.setStyleSheet(button_style("warning", resolve_theme(self.settings)))
        return recommendation

    def _compose_tune_recommended_radio(self) -> None:
        recommendation = getattr(self, "_compose_send_recommendation", ComposeSendRecommendation())
        if not recommendation.frequency_mhz:
            self._set_compose_status("No recommended frequency is available for this recipient.", role="warning")
            return
        meta = {
            "freq": recommendation.frequency_mhz,
            "band": recommendation.band,
            "mode": recommendation.mode,
            "auto_tune": True,
            "target_device_profile_id": recommendation.radio_id,
        }
        ok = perform_qsy(self.window(), meta)
        if ok:
            self._set_compose_status(
                f"Tune requested for {recommendation.radio_label or 'selected radio'} at {recommendation.frequency_mhz:.3f} MHz.",
                role="success",
            )
        else:
            self._set_compose_status("Tune request was blocked or could not be applied.", role="warning")

    def _compose_confirm_peer_schedule_before_send(self) -> bool:
        # Target-scoped schedule/path lookups are resolved by the background
        # guidance worker.  A Send click must never block the GUI on SQLite.
        recommendation = getattr(self, "_compose_send_recommendation", ComposeSendRecommendation())
        if not recommendation.tune_available or not recommendation.frequency_mhz:
            return True
        radio_label = recommendation.radio_label or "the selected radio"
        band = f" {recommendation.band}" if recommendation.band else ""
        prompt = (
            f"Peer schedule guidance says {radio_label} should be on "
            f"{recommendation.frequency_mhz:.3f} MHz{band} before sending.\n\n"
            "Tune the radio now before sending?"
        )
        msg = QMessageBox(self)
        msg.setWindowTitle("Tune Before Send")
        msg.setText(prompt)
        tune_btn = msg.addButton("Tune Now", QMessageBox.AcceptRole)
        send_btn = msg.addButton("Send Anyway", QMessageBox.DestructiveRole)
        msg.addButton("Cancel", QMessageBox.RejectRole)
        msg.exec()
        clicked = msg.clickedButton()
        if clicked == tune_btn:
            self._compose_tune_recommended_radio()
            return False
        if clicked == send_btn:
            self._set_compose_status(
                "Sending without tuning to the active peer schedule frequency.",
                role="warning",
            )
            return True
        self._set_compose_status("Send cancelled before radio tune.", role="info")
        return False

    def prefill_compose_intent(self, intent: Mapping[str, object]) -> None:
        """Apply a navigation handoff as one recoverable Compose transaction."""

        MessageViewerTab._begin_compose_update(self)
        completed = False
        try:
            self._apply_prefill_compose_intent(intent)
            completed = True
        finally:
            self._compose_spotter_source_loading = False
            MessageViewerTab._end_compose_update(self, flush=completed)

    def _apply_prefill_compose_intent(self, intent: Mapping[str, object]) -> None:
        data = compose_intent_from_mapping(intent).as_dict()
        self._compose_intent = data
        self._compose_expect_view_editing = not bool(data.get("expect_view", False))
        mode = str(data.get("transport") or data.get("mode") or "js8").strip().lower()
        requested_spotter_form = str(
            intent.get("spotter_form_code") or data.get("spotter_form_code") or ""
        ).strip().upper()
        if mode in {"spotter", "js8spotter", "fiospotter"}:
            self._compose_spotter_requested_form_code = requested_spotter_form
        if hasattr(self, "compose_mode_selector"):
            row = (
                4
                if mode in {"mesh", "meshcore", "meshtastic"}
                else 3
                if mode in {"commstat", "commstat_rf"}
                else 2
                if mode in {"spotter", "js8spotter", "fiospotter"}
                else 1
                if mode in {"js8", "js8call", "message", "traffic"}
                else 0
            )
            if self.compose_mode_selector.count() > row:
                self.compose_mode_selector.setCurrentRow(row)
        target = str(data.get("recipient_callsign") or data.get("target") or "").strip().upper()
        if target:
            if hasattr(self, "compose_js8_target_edit"):
                self.compose_js8_target_edit.setText(target)
            if hasattr(self, "compose_commstat_target_edit"):
                self.compose_commstat_target_edit.setText(target)
        body = str(data.get("body") or data.get("message") or "").strip()
        if body and hasattr(self, "compose_js8_plain_text_edit"):
            self.compose_js8_plain_text_edit.setPlainText(body)
        if mode in {"mesh", "meshcore", "meshtastic"}:
            self._refresh_compose_mesh_targets(force=True)
            self._compose_mesh_pending_intent = (self._compose_mesh_generation, dict(data))
            adapter_id = str(data.get("adapter_id") or "")
            source_combo = getattr(self, "compose_mesh_source_combo", None)
            if isinstance(source_combo, QComboBox) and adapter_id:
                for index in range(source_combo.count()):
                    config = source_combo.itemData(index)
                    if str(getattr(config, "adapter_id", "") or "") == adapter_id:
                        source_combo.setCurrentIndex(index)
                        break
            destination_kind = str(data.get("destination_kind") or ("direct" if data.get("destination_id") else "channel"))
            self._compose_set_combo_data(getattr(self, "compose_mesh_destination_kind_combo", None), destination_kind)
            self._on_compose_mesh_source_changed()
            self._compose_set_combo_data(getattr(self, "compose_mesh_channel_combo", None), str(data.get("channel_id") or ""))
            self._compose_set_combo_data(getattr(self, "compose_mesh_node_combo", None), str(data.get("destination_id") or data.get("node_id") or ""))
            if body and hasattr(self, "compose_mesh_text_edit"):
                self.compose_mesh_text_edit.setPlainText(body)
            self._on_compose_mesh_destination_changed()
        expect_entry_id = int(data.get("expect_entry_id", 0) or 0)
        if mode in {"spotter", "js8spotter", "fiospotter"} and expect_entry_id > 0:
            self._refresh_compose_spotter_expect_entries()
            combo = getattr(self, "compose_spotter_source_combo", None)
            if isinstance(combo, QComboBox):
                for index in range(combo.count()):
                    item = combo.itemData(index)
                    entry = item.get("entry", {}) if isinstance(item, dict) else {}
                    if isinstance(entry, dict) and int(entry.get("id", 0) or 0) == expect_entry_id:
                        if combo.currentIndex() == index:
                            loaded = self._on_compose_spotter_source_changed()
                        else:
                            # Apply the one-shot navigation transaction
                            # directly. Qt signal exceptions are otherwise
                            # reported outside this call stack, preventing the
                            # navigation boundary from showing its recoverable
                            # failure state.
                            blocked = combo.blockSignals(True)
                            try:
                                combo.setCurrentIndex(index)
                            finally:
                                combo.blockSignals(blocked)
                            loaded = self._on_compose_spotter_source_changed()
                        if not loaded:
                            raise ValueError("saved CommsPlan Spotter response could not be decoded")
                        break
        if requested_spotter_form:
            self._select_compose_spotter_form_code(requested_spotter_form)
        self._apply_compose_expect_view_state()
        # Mode activation already refreshes this cache when required. Reusing
        # it here avoids a second synchronous runtime-store scan during an
        # Expect View handoff while still loading it when absent.
        self._refresh_compose_radio_targets(force=False)
        last_heard = self._compose_last_heard_from_intent()
        if last_heard is not None:
            self._select_compose_radio_id(last_heard.radio_id)
        self._update_compose_preview()

    def _compose_radio_message_paths(self, target: Optional[ComposeRadioTarget]) -> Dict[str, str]:
        if target is None:
            return {}
        profile = target.profile
        return {
            "flmsg": self._compose_profile_text(profile, "flmsg_message_path"),
            "flamp": self._compose_profile_text(profile, "flamp_message_path"),
            "varac": self._compose_profile_text(profile, "varac_incoming_path"),
        }

    def _compose_bbs_targets_for_radio(self, target: Optional[ComposeRadioTarget]) -> List[Dict[str, str]]:
        """Return station-owned logical locations; the radio does not own BBS membership."""

        out: List[Dict[str, str]] = []
        for raw in self._varac_bbs_copy_targets():
            if str(raw.get("kind", "") or "") != "location" or not bool(raw.get("valid", False)):
                continue
            location_id = str(raw.get("location_id", "") or "").strip()
            name = str(raw.get("location_name", "") or raw.get("label", "") or location_id).strip()
            if not location_id:
                continue
            detail = str(raw.get("detail", "") or "").strip()
            out.append(
                {
                    "id": location_id,
                    "label": name,
                    "kind": "location",
                    "location_id": location_id,
                    "location_name": name,
                    "detail": detail,
                    "is_default": "1" if bool(raw.get("is_default", False)) else "0",
                }
            )
        return out

    def _refresh_compose_bbs_location_targets(self) -> None:
        selector = getattr(self, "compose_bbs_location_selector", None)
        if not isinstance(selector, DropdownChecklist):
            return
        saved_raw = self.settings.get("managed_bbs_compose_location_ids", []) or []
        if isinstance(saved_raw, str):
            saved = [value.strip() for value in saved_raw.split(",") if value.strip()]
        else:
            saved = [str(value or "").strip() for value in saved_raw if str(value or "").strip()]
        current = sorted(selector.selected_values())
        targets = self._compose_bbs_targets_for_radio(self._selected_compose_radio_target())
        self._compose_bbs_targets_cache = list(targets)
        valid_ids = {target["location_id"] for target in targets}
        selected = [value for value in (current or saved) if value in valid_ids]
        if not selected:
            selected = [target["location_id"] for target in targets if target.get("is_default") == "1"][:1]
        options = []
        for target in targets:
            label = target["label"]
            if target.get("is_default") == "1":
                label = f"{label} · Default"
            options.append((target["location_id"], label))
        selector.blockSignals(True)
        try:
            selector.set_options(options, selected_values=selected, select_all_when_empty=False)
        finally:
            selector.blockSignals(False)
        selector.setEnabled(bool(options))

    def _selected_compose_bbs_targets(self) -> List[Dict[str, str]]:
        selector = getattr(self, "compose_bbs_location_selector", None)
        if not isinstance(selector, DropdownChecklist):
            return []
        selected = selector.selected_values()
        return [
            target
            for target in list(getattr(self, "_compose_bbs_targets_cache", []) or [])
            if target.get("location_id") in selected
        ]

    def _selected_compose_bbs_target(self) -> Optional[Dict[str, str]]:
        targets = self._selected_compose_bbs_targets()
        return targets[0] if targets else None

    def _on_compose_bbs_publication_changed(self) -> None:
        selected = bool(
            hasattr(self, "compose_publish_bbs_chk") and self.compose_publish_bbs_chk.isChecked()
        )
        if selected and not getattr(self, "_compose_bbs_targets_cache", []):
            self._refresh_compose_bbs_location_targets()
        self._update_compose_preview()

    def _on_compose_bbs_location_changed(self) -> None:
        selector = getattr(self, "compose_bbs_location_selector", None)
        if isinstance(selector, DropdownChecklist):
            try:
                self.settings.set("managed_bbs_compose_location_ids", sorted(selector.selected_values()))
            except Exception:
                pass
        self._update_compose_preview()

    def _compose_message_root_dir(self, target: Optional[ComposeRadioTarget] = None) -> str:
        msg_paths = self._compose_radio_message_paths(target or self._selected_compose_radio_target())
        return str(msg_paths.get("flmsg", "") or "").strip()

    def _saved_compose_message_subfolders(self) -> Dict[str, str]:
        data = self.settings.get("messages_compose_subfolder_by_radio", {}) or {}
        return dict(data) if isinstance(data, dict) else {}

    def _saved_compose_message_subfolder(self, target: Optional[ComposeRadioTarget] = None) -> str:
        radio = target or self._selected_compose_radio_target()
        if radio is None:
            return ""
        saved = self._saved_compose_message_subfolders()
        return str(saved.get(str(radio.radio_id), "") or "").strip().replace("\\", "/")

    def _selected_compose_message_subfolder(self) -> str:
        if not hasattr(self, "compose_message_folder_combo"):
            return self._saved_compose_message_subfolder()
        data = self.compose_message_folder_combo.currentData()
        if isinstance(data, str):
            return data.strip().replace("\\", "/")
        return ""

    def _selected_compose_message_dir(self, target: Optional[ComposeRadioTarget] = None) -> str:
        radio = target or self._selected_compose_radio_target()
        root = self._compose_message_root_dir(radio)
        if not root:
            return ""
        selected = resolve_compose_message_folder(root, self._selected_compose_message_subfolder())
        return str(selected or Path(root).expanduser())

    def _save_compose_message_subfolder(self, subfolder: str, target: Optional[ComposeRadioTarget] = None) -> None:
        radio = target or self._selected_compose_radio_target()
        if radio is None:
            return
        saved = self._saved_compose_message_subfolders()
        saved[str(radio.radio_id)] = str(subfolder or "").strip().replace("\\", "/")
        try:
            self.settings.set("messages_compose_subfolder_by_radio", saved)
        except Exception:
            pass

    def _refresh_compose_message_folder_options(self, *, force: bool = False) -> None:
        if not hasattr(self, "compose_message_folder_combo"):
            return
        target = self._selected_compose_radio_target()
        root = self._compose_message_root_dir(target)
        radio_id = target.radio_id if target is not None else 0
        cache_key = f"{radio_id}:{Path(root).expanduser()}" if root else f"{radio_id}:"
        if not force and getattr(self, "_compose_message_folder_root_cache", None) == cache_key:
            return
        self._compose_message_folder_root_cache = cache_key
        saved = self._saved_compose_message_subfolder(target)
        current = self._selected_compose_message_subfolder()
        preferred = saved if force else (current or saved)
        options = discover_compose_message_folders(root) if root else []
        valid_relatives = {option.relative_path for option in options}
        if preferred not in valid_relatives:
            preferred = ""
        self.compose_message_folder_combo.blockSignals(True)
        try:
            self.compose_message_folder_combo.clear()
            for option in options:
                self.compose_message_folder_combo.addItem(option.label, option.relative_path)
            selected_index = 0
            for idx in range(self.compose_message_folder_combo.count()):
                if str(self.compose_message_folder_combo.itemData(idx) or "") == preferred:
                    selected_index = idx
                    break
            if self.compose_message_folder_combo.count():
                self.compose_message_folder_combo.setCurrentIndex(selected_index)
        finally:
            self.compose_message_folder_combo.blockSignals(False)
        enabled = bool(options)
        self.compose_message_folder_combo.setEnabled(enabled)
        if hasattr(self, "compose_choose_message_folder_btn"):
            self.compose_choose_message_folder_btn.setEnabled(enabled)
        self._configure_compose_combo_width(self.compose_message_folder_combo, floor=180)

    def _on_compose_message_folder_changed(self) -> None:
        target = self._selected_compose_radio_target()
        root = self._compose_message_root_dir(target)
        subfolder = self._selected_compose_message_subfolder()
        if root and resolve_compose_message_folder(root, subfolder) is not None:
            self._save_compose_message_subfolder(subfolder, target)
        self._refresh_compose_destination_plans()
        self._update_compose_preview()

    def _choose_compose_message_folder(self) -> None:
        target = self._selected_compose_radio_target()
        root_txt = self._compose_message_root_dir(target)
        if not root_txt:
            self._set_compose_status("Configure the selected radio's ICS/Messages path before choosing a compose folder.", role="warning")
            return
        root = Path(root_txt).expanduser()
        if not root.exists() or not root.is_dir():
            self._set_compose_status("The selected radio's ICS/Messages path is missing.", role="warning")
            return
        start = Path(self._selected_compose_message_dir(target) or str(root))
        chosen = QFileDialog.getExistingDirectory(self, "Choose Messages Folder", str(start))
        if not chosen:
            return
        rel = compose_message_relative_path(root, Path(chosen), max_depth=2)
        if rel is None:
            QMessageBox.warning(
                self,
                "Choose Messages Folder",
                "Choose a folder under the selected radio's ICS/Messages root, no more than two levels deep.",
            )
            return
        self._save_compose_message_subfolder(rel, target)
        self._compose_message_folder_root_cache = None
        self._refresh_compose_message_folder_options(force=True)
        self._refresh_compose_destination_plans()
        self._update_compose_preview()

    def _compose_cached_destinations(self) -> List[ComposeDestinationPlan]:
        """Return the last setup-time destination snapshot without filesystem I/O."""

        cached = list(getattr(self, "_compose_destination_plans_cache", []) or [])
        if not cached:
            return []
        base_name = self._compose_base_filename()
        signed_name = build_signed_filename(
            base_name,
            filename_policy=self._compose_fastlight_filename_policy(),
            operating_group=self._compose_fastlight_target_group(),
        )
        out: List[ComposeDestinationPlan] = []
        for plan in cached:
            if not plan.ready or not plan.directory:
                out.append(plan)
                continue
            name = signed_name if plan.key == "flamp" and self._compose_sign_flamp_selected() else base_name
            out.append(replace(plan, path=str(Path(plan.directory) / name), note=""))
        return out

    def _refresh_compose_destination_plans(self) -> List[ComposeDestinationPlan]:
        """Probe destination readiness after an explicit setup/action change."""

        radio_target = self._selected_compose_radio_target()
        msg_paths = self._compose_radio_message_paths(radio_target)
        target_group = self._compose_fastlight_target_group()
        filename_policy = self._compose_fastlight_filename_policy()
        plans = plan_compose_destinations(
            self._compose_base_filename(),
            send_target=self.compose_send_target_combo.currentText() if hasattr(self, "compose_send_target_combo") else "FLMsg",
            varac_target=self.compose_varac_target_combo.currentText() if hasattr(self, "compose_varac_target_combo") else "None",
            flmsg_dir=self._selected_compose_message_dir(radio_target) or str(msg_paths.get("flmsg", "") or "").strip(),
            flamp_dir=resolve_flamp_transmit_dir(str(msg_paths.get("flamp", "") or "").strip()),
            varac_outbox_dir=self._compose_varac_outbox_dir(radio_target),
            varac_bbs_dir="",
            sign_flamp_copy=bool(
                hasattr(self, "compose_sign_flamp_chk")
                and self.compose_sign_flamp_chk.isChecked()
            ),
            filename_policy=filename_policy,
            operating_group=target_group,
        )
        self._compose_destination_plans_cache = list(plans)
        return list(plans)

    def _compose_varac_outbox_dir(self, target: Optional[ComposeRadioTarget] = None) -> str:
        profile = target.profile if target is not None else {}
        configured = self._compose_profile_text(profile, "varac_outbox_dir") or str(self.settings.get("varac_outbox_dir", "") or "").strip()
        if configured:
            return configured
        install_txt = str(
            self._compose_profile_text(profile, "varac_install_path")
            or self.settings.get("varac_path", "")
            or self.settings.get("varac_install_path", "")
            or ""
        ).strip()
        install_path = Path(install_txt).expanduser() if install_txt else None
        if install_path is not None and install_path.exists() and install_path.is_file():
            install_path = install_path.parent
        candidates: List[Path] = []
        if install_path is not None:
            candidates.extend(
                [
                    install_path / "Outbox",
                    install_path / "OUTBOX",
                    install_path / "outbox",
                    install_path / "Outgoing",
                    install_path / "Outgoing Files",
                    install_path / "OutgoingFiles",
                ]
            )
        incoming_txt = str(self._compose_radio_message_paths(target).get("varac", "") or "").strip()
        if incoming_txt:
            incoming_path = Path(incoming_txt).expanduser()
            parent = incoming_path.parent
            for name in ("Outbox", "OUTBOX", "outbox", "Outgoing", "Outgoing Files", "OutgoingFiles"):
                candidates.append(parent / name)
        seen: set[str] = set()
        for candidate in candidates:
            key = str(candidate)
            if key in seen:
                continue
            seen.add(key)
            if candidate.exists() and candidate.is_dir():
                return str(candidate)
        return ""

    def _set_messages_mode(self, mode: str, *, save: bool = False, reset_compose: bool = False) -> None:
        mode_txt = str(mode or "Inbox").strip().title()
        if mode_txt not in {"Inbox", "Compose"}:
            mode_txt = "Inbox"
        self._messages_mode = mode_txt
        self._update_messages_mode_ui()
        if mode_txt == "Compose" and reset_compose:
            self._reset_compose_draft(status_text="Compose is ready.")
        if save:
            self._save_settings()

    def _leave_ops_traffic_scope(self) -> bool:
        active = getattr(self, "_ops_traffic_message_ids", None) is not None
        self._ops_traffic_message_ids = None
        self._ops_traffic_summary = None
        if active:
            self._traffic_action_filter = getattr(self, "_ops_traffic_previous_action_filter", "")
            if hasattr(self, "traffic_action_summary"):
                self.traffic_action_summary.set_active_bucket(self._traffic_action_filter)
            self._traffic_navigation_pending = False
            self._set_loading(False)
            # Force the normal intelligence chips to republish on return.
            self._intel_filter_bar_refresh_key = None
        return active

    def show_inbox_from_navigation(self) -> None:
        left_ops_scope = self._leave_ops_traffic_scope()
        self._set_messages_mode("Inbox", save=False)
        if left_ops_scope:
            self._load_projected_messages_into_table()

    def show_inbox_with_context(
        self,
        *,
        group_filter: str = "",
        topic_filter: str = "",
        query_filter: str = "",
        source_family: str = "",
        age_filter_seconds: object = 0,
        concern_only: object = False,
        state_filter: str = "",
        grid_filter: str = "",
        fema_region_filter: str = "",
        action_filter: str = "",
        traffic_message_ids: Sequence[str] | None = None,
        traffic_count_at_click: int = 0,
    ) -> None:
        self.show_inbox_from_navigation()
        incoming_bucket = str(action_filter or "").strip().lower()
        self._traffic_navigation_pending = incoming_bucket in {"reply", "relay", "review", "social"}
        self._traffic_loading_bucket = incoming_bucket
        self._traffic_loading_started = time.perf_counter()
        if self._traffic_navigation_pending:
            self._set_loading(True)
        self._close_message_reader_for_scope_change()
        if traffic_message_ids is not None and self._projection_primary_enabled:
            # Explicit dashboard view leaves saved Inbox controls untouched.
            if hasattr(self, "_filter_timer"):
                self._filter_timer.stop()
            self._ops_traffic_message_ids = tuple(dict.fromkeys(
                str(value).strip() for value in traffic_message_ids if str(value).strip()
            ))[:200]
            self._ops_traffic_previous_action_filter = getattr(self, "_traffic_action_filter", "")
            self._ops_traffic_count_at_click = max(0, int(traffic_count_at_click))
            self._ops_traffic_clicked_bucket = incoming_bucket
            self._ops_traffic_summary = None
            self._traffic_action_filter = incoming_bucket
            self.traffic_action_summary.set_active_bucket(incoming_bucket)
            self._update_visible_message_scope_label()
            self._update_map_context_filter_label()
            if hasattr(self, "message_intel_filter_widget"):
                self.message_intel_filter_widget.setVisible(False)
            self._load_projected_messages_into_table()
            return
        try:
            age_seconds = int(age_filter_seconds or 0)
        except Exception:
            age_seconds = 0
        concern_active = str(concern_only or "").strip().lower() in {"1", "true", "yes", "y", "on"} or bool(
            concern_only is True
        )
        self._map_context_filter = {
            "age_filter_seconds": age_seconds,
            "concern_only": concern_active,
            "state_filter": str(state_filter or "").strip().upper(),
            "grid_filter": str(grid_filter or "").strip().upper(),
            "fema_region_filter": str(fema_region_filter or "").strip().upper(),
        }
        source = str(source_family or "").strip().lower()
        source_values = self._message_context_source_values(source)
        normalized_source = normalize_message_source_family(source)
        focus = {
            "flmsg": "forms",
            "flamp": "forms",
            "forms": "forms",
            "nbems": "forms",
            "js8spotter": "spotter",
            "fiospotter": "spotter",
            "spotter": "spotter",
            "commstat": "commstat",
            "commstat_rf": "commstat",
            "js8call": "js8call",
            "js8": "js8call",
            "mesh": "mesh",
            "meshcore": "mesh",
            "meshtastic": "mesh",
            "mesh_client": "mesh",
            "local_mesh": "mesh",
            "varac": "varac",
        }.get(source, {
            "spotter": "spotter",
            "commstat": "commstat",
            "js8": "js8call",
            "meshcore": "mesh",
            "meshtastic": "mesh",
        }.get(normalized_source, "all"))
        self._set_inbox_focus(focus)
        # Setting focus can clear action state as part of a normal user focus
        # change. Restore the incoming Ops action only after focus is settled.
        self._traffic_action_filter = str(action_filter or "").strip().lower()
        if hasattr(self, "traffic_action_summary"):
            self.traffic_action_summary.set_active_bucket(self._traffic_action_filter)
        selected_group = self._select_context_group_filter(group_filter)
        selected_source = self._select_context_source_filter(source_values)
        search_parts: list[str] = []
        seen_parts: set[str] = set()
        for part in (
            str(query_filter or "").strip().lstrip("@"),
            str(topic_filter or "").strip(),
            str(grid_filter or "").strip().upper(),
            "" if selected_group else str(group_filter or "").strip().lstrip("@"),
            "" if selected_source else self._message_context_source_search_fallback(source),
        ):
            if not part:
                continue
            key = part.lower()
            if key in seen_parts:
                continue
            search_parts.append(part)
            seen_parts.add(key)
        search = " ".join(search_parts)
        if hasattr(self, "rcv_search"):
            self.rcv_search.setText(search)
        self._select_context_age_filter(age_seconds)
        # Reload from the canonical projection after every incoming scope value
        # is installed. This keeps Ops and Inbox on the same message population.
        if not self._load_projected_messages_into_table():
            # Lightweight test doubles and legacy embedders may not have the
            # projection lifecycle fields that a fully constructed tab owns.
            # Keep that compatibility path cache-only as well.
            if hasattr(self, "_projection_primary_enabled"):
                self._apply_message_filters_light()
            else:
                self._apply_message_filters()
        self._update_map_context_filter_label()

    def _select_context_age_filter(self, age_seconds: int) -> None:
        if not hasattr(self, "received_filter"):
            return
        seconds = int(age_seconds or 0)
        if seconds <= 0:
            idx = self.received_filter.findData(0)
            if idx >= 0:
                try:
                    self.received_filter.blockSignals(True)
                    self.received_filter.setCurrentIndex(idx)
                finally:
                    try:
                        self.received_filter.blockSignals(False)
                    except Exception:
                        pass
            return
        label_map = {
            15 * 60: "Last 15 min",
            60 * 60: "Last 1 hour",
            3 * 60 * 60: "Last 3 hours",
            6 * 60 * 60: "Last 6 hours",
            12 * 60 * 60: "Last 12 hours",
            24 * 60 * 60: "Last 24 hours",
            7 * 24 * 60 * 60: "Last 7 days",
        }
        idx = self.received_filter.findData(seconds)
        if idx < 0:
            self.received_filter.addItem(label_map.get(seconds, f"Last {seconds // 3600} hours"), seconds)
            idx = self.received_filter.findData(seconds)
        if idx >= 0:
            try:
                self.received_filter.blockSignals(True)
                self.received_filter.setCurrentIndex(idx)
            finally:
                try:
                    self.received_filter.blockSignals(False)
                except Exception:
                    pass

    @staticmethod
    def _message_context_source_values(source_family: object) -> list[str]:
        source = str(source_family or "").strip().lower()
        normalized = normalize_message_source_family(source)
        if source in {"", "fused", "mixed", "multiple_sources", "condition_alert"}:
            return []
        if source == "js8call" or normalized == "js8":
            return ["js8"]
        if source == "forms":
            return ["flmsg", "flamp"]
        if source == "nbems":
            return ["flmsg", "flamp"]
        if source == "fastlight":
            return ["flmsg", "flamp"]
        if source in {"js8spotter", "fiospotter"} or normalized == "spotter":
            return ["spotter"]
        if source == "commstat_rf" or normalized == "commstat":
            return ["commstat"]
        if source in {"mesh", "meshcore", "meshtastic", "mesh_client", "local_mesh"}:
            return ["mesh", "meshcore", "meshtastic"]
        if normalized in {"meshcore", "meshtastic"}:
            return [normalized]
        if normalized and normalized != "unknown":
            return [normalized]
        return [source]

    @staticmethod
    def _message_context_source_search_fallback(source_family: object) -> str:
        source = str(source_family or "").strip().lower()
        normalized = normalize_message_source_family(source)
        return {
            "js8call": "JS8Call",
            "js8": "JS8Call",
            "js8spotter": "Spotter",
            "fiospotter": "Spotter",
            "spotter": "Spotter",
            "commstat": "CommStat",
            "commstat_rf": "CommStat",
            "varac": "VarAC",
            "flmsg": "FLMSG",
            "flamp": "FLAMP",
            "mesh": "Mesh",
            "meshcore": "MeshCore",
            "meshtastic": "Meshtastic",
            "mesh_client": "Meshtastic",
        }.get(source, {
            "js8": "JS8Call",
            "spotter": "Spotter",
            "commstat": "CommStat",
            "meshcore": "MeshCore",
            "meshtastic": "Meshtastic",
        }.get(normalized, ""))

    @staticmethod
    def _dropdown_option_values(widget: object) -> set[str]:
        options = getattr(widget, "_options", []) or []
        values: set[str] = set()
        for option in options:
            if not isinstance(option, (list, tuple)) or not option:
                continue
            value = str(option[0] or "").strip()
            if value:
                values.add(value)
        return values

    def _select_context_group_filter(self, group_filter: object) -> bool:
        if not hasattr(self, "operating_group_filter"):
            return False
        group = self._normalize_message_group_filter_value(group_filter)
        if not group:
            return False
        options = self._dropdown_option_values(self.operating_group_filter)
        if group not in options:
            return False
        self.operating_group_filter.blockSignals(True)
        try:
            self.operating_group_filter.set_selected_values([group])
        finally:
            self.operating_group_filter.blockSignals(False)
        return group in self.operating_group_filter.selected_values()

    def _select_context_source_filter(self, source_values: list[str]) -> bool:
        if not hasattr(self, "source_filter") or not source_values:
            return False
        options = self._dropdown_option_values(self.source_filter)
        wanted = [
            canonical
            for value in source_values
            if (canonical := normalize_message_source_family(value)) in options
        ]
        if not wanted:
            return False
        self.source_filter.blockSignals(True)
        try:
            self.source_filter.set_selected_values(wanted)
        finally:
            self.source_filter.blockSignals(False)
        return bool(self.source_filter.selected_values() & set(wanted))

    def show_compose_from_navigation(self) -> None:
        self._set_messages_mode("Compose", save=False)

    def _open_traffic_summary(self) -> None:
        from freqinout.gui.traffic_summary_dialog import TrafficSummaryDialog
        path = self._db_path()
        if path is None:
            QMessageBox.warning(self, "Traffic Summary", "The station traffic database is not configured.")
            return
        dialog = getattr(self, "_traffic_summary_dialog", None)
        if dialog is None or getattr(dialog, "_closing", False):
            root = path.parent.parent / "reports" / "traffic-summaries"
            dialog = TrafficSummaryDialog(str(path), root, self, station_callsign=self._compose_operator_callsign(),
                                          reference_root=path.parent.parent / "cache" / "fcc_call_finder")
            dialog.stageRequested.connect(self._receive_traffic_summary)
            self._traffic_summary_dialog = dialog
        dialog.show()
        dialog.raise_()
        dialog.activateWindow()

    def _ensure_summary_blank_form(self) -> None:
        if getattr(self, "_compose_summary_context", None) is None or self._compose_mode != "nbems":
            return
        for index in range(self.compose_family_combo.count()):
            entry = self.compose_family_combo.itemData(index)
            if isinstance(entry, dict) and entry.get("kind") == "standard":
                if self.compose_family_combo.currentIndex() != index:
                    self.compose_family_combo.setCurrentIndex(index)
                return
        self.compose_family_combo.addItem("Standard Blank", {"kind": "standard", "key": "STANDARD", "label": "Standard Blank"})
        self.compose_family_combo.setCurrentIndex(self.compose_family_combo.count() - 1)

    def _receive_traffic_summary(self, snapshot, text: str) -> None:
        """Prefill only; existing Compose retains explicit destination/stage choices."""
        from freqinout.core.traffic_summary_stage import SummaryStageContext
        current = self._compose_field_values().get("MESSAGE", "").strip()
        if current and current != text.strip():
            answer = QMessageBox.question(self, "Replace Compose draft?",
                "Replace the current Compose message with the reviewed traffic summary?",
                QMessageBox.Yes | QMessageBox.No, QMessageBox.No)
            if answer != QMessageBox.Yes:
                return
        dialog = self.sender()
        if dialog is None:
            dialog = getattr(self, "_traffic_summary_dialog", None)
        excluded = tuple(getattr(dialog, "excluded_ids", ()))
        path = self._db_path()
        if path is None:
            return
        self.show_compose_from_navigation()
        if self._compose_mode != "nbems":
            self._apply_compose_mode_tab_changed(0)
        entries = list(self._compose_family_entries_cache)
        if not any(entry.get("kind") == "standard" for entry in entries):
            entries.insert(0, {"kind": "standard", "key": "STANDARD", "label": "Standard Blank"})
        self._apply_compose_family_entries(entries)
        for index in range(self.compose_family_combo.count()):
            entry = self.compose_family_combo.itemData(index)
            if isinstance(entry, dict) and entry.get("kind") == "standard":
                self.compose_family_combo.setCurrentIndex(index)
                break
        # A pre-existing Standard Blank selection may not emit a change.
        if self._compose_template_kind != "blank":
            self._on_compose_family_changed()
        self._compose_set_widget_value("SUBJECT", "Station Traffic Summary")
        self._compose_set_widget_value("MESSAGE", text)
        self.compose_report_title_edit.setText("Station_Traffic_Summary")
        self._compose_summary_context = SummaryStageContext(snapshot, text, excluded,
            str(path.parent.parent / "reports" / "traffic-summaries"),
            report_kind=getattr(dialog, "report_kind", "legacy"),
            companion_text=getattr(dialog, "companion_text", ""),
            target_minutes=getattr(dialog, "target_minutes", 3))
        self._store_compose_form_draft()
        self._update_compose_preview()
        self._set_compose_status("Reviewed summary loaded. Choose file format, radio, signing and optional BBS locations, then Stage Files. No transmission is automatic.", role="info")
        if dialog is not None:
            dialog.hide()

    def _update_messages_mode_ui(self) -> None:
        if not hasattr(self, "messages_mode_stack"):
            return
        compose_active = self._messages_mode == "Compose"
        theme = resolve_theme(self.settings)
        self.messages_mode_stack.setCurrentIndex(1 if compose_active else 0)
        if hasattr(self, "messages_title_label"):
            self.messages_title_label.setText("<h3>Message Compose</h3>" if compose_active else "<h3>Message Inbox</h3>")
        if hasattr(self, "messages_help_btn"):
            self.messages_help_btn.setText("Compose Help" if compose_active else "Inbox Help")
            self.messages_help_btn.setStyleSheet(button_style("secondary", theme))
        for widget in (self.messages_bbs_help_btn, self.messages_manage_bbs_btn, self.messages_copy_summary_btn):
            widget.setVisible(False)
        for widget in (self.compose_refresh_forms_btn, self.compose_reset_btn, self.compose_open_source_btn):
            widget.setVisible(compose_active)
            widget.setStyleSheet(button_style("muted", theme))
        if hasattr(self, "_compose_tools_row"):
            self._compose_tools_row.setVisible(False)
        self._update_show_all_message_groups_style()
        for widget in (
            self.received_filter,
            self.message_check_combo,
            self.operating_group_filter,
            self.source_filter,
            self.message_check_status_label,
            self.refresh_btn,
            self.more_actions_btn,
        ):
            widget.setVisible(not compose_active)
        if hasattr(self, "mark_all_read_btn"):
            self.mark_all_read_btn.setVisible(False)
        for widget in (self.scan_combo, self.export_btn, self.export_selected_btn, self.delete_selected_btn):
            widget.setVisible(False)
        if hasattr(self, "_inbox_actions_row"):
            self._inbox_actions_row.setVisible(not compose_active)
        self._apply_inbox_tools_visibility()
        if hasattr(self, "inbox_focus_widget"):
            self.inbox_focus_widget.setVisible(not compose_active)
        if hasattr(self, "message_funnel_widget"):
            self.message_funnel_widget.setVisible(not compose_active)
        if hasattr(self, "pending_retrieval_widget"):
            self._sync_pending_retrieval_disclosure(
                int(getattr(self, "_pending_total_count", 0) or 0)
            )
        if hasattr(self, "traffic_action_summary"):
            self.traffic_action_summary.setVisible(not compose_active)
        self._update_map_context_filter_label()
        if hasattr(self, "messages_help_btn"):
            self.messages_help_btn.setVisible(not compose_active)
        if hasattr(self, "bbs_status_btn"):
            self.bbs_status_btn.setVisible(not compose_active)
            self._refresh_varac_bbs_status_label()
        if hasattr(self, "bbs_manage_btn"):
            self.bbs_manage_btn.setVisible(not compose_active)
        if hasattr(self, "inbox_bbs_summary_label"):
            self.inbox_bbs_summary_label.setVisible(not compose_active)
        self._sync_message_check_timer()
        if compose_active:
            self._refresh_compose_layout_geometry_if_needed(force=True)
            QTimer.singleShot(0, lambda: self._refresh_compose_layout_geometry_if_needed(force=True))
            QTimer.singleShot(80, lambda: self._refresh_compose_layout_geometry_if_needed(force=True))
        self._update_compose_preview()
        if compose_active and str(getattr(self, "_compose_mode", "nbems") or "nbems") == "spotter":
            self._queue_compose_spotter_scroll_reset()

    def _open_messages_help(self) -> None:
        context_key = "messages.compose" if self._messages_mode == "Compose" else "tab.messages"
        self._open_context_help(context_key)

    def _messages_support_summary(self) -> str:
        mode = str(self._messages_mode or "Inbox")
        top_lines = [
            f"Mode: {mode}",
            f"Watch directories: {len(self.watch_dirs)}",
            f"Pending backlog: {self.pending_count.text() if hasattr(self, 'pending_count') else '0 pending'}",
        ]
        if mode == "Inbox":
            check_label = "off" if not self._visible_check_interval_sec else f"every {int(self._visible_check_interval_sec)} seconds while open"
            top_lines.append(f"Message check: {check_label}")
            top_lines.append(f"Folder scan: every {int(self.scan_minutes)} minute(s)")
            summaries = self.message_summaries(visible_only=True) if hasattr(self, "_messages_model") else ()
            default_visible = sum(1 for summary in summaries if summary.visible_by_default)
            source_contract_lines = []
            for source_family in sorted({summary.source_family for summary in summaries if summary.source_family}):
                contract = source_contract_for(source_family)
                failures = contract_gate_failures(contract)
                status = "meets gates" if not failures else "missing " + ", ".join(failures)
                source_contract_lines.append(f"{contract.display_name}: {status}")
            sections = (
                (
                    "Inbox Detail",
                    bullet_lines(
                        [
                            self.loading_label.text() if getattr(self, "loading_label", None) and self.loading_label.isVisible() else "",
                            f"Visible rows: {self.messages_table.rowCount()}" if hasattr(self, "messages_table") else "",
                            f"Operational default-visible rows: {default_visible} of {len(summaries)}" if summaries else "",
                            f"Status filter: {self.status_filter.currentText()}" if hasattr(self, "status_filter") else "",
                            f"Type filter: {self.type_filter.currentText()}" if hasattr(self, "type_filter") else "",
                        ]
                    ),
                ),
                (
                    "Source Contracts",
                    bullet_lines(source_contract_lines),
                ),
            )
        else:
            sections = (
                (
                    "Compose Detail",
                    bullet_lines(
                        [
                            f"Family: {self.compose_family_combo.currentText()}" if hasattr(self, "compose_family_combo") else "",
                            f"Form: {self.compose_form_combo.currentText()}" if hasattr(self, "compose_form_combo") else "",
                            f"Send target: {self.compose_send_target_combo.currentText()}" if hasattr(self, "compose_send_target_combo") else "",
                            f"VarAC copy: {self.compose_varac_target_combo.currentText()}" if hasattr(self, "compose_varac_target_combo") else "",
                            self.compose_status_label.text() if hasattr(self, "compose_status_label") else "",
                            self.compose_destinations_label.text() if hasattr(self, "compose_destinations_label") else "",
                        ]
                    ),
                ),
            )
        return build_support_summary("CommsPlan Multi-Rig Messages Summary", top_lines, sections=sections)

    def _copy_messages_support_summary(self) -> None:
        QApplication.clipboard().setText(self._messages_support_summary())
        if hasattr(self, "messages_copy_summary_btn"):
            self.messages_copy_summary_btn.setText("Copied")
            QTimer.singleShot(1500, lambda: self.messages_copy_summary_btn.setText("Copy Summary"))

    def _refresh_more_actions_menu(self) -> None:
        selected_rows = self._messages_model.selected_rows() if hasattr(self, "_messages_model") else []
        selected = len(selected_rows)
        if hasattr(self, "more_export_selected_action"):
            self.more_export_selected_action.setEnabled(bool(self._export_selected_available) and selected > 0)
        if hasattr(self, "more_publish_selected_bbs_action"):
            bbs_count = len(self._eligible_bbs_publication_rows(selected_rows))
            self.more_publish_selected_bbs_action.setVisible(bbs_count > 0)
            self.more_publish_selected_bbs_action.setEnabled(bbs_count > 0)
            self.more_publish_selected_bbs_action.setText(
                f"Publish Selected to BBS... ({bbs_count})"
                if bbs_count > 0
                else "Publish Selected to BBS..."
            )
        if hasattr(self, "more_copy_selected_summary_action"):
            self.more_copy_selected_summary_action.setEnabled(selected > 0)
        if hasattr(self, "more_actions_btn"):
            if selected:
                self.more_actions_btn.setToolTip(f"{selected} selected. Open for export, summaries, maintenance, and help.")
            else:
                self.more_actions_btn.setToolTip("Open message export, summaries, maintenance, and help.")

    def _select_visible_messages(self) -> None:
        rows = self._messages_model.rows() if hasattr(self, "_messages_model") else []
        deletable = self._collect_deletable_rows(rows)
        if not deletable:
            QMessageBox.information(self, "Select Matching Rows", "No selectable matching messages are visible.")
            return
        self._messages_model.set_selected_for_rows(deletable, True)
        self._update_bulk_delete_buttons()
        if hasattr(self, "message_check_status_label"):
            self.message_check_status_label.setText(
                f"Selected {len(deletable)} visible message(s) matching: {self._active_message_scope_summary()}."
            )

    def _select_cleanup_age_window(self, age_seconds: int) -> None:
        if not hasattr(self, "received_filter"):
            return
        target = int(age_seconds or 0)
        if target >= 0:
            return
        idx = self.received_filter.findData(target)
        if idx < 0:
            return
        self._unfreeze_table()
        self.received_filter.setCurrentIndex(idx)
        self._apply_message_filters()
        self._select_visible_messages()

    def _clear_message_selection(self) -> None:
        if hasattr(self, "_messages_model"):
            self._messages_model.clear_selection()
        self._update_bulk_delete_buttons()

    def _populate_maintenance_table(
        self,
        table: QTableWidget,
        *,
        headers: Sequence[str],
        rows: Sequence[Sequence[object]],
    ) -> None:
        table.setColumnCount(len(headers))
        table.setRowCount(len(rows))
        table.setHorizontalHeaderLabels([str(h) for h in headers])
        table.setEditTriggers(QAbstractItemView.NoEditTriggers)
        table.setSelectionMode(QAbstractItemView.NoSelection)
        table.setAlternatingRowColors(True)
        table.setSizeAdjustPolicy(QAbstractScrollArea.AdjustIgnored)
        for r, row in enumerate(rows):
            for c, value in enumerate(row):
                table.setItem(r, c, QTableWidgetItem(str(value or "")))
        header = table.horizontalHeader()
        for idx in range(max(0, len(headers) - 1)):
            header.setSectionResizeMode(idx, QHeaderView.ResizeToContents)
        if headers:
            header.setSectionResizeMode(len(headers) - 1, QHeaderView.Stretch)

    def _open_message_maintenance(self) -> None:
        dialog = QDialog(self)
        dialog.setWindowTitle("Message Maintenance")
        dialog.resize(980, 560)
        root = QVBoxLayout(dialog)
        intro = QLabel(
            "Review recent delete activity and messages hidden from CommsPlan views. "
            "This is for troubleshooting and cleanup review; the Inbox remains the primary operating view."
        )
        intro.setWordWrap(True)
        root.addWidget(intro)

        tabs = QTabWidget()
        audit_table = QTableWidget()
        hidden_table = QTableWidget()
        self._populate_maintenance_table(
            audit_table,
            headers=["When", "Result", "Source", "Action", "From", "To", "Message", "Detail"],
            rows=[("Loading…", "", "", "", "", "", "", "")],
        )
        self._populate_maintenance_table(
            hidden_table,
            headers=["Hidden", "Type", "From", "To", "Message", "Reason"],
            rows=[("Loading…", "", "", "", "", "")],
        )
        tabs.addTab(audit_table, "Delete Audit")
        tabs.addTab(hidden_table, "Hidden CommStat")
        rebuild_panel = QWidget()
        rebuild_layout = QVBoxLayout(rebuild_panel)
        rebuild_intro = QLabel(
            "Rebuild the derived Message Index only when troubleshooting stale or missing indexed views. "
            "CommsPlan previews the scope first; native message evidence and received files are never deleted."
        )
        rebuild_intro.setWordWrap(True)
        rebuild_layout.addWidget(rebuild_intro)
        self._message_maintenance_rebuild_status_label = QLabel(
            "Normal startup and Inbox refresh use bounded incremental catch-up."
        )
        self._message_maintenance_rebuild_status_label.setWordWrap(True)
        rebuild_layout.addWidget(self._message_maintenance_rebuild_status_label)
        rebuild_action_row = QHBoxLayout()
        rebuild_btn = QPushButton("Preview Message Index Rebuild")
        rebuild_btn.setToolTip(
            "Estimate the native records to re-index, then request an explicit cancellable rebuild."
        )
        rebuild_btn.clicked.connect(self._start_message_projection_deep_rebuild)
        rebuild_btn.setEnabled(self._message_projection_maintenance_service() is not None)
        rebuild_action_row.addWidget(rebuild_btn)
        rebuild_action_row.addStretch(1)
        rebuild_layout.addLayout(rebuild_action_row)
        rebuild_layout.addStretch(1)
        tabs.addTab(rebuild_panel, "Message Index")
        root.addWidget(tabs, 1)

        buttons = QDialogButtonBox(QDialogButtonBox.Close, dialog)
        buttons.rejected.connect(dialog.reject)
        root.addWidget(buttons)
        service = self._message_projection_maintenance_service()
        if service is not None and hasattr(service, "load_message_maintenance_rows_async"):
            future = service.load_message_maintenance_rows_async(limit=300)
            poll = QTimer(dialog)
            poll.setInterval(100)
            poll.timeout.connect(
                lambda: self._poll_message_maintenance_rows(
                    future=future,
                    timer=poll,
                    tabs=tabs,
                    audit_table=audit_table,
                    hidden_table=hidden_table,
                )
            )
            poll.start()
        else:
            audit_table.setItem(0, 0, QTableWidgetItem("Maintenance data unavailable"))
            hidden_table.setItem(0, 0, QTableWidgetItem("Maintenance data unavailable"))
        dialog.exec()

    def _poll_message_maintenance_rows(
        self,
        *,
        future: object,
        timer: QTimer,
        tabs: QTabWidget,
        audit_table: QTableWidget,
        hidden_table: QTableWidget,
    ) -> None:
        if not hasattr(future, "done") or not future.done():
            return
        timer.stop()
        try:
            payload = future.result()
            audit_rows = list(payload.get("audit", []) or [])
            hidden_rows = list(payload.get("hidden", []) or [])
        except Exception as exc:
            log.debug("MessageViewer: maintenance rows unavailable: %s", exc)
            audit_rows = []
            hidden_rows = []
        self._populate_maintenance_table(
            audit_table,
            headers=["When", "Result", "Source", "Action", "From", "To", "Message", "Detail"],
            rows=[
                (
                    self._fmt_ts(float(row.get("audit_ts") or 0.0)),
                    str(row.get("result", "") or "").upper(),
                    row.get("source", ""),
                    row.get("action", ""),
                    row.get("from_call", ""),
                    row.get("to_call", ""),
                    row.get("title", ""),
                    row.get("detail", ""),
                )
                for row in audit_rows
                if isinstance(row, Mapping)
            ],
        )
        self._populate_maintenance_table(
            hidden_table,
            headers=["Hidden", "Type", "From", "To", "Message", "Reason"],
            rows=[
                (
                    self._fmt_ts(float(row.get("deleted_ts") or 0.0)),
                    artifact_filter_label(str(row.get("artifact_kind", "") or ""))
                    or row.get("artifact_kind", ""),
                    row.get("from_call", ""),
                    MessageTableModel._strip_group_marker(row.get("target", "")),
                    row.get("title", "") or row.get("artifact_key", ""),
                    row.get("reason", ""),
                )
                for row in hidden_rows
                if isinstance(row, Mapping)
            ],
        )
        tabs.setTabText(0, f"Delete Audit ({len(audit_rows)})")
        tabs.setTabText(1, f"Hidden CommStat ({len(hidden_rows)})")

    def _message_projection_maintenance_service(self):
        # Messages is nested below the MainWindow in the production tab stack.
        # Its immediate Qt parent is therefore normally a container widget, not
        # the application host that owns the maintenance service.  Walk the
        # ownership chain so the same lookup works in the full shell, embedded
        # windows, and focused widget tests.
        current = self
        visited: set[int] = set()
        while current is not None and id(current) not in visited:
            visited.add(id(current))
            service = getattr(current, "message_projection_maintenance", None)
            if service is not None:
                return service
            current = current.parent()
        window = self.window()
        return getattr(window, "message_projection_maintenance", None)

    def _start_message_projection_deep_rebuild(self) -> None:
        service = self._message_projection_maintenance_service()
        if service is None:
            QMessageBox.information(
                self,
                "Message Index Rebuild",
                "Message Index maintenance is unavailable in this application mode.",
            )
            return
        if bool(getattr(self, "_message_projection_maintenance_busy", False)):
            QMessageBox.information(
                self,
                "Message Index Rebuild",
                "Message Index maintenance is already in progress.",
            )
            return
        self._message_projection_maintenance_busy = True
        try:
            future = service.preview_deep_rebuild_async()
        except Exception as exc:
            self._message_projection_maintenance_busy = False
            QMessageBox.warning(
                self,
                "Message Index Rebuild",
                f"CommsPlan could not prepare the rebuild preview: {type(exc).__name__}.",
            )
            return
        progress = QProgressDialog(
            "Preparing a read-only Message Index rebuild estimate…",
            "",
            0,
            0,
            self,
        )
        progress.setCancelButton(None)
        progress.setWindowTitle("Message Index Rebuild Preview")
        progress.setWindowModality(Qt.WindowModal)
        progress.setMinimumDuration(0)
        poll = QTimer(progress)
        poll.setInterval(100)
        poll.timeout.connect(
            lambda: self._poll_message_projection_rebuild_preview(
                future=future,
                progress=progress,
                timer=poll,
            )
        )
        poll.start()
        progress.show()

    def _poll_message_projection_rebuild_preview(
        self,
        *,
        future: object,
        progress: QProgressDialog,
        timer: QTimer,
    ) -> None:
        if not hasattr(future, "done") or not future.done():
            return
        timer.stop()
        progress.close()
        try:
            preview = future.result()
        except Exception as exc:
            self._message_projection_maintenance_busy = False
            QMessageBox.warning(
                self,
                "Message Index Rebuild",
                f"CommsPlan could not prepare the rebuild preview: {type(exc).__name__}.",
            )
            return
        estimate = int(getattr(preview, "source_rows", 0) or 0)
        available = int(getattr(preview, "available_sources", 0) or 0)
        unavailable = int(getattr(preview, "unavailable_sources", 0) or 0)
        answer = QMessageBox.question(
            self,
            "Rebuild Message Index?",
            "CommsPlan found approximately "
            f"{estimate:,} native records across {available} available source table(s). "
            f"{unavailable} source table(s) are currently unavailable.\n\n"
            "The rebuild is bounded, cancellable, and safely resumes through normal background catch-up "
            "or after restart. It changes only the derived "
            "Message Index; native messages and received files remain untouched. Continue?",
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No,
        )
        if answer != QMessageBox.Yes:
            self._message_projection_maintenance_busy = False
            return
        service = self._message_projection_maintenance_service()
        if service is None:
            self._message_projection_maintenance_busy = False
            return
        try:
            future = service.request_deep_rebuild_async(preview=preview)
        except Exception as exc:
            self._message_projection_maintenance_busy = False
            QMessageBox.warning(
                self,
                "Message Index Rebuild",
                f"CommsPlan could not request the rebuild: {type(exc).__name__}.",
            )
            return
        request_progress = QProgressDialog(
            "Preparing the derived Message Index for a bounded rebuild…",
            "",
            0,
            0,
            self,
        )
        request_progress.setCancelButton(None)
        request_progress.setWindowTitle("Message Index Rebuild")
        request_progress.setWindowModality(Qt.WindowModal)
        request_progress.setMinimumDuration(0)
        request_poll = QTimer(request_progress)
        request_poll.setInterval(100)
        request_poll.timeout.connect(
            lambda: self._poll_message_projection_rebuild_request(
                future=future,
                progress=request_progress,
                timer=request_poll,
                estimate=estimate,
            )
        )
        request_poll.start()
        request_progress.show()

    def _poll_message_projection_rebuild_request(
        self,
        *,
        future: object,
        progress: QProgressDialog,
        timer: QTimer,
        estimate: int,
    ) -> None:
        if not hasattr(future, "done") or not future.done():
            return
        timer.stop()
        progress.close()
        try:
            request = future.result()
        except Exception as exc:
            self._message_projection_maintenance_busy = False
            QMessageBox.warning(
                self,
                "Message Index Rebuild",
                f"CommsPlan could not request the rebuild: {type(exc).__name__}.",
            )
            return
        if str(getattr(request, "state", "") or "") == "busy":
            self._message_projection_maintenance_busy = False
            QMessageBox.information(
                self,
                "Message Index Busy",
                "A short incremental catch-up is finishing. Try the rebuild again in a moment.",
            )
            return
        rebuild_id = str(getattr(request, "rebuild_id", "") or "")
        if not rebuild_id:
            self._message_projection_maintenance_busy = False
            QMessageBox.warning(self, "Message Index Rebuild", "The rebuild request was not accepted.")
            return
        service = self._message_projection_maintenance_service()
        if service is None:
            self._message_projection_maintenance_busy = False
            return
        future = service.start_deep_rebuild(
            rebuild_id=rebuild_id,
            source_rows_estimate=estimate,
        )
        progress = QProgressDialog(
            "Rebuilding the derived Message Index…",
            "Cancel",
            0,
            max(1, estimate),
            self,
        )
        progress.setWindowTitle("Message Index Rebuild")
        # QProgressDialog processes nested Qt events from setValue() while it
        # is modal.  A large rebuild updates often enough that those nested
        # events can make the dialog appear to hang or disappear behind other
        # work.  The rebuild is already protected by the service busy flag;
        # keep this as a modeless, always-on-top status window instead.
        progress.setWindowModality(Qt.NonModal)
        progress.setWindowFlag(Qt.WindowStaysOnTopHint, True)
        progress.setAutoClose(False)
        progress.setAutoReset(False)
        progress.setMinimumDuration(0)
        progress.canceled.connect(service.cancel)
        poll = QTimer(progress)
        poll.setInterval(200)
        poll.timeout.connect(
            lambda: self._poll_message_projection_deep_rebuild(
                future=future,
                progress=progress,
                timer=poll,
            )
        )
        self._message_projection_rebuild_future = future
        self._message_projection_rebuild_progress = progress
        self._message_projection_rebuild_timer = poll
        poll.start()
        progress.show()

    def _poll_message_projection_deep_rebuild(
        self,
        *,
        future: object,
        progress: QProgressDialog,
        timer: QTimer,
    ) -> None:
        service = self._message_projection_maintenance_service()
        if service is None:
            self._message_projection_maintenance_busy = False
            timer.stop()
            progress.close()
            return
        snapshot = service.diagnostic_snapshot() if hasattr(service, "diagnostic_snapshot") else {}
        processed = int(snapshot.get("processed", 0) or 0) if isinstance(snapshot, Mapping) else 0
        estimate = int(snapshot.get("source_rows_estimate", 0) or 0) if isinstance(snapshot, Mapping) else 0
        display_total = max(estimate, processed, progress.maximum())
        display_value = min(display_total, processed)
        display_text = (
            "Rebuilding the derived Message Index… "
            f"{processed:,} of approximately {display_total:,} records"
        )
        # Avoid QProgressDialog.setValue() re-entering Qt for an unchanged
        # worker snapshot.  The worker publishes cheap in-memory progress and
        # the timer is only a UI observer, not a synchronization mechanism.
        prior_total = int(getattr(progress, "_fio_rebuild_display_total", -1))
        prior_value = int(getattr(progress, "_fio_rebuild_display_value", -1))
        prior_text = str(getattr(progress, "_fio_rebuild_display_text", ""))
        if display_total != prior_total:
            progress.setMaximum(display_total)
            progress._fio_rebuild_display_total = display_total
        if display_value != prior_value:
            progress.setValue(display_value)
            progress._fio_rebuild_display_value = display_value
        if display_text != prior_text:
            progress.setLabelText(display_text)
            progress._fio_rebuild_display_text = display_text
        if not hasattr(future, "done") or not future.done():
            return
        timer.stop()
        self._message_projection_maintenance_busy = False
        try:
            result = future.result()
            state = str(getattr(result, "state", "complete") or "complete")
            processed = int(getattr(result, "processed", processed) or processed)
            repaired = int(getattr(result, "repaired", 0) or 0)
        except Exception as exc:
            state = "failed"
            failure = type(exc).__name__
        progress.close()
        status_label = getattr(self, "_message_maintenance_rebuild_status_label", None)
        if status_label is not None:
            try:
                if state == "complete":
                    repair_text = (
                        f"; {repaired:,} legacy duplicate presentations repaired"
                        if repaired
                        else ""
                    )
                    status_label.setText(
                        f"Message Index rebuild complete: {processed:,} records considered{repair_text}."
                    )
                elif state == "cancelled":
                    status_label.setText(
                        "Message Index rebuild paused. Normal background catch-up may resume the remaining work safely."
                    )
                elif state == "deferred":
                    status_label.setText(
                        "Message Index rebuild paused for active database work. Its checkpoint remains safe; retry when activity settles."
                    )
                else:
                    status_label.setText(f"Message Index rebuild stopped: {state}.")
            except RuntimeError:
                pass
        if state == "complete":
            self._request_projected_message_query(force=True, delay_ms=0)
            repair_text = (
                f"; {repaired:,} legacy duplicate presentations repaired"
                if repaired
                else ""
            )
            QMessageBox.information(
                self,
                "Message Index Rebuild",
                f"The derived Message Index rebuild completed ({processed:,} records considered{repair_text}).",
            )
        elif state == "cancelled":
            QMessageBox.information(
                self,
                "Message Index Rebuild Paused",
                "The rebuild was paused. Its durable work remains safe and may resume during normal "
                "background catch-up or after CommsPlan restarts.",
            )
        elif state == "deferred":
            QMessageBox.information(
                self,
                "Message Index Rebuild Paused",
                "Active message database work remained busy, so the rebuild paused safely. "
                "Its checkpoint and queued work were retained; retry after current message activity settles.",
            )
        else:
            QMessageBox.warning(
                self,
                "Message Index Rebuild",
                f"The rebuild stopped ({locals().get('failure', state)}). Its checkpoint was retained.",
            )

    def _copy_selected_messages_summary(self) -> None:
        rows = self._messages_model.selected_rows() if hasattr(self, "_messages_model") else []
        if not rows:
            QMessageBox.information(self, "Copy Selected Summary", "Select one or more messages to copy.")
            return
        QApplication.clipboard().setText(self._selected_messages_summary_text(rows))

    @staticmethod
    def _selected_messages_summary_text(rows: Sequence[UnifiedMessage]) -> str:
        clean_rows = [row for row in rows if isinstance(row, UnifiedMessage)]
        lines = [
            "Selected Messages Summary",
            f"Messages: {len(clean_rows)}",
            "",
        ]
        lines.extend(MessageViewerTab._message_row_summary_line(row) for row in clean_rows)
        return "\n".join(lines).strip()

    @staticmethod
    def _message_row_summary_line(row: UnifiedMessage) -> str:
        return _core_message_row_summary_line(row)

    def _status_chip_html(self, text: str, role: str = "neutral") -> str:
        palette = {
            "ok": ("#E8F5E9", "#1B5E20", "#A5D6A7"),
            "info": ("#E3F2FD", "#0D47A1", "#90CAF9"),
            "warn": ("#FFF8E1", "#8D6E00", "#FFE082"),
            "bad": ("#FFEBEE", "#8E0000", "#EF9A9A"),
            "neutral": ("#ECEFF1", "#263238", "#CFD8DC"),
        }
        bg, fg, border = palette.get(str(role or "neutral"), palette["neutral"])
        label = html.escape(str(text or "").strip())
        return (
            f"<span style='background-color:{bg}; color:{fg}; border:1px solid {border}; "
            "padding:2px 7px; font-weight:600; white-space:nowrap;'>"
            f"{label}</span>"
        )

    @staticmethod
    def _allowed_callsign_count(text: object) -> int:
        raw = str(text or "").strip()
        if not raw:
            return 0
        parts = [p.strip().upper() for p in re.split(r"[,;\\s]+", raw) if p.strip()]
        return len([p for p in parts if p not in {"*", "ALL"}])

    def _open_varac_bbs_manager(self) -> None:
        host = resolve_help_host(self)
        if host is not None and hasattr(host, "open_station_bbs"):
            try:
                host.open_station_bbs()
            except Exception:
                pass
            return
        if host is not None and hasattr(host, "open_settings_section"):
            try:
                host.open_settings_section("varac")
            except Exception:
                pass

    def _refresh_varac_bbs_status_label(self) -> None:
        try:
            self.settings.reload()
        except Exception:
            pass
        inventory = build_bbs_inventory(self.settings, allowed_exts=ORIGIN_EXTS.get("bbs", set(SUPPORTED_EXT)))
        limit_access = bool(self.settings.get("varac_bbs_limit_access_enabled", False))
        announce_enabled = bool(self.settings.get("varac_bbs_announce_enabled", False))
        allowed_text = str(self.settings.get("varac_bbs_allowed_callsigns", "") or "")
        summary = bbs_summary_text(
            {
                "enable_bbs": inventory.bbs_enabled,
                "limit_access": limit_access,
                "announce": announce_enabled,
                "allowed_callsigns": allowed_text,
            }
        )
        if inventory.live_dir:
            suffix = f" Directory: {inventory.live_dir}"
            if not inventory.live_exists:
                suffix += " (missing)"
            else:
                suffix += f" ({inventory.live_file_count} live files)"
        else:
            suffix = " Directory not configured."
        vault_suffix = ""
        if inventory.vault_enabled:
            vault_suffix = (
                f" Managed locations: {inventory.enabled_location_count} enabled / "
                f"{inventory.total_location_count} total, {inventory.managed_file_count} files."
            )
        full_text = f"VarAC BBS (runtime-projected default context): {summary}.{suffix}{vault_suffix}"
        if not inventory.bbs_enabled:
            label, role = "BBS Off", "neutral"
        elif not inventory.live_dir or not inventory.live_exists:
            label, role = "BBS Issue", "danger"
        else:
            label, role = "BBS OK", "success"
        self._bbs_status_detail_text = full_text
        if hasattr(self, "bbs_status_btn"):
            self.bbs_status_btn.setText(label)
            self.bbs_status_btn.setToolTip(full_text)
            self.bbs_status_btn.setStyleSheet(button_style(role, resolve_theme(self.settings)))
        if hasattr(self, "inbox_bbs_summary_label"):
            if not inventory.bbs_enabled:
                summary_text = "BBS files: disabled"
            else:
                managed_text = "managed locations off"
                if inventory.vault_enabled:
                    managed_text = (
                        f"{inventory.enabled_location_count}/{inventory.total_location_count} managed locations, "
                        f"{inventory.managed_file_count} managed files"
                    )
                archive_text = f"archive after {inventory.archive_days}d" if inventory.archive_enabled else "archive off"
                live_text = f"{inventory.live_file_count} live files" if inventory.live_exists else "live directory missing"
                summary_text = f"BBS files: {live_text}; {managed_text}; {archive_text}."
            self.inbox_bbs_summary_label.setText(summary_text)
            self.inbox_bbs_summary_label.setToolTip(full_text)

    def _show_varac_bbs_status_details(self) -> None:
        self._refresh_varac_bbs_status_label()
        QMessageBox.information(
            self,
            "VarAC BBS Status",
            getattr(self, "_bbs_status_detail_text", "VarAC BBS status is not available."),
        )

    def _open_context_help(self, context_key: str) -> None:
        host = resolve_help_host(self)
        if host is not None and hasattr(host, "open_context_help"):
            try:
                host.open_context_help(context_key)
            except Exception:
                pass

    def _refresh_compose_timestamp(self) -> None:
        self._compose_timestamp_utc = datetime.datetime.now(datetime.timezone.utc)
        self._refresh_compose_smart_defaults()
        self._update_compose_preview()

    def _reset_compose_draft(self, *, status_text: str = "Compose draft reset.") -> None:
        self._compose_summary_context = None
        mode = str(getattr(self, "_compose_mode", "nbems") or "nbems")
        self._compose_timestamp_utc = datetime.datetime.now(datetime.timezone.utc)
        self._compose_mode_drafts.pop(mode, None)
        for form_key in self._compose_form_draft_mode_keys.pop(mode, set()):
            self._compose_form_draft_values.pop(form_key, None)
        self._compose_active_form_key = ""
        self._compose_restoring_mode_draft = True
        try:
            if mode == "nbems":
                self._compose_set_combo_text(getattr(self, "compose_priority_combo", None), "RR")
                self._compose_set_checked(getattr(self, "compose_sign_flamp_chk", None), False)
                self._compose_set_combo_text(getattr(self, "compose_send_target_combo", None), "FLMsg")
                self._compose_set_combo_text(getattr(self, "compose_varac_target_combo", None), "None")
                self._compose_set_checked(getattr(self, "compose_publish_bbs_chk", None), False)
                self._compose_set_line_text(getattr(self, "compose_report_title_edit", None), "")
                self._compose_last_stage_paths = []
                self._on_compose_form_changed()
            elif mode == "js8":
                self._compose_set_line_text(getattr(self, "compose_js8_target_edit", None), "")
                self._compose_set_combo_text(getattr(self, "compose_js8_plain_kind_combo", None), "Directed Message")
                self._compose_set_checked(getattr(self, "compose_js8_send_as_msg_chk", None), False)
                widget = getattr(self, "compose_js8_plain_text_edit", None)
                if isinstance(widget, QTextEdit):
                    blocked = widget.blockSignals(True)
                    try:
                        widget.clear()
                    finally:
                        widget.blockSignals(blocked)
            elif mode == "spotter":
                self._clear_compose_spotter_working_response()
                source_combo = getattr(self, "compose_spotter_source_combo", None)
                if isinstance(source_combo, QComboBox):
                    source_combo.blockSignals(True)
                    try:
                        source_combo.setCurrentIndex(0)
                    finally:
                        source_combo.blockSignals(False)
                self._compose_set_line_text(getattr(self, "compose_js8_target_edit", None), "")
                self._compose_set_checked(getattr(self, "compose_js8_send_as_msg_chk", None), False)
                self._compose_set_checked(getattr(self, "compose_js8_sign_chk", None), False)
                self._compose_set_checked(getattr(self, "compose_js8_auth_datecode_chk", None), False)
                self._on_compose_form_changed()
            elif mode == "commstat_rf":
                self._compose_set_line_text(getattr(self, "compose_commstat_target_edit", None), "")
                self._compose_set_line_text(getattr(self, "compose_commstat_grid_edit", None), "")
                self._compose_set_line_text(getattr(self, "compose_commstat_report_id_edit", None), "")
                self._compose_set_line_text(getattr(self, "compose_commstat_comment_edit", None), "")
                self._compose_set_checked(getattr(self, "compose_commstat_brevity_chk", None), False)
                self._compose_set_combo_text(getattr(self, "compose_commstat_brevity_edit", None), "")
                for combo in (getattr(self, "compose_commstat_status_widgets", {}) or {}).values():
                    self._compose_set_combo_text(combo, "Unknown")
                self._refresh_compose_commstat_defaults()
            elif mode == "mesh":
                self._compose_set_combo_data(getattr(self, "compose_mesh_destination_kind_combo", None), "channel")
                self._compose_set_checked(getattr(self, "compose_mesh_ack_chk", None), True)
                widget = getattr(self, "compose_mesh_text_edit", None)
                if isinstance(widget, QTextEdit):
                    blocked = widget.blockSignals(True)
                    try:
                        widget.clear()
                    finally:
                        widget.blockSignals(blocked)
                self._on_compose_mesh_destination_changed()
        finally:
            self._compose_restoring_mode_draft = False
        self._update_compose_preview()
        self._set_compose_status(status_text, role="info")

    def _open_compose_source_folder(self) -> None:
        if self._compose_last_source_dir is None:
            self._set_compose_status("No compose source folder is available for the current selection.", role="warning")
            return
        self._open_path_in_shell(self._compose_last_source_dir)

    def _open_compose_output_folder(self) -> None:
        if not self._compose_last_stage_paths:
            plans = [p for p in self._compose_cached_destinations() if p.ready]
            if not plans:
                self._set_compose_status("No ready staging folder is available.", role="warning")
                return
            self._open_path_in_shell(Path(plans[0].path).parent)
            return
        self._open_path_in_shell(self._compose_last_stage_paths[0].parent)

    def _copy_compose_output_paths(self) -> None:
        paths = self._compose_last_stage_paths or [Path(p.path) for p in self._compose_cached_destinations() if p.ready]
        if not paths:
            self._set_compose_status("No compose paths are available to copy.", role="warning")
            return
        QApplication.clipboard().setText("\n".join(str(path) for path in paths))
        self._set_compose_status("Compose output path copied to clipboard.", role="success")

    def _launch_compose_app(self, app_name: str) -> None:
        target = self._selected_compose_radio_target()
        label = self._compose_radio_target_short_label(target) if target is not None else "the selected radio"
        try:
            if self._compose_software_status.program_is_running(app_name):
                self._set_compose_status(f"{app_name} is already running for {label}. No second instance was opened.", role="info")
                return
        except Exception:
            pass
        profile = target.profile if target is not None else {}
        path_key = "flmsg_path" if app_name == "FLMsg" else "flamp_path" if app_name == "FLAmp" else ""
        configured_path = self._compose_profile_text(profile, path_key) if path_key else ""
        if configured_path:
            try:
                if platform.system() == "Darwin":
                    subprocess.Popen(["open", configured_path])
                else:
                    subprocess.Popen([configured_path])
                self._set_compose_status(f"Launching {app_name} for {label}...", role="info")
                return
            except Exception as e:
                self._set_compose_status(f"Could not launch {app_name}: {e}", role="warning")
                return
        if not self._compose_launch_orchestrator.is_configured(app_name):
            self._set_compose_status(f"{app_name} is not configured for {label}.", role="warning")
            return
        started = self._compose_launch_orchestrator.start_manual_sequence(
            [{"name": app_name, "enabled": True, "startup": False}]
        )
        if started:
            self._set_compose_status(f"Launching {app_name}...", role="info")
            return
        self._set_compose_status(f"{app_name} launch is already active or unavailable.", role="warning")

    def _open_path_in_shell(self, path: Path) -> None:
        try:
            if platform.system() == "Darwin":
                subprocess.Popen(["open", str(path)])
            elif os.name == "nt":
                os.startfile(str(path))  # type: ignore[attr-defined]
            else:
                subprocess.Popen(["xdg-open", str(path)])
        except Exception as e:
            self._set_compose_status(f"Could not open path: {e}", role="warning")

    def _set_compose_status(self, text: str, *, role: str = "info") -> None:
        if not hasattr(self, "compose_status_label"):
            return
        self._compose_status_role = str(role or "info")
        theme = resolve_theme(self.settings)
        role_map = {
            "info": theme.get("info", theme.get("accent", "#2563eb")),
            "success": theme.get("success", "#2e7d32"),
            "warning": theme.get("warning", "#b26a00"),
            "danger": theme.get("danger", "#b42318"),
        }
        color = role_map.get(role, theme.get("text", "#222222"))
        border = theme.get("border", "#cccccc")
        bg = theme.get("surface_alt", theme.get("surface", "#f5f5f5"))
        self.compose_status_label.setText(text)
        self.compose_status_label.setStyleSheet(
            f"padding: 6px 8px; border-radius: 4px; background: {bg}; color: {color}; border: 1px solid {border};"
        )
        self._refresh_compose_layout_geometry_if_needed(force=True)

    @staticmethod
    def _compose_signing_key_short_label(key) -> str:
        uid = next((str(u).strip() for u in getattr(key, "user_ids", []) if str(u).strip()), "")
        if uid:
            return uid
        fpr = normalize_fingerprint(str(getattr(key, "fingerprint", "") or ""))
        key_id = str(getattr(key, "key_id", "") or "").strip()
        short = fpr[-8:] if len(fpr) >= 8 else key_id[-8:]
        return short or "(unnamed key)"

    def _refresh_compose_signing_keys(self, *, force: bool = False) -> None:
        if not hasattr(self, "compose_signing_key_combo"):
            return
        if self._compose_signing_keys_loaded and not force:
            return
        self._compose_signing_key_generation += 1
        if self._compose_signing_key_thread is not None and self._qt_thread_running(self._compose_signing_key_thread):
            self._compose_signing_key_pending = True
            return
        self._compose_signing_keys_loading = True
        self._compose_signing_key_error = ""
        self.compose_signing_key_combo.blockSignals(True)
        self.compose_signing_key_combo.clear()
        self.compose_signing_key_combo.addItem("Loading signing keys…", "")
        self.compose_signing_key_combo.blockSignals(False)
        self._compose_signing_key_thread = QThread(self)
        self._compose_signing_key_worker = _ComposeSigningKeyWorker(
            generation=self._compose_signing_key_generation,
            configured_path=str(self.settings.get("gpg_executable_path", "") or "").strip(),
        )
        self._compose_signing_key_worker.moveToThread(self._compose_signing_key_thread)
        self._compose_signing_key_thread.started.connect(self._compose_signing_key_worker.run)
        self._compose_signing_key_worker.finished.connect(self._on_compose_signing_keys_finished)
        self._compose_signing_key_worker.finished.connect(self._compose_signing_key_thread.quit)
        self._compose_signing_key_worker.finished.connect(self._compose_signing_key_worker.deleteLater)
        self._compose_signing_key_thread.finished.connect(self._on_compose_signing_key_thread_finished)
        self._compose_signing_key_thread.finished.connect(self._compose_signing_key_thread.deleteLater)
        self._compose_signing_key_thread.start()

    def _on_compose_signing_key_thread_finished(self) -> None:
        self._retain_finished_worker_refs(self._compose_signing_key_thread, self._compose_signing_key_worker)
        self._compose_signing_key_thread = None
        self._compose_signing_key_worker = None
        if self._compose_signing_key_pending and not self._is_shutting_down:
            self._compose_signing_key_pending = False
            QTimer.singleShot(0, lambda: self._refresh_compose_signing_keys(force=True))

    def _on_compose_signing_keys_finished(self, payload: object) -> None:
        if self._is_shutting_down or not isinstance(payload, dict):
            return
        if int(payload.get("generation", 0) or 0) != self._compose_signing_key_generation:
            return
        saved = normalize_fingerprint(str(self.settings.get("gpg_compose_signing_key_fingerprint", "") or ""))
        current = normalize_fingerprint(str(self.compose_signing_key_combo.currentData() or ""))
        preferred = current or saved
        keys = list(payload.get("keys", []) or [])
        self._compose_signing_key_error = str(payload.get("error", "") or "")
        self.compose_signing_key_combo.blockSignals(True)
        try:
            self.compose_signing_key_combo.clear()
            self.compose_signing_key_combo.addItem("Select signing key...", "")
            selected_index = 0
            count = 0
            for key in keys:
                fingerprint = normalize_fingerprint(str(getattr(key, "fingerprint", "") or ""))
                if not fingerprint:
                    continue
                count += 1
                self.compose_signing_key_combo.addItem(self._compose_signing_key_short_label(key), fingerprint)
                self.compose_signing_key_combo.setItemData(
                    self.compose_signing_key_combo.count() - 1,
                    gpg_key_display_label(key),
                    Qt.ToolTipRole,
                )
                if preferred and fingerprint == preferred:
                    selected_index = self.compose_signing_key_combo.count() - 1
            if count == 1 and selected_index == 0:
                selected_index = 1
            self.compose_signing_key_combo.setCurrentIndex(selected_index)
            self._compose_signing_key_count = count
            self._compose_signing_keys_loaded = True
        finally:
            self.compose_signing_key_combo.blockSignals(False)
            self._compose_signing_keys_loading = False
        self._update_compose_preview()

    def _selected_compose_signing_fingerprint(self) -> str:
        if not hasattr(self, "compose_signing_key_combo"):
            return ""
        return normalize_fingerprint(str(self.compose_signing_key_combo.currentData() or ""))

    def _on_compose_signing_key_changed(self) -> None:
        if self._compose_signing_keys_loading:
            return
        try:
            self.settings.set("gpg_compose_signing_key_fingerprint", self._selected_compose_signing_fingerprint())
        except Exception:
            pass
        self._update_compose_preview()

    def _compose_sign_flamp_selected(self) -> bool:
        return bool(hasattr(self, "compose_sign_flamp_chk") and self.compose_sign_flamp_chk.isChecked())

    def _compose_flamp_target_selected(self) -> bool:
        return bool(
            hasattr(self, "compose_send_target_combo")
            and self.compose_send_target_combo.currentText() in {"FLAmp", "Both"}
        )

    def _ensure_compose_flamp_target_for_signing(self) -> bool:
        if self._compose_flamp_target_selected():
            return True
        if not self._compose_sign_flamp_selected() or not hasattr(self, "compose_send_target_combo"):
            return False
        previous_blocked = self.compose_send_target_combo.blockSignals(True)
        try:
            self.compose_send_target_combo.setCurrentText("Both")
        finally:
            self.compose_send_target_combo.blockSignals(previous_blocked)
        return self._compose_flamp_target_selected()

    def _update_compose_preview(self) -> None:
        with perf_span("compose.preview", settings=self.settings, min_ms=16.0,
                       meta={"mode": getattr(self, "_compose_mode", "nbems")}):
            self._render_compose_preview()

    def _render_compose_preview(self) -> None:
        if int(getattr(self, "_compose_update_depth", 0) or 0) > 0:
            self._compose_preview_update_pending = True
            return
        if bool(getattr(self, "_compose_restoring_mode_draft", False)):
            return
        if not hasattr(self, "compose_summary_label"):
            return
        for required_widget in (
            "compose_zulu_value",
            "compose_callsign_value",
            "compose_state_value",
            "compose_grid_value",
        ):
            if not hasattr(self, required_widget):
                return
        flamp_selected = self._ensure_compose_flamp_target_for_signing()
        if hasattr(self, "compose_sign_flamp_chk"):
            self.compose_sign_flamp_chk.setEnabled(True)
        sign_flamp_selected = bool(
            flamp_selected
            and self._compose_sign_flamp_selected()
        )
        if hasattr(self, "compose_signing_row_widget"):
            self.compose_signing_row_widget.setVisible(sign_flamp_selected)
        if hasattr(self, "compose_message_folder_combo"):
            self.compose_message_folder_combo.setMaximumWidth(280 if sign_flamp_selected else 16777215)
        if hasattr(self, "compose_signing_key_combo"):
            self.compose_signing_key_combo.setMinimumWidth(180)
            self.compose_signing_key_combo.setMaximumWidth(360)
        self._sync_compose_static_choice_chips()
        current_compose_mode = str(getattr(self, "_compose_mode", "nbems") or "nbems")
        early_js8_mode = current_compose_mode == "js8"
        early_spotter_mode = current_compose_mode == "spotter"
        early_commstat_mode = current_compose_mode == "commstat_rf"
        early_mesh_mode = current_compose_mode == "mesh"
        early_nbems_mode = not (early_js8_mode or early_spotter_mode or early_commstat_mode or early_mesh_mode)
        self.compose_refresh_target_action.setVisible(early_js8_mode or early_spotter_mode or early_commstat_mode)
        bbs_selected = bool(
            early_nbems_mode
            and hasattr(self, "compose_publish_bbs_chk")
            and self.compose_publish_bbs_chk.isChecked()
        )
        if hasattr(self, "compose_bbs_location_row_widget"):
            self.compose_bbs_location_row_widget.setVisible(bool(bbs_selected))
        self.compose_zulu_value.setText(self._compose_zulu_text())
        self.compose_callsign_value.setText(self._compose_operator_callsign() or "Not set")
        self.compose_state_value.setText(self._compose_operator_state() or "Not set")
        self.compose_grid_value.setText(self._compose_operator_grid() or "Not set")
        filename = self._compose_base_filename()
        radio_target = self._selected_compose_radio_target()
        profile = radio_target.profile if radio_target is not None else {}
        radio_label = radio_target.label if radio_target is not None else "No compose-capable radio"
        radio_short_label = self._compose_radio_target_short_label(radio_target) or radio_label
        folder_label = (
            self.compose_message_folder_combo.currentText()
            if hasattr(self, "compose_message_folder_combo") and self.compose_message_folder_combo.count()
            else "Messages"
        )
        self.compose_summary_label.setText(f"Radio: {radio_short_label}  |  File: {filename}  |  Folder: {folder_label}")
        self.compose_summary_label.setToolTip(
            f"{radio_label}\nCommsPlan stages compose files only. The operator sends them manually from FLMsg, FLAmp, or VarAC."
        )
        plans = self._compose_cached_destinations()
        destination_lines: List[str] = []
        if radio_target is None:
            destination_lines.append("No radio profile has FLMsg, FLAmp, or VarAC message destinations configured.")
        else:
            for plan in plans:
                if plan.ready:
                    detail = plan.note or plan.path
                    destination_lines.append(f"{plan.label}: {detail}")
                else:
                    destination_lines.append(f"{plan.label}: {radio_short_label} - {plan.note}")
        if not destination_lines:
            destination_lines.append("No stage destinations selected yet.")
        self.compose_destinations_label.setToolTip("\n".join(destination_lines))
        self.compose_destinations_label.setText(
            "\n".join(destination_lines) if radio_target is None else
            f"Create: {self.compose_send_target_combo.currentText()} · VarAC: {self.compose_varac_target_combo.currentText()} · Folder: {folder_label}"
        )
        self.compose_destinations_label.setVisible(early_nbems_mode)

        field_values = self._compose_field_values()
        if self._compose_template_kind == "blank":
            preview_rows = list(self._compose_blank_field_rows())
            title = "Standard Blank Form (.b2s)"
        else:
            preview_rows = list(self._compose_field_rows)
            title = self._compose_template_title or self.compose_form_combo.currentText()
        preview_html = self._render_custom_form_fields(field_values, preview_rows, title=title)
        js8_mode = str(getattr(self, "_compose_mode", "nbems") or "nbems") == "js8"
        spotter_mode = str(getattr(self, "_compose_mode", "nbems") or "nbems") == "spotter"
        commstat_mode = str(getattr(self, "_compose_mode", "nbems") or "nbems") == "commstat_rf"
        mesh_mode = str(getattr(self, "_compose_mode", "nbems") or "nbems") == "mesh"
        spotter_saved_selected = bool(
            int(getattr(self, "_compose_spotter_expect_active_id", 0) or 0) > 0
            and str(getattr(self, "_compose_spotter_working_response", "") or "").strip()
        )
        spotter_selected = spotter_mode and self._compose_template_kind == "spotter"
        if spotter_saved_selected:
            spotter_selected = True
        js8_plain_command = self._compose_plain_js8_command() if js8_mode else ""
        commstat_command = ""
        commstat_issue = ""
        if js8_mode:
            source_label = radio_short_label
            self.compose_summary_label.setText(f"Send From: {source_label}  |  JS8Call  |  {self._compose_plain_js8_kind()}")
            self.compose_summary_label.setToolTip(
                "JS8Call compose sends short directed or group traffic through the selected JS8Call radio."
            )
        if commstat_mode:
            try:
                commstat_command = self._compose_commstat_rf_text()
            except Exception as exc:
                commstat_issue = str(exc)
            source_label = radio_short_label
            self.compose_summary_label.setText(f"Send From: {source_label}  |  CommStat RF  |  StatRep")
            self.compose_summary_label.setToolTip(
                "CommStat RF builds a short StatRep. Optional brevity codes are included as part of the StatRep comment."
            )
        if spotter_mode:
            form_label = self.compose_form_combo.currentText() if hasattr(self, "compose_form_combo") else "No form selected"
            source_label = radio_short_label
            source_count = len([target for target in self._compose_radio_targets if "JS8Call" in tuple(target.capabilities)])
            source_part = f"Send From: {source_label}  |  " if source_count > 1 else ""
            self.compose_summary_label.setText(f"{source_part}CommsPlan Spotter draft  |  Form: {form_label}")
            self.compose_summary_label.setToolTip(
                "CommsPlan Spotter compose drafts an MCForm command for JS8Call. CommsPlan sends only after JS8Call target-state preflight passes."
            )
        mesh_request = self._compose_mesh_request() if mesh_mode else None
        mesh_config = self._selected_compose_mesh_config() if mesh_mode else None
        if mesh_mode:
            source_label = str(getattr(mesh_config, "display_name", "") or "No send-enabled mesh connection")
            protocol_label = str(getattr(mesh_config, "protocol", "mesh") or "mesh").title()
            self.compose_summary_label.setText(f"Send From: {source_label}  |  {protocol_label}")
            self.compose_summary_label.setToolTip(
                "Local Mesh sends use the selected connected adapter and preserve protocol-specific channel or node addressing."
            )
        if hasattr(self, "compose_radio_label"):
            self.compose_radio_label.setText("Send From" if (js8_mode or spotter_mode or commstat_mode) else "Compose For")
        if hasattr(self, "compose_radio_combo"):
            self.compose_radio_combo.setMaximumWidth(420 if bool(getattr(self, "_compose_in_workbench", False)) else 260)
            self.compose_radio_combo.setSizePolicy(QSizePolicy.Fixed, QSizePolicy.Fixed)
            self.compose_radio_combo.setVisible(False)
        if hasattr(self, "compose_radio_chip_container"):
            self.compose_radio_chip_container.setVisible(bool(self._compose_radio_targets) and not mesh_mode)
        if hasattr(self, "compose_radio_row_widget"):
            self.compose_radio_row_widget.setVisible(bool(self._compose_radio_targets) and not mesh_mode)
        self._refresh_compose_context_label()
        if hasattr(self, "compose_refresh_radios_btn"):
            self.compose_refresh_radios_btn.setVisible(bool(getattr(self, "_compose_in_workbench", False)))
        nbems_mode = not (js8_mode or spotter_mode or commstat_mode or mesh_mode)
        if hasattr(self, "compose_mesh_setup_widget"):
            self.compose_mesh_setup_widget.setVisible(mesh_mode)
        if hasattr(self, "compose_form_row_widget"):
            self.compose_form_row_widget.setVisible(nbems_mode or spotter_mode)
        if hasattr(self, "compose_header_row_widget"):
            self.compose_header_row_widget.setVisible(nbems_mode)
        if hasattr(self, "compose_family_label"):
            self.compose_family_label.setVisible(nbems_mode)
        if hasattr(self, "compose_family_combo"):
            self.compose_family_combo.setVisible(nbems_mode)
        if hasattr(self, "compose_operating_group_label"):
            self.compose_operating_group_label.setVisible(nbems_mode)
        if hasattr(self, "compose_operating_group_combo"):
            self.compose_operating_group_combo.setVisible(nbems_mode)
        if hasattr(self, "compose_spotter_category_label"):
            self.compose_spotter_category_label.setVisible(spotter_mode)
        if hasattr(self, "compose_spotter_category_combo"):
            self.compose_spotter_category_combo.setVisible(spotter_mode)
        if hasattr(self, "compose_form_label"):
            self.compose_form_label.setText("Spotter Form" if spotter_mode else "Form")
            self.compose_form_label.setVisible(not (js8_mode or commstat_mode or mesh_mode))
        if hasattr(self, "compose_form_combo"):
            self.compose_form_combo.setVisible(not (js8_mode or commstat_mode or mesh_mode))
        brevity_enabled = bool(getattr(getattr(self, "compose_commstat_brevity_chk", None), "isChecked", lambda: False)())
        if hasattr(self, "compose_js8_plain_row_widget"):
            self.compose_js8_plain_row_widget.setVisible(js8_mode)
        if hasattr(self, "compose_js8_plain_scroll"):
            self.compose_js8_plain_scroll.setVisible(js8_mode)
        if hasattr(self, "compose_commstat_row_widget"):
            self.compose_commstat_row_widget.setVisible(commstat_mode)
        if hasattr(self, "compose_commstat_scroll"):
            self.compose_commstat_scroll.setVisible(commstat_mode)
        if hasattr(self, "compose_mesh_message_widget"):
            self.compose_mesh_message_widget.setVisible(mesh_mode)
        if hasattr(self, "compose_mesh_scroll"):
            self.compose_mesh_scroll.setVisible(mesh_mode)
        if hasattr(self, "compose_commstat_grid_edit"):
            self.compose_commstat_grid_edit.setVisible(commstat_mode)
        if hasattr(self, "compose_commstat_grid_label"):
            self.compose_commstat_grid_label.setVisible(commstat_mode)
        if hasattr(self, "compose_commstat_scope_combo"):
            self.compose_commstat_scope_combo.setVisible(commstat_mode)
        if hasattr(self, "compose_commstat_scope_label"):
            self.compose_commstat_scope_label.setVisible(commstat_mode)
        if hasattr(self, "compose_commstat_report_id_edit"):
            self.compose_commstat_report_id_edit.setVisible(commstat_mode)
        if hasattr(self, "compose_commstat_report_id_label"):
            self.compose_commstat_report_id_label.setVisible(commstat_mode)
        if hasattr(self, "compose_commstat_brevity_chk"):
            self.compose_commstat_brevity_chk.setVisible(commstat_mode)
        if hasattr(self, "compose_commstat_brevity_edit"):
            self.compose_commstat_brevity_edit.setVisible(commstat_mode)
            self.compose_commstat_brevity_edit.setEnabled(brevity_enabled)
        if hasattr(self, "compose_commstat_brevity_label"):
            self.compose_commstat_brevity_label.setVisible(commstat_mode)
            self.compose_commstat_brevity_label.setEnabled(brevity_enabled)
        if hasattr(self, "compose_commstat_brevity_builder_widget"):
            self.compose_commstat_brevity_builder_widget.setVisible(commstat_mode and brevity_enabled)
            self.compose_commstat_brevity_builder_widget.setEnabled(brevity_enabled)
        for label_widget in (getattr(self, "compose_commstat_status_labels", {}) or {}).values():
            if isinstance(label_widget, QLabel):
                label_widget.setVisible(commstat_mode)
        for combo in (getattr(self, "compose_commstat_status_widgets", {}) or {}).values():
            if isinstance(combo, QComboBox):
                combo.setVisible(commstat_mode)
        output_options = bool(self.compose_output_options_btn.isChecked())
        self.compose_output_options_btn.setVisible(nbems_mode)
        self.compose_output_options_btn.setText("Fewer output options" if output_options else "Output options…")
        self.compose_sign_flamp_chk.setVisible(nbems_mode and (output_options or sign_flamp_selected))
        self.compose_publish_bbs_chk.setVisible(nbems_mode and (output_options or bbs_selected))
        if hasattr(self, "compose_priority_label"):
            self.compose_priority_label.setText("Priority")
            self.compose_priority_label.setVisible(nbems_mode and output_options)
        if hasattr(self, "compose_priority_combo"):
            self.compose_priority_combo.setVisible(nbems_mode and output_options)
        if hasattr(self, "compose_report_title_label"):
            self.compose_report_title_label.setVisible(nbems_mode)
        if hasattr(self, "compose_report_title_edit"):
            self.compose_report_title_edit.setVisible(nbems_mode)
        if hasattr(self, "compose_zulu_label"):
            self.compose_zulu_label.setVisible(nbems_mode and output_options)
        if hasattr(self, "compose_zulu_value"):
            self.compose_zulu_value.setVisible(nbems_mode and output_options)
        if hasattr(self, "compose_refresh_time_btn"):
            self.compose_refresh_time_btn.setVisible(nbems_mode and output_options)
        if hasattr(self, "compose_operator_row_widget"):
            self.compose_operator_row_widget.setVisible(nbems_mode and output_options)
        if hasattr(self, "compose_output_box"):
            self.compose_output_box.setTitle(
                "Mesh Send" if mesh_mode else
                "RF Send" if commstat_mode else
                "JS8 Send" if (js8_mode or spotter_mode) else
                "Staging Output"
            )

        if mesh_mode:
            self.compose_guidance_row_widget.hide()
        if hasattr(self, "compose_field_box"):
            self.compose_field_box.setVisible(True)
            if js8_mode:
                self.compose_field_box.setTitle("JS8 Message")
            elif commstat_mode:
                self.compose_field_box.setTitle("CommStat StatRep")
            elif mesh_mode:
                self.compose_field_box.setTitle("Mesh Message")
            else:
                self.compose_field_box.setTitle("CommsPlan Spotter Form Fields" if spotter_mode else "Form Fields")

        if hasattr(self, "compose_field_scroll"):
            self.compose_field_scroll.setVisible(not (js8_mode or commstat_mode or mesh_mode))
        if hasattr(self, "compose_rf_fields_stack"):
            self.compose_rf_fields_stack.setVisible(js8_mode or commstat_mode or mesh_mode)
            if js8_mode and hasattr(self, "compose_js8_plain_scroll"):
                self.compose_rf_fields_stack.setCurrentWidget(self.compose_js8_plain_scroll)
            elif commstat_mode and hasattr(self, "compose_commstat_scroll"):
                self.compose_rf_fields_stack.setCurrentWidget(self.compose_commstat_scroll)
            elif mesh_mode and hasattr(self, "compose_mesh_scroll"):
                self.compose_rf_fields_stack.setCurrentWidget(self.compose_mesh_scroll)
        if hasattr(self, "compose_nbems_dest_row_widget"):
            self.compose_nbems_dest_row_widget.setVisible(nbems_mode)
        if hasattr(self, "compose_nbems_folder_row_widget"):
            self.compose_nbems_folder_row_widget.setVisible(nbems_mode and (output_options or sign_flamp_selected or bbs_selected))
        if hasattr(self, "compose_js8_auth_row_widget"):
            auth_available = bool(spotter_mode and self._compose_js8_auth_key_count > 0)
            self.compose_js8_auth_row_widget.setVisible(auth_available)
            if not auth_available and hasattr(self, "compose_js8_sign_chk") and self.compose_js8_sign_chk.isChecked():
                previous_blocked = self.compose_js8_sign_chk.blockSignals(True)
                try:
                    self.compose_js8_sign_chk.setChecked(False)
                finally:
                    self.compose_js8_sign_chk.blockSignals(previous_blocked)
        if hasattr(self, "compose_expect_row_widget"):
            self.compose_expect_row_widget.setVisible(False)
            self.compose_save_expect_btn.setVisible(spotter_mode)
        if hasattr(self, "compose_save_expect_btn"):
            expect_active = bool(int(getattr(self, "_compose_spotter_expect_active_id", 0) or 0))
            self.compose_save_expect_btn.setText(
                "Save changes to Expect" if expect_active else "Save to Expect"
            )
            self.compose_save_expect_btn.setToolTip(
                "Persist this working copy to the selected Expect entry. Access policy and automation state are preserved."
                if expect_active else
                "Create a disabled, Saved-only Expect response. Review its access policy in Expect before enabling Auto reply."
            )
        if hasattr(self, "compose_spotter_source_row_widget"):
            self.compose_spotter_source_row_widget.setVisible(spotter_mode)
            self.compose_spotter_source_combo.setToolTip(self.compose_spotter_source_hint.text())
            self.compose_spotter_source_hint.setVisible(spotter_mode and bool(self._compose_spotter_decode_notice))
        if hasattr(self, "compose_spotter_source_refresh_btn"):
            self.compose_spotter_source_refresh_btn.setVisible(spotter_mode)
            self.compose_spotter_source_refresh_btn.setStyleSheet(button_style("muted", resolve_theme(self.settings)))
        if hasattr(self, "compose_spotter_source_hint"):
            self.compose_spotter_source_hint.setStyleSheet(
                label_style("muted", resolve_theme(self.settings), weight=600)
            )
        if hasattr(self, "compose_save_expect_inline_btn"):
            self.compose_save_expect_inline_btn.setVisible(False)
        # Preview uses the same datecode refresh and serializer as Send Now;
        # the timestamp is refreshed by the final-send path immediately before
        # this method runs, so the displayed payload never drifts from the
        # command handed to the guarded worker.
        expect_view = bool(
            dict(getattr(self, "_compose_intent", {}) or {}).get("expect_view", False)
            and not bool(getattr(self, "_compose_spotter_working_response_dirty", False))
        )
        spotter_issue = ""
        spotter_message_text = ""
        try:
            if spotter_selected:
                spotter_message_text = self._compose_spotter_message_text(
                    sign_for_target=False,
                    refresh_datecode=not expect_view,
                )
            spotter_command = self._compose_spotter_command(refresh_datecode=not expect_view) if spotter_selected else ""
        except ValueError as exc:
            spotter_command = ""
            spotter_message_text = ""
            spotter_issue = str(exc)
        if hasattr(self, "compose_js8_target_row_widget"):
            self.compose_js8_target_row_widget.setVisible(js8_mode or spotter_mode)
        if hasattr(self, "compose_js8_target_label"):
            self.compose_js8_target_label.setText("Send To" if js8_mode else "JS8 Target")
        if hasattr(self, "compose_js8_send_as_msg_chk"):
            self.compose_js8_send_as_msg_chk.setVisible(js8_mode or spotter_mode)
            self.compose_js8_send_as_msg_chk.setEnabled(js8_mode or spotter_mode)
        for widget in (
            getattr(self, "compose_js8_sign_chk", None),
            getattr(self, "compose_js8_auth_key_label", None),
            getattr(self, "compose_js8_auth_key_combo", None),
            getattr(self, "compose_js8_auth_datecode_chk", None),
            getattr(self, "compose_js8_auth_refresh_btn", None),
        ):
            if widget is not None:
                widget.setVisible(bool(spotter_mode and self._compose_js8_auth_key_count > 0))
        recommendation = (
            getattr(self, "_compose_send_recommendation", ComposeSendRecommendation())
            if (js8_mode or spotter_mode or commstat_mode)
            else ComposeSendRecommendation()
        )
        metadata = []
        if not (js8_mode or spotter_mode or commstat_mode or mesh_mode):
            metadata.append(f"<div><b>Compose For:</b> {html.escape(radio_label)}</div>")
            metadata.extend(
                [
                    f"<div><b>Filename:</b> {html.escape(filename)}</div>",
                    f"<div><b>Fast Light Format:</b> {html.escape(self._compose_fastlight_delimiter_guidance())}</div>",
                    f"<div><b>Message Folder:</b> {html.escape(self.compose_message_folder_combo.currentText() if hasattr(self, 'compose_message_folder_combo') and self.compose_message_folder_combo.count() else 'Messages')}</div>",
                    f"<div><b>Create File:</b> {html.escape(self.compose_send_target_combo.currentText())}</div>",
                    f"<div><b>Copy to VarAC:</b> {html.escape(self.compose_varac_target_combo.currentText())}</div>",
                ]
            )
        if js8_mode:
            metadata.extend(
                [
                    f"<div><b>JS8Call:</b> {html.escape(self._compose_plain_js8_kind())}</div>",
                    f"<div><b>Delivery:</b> {'Stored MSG' if self._compose_send_as_msg() else 'Directed traffic'}</div>",
                    f"<div><b>Send From:</b> {html.escape(self._compose_radio_short_label(profile) if isinstance(profile, dict) else radio_label)}</div>",
                    f"<div><b>Send To:</b> {html.escape(self._compose_intent_target() or 'Set a callsign or group for directed traffic')}</div>",
                    f"<div><b>RF Payload:</b> {html.escape(js8_plain_command or 'Enter short JS8 text to build the payload.')}</div>",
                ]
            )
        if spotter_selected:
            auth_selected = self._compose_js8_msg_auth_selected()
            auth_key = self._selected_compose_js8_msg_auth_key()
            auth_label = "Unsigned"
            if auth_selected and auth_key.get("key"):
                auth_label = f"Signed MsgAuth ({auth_key.get('label') or 'selected key'})"
            elif auth_selected:
                auth_label = "Sign MsgAuth selected; choose a matching key"
            metadata.extend(
                [
                    f"<div><b>Spotter Form:</b> {html.escape(self.compose_form_combo.currentText() if hasattr(self, 'compose_form_combo') else '')}</div>",
                    f"<div><b>Delivery:</b> {'Stored MSG' if self._compose_send_as_msg() else 'Directed traffic'}</div>",
                    f"<div><b>Send From:</b> {html.escape(self._compose_radio_short_label(profile) if isinstance(profile, dict) else radio_label)}</div>",
                    f"<div><b>JS8 Payload:</b> {html.escape(spotter_command or spotter_issue or 'Enter a JS8 target to build the payload.')}</div>",
                    f"<div><b>MsgAuth:</b> {html.escape(auth_label)}</div>",
                ]
            )
        if commstat_mode:
            metadata.extend(
                [
                    f"<div><b>CommStat RF:</b> StatRep</div>",
                    f"<div><b>Send From:</b> {html.escape(self._compose_radio_short_label(profile) if isinstance(profile, dict) else radio_label)}</div>",
                    f"<div><b>Send To:</b> {html.escape(self._compose_commstat_target() or 'Set a group or callsign')}</div>",
                    f"<div><b>RF Payload:</b> {html.escape(commstat_command or commstat_issue or 'Complete required fields to build payload.')}</div>",
                ]
            )
        if mesh_mode:
            destination_kind = str(
                self._compose_combo_data(getattr(self, "compose_mesh_destination_kind_combo", None)) or "channel"
            )
            destination_label = (
                self.compose_mesh_node_combo.currentText()
                if destination_kind == "direct" and hasattr(self, "compose_mesh_node_combo")
                else self.compose_mesh_channel_combo.currentText()
                if hasattr(self, "compose_mesh_channel_combo")
                else ""
            )
            if (
                destination_kind == "direct"
                and str(getattr(mesh_config, "protocol", "") or "").lower() == "meshtastic"
                and hasattr(self, "compose_mesh_channel_combo")
            ):
                destination_label = f"{destination_label} via {self.compose_mesh_channel_combo.currentText()}"
            adapter_label = str(getattr(mesh_config, "display_name", "") or "Not selected")
            protocol_label = str(getattr(mesh_config, "protocol", "mesh") or "mesh").title()
            evidence_label = (
                "Node acknowledgement requested" if destination_kind == "direct" and bool(
                    getattr(getattr(self, "compose_mesh_ack_chk", None), "isChecked", lambda: False)()
                ) else "Local transport acceptance"
            )
            metadata.extend(
                [
                    f"<div><b>Connection:</b> {html.escape(adapter_label)}</div>",
                    f"<div><b>Protocol:</b> {html.escape(protocol_label)}</div>",
                    f"<div><b>Destination:</b> {html.escape(destination_label or 'Choose a destination')}</div>",
                    f"<div><b>Evidence:</b> {html.escape(evidence_label)}</div>",
                ]
            )
        if (js8_mode or spotter_mode or commstat_mode) and recommendation.reason:
            metadata.append(f"<div><b>Send Guidance:</b> {html.escape(recommendation.reason)}</div>")
        if bbs_selected:
            bbs_targets = self._selected_compose_bbs_targets()
            labels = ", ".join(target.get("label", "") for target in bbs_targets if target.get("label"))
            publish_kind = "FLAmp" if self._compose_flamp_target_selected() else "FLMsg"
            metadata.append(
                f"<div><b>Add to BBS:</b> {html.escape(labels or 'Select at least one location')} "
                f"({publish_kind} artifact)</div>"
            )
        if sign_flamp_selected:
            metadata.append(
                f"<div><b>Signed FLAmp Name:</b> {html.escape(build_signed_filename(filename, filename_policy=self._compose_fastlight_filename_policy(), operating_group=self._compose_fastlight_target_group()))}</div>"
            )
            selected_signer = self._selected_compose_signing_fingerprint()
            if selected_signer:
                metadata.append(
                    f"<div><b>Signing Key:</b> {html.escape(self.compose_signing_key_combo.currentText())}</div>"
                )
            elif self._compose_signing_key_error:
                metadata.append(f"<div><b>Signing Key:</b> {html.escape(self._compose_signing_key_error)}</div>")
            elif self._compose_signing_key_count == 0:
                metadata.append("<div><b>Signing Key:</b> No private signing keys found.</div>")
            else:
                metadata.append("<div><b>Signing Key:</b> Select a private signing key.</div>")
        if mesh_mode:
            mesh_text = (
                self.compose_mesh_text_edit.toPlainText()
                if hasattr(self, "compose_mesh_text_edit") else ""
            )
            preview_body_html = (
                "<div><b>Exact Mesh Payload Preview</b></div>"
                f"<pre style='white-space: pre-wrap; margin-top: 6px;'>{html.escape(mesh_text or 'Enter a short mesh message.')}</pre>"
            )
        elif js8_mode:
            preview_body_html = (
                "<div><b>RF Payload Preview</b></div>"
                f"<pre style='white-space: pre-wrap; margin-top: 6px;'>{html.escape(js8_plain_command or 'Enter short JS8 text to build the payload.')}</pre>"
            )
        elif commstat_mode:
            preview_body_html = (
                "<div><b>RF Payload Preview</b></div>"
                f"<pre style='white-space: pre-wrap; margin-top: 6px;'>{html.escape(commstat_command or commstat_issue or 'Complete required fields to build payload.')}</pre>"
            )
        else:
            preview_body_html = preview_html
        self.compose_preview.setHtml("".join(metadata) + "<hr/>" + preview_body_html)
        self._refresh_compose_layout_geometry_if_needed()

        if (js8_mode or spotter_mode or commstat_mode or mesh_mode) and hasattr(self, "compose_destinations_label"):
            self.compose_destinations_label.setText("")
        ready_plans = [plan for plan in plans if plan.ready]
        signing_ready = (not sign_flamp_selected) or bool(self._selected_compose_signing_fingerprint())
        can_stage = (
            bool(ready_plans)
            and self._compose_has_valid_form_selection()
            and signing_ready
            and radio_target is not None
            and (not bbs_selected or bool(self._selected_compose_bbs_targets()))
            and not bool(getattr(self, "_compose_stage_inflight", False))
            and not (js8_mode or spotter_mode or commstat_mode or mesh_mode)
        )
        self.compose_stage_btn.setEnabled(can_stage)
        theme = resolve_theme(self.settings)
        self.compose_stage_btn.setVisible(not (js8_mode or spotter_mode or commstat_mode or mesh_mode))
        self.compose_stage_btn.setStyleSheet(button_style("primary" if can_stage else "muted", theme))
        can_send_js8 = bool(
            ((js8_mode and js8_plain_command) or (spotter_selected and spotter_command) or (commstat_mode and commstat_command))
            and radio_target is not None
            and "JS8Call" in tuple(radio_target.capabilities)
            and not bool(getattr(self, "_compose_send_inflight", False))
            and (js8_mode or commstat_mode or ((not self._compose_js8_msg_auth_selected()) or bool(self._selected_compose_js8_msg_auth_key())))
        )
        if hasattr(self, "compose_send_js8_btn"):
            self.compose_send_js8_btn.setVisible(js8_mode or spotter_mode or commstat_mode)
            self.compose_send_js8_btn.setEnabled(can_send_js8)
            source_label = self._compose_radio_short_label(profile) if isinstance(profile, dict) else radio_label
            js8_count = len([target for target in self._compose_radio_targets if "JS8Call" in tuple(target.capabilities)])
            if spotter_saved_selected:
                saved_key = "Saved response"
                for row in getattr(self, "_compose_spotter_expect_entries", []) or []:
                    try:
                        if int(row.get("id", 0) or 0) == int(self._compose_spotter_expect_active_id):
                            saved_key = str(row.get("expect_key", "") or "Saved response").strip().upper()
                            break
                    except (TypeError, ValueError):
                        continue
                self.compose_send_js8_btn.setText(f"Send Now: {saved_key}")
            else:
                self.compose_send_js8_btn.setText(f"Send Now: {source_label}" if js8_count > 1 and source_label else "Send Now")
            if js8_mode:
                self.compose_send_js8_btn.setToolTip("Send short JS8Call traffic after target-state and radio guidance preflight.")
            elif commstat_mode:
                self.compose_send_js8_btn.setToolTip("Send short CommStat RF traffic through the selected JS8Call radio.")
            else:
                self.compose_send_js8_btn.setToolTip(
                    "Send the selected saved response or CommsPlan Spotter form now through JS8Call after safety preflight."
                )
            self.compose_send_js8_btn.setStyleSheet(button_style("primary" if can_send_js8 else "muted", theme))
        if hasattr(self, "compose_send_mesh_btn"):
            mesh_health = (
                self._compose_mesh_health_by_adapter.get(str(getattr(mesh_config, "adapter_id", "") or ""), {})
                if mesh_config is not None else {}
            )
            max_bytes = 160 if str(getattr(mesh_config, "protocol", "")).lower() == "meshcore" else 220
            payload_bytes = len(str(getattr(mesh_request, "text", "") or "").encode("utf-8")) if mesh_request else 0
            can_send_mesh = bool(
                not getattr(self, "_compose_mesh_loading", False)
                and mesh_mode
                and mesh_request is not None
                and bool(mesh_health.get("connected"))
                and payload_bytes <= max_bytes
                and not self._compose_mesh_send_inflight
            )
            self.compose_send_mesh_btn.setVisible(mesh_mode)
            self.compose_send_mesh_btn.setEnabled(can_send_mesh)
            self.compose_send_mesh_btn.setStyleSheet(button_style("primary" if can_send_mesh else "muted", theme))
            if hasattr(self, "compose_mesh_hint_label") and mesh_mode:
                if bool(getattr(self, "_compose_mesh_loading", False)):
                    hint = "Loading mesh connections…"
                elif mesh_config is None:
                    hint = "Enable sending for a qualified Local Mesh connection in Settings."
                elif not bool(mesh_health.get("connected")):
                    hint = "This connection is offline. Connect it before sending."
                elif payload_bytes > max_bytes:
                    hint = f"Payload is {payload_bytes} bytes; {getattr(mesh_config, 'protocol', 'mesh').title()} is limited to {max_bytes} bytes in CommsPlan."
                else:
                    hint = f"Connected · {payload_bytes}/{max_bytes} UTF-8 bytes · automatic relays remain off."
                self.compose_mesh_hint_label.setText(hint)
            self._update_compose_mesh_contact_controls()
            theme = resolve_theme(self.settings)
            if hasattr(self, "compose_mesh_contact_history_btn"):
                self.compose_mesh_contact_history_btn.setStyleSheet(button_style("secondary", theme))
            if hasattr(self, "compose_mesh_contact_favorite_btn"):
                self.compose_mesh_contact_favorite_btn.setStyleSheet(button_style("secondary", theme))
        if hasattr(self, "compose_save_expect_btn"):
            self.compose_save_expect_btn.setEnabled(bool(
                spotter_selected
                and spotter_message_text
                and not self._expect_view_is_read_only()
                and ((not self._compose_js8_msg_auth_selected()) or bool(self._selected_compose_js8_msg_auth_key()))
            ))
            self.compose_save_expect_btn.setStyleSheet(
                button_style(
                    "secondary"
                    if self.compose_save_expect_btn.isEnabled()
                    else "muted",
                    theme,
                )
            )
        for btn in (
            self.compose_open_flmsg_btn,
            self.compose_open_flamp_btn,
            self.compose_open_folder_btn,
            self.compose_copy_paths_btn,
            self.compose_refresh_time_btn,
            self.compose_choose_message_folder_btn,
            self.compose_refresh_signing_keys_btn,
            self.compose_js8_auth_refresh_btn,
            self.compose_inline_reset_btn,
        ):
            btn.setStyleSheet(button_style("muted", theme))
        self.compose_open_flmsg_btn.setEnabled(
            bool(self._compose_profile_text(profile, "flmsg_path"))
            or self._compose_launch_orchestrator.is_configured("FLMsg")
        )
        self.compose_open_flamp_btn.setEnabled(
            bool(self._compose_profile_text(profile, "flamp_path"))
            or self._compose_launch_orchestrator.is_configured("FLAmp")
        )
        has_paths = bool(self._compose_last_stage_paths or ready_plans)
        self.compose_open_folder_btn.setEnabled(has_paths)
        self.compose_copy_paths_btn.setEnabled(has_paths)
        for btn in (
            self.compose_open_flmsg_btn,
            self.compose_open_flamp_btn,
            self.compose_open_folder_btn,
            self.compose_copy_paths_btn,
        ):
            btn.setVisible(not (js8_mode or spotter_mode or commstat_mode or mesh_mode))
        validation_hint = ""
        if mesh_mode and not self.compose_send_mesh_btn.isEnabled():
            validation_hint = self.compose_mesh_hint_label.text()
        elif (js8_mode or spotter_mode or commstat_mode) and not can_send_js8:
            if radio_target is None or "JS8Call" not in tuple(radio_target.capabilities):
                validation_hint = "Choose a JS8Call send radio."
            elif spotter_mode and not spotter_selected:
                validation_hint = "Choose a CommsPlan Spotter form or saved response."
            elif spotter_issue or commstat_issue:
                validation_hint = spotter_issue or commstat_issue
            else:
                validation_hint = "Enter a destination and complete the message before sending."
        elif nbems_mode and not can_stage:
            if not ready_plans:
                validation_hint = "Configure a message destination for this radio."
            elif not signing_ready:
                validation_hint = "Choose a signing key in Output options."
            elif bbs_selected and not self._selected_compose_bbs_targets():
                validation_hint = "Choose a managed BBS location in Output options."
            else:
                validation_hint = "Choose a form before staging."
        previous_hint = str(getattr(self, "_compose_validation_hint", "") or "")
        if self.compose_status_label.text() in {"Compose is ready.", previous_hint}:
            self.compose_status_label.setText(validation_hint or "Compose is ready.")
        self._compose_validation_hint = validation_hint
        self._refresh_compose_footer_geometry()

    def _send_compose_js8_spotter(self) -> None:
        if self._compose_send_inflight:
            self._set_compose_status("A JS8 send is already in progress.", role="info")
            return
        if not self._compose_radio_targets_loaded:
            self._refresh_compose_radio_targets()
        mode = str(getattr(self, "_compose_mode", "nbems") or "nbems")
        js8_mode = mode == "js8"
        commstat_mode = mode == "commstat_rf"
        has_saved_spotter = bool(
            int(getattr(self, "_compose_spotter_expect_active_id", 0) or 0) > 0
            and str(getattr(self, "_compose_spotter_working_response", "") or "").strip()
        )
        if not (js8_mode or commstat_mode) and self._compose_template_kind != "spotter" and not has_saved_spotter:
            self._set_compose_status("Select a CommsPlan Spotter form before sending via JS8Call.", role="warning")
            return
        try:
            command = (
                self._compose_plain_js8_command()
                if js8_mode
                else self._compose_commstat_rf_text()
                if commstat_mode
                else self._compose_spotter_command(refresh_datecode=True)
            )
        except Exception as exc:
            label = "CommStat RF" if commstat_mode else "JS8Call"
            self._set_compose_status(f"Complete {label} fields before sending: {exc}", role="warning")
            return
        if not command:
            if js8_mode and self._compose_plain_js8_kind() == "Directed Message":
                self._set_compose_status("Enter a JS8 target and short message text before sending.", role="warning")
            else:
                self._set_compose_status("Enter a JS8 target and complete the RF payload before sending.", role="warning")
            return
        typed_target = self._compose_intent_target()
        if typed_target and not typed_target.startswith("@") and self._compose_base_callsign(typed_target) == self._compose_base_callsign(self._compose_operator_callsign()):
            self._set_compose_status("Choose another station before sending. CommsPlan will not send a message to your own callsign.", role="warning")
            return
        if not (js8_mode or commstat_mode) and self._compose_js8_msg_auth_selected() and not self._selected_compose_js8_msg_auth_key():
            self._set_compose_status("Select a matching MsgAuth key before sending a signed CommsPlan Spotter message.", role="warning")
            return
        radio_target = self._selected_compose_radio_target()
        if radio_target is None:
            self._set_compose_status("Select a JS8Call-capable radio before sending.", role="warning")
            return
        if "JS8Call" not in tuple(radio_target.capabilities):
            radio_short_label = self._compose_radio_target_short_label(radio_target) or radio_target.label
            self._set_compose_status(f"{radio_short_label} is not configured for JS8Call send.", role="warning")
            return
        if not js8_profile_allows_transmit(radio_target.profile):
            self._set_compose_status(
                "Observer / SDR JS8Call instances are receive-only and cannot send messages.",
                role="warning",
            )
            return
        if not self._compose_confirm_peer_schedule_before_send():
            return
        if not (js8_mode or commstat_mode):
            # Refresh only the outgoing copy.  The saved Expect row and the
            # editable working draft remain unchanged.  Updating the preview
            # immediately after this snapshot keeps what the operator sees
            # byte-for-byte aligned with the guarded worker command.
            self._compose_timestamp_utc = datetime.datetime.now(datetime.timezone.utc)
            command = self._compose_spotter_command(refresh_datecode=True)
            if not command:
                self._set_compose_status("Complete the Spotter response before sending.", role="warning")
                return
            self._update_compose_preview()
        endpoint = js8_endpoint_from_radio_profile(radio_target.profile, fallback_settings=self.settings)
        label = "JS8Call" if js8_mode else "CommStat RF" if commstat_mode else "CommsPlan Spotter"
        radio_short_label = self._compose_radio_target_short_label(radio_target) or radio_target.label
        self._compose_action_generation += 1
        self._compose_send_context = {
            "label": label,
            "radio_label": radio_short_label,
            "command": command,
            "endpoint": endpoint,
            "generation": self._compose_action_generation,
        }
        self._start_compose_js8_send_worker(
            endpoint=endpoint,
            command=command,
            generation=self._compose_action_generation,
            allow_uncertain_target_state=False,
        )

    def _start_compose_js8_send_worker(
        self,
        *,
        endpoint: JS8ApiEndpoint,
        command: str,
        generation: int,
        allow_uncertain_target_state: bool,
    ) -> None:
        self._compose_send_inflight = True
        self._set_compose_status("Checking JS8Call and queueing the message…", role="info")
        self._update_compose_preview()
        self._compose_send_thread = QThread(self)
        self._compose_send_worker = _ComposeJs8SendWorker(
            endpoint=endpoint,
            command=command,
            generation=generation,
            allow_uncertain_target_state=allow_uncertain_target_state,
        )
        self._compose_send_worker.moveToThread(self._compose_send_thread)
        self._compose_send_thread.started.connect(self._compose_send_worker.run)
        self._compose_send_worker.finished.connect(self._on_compose_js8_send_finished)
        self._compose_send_worker.finished.connect(self._compose_send_thread.quit)
        self._compose_send_worker.finished.connect(self._compose_send_worker.deleteLater)
        self._compose_send_thread.finished.connect(self._on_compose_js8_send_thread_finished)
        self._compose_send_thread.finished.connect(self._compose_send_thread.deleteLater)
        self._compose_send_thread.start()

    def _on_compose_js8_send_thread_finished(self) -> None:
        self._retain_finished_worker_refs(self._compose_send_thread, self._compose_send_worker)
        self._compose_send_thread = None
        self._compose_send_worker = None
        retry = dict(getattr(self, "_compose_send_retry_pending", {}) or {})
        self._compose_send_retry_pending = {}
        if retry and not self._is_shutting_down:
            endpoint = retry.get("endpoint")
            if isinstance(endpoint, JS8ApiEndpoint):
                self._start_compose_js8_send_worker(
                    endpoint=endpoint,
                    command=str(retry.get("command", "") or ""),
                    generation=int(retry.get("generation", 0) or 0),
                    allow_uncertain_target_state=True,
                )
                return
        self._compose_send_inflight = False
        if not self._is_shutting_down:
            self._update_compose_preview()

    def _on_compose_js8_send_finished(self, payload: object) -> None:
        if self._is_shutting_down:
            return
        data = payload if isinstance(payload, dict) else {}
        error = str(data.get("error", "") or "").strip()
        result = data.get("result")
        context = dict(getattr(self, "_compose_send_context", {}) or {})
        generation = int(data.get("generation", 0) or 0)
        if error or result is None:
            self._set_compose_status(f"JS8Call send failed: {error or 'No result returned.'}", role="warning")
            self._update_compose_preview()
            return
        if not bool(getattr(result, "sent", False)):
            issues = list(getattr(getattr(result, "preflight", None), "issues", []) or [])
            issue_codes = [str(getattr(issue, "code", "") or "") for issue in issues]
            if issue_codes == ["target_state_unknown"] and not bool(data.get("allow_uncertain", False)):
                endpoint = data.get("endpoint")
                detail = str(getattr(issues[0], "detail", "") or "")
                endpoint_label = (
                    f"{endpoint.host}:{endpoint.port}" if isinstance(endpoint, JS8ApiEndpoint) else "the selected JS8Call endpoint"
                )
                confirm = QMessageBox.question(
                    self,
                    "JS8Call Target State Unverified",
                    f"{detail}\n\nSend anyway to {endpoint_label}?",
                    QMessageBox.Yes | QMessageBox.No,
                    QMessageBox.No,
                )
                if confirm == QMessageBox.Yes and isinstance(endpoint, JS8ApiEndpoint):
                    self._compose_send_retry_pending = {
                        "endpoint": endpoint,
                        "command": str(data.get("command", "") or ""),
                        "generation": generation,
                    }
                    self._compose_send_inflight = True
                    self._set_compose_status("Retrying after operator confirmation…", role="info")
                    return
            self._set_compose_status(str(getattr(result, "detail", "") or "JS8Call send was not accepted."), role="warning")
            self._update_compose_preview()
            return
        label = str(context.get("label", "") or "JS8Call")
        radio_label = str(context.get("radio_label", "") or "selected radio")
        command = str(data.get("command", "") or context.get("command", "") or "")
        self._set_compose_status(
            f"Queued {label} message via {radio_label}: {command}",
            role="success",
        )
        self._update_compose_preview()
    def _save_compose_js8_expect(self) -> None:
        active_id = int(getattr(self, "_compose_spotter_expect_active_id", 0) or 0)
        if self._compose_template_kind != "spotter" and active_id <= 0:
            self._set_compose_status("Select a CommsPlan Spotter form before saving to Expect.", role="warning")
            return
        try:
            message_text = self._compose_spotter_message_text(sign_for_target=False)
        except ValueError as exc:
            self._set_compose_status(f"Complete the Spotter form before saving: {exc}", role="warning")
            return
        form_data = self.compose_form_combo.currentData() if hasattr(self, "compose_form_combo") else None
        active_entry: Dict[str, object] = {}
        for row in getattr(self, "_compose_spotter_expect_entries", []) or []:
            try:
                if int(row.get("id", 0) or 0) == active_id:
                    active_entry = dict(row)
                    break
            except (TypeError, ValueError):
                continue
        expect_key = (
            str(active_entry.get("expect_key", "") or "").strip().upper()
            if active_entry else
            str((form_data or {}).get("code", "") or "").strip().upper()
            if isinstance(form_data, dict) else ""
        )
        if not message_text or not expect_key:
            self._set_compose_status("Complete the Spotter form before saving to Expect.", role="warning")
            return
        include_datecode = bool(
            hasattr(self, "compose_js8_auth_datecode_chk") and self.compose_js8_auth_datecode_chk.isChecked()
        )
        stored_datecode = encode_short_datecode(self._compose_timestamp_utc) if include_datecode else ""
        if active_entry:
            # Editing is explicitly opt-in. Preserve the existing access,
            # policy, routing and auto-reply state; only the response payload
            # (and optional signing datecode) comes from this working copy.
            payload = dict(active_entry)
            payload.update({
                "expect_key": expect_key,
                "response_text": message_text,
                "msg_auth_include_datecode": include_datecode,
                "msg_auth_datecode": stored_datecode if include_datecode else active_entry.get("msg_auth_datecode", ""),
                "import_source": "fio-compose-expect-edit",
            })
        else:
            # New Compose-created Expect entries are always disabled/saved-only
            # until the operator reviews policy and deliberately enables them
            # in Expect.
            payload = {
                "source_radio_id": "",
                "source_scope": "all",
                "js8_instance_id": "",
                "expect_key": expect_key,
                "response_text": message_text,
                "msg_auth_sign_enabled": self._compose_js8_msg_auth_selected(),
                "msg_auth_sign_callsign": self._compose_operator_callsign(),
                "msg_auth_include_datecode": include_datecode,
                "msg_auth_datecode": stored_datecode,
                "allowed_groups": [],
                "enabled": False,
                "auto_reply_enabled": False,
                "unattended_auto_reply_enabled": False,
                "import_source": "fio-compose-js8spotter",
                "create_only": True,
            }
        try:
            result = save_expect_entry(payload)
        except ExpectEntryExistsError as exc:
            self._set_compose_status(
                f"Expect rule {exc.expect_key} already exists. Opening CommsPlan Spotter to review it; "
                "Compose did not replace its access or auto-reply policy.",
                role="warning",
            )
            self._open_saved_expect_rule(entry_id=exc.entry_id, expect_key=exc.expect_key)
            return
        except Exception as exc:
            self._set_compose_status(f"Could not save Expect entry: {exc}", role="warning")
            return
        self._set_compose_status(
            (
                f"Created Saved-only Expect draft for {result.expect_key}. Opening it for policy review."
                if result.created else
                f"Updated Expect response {result.expect_key}. Its access policy and automation state were preserved."
            ),
            role="success",
        )
        self._open_saved_expect_rule(entry_id=result.id, expect_key=result.expect_key)

    def _open_saved_expect_rule(self, *, entry_id: int, expect_key: str) -> None:
        host = self.window()
        callback = getattr(host, "open_fio_spotter_expect", None)
        if callable(callback):
            callback(entry_id=entry_id, expect_key=expect_key)
            return
        self._set_compose_status(
            f"Saved {expect_key}. Open CommsPlan Spotter > Expect to review access before enabling it.",
            role="success",
        )

    def _compose_stage_request_snapshot(self) -> ComposeStageRequest | None:
        if not self._compose_has_valid_form_selection():
            self._set_compose_status("Select a compose form before staging files.", role="warning")
            return None
        if not self._compose_radio_targets_loaded:
            self._refresh_compose_radio_targets()
        # Re-probe and collision-reserve the current destinations immediately
        # before the worker snapshot. Preview rendering uses only cached plans.
        plans = self._refresh_compose_destination_plans()
        ready_plans = [plan for plan in plans if plan.ready]
        if not ready_plans:
            self._set_compose_status("No ready compose destinations are available.", role="warning")
            return None
        sign_flamp = self._compose_sign_flamp_selected()
        signer_fingerprint = self._selected_compose_signing_fingerprint() if sign_flamp else ""
        if sign_flamp and not signer_fingerprint:
            self._set_compose_status("Select a private signing key before staging a signed FLAmp copy.", role="warning")
            return None
        radio_target = self._selected_compose_radio_target()
        if radio_target is None:
            self._set_compose_status("Select a radio profile before staging compose files.", role="warning")
            return None
        publish_to_bbs = bool(
            hasattr(self, "compose_publish_bbs_chk") and self.compose_publish_bbs_chk.isChecked()
        )
        bbs_targets = self._selected_compose_bbs_targets() if publish_to_bbs else []
        if publish_to_bbs and not bbs_targets:
            self._set_compose_status("Select at least one enabled Managed BBS location.", role="warning")
            return None
        self._compose_action_generation += 1
        trusted_raw = self.settings.get("gpg_trusted_signers", []) or []
        if isinstance(trusted_raw, str):
            trusted = tuple(value.strip() for value in trusted_raw.split(",") if value.strip())
        else:
            trusted = tuple(str(value or "").strip() for value in trusted_raw if str(value or "").strip())
        return ComposeStageRequest(
            payload=self._compose_current_payload(),
            unsigned_name=self._compose_base_filename(),
            plans=tuple(plans),
            radio_id=str(radio_target.radio_id),
            radio_label=self._compose_radio_target_short_label(radio_target) or radio_target.label,
            sign_flamp=sign_flamp,
            signer_fingerprint=signer_fingerprint,
            gpg_path=str(self.settings.get("gpg_executable_path", "") or "").strip(),
            trusted_fingerprints=trusted,
            publish_to_bbs=publish_to_bbs,
            bbs_db_path=str(bbs_library_db_path_from_settings(self.settings)) if publish_to_bbs else "",
            bbs_location_ids=tuple(str(target.get("location_id", "") or "") for target in bbs_targets),
            bbs_location_names=tuple(str(target.get("label", "") or "") for target in bbs_targets),
            source_id=f"compose:{self._compose_base_filename()}",
            metadata=(
                ("form", str(self.compose_form_combo.currentText() if hasattr(self, "compose_form_combo") else "")),
                ("group", self._compose_fastlight_target_group()),
            ),
            generation=self._compose_action_generation,
        )

    def _stage_compose_files(self) -> None:
        if self._compose_stage_inflight:
            self._set_compose_status("Compose staging is already in progress.", role="info")
            return
        from freqinout.core.traffic_summary import REPORT_MARKER
        if (getattr(self, "_compose_summary_context", None) is None
                and REPORT_MARKER in self._compose_field_values().get("MESSAGE", "")):
            self._set_compose_status("Load this saved report through Create Traffic Summary before staging, so its evidence, counts and retry identity can be verified.", role="warning")
            return
        request = self._compose_stage_request_snapshot()
        if request is None:
            return
        self._compose_stage_inflight = True
        self._set_compose_status("Staging compose files…", role="info")
        self._update_compose_preview()
        self._compose_stage_thread = QThread(self)
        context = getattr(self, "_compose_summary_context", None)
        if context is not None:
            if self._compose_template_kind != "blank":
                self._compose_stage_inflight = False
                self._set_compose_status("Traffic summaries must use Standard Blank. Reset the Compose draft to start another message.", role="warning")
                self._compose_stage_thread.deleteLater()
                self._compose_stage_thread = None
                return
            context = replace(context, edited_text=self._compose_field_values().get("MESSAGE", ""))
        self._compose_stage_worker = _ComposeStageWorker(request, context)
        self._compose_stage_worker.moveToThread(self._compose_stage_thread)
        self._compose_stage_thread.started.connect(self._compose_stage_worker.run)
        self._compose_stage_worker.finished.connect(self._on_compose_stage_finished)
        self._compose_stage_worker.finished.connect(self._compose_stage_thread.quit)
        self._compose_stage_worker.finished.connect(self._compose_stage_worker.deleteLater)
        self._compose_stage_thread.finished.connect(self._on_compose_stage_thread_finished)
        self._compose_stage_thread.finished.connect(self._compose_stage_thread.deleteLater)
        self._compose_stage_thread.start()

    def _on_compose_stage_thread_finished(self) -> None:
        self._retain_finished_worker_refs(self._compose_stage_thread, self._compose_stage_worker)
        self._compose_stage_thread = None
        self._compose_stage_worker = None
        self._compose_stage_inflight = False
        if not self._is_shutting_down:
            self._update_compose_preview()

    def _on_compose_stage_finished(self, payload: object) -> None:
        if self._is_shutting_down:
            return
        result = payload if isinstance(payload, ComposeStageResult) else ComposeStageResult(
            generation=self._compose_action_generation,
            problems=("Compose staging returned an invalid result.",),
        )
        outputs = [Path(value) for value in result.outputs]
        self._compose_last_stage_paths = outputs
        lines: List[str] = []
        if outputs:
            lines.append(f"Staged {len(outputs)} compose file(s).")
            for path in outputs:
                lines.append(str(path))
        else:
            lines.append("No compose files were staged.")
        if result.bbs_artifact_id:
            names = ", ".join(str(value or "") for value in result.bbs_location_names if str(value or ""))
            lines.append(f"Published to Managed BBS: {names or len(result.bbs_location_ids)}.")
            self._invalidate_bbs_action_cache()
        lines.extend(result.skipped)
        lines.extend(result.signature_notes)
        lines.extend(result.problems)
        if outputs:
            lines.append("Draft retained. Reset it when you are ready for the next message.")
        role = "success" if outputs and not result.problems and not result.skipped else "warning"
        self._set_compose_status("\n".join(lines), role=role)
        self._update_compose_preview()

    @staticmethod
    def _normalize_excluded_msg_types(values) -> set[str]:
        out: set[str] = set()
        if not isinstance(values, (list, tuple, set)):
            return out
        for value in values:
            label = str(value or "").strip()
            if label and label != "MSG Type...":
                out.add(label)
        return out

    @staticmethod
    def _row_matches_type_filter(row: UnifiedMessage, type_sel: str) -> bool:
        return _core_row_matches_type_filter(row, type_sel)

    def _row_matches_excluded_type(self, row: UnifiedMessage) -> bool:
        return _core_row_matches_excluded_types(row, self._excluded_msg_types)

    def _rebuild_excluded_types_menu(self, type_vals: List[str]) -> None:
        if not hasattr(self, "_exclude_types_menu") or self._exclude_types_menu is None:
            return
        self._available_type_filters = [str(v).strip() for v in (type_vals or []) if str(v).strip()]
        menu_key = (tuple(self._available_type_filters), tuple(sorted(self._excluded_msg_types)))
        if menu_key == getattr(self, "_excluded_types_menu_key", None):
            self._update_excluded_types_button_state()
            return
        ordered: List[str] = []
        seen: set[str] = set()
        for label in self._available_type_filters + sorted(self._excluded_msg_types):
            if not label or label == "MSG Type..." or label in seen:
                continue
            seen.add(label)
            ordered.append(label)
        menu = self._exclude_types_menu
        menu.clear()
        self._excluded_types_menu_key = menu_key
        if self._excluded_msg_types:
            clear_action = menu.addAction("Show All Hidden Types")
            clear_action.triggered.connect(self._clear_excluded_types)
            menu.addSeparator()
        if not ordered:
            empty_action = menu.addAction("No message types available")
            empty_action.setEnabled(False)
            self._update_excluded_types_button_state()
            return
        for label in ordered:
            action = menu.addAction(label)
            action.setCheckable(True)
            action.setChecked(label in self._excluded_msg_types)
            action.toggled.connect(lambda checked, key=label: self._on_excluded_type_toggled(key, checked))
        self._update_excluded_types_button_state()

    def _on_excluded_type_toggled(self, label: str, checked: bool) -> None:
        key = str(label or "").strip()
        if not key:
            return
        changed = False
        if checked:
            if key not in self._excluded_msg_types:
                self._excluded_msg_types.add(key)
                changed = True
        else:
            if key in self._excluded_msg_types:
                self._excluded_msg_types.discard(key)
                changed = True
        if not changed:
            return
        self._save_settings()
        self._update_excluded_types_button_state()
        self._apply_message_filters_preserve_scroll()

    def _clear_excluded_types(self) -> None:
        if not self._excluded_msg_types:
            return
        self._excluded_msg_types.clear()
        self._save_settings()
        self._update_excluded_types_button_state()
        self._apply_message_filters_preserve_scroll()

    def _update_excluded_types_button_state(self) -> None:
        if not hasattr(self, "exclude_types_btn"):
            return
        hidden_count = len(self._excluded_msg_types)
        self.exclude_types_btn.setText(f"Hide Types ({hidden_count})" if hidden_count else "Hide Types")
        theme = resolve_theme(self.settings)
        role = "eligible_warning" if hidden_count else "muted"
        self.exclude_types_btn.setStyleSheet(button_style(role, theme))
        if not hidden_count:
            self.exclude_types_btn.setToolTip("Hide selected message types from the default view.")
            return
        hidden_labels = ", ".join(sorted(self._excluded_msg_types))
        current_type = self.type_filter.currentText() if hasattr(self, "type_filter") else "MSG Type..."
        if current_type not in ("", "MSG Type..."):
            self.exclude_types_btn.setToolTip(
                f"Hidden by default: {hidden_labels}. Current MSG Type selection overrides hidden types."
            )
        else:
            self.exclude_types_btn.setToolTip(f"Hidden by default: {hidden_labels}")

    # ---------- Timer ----------

    def _setup_timer(self):
        if self._timer:
            self._timer.stop()
        self._timer = QTimer(self)
        self._timer.timeout.connect(self._refresh_files)
        if self._has_active_view and self._app_active and not self._is_shutting_down:
            self._timer.start(self.scan_minutes * 60 * 1000)

    def _setup_js8_timer(self):
        if self._js8_timer:
            self._js8_timer.stop()
        self._js8_timer = QTimer(self)
        self._js8_timer.timeout.connect(lambda: self._refresh_js8_messages(force=False, rebuild=False))
        if self._has_active_view and self._app_active and not self._is_shutting_down:
            self._js8_timer.start(JS8_POLL_SECONDS * 1000)

    def _setup_pending_timer(self):
        if self._pending_timer:
            self._pending_timer.stop()
        self._pending_timer = QTimer(self)
        self._pending_timer.timeout.connect(self._refresh_pending_backlog)
        if self._has_active_view and self._app_active and not self._is_shutting_down:
            self._pending_timer.start(PENDING_POLL_SECONDS * 1000)

    def _setup_bbs_auto_archive_timer(self):
        if self._bbs_auto_archive_timer:
            self._bbs_auto_archive_timer.stop()
        self._bbs_auto_archive_timer = QTimer(self)
        self._bbs_auto_archive_timer.timeout.connect(self._on_bbs_auto_archive_timer)
        if self._has_active_view and self._app_active and not self._is_shutting_down:
            self._bbs_auto_archive_timer.start(int(self._bbs_auto_archive_interval_sec * 1000))

    def _on_bbs_auto_archive_timer(self) -> None:
        self._queue_bbs_auto_archive_check("timer", delay_ms=0)

    def _setup_message_check_timer(self) -> None:
        if self._message_check_timer:
            self._message_check_timer.stop()
        self._message_check_timer = QTimer(self)
        self._message_check_timer.timeout.connect(self._on_visible_message_check_timer)
        self._sync_message_check_timer()

    def _setup_file_system_watcher(self) -> None:
        if self._file_system_watcher is None:
            self._file_system_watcher = QFileSystemWatcher(self)
            self._file_system_watcher.directoryChanged.connect(self._on_watched_message_directory_changed)
        if self._file_watch_debounce_timer is None:
            self._file_watch_debounce_timer = QTimer(self)
            self._file_watch_debounce_timer.setSingleShot(True)
            self._file_watch_debounce_timer.timeout.connect(self._on_file_watch_debounce)
        self._sync_file_system_watcher()

    def _sync_file_system_watcher(self) -> None:
        watcher = getattr(self, "_file_system_watcher", None)
        if watcher is None:
            return
        desired: Set[str] = set()
        for entry in self._effective_watch_dirs():
            raw = str(entry.get("path", "") or "").strip()
            if not raw:
                continue
            path = Path(raw).expanduser()
            if path.exists() and path.is_dir():
                desired.add(str(path))
        current = set(watcher.directories())
        remove = sorted(current - desired)
        add = sorted(desired - current)
        if remove:
            watcher.removePaths(remove)
        if add:
            watcher.addPaths(add)

    def _on_watched_message_directory_changed(self, _path: str) -> None:
        if self._is_shutting_down:
            return
        timer = getattr(self, "_file_watch_debounce_timer", None)
        if timer is not None:
            timer.start(350)

    def _on_file_watch_debounce(self) -> None:
        if self._is_shutting_down:
            return
        self._sync_file_system_watcher()
        self._refresh_files(force=False)

    def _setup_projection_delete_queue_timer(self) -> None:
        if self._projection_delete_queue_timer:
            self._projection_delete_queue_timer.stop()
        self._projection_delete_queue_timer = QTimer(self)
        self._projection_delete_queue_timer.timeout.connect(self._process_projection_delete_queue)
        if self._has_active_view and self._app_active and not self._is_shutting_down:
            self._projection_delete_queue_timer.start(MESSAGE_PROJECTION_QUEUE_POLL_SECONDS * 1000)

    def _process_projection_delete_queue(self) -> None:
        if self._is_shutting_down:
            return
        db_path = self._db_path()
        if db_path is None or not db_path.exists():
            return
        try:
            counts = process_message_delete_queue(db_path, limit=25)
        except Exception as exc:
            log.debug("MessageViewer: failed to process message delete queue: %s", exc)
            return
        if any(int(value or 0) for value in counts.values()):
            log.debug("MessageViewer: processed message delete queue %s", counts)

    def _sync_message_check_timer(self) -> None:
        if self._message_check_timer is None:
            self._message_check_timer = QTimer(self)
            self._message_check_timer.timeout.connect(self._on_visible_message_check_timer)
        active = (
            bool(self._has_active_view)
            and bool(self._app_active)
            and self._messages_mode == "Inbox"
            and int(self._visible_check_interval_sec or 0) > 0
            and not self._is_shutting_down
        )
        if not active:
            self._message_check_timer.stop()
            self._next_visible_message_check_ts = 0.0
            self._update_message_check_status()
            return
        interval_ms = max(15, int(self._visible_check_interval_sec or 30)) * 1000
        self._message_check_timer.start(interval_ms)
        self._next_visible_message_check_ts = time.time() + max(15, int(self._visible_check_interval_sec or 30))
        self._update_message_check_status()

    def _message_source_count(self) -> int:
        return (
            len(self.js8_messages)
            + len(self.spotter_messages)
            + len(self.varac_messages)
            + len(self.sitrep_messages)
            + len(self.commstat_messages)
            + sum(len(v) for v in self.files.values())
        )

    @staticmethod
    def _source_text_hash(value: object) -> int:
        return hash(str(value or "")) & 0xFFFFFFFF

    @staticmethod
    def _message_row_source_identity(msg: object) -> Tuple[object, ...]:
        return (
            str(getattr(msg, "source_key", "") or ""),
            str(getattr(msg, "source_id", "") or ""),
            str(getattr(msg, "source_radio_id", "") or ""),
            str(getattr(msg, "js8_instance_id", "") or ""),
            str(getattr(msg, "source_path", "") or ""),
        )

    def _message_sources_fingerprint(self) -> Tuple[object, ...]:
        return (
            ("files", self._files_records_fingerprint(self.files)),
            (
                "js8",
                tuple(
                    sorted(
                        (
                            self._message_row_source_identity(msg),
                            int(msg.msg_id or 0),
                            str(msg.state or "").upper(),
                            int(float(msg.utc_ts or 0.0) * 1000.0),
                            int(msg.flag_state or 0),
                            self._source_text_hash(msg.raw_text),
                        )
                        for msg in self.js8_messages
                    )
                ),
            ),
            (
                "spotter",
                tuple(
                    sorted(
                        (
                            self._message_row_source_identity(msg),
                            int(msg.spotter_id or 0),
                            str(msg.state or "").upper(),
                            int(float(msg.utc_ts or 0.0) * 1000.0),
                            int(msg.flag_state or 0),
                            self._source_text_hash(msg.raw_text),
                        )
                        for msg in self.spotter_messages
                    )
                ),
            ),
            (
                "varac",
                tuple(
                    sorted(
                        (
                            str(msg.source or ""),
                            int(msg.msg_id or 0),
                            str(msg.guid or ""),
                            int(float(msg.ts or 0.0) * 1000.0),
                            int(msg.read_status or 0),
                            int(msg.flag_state or 0),
                            self._source_text_hash(msg.subject),
                        )
                        for msg in self.varac_messages
                    )
                ),
            ),
            (
                "sitrep",
                tuple(
                    sorted(
                        (
                            int(msg.event_id or 0),
                            str(msg.report_key or ""),
                            int(float(msg.updated_ts or msg.event_ts or 0.0) * 1000.0),
                            str(msg.overall_status or ""),
                            self._source_text_hash(msg.remarks_text),
                        )
                        for msg in self.sitrep_messages
                    )
                ),
            ),
            (
                "commstat",
                tuple(
                    sorted(
                        (
                            int(msg.artifact_id or 0),
                            str(msg.artifact_key or ""),
                            int(float(msg.updated_ts or msg.event_ts or 0.0) * 1000.0),
                            str(msg.status_label or ""),
                            self._source_text_hash(msg.title),
                        )
                        for msg in self.commstat_messages
                    )
                ),
            ),
            (
                "observations",
                tuple(
                    sorted(
                        (
                            str(obs.observation_id or ""),
                            str(obs.source_family or ""),
                            str(obs.source_ref or ""),
                            str(obs.status or ""),
                            str(obs.received_utc or obs.event_utc or ""),
                            self._source_text_hash(obs.summary),
                        )
                        for obs in getattr(self, "observation_messages", [])
                    )
                ),
            ),
        )

    def _on_visible_message_check_timer(self) -> None:
        if getattr(self, "_is_shutting_down", False):
            return
        if (
            bool(getattr(self, "_visible_message_check_inflight", False))
            or bool(getattr(self, "_refresh_files_inflight", False))
            or self._qt_thread_running(getattr(self, "_file_scan_thread", None))
            or self._qt_thread_running(getattr(self, "_rows_build_thread", None))
            or self._qt_thread_running(getattr(self, "_signature_verify_thread", None))
        ):
            self._message_check_status_text = "Still checking..."
            self._update_message_check_status()
            return
        self._visible_message_check_inflight = True
        self._emit_message_refresh_busy()
        before_count = self._message_source_count()
        before_fp = self._message_sources_fingerprint()
        self._message_check_status_text = "Checking..."
        self._update_message_check_status()
        try:
            projection_primary = bool(getattr(self, "_projection_primary_enabled", False))
            if projection_primary:
                # The activation refresh below starts source/file projection.
                # Completion callbacks reload only when a projector reports a
                # change, avoiding multiple 20k-row reads per timer tick.
                self._message_check_status_text = "Checking sources..."
            else:
                self._refresh_js8_messages(force=False, rebuild=False)
                self._refresh_varac_messages(force=False, rebuild=False)
                self._load_message_sources_from_local(force=False)
                after_fp = self._message_sources_fingerprint()
                if after_fp != before_fp:
                    self._populate_messages_table(force=False)
            self._refresh_pending_backlog()
            if not projection_primary:
                after_count = self._message_source_count()
                delta = max(0, int(after_count - before_count))
                self._message_check_status_text = (
                    f"{delta} new message{'s' if delta != 1 else ''}"
                    if delta
                    else "No new messages"
                )
            now = time.time()
            self._last_visible_message_check_ts = now
            self._last_activation_refresh_ts = now
        except Exception as e:
            log.debug("MessageViewer: visible message check failed: %s", e)
            self._message_check_status_text = "Check failed"
        finally:
            self._visible_message_check_inflight = False
            self._emit_message_refresh_busy()
            if self._has_active_view and self._messages_mode == "Inbox" and self._visible_check_interval_sec:
                self._next_visible_message_check_ts = time.time() + max(15, int(self._visible_check_interval_sec or 30))
            self._update_message_check_status()

    def _update_message_check_status(self) -> None:
        label = getattr(self, "message_check_status_label", None)
        if label is None:
            return
        if self._messages_mode != "Inbox":
            label.setText("")
            return
        if int(self._visible_check_interval_sec or 0) <= 0:
            label.setText("Auto-check off")
            label.setToolTip("Automatic checks are off. Use Refresh Now when you want CommsPlan to check immediately.")
            return
        if self._visible_message_check_inflight or self._message_check_status_text == "Checking...":
            label.setText("Checking...")
            label.setToolTip("CommsPlan is checking for new messages now.")
            return
        now = time.time()
        remaining = int(max(0.0, float(self._next_visible_message_check_ts or 0.0) - now))
        display_remaining = int(math.ceil(max(0, remaining) / 5.0) * 5) if remaining else 0
        if not self._has_active_view:
            label.setText("Checks pause when closed")
            label.setToolTip("CommsPlan checks faster only while the Messages tab is open.")
            return
        if self._message_check_status_text and self._last_visible_message_check_ts and remaining > 3:
            label.setText(f"{self._message_check_status_text} | Next: {display_remaining}s")
        else:
            label.setText(f"Next check: {display_remaining}s")
        if self._last_visible_message_check_ts:
            checked = datetime.datetime.fromtimestamp(self._last_visible_message_check_ts).strftime("%H:%M:%S")
            label.setToolTip(f"Last checked {checked}. CommsPlan checks faster only while this tab is open.")
        else:
            label.setToolTip("CommsPlan checks faster only while this tab is open.")

    def _on_refresh_now(self) -> None:
        self._unfreeze_table()
        if self._message_scan_or_build_active():
            self._refresh_files_pending = True
            self._refresh_files_pending_force = True
            self._message_check_status_text = "Still checking..."
            self._update_message_check_status()
            self._schedule_loading("Finishing current check...")
            return
        self._message_check_status_text = "Checking..."
        self._update_message_check_status()
        self._set_loading(True)
        before_count = self._message_source_count()
        before_fp = self._message_sources_fingerprint()
        try:
            self._refresh_files(force=True)
            self._refresh_js8_messages(force=True, rebuild=False)
            self._refresh_varac_messages(force=True, rebuild=False)
            after_fp = self._message_sources_fingerprint()
            stale_file_metadata = self._has_stale_message_file_metadata()
            if after_fp != before_fp or stale_file_metadata or not self._message_rows:
                self._populate_messages_table(force=True)
            after_count = self._message_source_count()
            delta = max(0, int(after_count - before_count))
            self._message_check_status_text = f"{delta} new message{'s' if delta != 1 else ''}" if delta else "No new messages"
            now = time.time()
            self._last_visible_message_check_ts = now
            self._last_activation_refresh_ts = now
        finally:
            if self._has_active_view and self._messages_mode == "Inbox" and self._visible_check_interval_sec:
                self._next_visible_message_check_ts = time.time() + max(15, int(self._visible_check_interval_sec or 30))
            self._update_message_check_status()
            self._set_loading(False)

    def _on_scan_changed(self):
        val = self.scan_combo.currentData()
        if not val:
            return
        self.scan_minutes = int(val)
        self._setup_timer()
        self._save_settings()

    def _on_message_check_interval_changed(self):
        val = self.message_check_combo.currentData()
        try:
            self._visible_check_interval_sec = int(val or 0)
        except Exception:
            self._visible_check_interval_sec = 30
        self._message_check_status_text = ""
        self._sync_message_check_timer()
        self._save_settings()

    def _initial_refresh(self) -> None:
        if getattr(self, "_is_shutting_down", False):
            return
        self._set_loading(False)
        self._load_paths_lists()
        if not self._scan_cache_loaded:
            self._refresh_files()
        else:
            # Cache-first startup: keep first paint fast, then reconcile in background.
            self._last_file_refresh_ts = time.time()
            QTimer.singleShot(1500, lambda: self._refresh_files(force=False))
        if getattr(self, "_projection_primary_enabled", False):
            self._request_projected_source_ingest(force=False)
            self._request_application_projection_catchup(reason="messages_initial")
        else:
            self._refresh_js8_messages(rebuild=False)
            self._refresh_varac_messages(force=False, rebuild=False)
        if self._has_active_view:
            self._populate_messages_table(force=False)
            QTimer.singleShot(0, lambda: self._start_signature_verification(force=False))
        else:
            self._initial_populate_deferred = True
            self._deferred_refresh = True
            self._message_check_status_text = "Indexing messages..."
            log.info("MESSAGES|initial_table_populate_deferred reason=hidden_startup_index")
            # Hidden startup lazy-prewarm should not launch GPG verification; defer
            # until the Messages tab is first shown.
            self._signature_verify_deferred_until_active = True
        self._refresh_pending_backlog()
        self._last_activation_refresh_ts = time.time()

    def _set_loading(self, active: bool, text: str = "Indexing messages...") -> None:
        if bool(getattr(self, "_traffic_navigation_pending", False)):
            active = True
            text = f"Loading {self._traffic_loading_bucket.title()} traffic…"
        if not getattr(self, "loading_label", None):
            return
        if self._loading_timer and self._loading_timer.isActive():
            self._loading_timer.stop()
        self.loading_label.setText(text)
        self.loading_label.setVisible(bool(active))
        if self._loading_progress is not None:
            self._loading_progress.setVisible(bool(active))

    def _schedule_loading(self, text: str = "Indexing messages...", delay_ms: int = 350) -> None:
        if not self.loading_label:
            return
        if self._loading_timer is None:
            self._loading_timer = QTimer(self)
            self._loading_timer.setSingleShot(True)
            self._loading_timer.timeout.connect(self._show_loading_delayed)
        self._loading_text = text
        self._loading_timer.stop()
        self._loading_timer.start(max(0, int(delay_ms)))

    def _show_loading_delayed(self) -> None:
        self._set_loading(True, self._loading_text)

    def show_loading_toast(self) -> None:
        self._set_loading(True)

    def on_tab_activated(self) -> None:
        with perf_span(
            "messages.on_tab_activated",
            settings=self.settings,
            meta={"rows": len(self._message_rows)},
            min_ms=10.0,
        ):
            self._unfreeze_table()
            if self._message_rows and self._deferred_refresh:
                self._refresh_message_filters(self._message_rows)
                self._apply_message_filters_preserve_scroll()
            self._update_pending_table()
            if self._bbs_auto_archive_first_activation_pending:
                self._bbs_auto_archive_first_activation_pending = False
                self._queue_bbs_auto_archive_check("first_activation", delay_ms=1200)
            else:
                self._queue_bbs_auto_archive_check("tab_activated", delay_ms=250)
            now = time.time()
            stale = (not self._message_rows) or (
                now - float(self._last_activation_refresh_ts) >= self._activation_refresh_interval_sec
            )
            if not stale:
                self._set_loading(False)
                return
            if self._activation_refresh_pending:
                return
            self._activation_refresh_pending = True
            self._emit_message_refresh_busy()
            self._schedule_loading("Indexing messages...")
            QTimer.singleShot(0, lambda: self._run_activation_refresh(force=False))

    def _run_activation_refresh(self, force: bool = False) -> None:
        if getattr(self, "_is_shutting_down", False):
            self._activation_refresh_pending = False
            return
        if self._message_scan_or_build_active():
            self._activation_refresh_pending = False
            self._last_activation_refresh_ts = time.time()
            self._set_loading(False)
            self._emit_message_refresh_busy()
            return
        with perf_span(
            "messages.activation_refresh",
            settings=self.settings,
            meta={"force": bool(force)},
            min_ms=5.0,
        ):
            try:
                self._load_paths_lists()
                now = time.time()
                should_refresh_files = bool(force) or (
                    now - float(self._last_file_refresh_ts) >= self._file_refresh_interval_sec
                )
                if should_refresh_files:
                    self._refresh_files(force=force)
                if getattr(self, "_projection_primary_enabled", False):
                    self._request_projected_source_ingest(force=force)
                    self._request_application_projection_catchup(reason="messages_activation")
                    if not self._message_rows:
                        self._populate_messages_table(force=force)
                else:
                    before_fp = self._message_sources_fingerprint()
                    self._refresh_js8_messages(force=force, rebuild=False)
                    self._refresh_varac_messages(force=force, rebuild=False)
                    after_fp = self._message_sources_fingerprint()
                    if after_fp != before_fp or force or not self._message_rows:
                        self._populate_messages_table(force=force)
                self._refresh_pending_backlog()
                self._last_activation_refresh_ts = time.time()
            finally:
                self._activation_refresh_pending = False
                self._set_loading(False)
                self._emit_message_refresh_busy()

    def _load_message_sources_from_local(self, *, force: bool = False) -> None:
        try:
            self._load_js8_from_local(force=force, rebuild=False)
        except Exception as e:
            log.debug("MessageViewer: JS8 local activation load failed: %s", e)
        try:
            self._load_spotter_from_db(force=force, rebuild=False)
        except Exception as e:
            log.debug("MessageViewer: spotter activation load failed: %s", e)
        try:
            self._load_sitrep_from_local(force=force, rebuild=False)
        except Exception as e:
            log.debug("MessageViewer: sitrep activation load failed: %s", e)
        try:
            self._load_commstat_from_local(force=force, rebuild=False)
        except Exception as e:
            log.debug("MessageViewer: CommStat activation load failed: %s", e)
        try:
            self._load_varac_from_local(force=force, rebuild=False)
        except Exception as e:
            log.debug("MessageViewer: VarAC activation load failed: %s", e)

    def set_tab_active(self, active: bool) -> None:
        self._has_active_view = bool(active)
        if not active:
            self._invalidate_compose_mesh_contact()
            self._cancel_compose_js8_selected_target_worker()
            self._compose_js8_selected_target_generation += 1
            self._compose_js8_selected_target_pending_context = {}
            self._compose_js8_selected_target_state = "unknown"
            self._compose_js8_selected_target_value = ""
            self._compose_js8_selected_target_action = ""
            self._refresh_compose_js8_selected_target_cue()
        if active and self._app_active:
            if self._clock_timer is None:
                self._setup_clock_timer()
            elif not self._clock_timer.isActive():
                self._clock_timer.start(1000)
            self._setup_timer()
            self._setup_js8_timer()
            self._setup_pending_timer()
            self._sync_message_check_timer()
            self._setup_projection_delete_queue_timer()
            self._setup_bbs_auto_archive_timer()
            if self._signature_verify_deferred_until_active:
                self._signature_verify_deferred_until_active = False
                QTimer.singleShot(0, lambda: self._start_signature_verification(force=False))
            if self._initial_populate_deferred:
                self._initial_populate_deferred = False
                self._deferred_refresh = False
                self._schedule_loading("Indexing messages...")
                QTimer.singleShot(0, lambda: self._populate_messages_table(force=False))
                return
            if self._deferred_refresh:
                self._schedule_loading("Indexing messages...")
                QTimer.singleShot(0, lambda: self._populate_messages_table(force=False))
                return
            return
        for timer in (
            self._clock_timer,
            self._timer,
            self._js8_timer,
            self._pending_timer,
            self._message_check_timer,
            self._projection_delete_queue_timer,
            self._bbs_auto_archive_timer,
        ):
            if timer:
                timer.stop()
        self._next_visible_message_check_ts = 0.0
        self._update_message_check_status()

    def set_app_active(self, active: bool) -> None:
        self._app_active = bool(active)
        if not self._app_active:
            self._deferred_refresh = True
            for timer in (
                self._clock_timer,
                self._timer,
                self._js8_timer,
                self._pending_timer,
                self._message_check_timer,
                self._projection_delete_queue_timer,
                self._bbs_auto_archive_timer,
            ):
                if timer:
                    timer.stop()
            log.info("MESSAGES|ui_paused reason=app_inactive")
            return
        if self._has_active_view:
            self.set_tab_active(True)

    # ---------- BBS Auto-Archive ----------

    def _bbs_auto_archive_settings_snapshot(self) -> Optional[Dict[str, object]]:
        if not MessageViewerTab._is_truthy(self.settings.get("varac_bbs_enabled", False), False):
            log.debug("MessageViewer: BBS auto-archive skipped (BBS disabled)")
            return None
        if not self._is_truthy(self.settings.get("varac_bbs_auto_archive_enabled", False), False):
            return None
        bbs_dir_txt = str(self.settings.get("varac_bbs_dir", "") or "").strip()
        archive_dir_txt = str(self.settings.get("varac_bbs_archive_dir", "") or "").strip()
        if not bbs_dir_txt or not archive_dir_txt:
            log.debug("MessageViewer: BBS auto-archive skipped (paths not configured)")
            return None
        bbs_dir = Path(bbs_dir_txt)
        archive_dir = Path(archive_dir_txt)
        if not bbs_dir.exists() or not bbs_dir.is_dir() or not archive_dir.exists() or not archive_dir.is_dir():
            log.debug("MessageViewer: BBS auto-archive skipped (invalid directories)")
            return None
        try:
            if bbs_dir.resolve() == archive_dir.resolve():
                log.debug("MessageViewer: BBS auto-archive skipped (BBS and archive dirs are the same)")
                return None
        except Exception:
            pass
        days_raw = self.settings.get("varac_bbs_auto_archive_days", 14)
        try:
            days_val = max(1, int(days_raw or 14))
        except Exception:
            days_val = 14
        allowed = sorted(set(ORIGIN_EXTS.get("bbs", set(SUPPORTED_EXT))))
        archive_jobs: List[Dict[str, object]] = [
            {
                "bbs_dir": str(bbs_dir),
                "days": int(days_val),
                "archive_context": "live",
            }
        ]
        if self._is_truthy(self.settings.get("varac_bbs_vault_enabled", False), False):
            for location in load_vault_locations(self.settings.get("varac_bbs_vault_locations_v1", [])):
                if not location.enabled:
                    continue
                if location.retention_policy != "Archive this location by age":
                    continue
                source_txt = str(location.source_dir or "").strip()
                if not source_txt:
                    continue
                source_path = Path(source_txt)
                if not source_path.exists() or not source_path.is_dir():
                    continue
                try:
                    if source_path.resolve() == archive_dir.resolve():
                        continue
                except Exception:
                    pass
                context_id = re.sub(r"[^A-Za-z0-9_.-]+", "-", str(location.id or location.name or "location")).strip("-")
                archive_jobs.append(
                    {
                        "bbs_dir": str(source_path),
                        "days": max(1, int(location.retention_days or days_val)),
                        "archive_context": f"managed/{context_id or 'location'}",
                    }
                )
        return {
            "bbs_dir": str(bbs_dir),
            "archive_dir": str(archive_dir),
            "days": int(days_val),
            "allowed_exts": allowed,
            "archive_jobs": archive_jobs,
        }

    def _bbs_auto_archive_last_check_ts(self) -> float:
        raw = self.settings.get(BBS_AUTO_ARCHIVE_LAST_CHECK_KEY, 0.0)
        try:
            return float(raw or 0.0)
        except Exception:
            return 0.0

    def _bbs_auto_archive_due_now(self, now_ts: Optional[float] = None) -> bool:
        now_val = float(now_ts if now_ts is not None else time.time())
        last_ts = self._bbs_auto_archive_last_check_ts()
        if last_ts <= 0:
            return True
        return (now_val - last_ts) >= float(self._bbs_auto_archive_interval_sec)

    def _set_bbs_auto_archive_last_check_ts(self, ts: float) -> None:
        try:
            self.settings.set(BBS_AUTO_ARCHIVE_LAST_CHECK_KEY, float(ts))
        except Exception as e:
            log.debug("MessageViewer: failed to persist BBS auto-archive check ts: %s", e)

    def _queue_bbs_auto_archive_check(self, reason: str, delay_ms: int = 0) -> None:
        if self._is_shutting_down:
            return
        if self._bbs_auto_archive_check_pending or self._bbs_auto_archive_inflight:
            return
        self._bbs_auto_archive_check_pending = True

        def _run() -> None:
            self._bbs_auto_archive_check_pending = False
            self._run_bbs_auto_archive_if_due(reason=reason)

        QTimer.singleShot(max(0, int(delay_ms)), _run)

    def _run_bbs_auto_archive_if_due(self, *, reason: str) -> None:
        if self._is_shutting_down or self._bbs_auto_archive_inflight:
            return
        if not self._has_active_view:
            return
        if self._bbs_auto_archive_thread:
            try:
                if self._bbs_auto_archive_thread.isRunning():
                    return
            except RuntimeError:
                self._bbs_auto_archive_thread = None
                self._bbs_auto_archive_worker = None
        snapshot = self._bbs_auto_archive_settings_snapshot()
        if not snapshot:
            return
        if not self._bbs_auto_archive_due_now():
            return
        if self._refresh_files_inflight:
            self._queue_bbs_auto_archive_check(reason, delay_ms=3000)
            return
        self._bbs_auto_archive_inflight = True
        self._bbs_auto_archive_thread = QThread(self)
        self._bbs_auto_archive_worker = _BbsAutoArchiveWorker(
            bbs_dir=str(snapshot.get("bbs_dir", "") or ""),
            archive_dir=str(snapshot.get("archive_dir", "") or ""),
            days=int(snapshot.get("days", 14) or 14),
            allowed_exts=[str(v) for v in (snapshot.get("allowed_exts", []) or [])],
            reason=str(reason or "timer"),
            archive_context="live",
            archive_jobs=[dict(v) for v in (snapshot.get("archive_jobs", []) or []) if isinstance(v, dict)],
        )
        self._bbs_auto_archive_worker.moveToThread(self._bbs_auto_archive_thread)
        self._bbs_auto_archive_thread.started.connect(self._bbs_auto_archive_worker.run)
        self._bbs_auto_archive_worker.finished.connect(self._on_bbs_auto_archive_finished)
        self._bbs_auto_archive_worker.finished.connect(self._bbs_auto_archive_thread.quit)
        self._bbs_auto_archive_worker.finished.connect(self._bbs_auto_archive_worker.deleteLater)
        self._bbs_auto_archive_thread.finished.connect(self._on_bbs_auto_archive_thread_finished)
        self._bbs_auto_archive_thread.finished.connect(self._bbs_auto_archive_thread.deleteLater)
        self._bbs_auto_archive_thread.start()

    def _on_bbs_auto_archive_thread_finished(self) -> None:
        self._retain_finished_worker_refs(self._bbs_auto_archive_thread, self._bbs_auto_archive_worker)
        self._bbs_auto_archive_thread = None
        self._bbs_auto_archive_worker = None

    def _on_bbs_auto_archive_finished(self, payload: object) -> None:
        self._bbs_auto_archive_inflight = False
        if self._is_shutting_down:
            return
        data = payload if isinstance(payload, dict) else {}
        try:
            completed_ts = float(data.get("completed_ts", time.time()) or time.time())
        except Exception:
            completed_ts = time.time()
        self._set_bbs_auto_archive_last_check_ts(completed_ts)
        reason = str(data.get("reason", "") or "timer")
        moved_count = int(data.get("moved_count", 0) or 0)
        error_count = int(data.get("error_count", 0) or 0)
        scanned_count = int(data.get("scanned_count", 0) or 0)
        eligible_count = int(data.get("eligible_count", 0) or 0)
        fatal_error = str(data.get("fatal_error", "") or "").strip()
        if fatal_error:
            log.warning("MessageViewer: BBS auto-archive failed (%s): %s", reason, fatal_error)
            return
        if moved_count or error_count:
            log.info(
                "MessageViewer: BBS auto-archive check (%s) scanned=%s eligible=%s moved=%s errors=%s",
                reason,
                scanned_count,
                eligible_count,
                moved_count,
                error_count,
            )
        else:
            log.debug(
                "MessageViewer: BBS auto-archive check (%s) scanned=%s eligible=%s moved=0",
                reason,
                scanned_count,
                eligible_count,
            )
        if moved_count > 0:
            if self._refresh_files_inflight:
                QTimer.singleShot(1200, lambda: self._refresh_files(force=False))
            else:
                self._refresh_files(force=False)


    # ---------- Paths ----------

    def _load_paths_lists(self):
        by_origin: Dict[str, List[str]] = {"varac": [], "flmsg": [], "flamp": [], "bbs": []}
        for entry in self.watch_dirs:
            origin = entry.get("origin", "unknown")
            path = entry.get("path", "")
            if origin in by_origin and path:
                by_origin[origin].append(path)
        for origin, lbl in self.paths_labels.items():
            paths_raw = "; ".join(by_origin.get(origin, [])) if by_origin.get(origin) else "(none)"
            paths_txt = paths_raw if len(paths_raw) <= 50 else paths_raw[:50] + "..."
            lbl.setText(f"Paths: {paths_txt}")

    def _add_path(self, origin: str):
        fn = QFileDialog.getExistingDirectory(self, f"Add {origin.upper()} watch folder")
        if not fn:
            return
        self.watch_dirs.append({"path": fn, "origin": origin})
        self._scan_cache_loaded = False
        self._scan_cache_saved_ts = 0.0
        self._scan_dir_mtime_cache = {}
        self._files_snapshot_fp = None
        self._save_settings()
        self._sync_file_system_watcher()
        self._refresh_files()

    def _remove_path(self, origin: str):
        # remove last added path for this origin (or prompt later)
        paths = [w for w in self.watch_dirs if w.get("origin") == origin]
        if not paths:
            return
        last = paths[-1]
        self.watch_dirs = [w for w in self.watch_dirs if not (w.get("origin") == origin and w.get("path") == last.get("path"))]
        self._scan_cache_loaded = False
        self._scan_cache_saved_ts = 0.0
        self._scan_dir_mtime_cache = {}
        self._files_snapshot_fp = None
        self._save_settings()
        self._sync_file_system_watcher()
        self._refresh_files()

    # ---------- Scanning ----------

    def _effective_watch_dirs(self, *, include_source_metadata: bool = False) -> List[Dict]:
        out: List[Dict] = []
        seen: set[tuple[str, str]] = set()
        for entry in self.watch_dirs:
            origin = str(entry.get("origin", "") or "").strip().lower()
            path = str(entry.get("path", "") or "").strip()
            if not origin or not path:
                continue
            key = (origin, path)
            if key in seen:
                continue
            row = {"origin": origin, "path": path}
            if include_source_metadata:
                row.update(
                    {
                        "source_id": str(entry.get("source_id", "") or ""),
                        "source_label": str(entry.get("source_label", "") or ""),
                    }
                )
            out.append(row)
            seen.add(key)
        for entry in self._multi_radio_message_path_entries():
            origin = str(entry.get("origin", "") or "").strip().lower()
            path = str(entry.get("path", "") or "").strip()
            if not origin or not path:
                continue
            key = (origin, path)
            if key in seen:
                continue
            row = {"origin": origin, "path": path}
            if include_source_metadata:
                row.update(
                    {
                        "source_id": str(entry.get("source_id", "") or ""),
                        "source_label": str(entry.get("source_label", "") or ""),
                    }
                )
            out.append(row)
            seen.add(key)
        for root in bbs_file_management_roots(self.settings):
            kind = str(root.get("kind", "") or "").strip().lower()
            path = str(root.get("path", "") or "").strip()
            if not path:
                continue
            origin = "varac" if kind in {"incoming", "outgoing"} else "bbs"
            key = (origin, path)
            if key in seen:
                continue
            row = {"origin": origin, "path": path}
            if include_source_metadata:
                source_label = str(root.get("label", "") or "").strip() or "BBS"
                source_key = f"bbs-{kind or 'file'}"
                row.update(
                    {
                        "source_id": stable_source_id(source_key, path, prefix="ingest"),
                        "source_label": source_label,
                    }
                )
            out.append(row)
            seen.add(key)
        return out

    @staticmethod
    def _norm_scan_path(path: str | Path) -> str:
        return os.path.normcase(os.path.normpath(str(path)))

    @staticmethod
    def _path_stat_fingerprint(path: str | Path | None) -> Tuple[str, int, int]:
        if not path:
            return ("", 0, 0)
        try:
            path_obj = Path(path)
            stat = path_obj.stat()
            return (
                os.path.normcase(os.path.normpath(str(path_obj))),
                int(getattr(stat, "st_mtime_ns", int(stat.st_mtime * 1_000_000_000))),
                int(stat.st_size),
            )
        except Exception:
            return (os.path.normcase(os.path.normpath(str(path))), 0, 0)

    def _js8_display_fingerprint(self) -> Tuple[Tuple[str, int, int], ...]:
        return tuple(
            sorted(
                {
                    self._path_stat_fingerprint(self._db_path()),
                    self._path_stat_fingerprint(self._local_js8_db()),
                }
            )
        )

    def _bbs_archive_roots(self) -> set[str]:
        archive_dir = (self.settings.get("varac_bbs_archive_dir", "") or "").strip()
        if not archive_dir:
            return set()
        try:
            archive_path = Path(archive_dir)
            if not archive_path.exists() or not archive_path.is_dir():
                return set()
        except Exception:
            return set()
        return {self._norm_scan_path(archive_dir)}

    def _is_bbs_archive_record(
        self,
        rec: FileRecord,
        *,
        archive_roots: Optional[set[str]] = None,
    ) -> bool:
        if not rec or (rec.origin or "").strip().lower() != "bbs":
            return False
        roots = archive_roots if archive_roots is not None else self._bbs_archive_roots()
        if not roots:
            return False
        path_norm = self._norm_scan_path(rec.path)
        for root_norm in roots:
            if path_norm == root_norm or path_norm.startswith(root_norm + os.sep):
                return True
        return False

    def _bbs_file_management_context_for_record(self, rec: FileRecord | None) -> Dict[str, str]:
        if not isinstance(rec, FileRecord):
            return {}
        path_norm = self._norm_scan_path(rec.path)
        best: Dict[str, str] = {}
        best_len = -1
        for root in bbs_file_management_roots(self.settings):
            root_path = str(root.get("path", "") or "").strip()
            if not root_path:
                continue
            root_norm = self._norm_scan_path(root_path)
            if not (path_norm == root_norm or path_norm.startswith(root_norm + os.sep)):
                continue
            if len(root_norm) <= best_len:
                continue
            best = {
                "kind": str(root.get("kind", "") or ""),
                "label": str(root.get("label", "") or ""),
                "path": root_path,
                "archive_context": str(root.get("archive_context", "") or "live"),
            }
            best_len = len(root_norm)
        return best

    def _is_bbs_manageable_file_record(self, rec: FileRecord | None) -> bool:
        context = self._bbs_file_management_context_for_record(rec)
        if not context:
            return False
        return str(context.get("kind", "") or "").strip().lower() != "archive"

    def _is_bbs_manageable_file_row(self, row: UnifiedMessage | None) -> bool:
        payload = getattr(row, "payload", None) if row is not None else None
        if isinstance(payload, ProjectedMessagePayload):
            payload = self._projected_file_record(payload, allow_detail_lookup=False)
        return isinstance(payload, FileRecord) and self._is_bbs_manageable_file_record(payload)

    def _retag_bbs_archive_rows(self, rows: List[UnifiedMessage]) -> None:
        archive_roots = self._bbs_archive_roots()
        if not rows:
            return
        for row in rows:
            payload = row.payload
            if not isinstance(payload, FileRecord):
                continue
            if not self._is_bbs_archive_record(payload, archive_roots=archive_roots):
                continue
            row.origin = "bbs_archive"
            base_title = str(row.title or payload.path.name or "").strip() or payload.path.name
            if not base_title.startswith("[Archived] "):
                row.title = f"[Archived] {base_title}"
            row.search_text = " ".join(
                [
                    str(row.msg_type or ""),
                    str(row.status or ""),
                    str(row.from_call or ""),
                    str(row.to_call or ""),
                    str(row.rcv_display or ""),
                    str(row.title or ""),
                    "archived",
                    "archive",
                ]
            ).lower()

    def _file_origin_label(self, rec: FileRecord) -> str:
        if self._is_bbs_archive_record(rec):
            return "BBS ARCHIVE"
        bbs_context = self._bbs_file_management_context_for_record(rec)
        if bbs_context:
            label = str(bbs_context.get("label", "") or "").strip()
            if label:
                return label.upper()
        return str(rec.origin or "").strip().upper()

    def _bbs_file_area_display_rows(self, rec: FileRecord) -> Tuple[Tuple[str, str], ...]:
        bbs_context = self._bbs_file_management_context_for_record(rec)
        if not bbs_context:
            return ()
        kind = str(bbs_context.get("kind", "") or "").strip().lower()
        label = str(bbs_context.get("label", "") or "").strip() or self._file_origin_label(rec)
        folder = str(bbs_context.get("path", "") or "").strip()
        if kind == "archive":
            role = "Archived BBS file"
        elif kind == "incoming":
            role = "VarAC incoming file"
        elif kind == "outgoing":
            role = "VarAC outgoing file"
        elif kind == "managed_location":
            role = "Managed BBS Library location"
        else:
            role = "Live VarAC BBS file"
        rows: List[Tuple[str, str]] = [("BBS File Area", label), ("Role", role)]
        if folder:
            rows.append(("Folder", folder))
        return tuple(rows)

    def _bbs_file_area_text(self, rec: FileRecord) -> str:
        rows = self._bbs_file_area_display_rows(rec)
        if not rows:
            return ""
        lines = ["BBS File Area"]
        lines.extend(f"{label}: {value}" for label, value in rows)
        return "\n".join(lines)

    def _bbs_file_area_html(self, rec: FileRecord) -> str:
        rows = self._bbs_file_area_display_rows(rec)
        if not rows:
            return ""
        out = [
            "<div style='font-family: sans-serif; margin: 0 0 10px 0; padding: 8px; "
            "border: 1px solid; background: inherit;'>",
            "<div><b>BBS File Area</b></div>",
        ]
        for label, value in rows:
            out.append(
                f"<div><b>{html.escape(label)}:</b> {html.escape(str(value or ''))}</div>"
            )
        out.append("</div>")
        return "".join(out)

    def _refresh_files(self, force: bool = False):
        if self._is_shutting_down:
            return
        if self._refresh_files_inflight or self._bbs_auto_archive_inflight:
            self._refresh_files_pending = True
            self._refresh_files_pending_force = bool(self._refresh_files_pending_force or force)
            return
        if self._file_scan_thread:
            try:
                if self._file_scan_thread.isRunning():
                    self._refresh_files_pending = True
                    self._refresh_files_pending_force = bool(self._refresh_files_pending_force or force)
                    return
            except RuntimeError:
                self._file_scan_thread = None
                self._file_scan_worker = None
        self._refresh_files_inflight = True
        self._emit_message_refresh_busy()
        self._file_scan_start_ts = time.time()
        self._load_paths_lists()
        base_records = None if force else self.files
        base_dir_mtimes = None if force else self._scan_dir_mtime_cache
        scan_watch_dirs = self._effective_watch_dirs(include_source_metadata=True)
        watch_signature = self._watch_dirs_signature(scan_watch_dirs)
        db_path = self._db_path()
        self._file_scan_thread = QThread(self)
        self._file_scan_worker = _FileScanWorker(
            scan_watch_dirs,
            force,
            base_records=base_records,
            base_dir_mtimes=base_dir_mtimes,
            db_path=str(db_path) if db_path else "",
            watch_signature=watch_signature,
            bbs_db_path=str(bbs_library_db_path_from_settings(self.settings)),
            legacy_bbs_rules=self.settings.get("varac_bbs_sweeper_rules_v1", []),
            legacy_bbs_locations=self.settings.get("varac_bbs_vault_locations_v1", []),
            legacy_bbs_enabled=self._is_truthy(
                self.settings.get("varac_bbs_vault_enabled", False), False
            ),
        )
        self._file_scan_worker.moveToThread(self._file_scan_thread)
        self._file_scan_thread.started.connect(self._file_scan_worker.run)
        self._file_scan_worker.finished.connect(self._on_file_scan_finished)
        self._file_scan_worker.finished.connect(self._file_scan_thread.quit)
        self._file_scan_worker.finished.connect(self._file_scan_worker.deleteLater)
        self._file_scan_thread.finished.connect(self._on_file_scan_thread_finished)
        self._file_scan_thread.finished.connect(self._file_scan_thread.deleteLater)
        self._file_scan_thread.start()

    def _on_file_scan_thread_finished(self) -> None:
        self._retain_finished_worker_refs(self._file_scan_thread, self._file_scan_worker)
        self._file_scan_thread = None
        self._file_scan_worker = None
        self._emit_message_refresh_busy()
        if self._refresh_files_pending and not self._is_shutting_down:
            pending_force = bool(self._refresh_files_pending_force)
            self._refresh_files_pending = False
            self._refresh_files_pending_force = False
            QTimer.singleShot(1200, lambda force=pending_force: self._refresh_files(force=force))

    def _on_file_scan_finished(self, payload: object, force: bool) -> None:
        if self._is_shutting_down:
            self._refresh_files_inflight = False
            return
        records: Dict[str, List[FileRecord]]
        dir_mtimes: Dict[str, float] = {}
        mode = "legacy"
        projection: Dict[str, object] = {}
        automation: Dict[str, object] = {}
        if isinstance(payload, dict) and "records" in payload:
            maybe_records = payload.get("records")
            if isinstance(maybe_records, dict):
                records = maybe_records
            else:
                records = {"varac": [], "flmsg": [], "flamp": [], "bbs": []}
            maybe_dirs = payload.get("dir_mtimes")
            if isinstance(maybe_dirs, dict):
                for k, v in maybe_dirs.items():
                    try:
                        dir_mtimes[os.path.normcase(os.path.normpath(str(k)))] = float(v or 0.0)
                    except Exception:
                        continue
            mode = str(payload.get("mode", "unknown") or "unknown")
            maybe_projection = payload.get("projection")
            if isinstance(maybe_projection, dict):
                projection = maybe_projection
            maybe_automation = payload.get("automation")
            if isinstance(maybe_automation, dict):
                automation = maybe_automation
        elif isinstance(payload, dict):
            records = payload  # type: ignore[assignment]
        else:
            records = {"varac": [], "flmsg": [], "flamp": [], "bbs": []}
        total_records = sum(len(v) for v in records.values())
        changed_count = int(projection.get("added_or_changed", 0) or 0)
        removed_count = int(projection.get("removed", 0) or 0)
        unchanged_records = not force and changed_count == 0 and removed_count == 0
        try:
            with perf_span(
                "messages.file_scan_finished_handler",
                settings=self.settings,
                meta={
                    "force": bool(force),
                    "records": total_records,
                    "mode": mode,
                    "unchanged": bool(unchanged_records),
                },
                min_ms=5.0,
            ):
                # MIP-3 boundary: scanning, parsing, cache persistence, and
                # normalized projection have already completed on the worker.
                # The Qt callback only swaps immutable snapshot state and marks
                # the read model stale for the next coalesced refresh.
                self.files = records
                self._scan_dir_mtime_cache = dir_mtimes
                self._scan_cache_loaded = True
                self._files_snapshot_fp = None
                projection_state = str(projection.get("state", "") or "")
                projection_error = str(projection.get("error", "") or "")
                if projection_error:
                    log.warning("MessageViewer: file projection pipeline failed: %s", projection_error)
                    self._message_check_status_text = "Message file update deferred"
                elif changed_count or removed_count or force:
                    self._message_check_status_text = "Messages updated"
                    self._deferred_refresh = True
                elif projection_state in {"unchanged", "cached"}:
                    self._message_check_status_text = "No new messages"
                self._update_message_check_status()
                automation_error = str(automation.get("error", "") or "")
                automation_copied = int(automation.get("copied", 0) or 0)
                if automation_error:
                    log.warning("MessageViewer: BBS automation failed: %s", automation_error)
                elif automation_copied:
                    log.info(
                        "MessageViewer: BBS automation copied=%s skipped=%s planned=%s",
                        automation_copied,
                        int(automation.get("skipped", 0) or 0),
                        int(automation.get("planned", 0) or 0),
                    )
        finally:
            self._refresh_files_inflight = False
            self._last_file_refresh_ts = time.time()
            self._emit_message_refresh_busy()
            elapsed = time.time() - self._file_scan_start_ts
            emit_span(
                "messages.file_scan_total",
                elapsed * 1000.0,
                settings=self.settings,
                meta={
                    "force": bool(force),
                    "records": total_records,
                    "mode": mode,
                    "unchanged": bool(unchanged_records),
                },
                min_ms=5.0,
            )
            if not unchanged_records or elapsed >= 0.25:
                emit_span(
                    "messages.file_discovery",
                    elapsed * 1000.0,
                    settings=self.settings,
                    meta={
                        "changed": not bool(unchanged_records),
                        "records": total_records,
                        "mode": mode,
                    },
                    level="warning" if elapsed >= 0.5 else "debug",
                )
            if elapsed > 0.5:
                log.debug("MessageViewer: refresh_files took %.2fs", elapsed)

    def _project_message_files_to_observations(self, records: Dict[str, List[FileRecord]]) -> None:
        db_path = self._db_path()
        if not db_path:
            return
        try:
            limit = int(self.settings.get("observation_file_projection_batch_limit", 100) or 100)
        except Exception:
            limit = 100
        try:
            projected = project_message_file_observations(
                db_path,
                records,
                origins=("flmsg", "flamp"),
                condition_alert_rules=self.settings.get(CONDITION_ALERT_RULES_SETTING_KEY, None),
                batch_limit=max(1, min(250, limit)),
            )
            if projected:
                log.debug("MessageViewer: projected %s message file observations", projected)
        except Exception as exc:
            log.debug("MessageViewer: message file observation projection failed: %s", exc)

    def _project_commstat_alerts_to_observations(self) -> None:
        db_path = self._db_path()
        if not db_path:
            return
        rules = self.settings.get(CONDITION_ALERT_RULES_SETTING_KEY, None)
        if not rules:
            return
        try:
            backfill_observations(
                db_path,
                include_local_reports=False,
                include_spotter_traffic=False,
                include_commstat_artifacts=True,
                condition_alert_rules=rules,
                batch_limit=100,
            )
        except Exception as exc:
            log.debug("MessageViewer: CommStat condition alert projection failed: %s", exc)

    def _refresh_js8_messages(self, force: bool = False, rebuild: bool = True):
        if self._is_shutting_down:
            return
        with perf_span(
            "messages.refresh_js8_messages",
            settings=self.settings,
            meta={"force": bool(force), "rebuild": bool(rebuild)},
            min_ms=5.0,
        ):
            now = time.time()
            should_ingest = bool(force) or (
                now - float(self._last_js8_ingest_ts) >= self._js8_ingest_interval_sec
            )
            display_fp_before = self._js8_display_fingerprint()
            self._load_structured_message_projections(force=force, rebuild=False)
            loaded_fp = self._js8_display_fingerprint()
            background_requested = False
            if should_ingest:
                background_requested = self._request_background_ingest("message_cache", force=force)
                if not background_requested:
                    if force:
                        try:
                            self._ingest_js8_runtime_messages()
                        except Exception as e:
                            log.debug("MessageViewer: JS8 runtime message ingest failed: %s", e)
                    else:
                        log.debug("MessageViewer: JS8 runtime ingest deferred; background ingest unavailable")
                self._last_js8_ingest_ts = now
                if force and not background_requested:
                    self._load_structured_message_projections(force=True, rebuild=False)
            display_fp_after = self._js8_display_fingerprint()
            if not force and self._js8_display_snapshot_fp == display_fp_after and loaded_fp == display_fp_before:
                return
            self._js8_display_snapshot_fp = display_fp_after
            if rebuild and (force or display_fp_after != display_fp_before or not getattr(self, "_message_rows", [])):
                self._populate_messages_table(force=force)

    def _load_structured_message_projections(self, force: bool = False, rebuild: bool = False) -> None:
        if getattr(self, "_projection_primary_enabled", False):
            self._request_application_projection_catchup(reason="messages_structured_refresh")
            if rebuild:
                self._request_projected_message_query(force=force, delay_ms=0)
            return
        try:
            self._load_js8_from_local(force=force, rebuild=False)
        except Exception as e:
            log.debug("MessageViewer: JS8 local load failed: %s", e)
        try:
            self._load_spotter_from_db(force=force, rebuild=False)
        except Exception as e:
            log.debug("MessageViewer: spotter load failed: %s", e)
        try:
            self._load_sitrep_from_local(force=force, rebuild=False)
        except Exception as e:
            log.debug("MessageViewer: sitrep load failed: %s", e)
        try:
            self._load_commstat_from_local(force=force, rebuild=False)
        except Exception as e:
            log.debug("MessageViewer: CommStat local load failed: %s", e)
        try:
            self._load_mesh_observations_from_store()
        except Exception as e:
            log.debug("MessageViewer: mesh observation load failed: %s", e)
        self._request_application_projection_catchup(reason="messages_source_refresh")
        if rebuild:
            self._populate_messages_table(force=force)

    def _load_mesh_observations_from_store(self, *, limit: int = 300) -> None:
        db_path = default_mesh_db_path()
        rows: list[Observation] = []
        for source_family in ("meshcore", "meshtastic"):
            try:
                rows.extend(list_observations(db_path, source_family=source_family, limit=limit))
            except Exception as exc:
                log.debug("MessageViewer: failed to load %s observations: %s", source_family, exc)
        visible: list[Observation] = []
        for row in rows:
            if not _core_mesh_row_is_inbox_message(row):
                continue
            provenance = row.provenance if isinstance(row.provenance, Mapping) else {}
            surfaces = provenance.get("surfaces", ()) if isinstance(provenance, Mapping) else ()
            if surfaces and "inbox" not in {str(surface or "").strip().lower() for surface in surfaces}:
                continue
            visible.append(row)
        self.observation_messages = sorted(
            visible,
            key=lambda obs: str(obs.received_utc or obs.event_utc or ""),
            reverse=True,
        )[: max(1, int(limit or 300))]

    def _refresh_sitrep_messages(self, force: bool = False, rebuild: bool = True) -> None:
        if self._is_shutting_down:
            return
        before_fp = self._message_sources_fingerprint()
        try:
            self._load_sitrep_from_local(force=force, rebuild=False)
        except Exception as e:
            log.debug("MessageViewer: sitrep refresh failed: %s", e)
        try:
            self._load_commstat_from_local(force=force, rebuild=False)
        except Exception as e:
            log.debug("MessageViewer: CommStat refresh failed: %s", e)
        try:
            self._load_mesh_observations_from_store()
        except Exception as e:
            log.debug("MessageViewer: mesh observation refresh failed: %s", e)
        after_fp = self._message_sources_fingerprint()
        if rebuild and (force or after_fp != before_fp or not getattr(self, "_message_rows", [])):
            self._populate_messages_table(force=force)

    def _update_fldigi_senders(self, records: Dict[str, List[FileRecord]]) -> None:
        db_path = self._db_path()
        if not db_path or not db_path.exists():
            return
        def _base_callsign(val: str) -> str:
            cs_norm = (val or "").strip().upper()
            if not cs_norm:
                return ""
            cs_norm = re.sub(r"/(P|M|MM|QRP|SOTA|ROVER|[A-Z0-9]{1,4})$", "", cs_norm)
            match = re.search(r"\b[A-Z]{1,2}\d[A-Z0-9]{1,4}\b", cs_norm)
            if match:
                return match.group(0)
            return cs_norm
        rows: Dict[str, tuple[float, str]] = {}
        for origin in ("flmsg", "flamp"):
            for rec in records.get(origin, []):
                sender = self._extract_sender_from_file(rec)
                if not sender:
                    continue
                sender = _base_callsign(sender)
                if not sender:
                    continue
                ts_val = float(rec.mtime or 0.0)
                existing = rows.get(sender)
                if not existing or ts_val > existing[0]:
                    rows[sender] = (ts_val, origin)
        if not rows:
            return
        try:
            conn = sqlite3.connect(db_path)
            cur = conn.cursor()
            for cs, (ts_val, origin) in rows.items():
                cur.execute(
                    """
                    INSERT INTO fldigi_file_senders (callsign, last_seen_ts, origin)
                    VALUES (?, ?, ?)
                    ON CONFLICT(callsign) DO UPDATE SET
                        last_seen_ts=excluded.last_seen_ts,
                        origin=excluded.origin
                    """,
                    (cs, float(ts_val), origin),
                )
            conn.commit()
            conn.close()
        except Exception as e:
            log.debug("MessageViewer: failed to update fldigi senders: %s", e)

    def _refresh_varac_messages(self, force: bool = False, rebuild: bool = True) -> None:
        if self._is_shutting_down:
            return
        before_fp = self._message_sources_fingerprint()
        now = time.time()
        should_ingest = bool(force) or (
            now - float(self._last_varac_ingest_ts) >= self._varac_ingest_interval_sec
        )
        background_requested = False
        if should_ingest:
            background_requested = self._request_background_ingest("varac", force=force)
            if not background_requested:
                if force:
                    try:
                        result = ingest_varac_for_runtime_sources(self.settings)
                        if result.used_runtime_sources:
                            log.debug(
                                "MessageViewer: VarAC runtime ingest refreshed %s/%s source(s)",
                                result.sources_succeeded,
                                result.sources_attempted,
                            )
                    except Exception as e:
                        log.debug("MessageViewer: VarAC ingest failed: %s", e)
                else:
                    log.debug("MessageViewer: VarAC runtime ingest deferred; background ingest unavailable")
            self._last_varac_ingest_ts = now
        try:
            self._load_varac_from_local(force=force, rebuild=False)
        except Exception as e:
            log.debug("MessageViewer: VarAC load failed: %s", e)
        after_fp = self._message_sources_fingerprint()
        if rebuild and (force or background_requested or after_fp != before_fp or not getattr(self, "_message_rows", [])):
            self._populate_messages_table(force=force)

    def _cycle_flag_state(self, payload: object) -> None:
        current = int(getattr(payload, "flag_state", 0) or 0)
        next_state = 1 if current == 0 else (2 if current == 1 else 0)
        try:
            setattr(payload, "flag_state", next_state)
        except Exception:
            pass
        if isinstance(payload, JS8Message):
            self._set_js8_flag(payload.msg_id, next_state)
        elif isinstance(payload, SpotterMessage):
            self._set_spotter_flag(payload.spotter_id, next_state)
        elif isinstance(payload, VarACMessage):
            self._set_varac_flag(payload, next_state)
        elif isinstance(payload, FileRecord):
            self._set_file_flag(payload, next_state)
        self._populate_messages_table(force=True)

    def _cycle_row_flag_state(self, row: UnifiedMessage | None) -> None:
        """Toggle a row flag while preserving native and projection state."""

        if row is None:
            return
        payload = getattr(row, "payload", None)
        if not isinstance(payload, ProjectedMessagePayload):
            self._cycle_flag_state(payload)
            return
        next_state = 0 if int(payload.flag_state or 0) else 1
        db_path = self._db_path()
        if db_path is None or not payload.message_id:
            return
        try:
            if not set_projected_message_attention(db_path, payload.message_id, bool(next_state)):
                return
            payload.flag_state = next_state
            row.actionable = bool(next_state)
            rec = self._projected_file_record(payload, allow_detail_lookup=False)
            if rec is not None:
                self._set_file_flag(rec, next_state)
        except Exception as exc:
            log.debug("MessageViewer: failed to update projected row flag: %s", exc)
            return
        row_index = self._messages_model.index_for_row(row) if hasattr(self, "_messages_model") else -1
        if row_index >= 0:
            index = self._messages_model.index(row_index, 7)
            self._messages_model.dataChanged.emit(index, index, [Qt.DisplayRole, Qt.ToolTipRole])
        if hasattr(self, "messages_table"):
            self.messages_table.viewport().update()

    def _set_js8_flag(self, msg_id: int, flag_state: int) -> None:
        db_path = self._local_js8_db()
        if not db_path or not Path(db_path).exists():
            return
        try:
            conn = sqlite3.connect(db_path)
            cur = conn.cursor()
            cur.execute("UPDATE js8_messages SET flag_state=? WHERE id=?", (int(flag_state), int(msg_id)))
            conn.commit()
            conn.close()
        except Exception as e:
            log.debug("MessageViewer: failed to update JS8 flag: %s", e)

    def _set_spotter_flag(self, msg_id: int, flag_state: int) -> None:
        db_path = self._db_path()
        if not db_path or not db_path.exists():
            return
        try:
            conn = sqlite3.connect(db_path)
            cur = conn.cursor()
            cur.execute("UPDATE spotter_traffic SET flag_state=? WHERE id=?", (int(flag_state), int(msg_id)))
            conn.commit()
            conn.close()
        except Exception as e:
            log.debug("MessageViewer: failed to update Spotter flag: %s", e)

    def _set_varac_flag(self, msg: VarACMessage, flag_state: int) -> None:
        db_path = self._db_path()
        if not db_path or not db_path.exists():
            return
        try:
            conn = sqlite3.connect(db_path)
            cur = conn.cursor()
            source_key = str(getattr(msg, "source_key", "") or "").strip()
            if source_key and self._table_has_column(conn, "varac_messages", "ingest_source_key"):
                cur.execute(
                    "UPDATE varac_messages SET flag_state=? WHERE ingest_source_key=? AND source=? AND id=?",
                    (int(flag_state), source_key, msg.source, int(msg.msg_id)),
                )
            else:
                cur.execute(
                    "UPDATE varac_messages SET flag_state=? WHERE source=? AND id=?",
                    (int(flag_state), msg.source, int(msg.msg_id)),
                )
            conn.commit()
            conn.close()
        except Exception as e:
            log.debug("MessageViewer: failed to update VarAC flag: %s", e)

    def _set_file_flag(self, rec: FileRecord, flag_state: int) -> None:
        db_path = self._db_path()
        if not db_path:
            return
        key = self._read_state_key(rec.origin, rec)
        status, read_ts, _ = self._read_state_map.get(key, ("NEW", 0.0, 0))
        self._read_state_map[key] = (status, read_ts, int(flag_state))
        try:
            conn = sqlite3.connect(db_path)
            cur = conn.cursor()
            cur.execute(
                """
                INSERT OR REPLACE INTO message_read_state
                    (origin, path, mtime, size, status, read_ts, flag_state)
                VALUES (?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    rec.origin,
                    str(rec.path),
                    float(rec.mtime),
                    int(rec.size),
                    status,
                    float(read_ts),
                    int(flag_state),
                ),
            )
            conn.commit()
            conn.close()
        except Exception as e:
            log.debug("MessageViewer: failed to update file flag: %s", e)

    @staticmethod
    def _sqlite_identifier(name: str) -> str:
        return sqlite_identifier(name)

    def _local_projection_fingerprint(
        self,
        tables: Sequence[str],
        db_path: str | Path | None = None,
    ) -> Tuple[Tuple[str, ...], ...]:
        if db_path is None:
            db_path = self._db_path()
        return sqlite_table_fingerprint(db_path, tables)

    def _can_skip_local_projection_load(
        self,
        cache_attr: str,
        fingerprint: Tuple[Tuple[str, ...], ...],
        *,
        force: bool,
    ) -> bool:
        if force or not fingerprint:
            return False
        return getattr(self, cache_attr, None) == fingerprint

    def _load_varac_from_local(self, force: bool = False, rebuild: bool = True) -> None:
        db_path = self._db_path()
        msgs: List[VarACMessage] = []
        if not db_path or not db_path.exists():
            self.varac_messages = msgs
            if rebuild:
                self._populate_messages_table(force=force)
            return
        fingerprint = self._local_projection_fingerprint(("varac_messages",))
        if self._can_skip_local_projection_load("_varac_local_snapshot_fp", fingerprint, force=force):
            return
        try:
            conn = sqlite3.connect(db_path)
            cur = conn.cursor()
            has_source_key = self._table_has_column(conn, "varac_messages", "ingest_source_key")
            source_key_expr = "COALESCE(ingest_source_key, 'legacy')" if has_source_key else "'legacy'"
            cur.execute(
                f"""
                SELECT id, guid, source, msg_type, from_call, to_call, subject, body,
                       ts, band, freq_hz, snr, read_status, folder, vmail_guid, is_deleted, flag_state, has_attachment,
                       {source_key_expr} AS ingest_source_key
                FROM varac_messages
                WHERE COALESCE(is_deleted, 0) = 0
                ORDER BY ts DESC
                """
            )
            rows = cur.fetchall()
            conn.close()
        except Exception as e:
            log.debug("MessageViewer: failed to load varac messages: %s", e)
            rows = []
        for r in rows:
            msg_type = (r[3] or "")
            if msg_type.strip().upper() == "QSO":
                continue
            msg = VarACMessage(
                msg_id=int(r[0]),
                guid=(r[1] or ""),
                source=(r[2] or ""),
                msg_type=msg_type,
                from_call=(r[4] or "").strip().upper(),
                to_call=(r[5] or "").strip().upper(),
                subject=(r[6] or ""),
                body=(r[7] or ""),
                ts=float(r[8] or 0.0),
                band=(r[9] or ""),
                freq_hz=float(r[10]) if r[10] not in (None, "") else None,
                snr=float(r[11]) if r[11] not in (None, "") else None,
                read_status=int(r[12] or 0),
                folder=str(r[13] or ""),
                vmail_guid=(r[14] or ""),
                flag_state=int(r[16] or 0),
                has_attachment=int(r[17] or 0),
                source_key=str(r[18] or "legacy"),
            )
            msgs.append(msg)
        self.varac_messages = msgs
        self._varac_local_snapshot_fp = fingerprint or None
        if rebuild:
            self._populate_messages_table(force=force)

    @staticmethod
    def _is_truthy(value: object, default: bool = False) -> bool:
        if isinstance(value, bool):
            return value
        if isinstance(value, (int, float)):
            return bool(value)
        txt = str(value or "").strip().lower()
        if txt in {"1", "true", "yes", "on", "enabled"}:
            return True
        if txt in {"0", "false", "no", "off", "disabled"}:
            return False
        return bool(default)

    def _load_sitrep_from_local(self, force: bool = False, rebuild: bool = True) -> None:
        db_path = self._db_path()
        msgs: List[SitrepMessage] = []
        enabled = self._is_truthy(self.settings.get("sitrep_unified_messages_enabled", True), True)
        if not enabled:
            self.sitrep_messages = msgs
            if rebuild:
                self._populate_messages_table(force=force)
            return
        if not db_path or not db_path.exists():
            self.sitrep_messages = msgs
            if rebuild:
                self._populate_messages_table(force=force)
            return
        fingerprint = self._local_projection_fingerprint(("sitrep_events",))
        if self._can_skip_local_projection_load("_sitrep_local_snapshot_fp", fingerprint, force=force):
            return
        started = time.perf_counter()
        try:
            limit = int(self.settings.get("sitrep_message_load_limit", 1000) or 1000)
        except Exception:
            limit = 1000
        limit = max(250, min(50000, limit))
        try:
            conn = sqlite3.connect(db_path)
            cur = conn.cursor()
            cur.execute(
                """
                SELECT id, report_key, event_ts, event_ts_utc, from_call, target, report_group, grid,
                       state_code, state_confidence, geo_confidence, scope,
                       subtype, overall_status, power, water, medical, communications, internet,
                       travel, food, fuel, crime, civil_unrest, political,
                       transport_mode, remarks_text, brevity_code, brevity_summary,
                       source_first, source_last, source_count, sources_json, source_refs_json, raw_payload_json, updated_ts
                FROM sitrep_events
                ORDER BY event_ts DESC, id DESC
                LIMIT ?
                """,
                (limit,),
            )
            rows = cur.fetchall()
            conn.close()
        except Exception as e:
            log.debug("MessageViewer: failed to load sitrep events: %s", e)
            rows = []
        for r in rows:
            sources_json = str(r[32] or "")
            source_candidates = self._safe_json_array_loads(sources_json)
            if not source_candidates:
                source_candidates = [str(r[29] or "").strip().upper(), str(r[30] or "").strip().upper()]
            source_families = source_families_from_sources(source_candidates)
            msg = SitrepMessage(
                event_id=int(r[0] or 0),
                report_key=str(r[1] or ""),
                event_ts=float(r[2] or 0.0),
                event_ts_utc=str(r[3] or ""),
                from_call=str(r[4] or "").strip().upper(),
                target=str(r[5] or "").strip().upper(),
                report_group=normalize_group_name(r[6]),
                grid=str(r[7] or "").strip().upper(),
                state_code=str(r[8] or "").strip().upper(),
                state_confidence=str(r[9] or "").strip().lower(),
                geo_confidence=str(r[10] or "").strip().lower(),
                scope=str(r[11] or "").strip(),
                subtype=str(r[12] or "").strip().upper(),
                subtype_label=subtype_label(r[12]),
                transport_mode=str(r[25] or "").strip().lower(),
                transport_label=transport_label(r[25]),
                remarks_text=str(r[26] or "").strip(),
                brevity_code=str(r[27] or "").strip().upper(),
                brevity_summary=str(r[28] or "").strip(),
                source_family_label=source_family_display_label(source_families),
                overall_status=str(r[13] or "").strip().lower(),
                power=str(r[14] or "").strip().lower(),
                water=str(r[15] or "").strip().lower(),
                medical=str(r[16] or "").strip().lower(),
                communications=str(r[17] or "").strip().lower(),
                internet=str(r[18] or "").strip().lower(),
                travel=str(r[19] or "").strip().lower(),
                food=str(r[20] or "").strip().lower(),
                fuel=str(r[21] or "").strip().lower(),
                crime=str(r[22] or "").strip().lower(),
                civil_unrest=str(r[23] or "").strip().lower(),
                political=str(r[24] or "").strip().lower(),
                source_first=str(r[29] or "").strip().upper(),
                source_last=str(r[30] or "").strip().upper(),
                source_count=int(r[31] or 0),
                sources_json=sources_json,
                source_refs_json=str(r[33] or ""),
                raw_payload_json=str(r[34] or ""),
                updated_ts=float(r[35] or 0.0),
            )
            msgs.append(msg)
        self.sitrep_messages = msgs
        self._sitrep_local_snapshot_fp = fingerprint or None
        if rebuild:
            self._populate_messages_table(force=force)
        emit_span(
            "messages.load_sitrep_from_local",
            (time.perf_counter() - started) * 1000.0,
            settings=self.settings,
            meta={"rows": len(msgs), "limit": limit, "force": bool(force), "rebuild": bool(rebuild)},
            min_ms=5.0,
        )

    def _load_commstat_from_local(self, force: bool = False, rebuild: bool = True) -> None:
        db_path = self._db_path()
        msgs: List[CommStatArtifact] = []
        if not db_path or not db_path.exists():
            self.commstat_messages = msgs
            if rebuild:
                self._populate_messages_table(force=force)
            return
        fingerprint = self._local_projection_fingerprint(("commstat_artifacts", "commstat_artifact_deletions"))
        if self._can_skip_local_projection_load("_commstat_local_snapshot_fp", fingerprint, force=force):
            return
        started = time.perf_counter()
        try:
            limit = int(self.settings.get("commstat_message_load_limit", 1000) or 1000)
        except Exception:
            limit = 1000
        limit = max(250, min(50000, limit))
        try:
            conn = sqlite3.connect(db_path)
            cur = conn.cursor()
            has_deletions = table_exists(conn, "commstat_artifact_deletions")
            deletion_join = (
                """
                LEFT JOIN commstat_artifact_deletions cad
                  ON cad.artifact_key = ca.artifact_key
                """
                if has_deletions
                else ""
            )
            deletion_where = "WHERE cad.artifact_key IS NULL" if has_deletions else ""
            cur.execute(
                f"""
                SELECT ca.id, ca.artifact_key, ca.artifact_kind, ca.subtype, ca.event_ts, ca.event_ts_utc,
                       ca.from_call, ca.target, ca.report_group, ca.grid, ca.state_code, ca.scope,
                       ca.transport_mode, ca.reach_mode, ca.status_label, ca.alert_color, ca.title, ca.body_text, ca.remarks_text,
                       ca.source_first, ca.source_last, ca.source_count, ca.sources_json, ca.source_refs_json,
                       ca.external_ids_json, ca.payload_json, ca.updated_ts
                FROM commstat_artifacts ca
                {deletion_join}
                {deletion_where}
                ORDER BY ca.event_ts DESC, ca.id DESC
                LIMIT ?
                """,
                (limit,),
            )
            rows = cur.fetchall()
            conn.close()
        except Exception as e:
            log.debug("MessageViewer: failed to load CommStat artifacts: %s", e)
            rows = []
        for r in rows:
            sources_json = str(r[22] or "")
            source_candidates = self._safe_json_array_loads(sources_json)
            if not source_candidates:
                source_candidates = [str(r[19] or "").strip().upper(), str(r[20] or "").strip().upper()]
            msg = CommStatArtifact(
                artifact_id=int(r[0] or 0),
                artifact_key=str(r[1] or ""),
                artifact_kind=str(r[2] or "").strip().upper(),
                subtype=str(r[3] or "").strip().upper(),
                event_ts=float(r[4] or 0.0),
                event_ts_utc=str(r[5] or ""),
                from_call=str(r[6] or "").strip().upper(),
                target=str(r[7] or "").strip().upper(),
                report_group=normalize_group_name(r[8]),
                grid=str(r[9] or "").strip().upper(),
                state_code=str(r[10] or "").strip().upper(),
                scope=str(r[11] or "").strip(),
                transport_mode=str(r[12] or "").strip().lower(),
                transport_label=transport_label(r[12]),
                reach_mode=str(r[13] or "").strip().lower(),
                reach_label=commstat_reach_label(r[13]),
                status_label=str(r[14] or "").strip().upper(),
                alert_color=str(r[15] or "").strip().upper(),
                title=str(r[16] or "").strip(),
                body_text=str(r[17] or "").strip(),
                remarks_text=str(r[18] or "").strip(),
                source_family_label=source_family_display_label(source_families_from_sources(source_candidates)),
                source_first=str(r[19] or "").strip().upper(),
                source_last=str(r[20] or "").strip().upper(),
                source_count=int(r[21] or 0),
                sources_json=sources_json,
                source_refs_json=str(r[23] or ""),
                external_ids_json=str(r[24] or ""),
                payload_json=str(r[25] or ""),
                updated_ts=float(r[26] or 0.0),
            )
            msgs.append(msg)
        self.commstat_messages = msgs
        self._commstat_local_snapshot_fp = fingerprint or None
        self._project_commstat_alerts_to_observations()
        if rebuild:
            self._populate_messages_table(force=force)
        emit_span(
            "messages.load_commstat_from_local",
            (time.perf_counter() - started) * 1000.0,
            settings=self.settings,
            meta={"rows": len(msgs), "limit": limit, "force": bool(force), "rebuild": bool(rebuild)},
            min_ms=5.0,
        )

    # ---------- Pending JS8 MSG backlog ---------- #

    def _refresh_pending_backlog(self) -> None:
        if self._is_shutting_down:
            return
        self._ensure_backlog_table()
        self._update_pending_table()

    def _load_pending_rows(self, *, include_page: bool = True) -> List[Dict[str, str | float]]:
        db_path = self._backlog_db_path()
        if not db_path or not db_path.exists():
            self._pending_rows = []
            self._pending_total_count = 0
            return []
        try:
            # Keep both count and page inside one read snapshot.  Filtering
            # retrieved rows in SQL avoids materializing historical backlog
            # entries merely to hide them in the UI.
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True, timeout=1.5)
            try:
                conn.execute("PRAGMA busy_timeout=1500")
                conn.execute("BEGIN")
                total_row = conn.execute(
                    """
                    SELECT COUNT(*)
                    FROM autoquery_backlog
                    WHERE kind='MSG' AND UPPER(COALESCE(status, 'PENDING')) != 'RETRIEVED'
                    """
                ).fetchone()
                total_count = int(total_row[0] or 0) if total_row else 0
                offset = max(0, int(getattr(self, "_pending_page_offset", 0) or 0))
                if total_count and offset >= total_count:
                    offset = ((total_count - 1) // PENDING_RETRIEVAL_PAGE_SIZE) * PENDING_RETRIEVAL_PAGE_SIZE
                rows = []
                if include_page:
                    rows = conn.execute(
                        """
                        SELECT callsign, msg_id, status, last_attempt_ts, created_ts,
                               COALESCE(source_key, ''), COALESCE(source_radio_id, ''),
                               COALESCE(js8_instance_id, ''), COALESCE(source_path, '')
                        FROM autoquery_backlog
                        WHERE kind='MSG' AND UPPER(COALESCE(status, 'PENDING')) != 'RETRIEVED'
                        ORDER BY created_ts DESC, id DESC
                        LIMIT ? OFFSET ?
                        """,
                        (PENDING_RETRIEVAL_PAGE_SIZE, offset),
                    ).fetchall()
                self._pending_page_offset = offset
                self._pending_total_count = total_count
            finally:
                conn.close()
        except Exception as e:
            log.debug("MessageViewer: failed to load pending backlog: %s", e)
            self._pending_rows = []
            self._pending_total_count = 0
            return []
        out: List[Dict[str, str | float]] = []
        for row in rows:
            out.append(
                {
                    "callsign": (row[0] or "").strip().upper(),
                    "msg_id": str(row[1] or "").strip(),
                    "status": (row[2] or "PENDING").strip().upper(),
                    "last_seen_ts": float(row[3] or row[4] or 0.0),
                    "source_key": str(row[5] or "").strip(),
                    "source_radio_id": str(row[6] or "").strip(),
                    "js8_instance_id": str(row[7] or "").strip(),
                    "source_path": str(row[8] or "").strip(),
                }
            )
        self._pending_rows = out
        return out

    def _update_pending_table(self, *, include_page: bool | None = None) -> None:
        if include_page is None:
            include_page = bool(
                hasattr(self, "pending_review_dialog")
                and self.pending_review_dialog.isVisible()
            )
        rows = self._load_pending_rows(include_page=bool(include_page))
        pending_count = int(getattr(self, "_pending_total_count", len(rows)) or 0)
        if hasattr(self, "pending_count"):
            self.pending_count.setText(f"{pending_count} pending")
        if hasattr(self, "pending_review_summary"):
            if pending_count:
                self.pending_review_summary.setText(
                    f"{pending_count} pending JS8 retrieval{'s' if pending_count != 1 else ''}. "
                    "Newest retrievals are shown first."
                )
            else:
                self.pending_review_summary.setText("No pending JS8 retrievals.")
        self._sync_pending_retrieval_disclosure(pending_count)
        if not include_page:
            return
        rows_signature = json.dumps(rows, sort_keys=True, default=str)
        if rows_signature == self._pending_rows_signature:
            self._update_pending_paging_controls(pending_count, len(rows))
            return
        self._pending_rows_signature = rows_signature
        self.pending_table.setRowCount(0)
        for idx, row in enumerate(rows):
            self.pending_table.insertRow(idx)
            callsign = str(row.get("callsign", ""))
            msg_id = str(row.get("msg_id", ""))
            status = str(row.get("status", "PENDING")).upper()
            last_seen_ts = float(row.get("last_seen_ts", 0.0))

            self.pending_table.setItem(idx, 0, QTableWidgetItem(callsign))
            self.pending_table.setItem(idx, 1, QTableWidgetItem(msg_id))
            self.pending_table.setItem(idx, 2, QTableWidgetItem(self._fmt_ts(last_seen_ts)))
            self.pending_table.setItem(idx, 3, QTableWidgetItem(status))

            action_widget = QWidget()
            action_layout = QHBoxLayout(action_widget)
            action_layout.setContentsMargins(0, 0, 0, 0)
            action_layout.setSpacing(6)

            get_btn = QPushButton()
            retrieved_btn = QPushButton()
            theme = resolve_theme(self.settings)

            if status == "RETRIEVED":
                get_btn.setText("Get")
                get_btn.setEnabled(False)
                get_btn.setStyleSheet(button_style("muted", theme))
                retrieved_btn.setText("Retrieved")
                retrieved_btn.setEnabled(False)
                retrieved_btn.setStyleSheet(button_style("muted", theme))
            else:
                get_btn.setText("Get")
                get_btn.setEnabled(True)
                get_btn.setStyleSheet(button_style("success", theme))
                retrieved_btn.setText("Mark Retrieved")
                retrieved_btn.setEnabled(True)
                retrieved_btn.setStyleSheet(button_style("warning", theme))

            row_context = dict(row)
            get_btn.clicked.connect(lambda _, ctx=row_context: self._on_pending_get_row(ctx))
            retrieved_btn.clicked.connect(lambda _, ctx=row_context: self._on_pending_mark_retrieved_row(ctx))
            action_layout.addWidget(get_btn)
            action_layout.addWidget(retrieved_btn)
            action_layout.addStretch()
            self.pending_table.setCellWidget(idx, 4, action_widget)
        self._update_pending_paging_controls(pending_count, len(rows))

    def _sync_pending_retrieval_disclosure(self, pending_count: int) -> None:
        visible = bool(pending_count > 0 and self._messages_mode == "Inbox")
        if hasattr(self, "pending_retrieval_widget"):
            self.pending_retrieval_widget.setVisible(visible)
        if hasattr(self, "pending_review_btn"):
            self.pending_review_btn.setEnabled(pending_count > 0)
        if pending_count <= 0 and hasattr(self, "pending_review_dialog") and self.pending_review_dialog.isVisible():
            self.pending_review_dialog.close()

    def _update_pending_paging_controls(self, pending_count: int, page_rows: int) -> None:
        offset = max(0, int(getattr(self, "_pending_page_offset", 0) or 0))
        if hasattr(self, "pending_previous_btn"):
            self.pending_previous_btn.setEnabled(offset > 0)
        if hasattr(self, "pending_next_btn"):
            self.pending_next_btn.setEnabled(offset + page_rows < pending_count)
        if hasattr(self, "pending_page_label"):
            if pending_count <= 0:
                self.pending_page_label.setText("")
            else:
                self.pending_page_label.setText(
                    f"Showing {offset + 1}–{offset + page_rows} of {pending_count}"
                )

    def _change_pending_page(self, direction: int) -> None:
        current = max(0, int(getattr(self, "_pending_page_offset", 0) or 0))
        self._pending_page_offset = max(0, current + (PENDING_RETRIEVAL_PAGE_SIZE * int(direction or 0)))
        self._pending_rows_signature = ""
        self._update_pending_table(include_page=True)

    def _open_pending_review(self) -> None:
        self._pending_page_offset = 0
        self._pending_rows_signature = ""
        if not int(getattr(self, "_pending_total_count", 0) or 0):
            return
        host = self.window()
        available = host.size() if host is not None else self.size()
        width = max(480, min(980, int(available.width() * 0.9)))
        height = max(300, min(640, int(available.height() * 0.85)))
        self.pending_review_dialog.resize(width, height)
        self.pending_review_dialog.show()
        self.pending_review_dialog.raise_()
        self.pending_review_dialog.activateWindow()
        # Let the workbench paint before its bounded page is materialized.
        QTimer.singleShot(0, lambda: self._update_pending_table(include_page=True))

    def _on_pending_review_closed(self, _result: int) -> None:
        self._pending_page_offset = 0
        self._pending_rows_signature = ""
        if hasattr(self, "pending_table"):
            self.pending_table.setRowCount(0)
        if hasattr(self, "messages_table") and self._messages_mode == "Inbox":
            self.messages_table.setFocus(Qt.OtherFocusReason)

    def apply_theme(self) -> None:
        theme = resolve_theme(self.settings)
        grid = theme["border"]
        table_style = (
            f"QTableView {{ gridline-color: {grid}; }}"
            "QTableView::indicator {"
            " width: 14px; height: 14px;"
            f" border: 1px solid {theme['text_muted']};"
            f" background-color: {theme['surface']};"
            "}"
            "QTableView::indicator:checked {"
            f" background-color: {theme['accent']};"
            f" border: 1px solid {theme['accent']};"
            "}"
        )
        self.messages_table.setStyleSheet(table_style)
        self.pending_table.setStyleSheet(f"QTableWidget {{ gridline-color: {grid}; }}")
        if self._actions_delegate:
            self.messages_table.viewport().update()
        if self.loading_label:
            bg = theme.get("surface_alt", theme.get("surface", "#f2f2f2"))
            fg = theme.get("accent", theme.get("text", "#222"))
            border = theme.get("border", "#ccc")
            self.loading_label.setStyleSheet(
                f"padding: 2px 6px; border-radius: 4px; background: {bg}; color: {fg}; border: 1px solid {border};"
            )
        header = self.messages_table.horizontalHeader()
        if isinstance(header, MessageHeaderWithCheckbox):
            accent = QColor(theme["accent"])
            luminance = (
                0.299 * accent.redF()
                + 0.587 * accent.greenF()
                + 0.114 * accent.blueF()
            )
            mark = QColor("#111111") if luminance >= 0.62 else QColor("#ffffff")
            header.set_checkbox_colors(
                bg=QColor(theme.get("surface_alt", theme["surface"])),
                border=QColor(theme.get("accent", theme["border"])),
                accent=accent,
                mark=mark,
            )
        self._update_time_toggle_style(theme)
        if hasattr(self, "traffic_action_summary"):
            self.traffic_action_summary.apply_theme(theme)
        self._update_clear_filters_style()
        self._update_mark_all_read_style()
        self._apply_accessibility_width_guards()
        # Theme changes repaint retained queue rows but never read or resize the
        # backlog.  The normal 30-second queue refresh owns that bounded query.
        self._sync_pending_retrieval_disclosure(
            int(getattr(self, "_pending_total_count", 0) or 0)
        )
        self._update_messages_mode_ui()
        if hasattr(self, "compose_setup_help_btn"):
            self.compose_setup_help_btn.setStyleSheet(button_style("secondary", theme))
        if hasattr(self, "compose_status_label"):
            self._set_compose_status(
                self.compose_status_label.text() or "Compose is ready.",
                role=getattr(self, "_compose_status_role", "info"),
            )
        self._refresh_compose_js8_selected_target_cue()
        if hasattr(self, "reader_delete_btn"):
            self.reader_delete_btn.setStyleSheet(button_style("danger", theme))
        for context_button in (
            getattr(self, "reader_map_btn", None),
            getattr(self, "reader_operator_btn", None),
            getattr(self, "reader_reply_btn", None),
            getattr(self, "reader_watch_btn", None),
        ):
            if isinstance(context_button, QPushButton):
                context_button.setStyleSheet(button_style("secondary", theme))

    def shutdown(self) -> None:
        self._is_shutting_down = True
        lane = getattr(self, "_compose_mesh_contact_lane", None)
        if lane is not None:
            lane.shutdown()
        self._compose_mesh_contact_generation = int(getattr(self, "_compose_mesh_contact_generation", 0)) + 1
        self._compose_mesh_contact_pending = {}
        contact_dialog = getattr(self, "_compose_mesh_contact_dialog", None)
        if isinstance(contact_dialog, QDialog):
            contact_dialog.close()
            self._compose_mesh_contact_dialog = None
        cache = getattr(self, "_compose_brevity_read_cache", None)
        if cache is not None:
            cache.close()
        timer = getattr(self, "_compose_brevity_poll", None)
        if timer is not None:
            timer.stop()
        # Invalidate any endpoint result that races application shutdown.  The
        # selected-target endpoint worker is attached by the primary runtime.
        self._cancel_compose_js8_selected_target_worker()
        self._compose_js8_selected_target_generation += 1
        self._compose_js8_selected_target_state = "unknown"
        self._compose_js8_selected_target_value = ""
        self._compose_js8_selected_target_action = ""
        self._compose_js8_selected_target_pending_context = {}
        try:
            if self._persist_timer and self._persist_timer.isActive():
                self._persist_timer.stop()
        except Exception:
            pass
        try:
            self._flush_persist_ops()
        except Exception:
            pass
        try:
            if self._timer:
                self._timer.stop()
        except Exception:
            pass
        try:
            if self._js8_timer:
                self._js8_timer.stop()
        except Exception:
            pass
        try:
            if self._pending_timer:
                self._pending_timer.stop()
        except Exception:
            pass
        try:
            if self._bbs_auto_archive_timer:
                self._bbs_auto_archive_timer.stop()
        except Exception:
            pass
        try:
            if self._projection_delete_queue_timer:
                self._projection_delete_queue_timer.stop()
        except Exception:
            pass
        try:
            if self._filter_timer:
                self._filter_timer.stop()
        except Exception:
            pass
        try:
            if self._projected_query_timer:
                self._projected_query_timer.stop()
        except Exception:
            pass
        try:
            if self._file_watch_debounce_timer:
                self._file_watch_debounce_timer.stop()
        except Exception:
            pass
        self._request_worker_thread_stop(self._file_scan_thread)
        self._request_worker_thread_stop(self._rows_build_thread)
        self._request_worker_thread_stop(self._projection_write_thread)
        self._request_worker_thread_stop(self._native_file_projection_thread)
        self._request_worker_thread_stop(self._projected_query_thread)
        self._request_worker_thread_stop(self._signature_verify_thread)
        self._request_worker_thread_stop(self._bbs_auto_archive_thread)
        # Compose discovery workers touch the filesystem, external GPG state,
        # local databases, or one bounded JS8 socket request. Give these
        # short-lived workers a bounded clean exit so Qt never destroys a live
        # thread during application shutdown.
        for background_thread in (
            getattr(self, "_compose_discovery_thread", None),
            getattr(self, "_compose_mesh_thread", None),
            getattr(self, "_compose_signing_key_thread", None),
            getattr(self, "_compose_guidance_thread", None),
            getattr(self, "_compose_js8_selected_target_thread", None),
        ):
            if background_thread is None:
                continue
            try:
                if background_thread.isRunning():
                    background_thread.requestInterruption()
                    background_thread.quit()
                    background_thread.wait(5000)
            except Exception:
                pass
        compose_thread = getattr(self, "_compose_stage_thread", None)
        if compose_thread is not None:
            try:
                if compose_thread.isRunning():
                    compose_thread.requestInterruption()
                    compose_thread.quit()
                    # A signing process or final local transaction must finish
                    # before Qt destroys its worker thread during app exit.
                    compose_thread.wait(10000)
            except Exception:
                pass
        send_thread = getattr(self, "_compose_send_thread", None)
        if send_thread is not None:
            try:
                if send_thread.isRunning():
                    send_thread.requestInterruption()
                    send_thread.quit()
                    send_thread.wait(3000)
            except Exception:
                pass

    @staticmethod
    def _request_worker_thread_stop(thread: QThread | None, *, wait_ms: int = 150) -> None:
        if thread is None:
            return
        try:
            if not thread.isRunning():
                return
            thread.requestInterruption()
            thread.quit()
            thread.wait(max(0, min(int(wait_ms), 250)))
        except Exception:
            pass

    def on_settings_saved(self) -> None:
        try:
            self.plan_context_label.invalidate_context()
            self.plan_context_label.refresh_context(refresh=True)
        except Exception:
            pass
        prev_watch_sig = ""
        prev_auth_sig: tuple = tuple()
        try:
            prev_watch_sig = self._watch_dirs_signature(self._effective_watch_dirs())
            prev_auth_sig = self._auth_refresh_signature()
        except Exception:
            prev_watch_sig = ""
            prev_auth_sig = tuple()
        try:
            if hasattr(self.settings, "reload"):
                self.settings.reload()
        except Exception:
            pass
        self._invalidate_bbs_action_cache()
        if bool(getattr(self, "_projection_primary_enabled", False)):
            self._request_projected_message_query(force=True)
        watch_sig_changed = False
        auth_sig_changed = False
        try:
            watch_sig_changed = prev_watch_sig != self._watch_dirs_signature(self._effective_watch_dirs())
            auth_sig_changed = prev_auth_sig != self._auth_refresh_signature()
        except Exception:
            watch_sig_changed = False
            auth_sig_changed = False
        try:
            if watch_sig_changed:
                # Only rescan file watches when a watch-root-affecting setting changed.
                self._sync_file_system_watcher()
                self._refresh_files(force=False)
        except Exception:
            if watch_sig_changed:
                try:
                    self._refresh_varac_messages(force=True)
                except Exception:
                    pass
        if auth_sig_changed:
            try:
                self._start_signature_verification(force=True)
            except Exception:
                pass
        try:
            if self._has_active_view:
                self._queue_bbs_auto_archive_check("settings_saved", delay_ms=1500)
        except Exception:
            pass
        self._update_pending_table()

    def _auth_refresh_signature(self) -> tuple:
        try:
            trusted_signers_raw = self.settings.get("gpg_trusted_signers", []) or []
            if not isinstance(trusted_signers_raw, list):
                trusted_signers_raw = []
            trusted_signers = tuple(sorted(normalize_fingerprints(str(v) for v in trusted_signers_raw)))
        except Exception:
            trusted_signers = tuple()
        try:
            inline_suffixes = tuple(self._inline_signature_name_suffixes())
        except Exception:
            inline_suffixes = tuple()
        return (
            bool(self.settings.get("gpg_verify_flamp_k2s_enabled", False)),
            bool(self.settings.get("hash_verify_flamp_k2s_enabled", True)),
            str(self.settings.get("gpg_executable_path", "") or "").strip(),
            trusted_signers,
            inline_suffixes,
            str(self._trusted_hash_set_signature() or ""),
        )

    def _queue_persist_op(self, op: str, payload: Tuple) -> None:
        self._pending_persist_ops.append((op, payload))
        if self._persist_timer is None:
            self._persist_timer = QTimer(self)
            self._persist_timer.setSingleShot(True)
            self._persist_timer.timeout.connect(self._flush_persist_ops)
        if not self._persist_timer.isActive():
            self._persist_timer.start(120)

    def _flush_persist_ops(self) -> None:
        if not self._pending_persist_ops:
            return
        ops = self._pending_persist_ops
        self._pending_persist_ops = []
        for op, payload in ops:
            try:
                if op == "file_read_state":
                    origin, path_txt, mtime, size, status, read_ts, flag_state = payload
                    self._persist_file_read_state(
                        str(origin),
                        str(path_txt),
                        float(mtime),
                        int(size),
                        str(status),
                        float(read_ts),
                        int(flag_state),
                    )
                elif op == "spotter_read":
                    spotter_id, read_ts = payload
                    self._persist_spotter_read(int(spotter_id), float(read_ts))
                elif op == "varac_read":
                    source, msg_id, source_key = (*payload, "")[:3]
                    self._persist_varac_read(str(source), int(msg_id), str(source_key))
                elif op == "js8_read":
                    msg_id, utc_ts, read_ts, sync_flag, source_id, source_path, source_key = (*payload, 0, "", "")[:7]
                    self._persist_js8_read(
                        int(msg_id),
                        float(utc_ts),
                        float(read_ts),
                        bool(sync_flag),
                        source_id=int(source_id or 0),
                        source_path=str(source_path or ""),
                        source_key=str(source_key or ""),
                    )
            except Exception as e:
                log.debug("MessageViewer: deferred persist op failed (%s): %s", op, e)

    def _persist_file_read_state(
        self,
        origin: str,
        path_txt: str,
        mtime: float,
        size: int,
        status: str,
        read_ts: float,
        flag_state: int,
    ) -> None:
        db_path = self._db_path()
        if not db_path:
            return
        try:
            conn = sqlite3.connect(db_path)
            cur = conn.cursor()
            cur.execute(
                """
                INSERT OR REPLACE INTO message_read_state
                    (origin, path, mtime, size, status, read_ts, flag_state)
                VALUES (?, ?, ?, ?, ?, ?, ?)
                """,
                (origin, path_txt, float(mtime), int(size), status, float(read_ts), int(flag_state)),
            )
            conn.commit()
            conn.close()
        except Exception as e:
            log.debug("MessageViewer: failed to persist read state: %s", e)

    def _persist_spotter_read(self, spotter_id: int, read_ts: float) -> None:
        db_path = self._db_path()
        if not db_path:
            return
        try:
            conn = sqlite3.connect(db_path)
            cur = conn.cursor()
            cur.execute(
                "UPDATE spotter_traffic SET state='READ', read_ts=? WHERE id=?",
                (float(read_ts), int(spotter_id)),
            )
            conn.commit()
            conn.close()
        except Exception as e:
            log.debug("MessageViewer: failed to update spotter read state: %s", e)

    def _persist_varac_read(self, source: str, msg_id: int, source_key: str = "") -> None:
        db_path = self._db_path()
        if not db_path or not db_path.exists():
            return
        try:
            conn = sqlite3.connect(db_path)
            cur = conn.cursor()
            source_key = str(source_key or "").strip()
            if source_key and self._table_has_column(conn, "varac_messages", "ingest_source_key"):
                cur.execute(
                    "UPDATE varac_messages SET read_status=1 WHERE ingest_source_key=? AND source=? AND id=?",
                    (source_key, source, int(msg_id)),
                )
            else:
                cur.execute(
                    "UPDATE varac_messages SET read_status=1 WHERE source=? AND id=?",
                    (source, int(msg_id)),
                )
            conn.commit()
            conn.close()
        except Exception:
            pass

    def _persist_js8_read(
        self,
        msg_id: int,
        utc_ts: float,
        read_ts: float,
        sync_flag: bool,
        *,
        source_id: int = 0,
        source_path: str = "",
        source_key: str = "",
    ) -> None:
        try:
            self._save_js8_state(
                source_id or msg_id,
                "READ",
                utc_ts,
                read_ts=read_ts,
                source_key=source_key,
                source_id=source_id or msg_id,
            )
            self._update_local_read(msg_id, read_ts)
        except Exception as e:
            log.debug("MessageViewer: failed to persist JS8 READ state: %s", e)
        if sync_flag:
            try:
                ok = self._mark_js8call_inbox_read_by_id(source_id or msg_id, inbox_path=source_path)
                if not ok:
                    log.debug(
                        "MessageViewer: JS8Call inbox mark READ failed (msg_id=%s)",
                        msg_id,
                    )
            except Exception:
                pass

    def _pending_set_status(self, callsign: str, msg_id: str, status: str, source_key: str = "") -> None:
        db_path = self._backlog_db_path()
        if not db_path:
            return
        try:
            conn = sqlite3.connect(db_path)
            cur = conn.cursor()
            cur.execute(
                """
                UPDATE autoquery_backlog
                SET status=?, last_attempt_ts=?
                WHERE callsign=? AND COALESCE(msg_id,'')=COALESCE(?, '') AND kind='MSG'
                  AND COALESCE(source_key, '')=COALESCE(?, '')
                """,
                (status.upper(), time.time(), callsign, msg_id or "", str(source_key or "").strip()),
            )
            conn.commit()
            conn.close()
        except Exception as e:
            log.debug("MessageViewer: failed to set pending status: %s", e)

    def _pending_delete(self, callsign: str, msg_id: str, source_key: str = "") -> None:
        db_path = self._backlog_db_path()
        if not db_path:
            return
        try:
            conn = sqlite3.connect(db_path)
            cur = conn.cursor()
            cur.execute(
                """
                DELETE FROM autoquery_backlog
                WHERE callsign=? AND COALESCE(msg_id,'')=COALESCE(?, '') AND kind='MSG'
                  AND COALESCE(source_key, '')=COALESCE(?, '')
                """,
                (callsign, msg_id or "", str(source_key or "").strip()),
            )
            conn.commit()
            conn.close()
        except Exception as e:
            log.debug("MessageViewer: failed to delete pending row: %s", e)

    def _minutes_to_next_change(self) -> Optional[int]:
        if suspend_active(self.settings) or not scheduler_enabled(self.settings):
            return None
        win = self.window()
        sched = getattr(win, "scheduler", None) if win is not None else None
        dt = getattr(sched, "next_change_utc", None) if sched is not None else None
        if not dt:
            return None
        if getattr(dt, "tzinfo", None) is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        else:
            dt = dt.astimezone(datetime.timezone.utc)
        now_utc = datetime.datetime.now(datetime.timezone.utc)
        delta = (dt - now_utc).total_seconds()
        if delta <= 0:
            return None
        return int((delta + 59) // 60)

    def _on_pending_get(self, callsign: str, msg_id: str) -> None:
        self._on_pending_get_row({"callsign": callsign, "msg_id": msg_id})

    def _on_pending_get_row(self, row: Mapping[str, object]) -> None:
        callsign = str(row.get("callsign", "") or "").strip().upper()
        msg_id = str(row.get("msg_id", "") or "").strip()
        if not callsign or not msg_id:
            return
        mycall = self._my_callsign()
        if not mycall:
            QMessageBox.warning(self, "Missing Callsign", "Configure your callsign in the Settings tab.")
            return
        minutes = self._minutes_to_next_change()
        if minutes is not None and minutes <= 5:
            resp = QMessageBox.question(
                self,
                "Frequency Change",
                f"Frequency Change in {minutes} minutes. Continue?",
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No,
            )
            if resp != QMessageBox.Yes:
                return
        text = f"{mycall}: {callsign} QUERY MSG {msg_id}".strip()
        resp = QMessageBox.question(
            self,
            "Send MSG",
            f"Send this JS8Call message?\n\n{text}",
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No,
        )
        if resp != QMessageBox.Yes:
            return
        endpoint, source_label = self._pending_js8_endpoint(row)
        source_key = str(row.get("source_key", "") or "")

        def _send() -> dict[str, object]:
            sent = self._send_js8_message_to_endpoint(text, endpoint=endpoint, source_label=source_label)
            if sent:
                self._pending_set_status(callsign, msg_id, "WAITING", source_key)
            return {
                "ok": sent,
                "message": "Request sent; waiting for the JS8 retrieval."
                if sent
                else f"The retrieval request could not be sent through {source_label}.",
            }

        self._start_pending_action("Sending retrieval request…", _send)

    def _on_pending_mark_retrieved(self, callsign: str, msg_id: str) -> None:
        self._on_pending_mark_retrieved_row({"callsign": callsign, "msg_id": msg_id})

    def _on_pending_mark_retrieved_row(self, row: Mapping[str, object]) -> None:
        callsign = str(row.get("callsign", "") or "").strip().upper()
        msg_id = str(row.get("msg_id", "") or "").strip()
        source_key = str(row.get("source_key", "") or "").strip()
        if not callsign or not msg_id:
            return
        sync_inbox = bool(self.settings.get("js8_inbox_mark_retrieved_sync", False))
        source_path = str(row.get("source_path", "") or "").strip() or None

        def _mark_retrieved() -> dict[str, object]:
            inbox_updated = True
            if sync_inbox:
                inbox_updated = self._mark_js8call_inbox_read(
                    callsign,
                    msg_id,
                    inbox_path=source_path,
                )
                if not inbox_updated:
                    log.debug(
                        "MessageViewer: JS8Call inbox mark READ failed (callsign=%s msg_id=%s)",
                        callsign,
                        msg_id,
                    )
            self._pending_delete(callsign, msg_id, source_key)
            return {
                "ok": True,
                "message": "Marked retrieved."
                if inbox_updated
                else "Removed from CommsPlan retrievals; the JS8Call inbox could not be updated.",
            }

        self._start_pending_action("Marking retrieval complete…", _mark_retrieved)

    def _start_pending_action(
        self,
        acknowledgement: str,
        operation: Callable[[], Mapping[str, object]],
    ) -> bool:
        """Acknowledge immediately and serialize endpoint/storage work off the GUI thread."""

        # Preserve the narrow headless/core compatibility seam used by source
        # mutation tests and non-widget callers. A constructed UI always owns
        # the bridge and therefore always takes the asynchronous path.
        if not hasattr(self, "pending_review_summary") or not hasattr(self, "_pending_action_bridge"):
            operation()
            try:
                self._update_pending_table()
            except Exception:
                pass
            return True

        current = getattr(self, "_pending_action_thread", None)
        if current is not None and current.is_alive():
            self.pending_review_summary.setText("Finish the current retrieval action before starting another.")
            return False
        self._pending_action_generation = int(getattr(self, "_pending_action_generation", 0) or 0) + 1
        generation = self._pending_action_generation
        self.pending_review_summary.setText(acknowledgement)
        self.pending_table.setEnabled(False)
        self.pending_previous_btn.setEnabled(False)
        self.pending_next_btn.setEnabled(False)

        def _run() -> None:
            started = time.perf_counter()
            try:
                result = dict(operation() or {})
                payload: dict[str, object] = {
                    "generation": generation,
                    "ok": bool(result.get("ok", True)),
                    "message": str(result.get("message", "") or ""),
                }
            except Exception as exc:
                log.warning("MessageViewer: pending retrieval action failed: %s", exc)
                payload = {
                    "generation": generation,
                    "ok": False,
                    "message": f"Retrieval action failed: {exc}",
                }
            payload["elapsed_ms"] = (time.perf_counter() - started) * 1000.0
            try:
                self._pending_action_bridge.finished.emit(payload)
            except RuntimeError:
                # The tab may have closed while bounded endpoint I/O drained.
                return

        thread = threading.Thread(
            target=_run,
            name=f"fio-js8-retrieval-{generation}",
            daemon=True,
        )
        self._pending_action_thread = thread
        thread.start()
        return True

    def _on_pending_action_finished(self, payload: object) -> None:
        data = payload if isinstance(payload, dict) else {}
        generation = int(data.get("generation", 0) or 0)
        if generation != int(getattr(self, "_pending_action_generation", 0) or 0):
            return
        self._pending_action_thread = None
        if getattr(self, "_is_shutting_down", False):
            return
        self.pending_table.setEnabled(True)
        review_open = self.pending_review_dialog.isVisible()
        self._pending_rows_signature = ""
        self._update_pending_table(include_page=review_open)
        message = str(data.get("message", "") or "").strip()
        if message and review_open:
            self.pending_review_summary.setText(message)
        emit_span(
            "messages.pending_retrieval_action",
            float(data.get("elapsed_ms", 0.0) or 0.0),
            settings=self.settings,
            meta={"ok": bool(data.get("ok", False))},
            min_ms=50.0,
        )

    def _send_js8_message(self, text: str, *, source_context: Mapping[str, object] | None = None) -> bool:
        context = source_context or {}
        if not self._pending_js8_source_allows_transmit(context):
            log.warning("MessageViewer: blocked JS8 transmit through receive-only observer source")
            return False
        endpoint, source_label = self._pending_js8_endpoint(context)
        return self._send_js8_message_to_endpoint(text, endpoint=endpoint, source_label=source_label)

    def _pending_js8_source_allows_transmit(self, source_context: Mapping[str, object]) -> bool:
        """Reject retrieval/send routing through an observer-owned JS8 source.

        Historical rows may not carry radio or instance provenance; those keep
        the legacy endpoint fallback.  When durable provenance is present, the
        matching radio profile is authoritative and an observer must never be
        used to transmit a retrieval request.
        """

        radio_id = str(source_context.get("source_radio_id", "") or "").strip()
        js8_id = str(source_context.get("js8_instance_id", "") or "").strip().casefold()
        if not radio_id and not js8_id:
            return True
        try:
            profiles = MultiRadioStore().list_profiles(enabled_only=False)
        except Exception:
            # Failure to resolve a provenance-bearing source must not silently
            # grant transmit authority.
            return False
        for profile in profiles:
            if not isinstance(profile, Mapping):
                continue
            profile_radio = str(profile.get("id", "") or profile.get("radio_profile_id", "") or "").strip()
            profile_js8 = str(profile.get("js8_instance_id", "") or "").strip().casefold()
            if radio_id and profile_radio != radio_id:
                continue
            if js8_id and profile_js8 != js8_id:
                continue
            return js8_profile_allows_transmit(profile)
        return False

    @staticmethod
    def _send_js8_message_to_endpoint(
        text: str,
        *,
        endpoint: JS8ApiEndpoint,
        source_label: str,
    ) -> bool:
        try:
            client = JS8ApiClientRegistry.get(endpoint, timeout_s=1.0, auto_reconnect=True)
            result = send_js8_message_guarded(
                client,
                text,
                timeout_s=0.6,
                allow_uncertain_target_state=True,
            )
            if result.sent:
                log.info("MessageViewer: sent JS8 TX.SEND_MESSAGE to %s text=%s", source_label, text)
                return True
            log.warning("MessageViewer: JS8 send blocked for %s: %s", source_label, result.detail)
        except Exception as e:
            log.error("MessageViewer: failed to send JS8 message to %s text=%s err=%s", source_label, text, e)
        return False

    def _pending_js8_endpoint(self, source_context: Mapping[str, object]) -> tuple[JS8ApiEndpoint, str]:
        radio_id = str(source_context.get("source_radio_id", "") or "").strip()
        js8_id = str(source_context.get("js8_instance_id", "") or "").strip()
        source_key = str(source_context.get("source_key", "") or "").strip()
        resolved = resolve_js8_endpoint_context(self.settings, source_context=source_context)
        if resolved:
            host = str(resolved.get("host", "") or "127.0.0.1").strip() or "127.0.0.1"
            try:
                port = int(resolved.get("port", 2442) or 2442)
            except Exception:
                port = 2442
            label = str(resolved.get("label", "") or source_key or js8_id or radio_id or f"{host}:{port}").strip()
            return JS8ApiEndpoint(host, port), label
        try:
            profiles = MultiRadioStore().list_profiles(enabled_only=False)
        except Exception:
            profiles = []
        radio_id_lc = radio_id.lower()
        js8_id_lc = js8_id.lower()
        for profile in profiles:
            profile_radio = str(profile.get("id", "") or profile.get("radio_profile_id", "") or "").strip()
            profile_js8 = str(profile.get("js8_instance_id", "") or profile.get("name", "") or profile_radio).strip()
            if radio_id and profile_radio.lower() != radio_id_lc:
                continue
            if js8_id and profile_js8.lower() != js8_id_lc:
                continue
            host = str(profile.get("js8_host") or self.settings.get("js8_host", "") or "127.0.0.1").strip() or "127.0.0.1"
            try:
                port = int(profile.get("js8_port") or self.settings.get("js8_port", 2442) or 2442)
            except Exception:
                port = 2442
            label = str(profile.get("name") or profile_js8 or profile_radio or source_key or f"{host}:{port}").strip()
            return JS8ApiEndpoint(host, port), label
        host = (self.settings.get("js8_host", "") or "").strip() or "127.0.0.1"
        try:
            port = int(self.settings.get("js8_port", 2442) or 2442)
        except Exception:
            port = 2442
        label = source_key or js8_id or radio_id or f"{host}:{port}"
        return JS8ApiEndpoint(host, port), label

    def _my_callsign(self) -> str:
        return (
            (self.settings.get("operator_callsign", "") or self.settings.get("callsign", "") or "")
            .strip()
            .upper()
        )

    def _current_time_mode(self) -> str:
        if self._time_mode_override:
            return self._time_mode_override
        return "LOCAL" if self._show_local_time else "UTC"

    def _current_timezone_label(self) -> tuple[str, str]:
        tz_name = self.settings.get("timezone", "UTC") or "UTC"
        tz = get_timezone(tz_name)
        now = datetime.datetime.now(tz)
        fallback = now.tzname() or tz_name
        abbr = self._ui_tz_abbr(tz_name, fallback)
        if abbr and len(abbr) > 5:
            abbr = self._ui_tz_abbr(tz_name, abbr)
        return str(tz_name), str(abbr)

    def _ui_tz_abbr(self, tz_name: str, fallback: str) -> str:
        mapping = {
            "UTC": "UTC",
            "America/New_York": "ET",
            "America/Chicago": "CT",
            "America/Denver": "MT",
            "America/Los_Angeles": "PT",
            "Mountain Standard Time": "MST",
            "Central Standard Time": "CST",
            "Eastern Standard Time": "EST",
            "Pacific Standard Time": "PST",
        }
        return mapping.get(tz_name, fallback)

    def _fmt_ts(self, ts: float) -> str:
        if not ts:
            return ""
        try:
            mode = self._current_time_mode()
            if mode == "UTC":
                return datetime.datetime.fromtimestamp(ts, tz=datetime.timezone.utc).strftime("%Y-%m-%d %H:%M:%S")
            tz_name = self.settings.get("timezone", "UTC") or "UTC"
            tz = get_timezone(tz_name)
            return datetime.datetime.fromtimestamp(ts, tz=tz).strftime("%Y-%m-%d %H:%M:%S")
        except Exception:
            return ""

    def _format_rcv_display(self, ts: float, utc_str: str | None) -> str:
        mode = self._current_time_mode()
        if mode == "UTC":
            if utc_str:
                return utc_str
            return self._fmt_ts(ts)
        if ts:
            return self._fmt_ts(ts)
        if utc_str:
            try:
                dt = datetime.datetime.strptime(utc_str, "%Y-%m-%d %H:%M:%S").replace(tzinfo=datetime.timezone.utc)
                tz_name = self.settings.get("timezone", "UTC") or "UTC"
                tz = get_timezone(tz_name)
                return dt.astimezone(tz).strftime("%Y-%m-%d %H:%M:%S")
            except Exception:
                return utc_str
        return ""

    def _update_time_ui(self) -> None:
        mode = self._current_time_mode()
        tz_name, tz_abbr = self._current_timezone_label()
        if mode == "UTC":
            self.time_toggle_btn.setText("Time Display: UTC")
            self._messages_model.set_time_header("Age")
            self.pending_table.setHorizontalHeaderLabels(
                ["Callsign", "Msg ID", "Last Seen (UTC)", "Status", "Actions"]
            )
        else:
            self.time_toggle_btn.setText("Time Display: Local")
            self._messages_model.set_time_header("Age")
            self.pending_table.setHorizontalHeaderLabels(
                ["Callsign", "Msg ID", f"Last Seen ({tz_abbr})", "Status", "Actions"]
            )
        self._update_time_toggle_style()

    def _setup_clock_timer(self) -> None:
        if self._clock_timer is not None:
            self._clock_timer.stop()
        self._clock_timer = QTimer(self)
        self._clock_timer.timeout.connect(self._on_clock_tick)
        self._clock_timer.start(1000)
        self._update_clock_labels()

    def _on_clock_tick(self) -> None:
        self._update_clock_labels()

    def _update_clock_labels(self) -> None:
        if not hasattr(self, "utc_label") or not hasattr(self, "local_label"):
            return
        now_utc = datetime.datetime.now(datetime.timezone.utc)
        utc_day = now_utc.strftime("%a")
        self.utc_label.setText(now_utc.strftime(f"<b>UTC ({utc_day}):</b> %y%m%d %H:%M:%S Z"))

        tz_name = self.settings.get("timezone", "UTC") or "UTC"
        tz = get_timezone(tz_name)
        now_local = now_utc.astimezone(tz)
        fallback = now_local.tzname() or tz_name
        local_abbr = fallback or tz_name
        local_day = now_local.strftime("%a")
        self.local_label.setText(now_local.strftime(f"<b>Local ({local_day}):</b> %y%m%d %H:%M:%S {local_abbr}"))
        if hasattr(self, "time_toggle_btn"):
            self.time_toggle_btn.setText("Time Display: Local" if self._show_local_time else "Time Display: UTC")

    def _update_time_toggle_style(self, theme: Optional[Dict[str, str]] = None) -> None:
        if theme is None:
            theme = resolve_theme(self.settings)
        role = "info" if self._current_time_mode() == "UTC" else "muted"
        self.time_toggle_btn.setStyleSheet(button_style(role, theme))

    def _toggle_time_view(self) -> None:
        mode = self._current_time_mode()
        self._time_mode_override = "UTC" if mode == "LOCAL" else "LOCAL"
        if (self._time_mode_override == "LOCAL" and self._show_local_time) or (
            self._time_mode_override == "UTC" and not self._show_local_time
        ):
            self._time_mode_override = None
        self._update_time_ui()
        self._populate_messages_table(force=True)

    def _populate_messages_table(self, force: bool = False):
        with perf_span(
            "messages.populate_table",
            settings=self.settings,
            meta={"force": bool(force)},
            min_ms=5.0,
        ):
            if not self._has_active_view or not self._app_active:
                self._deferred_refresh = True
                log.info(
                    "MESSAGES|table_refresh_deferred active_view=%s app_active=%s",
                    self._has_active_view,
                    self._app_active,
                )
                return
            if self._freeze_messages_table and not force:
                self._deferred_refresh = True
                log.debug("MessageViewer: table refresh deferred (freeze active)")
                return
            self._deferred_refresh = False
            if self._projection_primary_enabled:
                self._load_projected_messages_into_table(force=force)
                return
            self._start_rows_build(force=force)

    def _load_projected_messages_into_table(self, *, force: bool = False) -> bool:
        """Compatibility seam: normal projection rendering is always asynchronous."""

        if not bool(getattr(self, "_projection_primary_enabled", False)):
            return False
        self._request_projected_message_query(force=force)
        return True

    def _projected_query_parameters(self) -> Dict[str, object]:
        ids = getattr(self, "_ops_traffic_message_ids", None)
        if ids is not None:
            return {"message_ids": ids}
        source_families = self._projected_source_families_for_current_scope()
        minimum_age, maximum_age = _core_age_filter_bounds(
            self.received_filter.currentData() if hasattr(self, "received_filter") else 0
        )
        now_ts = time.time()
        params: Dict[str, object] = {
            "source_families": source_families,
            "received_after_ts": now_ts - maximum_age if maximum_age > 0 else 0.0,
            "received_before_ts": now_ts - minimum_age if minimum_age > 0 else 0.0,
            "search_text": (self.rcv_search.text() if hasattr(self, "rcv_search") else "").strip(),
        }
        focus = str(getattr(self, "_inbox_focus", "all") or "all").strip().lower()
        if focus == "new":
            params["statuses"] = ("NEW", "UNREAD")
        status = self.status_filter.currentText() if hasattr(self, "status_filter") else ""
        if status not in {"", "Status...", "Action Needed"}:
            if focus == "new":
                params["statuses"] = (status,) if status.upper() in {"NEW", "UNREAD"} else ("__NONE__",)
            else:
                params["status"] = status
        # Parent/family selection must be expanded before the bounded indexed
        # query.  Expanding only in the later in-memory predicate loses child
        # group rows before they can be evaluated.
        groups = self._expanded_selected_message_groups()
        if groups:
            params["group_names"] = tuple(sorted(groups))
        from_call = self.from_filter.currentText() if hasattr(self, "from_filter") else ""
        to_call = self.to_filter.currentText() if hasattr(self, "to_filter") else ""
        if from_call:
            params["from_call"] = from_call
        if to_call:
            params["to_call"] = to_call
        type_value = self.type_filter.currentText() if hasattr(self, "type_filter") else ""
        type_sources = {
            "CommStat": {"commstat"},
            "Spotter": {"spotter"},
            "JS8Call": {"js8"},
            "FLMSG/FLAMP": {"flmsg", "flamp"},
            "SitRep": {"sitrep"},
            "VarAC": {"varac"},
        }
        if type_value in type_sources:
            wanted = type_sources[type_value]
            current = set(source_families)
            narrowed = wanted if not current else current.intersection(wanted)
            params["source_families"] = tuple(sorted(narrowed)) if narrowed else ("__none__",)
        elif type_value not in {"", "MSG Type..."} and not type_value.startswith("SitRep/"):
            params["message_type"] = type_value
        return params

    def _request_projected_message_query(self, *, force: bool = False, delay_ms: int | None = None) -> None:
        if getattr(self, "_is_shutting_down", False) or not self._projection_primary_enabled:
            return
        self._projected_query_request_id += 1
        if bool(getattr(self, "_traffic_navigation_pending", False)):
            self._traffic_loading_request_id = self._projected_query_request_id
        if not self._has_active_view or not self._app_active:
            # Hidden/minimized views do not render. Multiple invalidations are
            # collapsed into the one activation query, bounded by the declared
            # hidden coalescing policy rather than periodic table work.
            self._projected_query_pending = True
            self._projected_query_pending_force = bool(self._projected_query_pending_force or force)
            self._deferred_refresh = True
            return
        if self._qt_thread_running(self._projected_query_thread):
            self._projected_query_pending = True
            self._projected_query_pending_force = bool(self._projected_query_pending_force or force)
            return
        if self._projected_query_timer.isActive() and not force:
            # The already-scheduled query snapshots the latest controls and
            # request id when it starts, so repeated invalidations collapse
            # without extending the operator-visible latency window.
            return
        if delay_ms is None:
            delay_ms = 0 if force else min(250, MESSAGE_PROJECTION_VISIBLE_COALESCE_MS)
        self._projected_query_timer.start(max(0, min(int(delay_ms), MESSAGE_PROJECTION_VISIBLE_COALESCE_MS)))

    def _start_projected_message_query(self) -> None:
        if self._is_shutting_down or not self._projection_primary_enabled:
            return
        if not self._has_active_view or not self._app_active:
            self._projected_query_pending = True
            self._deferred_refresh = True
            return
        if self._qt_thread_running(self._projected_query_thread):
            self._projected_query_pending = True
            return
        db_path = self._db_path()
        if db_path is None or not db_path.exists():
            self._finish_traffic_navigation("Messages database is unavailable.")
            return
        request_id = int(self._projected_query_request_id)
        scope_key = self._projected_scope_key()
        self._projected_query_pending = False
        self._projected_query_pending_force = False
        selected_groups = self._selected_message_groups()
        self._projected_query_thread = QThread(self)
        self._projected_query_worker = _ProjectedMessageQueryWorker(
            db_path=str(db_path),
            request_id=request_id,
            scope_key=scope_key,
            query=self._projected_query_parameters(),
            traffic_context_inputs=self._traffic_context_inputs(),
            filter_settings=self._projection_filter_settings(),
            selected_groups=tuple(sorted(selected_groups)) if selected_groups is not None else None,
        )
        self._projected_query_worker.moveToThread(self._projected_query_thread)
        self._projected_query_thread.started.connect(self._projected_query_worker.run)
        self._projected_query_worker.finished.connect(self._on_projected_message_query_finished)
        self._projected_query_worker.finished.connect(self._projected_query_thread.quit)
        self._projected_query_worker.finished.connect(self._projected_query_worker.deleteLater)
        self._projected_query_thread.finished.connect(self._on_projected_message_query_thread_finished)
        self._projected_query_thread.finished.connect(self._projected_query_thread.deleteLater)
        self._projected_query_thread.start()

    def _on_projected_message_query_finished(self, payload: object) -> None:
        data = payload if isinstance(payload, dict) else {}
        request_id = int(data.get("request_id", 0) or 0)
        if request_id != int(self._projected_query_request_id):
            log.debug("MessageViewer: discarded stale projection query %d", request_id)
            return
        error = str(data.get("error", "") or "")
        if error:
            log.warning("MessageViewer: projection query failed: %s", error)
            self._finish_traffic_navigation("Could not load traffic. Refresh to retry.")
            return
        if not self._has_active_view or not self._app_active or self._is_shutting_down:
            self._projected_query_pending = True
            self._deferred_refresh = True
            return
        generation = int(data.get("generation", 0) or 0)
        if generation and generation < int(self._active_projection_generation or 0):
            log.debug("MessageViewer: discarded projection generation %d", generation)
            self._finish_traffic_navigation("Traffic changed while loading. Refresh to retry.")
            return
        try:
            apply_started = time.perf_counter()
            inputs = data.get("traffic_context_inputs")
            filter_settings = data.get("filter_settings")
            if (
                inputs is not None and inputs != self._traffic_context_inputs()
                or filter_settings is not None and filter_settings != self._projection_filter_settings()
            ):
                self._request_projected_message_query(force=True)
                return
            if isinstance(data.get("commstat_groups"), CommStatGroupState):
                self._projected_commstat_groups = data["commstat_groups"]
            if isinstance(data.get("group_families"), dict):
                self._projected_group_families = data["group_families"]
            context = data.get("traffic_context")
            if isinstance(context, OperatorTrafficContext):
                self._projected_traffic_context = context
                self._projected_traffic_context_inputs = data.get("traffic_context_inputs")
            db_rows = data.get("rows", [])
            refs = data.get("refs", {})
            rows = self._projected_rows_from_mappings(
                db_rows if isinstance(db_rows, list) else [],
                refs if isinstance(refs, dict) else {},
            )
            self._install_projected_action_state(
                rows,
                data.get("bbs_published_counts", {}),
            )
            focus_counts = data.get("focus_counts", data.get("focus_unread_counts"))
            focus_counts_generation = int(data.get("focus_counts_generation", generation) or 0)
            if (
                isinstance(focus_counts, Mapping)
                and (
                    not focus_counts_generation
                    or focus_counts_generation >= int(getattr(self, "_focus_counts_generation", 0) or 0)
                )
            ):
                focus_keys = [key for key, _label, _tip in self._inbox_focus_options()]
                self._inbox_focus_unread_counts = {
                    key: max(0, int(focus_counts.get(key, 0) or 0))
                    for key in focus_keys
                }
                self._focus_counts_generation = focus_counts_generation
                self._projection_focus_counts_available = True
                if hasattr(self, "_inbox_focus_buttons"):
                    self._sync_inbox_focus_buttons()
            self._projected_table_loading = True
            try:
                self._message_rows = rows
                summary = data.get("traffic_summary")
                if isinstance(summary, TrafficActionSummary):
                    available_ids = {str(getattr(row.payload, "message_id", "")) for row in rows}
                    summary = replace(summary, items=tuple(item for item in summary.items if item.stable_id in available_ids))
                self._ops_traffic_summary = summary
                self._last_projection_render_ts = time.time()
                self._projected_scope_load_key = tuple(data.get("scope_key", ()) or ())
                self._projected_total_count = int(data.get("total_count", len(rows)) or 0)
                self._active_projection_generation = generation
                with perf_span("messages.refresh_filters.projected", settings=self.settings, min_ms=5.0):
                    if getattr(self, "_ops_traffic_message_ids", None) is None:
                        self._refresh_message_filters(rows)
                with perf_span("messages.apply_filters.projected", settings=self.settings, min_ms=5.0):
                    self._apply_message_filters(recover_empty_stale_scope=True)
            finally:
                self._projected_table_loading = False
            elapsed_ms = float(data.get("elapsed_ms", 0.0) or 0.0)
            emit_span(
                "messages.model_query",
                elapsed_ms,
                settings=self.settings,
                meta={"rows": len(rows), "total": self._projected_total_count, "generation": generation},
                min_ms=5.0,
            )
            emit_span(
                "messages.model_apply",
                (time.perf_counter() - apply_started) * 1000.0,
                settings=self.settings,
                meta={
                    "rows": len(rows),
                    "total": self._projected_total_count,
                    "generation": generation,
                },
                level="debug",
            )
            self._finish_traffic_navigation()
            log.info(
                "MESSAGES|projected_table_loaded rows=%d total=%d generation=%d scope=%s",
                len(rows),
                self._projected_total_count,
                generation,
                self._active_message_scope_summary(),
            )
        except Exception:
            log.exception("MessageViewer: could not apply projected traffic")
            self._finish_traffic_navigation("Could not display traffic. Refresh to retry.")

    def _finish_traffic_navigation(self, error: str = "") -> None:
        if not bool(getattr(self, "_traffic_navigation_pending", False)):
            return
        if int(getattr(self, "_traffic_loading_request_id", -1)) != int(self._projected_query_request_id):
            return
        self._traffic_navigation_pending = False
        self._set_loading(bool(error), error or "")
        if error and self._loading_progress is not None:
            self._loading_progress.setVisible(False)
        emit_span(
            "messages.traffic_navigation_complete",
            (time.perf_counter() - self._traffic_loading_started) * 1000.0,
            settings=self.settings,
            meta={"bucket": self._traffic_loading_bucket, "failed": bool(error)},
            min_ms=0.0,
        )

    def _install_projected_action_state(
        self,
        rows: Sequence[UnifiedMessage],
        bbs_published_counts: object,
    ) -> None:
        """Install worker-produced action state without querying during paint."""

        counts = bbs_published_counts if isinstance(bbs_published_counts, Mapping) else {}
        known = getattr(self, "_reader_bbs_known_counts", {})
        for row in list(rows)[:200]:
            rec = self._file_record_for_message_row(row, allow_detail_lookup=False)
            key = self._bbs_copy_session_key_for_record(rec)
            if key is None:
                continue
            known[key] = max(0, int(counts.get(key[0], 0) or 0))
        self._reader_bbs_known_counts = known

    def _on_projected_message_query_thread_finished(self) -> None:
        self._retain_finished_worker_refs(self._projected_query_thread, self._projected_query_worker)
        self._projected_query_thread = None
        self._projected_query_worker = None
        if self._projected_query_pending and not self._is_shutting_down:
            force = bool(self._projected_query_pending_force)
            self._projected_query_pending = False
            self._projected_query_pending_force = False
            self._request_projected_message_query(force=force)

    def _projected_rows_from_mappings(
        self,
        db_rows: Sequence[Mapping[str, object]],
        refs_by_message: Mapping[str, Sequence[Mapping[str, object]]],
    ) -> List[UnifiedMessage]:
        rows: List[UnifiedMessage] = []
        for db_row in list(db_rows)[:200]:
            try:
                message_id = str(db_row["message_id"] or "")
                payload = projected_payload_from_row(
                    db_row,
                    external_refs=tuple(refs_by_message.get(message_id, ())),
                )
                received_ts = float(db_row["received_ts"] or db_row["event_ts"] or 0.0)
                event_utc = str(db_row["received_utc"] or db_row["event_utc"] or "")
                status = str(db_row["status"] or "INFO").strip().upper()
                row = UnifiedMessage(
                    msg_type=str(db_row["message_type"] or payload.message_type or payload.source_label or "Message"),
                    status=status,
                    from_call=str(db_row["from_call"] or ""),
                    to_call=str(db_row["to_call"] or ""),
                    rcv_ts=received_ts,
                    rcv_display=self._format_rcv_display(received_ts, event_utc),
                    title=str(db_row["summary"] or db_row["subject"] or payload.body_preview or ""),
                    origin=str(db_row["source_family"] or payload.source_family or "message"),
                    payload=payload,
                    search_text=str(db_row["search_text"] or ""),
                    topics=payload.topics,
                    actionable=bool(db_row["actionable"] or db_row["operator_attention"]),
                    display_type=str(db_row["display_type"] or payload.display_type or ""),
                )
                row.summary = message_summary_from_row(row)
                rows.append(row)
            except Exception as exc:
                log.debug("MessageViewer: skipped projected message row: %s", exc)
        return rows

    def _load_projected_message_rows(self, *, limit: int = 200) -> List[UnifiedMessage]:
        """Bounded synchronous compatibility helper; normal UI paths use the worker."""

        db_path = self._db_path()
        if db_path is None or not db_path.exists():
            return []
        try:
            page = query_projected_message_page(
                db_path,
                page_size=min(int(limit or 200), 200),
                **self._projected_query_parameters(),
            )
            db_rows = page.rows
        except Exception as exc:
            log.debug("MessageViewer: failed to load projected messages: %s", exc)
            return []
        try:
            refs_by_message = load_projected_external_refs_for_messages(
                db_path,
                [str(row["message_id"] or "") for row in db_rows],
            )
        except Exception as exc:
            log.debug("MessageViewer: failed to load projected refs: %s", exc)
            refs_by_message = {}
        return self._projected_rows_from_mappings(db_rows, refs_by_message)

    def _spotter_msg_auth_state_for_message(
        self,
        msg: SpotterMessage,
        keys_by_scope: Optional[Dict[tuple[str, str], List[MsgAuthKey]]] = None,
    ) -> Dict[str, object]:
        msg_id = int(getattr(msg, "spotter_id", 0) or 0)
        raw_text = str(getattr(msg, "raw_text", "") or "").strip()
        if msg_id <= 0 or not raw_text:
            return {}
        from_call = str(getattr(msg, "from_call", "") or "").strip().upper()
        target = str(getattr(msg, "to_call", "") or "").strip().upper()
        try:
            if keys_by_scope is None:
                keys = load_msg_auth_verification_keys(group_name=target, callsign=from_call)
            else:
                group = normalize_group_name(target)
                keys = list(keys_by_scope.get((group, from_call), [])) + list(keys_by_scope.get((group, "*"), []))
            verification = verify_js8_text(from_call, target, raw_text, keys=keys)
        except Exception as exc:
            return {
                "status": "error",
                "detail": f"MsgAuth: Verification error ({exc})",
                "trusted": False,
            }
        state = str(verification.state or "").strip().lower()
        if state == "verified":
            label = str(verification.key_label or "").strip()
            detail = "MsgAuth: Valid"
            if label:
                detail += f" ({label})"
            if verification.decoded_datecode:
                detail += f" | Date code {verification.decoded_datecode}"
            return {"status": "valid", "detail": detail, "trusted": True}
        if state == "unsigned":
            # Unsigned Spotter traffic stays visually quiet by design; signed good traffic gets the green check.
            return {}
        if state == "no_key":
            return {
                "status": "",
                "detail": f"MsgAuth: CRC present, but no enabled key for {target or 'group'} / {from_call or 'callsign'}.",
                "trusted": False,
            }
        if state in {"failed", "invalid"}:
            return {
                "status": "invalid",
                "detail": f"MsgAuth: {verification.detail or 'Checksum did not verify.'}",
                "trusted": False,
            }
        return {
            "status": "",
            "detail": f"MsgAuth: {verification.detail or state or 'Not verified.'}",
            "trusted": False,
        }

    def _enabled_msg_auth_keys_by_scope(self) -> Dict[tuple[str, str], List[MsgAuthKey]]:
        grouped: Dict[tuple[str, str], List[MsgAuthKey]] = {}
        try:
            rows = list_msg_auth_key_rows(enabled_only=True)
        except Exception as exc:
            log.debug("MessageViewer: failed to load MsgAuth key rows: %s", exc)
            return grouped
        for row in rows:
            if not isinstance(row, dict):
                continue
            group = normalize_group_name(row.get("group_name", ""))
            callsign = str(row.get("callsign", "") or "").strip().upper()
            key_text = str(row.get("key_text", "") or "").strip()
            key_scope = str(row.get("key_scope", "") or "").strip().lower()
            if key_scope not in {MSG_AUTH_SCOPE_VERIFY_SENDER, MSG_AUTH_SCOPE_VERIFY_ANY}:
                continue
            if not group or not callsign or not key_text:
                continue
            display_call = "Any Sender" if callsign == "*" else callsign
            label = str(row.get("label", "") or "").strip() or f"{group} / {display_call}"
            grouped.setdefault((group, callsign), []).append(
                MsgAuthKey(label=label, key=key_text, enabled=bool(row.get("enabled", True)))
            )
        return grouped

    def _spotter_msg_auth_state_map(self) -> Dict[int, Dict[str, object]]:
        out: Dict[int, Dict[str, object]] = {}
        keys_by_scope = self._enabled_msg_auth_keys_by_scope()
        for msg in self.spotter_messages:
            try:
                msg_id = int(getattr(msg, "spotter_id", 0) or 0)
            except Exception:
                msg_id = 0
            if msg_id <= 0:
                continue
            state = self._spotter_msg_auth_state_for_message(msg, keys_by_scope=keys_by_scope)
            if state:
                out[msg_id] = state
        return out

    @staticmethod
    def _norm_expect_group(value: object) -> str:
        text = str(value or "").strip().upper()
        if text and not text.startswith("@"):
            text = f"@{text}"
        return text

    def _expect_audit_rows_cached(self) -> List[Dict[str, Any]]:
        now = time.time()
        cached_ts, cached_rows = getattr(self, "_expect_request_audit_cache", (0.0, []))
        if cached_rows and (now - float(cached_ts or 0.0)) < 5.0:
            return [dict(row) for row in cached_rows]
        try:
            rows = list_expect_runtime_audit(limit=300)
        except Exception as exc:
            log.debug("MessageViewer: failed to load Expect request audit: %s", exc)
            rows = []
        self._expect_request_audit_cache = (now, [dict(row) for row in rows])
        return rows

    def _spotter_expect_state_for_message(self, msg: SpotterMessage) -> Dict[str, object]:
        form_key = str(getattr(msg, "msg_type", "") or "").strip().upper()
        if form_key and form_key.startswith("F!") and len(form_key) > 2:
            pass
        elif form_key:
            form_key = f"F!{form_key}"
        from_call = str(getattr(msg, "from_call", "") or "").strip().upper()
        target_group = self._norm_expect_group(getattr(msg, "to_call", ""))
        source_radio = str(getattr(msg, "source_radio_id", "") or "").strip()
        source_js8 = str(getattr(msg, "js8_instance_id", "") or "").strip()
        if not form_key or not from_call:
            return {}
        for row in self._expect_audit_rows_cached():
            if str(row.get("expect_key", "") or "").strip().upper() != form_key:
                continue
            if str(row.get("requesting_callsign", "") or "").strip().upper() != from_call:
                continue
            audit_group = self._norm_expect_group(row.get("target_group", ""))
            if target_group and audit_group and audit_group != target_group:
                continue
            audit_radio = str(row.get("source_radio_id", "") or "").strip()
            audit_js8 = str(row.get("source_js8_instance_id", "") or "").strip()
            if source_radio and audit_radio and audit_radio != source_radio:
                continue
            if source_js8 and audit_js8 and audit_js8 != source_js8:
                continue
            decision = str(row.get("decision", "") or "").strip()
            reason = str(row.get("reason", "") or "").strip()
            if not decision and not reason:
                continue
            detail = f"Expect: {decision}"
            if reason:
                detail += f" - {reason}"
            return {
                "decision": decision,
                "detail": detail,
                "expect_entry_id": int(row.get("expect_entry_id", 0) or 0),
            }
        return {}

    def _spotter_expect_state_map(self) -> Dict[int, Dict[str, object]]:
        out: Dict[int, Dict[str, object]] = {}
        for msg in self.spotter_messages:
            try:
                msg_id = int(getattr(msg, "spotter_id", 0) or 0)
            except Exception:
                msg_id = 0
            if msg_id <= 0:
                continue
            state = self._spotter_expect_state_for_message(msg)
            if state:
                out[msg_id] = state
        return out

    def _snapshot_for_rows_build(self) -> Dict[str, object]:
        form_ids: set[str] = set()
        for msg in self.js8_messages:
            if isinstance(msg.msg_type, str) and msg.msg_type.startswith("F!"):
                form_ids.add(msg.msg_type[2:].strip())
        for msg in self.spotter_messages:
            mtype = str(msg.msg_type or "")
            if mtype.startswith("F!"):
                form_ids.add(mtype[2:].strip())
        form_titles: Dict[str, str] = {}
        for form_id in sorted({f for f in form_ids if f}):
            form_titles[form_id] = self._load_form_title(form_id)
        message_form_codes = self._form_codes_for_flag("messages")
        alert_form_codes = self._form_codes_for_flag("alert")
        signature_map: Dict[tuple, Dict[str, object]] = {}
        if self._is_any_auth_verification_enabled():
            current_sig_keys: set[tuple] = set()
            for origin in ("flamp", "varac", "bbs"):
                for rec in self.files.get(origin, []):
                    if not self._is_auth_verifiable_file(rec):
                        continue
                    current_sig_keys.add(self._signature_cache_key(rec))
            for key in current_sig_keys:
                state = self._signature_state_map.get(key)
                if not isinstance(key, tuple) or len(key) != 4:
                    continue
                if not isinstance(state, FileSignatureState):
                    continue
                ui_state, ui_detail, ui_trusted = self._derive_auth_ui(state)
                signature_map[key] = {
                    "status": ui_state,
                    "detail": ui_detail,
                    "trusted": ui_trusted,
                }
        current_files = {k: list(v) for k, v in self.files.items()}
        file_metadata_map = self._load_message_file_metadata_map(current_files)
        cached_files, cached_metadata_map = self._load_existing_cached_message_files()
        files_for_rows = self._merge_file_record_sets(current_files, cached_files)
        file_metadata_map.update(cached_metadata_map)
        return {
            "js8_messages": list(self.js8_messages),
            "spotter_messages": list(self.spotter_messages),
            "varac_messages": list(self.varac_messages),
            "sitrep_messages": list(self.sitrep_messages),
            "commstat_messages": list(self.commstat_messages),
            "observation_messages": list(self.observation_messages),
            "files": files_for_rows,
            "file_metadata_map": file_metadata_map,
            "read_state_map": dict(self._read_state_map),
            "signature_state_map": signature_map,
            "spotter_auth_state_map": self._spotter_msg_auth_state_map(),
            "spotter_expect_state_map": self._spotter_expect_state_map(),
            "sender_cache_seed": dict(self._sender_cache),
            "form_titles": form_titles,
            "custom_forms_path": str(self._resolve_custom_forms_path() or ""),
            "message_form_codes": message_form_codes,
            "alert_form_codes": alert_form_codes,
            "show_local_time": self._current_time_mode() != "UTC",
            "tz_name": str(self.settings.get("timezone", "UTC") or "UTC"),
            "sitrep_dedupe_enabled": self._is_truthy(
                self.settings.get("sitrep_messages_dedupe_enabled", True), True
            ),
            "sitrep_show_raw_duplicates": self._is_truthy(
                self.settings.get("sitrep_messages_show_raw_duplicates", False), False
            ),
        }

    def _start_rows_build(self, force: bool = False) -> None:
        if self._is_shutting_down:
            return
        source_fp = self._message_sources_fingerprint()
        if self._rows_build_thread:
            try:
                if self._rows_build_thread.isRunning():
                    if source_fp != getattr(self, "_rows_build_active_fp", None):
                        self._rows_build_pending = True
                        self._rows_build_pending_force = bool(self._rows_build_pending_force or force)
                    return
            except RuntimeError:
                self._rows_build_thread = None
                self._rows_build_worker = None
        snapshot = self._snapshot_for_rows_build()
        self._rows_build_generation += 1
        generation = int(self._rows_build_generation)
        self._rows_build_pending = False
        self._rows_build_pending_force = False
        self._rows_build_active_fp = source_fp
        self._rows_build_thread = QThread(self)
        self._rows_build_worker = _RowsBuildWorker(
            js8_messages=snapshot.get("js8_messages", []),  # type: ignore[arg-type]
            spotter_messages=snapshot.get("spotter_messages", []),  # type: ignore[arg-type]
            varac_messages=snapshot.get("varac_messages", []),  # type: ignore[arg-type]
            sitrep_messages=snapshot.get("sitrep_messages", []),  # type: ignore[arg-type]
            commstat_messages=snapshot.get("commstat_messages", []),  # type: ignore[arg-type]
            observation_messages=snapshot.get("observation_messages", []),  # type: ignore[arg-type]
            files=snapshot.get("files", {}),  # type: ignore[arg-type]
            file_metadata_map=snapshot.get("file_metadata_map", {}),  # type: ignore[arg-type]
            read_state_map=snapshot.get("read_state_map", {}),  # type: ignore[arg-type]
            signature_state_map=snapshot.get("signature_state_map", {}),  # type: ignore[arg-type]
            spotter_auth_state_map=snapshot.get("spotter_auth_state_map", {}),  # type: ignore[arg-type]
            spotter_expect_state_map=snapshot.get("spotter_expect_state_map", {}),  # type: ignore[arg-type]
            sender_cache_seed=snapshot.get("sender_cache_seed", {}),  # type: ignore[arg-type]
            form_titles=snapshot.get("form_titles", {}),  # type: ignore[arg-type]
            custom_forms_path=str(snapshot.get("custom_forms_path", "") or ""),
            message_form_codes=snapshot.get("message_form_codes"),  # type: ignore[arg-type]
            alert_form_codes=snapshot.get("alert_form_codes"),  # type: ignore[arg-type]
            show_local_time=bool(snapshot.get("show_local_time", False)),
            tz_name=str(snapshot.get("tz_name", "UTC") or "UTC"),
            sitrep_dedupe_enabled=bool(snapshot.get("sitrep_dedupe_enabled", True)),
            sitrep_show_raw_duplicates=bool(snapshot.get("sitrep_show_raw_duplicates", False)),
            force=bool(force),
            generation=generation,
        )
        self._rows_build_worker.moveToThread(self._rows_build_thread)
        self._rows_build_thread.started.connect(self._rows_build_worker.run)
        self._rows_build_worker.finished.connect(self._on_rows_build_finished)
        self._rows_build_worker.finished.connect(self._rows_build_thread.quit)
        self._rows_build_worker.finished.connect(self._rows_build_worker.deleteLater)
        self._rows_build_thread.finished.connect(self._on_rows_build_thread_finished)
        self._rows_build_thread.finished.connect(self._rows_build_thread.deleteLater)
        self._rows_build_thread.start()
        self._emit_message_refresh_busy()

    def _on_rows_build_thread_finished(self) -> None:
        self._retain_finished_worker_refs(self._rows_build_thread, self._rows_build_worker)
        self._rows_build_thread = None
        self._rows_build_worker = None
        self._rows_build_active_fp = None
        self._emit_message_refresh_busy()
        if self._rows_build_pending and not self._is_shutting_down:
            pending_force = bool(self._rows_build_pending_force)
            self._rows_build_pending = False
            self._rows_build_pending_force = False
            QTimer.singleShot(250, lambda force=pending_force: self._start_rows_build(force=force))

    def _on_rows_build_finished(self, payload: object) -> None:
        if self._is_shutting_down:
            return
        data = payload if isinstance(payload, dict) else {}
        try:
            generation = int(data.get("generation", 0) or 0)
        except Exception:
            generation = 0
        if generation and generation != self._rows_build_generation:
            return
        rows = data.get("rows", [])
        if not isinstance(rows, list):
            rows = []
        if self._locally_deleted_row_keys:
            rows = _core_filter_rows_excluding_identities(rows, self._locally_deleted_row_keys)
        self._retag_bbs_archive_rows(rows)
        self._last_source_rows_build_ts = time.time()
        projection_render_active = bool(
            self._projection_primary_enabled
            and float(getattr(self, "_last_projection_render_ts", 0.0) or 0.0) > 0.0
        )
        self._message_rows = rows
        self._save_message_file_metadata_from_rows(rows)
        # Projection-primary mode is owned by the application coordinator.
        # Re-projecting this presentation snapshot here creates a second
        # identity lane (notably across file-path identity upgrades) and can
        # duplicate one physical FLMSG/FLAMP file in the Inbox. Keep the legacy
        # writer only for the explicit projection-disabled compatibility mode.
        if not self._projection_primary_enabled:
            self._start_message_projection_write(rows, force=bool(data.get("force", False)))
        sender_updates = data.get("sender_cache_updates", {})
        if isinstance(sender_updates, dict):
            self._sender_cache.update(sender_updates)
            self._prune_cache(self._sender_cache, self._cache_max_sender_entries)
        try:
            build_ms = float(data.get("elapsed_ms", 0.0) or 0.0)
        except Exception:
            build_ms = 0.0
        if build_ms > 0:
            origin_counts: dict[str, int] = {}
            for row in rows:
                origin = str(getattr(row, "origin", "") or "unknown").strip().lower() or "unknown"
                origin_counts[origin] = origin_counts.get(origin, 0) + 1
            emit_span(
                "messages.build_rows",
                build_ms,
                settings=self.settings,
                meta={
                    "rows": len(rows),
                    "origins": origin_counts,
                    "force": bool(data.get("force", False)),
                    "file_metadata_hits": int(data.get("file_metadata_hits", 0) or 0),
                    "file_parse_count": int(data.get("file_parse_count", 0) or 0),
                },
                min_ms=5.0,
            )
        if projection_render_active:
            log.debug(
                "MessageViewer: built %d source rows for projection refresh; keeping projection-primary table",
                len(rows),
            )
            return
        if self._freeze_messages_table and not bool(data.get("force", False)):
            self._deferred_refresh = True
            return
        with perf_span("messages.refresh_filters", settings=self.settings, min_ms=5.0):
            self._refresh_message_filters(rows)
        with perf_span("messages.apply_filters", settings=self.settings, min_ms=5.0):
            self._apply_message_filters()
        self._start_signature_verification(force=bool(data.get("force", False)))
        log.debug("MessageViewer: built %d unified messages", len(rows))

    def _start_message_projection_write(self, rows: Sequence[UnifiedMessage], *, force: bool = False) -> None:
        if self._is_shutting_down:
            return
        db_path = self._db_path()
        if db_path is None or not rows:
            return
        if self._qt_thread_running(getattr(self, "_projection_write_thread", None)):
            self._projection_write_pending_rows = list(rows)
            return
        self._projection_write_generation += 1
        generation = int(self._projection_write_generation)
        self._projection_write_pending_rows = []
        self._projection_write_thread = QThread(self)
        self._projection_write_worker = _MessageProjectionWriteWorker(
            db_path=str(db_path),
            rows=list(rows),
            generation=generation,
            force=force,
        )
        self._projection_write_worker.moveToThread(self._projection_write_thread)
        self._projection_write_thread.started.connect(self._projection_write_worker.run)
        self._projection_write_worker.finished.connect(self._on_message_projection_write_finished)
        self._projection_write_worker.finished.connect(self._projection_write_thread.quit)
        self._projection_write_worker.finished.connect(self._projection_write_worker.deleteLater)
        self._projection_write_thread.finished.connect(self._on_message_projection_write_thread_finished)
        self._projection_write_thread.finished.connect(self._projection_write_thread.deleteLater)
        self._projection_write_thread.start()

    def _on_message_projection_write_finished(self, payload: object) -> None:
        data = payload if isinstance(payload, dict) else {}
        error = str(data.get("error", "") or "")
        if error:
            log.warning("MessageViewer: message projection write failed: %s", error)
            return
        try:
            elapsed_ms = float(data.get("elapsed_ms", 0.0) or 0.0)
        except Exception:
            elapsed_ms = 0.0
        if elapsed_ms > 0:
            emit_span(
                "messages.project_rows",
                elapsed_ms,
                settings=self.settings,
                meta={
                    "rows": int(data.get("rows", 0) or 0),
                    "projected": int(data.get("projected", 0) or 0),
                },
                min_ms=5.0,
            )
        projected_count = int(data.get("projected", 0) or 0)
        if self._projection_primary_enabled and not self._is_shutting_down and (
            projected_count > 0 or bool(data.get("force", False))
        ):
            self._request_projected_message_query(
                force=bool(data.get("force", False)),
                delay_ms=0 if bool(data.get("force", False)) else MESSAGE_PROJECTION_VISIBLE_COALESCE_MS,
            )

    def _on_message_projection_write_thread_finished(self) -> None:
        self._retain_finished_worker_refs(self._projection_write_thread, self._projection_write_worker)
        self._projection_write_thread = None
        self._projection_write_worker = None
        if self._projection_write_pending_rows and not self._is_shutting_down:
            pending = list(self._projection_write_pending_rows)
            self._projection_write_pending_rows = []
            QTimer.singleShot(100, lambda rows=pending: self._start_message_projection_write(rows))

    def _request_application_projection_catchup(self, *, reason: str) -> bool:
        """Ask the application-owned coordinator to process durable work.

        The Inbox owns presentation queries only.  It never creates a second
        coordinator or drains source history as a consequence of tab activity.
        """

        if getattr(self, "_is_shutting_down", False):
            return False
        host = self.parent()
        request = getattr(host, "request_message_projection_catchup", None)
        if not callable(request):
            return False
        try:
            request(reason=str(reason or "messages"))
            return True
        except Exception as exc:
            log.debug("MessageViewer: application projection request failed: %s", exc)
            return False

    def _start_native_file_projection_write(
        self,
        records: Dict[str, List[FileRecord]],
        *,
        force: bool = False,
    ) -> None:
        if self._is_shutting_down:
            return
        db_path = self._db_path()
        if db_path is None:
            return
        if self._qt_thread_running(getattr(self, "_native_file_projection_thread", None)):
            self._native_file_projection_pending_records = {str(k or ""): list(v or []) for k, v in (records or {}).items()}
            self._native_file_projection_pending_force = bool(self._native_file_projection_pending_force or force)
            return
        self._native_file_projection_generation = int(getattr(self, "_native_file_projection_generation", 0) or 0) + 1
        generation = int(self._native_file_projection_generation)
        self._native_file_projection_pending_records = {}
        self._native_file_projection_pending_force = False
        self._native_file_projection_thread = QThread(self)
        self._native_file_projection_worker = _NativeFileProjectionWorker(
            db_path=str(db_path),
            records={str(k or ""): list(v or []) for k, v in (records or {}).items()},
            generation=generation,
            force=force,
        )
        self._native_file_projection_worker.moveToThread(self._native_file_projection_thread)
        self._native_file_projection_thread.started.connect(self._native_file_projection_worker.run)
        self._native_file_projection_worker.finished.connect(self._on_native_file_projection_finished)
        self._native_file_projection_worker.finished.connect(self._native_file_projection_thread.quit)
        self._native_file_projection_worker.finished.connect(self._native_file_projection_worker.deleteLater)
        self._native_file_projection_thread.finished.connect(self._on_native_file_projection_thread_finished)
        self._native_file_projection_thread.finished.connect(self._native_file_projection_thread.deleteLater)
        self._native_file_projection_thread.start()

    def _on_native_file_projection_finished(self, payload: object) -> None:
        data = payload if isinstance(payload, dict) else {}
        error = str(data.get("error", "") or "")
        if error:
            log.warning("MessageViewer: native file projection failed: %s", error)
            return
        try:
            elapsed_ms = float(data.get("elapsed_ms", 0.0) or 0.0)
        except Exception:
            elapsed_ms = 0.0
        if elapsed_ms > 0:
            emit_span(
                "messages.project_native_files",
                elapsed_ms,
                settings=self.settings,
                meta={
                    "projected": int(data.get("projected", 0) or 0),
                    "force": bool(data.get("force", False)),
                },
                min_ms=5.0,
            )
        projected_count = int(data.get("projected", 0) or 0)
        if projected_count > 0:
            self._message_check_status_text = "Messages updated"
            self._update_message_check_status()
        if self._projection_primary_enabled and not self._is_shutting_down and (
            projected_count > 0 or bool(data.get("force", False))
        ):
            self._request_projected_message_query(
                force=bool(data.get("force", False)),
                delay_ms=0 if bool(data.get("force", False)) else MESSAGE_PROJECTION_VISIBLE_COALESCE_MS,
            )

    def _on_native_file_projection_thread_finished(self) -> None:
        self._retain_finished_worker_refs(self._native_file_projection_thread, self._native_file_projection_worker)
        self._native_file_projection_thread = None
        self._native_file_projection_worker = None
        if self._native_file_projection_pending_records and not self._is_shutting_down:
            pending = dict(self._native_file_projection_pending_records)
            pending_force = bool(self._native_file_projection_pending_force)
            self._native_file_projection_pending_records = {}
            self._native_file_projection_pending_force = False
            QTimer.singleShot(
                100,
                lambda records=pending, force=pending_force: self._start_native_file_projection_write(records, force=force),
            )

    def _remember_locally_deleted_row(self, row: UnifiedMessage) -> None:
        key = MessageTableModel._row_key(row)
        if key is not None:
            self._locally_deleted_row_keys.add(key)

    def _remember_locally_deleted_key(self, key: tuple | None) -> None:
        if key is not None:
            self._locally_deleted_row_keys.add(key)

    def _remove_deleted_rows_from_current_view(self, rows: List[UnifiedMessage]) -> None:
        keys = _core_message_row_identity_set(rows)
        if not keys:
            return
        self._message_rows = _core_filter_rows_excluding_identities(self._message_rows, keys)
        self._render_messages_table(_core_filter_rows_excluding_identities(self._messages_model.rows(), keys))

    def _refresh_message_filters(self, rows: List[UnifiedMessage]) -> None:
        type_vals = sorted({r.msg_type for r in rows if r.msg_type})
        status_vals = sorted({r.status for r in rows if r.status})
        from_vals = sorted({r.from_call for r in rows if r.from_call})
        to_vals = sorted({r.to_call for r in rows if r.to_call})
        spotter_forms = sorted({t for t in type_vals if normalize_form_code(t)})
        has_commstat = any((r.origin or "").strip().lower() == "commstat" for r in rows)
        has_js8call = any((r.origin or "").strip().lower() == "js8" for r in rows)
        form_types = {
            str(r.msg_type or "").strip()
            for r in rows
            if str(r.msg_type or "").strip() and _core_row_matches_type_filter(r, "FLMSG/FLAMP")
        }
        has_forms = bool(form_types)
        grouped_types = set(spotter_forms)
        if has_commstat:
            grouped_types.update(t for t in type_vals if str(t or "").startswith("CommStat"))
        if has_js8call:
            grouped_types.update(t for t in type_vals if str(t or "").strip().upper() in {"JS8", "JS8 MSG", "JS8CALL"})
        if has_forms:
            grouped_types.update(form_types)
        base_types = sorted([t for t in type_vals if t not in grouped_types])
        sitrep_subtypes = sorted(
            {
                str(getattr(r.payload, "subtype", "") or "").strip().upper()
                for r in rows
                if r.msg_type == "SitRep"
            }
        )
        sitrep_subtypes = [s for s in sitrep_subtypes if s]
        if spotter_forms:
            type_vals = base_types + ["Spotter"]
        else:
            type_vals = base_types
        if has_forms and "FLMSG/FLAMP" not in type_vals:
            type_vals.append("FLMSG/FLAMP")
        if has_commstat and "CommStat" not in type_vals:
            type_vals.append("CommStat")
        if has_js8call and "JS8Call" not in type_vals:
            type_vals.append("JS8Call")
        if sitrep_subtypes:
            if "SitRep" in type_vals:
                idx = type_vals.index("SitRep") + 1
            else:
                type_vals.append("SitRep")
                idx = len(type_vals)
            sitrep_filters = [subtype_filter_label(s) for s in sitrep_subtypes]
            type_vals[idx:idx] = sitrep_filters
        preferred_order = ["FLMSG/FLAMP", "Spotter", "CommStat", "JS8Call", "VarAC", "SitRep"]
        type_vals = sorted(type_vals, key=lambda value: (preferred_order.index(value) if value in preferred_order else 99, value))
        if any(getattr(r.payload, "flag_state", 0) == 1 or bool(getattr(r, "actionable", False)) for r in rows):
            if "Action Needed" not in status_vals:
                status_vals.append("Action Needed")
        self._rebuild_excluded_types_menu(type_vals)

        current_type = self.type_filter.currentText() if hasattr(self, "type_filter") else "ALL"
        current_status = self.status_filter.currentText() if hasattr(self, "status_filter") else "ALL"
        current_from = self.from_filter.currentText() if hasattr(self, "from_filter") else ""
        current_to = self.to_filter.currentText() if hasattr(self, "to_filter") else ""
        if not current_type:
            current_type = "ALL"
        if not current_status:
            current_status = "ALL"
        if not current_from:
            current_from = ""
        if not current_to:
            current_to = ""

        def _sync_combo_options(combo: QComboBox, options: Sequence[str], selected: str) -> bool:
            desired = tuple(str(value) for value in options)
            existing = tuple(combo.itemText(index) for index in range(combo.count()))
            if existing == desired and combo.currentText() == selected:
                return False
            combo.blockSignals(True)
            try:
                combo.clear()
                combo.addItems(list(desired))
                if selected in desired or not desired:
                    combo.setCurrentText(selected)
                elif combo.isEditable():
                    combo.setCurrentText(selected)
                elif desired:
                    combo.setCurrentIndex(0)
            finally:
                combo.blockSignals(False)
            return True

        type_options = ("MSG Type...", *type_vals)
        status_options = ("Status...", *status_vals)
        selected_type = (
            "MSG Type..."
            if not self._filters_initialized
            else current_type if current_type in type_options else type_options[0]
        )
        selected_status = (
            "Status..."
            if not self._filters_initialized
            else current_status if current_status in status_options else status_options[0]
        )
        selected_from = current_from if current_from in from_vals else ""
        selected_to = current_to if current_to in to_vals else ""
        changed = _sync_combo_options(self.type_filter, type_options, selected_type)
        changed = _sync_combo_options(self.status_filter, status_options, selected_status) or changed
        changed = _sync_combo_options(self.from_filter, from_vals, selected_from) or changed
        changed = _sync_combo_options(self.to_filter, to_vals, selected_to) or changed
        self._filters_initialized = True
        fit_signature = (
            tuple(type_options),
            tuple(status_options),
            tuple(from_vals),
            tuple(to_vals),
            tuple(
                (
                    combo.font().toString(),
                    int(combo.width()),
                    float(combo.devicePixelRatioF()),
                    str(combo.style().metaObject().className()),
                )
                for combo in (self.type_filter, self.status_filter, self.from_filter, self.to_filter)
            ),
        )
        if changed or fit_signature != getattr(self, "_message_filter_fit_signature", None):
            for combo in (self.type_filter, self.status_filter, self.from_filter, self.to_filter):
                self._fit_filter_combo_popup(combo)
                fit_combo_box_to_contents(combo)
            self._message_filter_fit_signature = fit_signature
        self._refresh_workspace_filter_options(rows)
        self._update_excluded_types_button_state()

    def _current_inbox_filter_criteria(self, *, now_ts: float | None = None) -> InboxFilterCriteria:
        return InboxFilterCriteria(
            focus=str(getattr(self, "_inbox_focus", "all") or "all").strip().lower(),
            type_sel=self.type_filter.currentText() if hasattr(self, "type_filter") else "MSG Type...",
            status_sel=self.status_filter.currentText() if hasattr(self, "status_filter") else "Status...",
            from_sel=self.from_filter.currentText() if hasattr(self, "from_filter") else "",
            to_sel=self.to_filter.currentText() if hasattr(self, "to_filter") else "",
            age_filter_seconds=self.received_filter.currentData() if hasattr(self, "received_filter") else 0,
            search_query=(self.rcv_search.text() if hasattr(self, "rcv_search") else "").strip().lower(),
            excluded_types=frozenset(
                str(v or "").strip() for v in getattr(self, "_excluded_msg_types", set()) if str(v or "").strip()
            ),
            now_ts=now_ts,
        )

    @staticmethod
    def _ensure_row_search_text(row: UnifiedMessage) -> None:
        if not row.search_text:
            row.search_text = _core_row_search_text(row)

    @staticmethod
    def _message_summary_for_row(row: UnifiedMessage) -> MessageSummary:
        summary = getattr(row, "summary", None)
        if isinstance(summary, MessageSummary):
            return summary
        summary = message_summary_from_row(row)
        row.summary = summary
        return summary

    def _row_matches_intel_filter(self, row: UnifiedMessage) -> bool:
        return row_matches_intel_filters(
            row,
            status_bucket=getattr(self, "_intel_status_filter", ""),
            topic=getattr(self, "_intel_topic_filter", ""),
        )

    def _refresh_intel_filter_bar(self, rows: Sequence[UnifiedMessage]) -> None:
        widget = getattr(self, "message_intel_filter_widget", None)
        layout = getattr(self, "message_intel_filter_layout", None)
        if widget is None or layout is None:
            return
        rollup = build_intel_filter_rollup(
            rows,
            active_status=getattr(self, "_intel_status_filter", ""),
            active_topic=getattr(self, "_intel_topic_filter", ""),
            topic_limit=8,
        )
        chips = list(rollup.status_chips) + list(rollup.topic_chips)
        theme_key = tuple(sorted((str(key), str(value)) for key, value in resolve_theme(self.settings).items()))
        font_key = widget.font().toString()
        chip_key = tuple(
            (
                str(chip.kind or ""),
                str(chip.label or ""),
                int(chip.count),
                bool(chip.active),
                str(chip.status_bucket or ""),
                str(chip.value or ""),
            )
            for chip in chips
        )
        refresh_key = (chip_key, theme_key, font_key)
        if refresh_key == getattr(self, "_intel_filter_bar_refresh_key", None):
            return
        for btn in list(getattr(self, "_intel_filter_buttons", [])):
            layout.removeWidget(btn)
            btn.deleteLater()
        self._intel_filter_buttons = []
        self._intel_filter_bar_refresh_key = refresh_key
        if not chips:
            widget.setVisible(False)
            return
        insert_at = max(1, layout.count() - 1)
        for chip in chips:
            btn = self._intel_filter_button(chip)
            layout.insertWidget(insert_at, btn)
            insert_at += 1
            self._intel_filter_buttons.append(btn)
        widget.setVisible(True)

    def _intel_filter_button(self, chip: IntelFilterChip) -> QPushButton:
        label = f"{chip.label} {chip.count}"
        btn = QPushButton(label)
        btn.setCheckable(True)
        btn.setChecked(bool(chip.active))
        btn.setSizePolicy(QSizePolicy.Minimum, QSizePolicy.Fixed)
        btn.setToolTip(
            f"Show {chip.count} message{'s' if chip.count != 1 else ''} "
            f"with {chip.label} {'status' if chip.kind == 'status' else 'topic'}."
        )
        btn.clicked.connect(
            lambda _checked=False, kind=chip.kind, value=chip.value: self._toggle_intel_filter(kind, value)
        )
        theme = resolve_theme(self.settings)
        role = "primary" if chip.active else self._intel_filter_button_role(chip)
        btn.setStyleSheet(button_style(role, theme))
        return btn

    @staticmethod
    def _intel_filter_button_role(chip: IntelFilterChip) -> str:
        if str(chip.kind or "").strip().lower() != "status":
            return "muted"
        bucket = str(chip.status_bucket or "").strip().lower()
        if bucket == "red":
            return "eligible_danger"
        if bucket == "yellow":
            return "eligible_warning"
        if bucket == "green":
            return "eligible_success"
        return "muted"

    def _toggle_intel_filter(self, kind: str, value: str) -> None:
        left_ops_scope = self._leave_ops_traffic_scope()
        self._close_message_reader_for_scope_change()
        kind = str(kind or "").strip().lower()
        value = str(value or "").strip()
        if kind == "status":
            self._intel_status_filter = "" if self._intel_status_filter == value else value
        elif kind == "topic":
            self._intel_topic_filter = "" if self._intel_topic_filter == value else value
        self._unfreeze_table()
        if left_ops_scope and self._load_projected_messages_into_table():
            return
        self._apply_message_filters_preserve_scroll()

    def _operator_traffic_context(self) -> OperatorTrafficContext:
        if bool(getattr(self, "_projection_primary_enabled", False)):
            # A coherent context arrives with the existing worker publication.
            # Pending settings changes use the previous context until the next
            # publication; no per-row filesystem freshness checks on the GUI.
            return getattr(self, "_projected_traffic_context", OperatorTrafficContext())
        hf_groups, local_groups = configured_group_names(self.settings)
        callsign = str(self.settings.get("operator_callsign", "") or "").strip().upper()
        db_path = self._db_path()
        try:
            db_mtime = int(db_path.stat().st_mtime_ns) if db_path and db_path.exists() else 0
        except Exception:
            db_mtime = 0
        cache_key = (callsign, hf_groups, local_groups, db_mtime)
        if cache_key != self._traffic_context_cache_key:
            self._traffic_context_cache = load_operator_traffic_context(
                db_path,
                callsign=callsign,
                configured_operating_groups=hf_groups,
                configured_local_groups=local_groups,
            )
            self._traffic_context_cache_key = cache_key
        return self._traffic_context_cache

    def _traffic_context_inputs(self) -> tuple[object, ...]:
        hf_groups, local_groups = configured_group_names(self.settings)
        callsign = str(self.settings.get("operator_callsign", "") or "").strip().upper() if self.settings else ""
        return callsign, hf_groups, local_groups

    def _projection_filter_settings(self) -> dict[str, object]:
        keys = ("commstat3_db_path", "commstat_db_path", "commstat23_db_path",
                "path_commstat", "commstat_launch_path", "commstat_config_path")
        return {key: str(self.settings.get(key, "") or "") for key in keys} if self.settings else {}

    def _set_traffic_action_filter(self, bucket: object) -> None:
        self._close_message_reader_for_scope_change()
        self._traffic_action_filter = str(bucket or "").strip().lower()
        if bool(getattr(self, "_traffic_navigation_pending", False)):
            if self._traffic_action_filter:
                self._traffic_loading_bucket = self._traffic_action_filter
                self._set_loading(True)
            else:
                self._traffic_navigation_pending = False
                self._set_loading(False)
        if hasattr(self, "traffic_action_summary"):
            self.traffic_action_summary.set_active_bucket(self._traffic_action_filter)
        self._unfreeze_table()
        self._apply_message_filters_preserve_scroll()

    def _refresh_traffic_action_summary(self, rows: Sequence[UnifiedMessage]) -> None:
        if not hasattr(self, "traffic_action_summary"):
            return
        for row in rows:
            self._message_summary_for_row(row)
        summary = build_traffic_action_summary(rows, self._operator_traffic_context())
        self.traffic_action_summary.set_active_bucket(self._traffic_action_filter)
        self.traffic_action_summary.set_summary(summary)

    def _row_matches_traffic_action_filter(self, row: UnifiedMessage) -> bool:
        bucket = str(getattr(self, "_traffic_action_filter", "") or "").strip().lower()
        if not bucket:
            return True
        return message_matches_traffic_bucket(
            row,
            self._operator_traffic_context(),
            bucket,
        )

    def message_summaries(self, *, visible_only: bool = True, default_visible_only: bool = False) -> Tuple[MessageSummary, ...]:
        if visible_only and hasattr(self, "_messages_model"):
            rows = self._messages_model.rows()
        else:
            rows = list(getattr(self, "_message_rows", []))
        summaries = tuple(self._message_summary_for_row(row) for row in rows)
        if default_visible_only:
            return tuple(summary for summary in summaries if summary.visible_by_default)
        return summaries

    def _row_matches_inbox_criteria(self, row: UnifiedMessage, criteria: InboxFilterCriteria) -> bool:
        if criteria.search_query:
            self._ensure_row_search_text(row)
        if criteria.focus == "bbs":
            payload = getattr(row, "payload", None)
            if not isinstance(payload, FileRecord) or not self._bbs_file_management_context_for_record(payload):
                return False
            criteria = replace(criteria, focus="all")
        return _core_row_matches_inbox_criteria(row, criteria)

    def _apply_message_filters(
        self,
        *,
        refresh_options: bool = True,
        recover_empty_stale_scope: bool = False,
    ) -> None:
        rows = self._message_rows
        if getattr(self, "_ops_traffic_message_ids", None) is not None:
            summary = getattr(self, "_ops_traffic_summary", None)
            bucket = str(self._traffic_action_filter or "")
            items = (summary.items_for(bucket) if bucket else summary.items) if summary is not None else ()
            allowed = {item.stable_id for item in items}
            filtered = [row for row in rows if str(getattr(row.payload, "message_id", "")) in allowed]
            self._set_message_table_display_profile(self._message_display_profile_for_current_view("MSG Type..."))
            self._render_messages_table(self._sort_rows(filtered))
            if summary is not None:
                self.traffic_action_summary.set_active_bucket(bucket)
                self.traffic_action_summary.set_summary(summary)
            self._update_visible_message_scope_label()
            self._update_clear_filters_style()
            self._update_mark_all_read_style()
            return
        now_ts = datetime.datetime.now(datetime.timezone.utc).timestamp()
        criteria = self._current_inbox_filter_criteria(now_ts=now_ts)
        type_sel = criteria.type_sel
        selected_sources = self._selected_message_sources()
        selected_groups = self._expanded_selected_message_groups()
        configured_groups = self._configured_message_group_names()

        filtered = []
        intel_base_rows = []
        traffic_base_rows = []
        workspace_pass_count = 0
        criteria_pass_count = 0
        map_context_pass_count = 0
        intel_pass_count = 0
        for row in rows:
            if not _core_row_matches_workspace_scope(
                row,
                selected_sources=selected_sources,
                selected_groups=selected_groups,
                configured_groups=configured_groups,
            ):
                continue
            workspace_pass_count += 1
            if not self._row_matches_inbox_criteria(row, criteria):
                continue
            criteria_pass_count += 1
            if not self._row_matches_map_context_filter(row):
                continue
            map_context_pass_count += 1
            intel_base_rows.append(row)
            if not self._row_matches_intel_filter(row):
                continue
            intel_pass_count += 1
            traffic_base_rows.append(row)
            if not self._row_matches_traffic_action_filter(row):
                continue
            filtered.append(row)
        if (
            recover_empty_stale_scope
            and not filtered
            and rows
            and self._recover_empty_message_filter_state(rows, criteria, selected_sources, selected_groups)
        ):
            criteria = self._current_inbox_filter_criteria(now_ts=now_ts)
            type_sel = criteria.type_sel
            selected_sources = self._selected_message_sources()
            selected_groups = self._expanded_selected_message_groups()
            configured_groups = self._configured_message_group_names()
            workspace_pass_count = 0
            criteria_pass_count = 0
            map_context_pass_count = 0
            intel_pass_count = 0
            intel_base_rows = []
            traffic_base_rows = []
            for row in rows:
                if not _core_row_matches_workspace_scope(
                    row,
                    selected_sources=selected_sources,
                    selected_groups=selected_groups,
                    configured_groups=configured_groups,
                ):
                    continue
                workspace_pass_count += 1
                if not self._row_matches_inbox_criteria(row, criteria):
                    continue
                criteria_pass_count += 1
                if not self._row_matches_map_context_filter(row):
                    continue
                map_context_pass_count += 1
                intel_base_rows.append(row)
                if not self._row_matches_intel_filter(row):
                    continue
                intel_pass_count += 1
                traffic_base_rows.append(row)
                if not self._row_matches_traffic_action_filter(row):
                    continue
                filtered.append(row)
        self._set_message_table_display_profile(self._message_display_profile_for_current_view(type_sel))
        if (
            type_sel == "BBS"
            and self._sort_column == self._default_sort_column
            and self._sort_order == self._default_sort_order
        ):
            filtered = sorted(filtered, key=lambda r: r.rcv_ts or 0.0)
        else:
            filtered = self._sort_rows(filtered)
        if self._projection_primary_enabled and self._projection_focus_counts_available:
            self._sync_inbox_focus_buttons()
        else:
            self._refresh_inbox_focus_unread_counts(rows, now_ts=now_ts)
        self._render_messages_table(filtered)
        self._refresh_intel_filter_bar(intel_base_rows)
        self._refresh_traffic_action_summary(traffic_base_rows)
        self._update_clear_filters_style()
        self._update_map_context_filter_label()
        self._update_visible_message_scope_label()
        self._update_mark_all_read_style()
        if refresh_options:
            self._refresh_workspace_filter_options(self._rows_for_group_filter_options(rows))
        display_groups = self._selected_message_groups()
        log.debug(
            "MessageViewer: filters focus=%s age=%s type=%s hidden=%d status=%s from=%s to=%s rcv=%s groups=%s sources=%s => %d rows",
            criteria.focus,
            criteria.age_filter_seconds,
            criteria.type_sel,
            len(criteria.excluded_types) if criteria.applies_hidden_types else 0,
            criteria.status_sel,
            criteria.from_sel,
            criteria.to_sel,
            criteria.search_query or "ALL",
            sorted(display_groups) if display_groups is not None else ["ALL"],
            sorted(selected_sources) if selected_sources is not None else ["ALL"],
            len(filtered),
        )
        log.info(
            (
                "MESSAGES|inbox_filter_result loaded=%d workspace=%d criteria=%d map=%d intel=%d rendered=%d "
                "focus=%s sources=%s groups=%s type=%s status=%s intel_status=%s intel_topic=%s hidden=%s search=%s map_context=%s"
            ),
            len(rows),
            workspace_pass_count,
            criteria_pass_count,
            map_context_pass_count,
            intel_pass_count,
            len(filtered),
            criteria.focus,
            sorted(selected_sources) if selected_sources is not None else ["ALL"],
            sorted(display_groups) if display_groups is not None else ["ALL"],
            criteria.type_sel,
            criteria.status_sel,
            getattr(self, "_intel_status_filter", "") or "ALL",
            getattr(self, "_intel_topic_filter", "") or "ALL",
            sorted(criteria.excluded_types) if criteria.excluded_types else ["NONE"],
            criteria.search_query or "ALL",
            getattr(self, "_map_context_filter", {}) or {},
        )

    def _recover_empty_message_filter_state(
        self,
        rows: List[UnifiedMessage],
        criteria: InboxFilterCriteria,
        selected_sources: Optional[Set[str]],
        selected_groups: Optional[Set[str]],
    ) -> bool:
        if not rows:
            return False
        configured_groups = self._configured_message_group_names()

        def matches_without_source(row: UnifiedMessage) -> bool:
            if selected_groups is not None and (
                _core_message_group_value(row, configured_groups=configured_groups) not in selected_groups
            ):
                return False
            if not self._row_matches_inbox_criteria(row, criteria):
                return False
            return self._row_matches_map_context_filter(row)

        def matches_without_group(row: UnifiedMessage) -> bool:
            if not _core_row_matches_source_filter(row, selected_sources):
                return False
            if not self._row_matches_inbox_criteria(row, criteria):
                return False
            return self._row_matches_map_context_filter(row)

        stale_source_filter = selected_sources is not None and not any(
            _core_row_matches_source_filter(row, selected_sources) for row in rows
        )
        stale_group_filter = selected_groups is not None and not any(
            _core_message_group_value(row, configured_groups=configured_groups) in selected_groups
            for row in rows
        )
        blocking_source_filter = selected_sources is not None and any(matches_without_source(row) for row in rows)
        blocking_group_filter = selected_groups is not None and any(matches_without_group(row) for row in rows)
        stale_source_filter = bool(stale_source_filter or blocking_source_filter)
        stale_group_filter = bool(stale_group_filter or blocking_group_filter)
        if not stale_source_filter and not stale_group_filter:
            return False
        if stale_source_filter and hasattr(self, "source_filter"):
            self._select_all_dropdown_values(self.source_filter)
        if stale_group_filter and hasattr(self, "operating_group_filter"):
            self._select_all_dropdown_values(self.operating_group_filter)
        log.warning(
            "MESSAGES|recovered_empty_filter_state loaded=%d focus=%s stale_sources=%s stale_groups=%s",
            len(rows),
            criteria.focus,
            bool(stale_source_filter),
            bool(stale_group_filter),
        )
        return True

    @staticmethod
    def _select_all_dropdown_values(widget: object) -> None:
        values = [value for value, _label in getattr(widget, "_options", []) or [] if str(value or "").strip()]
        if not values:
            return
        try:
            widget.blockSignals(True)
            widget.set_selected_values(values)
        finally:
            try:
                widget.blockSignals(False)
            except Exception:
                pass

    def _rows_for_group_filter_options(self, rows: List[UnifiedMessage]) -> List[UnifiedMessage]:
        now_ts = datetime.datetime.now(datetime.timezone.utc).timestamp()
        criteria = self._current_inbox_filter_criteria(now_ts=now_ts)
        sources = self._selected_message_sources()
        option_rows: List[UnifiedMessage] = []
        for row in rows:
            if not _core_row_matches_source_filter(row, sources):
                continue
            if not self._row_matches_inbox_criteria(row, criteria):
                continue
            option_rows.append(row)
        return option_rows

    def _message_display_profile_for_current_view(self, type_sel: object) -> str:
        return message_display_profile_for_focus_type(getattr(self, "_inbox_focus", "all"), type_sel)

    def _message_display_profile_for_type(self, type_sel: object) -> str:
        return message_display_profile_for_type(type_sel)

    def _current_messages_time_header(self) -> str:
        return "Age"

    def _set_message_table_display_profile(self, profile: str) -> None:
        if not hasattr(self, "_messages_model"):
            return
        old = self._messages_model.display_profile()
        old_default_col = 6 if old in {"field_report", "field_summary", "intel_report"} else 5 if old == "form_message" else self._default_sort_column
        self._messages_model.set_display_profile(profile, self._current_messages_time_header())
        new_profile = self._messages_model.display_profile()
        new_default_col = 6 if new_profile in {"field_report", "field_summary", "intel_report"} else 5 if new_profile == "form_message" else self._default_sort_column
        if old != new_profile and self._sort_column == old_default_col:
            self._sort_column = new_default_col
        if old != new_profile and hasattr(self, "messages_table"):
            self._apply_message_table_profile_widths()
        if hasattr(self, "view_spotter_map_btn"):
            self.view_spotter_map_btn.setVisible(new_profile in {"field_report", "field_summary"})

    def _request_spotter_map_view(self) -> None:
        context = self._message_map_context()
        host = self.window()
        if host is not None and hasattr(host, "open_spotter_map"):
            try:
                host.open_spotter_map(**context)
                return
            except Exception as exc:
                log.debug("MessageViewer: open_spotter_map failed: %s", exc)
        QMessageBox.information(self, "View HF Reports Map", "The Map view is not available in this runtime profile.")

    def _message_map_context(self) -> Dict[str, str]:
        row = self._current_message_table_row()
        group = self._message_map_group_from_row(row)
        if not group:
            selected_groups = [
                self._normalize_message_group_filter_value(group_value)
                for group_value in (self._selected_message_groups() if self._message_group_filter_active() else [])
            ]
            selected_groups = [g for g in selected_groups if g and g.lower() != "unassigned"]
            if len(selected_groups) == 1:
                group = selected_groups[0]
        topic = ""
        if row is not None:
            topic = next((str(t).strip() for t in row.topics if str(t).strip()), "")
        return {"group_filter": group, "topic_filter": topic}

    def _current_message_table_row(self) -> UnifiedMessage | None:
        if not hasattr(self, "messages_table"):
            return None
        try:
            index = self.messages_table.currentIndex()
            if not index.isValid():
                return None
            row = index.data(Qt.UserRole)
            return row if isinstance(row, UnifiedMessage) else None
        except Exception:
            return None

    @staticmethod
    def _message_map_group_from_row(row: UnifiedMessage | None) -> str:
        if row is None:
            return ""
        raw = str(row.to_call or "").strip().upper()
        if not raw:
            return ""
        raw = raw.split(">", 1)[0].strip()
        raw = raw[1:] if raw.startswith("@") else raw
        raw = re.sub(r"[^A-Z0-9_-]", "", raw)
        return raw

    def _apply_message_table_profile_widths(self) -> None:
        """Fit the bounded Inbox model without turning resize into a hot path.

        The model is capped at 200 rows.  Measuring those retained display
        values is deterministic and cache-only, unlike Qt's ResizeToContents
        mode, which may repeatedly call the model during native layout passes.
        Narrative columns may consume genuine surplus; categorical columns
        (especially CommStat Kind) never expand merely because the window is
        wide.
        """
        profile = self._messages_model.display_profile() if hasattr(self, "_messages_model") else "triage"
        table = getattr(self, "messages_table", None)
        model = getattr(self, "_messages_model", None)
        if table is None or model is None:
            return
        font_metrics = table.fontMetrics()
        _chip_padding, _chip_gap, chip_margin, chip_height, _chip_radius = action_chip_metrics(font_metrics)
        action_row_height = chip_height + (2 * chip_margin)
        vertical_header = table.verticalHeader()
        vertical_header.setMinimumSectionSize(
            max(vertical_header.minimumSectionSize(), action_row_height)
        )
        vertical_header.setDefaultSectionSize(action_row_height)
        padding = max(24, int(font_metrics.horizontalAdvance("MM")))
        header = table.horizontalHeader()
        indicator_width = (
            header.select_button_width_hint()
            if isinstance(header, MessageHeaderWithCheckbox)
            else max(32, int(font_metrics.height()) + 16)
        )
        measured: list[int] = []
        for column in range(model.columnCount()):
            header_text = str(model.headerData(column, Qt.Horizontal, Qt.DisplayRole) or "")
            semantic = header_text.strip().casefold()
            if column == 0:
                minimum, cap = indicator_width, indicator_width
            elif column == model.columnCount() - 1:
                action_width = MessageActionDelegate.required_width(font_metrics)
                minimum, cap = action_width, action_width
            elif semantic == "source":
                minimum, cap = 78, 180
            elif semantic in {"status", "age"}:
                minimum, cap = (78, 132) if semantic == "status" else (68, 100)
            elif semantic in {"from", "to"}:
                minimum, cap = 88, 190
            elif semantic == "kind":
                minimum, cap = 78, 240
            elif semantic in {"message", "summary", "kind / message"}:
                minimum, cap = 140, 760
            elif semantic == "mcf":
                minimum, cap = 90, 300
            elif semantic == "state / grid":
                minimum, cap = 100, 220
            elif semantic == "type":
                minimum, cap = 78, 220
            else:
                minimum, cap = 78, 300
            widest = font_metrics.horizontalAdvance(header_text) + padding
            for row_index in range(model.rowCount()):
                value = model.data(model.index(row_index, column), Qt.DisplayRole)
                if value is not None:
                    widest = max(widest, font_metrics.horizontalAdvance(str(value)) + padding)
            measured.append(max(minimum, min(cap, int(widest))))

        signature = (
            profile,
            font_metrics.height(),
            tuple(measured),
        )
        if signature == getattr(self, "_message_table_fit_signature", None):
            return
        self._message_table_fit_signature = signature

        # Summary/message text is the only elastic content.  CommStat's Kind
        # is intentionally content-fit so a single repeated value cannot
        # become the dominant full-screen column.
        stretch_col = {
            "triage": 6,
            "field_summary": 5,
            "form_message": 1,
        }.get(profile)
        updates_were_enabled = table.updatesEnabled()
        if updates_were_enabled:
            table.setUpdatesEnabled(False)
        try:
            try:
                header = table.horizontalHeader()
                header.setStretchLastSection(False)
                for idx in range(8):
                    if idx in {0, 7}:
                        header.setSectionResizeMode(idx, QHeaderView.Fixed)
                    else:
                        header.setSectionResizeMode(idx, QHeaderView.Interactive)
                if stretch_col is not None:
                    header.setSectionResizeMode(stretch_col, QHeaderView.Stretch)
            except Exception:
                pass
            for idx, width in enumerate(measured):
                if idx == stretch_col:
                    continue
                try:
                    table.setColumnWidth(idx, width)
                except Exception:
                    pass
            try:
                table.setMinimumWidth(0)
            except Exception:
                pass
            try:
                self._sync_header_widths()
            except Exception:
                pass
        finally:
            if updates_were_enabled:
                table.setUpdatesEnabled(True)
                table.viewport().update()

    def _queue_message_table_column_fit(self) -> None:
        """Coalesce font/model/viewport fit requests into one UI-thread pass."""

        if not hasattr(self, "messages_table"):
            return
        timer = getattr(self, "_message_table_fit_timer", None)
        if timer is None:
            timer = QTimer(self)
            timer.setSingleShot(True)
            timer.timeout.connect(self._apply_message_table_profile_widths)
            self._message_table_fit_timer = timer
        timer.start(0)

    def _refresh_workspace_filter_options(self, rows: List[UnifiedMessage]) -> None:
        group_option_rows = rows
        if self._show_all_message_groups_enabled() and not group_option_rows and self._message_rows:
            group_option_rows = self._message_rows
        if hasattr(self, "operating_group_filter"):
            commstat_state = self._commstat_group_state()
            group_sources = self._message_group_source_map(group_option_rows)
            selected_groups, select_all_when_empty = _core_message_group_rebuild_selection(
                group_sources,
                current_selected=self.operating_group_filter.selected_values(),
                current_all_selected=self.operating_group_filter.all_selected(),
                fio_configured_groups=self._configured_message_group_names(),
                commstat_active_groups=self._message_group_candidate_set(commstat_state.active_groups),
                commstat_configured_groups=self._message_group_candidate_set(commstat_state.configured_groups),
                show_all_groups=self._show_all_message_groups_enabled(),
            )
            sections = self._message_group_option_sections_from_sources(group_sources)
            group_filter = self.operating_group_filter
            seen_group_values: set[str] = set()
            normalized_group_sections: list[tuple[str, tuple[tuple[str, str], ...]]] = []
            for section, options in sections:
                normalized_options: list[tuple[str, str]] = []
                for value, label in options:
                    clean_value = str(value or "").strip()
                    clean_label = str(label or clean_value).strip() or clean_value
                    if not clean_value or clean_value in seen_group_values:
                        continue
                    seen_group_values.add(clean_value)
                    normalized_options.append((clean_value, clean_label))
                if normalized_options:
                    normalized_group_sections.append((str(section or "").strip(), tuple(normalized_options)))
            section_key = tuple(normalized_group_sections)
            group_option_values = {value for _section, options in section_key for value, _label in options}
            desired_group_selection = (
                set(group_option_values)
                if selected_groups is None
                else {str(value) for value in selected_groups} & group_option_values
            )
            if selected_groups is not None and select_all_when_empty and not desired_group_selection:
                desired_group_selection = set(group_option_values)
            expected_group_sections = tuple(
                (section, tuple(value for value, _label in options))
                for section, options in section_key
            )
            if (
                expected_group_sections != tuple(
                    (str(section or ""), tuple(str(value) for value in values))
                    for section, values in getattr(group_filter, "_sections", [])
                )
                or tuple((str(value), str(label)) for value, label in getattr(group_filter, "_options", []))
                != tuple(item for _section, options in section_key for item in options)
                or desired_group_selection != group_filter.selected_values()
            ):
                group_filter.set_grouped_options(
                    sections,
                    selected_values=selected_groups,
                    select_all_when_empty=select_all_when_empty,
                )
        if hasattr(self, "source_filter"):
            selected_sources = None
            if not self.source_filter.all_selected():
                # Preserve a live pre-normalization selection across the
                # operator-facing SitRep -> Spotter vocabulary migration.
                selected_sources = sorted({
                    normalize_message_source_family(value)
                    for value in self.source_filter.selected_values()
                    if normalize_message_source_family(value)
                })
            options = self._message_source_options(rows)
            source_filter = self.source_filter
            seen_source_values: set[str] = set()
            normalized_source_options: list[tuple[str, str]] = []
            for value, label in options:
                clean_value = str(value or "").strip()
                clean_label = str(label or clean_value).strip() or clean_value
                if not clean_value or clean_value in seen_source_values:
                    continue
                seen_source_values.add(clean_value)
                normalized_source_options.append((clean_value, clean_label))
            normalized_options = tuple(normalized_source_options)
            current_options = tuple((str(value), str(label)) for value, label in getattr(source_filter, "_options", []))
            desired_selection = (
                {value for value, _label in normalized_options}
                if selected_sources is None
                else set(selected_sources) & {value for value, _label in normalized_options}
            )
            if (
                normalized_options != current_options
                or desired_selection != source_filter.selected_values()
            ):
                source_filter.set_options(
                    options,
                    selected_values=selected_sources,
                    select_all_when_empty=selected_sources is None,
                )
        self._refresh_basic_filter_button_texts()

    def _message_source_options(self, rows: List[UnifiedMessage]) -> list[tuple[str, str]]:
        options = _core_message_source_options(rows)
        focus_values = set(self._source_values_for_inbox_focus(getattr(self, "_inbox_focus", "all")))
        if focus_values:
            options = [(value, label) for value, label in options if value in focus_values]
        return options

    def _message_group_options(self, rows: List[UnifiedMessage]) -> list[tuple[str, str]]:
        options: list[tuple[str, str]] = []
        for _section, section_options in self._message_group_option_sections(rows):
            options.extend(section_options)
        return options

    def _primary_message_group_values(self, rows: List[UnifiedMessage]) -> set[str]:
        fio_configured_groups = self._configured_message_group_names()
        commstat_state = self._commstat_group_state()
        return _core_primary_message_group_values(
            self._message_group_source_map(rows),
            fio_configured_groups=fio_configured_groups,
            commstat_active_groups=self._message_group_candidate_set(commstat_state.active_groups),
            commstat_configured_groups=self._message_group_candidate_set(commstat_state.configured_groups),
        )

    def _message_group_source_map(self, rows: List[UnifiedMessage]) -> dict[str, set[str]]:
        pairs: list[tuple[str, str]] = []
        configured_groups = self._configured_message_group_names()
        for row in rows:
            for group in _core_message_group_values(
                row,
                configured_groups=configured_groups,
                candidate_groups=configured_groups,
            ):
                pairs.append((group, self._message_source_value(row)))
        group_sources = _core_message_group_source_map(pairs, family_map=self._operator_group_family_map())
        self._add_commstat_group_options_for_current_scope(group_sources)
        return group_sources

    def _add_commstat_group_options_for_current_scope(self, group_sources: dict[str, set[str]]) -> None:
        selected_sources = self._selected_message_sources()
        focus = str(getattr(self, "_inbox_focus", "all") or "all").strip().lower()
        includes_commstat = focus in {"all", "commstat"} or selected_sources is None or "commstat" in selected_sources
        if not includes_commstat:
            return
        try:
            commstat_state = self._commstat_group_state()
        except Exception:
            return
        groups = set(commstat_state.active_groups or ()) or set(commstat_state.configured_groups or ())
        for group in self._message_group_candidate_set(groups):
            if group and group != "unassigned":
                group_sources.setdefault(group, set()).add("commstat")

    def _message_group_option_sections(self, rows: List[UnifiedMessage]) -> list[tuple[str, list[tuple[str, str]]]]:
        return self._message_group_option_sections_from_sources(self._message_group_source_map(rows))

    def _message_group_option_sections_from_sources(
        self,
        group_sources: dict[str, set[str]],
    ) -> list[tuple[str, list[tuple[str, str]]]]:
        fio_configured_groups = self._configured_message_group_names()
        commstat_state = self._commstat_group_state()
        commstat_active_groups = self._message_group_candidate_set(commstat_state.active_groups)
        commstat_configured_groups = self._message_group_candidate_set(commstat_state.configured_groups)
        show_all_groups = self._show_all_message_groups_enabled()
        return _core_message_group_option_sections(
            group_sources,
            fio_configured_groups=fio_configured_groups,
            commstat_active_groups=commstat_active_groups,
            commstat_configured_groups=commstat_configured_groups,
            show_all_groups=show_all_groups,
        )

    def _show_all_message_groups_enabled(self) -> bool:
        return bool(
            getattr(getattr(self, "show_all_message_groups_chk", None), "isChecked", lambda: False)()
        )

    def _commstat_group_state(self):
        if bool(getattr(self, "_projection_primary_enabled", False)):
            return getattr(self, "_projected_commstat_groups",
                           CommStatGroupState(frozenset(), frozenset(), frozenset(), True))
        try:
            return load_commstat_group_state(self.settings)
        except Exception:
            return load_commstat_group_state({})

    def _configured_message_group_names(self) -> set[str]:
        groups: set[str] = set()
        for key in ("operating_groups", "local_net_profiles"):
            try:
                records = self.settings.get(key, []) or []
            except Exception:
                records = []
            if not isinstance(records, list):
                continue
            for record in records:
                if not isinstance(record, dict):
                    continue
                group = self._normalize_message_group_filter_value(
                    record.get("group") or record.get("group_name") or record.get("name") or ""
                )
                if group:
                    groups.add(group)
        return groups

    @classmethod
    def _message_group_candidate_set(cls, values: object) -> set[str]:
        return _core_message_group_candidate_set(values)

    @staticmethod
    def _is_message_group_candidate(value: object, *, configured_groups: set[str] | None = None) -> bool:
        return _core_is_message_group_candidate(value, configured_groups=configured_groups)

    def _operator_group_family_map(self) -> dict[str, OperatorGroupFamily]:
        if bool(getattr(self, "_projection_primary_enabled", False)):
            return getattr(self, "_projected_group_families", {})
        db_path = self._db_path()
        if not db_path or not db_path.exists():
            return {}
        try:
            stat = db_path.stat()
            fp = (str(db_path), float(stat.st_mtime), int(stat.st_size))
        except Exception:
            fp = (str(db_path), 0.0, 0)
        cache_fp = getattr(self, "_operator_group_family_fp", None)
        cache = getattr(self, "_operator_group_family_cache", None)
        if cache_fp == fp and isinstance(cache, dict):
            return cache
        families = load_operator_group_families(db_path)
        self._operator_group_family_fp = fp
        self._operator_group_family_cache = families
        return families

    def _expanded_selected_message_groups(self) -> Optional[Set[str]]:
        groups = self._selected_message_groups()
        if groups is None:
            return None
        return expand_group_selection(groups, self._operator_group_family_map())

    @staticmethod
    def _normalize_message_group_filter_value(value: object) -> str:
        return _core_normalize_message_group_filter_value(value)

    def _message_source_value(self, row: UnifiedMessage) -> str:
        return _core_message_source_value(row)

    def _message_group_value(self, row: UnifiedMessage) -> str:
        return _core_message_group_value(row, configured_groups=self._configured_message_group_names())

    def _selected_message_sources(self) -> Optional[Set[str]]:
        if hasattr(self, "source_filter"):
            if self.source_filter.all_selected():
                return None
            return self.source_filter.selected_values()
        return None

    def _source_filter_refinement_active(self) -> bool:
        selected = self._selected_message_sources()
        if selected is None:
            return False
        focus_sources = {
            str(value or "").strip().lower()
            for value in self._source_values_for_inbox_focus(getattr(self, "_inbox_focus", "all"))
            if str(value or "").strip()
        }
        if focus_sources and {str(value or "").strip().lower() for value in selected} == focus_sources:
            return False
        return True

    def _selected_message_groups(self) -> Optional[Set[str]]:
        if hasattr(self, "operating_group_filter"):
            if self.operating_group_filter.all_selected():
                return None
            return {
                group
                for value in self.operating_group_filter.selected_values()
                if (group := self._normalize_message_group_filter_value(value))
            }
        return None

    def _message_group_filter_active(self) -> bool:
        if not hasattr(self, "operating_group_filter"):
            return False
        selected = self._selected_message_groups()
        if selected is None:
            return False
        if self._show_all_message_groups_enabled() and selected == self._primary_message_group_values(self._message_rows):
            return False
        if not self._show_all_message_groups_enabled() and self.operating_group_filter.all_selected():
            return False
        return True

    def _row_matches_workspace_filters(self, row: UnifiedMessage) -> bool:
        return _core_row_matches_workspace_scope(
            row,
            selected_sources=self._selected_message_sources(),
            selected_groups=self._expanded_selected_message_groups(),
            configured_groups=self._configured_message_group_names(),
        )

    @staticmethod
    def _row_matches_age_filter(row: UnifiedMessage, age_filter_seconds: object, *, now_ts: float | None = None) -> bool:
        return _core_row_matches_age_filter(row, age_filter_seconds, now_ts=now_ts)

    def _row_matches_inbox_focus(self, row: UnifiedMessage) -> bool:
        focus = str(getattr(self, "_inbox_focus", "all") or "all").strip().lower()
        if focus == "bbs":
            payload = getattr(row, "payload", None)
            if isinstance(payload, FileRecord) and self._bbs_file_management_context_for_record(payload):
                return True
        return _core_row_matches_inbox_focus(row, focus)

    def _row_matches_map_context_filter(self, row: UnifiedMessage) -> bool:
        context = getattr(self, "_map_context_filter", {}) or {}
        if not isinstance(context, dict):
            return True
        state_filter = str(context.get("state_filter") or "").strip().upper()
        grid_filter = str(context.get("grid_filter") or "").strip().upper()
        fema_region_filter = str(context.get("fema_region_filter") or "").strip().upper()
        if state_filter or fema_region_filter:
            row_state = self._map_context_row_state(row)
            if state_filter and row_state != state_filter:
                return False
            if fema_region_filter and STATE_TO_FEMA_REGION.get(row_state, "") != fema_region_filter:
                return False
        if grid_filter:
            summary = self._message_summary_for_row(row)
            row_grid = str(getattr(summary.map_hint, "grid_square", "") or "").strip().upper()
            if row_grid:
                if not row_grid.startswith(grid_filter):
                    return False
            else:
                self._ensure_row_search_text(row)
                if grid_filter not in str(row.search_text or "").upper():
                    return False
        if not context.get("concern_only"):
            return True
        payload = getattr(row, "payload", None)
        status_values = [
            getattr(row, "status", ""),
            getattr(payload, "status_label", ""),
            getattr(payload, "alert_color", ""),
            getattr(payload, "overall_status", ""),
        ]
        status_text = " ".join(str(value or "").strip().lower() for value in status_values if str(value or "").strip())
        if any(term in status_text for term in ("red", "yellow", "orange", "caution", "degraded", "warning", "watch")):
            return True
        if any(term in status_text for term in ("green", "normal", "functioning", "all clear")):
            return False
        self._ensure_row_search_text(row)
        haystack = str(row.search_text or "").lower()
        if any(term in haystack for term in (" red", " yellow", " orange", " caution", "degraded", "warning", "outage", "down")):
            return True
        if any(term in haystack for term in (" green", "normal", "functioning", "all clear")):
            return False
        return True

    @staticmethod
    def _map_context_row_state(row: UnifiedMessage) -> str:
        payload = getattr(row, "payload", None)
        candidates = [
            getattr(payload, "state_code", ""),
            getattr(payload, "state", ""),
            getattr(payload, "reported_for_state", ""),
        ]
        if isinstance(payload, dict):
            candidates.extend(
                [
                    payload.get("state_code", ""),
                    payload.get("state", ""),
                    payload.get("reported_for_state", ""),
                ]
            )
        for value in candidates:
            text = str(value or "").strip().upper()
            if not text:
                continue
            token = re.split(r"[\s/|,]+", text)[0].strip().upper()
            if token in STATE_TO_FEMA_REGION:
                return token
            if token in US_STATE_ABBR_FROM_NAME:
                return US_STATE_ABBR_FROM_NAME[token]
        search_text = str(getattr(row, "search_text", "") or "")
        if not search_text:
            search_text = _core_row_search_text(row)
            row.search_text = search_text
        haystack = search_text.upper()
        for state in STATE_TO_FEMA_REGION:
            state_pat = re.escape(state)
            if re.search(rf"\b(?:AREA|STATE/GRID|REPORTED FOR|LOCATION)\s*:\s*{state_pat}\b", haystack):
                return state
            if re.search(rf"\b{state_pat}\s*/\s*[A-R]{{2}}\d{{2}}", haystack):
                return state
        return ""

    def _is_filter_or_sort_active(self) -> bool:
        type_sel = self.type_filter.currentText() if hasattr(self, "type_filter") else "MSG Type..."
        status_sel = self.status_filter.currentText() if hasattr(self, "status_filter") else "Status..."
        from_sel = self.from_filter.currentText() if hasattr(self, "from_filter") else ""
        to_sel = self.to_filter.currentText() if hasattr(self, "to_filter") else ""
        if type_sel not in ("", "MSG Type..."):
            return True
        if status_sel not in ("", "Status..."):
            return True
        if from_sel:
            return True
        if to_sel:
            return True
        if self._source_filter_refinement_active():
            return True
        if self._message_group_filter_active():
            return True
        if getattr(self, "_intel_status_filter", "") or getattr(self, "_intel_topic_filter", ""):
            return True
        if getattr(self, "_traffic_action_filter", ""):
            return True
        if (self.rcv_search.text() if hasattr(self, "rcv_search") else "").strip():
            return True
        if (
            hasattr(self, "received_filter")
            and _core_age_filter_bounds(self.received_filter.currentData())
            != _core_age_filter_bounds(DEFAULT_RECEIVED_FILTER_SECONDS)
        ):
            return True
        if getattr(self, "_map_context_filter", {}) or {}:
            return True
        if (
            self._sort_column != self._default_sort_column
            or self._sort_order != self._default_sort_order
        ):
            return True
        return False

    def _requires_full_refresh_after_read(self) -> bool:
        status_sel = self.status_filter.currentText() if hasattr(self, "status_filter") else "Status..."
        if status_sel not in ("", "Status..."):
            return True
        # Sorting by status can change row ordering when NEW -> READ.
        if self._sort_column == 2:
            return True
        # Search text may include status terms and would require recompute.
        query = (self.rcv_search.text() if hasattr(self, "rcv_search") else "").strip().lower()
        if query:
            return True
        return False

    def _is_filter_active(self) -> bool:
        return self._filters_active()

    def _apply_message_filters_preserve_scroll(self) -> None:
        if not hasattr(self, "messages_table"):
            self._apply_message_filters()
            return
        bar = self.messages_table.verticalScrollBar()
        value = bar.value()
        self._apply_message_filters()
        bar.setValue(min(value, bar.maximum()))

    def _update_rendered_status(self, match_fn) -> None:
        if not hasattr(self, "_messages_model"):
            return
        for i, row in enumerate(self._messages_model._rows):
            if match_fn(row):
                row.status = "READ"
                idx = self._messages_model.index(i, 2)
                self._messages_model.dataChanged.emit(
                    idx, idx, [Qt.DisplayRole, Qt.ForegroundRole]
                )

    def _refresh_table_after_read(self, match_fn, row_ref: Optional[UnifiedMessage] = None) -> None:
        updated = False
        unread_rows: List[UnifiedMessage] = []
        if row_ref is not None:
            if self._row_is_unread_for_focus_count(row_ref):
                unread_rows.append(row_ref)
            row_ref.status = "READ"
            updated = True
        else:
            for row in self._message_rows:
                if match_fn(row):
                    if self._row_is_unread_for_focus_count(row):
                        unread_rows.append(row)
                    row.status = "READ"
                    updated = True
        if not updated:
            return
        if self._requires_full_refresh_after_read():
            self._refresh_message_filters(self._message_rows)
            self._apply_message_filters_preserve_scroll()
        else:
            if row_ref is not None and hasattr(self, "_messages_model"):
                if not self._messages_model.mark_row_read(row_ref):
                    self._update_rendered_status(match_fn)
            else:
                self._update_rendered_status(match_fn)
            self._update_mark_all_read_style()
        for row in unread_rows:
            self._decrement_inbox_focus_counts_for_row(row)

    def _decrement_inbox_focus_counts_for_row(self, row: UnifiedMessage) -> None:
        counts = getattr(self, "_inbox_focus_unread_counts", None)
        if not isinstance(counts, dict) or not counts:
            return
        matched = {"all", "new"}
        for key, _label, _tip in self._inbox_focus_options():
            if key in {"all", "new"}:
                continue
            if _core_row_matches_inbox_focus(row, key):
                matched.add(key)
        for key in matched:
            counts[key] = max(0, int(counts.get(key, 0) or 0) - 1)
        self._sync_inbox_focus_buttons()

    def _clear_filters(self) -> None:
        left_ops_scope = self._leave_ops_traffic_scope()
        self._close_message_reader_for_scope_change()
        self._unfreeze_table()
        if (
            self.type_filter.currentText() in ("", "MSG Type...")
            and self.status_filter.currentText() in ("", "Status...")
            and self.from_filter.currentText() in ("",)
            and self.to_filter.currentText() in ("",)
            and not self._source_filter_refinement_active()
            and self._selected_message_groups() is None
            and not getattr(self, "_intel_status_filter", "")
            and not getattr(self, "_intel_topic_filter", "")
            and not getattr(self, "_traffic_action_filter", "")
            and not (getattr(self, "_map_context_filter", {}) or {})
            and _core_age_filter_bounds(self.received_filter.currentData())
            == _core_age_filter_bounds(DEFAULT_RECEIVED_FILTER_SECONDS)
            and not self.rcv_search.text().strip()
        ):
            if left_ops_scope:
                self._load_projected_messages_into_table()
            return
        self.type_filter.blockSignals(True)
        self.status_filter.blockSignals(True)
        self.from_filter.blockSignals(True)
        self.to_filter.blockSignals(True)
        self.rcv_search.blockSignals(True)
        self.received_filter.blockSignals(True)
        if hasattr(self, "show_all_message_groups_chk"):
            self.show_all_message_groups_chk.blockSignals(True)
            self.show_all_message_groups_chk.setChecked(False)
        self._map_context_filter = {}
        self._intel_status_filter = ""
        self._intel_topic_filter = ""
        self._traffic_action_filter = ""
        if hasattr(self, "traffic_action_summary"):
            self.traffic_action_summary.set_active_bucket("")
        self._sync_inbox_focus_buttons()
        default_age_idx = self.received_filter.findData(DEFAULT_RECEIVED_FILTER_SECONDS)
        self.received_filter.setCurrentIndex(default_age_idx if default_age_idx >= 0 else 0)
        self.type_filter.setCurrentText("MSG Type...")
        self.status_filter.setCurrentText("Status...")
        self.from_filter.setCurrentText("")
        self.to_filter.setCurrentText("")
        self.rcv_search.clear()
        if hasattr(self, "source_filter"):
            self._sync_source_filter_for_inbox_focus(getattr(self, "_inbox_focus", "all"))
        if hasattr(self, "operating_group_filter"):
            self.operating_group_filter.set_grouped_options(
                self._message_group_option_sections(self._message_rows),
                selected_values=None,
                select_all_when_empty=True,
            )
        self.type_filter.blockSignals(False)
        self.status_filter.blockSignals(False)
        self.from_filter.blockSignals(False)
        self.to_filter.blockSignals(False)
        self.rcv_search.blockSignals(False)
        self.received_filter.blockSignals(False)
        if hasattr(self, "show_all_message_groups_chk"):
            self.show_all_message_groups_chk.blockSignals(False)
            self._update_show_all_message_groups_style()
        self._refresh_basic_filter_button_texts()
        if left_ops_scope and self._load_projected_messages_into_table():
            return
        self._apply_message_filters()

    def _toggle_message_groups_mode_from_menu(self) -> None:
        if not hasattr(self, "show_all_message_groups_chk"):
            return
        self.show_all_message_groups_chk.setChecked(not self._show_all_message_groups_enabled())

    def _on_show_all_message_groups_changed(self, *_args) -> None:
        self._close_message_reader_for_scope_change()
        self._update_show_all_message_groups_style()
        if hasattr(self, "operating_group_filter"):
            commstat_state = self._commstat_group_state()
            group_sources = self._message_group_source_map(self._message_rows)
            selected_values, select_all_when_empty = _core_message_group_rebuild_selection(
                group_sources,
                current_selected=self.operating_group_filter.selected_values(),
                current_all_selected=self.operating_group_filter.all_selected(),
                fio_configured_groups=self._configured_message_group_names(),
                commstat_active_groups=self._message_group_candidate_set(commstat_state.active_groups),
                commstat_configured_groups=self._message_group_candidate_set(commstat_state.configured_groups),
                show_all_groups=self._show_all_message_groups_enabled(),
                prefer_primary=self._show_all_message_groups_enabled(),
            )
            self.operating_group_filter.set_grouped_options(
                self._message_group_option_sections_from_sources(group_sources),
                selected_values=selected_values,
                select_all_when_empty=select_all_when_empty,
            )
        self._refresh_basic_filter_button_texts()
        self._on_filter_changed()

    def _update_show_all_message_groups_style(self) -> None:
        if not hasattr(self, "show_all_message_groups_chk"):
            self._refresh_basic_filter_button_texts()
            return
        theme = resolve_theme(self.settings)
        role = "secondary" if self._show_all_message_groups_enabled() else "muted"
        self.show_all_message_groups_chk.setStyleSheet(button_style(role, theme))
        self.show_all_message_groups_chk.setText("All Groups" if self._show_all_message_groups_enabled() else "Configured")
        self.show_all_message_groups_chk.setToolTip(
            "Operating Group list is expanded to every discovered group."
            if self._show_all_message_groups_enabled()
            else "Operating Group list is focused on configured and CommStat active groups."
        )
        self.show_all_message_groups_chk.setVisible(False)
        self._refresh_basic_filter_button_texts()

    def _refresh_basic_filter_button_texts(self) -> None:
        group_filter = getattr(self, "operating_group_filter", None)
        if group_filter is not None:
            try:
                group_filter.refresh_text()
                if group_filter.all_selected():
                    text = "Groups: All" if self._show_all_message_groups_enabled() else "Groups: Configured"
                    group_filter.setText(text)
                    group_filter.setToolTip(
                        "Showing every discovered group."
                        if self._show_all_message_groups_enabled()
                        else "Showing configured and CommStat active groups."
                    )
                action_label = (
                    "Show configured groups only"
                    if self._show_all_message_groups_enabled()
                    else "Show all discovered groups"
                )
                group_filter.set_prefix_actions([(action_label, self._toggle_message_groups_mode_from_menu)])
            except Exception:
                pass
        source_filter = getattr(self, "source_filter", None)
        if source_filter is not None:
            try:
                source_filter.refresh_text()
                selected = source_filter.selected_values()
                if len(selected) == 1:
                    only = next(iter(selected))
                    source_filter.setText(f"Sources: {source_filter.option_label(only)}")
                    source_filter.setToolTip(f"Sources: {source_filter.option_label(only)}")
            except Exception:
                pass

    def _on_filter_changed(self) -> None:
        left_ops_scope = False
        if not getattr(self, "_projected_table_loading", False):
            left_ops_scope = self._leave_ops_traffic_scope()
        self._close_message_reader_for_scope_change()
        self._unfreeze_table()
        self._update_excluded_types_button_state()
        self._refresh_basic_filter_button_texts()
        # Even before the Ops publication lands, exiting must supersede its
        # pending request rather than reuse an identical previous Inbox key.
        if left_ops_scope and self._load_projected_messages_into_table():
            return
        if not getattr(self, "_projected_table_loading", False) and self._reload_projected_messages_for_scope_change():
            return
        self._apply_message_filters_light()

    def _render_messages_table(self, rows: List[UnifiedMessage]) -> None:
        self.messages_table.setUpdatesEnabled(False)
        self._messages_model.set_rows_for_generation(
            rows,
            int(getattr(self, "_active_projection_generation", 0) or 0),
        )
        if not self._has_active_view:
            self._clear_message_detail_view("No file selected")
            self.current_record = None
            self.current_js8 = None
            self.current_sitrep = None
            self.current_commstat = None
        self.messages_table.setUpdatesEnabled(True)
        self._message_table_fit_signature = None
        self._queue_message_table_column_fit()
        self._update_bulk_delete_buttons()
        self._update_mark_all_read_style()

    def _message_row_from_index(self, index: QModelIndex) -> UnifiedMessage | None:
        if not index.isValid() or not hasattr(self, "_messages_model"):
            return None
        row = index.data(Qt.UserRole)
        if isinstance(row, UnifiedMessage):
            return row
        try:
            model_row = int(index.row())
        except Exception:
            return None
        rows = self._messages_model.rows()
        if 0 <= model_row < len(rows):
            return rows[model_row]
        return None

    def _on_message_table_activated(self, index: QModelIndex) -> None:
        if not index.isValid():
            return
        # Column 0 is selection and column 7 has explicit View/Delete actions.
        if index.column() in {0, 7}:
            return
        row = self._message_row_from_index(index)
        if row is not None:
            self._on_view_message(row)

    def _update_bulk_delete_buttons(self) -> None:
        theme = resolve_theme(self.settings)
        rows = self._messages_model.selected_rows() if hasattr(self, "_messages_model") else []
        count = len(rows)
        has_selection = count > 0
        unread_count = sum(1 for row in rows if (row.status or "").upper() != "READ")
        delete_tooltip = self._delete_effect_tooltip(rows)
        if hasattr(self, "delete_selected_btn"):
            # Keep the legacy left-rail delete button out of the normal Inbox
            # flow. Bulk actions live inline above the table so selection does
            # not create a sudden red action surface away from the messages.
            self.delete_selected_btn.setEnabled(False)
            self.delete_selected_btn.setVisible(False)
            self.delete_selected_btn.setStyleSheet(button_style("muted", theme))
        if hasattr(self, "export_selected_btn"):
            self.export_selected_btn.setEnabled(has_selection)
            role = "eligible_warning" if has_selection else "muted"
            self.export_selected_btn.setStyleSheet(button_style(role, theme))
        if hasattr(self, "bulk_selection_bar"):
            self.bulk_selection_bar.setVisible(has_selection)
            self.bulk_selection_bar.setStyleSheet(
                "QFrame#messageBulkSelectionBar {"
                f"background-color: {theme.get('surface_alt', '#E8EDF3')};"
                f"border: 1px solid {theme.get('border', '#CCD6E0')};"
                "border-radius: 6px;"
                "}"
            )
            self.bulk_selection_bar.setToolTip(delete_tooltip)
        if hasattr(self, "bulk_selection_label"):
            source_summary = self._summarize_types(rows) if rows else ""
            label = f"{count} selected"
            if source_summary:
                label = f"{label} | {source_summary}"
            self.bulk_selection_label.setText(label)
            self.bulk_selection_label.setToolTip(delete_tooltip)
        if hasattr(self, "bulk_mark_read_btn"):
            self.bulk_mark_read_btn.setEnabled(unread_count > 0)
            self.bulk_mark_read_btn.setText(f"Mark Read ({unread_count})" if unread_count else "Mark Read")
            self.bulk_mark_read_btn.setToolTip(
                "Mark selected unread messages as READ." if unread_count else "Selected messages are already read."
            )
            self.bulk_mark_read_btn.setStyleSheet(button_style("eligible_warning" if unread_count else "muted", theme))
        if hasattr(self, "bulk_delete_btn"):
            self.bulk_delete_btn.setEnabled(has_selection)
            self.bulk_delete_btn.setStyleSheet(button_style("eligible_danger" if has_selection else "muted", theme))
            self.bulk_delete_btn.setToolTip(delete_tooltip)
        if hasattr(self, "bulk_clear_btn"):
            self.bulk_clear_btn.setEnabled(has_selection)
            self.bulk_clear_btn.setStyleSheet(button_style("muted", theme))
        self._refresh_more_actions_menu()
        self._sync_select_all_checkbox()
        self._update_mark_all_read_style()

    def _mark_selected_read(self) -> None:
        rows = self._messages_model.selected_rows() if hasattr(self, "_messages_model") else []
        unread_rows = [row for row in rows if (row.status or "").upper() != "READ"]
        if not unread_rows:
            if hasattr(self, "message_check_status_label"):
                self.message_check_status_label.setText("Selected messages are already read.")
            return
        changed = self._mark_rows_read_bulk(unread_rows)
        if changed > 0:
            self._messages_model.clear_selection()
            self._apply_message_filters_preserve_scroll()
            if hasattr(self, "message_check_status_label"):
                self.message_check_status_label.setText(f"Marked {changed} selected message(s) as READ.")
        else:
            self._update_bulk_delete_buttons()
            if hasattr(self, "message_check_status_label"):
                self.message_check_status_label.setText("No selected messages were updated.")

    def _delete_selected_messages(self) -> None:
        rows = self._messages_model.selected_rows()
        deletable = self._collect_deletable_rows(rows)
        if not deletable:
            QMessageBox.information(self, "Delete Selected", "No deletable messages selected.")
            return
        if not self._confirm_bulk_delete(deletable, "Delete selected messages?"):
            return
        self._bulk_delete_rows(deletable)

    @staticmethod
    def _collect_deletable_rows(rows: List[UnifiedMessage]) -> List[UnifiedMessage]:
        return list(collect_deletable_message_rows(rows))

    @staticmethod
    def _summarize_types(rows: List[UnifiedMessage]) -> str:
        return summarize_delete_sources(rows)

    def _confirm_bulk_delete(self, rows: List[UnifiedMessage], prompt: str) -> bool:
        msg = self._bulk_delete_confirmation_text(rows, prompt)
        resp = QMessageBox.question(self, "Delete Messages", msg, QMessageBox.Yes | QMessageBox.No)
        return resp == QMessageBox.Yes

    @staticmethod
    def _delete_source_label(row: UnifiedMessage) -> str:
        return delete_source_label_for_row(row)

    @staticmethod
    def _delete_effect_label(row: UnifiedMessage) -> str:
        return delete_effect_label_for_row(row)

    @staticmethod
    def _summarize_delete_effects(rows: Sequence[UnifiedMessage]) -> str:
        return summarize_delete_effects(rows)

    @staticmethod
    def _delete_effect_tooltip(rows: Sequence[UnifiedMessage]) -> str:
        return delete_effect_tooltip(rows)

    def _current_age_filter_label(self) -> str:
        if not hasattr(self, "received_filter"):
            return ""
        if _core_age_filter_bounds(self.received_filter.currentData()) == _core_age_filter_bounds(
            DEFAULT_RECEIVED_FILTER_SECONDS
        ):
            return ""
        return str(self.received_filter.currentText() or "").strip()

    def _active_message_scope_summary(self) -> str:
        if getattr(self, "_ops_traffic_message_ids", None) is not None:
            return f"Ops Center traffic; Action {str(self._traffic_action_filter or 'All').title()}; Inbox filters suspended"
        focus = str(getattr(self, "_inbox_focus", "all") or "all").strip().lower()
        focus_labels = {key: label for key, label, _tip in self._inbox_focus_options()}
        summary = active_inbox_scope_summary(
            focus=focus,
            focus_labels=focus_labels,
            groups=self._selected_message_groups() if self._message_group_filter_active() else None,
            sources=self._selected_message_sources(),
            age_label=self._current_age_filter_label(),
            search_query=(self.rcv_search.text() if hasattr(self, "rcv_search") else "").strip(),
            type_sel=self.type_filter.currentText() if hasattr(self, "type_filter") else "MSG Type...",
            status_sel=self.status_filter.currentText() if hasattr(self, "status_filter") else "Status...",
            from_sel=self.from_filter.currentText() if hasattr(self, "from_filter") else "",
            to_sel=self.to_filter.currentText() if hasattr(self, "to_filter") else "",
        )
        context = getattr(self, "_map_context_filter", {}) or {}
        intel_parts = []
        if getattr(self, "_intel_status_filter", ""):
            intel_parts.append(f"Status {str(self._intel_status_filter).title()}")
        if getattr(self, "_intel_topic_filter", ""):
            intel_parts.append(f"Topic {self._intel_topic_filter}")
        if getattr(self, "_traffic_action_filter", ""):
            intel_parts.append(f"Action {str(self._traffic_action_filter).title()}")
        if isinstance(context, dict) and context.get("concern_only"):
            geo_parts = []
            state_filter = str(context.get("state_filter") or "").strip().upper()
            fema_region_filter = str(context.get("fema_region_filter") or "").strip().upper()
            if state_filter:
                geo_parts.append(f"Map State {state_filter}")
            if fema_region_filter:
                geo_parts.append(f"Map FEMA Region {fema_region_filter}")
            geo_parts.append("non-green/status evidence only")
            map_summary = "; ".join([" ".join(geo_parts), *intel_parts])
            return f"{summary}; {map_summary}" if summary else map_summary
        if intel_parts:
            intel_summary = "; ".join(intel_parts)
            return f"{summary}; {intel_summary}" if summary else intel_summary
        return summary

    def _update_map_context_filter_label(self) -> None:
        label = getattr(self, "map_context_filter_label", None)
        if label is None:
            return
        context = getattr(self, "_map_context_filter", {}) or {}
        active = bool(isinstance(context, dict) and context) and getattr(self, "_ops_traffic_message_ids", None) is None
        if not active:
            label.setText("")
            label.setVisible(False)
            return
        summary = self._active_message_scope_summary() or "map-selected evidence"
        label.setText(f"Map filter active: {summary}. Use Clear Filters to return to the normal inbox.")
        label.setVisible(str(getattr(self, "_messages_mode", "Inbox") or "Inbox") != "Compose")

    @staticmethod
    def _bulk_delete_sample_lines(rows: Sequence[UnifiedMessage], *, limit: int = 8) -> List[str]:
        return bulk_delete_sample_lines(rows, limit=limit)

    @staticmethod
    def _bulk_delete_confirmation_text(rows: Sequence[UnifiedMessage], prompt: str = "Delete selected messages?") -> str:
        return bulk_delete_confirmation_text(rows, prompt=prompt)

    @staticmethod
    def _bulk_delete_completion_text(
        *,
        deleted: int,
        skipped: int,
        failed: int,
        source_summary: str,
        detail_counts: Dict[str, int],
    ) -> str:
        return bulk_delete_completion_text(
            deleted=deleted,
            skipped=skipped,
            failed=failed,
            source_summary=source_summary,
            detail_counts=detail_counts,
        )

    @staticmethod
    def _single_delete_confirmation_text(row: UnifiedMessage, prompt: str = "Delete this message?") -> str:
        return single_delete_confirmation_text(row, prompt=prompt)

    def _confirm_single_delete(self, row: UnifiedMessage, prompt: str = "Delete this message?") -> bool:
        msg = self._single_delete_confirmation_text(row, prompt)
        resp = QMessageBox.question(self, "Delete Message", msg, QMessageBox.Yes | QMessageBox.No)
        return resp == QMessageBox.Yes

    @staticmethod
    def _single_delete_success_text(row: UnifiedMessage, *, hidden: bool = False) -> str:
        return single_delete_success_text(row, hidden=hidden)

    def _finalize_single_delete_success(self, row: UnifiedMessage, outcome: MessageDeleteExecutionResult) -> None:
        self._record_message_delete_audit(
            row,
            result="deleted",
            detail=message_delete_result_detail(row.payload, outcome.detail_key),
            batch_id="single",
        )
        if not isinstance(row.payload, ProjectedMessagePayload):
            self._mark_projection_rows_deleted([row], source_scope="single")
        self._remember_locally_deleted_row(row)
        self._unfreeze_table()
        self._populate_messages_table(force=True)
        QMessageBox.information(self, "Delete Message", self._single_delete_success_text(row, hidden=outcome.hidden))

    def _clear_message_detail_view(self, label: str = "No message selected") -> None:
        if getattr(self, "_reader_open", False):
            self._close_message_reader(clear_content=True, cleared_label=label)
        else:
            self._set_open_external_path(None)
            self.info_label.setText(label)
            self.viewer.clear()

    @staticmethod
    def _delete_audit_row_key(row: UnifiedMessage) -> str:
        key = MessageTableModel._row_key(row)
        try:
            return json.dumps(key, default=str, separators=(",", ":")) if key is not None else ""
        except Exception:
            return str(key or "")

    @staticmethod
    def _delete_audit_safe_text(value: object, *, limit: int = 160) -> str:
        return safe_audit_text(value, limit=limit)

    @staticmethod
    def _delete_audit_action(row: UnifiedMessage) -> str:
        return delete_audit_action_for_row(row)

    @staticmethod
    def _delete_audit_row_for_payload(payload: object) -> UnifiedMessage:
        if isinstance(payload, FileRecord):
            return UnifiedMessage(
                msg_type=str(payload.origin or "File").upper(),
                status="",
                from_call="",
                to_call="",
                rcv_ts=float(payload.mtime or 0.0),
                rcv_display="",
                title=payload.path.name,
                origin=str(payload.origin or "file"),
                payload=payload,
            )
        if isinstance(payload, JS8Message):
            return unified_message_from_presentation(
                js8_message_row_presentation(payload),
                payload=payload,
                rcv_display="",
            )
        if isinstance(payload, SpotterMessage):
            return unified_message_from_presentation(
                spotter_message_row_presentation(payload),
                payload=payload,
                rcv_display="",
            )
        if isinstance(payload, VarACMessage):
            return unified_message_from_presentation(
                varac_message_row_presentation(payload),
                payload=payload,
                rcv_display="",
            )
        if isinstance(payload, SitrepMessage):
            return unified_message_from_presentation(
                sitrep_message_row_presentation(payload),
                payload=payload,
                rcv_display="",
            )
        if isinstance(payload, CommStatArtifact):
            return unified_message_from_presentation(
                commstat_message_row_presentation(payload),
                payload=payload,
                rcv_display="",
            )
        return UnifiedMessage("Message", "", "", "", 0.0, "", "", "message", payload)

    def _record_message_delete_audit(
        self,
        row: UnifiedMessage,
        *,
        result: str,
        detail: str = "",
        batch_id: str = "",
    ) -> None:
        if not isinstance(row, UnifiedMessage):
            return
        db_path = self._db_path()
        if not db_path:
            return
        try:
            record_message_delete_audit(
                db_path,
                batch_id=str(batch_id or ""),
                source=self._delete_source_label(row),
                action=self._delete_audit_action(row),
                result=str(result or "").strip().lower() or "unknown",
                row_key=self._delete_audit_row_key(row),
                from_call=row.from_call,
                to_call=row.to_call,
                title=row.title,
                detail=detail,
            )
        except Exception as e:
            log.debug("MessageViewer: failed to record delete audit: %s", e)

    def _execute_message_delete(self, row: UnifiedMessage) -> MessageDeleteExecutionResult:
        payload = row.payload
        if isinstance(payload, ProjectedMessagePayload):
            db_path = self._db_path()
            if db_path is None or not payload.message_id:
                return missing_identity_delete_result()
            try:
                mark_projected_message_rows_deleted(
                    db_path,
                    [row],
                    requested_effect="source_delete",
                    requested_by="fio",
                    source_scope="projection",
                )
                process_message_delete_queue(db_path, limit=25)
                return delete_success_result("hidden", hidden=True)
            except Exception as exc:
                log.debug("MessageViewer: projected message delete failed: %s", exc)
                return failed_source_delete_result(payload)
        if isinstance(payload, JS8Message):
            msg_id = int(getattr(payload, "msg_id", 0) or 0)
            if msg_id <= 0:
                return missing_identity_delete_result()
            if not self._delete_js8_inbox_row(payload):
                return failed_source_delete_result(payload)
            self._delete_js8_local_row(payload)
            self.js8_messages = [m for m in self.js8_messages if not self._same_js8_message(m, payload)]
            if self.current_js8 and self._same_js8_message(self.current_js8, payload):
                self.current_js8 = None
                self._clear_message_detail_view()
            return delete_success_result()
        if isinstance(payload, VarACMessage):
            msg_id = int(getattr(payload, "msg_id", 0) or 0)
            if msg_id <= 0:
                return missing_identity_delete_result()
            if not self._soft_delete_varac_row(payload):
                return failed_source_delete_result(payload)
            self._delete_varac_local_row(payload)
            self.varac_messages = [m for m in self.varac_messages if not self._same_varac_message(m, payload)]
            if (
                self.current_record is None
                and self.current_js8 is None
                and self.current_sitrep is None
                and self.current_commstat is None
            ):
                self._clear_message_detail_view()
            return delete_success_result()
        if isinstance(payload, SpotterMessage):
            msg_id = int(getattr(payload, "spotter_id", 0) or 0)
            if msg_id <= 0:
                return missing_identity_delete_result()
            if not self._delete_spotter_row(msg_id):
                return failed_source_delete_result(payload)
            self.spotter_messages = [m for m in self.spotter_messages if m.spotter_id != msg_id]
            if (
                self.current_js8 is None
                and self.current_record is None
                and self.current_sitrep is None
                and self.current_commstat is None
            ):
                self._clear_message_detail_view()
            return delete_success_result()
        if isinstance(payload, SitrepMessage):
            if not self._delete_sitrep_row(payload):
                return failed_source_delete_result(payload)
            msg_key = self._sitrep_message_key(payload)
            self.sitrep_messages = [
                m for m in self.sitrep_messages if self._sitrep_message_key(m) != msg_key
            ]
            if self.current_sitrep and self._sitrep_message_key(self.current_sitrep) == msg_key:
                self.current_sitrep = None
                self._clear_message_detail_view()
            return delete_success_result()
        if isinstance(payload, CommStatArtifact):
            result = self._delete_commstat_row(payload)
            outcome = commstat_delete_execution_result(result)
            if outcome.result != "deleted":
                return outcome
            msg_key = self._commstat_message_key(payload)
            self.commstat_messages = [
                m for m in self.commstat_messages if self._commstat_message_key(m) != msg_key
            ]
            if self.current_commstat and self._commstat_message_key(self.current_commstat) == msg_key:
                self.current_commstat = None
                self._clear_message_detail_view()
            return outcome
        if isinstance(payload, FileRecord):
            if not payload.path.exists():
                return missing_identity_delete_result()
            if not self._send_to_recycle_bin(payload.path):
                return failed_source_delete_result(payload)
            log.info("MessageViewer: deleted file %s", payload.path)
            self._remove_file_record(payload)
            return delete_success_result()
        return missing_identity_delete_result()

    def _delete_projected_message(self, row: UnifiedMessage) -> None:
        if not isinstance(getattr(row, "payload", None), ProjectedMessagePayload):
            return
        if not self._confirm_single_delete(row):
            return
        outcome = self._execute_message_delete(row)
        if outcome.result != "deleted":
            QMessageBox.warning(self, "Delete Message", single_delete_failure_warning(row, outcome.warning))
            return
        self._finalize_single_delete_success(row, outcome)

    def _bulk_delete_rows(self, rows: List[UnifiedMessage]) -> None:
        batch_id = f"bulk-{int(time.time() * 1000)}-{len(rows)}"
        deleted = 0
        failed = 0
        skipped = 0
        deleted_rows: List[UnifiedMessage] = []
        detail_counts: Dict[str, int] = {}
        for row in rows:
            payload = row.payload
            outcome = self._execute_message_delete(row)
            if outcome.result == "deleted":
                deleted += 1
                detail_counts[outcome.detail_key] = detail_counts.get(outcome.detail_key, 0) + 1
                if outcome.deleted_row:
                    deleted_rows.append(row)
                self._record_message_delete_audit(row, result="deleted", detail=message_delete_result_detail(payload, outcome.detail_key), batch_id=batch_id)
            elif outcome.result == "skipped":
                skipped += 1
                self._record_message_delete_audit(row, result="skipped", detail=message_delete_result_detail(payload, outcome.detail_key), batch_id=batch_id)
            else:
                failed += 1
                self._record_message_delete_audit(row, result="failed", detail=message_delete_result_detail(payload, outcome.detail_key), batch_id=batch_id)
        for row in deleted_rows:
            self._remember_locally_deleted_row(row)
        source_deleted_rows = [
            row for row in deleted_rows if not isinstance(getattr(row, "payload", None), ProjectedMessagePayload)
        ]
        self._mark_projection_rows_deleted(source_deleted_rows, source_scope="bulk")
        self._messages_model.clear_selection()
        self._unfreeze_table()
        self._remove_deleted_rows_from_current_view(deleted_rows)
        self._populate_messages_table(force=True)
        summary = self._summarize_types(rows)
        details = self._bulk_delete_completion_text(
            deleted=deleted,
            skipped=skipped,
            failed=failed,
            source_summary=summary,
            detail_counts=detail_counts,
        )
        QMessageBox.information(self, "Delete Messages", details)

    def _mark_projection_rows_deleted(self, rows: Sequence[UnifiedMessage], *, source_scope: str) -> None:
        db_path = self._db_path()
        if db_path is None or not rows:
            return
        try:
            mark_projected_message_rows_deleted(
                db_path,
                rows,
                requested_effect="source_delete",
                requested_by="fio",
                source_scope=source_scope,
            )
        except Exception as e:
            log.debug("MessageViewer: failed to mark projected messages deleted: %s", e)

    def _mark_rows_read_bulk(self, rows: List[UnifiedMessage]) -> int:
        ts = time.time()
        js8_rows: List[JS8Message] = []
        spotter_rows: List[SpotterMessage] = []
        varac_rows: List[VarACMessage] = []
        file_rows: List[FileRecord] = []
        projected_rows: List[ProjectedMessagePayload] = []
        for row in rows:
            payload = row.payload
            if isinstance(payload, JS8Message) and payload.msg_id > 0 and payload.state.upper() != "READ":
                js8_rows.append(payload)
            elif isinstance(payload, SpotterMessage) and payload.spotter_id > 0 and payload.state.upper() != "READ":
                spotter_rows.append(payload)
            elif isinstance(payload, VarACMessage) and payload.msg_id > 0 and int(payload.read_status or 0) == 0:
                varac_rows.append(payload)
            elif isinstance(payload, FileRecord):
                key = self._read_state_key(payload.origin, payload)
                status = (self._read_state_map.get(key, ("NEW", 0.0, 0))[0] or "").upper()
                if status != "READ":
                    file_rows.append(payload)
            elif isinstance(payload, ProjectedMessagePayload) and str(payload.read_state or "").lower() != "read":
                projected_rows.append(payload)

        if js8_rows:
            self._mark_js8_rows_read_bulk(js8_rows, ts)
        if spotter_rows:
            self._mark_spotter_rows_read_bulk(spotter_rows, ts)
        if varac_rows:
            self._mark_varac_rows_read_bulk(varac_rows)
        if file_rows:
            self._set_read_state_bulk(file_rows, "READ", ts)
        if projected_rows:
            db_path = self._db_path()
            if db_path is not None:
                try:
                    mark_projected_messages_read(db_path, [msg.message_id for msg in projected_rows])
                    projected_file_records = [
                        rec
                        for msg in projected_rows
                        for rec in [self._projected_file_record(msg, allow_detail_lookup=False)]
                        if rec is not None
                    ]
                    if projected_file_records:
                        self._set_read_state_bulk(projected_file_records, "READ", ts)
                except Exception as exc:
                    log.debug("MessageViewer: failed to mark projected rows read in bulk: %s", exc)

        changed = 0
        for row in rows:
            prev = (row.status or "").upper()
            payload = row.payload
            now_read = False
            if isinstance(payload, JS8Message):
                now_read = payload.state.upper() == "READ"
            elif isinstance(payload, SpotterMessage):
                now_read = payload.state.upper() == "READ"
            elif isinstance(payload, VarACMessage):
                now_read = int(payload.read_status or 0) == 1
            elif isinstance(payload, FileRecord):
                key = self._read_state_key(payload.origin, payload)
                now_read = ((self._read_state_map.get(key, ("NEW", 0.0, 0))[0] or "").upper() == "READ")
            elif isinstance(payload, ProjectedMessagePayload):
                now_read = str(payload.read_state or "").lower() == "read" or payload in projected_rows
            if now_read:
                row.status = "READ"
                if isinstance(payload, ProjectedMessagePayload):
                    payload.status = "READ"
                    payload.read_state = "read"
                if prev != "READ":
                    changed += 1
        return changed

    def _mark_js8_rows_read_bulk(self, msgs: List[JS8Message], read_ts: float) -> None:
        dedup: Dict[tuple[str, int, int], JS8Message] = {}
        for msg in msgs:
            if msg.msg_id > 0:
                source_key = str(getattr(msg, "source_key", "") or "").strip()
                native_id = int(getattr(msg, "source_id", 0) or getattr(msg, "msg_id", 0) or 0)
                dedup[(source_key, native_id, int(msg.msg_id))] = msg
        if not dedup:
            return
        self._save_js8_state_bulk(list(dedup.values()), read_ts)
        self._update_local_read_bulk(sorted({int(msg.msg_id) for msg in dedup.values()}), read_ts)
        if self.settings.get("js8_inbox_mark_retrieved_sync", False):
            updated = self._mark_js8call_inbox_read_messages(list(dedup.values()))
            log.debug(
                "MessageViewer: mark-all JS8 inbox sync updated %s/%s rows",
                updated,
                len(dedup),
            )
        for msg in dedup.values():
            msg.state = "READ"
            msg.read_ts = read_ts

    def _mark_spotter_rows_read_bulk(self, msgs: List[SpotterMessage], read_ts: float) -> None:
        ids = sorted({int(msg.spotter_id) for msg in msgs if int(msg.spotter_id or 0) > 0})
        if not ids:
            return
        db_path = self._db_path()
        if db_path and db_path.exists():
            try:
                conn = sqlite3.connect(db_path)
                cur = conn.cursor()
                for start in range(0, len(ids), 250):
                    chunk = ids[start : start + 250]
                    placeholders = ",".join("?" for _ in chunk)
                    cur.execute(
                        f"UPDATE spotter_traffic SET state='READ', read_ts=? WHERE id IN ({placeholders})",
                        (float(read_ts), *chunk),
                    )
                conn.commit()
                conn.close()
            except Exception as e:
                log.debug("MessageViewer: bulk spotter read update failed: %s", e)
        for msg in msgs:
            msg.state = "READ"
            msg.read_ts = read_ts

    def _mark_varac_rows_read_bulk(self, msgs: List[VarACMessage]) -> None:
        triples = sorted(
            {
                (str(getattr(msg, "source_key", "") or ""), str(msg.source or ""), int(msg.msg_id))
                for msg in msgs
                if int(msg.msg_id or 0) > 0
            }
        )
        pairs = [(source, msg_id) for source_key, source, msg_id in triples if not source_key]
        keyed = [(source_key, source, msg_id) for source_key, source, msg_id in triples if source_key]
        if not triples:
            return
        if not keyed:
            pairs = [(source, msg_id) for _source_key, source, msg_id in triples]
        if not pairs:
            pairs = []
        db_path = self._db_path()
        if db_path and db_path.exists():
            try:
                conn = sqlite3.connect(db_path)
                cur = conn.cursor()
                has_source_key = self._table_has_column(conn, "varac_messages", "ingest_source_key")
                if keyed and has_source_key:
                    cur.executemany(
                        "UPDATE varac_messages SET read_status=1 WHERE ingest_source_key=? AND source=? AND id=?",
                        keyed,
                    )
                elif keyed:
                    pairs.extend((source, msg_id) for _source_key, source, msg_id in keyed)
                if pairs:
                    cur.executemany(
                        "UPDATE varac_messages SET read_status=1 WHERE source=? AND id=?",
                        pairs,
                    )
                conn.commit()
                conn.close()
            except Exception as e:
                log.debug("MessageViewer: bulk VarAC read update failed: %s", e)
        for msg in msgs:
            msg.read_status = 1

    def _set_read_state_bulk(self, recs: List[FileRecord], status: str, read_ts: float) -> None:
        status = (status or "READ").upper()
        if status != "READ":
            return
        dedup: Dict[tuple, FileRecord] = {}
        for rec in recs:
            dedup[self._read_state_key(rec.origin, rec)] = rec
        if not dedup:
            return
        rows: List[Tuple[str, str, float, int, str, float, int]] = []
        for key, rec in dedup.items():
            flag_state = self._get_flag_state(rec)
            self._read_state_map[key] = ("READ", float(read_ts), int(flag_state))
            rows.append(
                (
                    str(rec.origin or "").strip().lower(),
                    str(rec.path),
                    float(rec.mtime),
                    int(rec.size),
                    "READ",
                    float(read_ts),
                    int(flag_state),
                )
            )
        db_path = self._db_path()
        if not db_path:
            return
        try:
            conn = sqlite3.connect(db_path)
            cur = conn.cursor()
            cur.executemany(
                """
                INSERT OR REPLACE INTO message_read_state
                    (origin, path, mtime, size, status, read_ts, flag_state)
                VALUES (?, ?, ?, ?, ?, ?, ?)
                """,
                rows,
            )
            conn.commit()
            conn.close()
        except Exception as e:
            log.debug("MessageViewer: bulk file read-state update failed: %s", e)

    def _save_js8_state_bulk(self, msgs: List[JS8Message], read_ts: float) -> None:
        db_path = self._local_js8_db()
        if not db_path:
            return
        if not msgs:
            return
        try:
            conn = sqlite3.connect(db_path)
            cur = conn.cursor()
            cur.execute(
                "CREATE TABLE IF NOT EXISTS js8_inbox_state (id INTEGER PRIMARY KEY, state TEXT, last_seen REAL, read_ts REAL, last_ingested_id INTEGER)"
            )
            try:
                cur.execute("ALTER TABLE js8_inbox_state ADD COLUMN source_key TEXT")
            except Exception:
                pass
            try:
                cur.execute("ALTER TABLE js8_inbox_state ADD COLUMN source_id INTEGER")
            except Exception:
                pass
            rows = []
            for msg in msgs:
                source_key = str(getattr(msg, "source_key", "") or "").strip()
                native_id = int(getattr(msg, "source_id", 0) or getattr(msg, "msg_id", 0) or 0)
                if native_id <= 0:
                    continue
                rows.append(
                    (
                        self._js8_state_row_id(native_id, source_key),
                        float(getattr(msg, "utc_ts", 0.0) or 0.0),
                        float(read_ts),
                        source_key,
                        native_id,
                    )
                )
            cur.executemany(
                "INSERT INTO js8_inbox_state (id, state, last_seen, read_ts, source_key, source_id) VALUES (?, 'READ', ?, ?, ?, ?) "
                "ON CONFLICT(id) DO UPDATE SET state='READ', last_seen=excluded.last_seen, read_ts=excluded.read_ts, source_key=excluded.source_key, source_id=excluded.source_id",
                rows,
            )
            conn.commit()
            conn.close()
        except Exception as e:
            log.debug("MessageViewer: bulk js8 state save failed: %s", e)

    def _update_local_read_bulk(self, msg_ids: List[int], read_ts: float) -> None:
        db_path = self._local_js8_db()
        if not db_path or not Path(db_path).exists():
            return
        ids = [int(i) for i in msg_ids if int(i) > 0]
        if not ids:
            return
        try:
            conn = sqlite3.connect(db_path)
            cur = conn.cursor()
            cur.executemany(
                "UPDATE js8_messages SET state='READ', read_ts=? WHERE id=?",
                [(float(read_ts), int(msg_id)) for msg_id in ids],
            )
            conn.commit()
            conn.close()
        except Exception as e:
            log.debug("MessageViewer: bulk local js8 read update failed: %s", e)

    def _mark_js8call_inbox_read_by_ids(self, row_ids: List[int]) -> int:
        inbox_path = self._inbox_path()
        if not inbox_path or not inbox_path.exists():
            return 0
        pending = {int(rid) for rid in row_ids if int(rid) > 0}
        if not pending:
            return 0
        updated_count = 0
        candidates = [
            ("inbox_v1", "blob"),
            ("inbox_v1", "json"),
            ("inbox_v1", "message"),
            ("inbox", "blob"),
            ("inbox", "json"),
            ("inbox", "message"),
        ]
        try:
            conn = sqlite3.connect(inbox_path, timeout=1.5)
            cur = conn.cursor()
            cur.execute("PRAGMA busy_timeout = 1500")
            for table, col in candidates:
                if not pending:
                    break
                has_type_col = self._table_has_column(conn, table, "type")
                for id_expr in ("id", "rowid"):
                    if not pending:
                        break
                    remaining = sorted(pending)
                    table_usable = True
                    for start in range(0, len(remaining), 250):
                        chunk = remaining[start : start + 250]
                        placeholders = ",".join("?" for _ in chunk)
                        try:
                            cur.execute(
                                f"SELECT {id_expr} as id, {col} FROM {table} WHERE {id_expr} IN ({placeholders})",
                                chunk,
                            )
                            rows = cur.fetchall()
                        except Exception:
                            table_usable = False
                            break
                        if not rows:
                            continue
                        updates_blob: List[Tuple[str, str, int]] = []
                        updates_blob_only: List[Tuple[str, int]] = []
                        seen_ids: List[int] = []
                        for row_id, blob in rows:
                            rid = int(row_id or 0)
                            if rid <= 0:
                                continue
                            try:
                                parsed = json.loads(blob or "{}")
                            except Exception:
                                continue
                            if not isinstance(parsed, dict):
                                continue
                            current_type = str(parsed.get("type", "") or "").strip().upper()
                            if current_type == "DELIVERED":
                                seen_ids.append(rid)
                                continue
                            if current_type != "READ":
                                parsed["type"] = "READ"
                                new_blob = json.dumps(parsed, separators=(",", ":"))
                                if has_type_col:
                                    updates_blob.append((new_blob, "READ", rid))
                                else:
                                    updates_blob_only.append((new_blob, rid))
                                updated_count += 1
                            seen_ids.append(rid)
                        if updates_blob:
                            cur.executemany(
                                f"UPDATE {table} SET {col}=?, type=? WHERE {id_expr}=?",
                                updates_blob,
                            )
                        if updates_blob_only:
                            cur.executemany(
                                f"UPDATE {table} SET {col}=? WHERE {id_expr}=?",
                                updates_blob_only,
                            )
                        for rid in seen_ids:
                            pending.discard(rid)
                    if table_usable and not pending:
                        break
            conn.commit()
            conn.close()
        except Exception as e:
            log.debug("MessageViewer: bulk JS8Call inbox mark READ failed: %s", e)
        return updated_count

    def _mark_js8call_inbox_read_messages(self, msgs: List[JS8Message]) -> int:
        by_path: Dict[str, List[int]] = {}
        legacy_ids: List[int] = []
        for msg in msgs or []:
            native_id = int(getattr(msg, "source_id", 0) or getattr(msg, "msg_id", 0) or 0)
            if native_id <= 0:
                continue
            source_path = str(getattr(msg, "source_path", "") or "").strip()
            if source_path:
                by_path.setdefault(source_path, []).append(native_id)
            else:
                legacy_ids.append(native_id)
        updated = 0
        for source_path, ids in by_path.items():
            for row_id in sorted(set(ids)):
                if self._mark_js8call_inbox_read_by_id(row_id, inbox_path=source_path):
                    updated += 1
        if legacy_ids:
            updated += self._mark_js8call_inbox_read_by_ids(sorted(set(legacy_ids)))
        return updated

    def _build_messages_header(self) -> None:
        while self.messages_header_layout.count():
            item = self.messages_header_layout.takeAt(0)
            if item.widget():
                item.widget().deleteLater()
        self._header_cells = []
        self.messages_header.setVisible(False)
        self._update_clear_filters_style()
        self._update_mark_all_read_style()
        header = self.messages_table.horizontalHeader()
        if not self._messages_header_sync_connected:
            header.sectionResized.connect(self._sync_header_widths)
            # Catch first-show geometry recalcs that do not emit sectionResized.
            header.geometriesChanged.connect(self._sync_header_widths)
            self._messages_header_sync_connected = True
        QTimer.singleShot(0, self._sync_select_all_checkbox)

    def _set_initial_splitter_sizes(self) -> None:
        if not hasattr(self, "messages_splitter"):
            return
        row_height = self.messages_table.verticalHeader().defaultSectionSize()
        header_height = self.messages_header.sizeHint().height()
        target = (row_height * 5) + header_height + 12
        total = max(target * 3, 400)
        self._apply_inbox_primary_height_guard()
        self.messages_splitter.setSizes([target, total - target])
        self._sync_header_widths()

    def _unfreeze_table(self) -> None:
        if not self._freeze_messages_table:
            return
        self._freeze_messages_table = False
        if self._deferred_refresh:
            self._populate_messages_table(force=True)

    def _make_filter_cell(self, combo: QComboBox) -> QWidget:
        container = QWidget()
        layout = QVBoxLayout(container)
        layout.setContentsMargins(4, 0, 4, 0)
        layout.setSpacing(2)
        try:
            min_w = int(combo.fontMetrics().horizontalAdvance("MSG Type...") + 44)
        except Exception:
            min_w = 110
        combo.setMinimumWidth(max(110, min_w))
        combo.setMinimumContentsLength(6)
        combo.setSizeAdjustPolicy(QComboBox.AdjustToContents)
        combo.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        self._fit_filter_combo_popup(combo)
        layout.addWidget(combo)
        return container

    def _make_combo_searchable(self, combo: QComboBox, placeholder: str) -> None:
        combo.setEditable(True)
        combo.setInsertPolicy(QComboBox.NoInsert)
        combo.setStyleSheet("QComboBox { padding-right: 20px; } QComboBox::drop-down { width: 18px; }")
        completer = QCompleter(combo.model(), combo)
        completer.setCaseSensitivity(Qt.CaseInsensitive)
        completer.setFilterMode(Qt.MatchContains)
        completer.setCompletionMode(QCompleter.PopupCompletion)
        completer.activated.connect(lambda _: self._on_filter_changed())
        combo.setCompleter(completer)
        edit = combo.lineEdit()
        if edit is not None:
            edit.setPlaceholderText(placeholder)
            edit.editingFinished.connect(self._on_filter_changed)
            edit.textEdited.connect(lambda _: combo.completer().complete())
        self._fit_filter_combo_popup(combo)

    def _make_search_filter_cell(self, edit: QLineEdit) -> QWidget:
        container = QWidget()
        layout = QVBoxLayout(container)
        layout.setContentsMargins(4, 0, 4, 0)
        layout.setSpacing(2)
        try:
            min_w = int(edit.fontMetrics().horizontalAdvance("Search...") + 136)
        except Exception:
            min_w = 200
        edit.setMinimumWidth(max(200, min_w))
        edit.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        layout.addWidget(edit)
        return container

    def _fit_filter_combo_popup(self, combo: QComboBox) -> None:
        try:
            fm = combo.fontMetrics()
            text_w = 0
            for i in range(combo.count()):
                text_w = max(text_w, int(fm.horizontalAdvance(combo.itemText(i))))
            if combo.isEditable() and combo.lineEdit() is not None:
                ph = combo.lineEdit().placeholderText() or ""
                if ph:
                    text_w = max(text_w, int(fm.horizontalAdvance(ph)))
            popup_w = max(int(combo.width()), text_w + 52)
            popup_w = min(520, popup_w)
            view = combo.view()
            if view is not None:
                view.setMinimumWidth(popup_w)
        except Exception:
            pass

    def _apply_accessibility_width_guards(self) -> None:
        # Prevent control label clipping at larger text sizes.
        max_w = 360
        buttons = [
            getattr(self, "messages_help_btn", None),
            getattr(self, "messages_bbs_help_btn", None),
            getattr(self, "messages_manage_bbs_btn", None),
            getattr(self, "compose_refresh_forms_btn", None),
            getattr(self, "compose_reset_btn", None),
            getattr(self, "compose_inline_reset_btn", None),
            getattr(self, "compose_open_source_btn", None),
            getattr(self, "refresh_btn", None),
            getattr(self, "more_actions_btn", None),
            getattr(self, "bbs_manage_btn", None),
            getattr(self, "export_btn", None),
            getattr(self, "delete_selected_btn", None),
            getattr(self, "mark_all_read_btn", None),
            getattr(self, "time_toggle_btn", None),
            getattr(self, "exclude_types_btn", None),
            getattr(self, "clear_filters_btn", None),
            getattr(self, "open_external_btn", None),
        ]
        for btn in buttons:
            if btn is None:
                continue
            try:
                txt = str(btn.text() or "").strip()
            except Exception:
                txt = ""
            if not txt:
                continue
            try:
                needed = int(btn.fontMetrics().horizontalAdvance(txt.replace("&", "")) + 30)
            except Exception:
                continue
            try:
                current_min = int(btn.minimumWidth() or 0)
            except Exception:
                current_min = 0
            base = btn.property("_fio_base_min_width")
            try:
                base_w = int(base)
            except Exception:
                base_w = current_min
                try:
                    btn.setProperty("_fio_base_min_width", base_w)
                except Exception:
                    pass
            target = max(base_w, min(max_w, needed))
            try:
                btn.setMinimumWidth(target)
            except Exception:
                pass

        try:
            progress_w = int(self.loading_label.fontMetrics().horizontalAdvance("Indexing messages...") + 64)
            self._loading_progress.setFixedWidth(max(140, min(260, progress_w)))
        except Exception:
            pass

        for combo in (self.type_filter, self.status_filter, self.from_filter, self.to_filter):
            if combo is None:
                continue
            try:
                needed = int(combo.fontMetrics().horizontalAdvance("Status...") + 52)
            except Exception:
                continue
            try:
                current_min = int(combo.minimumWidth() or 0)
                base = combo.property("_fio_base_min_width")
                try:
                    base_w = int(base)
                except Exception:
                    base_w = current_min
                    combo.setProperty("_fio_base_min_width", base_w)
                combo.setMinimumWidth(max(base_w, min(220, needed)))
            except Exception:
                pass
            self._fit_filter_combo_popup(combo)
        try:
            search_needed = int(
                self.rcv_search.fontMetrics().horizontalAdvance(
                    "Search callsign, group, MCF/F! code, topic, state/grid, keyword..."
                )
                + 72
            )
            current_min = int(self.rcv_search.minimumWidth() or 0)
            base = self.rcv_search.property("_fio_base_min_width")
            try:
                base_w = int(base)
            except Exception:
                base_w = current_min
                self.rcv_search.setProperty("_fio_base_min_width", base_w)
            self.rcv_search.setMinimumWidth(max(base_w, min(640, search_needed)))
        except Exception:
            pass
        try:
            self._sync_header_widths()
        except Exception:
            pass
        try:
            font = self.font()
            guard_signature = (
                font.family(),
                round(float(font.pointSizeF()), 2),
                int(font.pixelSize()),
                int(font.weight()),
            )
        except Exception:
            guard_signature = ("", 0.0, 0, 0)
        if guard_signature != getattr(self, "_messages_text_size_guard_signature", None):
            apply_text_size_accessibility_guards(self, include_widths=False)
            self._messages_text_size_guard_signature = guard_signature

    @staticmethod
    def _make_header_spacer() -> QWidget:
        spacer = QWidget()
        return spacer

    def _sync_header_widths(self) -> None:
        if not hasattr(self, "messages_table"):
            return
        if not self._header_cells:
            return
        header = self.messages_table.horizontalHeader()
        fallback_widths = {
            0: (
                header.select_button_width_hint()
                if isinstance(header, MessageHeaderWithCheckbox)
                else 96
            ),
            1: 164,
            2: 88,
            3: 104,
            4: 120,
            5: 160,
            6: 92,
            7: 142,
        }
        for idx, widget in enumerate(self._header_cells):
            if widget is None:
                continue
            width = header.sectionSize(idx)
            if int(width) <= 1:
                try:
                    width = int(self.messages_table.columnWidth(idx))
                except Exception:
                    width = 0
            if int(width) <= 1:
                width = fallback_widths.get(idx, 60)
            if idx == 0:
                min_width = (
                    header.select_button_width_hint()
                    if isinstance(header, MessageHeaderWithCheckbox)
                    else 96
                )
            elif idx == 7:
                min_width = MessageActionDelegate.required_width(widget.fontMetrics())
            elif idx in (3, 4):
                min_width = 96
            else:
                min_width = 60
            widget.setFixedWidth(max(min_width, width))

    def _filters_active(self) -> bool:
        return (
            self.type_filter.currentText() not in ("", "MSG Type...")
            or self.status_filter.currentText() not in ("", "Status...")
            or self.from_filter.currentText() not in ("",)
            or self.to_filter.currentText() not in ("",)
            or self._source_filter_refinement_active()
            or self._message_group_filter_active()
            or bool(getattr(self, "_intel_status_filter", ""))
            or bool(getattr(self, "_intel_topic_filter", ""))
            or bool(getattr(self, "_traffic_action_filter", ""))
            or _core_age_filter_bounds(self.received_filter.currentData())
            != _core_age_filter_bounds(DEFAULT_RECEIVED_FILTER_SECONDS)
            or bool(getattr(self, "_map_context_filter", {}) or {})
            or bool(self.rcv_search.text().strip())
        )

    def _update_clear_filters_style(self) -> None:
        theme = resolve_theme(self.settings)
        active = self._filters_active()
        role = "eligible_warning" if active else "muted"
        self.clear_filters_btn.setStyleSheet(button_style(role, theme))
        self.clear_filters_btn.setToolTip(
            f"Clear active message filters: {self._active_message_scope_summary()}."
            if active
            else "No message filters are active."
        )
        self.clear_filters_btn.setVisible(True)

    def _mark_all_read_eligibility(self) -> tuple[bool, str]:
        type_sel = self.type_filter.currentText() if hasattr(self, "type_filter") else "MSG Type..."
        if type_sel in ("", "MSG Type..."):
            return False, "Select a Message Type filter first."
        rows = self._messages_model.rows()
        if not rows:
            return False, "No messages in current filtered view."
        if type_sel in {"Spotter", "CommStat", "JS8Call", "FLMSG/FLAMP"}:
            if any(not self._row_matches_type_filter(r, type_sel) for r in rows):
                return False, "Filtered rows are not scoped to one message type."
        else:
            if any((r.msg_type or "") != type_sel for r in rows):
                return False, "Filtered rows are not scoped to one message type."
        unread = sum(1 for r in rows if (r.status or "").upper() != "READ")
        if unread <= 0:
            return False, "No unread rows in current filtered view."
        return True, ""

    def _update_mark_all_read_style(self) -> None:
        theme = resolve_theme(self.settings)
        enabled, reason = self._mark_all_read_eligibility()
        self.mark_all_read_btn.setEnabled(enabled)
        self.mark_all_read_btn.setToolTip(reason if not enabled else "Mark all visible rows as READ.")
        role = "eligible_warning" if enabled else "muted"
        self.mark_all_read_btn.setStyleSheet(button_style(role, theme))

    def _mark_all_filtered_read(self) -> None:
        enabled, reason = self._mark_all_read_eligibility()
        if not enabled:
            QMessageBox.information(self, "Mark All as Read", reason or "Nothing to mark.")
            return
        type_sel = self.type_filter.currentText()
        rows = self._messages_model.rows()
        unread_rows = [r for r in rows if (r.status or "").upper() != "READ"]
        if not unread_rows:
            QMessageBox.information(self, "Mark All as Read", "No unread rows in current filtered view.")
            return
        prompt = (
            f"Mark {len(unread_rows)} unread {type_sel} message(s) as READ "
            f"in the current filtered view?"
        )
        if QMessageBox.question(self, "Mark All as Read", prompt, QMessageBox.Yes | QMessageBox.No) != QMessageBox.Yes:
            return
        changed = self._mark_rows_read_bulk(unread_rows)
        if changed <= 0:
            QMessageBox.information(self, "Mark All as Read", "No rows were updated.")
            return
        self._apply_message_filters_preserve_scroll()
        QMessageBox.information(self, "Mark All as Read", f"Marked {changed} message(s) as READ.")

    def _on_sort_clicked(self, section: int) -> None:
        if section == 0 or section >= 7:
            return
        self._close_message_reader_for_scope_change()
        if section == self._sort_column:
            self._sort_order = (
                Qt.AscendingOrder if self._sort_order == Qt.DescendingOrder else Qt.DescendingOrder
            )
        else:
            self._sort_column = section
            self._sort_order = Qt.AscendingOrder
        self._apply_message_filters()

    def _sync_select_all_checkbox(self) -> None:
        header = self.messages_table.horizontalHeader() if hasattr(self, "messages_table") else None
        if not isinstance(header, MessageHeaderWithCheckbox):
            return
        rows = self._messages_model.rows()
        selectable_rows = self._collect_deletable_rows(rows)
        keys = [MessageTableModel._row_key(r) for r in selectable_rows]
        keys = [k for k in keys if k is not None]
        enabled = bool(keys)
        if not keys:
            header.set_checkbox_state(Qt.Unchecked, enabled=False)
            return
        selected = 0
        for k in keys:
            if k in self._messages_model._selected_keys:
                selected += 1
        if selected == 0:
            header.set_checkbox_state(Qt.Unchecked, enabled=enabled)
        elif selected == len(keys):
            header.set_checkbox_state(Qt.Checked, enabled=enabled)
        else:
            header.set_checkbox_state(Qt.PartiallyChecked, enabled=enabled)

    def _on_header_checkbox_toggled(self, state: int) -> None:
        rows = self._messages_model.rows()
        state_val = int(getattr(state, "value", state))
        if state_val == Qt.PartiallyChecked.value:
            return
        target = state_val == Qt.Checked.value
        rows_to_update = self._collect_deletable_rows(rows) if target else rows
        self._messages_model.set_selected_for_rows(rows_to_update, target)
        self._update_bulk_delete_buttons()

    def _sort_rows(self, rows: List[UnifiedMessage]) -> List[UnifiedMessage]:
        reverse = self._sort_order == Qt.DescendingOrder
        col = self._sort_column
        profile = self._messages_model.display_profile() if hasattr(self, "_messages_model") else "triage"

        def key(row: UnifiedMessage):
            if profile in {"field_report", "field_summary"}:
                if col == 1:
                    return MessageTableModel._field_report_form(row)
                if col == 2:
                    return MessageTableModel._field_report_status(row)
                if col == 3:
                    return row.from_call or ""
                if col == 4:
                    return MessageTableModel._field_report_group(row)
                if col == 5:
                    if profile == "field_summary":
                        return row.title or ""
                    return MessageTableModel._field_report_area(row)
                if col == 6:
                    return row.rcv_ts or 0.0
                return row.rcv_ts or 0.0
            if profile == "form_message":
                if col == 1:
                    return row.title or ""
                if col == 2:
                    return row.display_type or row.msg_type or ""
                if col == 3:
                    return row.status or ""
                if col == 4:
                    return row.from_call or ""
                if col == 5:
                    return row.to_call or ""
                if col == 6:
                    return row.rcv_ts or 0.0
                return row.rcv_ts or 0.0
            if col == 1:
                return message_row_source_label(row)
            if col == 2:
                return row.status or ""
            if col == 3:
                return row.from_call or ""
            if col == 4:
                return row.to_call or ""
            if col == 5:
                return row.rcv_ts or 0.0
            if col == 6:
                return message_row_narrative_label(row)
            return row.rcv_ts or 0.0

        return sorted(rows, key=key, reverse=reverse)


    # ---------- Selection / Viewing ----------

    def _build_message_rows(self) -> List[UnifiedMessage]:
        rows: List[UnifiedMessage] = []
        dedupe_raw_spotter = bool(
            self._is_truthy(self.settings.get("sitrep_messages_dedupe_enabled", True), True)
            and not self._is_truthy(self.settings.get("sitrep_messages_show_raw_duplicates", False), False)
        )
        sitrep_report_keys: set[str] = set()
        sitrep_render_keys: set[str] = set()
        if dedupe_raw_spotter:
            for sitrep in self.sitrep_messages:
                key = _RowsBuildWorker._sitrep_message_semantic_key(sitrep, bucket_seconds=60)
                if key:
                    sitrep_report_keys.add(key)

        for msg in self.js8_messages:
            presentation = js8_message_row_presentation(
                msg,
                form_title_lookup=self._load_form_title,
                alert_predicate=self._form_is_alert,
            )
            if not self._form_visible_in_messages(presentation.msg_type):
                continue
            rcv_display = self._format_rcv_display(presentation.rcv_ts, msg.utc_str)
            rows.append(
                unified_message_from_presentation(
                    presentation,
                    payload=msg,
                    rcv_display=rcv_display,
                )
            )

        for msg in self.spotter_messages:
            if dedupe_raw_spotter:
                spotter_key = _RowsBuildWorker._spotter_message_report_key(msg)
                if spotter_key and spotter_key in sitrep_report_keys:
                    continue
            presentation = spotter_message_row_presentation(
                msg,
                form_title_lookup=self._load_form_title,
                alert_predicate=self._form_is_alert,
            )
            if not self._form_visible_in_messages(presentation.msg_type):
                continue
            rcv_display = self._format_rcv_display(presentation.rcv_ts, msg.utc_str)
            auth_map = self._spotter_msg_auth_state_for_message(msg)
            expect_map = self._spotter_expect_state_for_message(msg)
            rows.append(
                unified_message_from_presentation(
                    presentation,
                    payload=msg,
                    rcv_display=rcv_display,
                    auth_state=str(auth_map.get("status", "") or ""),
                    auth_detail=str(auth_map.get("detail", "") or ""),
                    auth_trusted=bool(auth_map.get("trusted", False)),
                    expect_decision=str(expect_map.get("decision", "") or ""),
                    expect_detail=str(expect_map.get("detail", "") or ""),
                )
            )

        for msg in self.varac_messages:
            presentation = varac_message_row_presentation(msg)
            rcv_display = self._format_rcv_display(presentation.rcv_ts, None)
            rows.append(
                unified_message_from_presentation(
                    presentation,
                    payload=msg,
                    rcv_display=rcv_display,
                )
            )

        for msg in self.sitrep_messages:
            if dedupe_raw_spotter:
                ui_key = _RowsBuildWorker._sitrep_message_semantic_key(msg, bucket_seconds=1)
                if ui_key and ui_key in sitrep_render_keys:
                    continue
                if ui_key:
                    sitrep_render_keys.add(ui_key)
            presentation = sitrep_message_row_presentation(msg)
            rcv_display = self._format_rcv_display(presentation.rcv_ts, msg.event_ts_utc)
            rows.append(
                unified_message_from_presentation(
                    presentation,
                    payload=msg,
                    rcv_display=rcv_display,
                )
            )

        for msg in self.commstat_messages:
            presentation = commstat_message_row_presentation(msg)
            rcv_display = self._format_rcv_display(presentation.rcv_ts, msg.event_ts_utc)
            rows.append(
                unified_message_from_presentation(
                    presentation,
                    payload=msg,
                    rcv_display=rcv_display,
                )
            )

        files_for_rows = self.files
        file_metadata_map = dict(getattr(self, "_file_metadata_map", {}) or {})
        try:
            cached_files, cached_metadata_map = self._load_existing_cached_message_files()
            files_for_rows = self._merge_file_record_sets(files_for_rows, cached_files)
            file_metadata_map.update(cached_metadata_map)
        except Exception:
            pass

        for origin, recs in files_for_rows.items():
            for rec in recs:
                status = self._get_read_state(rec)
                is_image = self._is_image_file(rec.path)
                cached_meta = file_metadata_map.get(file_metadata_key(rec), {}) if not is_image else {}
                candidate = file_message_row_candidate(
                    rec,
                    origin,
                    status=status,
                    is_image=is_image,
                    is_transport_form=not is_image and self._is_transport_form_ext(rec.path.suffix.lower()),
                    cached_meta=cached_meta,
                    form_meta_loader=lambda rec=rec: self._extract_form_file_metadata(rec),
                    fallback_from_loader=lambda rec=rec: self._extract_sender_from_file(rec),
                )
                rcv_display = self._format_rcv_display(candidate.rcv_ts, None)
                auth_state = ""
                auth_detail = ""
                auth_trusted = False
                if self._is_auth_verifiable_file(rec):
                    sig_state = self._signature_state_for_record(rec)
                    auth_state, auth_detail, auth_trusted = self._derive_auth_ui(sig_state)
                rows.append(
                    unified_file_message_from_candidate(
                        candidate,
                        origin=origin,
                        payload=rec,
                        rcv_display=rcv_display,
                        auth_state=auth_state,
                        auth_detail=auth_detail,
                        auth_trusted=auth_trusted,
                    )
                )

        for row in rows:
            if not row.search_text:
                row.search_text = " ".join(
                    [
                        row.msg_type or "",
                        row.status or "",
                        row.from_call or "",
                        row.to_call or "",
                        row.rcv_display or "",
                        row.title or "",
                        row.display_type or "",
                        " ".join(row.topics),
                        "actionable" if row.actionable else "",
                    ]
                ).lower()
        rows.sort(key=lambda r: r.rcv_ts, reverse=True)
        return rows

    def _reader_row_key(self, row: UnifiedMessage | None) -> tuple | None:
        return MessageTableModel._row_key(row) if row is not None else None

    def _reader_visible_rows(self) -> List[UnifiedMessage]:
        if not hasattr(self, "_messages_model"):
            return []
        # The model is already capped by the Inbox projection.  Copy only the
        # row references so navigation cannot trigger source, DB, or page work.
        return list(self._messages_model.rows())[:200]

    def _log_message_reader_lifecycle(self, event: str, **fields: object) -> None:
        """Record sparse, operator-driven reader events for production diagnosis."""

        details = "|".join(
            f"{key}={str(value).replace(chr(10), ' ')[:160]}"
            for key, value in fields.items()
            if value is not None
        )
        suffix = f"|{details}" if details else ""
        log.info("MESSAGES|reader_%s%s", str(event or "event").strip().lower(), suffix)

    def _update_message_reader_navigation(self) -> None:
        count = len(getattr(self, "_reader_snapshot", []))
        index = int(getattr(self, "_reader_index", -1))
        transitioning = bool(getattr(self, "_reader_transitioning", False))
        if hasattr(self, "reader_position_label"):
            self.reader_position_label.setText(f"{index + 1} of {count}" if 0 <= index < count else "0 of 0")
        if hasattr(self, "reader_previous_btn"):
            self.reader_previous_btn.setEnabled(not transitioning and index > 0)
        if hasattr(self, "reader_next_btn"):
            self.reader_next_btn.setEnabled(not transitioning and 0 <= index < (count - 1))

    def _release_message_reader_navigation(self, serial: int) -> None:
        """Release the short post-paint input debounce for reader navigation."""
        if serial != int(getattr(self, "_reader_transition_serial", 0)):
            return
        if not getattr(self, "_reader_open", False) or not getattr(self, "_reader_transitioning", False):
            return
        self._reader_transitioning = False
        row = self._reader_current_row()
        self._sync_reader_bbs_action(row)
        self._sync_reader_delete_action(row)
        self._sync_reader_context_actions(row)
        self._update_message_reader_navigation()

    def _reader_current_row(self) -> UnifiedMessage | None:
        rows = getattr(self, "_reader_snapshot", [])
        index = int(getattr(self, "_reader_index", -1))
        if 0 <= index < len(rows):
            return rows[index]
        return None

    @staticmethod
    def _reader_summary(row: UnifiedMessage | None) -> MessageSummary | None:
        if row is None:
            return None
        summary = getattr(row, "summary", None)
        if isinstance(summary, MessageSummary):
            return summary
        summary = message_summary_from_row(row)
        row.summary = summary
        return summary

    def _sync_reader_context_actions(self, row: UnifiedMessage | None) -> None:
        """Update source-neutral reader actions from the retained row only."""

        summary = self._reader_summary(row)
        transitioning = bool(getattr(self, "_reader_transitioning", False))
        family = normalize_message_source_family(summary.source_family if summary else "")
        map_ready = bool(
            summary
            and summary.actions.can_map
            and summary.map_hint
            and (
                summary.map_hint.state
                or summary.map_hint.grid
                or summary.map_hint.region
                or summary.map_hint.latitude is not None
            )
        )
        operator_ready = bool(summary and summary.from_call)
        reply_ready = bool(summary and summary.actions.can_reply and family in {"js8", "spotter", "commstat"})
        watch_ready = bool(
            summary
            and (
                summary.from_call
                or summary.to_target
                or summary.group
                or summary.topics
                or summary.status
                or summary.summary
            )
        )
        states = (
            (getattr(self, "reader_map_btn", None), map_ready, "No mapped state or grid is available."),
            (getattr(self, "reader_operator_btn", None), operator_ready, "No sender callsign is available."),
            (getattr(self, "reader_reply_btn", None), reply_ready, "Reply is not supported for this source."),
            (getattr(self, "reader_watch_btn", None), watch_ready, "No watchable identity is available."),
        )
        for button, ready, unavailable_tip in states:
            if not isinstance(button, QPushButton):
                continue
            button.setVisible(summary is not None)
            button.setEnabled(bool(ready) and not transitioning)
            if not ready:
                button.setToolTip(unavailable_tip)
        action_row = getattr(self, "reader_context_actions_widget", None)
        if action_row is not None:
            action_row.setVisible(summary is not None)
        if map_ready:
            self.reader_map_btn.setToolTip("Open Map using this message's cached location context.")
        if operator_ready:
            self.reader_operator_btn.setToolTip(f"Open {summary.from_call} in HF Operators.")
        if reply_ready:
            self.reader_reply_btn.setToolTip(f"Compose a JS8 reply to {summary.from_call}.")
        if watch_ready:
            self.reader_watch_btn.setToolTip("Stage an unsaved shared watch from this message for review.")

    def _open_reader_map(self) -> None:
        summary = self._reader_summary(self._reader_current_row())
        if summary is None or summary.map_hint is None or not summary.actions.can_map:
            return
        host = self.window()
        callback = getattr(host, "open_spotter_map", None)
        if callable(callback):
            callback(
                group_filter=summary.group,
                topic_filter=next(iter(summary.topics), ""),
                query_filter=summary.from_call,
                state_filter=summary.map_hint.state,
                grid_filter=summary.map_hint.grid,
            )

    def _open_reader_operator(self) -> None:
        summary = self._reader_summary(self._reader_current_row())
        callback = getattr(self.window(), "open_hf_operator", None)
        if summary is not None and summary.from_call and callable(callback):
            callback(summary.from_call)

    def _reply_to_reader_message(self) -> None:
        summary = self._reader_summary(self._reader_current_row())
        if summary is None or not summary.from_call:
            return
        callback = getattr(self.window(), "open_messages_section", None)
        if callable(callback):
            callback(
                "compose",
                compose_intent={
                    "mode": "js8",
                    "transport": "js8",
                    "recipient_callsign": summary.from_call,
                    "group": summary.group,
                    "source": "message_reader_reply",
                    "source_family": summary.source_family,
                    "source_ref": summary.provenance.source_ref if summary.provenance else "",
                    "title": summary.subject,
                    "topic": next(iter(summary.topics), ""),
                    "state": summary.map_hint.state if summary.map_hint else "",
                    "grid": summary.map_hint.grid if summary.map_hint else "",
                },
            )

    def _add_reader_message_to_watch(self) -> None:
        row = self._reader_current_row()
        summary = self._reader_summary(row)
        callback = getattr(self.window(), "open_fio_spotter_watch", None)
        if row is None or summary is None or not callable(callback):
            return
        callback(
            {
                "source_family": summary.source_family,
                "source_label": summary.source_label,
                "source_scope": normalize_message_source_family(message_row_source_label(row)),
                "source_kind": message_row_kind_label(row),
                "message_type": summary.form_type,
                "from_call": summary.from_call,
                "to_call": summary.to_target,
                "group_name": summary.group,
                "status": summary.status,
                "severity": summary.severity,
                "state_code": summary.map_hint.state if summary.map_hint else "",
                "grid": summary.map_hint.grid if summary.map_hint else "",
                "subject": summary.subject,
                "summary": summary.summary,
                "topics": tuple(summary.topics),
                "radio_id": summary.provenance.radio_short_name if summary.provenance else "",
            }
        )

    def _cached_reader_bbs_location_count(self, row: UnifiedMessage | None) -> int | None:
        rec = self._file_record_for_message_row(row, allow_detail_lookup=False)
        key = self._bbs_copy_session_key_for_record(rec)
        if key is None:
            return None
        known = getattr(self, "_reader_bbs_known_counts", {})
        if key in known:
            return max(0, int(known[key] or 0))
        cache_ts = float(getattr(self, "_bbs_published_index_cache_ts", 0.0) or 0.0)
        if (time.monotonic() - cache_ts) >= 5.0:
            return None
        published = getattr(self, "_bbs_published_index_cache", {})
        if not isinstance(published, dict):
            return None
        return len(set(published.get(key[0], set())))

    def _sync_reader_bbs_action(
        self,
        row: UnifiedMessage | None,
        *,
        confirmed_count: int | None = None,
    ) -> None:
        button = getattr(self, "reader_bbs_btn", None)
        status = getattr(self, "reader_bbs_status_label", None)
        if button is None:
            return
        eligible = MessageViewerTab._row_supports_managed_bbs_publication(self, row)
        button.setVisible(eligible)
        button.setEnabled(eligible and not getattr(self, "_reader_transitioning", False))
        if status is not None:
            status.clear()
            status.setVisible(False)
        if not eligible:
            button.setText("+BBS")
            return
        count = confirmed_count
        rec = self._file_record_for_message_row(row, allow_detail_lookup=False)
        key = self._bbs_copy_session_key_for_record(rec)
        if count is not None and key is not None:
            self._reader_bbs_known_counts[key] = max(0, int(count))
        if count is None:
            count = self._cached_reader_bbs_location_count(row)
        if count is not None and count > 0:
            button.setText(f"BBS · {count}")
            button.setAccessibleName(f"Manage {count} Managed BBS locations for this message file")
            button.setToolTip("Review or change the Managed BBS locations for this message file.")
        else:
            button.setText("+BBS")
            button.setAccessibleName("Add message file to Managed BBS")
            button.setToolTip("Choose the Managed BBS locations for this message file.")

    def _manage_reader_bbs_locations(self) -> None:
        row = self._reader_current_row()
        if not MessageViewerTab._row_supports_managed_bbs_publication(self, row):
            return
        result = self._copy_row_to_varac_bbs(row, show_confirmation=False)
        if result is None:
            return
        self._sync_reader_bbs_action(row, confirmed_count=result)
        status = getattr(self, "reader_bbs_status_label", None)
        if status is not None:
            status.setText("BBS updated")
            status.setVisible(True)

    def _reader_deletable_file_record(self, row: UnifiedMessage | None) -> FileRecord | None:
        rec = self._file_record_for_message_row(row, allow_detail_lookup=False)
        if rec is None:
            return None
        origin = str(rec.origin or getattr(row, "origin", "") or "").strip().lower()
        if origin not in {"flmsg", "flamp"}:
            return None
        if not rec.path.exists() or not rec.path.is_file():
            return None
        return rec

    def _sync_reader_delete_action(self, row: UnifiedMessage | None) -> None:
        button = getattr(self, "reader_delete_btn", None)
        if button is None:
            return
        rec = self._reader_deletable_file_record(row)
        button.setVisible(rec is not None)
        button.setEnabled(rec is not None and not getattr(self, "_reader_transitioning", False))
        if rec is not None:
            source = str(rec.origin or "message").strip().upper()
            button.setAccessibleName(f"Delete {source} message file")
            button.setToolTip(f"Move {rec.path.name} to the system Trash or Recycle Bin.")

    def _delete_reader_file_message(self) -> None:
        row = self._reader_current_row()
        rec = self._reader_deletable_file_record(row)
        if row is None or rec is None:
            return
        source = str(rec.origin or row.origin or "message").strip().upper()
        bbs_count = self._cached_reader_bbs_location_count(row)
        publication_note = (
            f"It is currently associated with {bbs_count} Managed BBS location(s); "
            "those locations will stop publishing it when the missing source is reconciled."
            if bbs_count is not None and bbs_count > 0
            else "If it is published through Managed BBS, publication will stop when the missing source is reconciled."
        )
        prompt = (
            f"Move this {source} message file to Trash / Recycle Bin?\n\n"
            f"{rec.path}\n\n"
            "The operating system trash may allow recovery. CommsPlan will remove the message from its current views.\n"
            f"{publication_note}"
        )
        delete_row = self._delete_audit_row_for_payload(rec)
        if not self._confirm_single_delete(delete_row, prompt):
            return
        button = getattr(self, "reader_delete_btn", None)
        if button is not None:
            button.setEnabled(False)
        outcome = self._execute_message_delete(delete_row)
        if outcome.result != "deleted":
            self._record_message_delete_audit(
                delete_row,
                result=outcome.result,
                detail=message_delete_result_detail(rec, outcome.detail_key),
                batch_id="reader",
            )
            if outcome.result == "failed":
                QMessageBox.warning(
                    self,
                    "Delete Message File",
                    outcome.warning or "CommsPlan could not move the file to Trash / Recycle Bin.",
                )
            self._sync_reader_delete_action(row)
            return
        self._record_message_delete_audit(
            delete_row,
            result="deleted",
            detail=message_delete_result_detail(rec, outcome.detail_key),
            batch_id="reader",
        )
        self._remember_locally_deleted_row(row)
        self._mark_projection_rows_deleted([row], source_scope="reader_file")
        if getattr(self, "_reader_open", False):
            self._close_message_reader(
                clear_content=True,
                cleared_label="Message moved to Trash",
                reason="delete",
            )
        self._remove_deleted_rows_from_current_view([row])
        self._unfreeze_table()
        self._populate_messages_table(force=True)
        QMessageBox.information(
            self,
            "Delete Message File",
            f"Moved {rec.path.name} to Trash / Recycle Bin.",
        )

    def _scroll_reader_to_top(self) -> None:
        if hasattr(self, "viewer"):
            self.viewer.verticalScrollBar().setValue(0)

    def _open_message_reader(self, row: UnifiedMessage) -> None:
        rows = self._reader_visible_rows()
        key = self._reader_row_key(row)
        try:
            index = next(i for i, candidate in enumerate(rows) if self._reader_row_key(candidate) == key)
        except StopIteration:
            # A direct View action can race a model refresh.  Keep the selected
            # row readable, but never fetch a replacement Inbox page for it.
            rows = [row]
            index = 0
        if hasattr(self, "messages_table"):
            self._saved_list_scroll = self.messages_table.verticalScrollBar().value()
        self._reader_snapshot = rows
        self._reader_message_key = key
        self._reader_index = index
        self._reader_generation = int(getattr(self, "_active_projection_generation", 0) or 0)
        self._reader_open = True
        if hasattr(self, "inbox_workspace_stack") and hasattr(self, "reader_page"):
            self.inbox_workspace_stack.setCurrentWidget(self.reader_page)
        self._render_message_content(row)
        self._sync_reader_bbs_action(row)
        self._sync_reader_delete_action(row)
        self._sync_reader_context_actions(row)
        self._scroll_reader_to_top()
        self._update_message_reader_navigation()
        self._log_message_reader_lifecycle(
            "open",
            index=index + 1,
            count=len(rows),
            key=hashlib.sha1(repr(key).encode("utf-8", errors="replace")).hexdigest()[:12],
            origin=row.origin,
        )
        if hasattr(self, "viewer"):
            self.viewer.setFocus(Qt.OtherFocusReason)

    def _navigate_message_reader(self, delta: int) -> None:
        if not getattr(self, "_reader_open", False) or getattr(self, "_reader_transitioning", False):
            return
        target = int(getattr(self, "_reader_index", -1)) + int(delta)
        rows = getattr(self, "_reader_snapshot", [])
        if target < 0 or target >= len(rows):
            self._update_message_reader_navigation()
            return
        row = rows[target]
        self._reader_transitioning = True
        self._reader_transition_serial = int(getattr(self, "_reader_transition_serial", 0)) + 1
        serial = int(self._reader_transition_serial)
        self._update_message_reader_navigation()
        if hasattr(self, "reader_bbs_btn"):
            self.reader_bbs_btn.setEnabled(False)
        if hasattr(self, "reader_delete_btn"):
            self.reader_delete_btn.setEnabled(False)
        try:
            # Render first, then commit the identity and position.  This keeps
            # the toolbar from describing N+1 while the document still shows N
            # and fences accidental re-entry during file/form parsing.
            self._render_message_content(row)
            self._scroll_reader_to_top()
        except Exception as exc:
            log.exception("MessageViewer: failed reader navigation render")
            if hasattr(self, "info_label"):
                self.info_label.setText("Message could not be displayed")
            if hasattr(self, "viewer"):
                self.viewer.setAcceptRichText(False)
                self.viewer.setPlainText(f"CommsPlan could not display this message.\n\nError: {exc}")
            self._scroll_reader_to_top()
        finally:
            # The document is installed before its identity controls change.
            # Let Qt paint the complete state after this handler returns; do
            # not force, intercept, or suppress a paint event here. Linux
            # compositors proved sensitive to all three approaches.
            self._reader_index = target
            self._reader_message_key = self._reader_row_key(row)
            self._sync_reader_bbs_action(row)
            self._sync_reader_delete_action(row)
            self._sync_reader_context_actions(row)
            self._update_message_reader_navigation()
            self._log_message_reader_lifecycle(
                "navigate",
                index=target + 1,
                count=len(rows),
                key=hashlib.sha1(
                    repr(self._reader_message_key).encode("utf-8", errors="replace")
                ).hexdigest()[:12],
                origin=row.origin,
            )
            QTimer.singleShot(100, lambda serial=serial: self._release_message_reader_navigation(serial))

    def _restore_reader_list_position(self) -> None:
        if not hasattr(self, "messages_table"):
            return
        table = self.messages_table
        table.verticalScrollBar().setValue(min(int(getattr(self, "_saved_list_scroll", 0)), table.verticalScrollBar().maximum()))
        key = getattr(self, "_reader_message_key", None)
        if key is None:
            return
        for i, row in enumerate(self._messages_model.rows()):
            if self._reader_row_key(row) != key:
                continue
            index = self._messages_model.index(i, 1)
            table.setCurrentIndex(index)
            table.scrollTo(index, QAbstractItemView.PositionAtCenter)
            break

    def _close_message_reader(
        self,
        *_args,
        clear_content: bool = False,
        cleared_label: str = "No message selected",
        reason: str = "back",
    ) -> None:
        was_open = bool(getattr(self, "_reader_open", False))
        self._reader_open = False
        if hasattr(self, "inbox_workspace_stack") and hasattr(self, "inbox_list_page"):
            self.inbox_workspace_stack.setCurrentWidget(self.inbox_list_page)
        if was_open:
            self._restore_reader_list_position()
        self._reader_snapshot = []
        self._reader_index = -1
        self._reader_generation = 0
        self._reader_transitioning = False
        self._reader_transition_serial = int(getattr(self, "_reader_transition_serial", 0)) + 1
        if clear_content:
            self._reader_message_key = None
            self._set_open_external_path(None)
            self.current_record = None
            self.current_js8 = None
            self.current_sitrep = None
            self.current_commstat = None
            self.current_observation = None
            self.info_label.setText(cleared_label)
            self.viewer.clear()
        if hasattr(self, "reader_bbs_btn"):
            self.reader_bbs_btn.setVisible(False)
        if hasattr(self, "reader_bbs_status_label"):
            self.reader_bbs_status_label.clear()
            self.reader_bbs_status_label.setVisible(False)
        if hasattr(self, "reader_delete_btn"):
            self.reader_delete_btn.setVisible(False)
        self._sync_reader_context_actions(None)
        self._update_message_reader_navigation()
        if was_open:
            self._log_message_reader_lifecycle("close", reason=reason, clear=int(bool(clear_content)))

    def _close_message_reader_for_scope_change(self) -> None:
        if not getattr(self, "_reader_open", False):
            return
        # Scope changes must never leave an old document looking as though it
        # belongs to the newly requested Inbox result.
        self._close_message_reader(clear_content=True, reason="scope_change")

    def _on_view_message(self, row: UnifiedMessage) -> None:
        if hasattr(self, "inbox_workspace_stack"):
            self._open_message_reader(row)
            return
        self._render_message_content(row)

    def _render_message_content(self, row: UnifiedMessage) -> None:
        with perf_span(
            "messages.view_message",
            settings=self.settings,
            meta={"msg_type": row.msg_type, "origin": row.origin},
            min_ms=5.0,
        ):
            log.debug(
                "MessageViewer: view requested type=%s origin=%s title=%s",
                row.msg_type,
                row.origin,
                row.title,
            )
            self._set_open_external_path(None)
            if isinstance(row.payload, JS8Message):
                self.current_record = None
                self.current_sitrep = None
                self.current_commstat = None
                self.current_observation = None
                self.current_js8 = row.payload
                self._load_js8_content(row.payload)
                self._mark_js8_read(row.payload, row_ref=row)
            elif isinstance(row.payload, SpotterMessage):
                self.current_record = None
                self.current_js8 = None
                self.current_sitrep = None
                self.current_commstat = None
                self.current_observation = None
                self._load_js8_content(row.payload)
                self._mark_spotter_read(row.payload, row_ref=row)
            elif isinstance(row.payload, FileRecord):
                self.current_js8 = None
                self.current_sitrep = None
                self.current_commstat = None
                self.current_observation = None
                self.current_record = row.payload
                try:
                    self._load_content(row.payload)
                except Exception as exc:
                    log.exception("MessageViewer: failed to load file message %s", row.payload.path)
                    self.info_label.setText(f"{row.payload.path.name} - could not load")
                    self.viewer.setAcceptRichText(False)
                    self.viewer.setPlainText(
                        "CommsPlan could not display this message file.\n\n"
                        f"File: {row.payload.path}\n"
                        f"Error: {exc}"
                    )
                    return
                else:
                    self._set_read_state(row.payload, "READ", row_ref=row)
            elif isinstance(row.payload, VarACMessage):
                self.current_js8 = None
                self.current_record = None
                self.current_sitrep = None
                self.current_commstat = None
                self.current_observation = None
                self._load_varac_content(row.payload, row_ref=row)
            elif isinstance(row.payload, SitrepMessage):
                self.current_js8 = None
                self.current_record = None
                self.current_commstat = None
                self.current_observation = None
                self.current_sitrep = row.payload
                self._load_sitrep_content(row.payload)
            elif isinstance(row.payload, CommStatArtifact):
                self.current_js8 = None
                self.current_record = None
                self.current_sitrep = None
                self.current_observation = None
                self.current_commstat = row.payload
                self._load_commstat_content(row.payload)
            elif isinstance(row.payload, ProjectedMessagePayload):
                self.current_js8 = None
                self.current_sitrep = None
                self.current_commstat = None
                self.current_observation = None
                file_record = self._projected_file_record(row.payload, allow_detail_lookup=False)
                if file_record is not None and file_record.path.exists():
                    self.current_record = file_record
                    self._load_content(file_record)
                else:
                    self.current_record = None
                    self._load_projected_content(row.payload)
                self._mark_projected_read(row.payload, row_ref=row)
            elif isinstance(row.payload, Observation):
                self.current_js8 = None
                self.current_record = None
                self.current_sitrep = None
                self.current_commstat = None
                self.current_observation = row.payload
                self._load_observation_content(row.payload)
            else:
                # Never advance reader identity while retaining the previous
                # document. Unknown payloads can occur during an additive
                # source rollout or while opening a stale model snapshot.
                self.current_js8 = None
                self.current_record = None
                self.current_sitrep = None
                self.current_commstat = None
                self.current_observation = None
                self._set_open_external_path(None)
                self.info_label.setText("Message format is not available")
                self.viewer.setAcceptRichText(False)
                self.viewer.setPlainText(
                    "CommsPlan cannot display this message format in the current build.\n\n"
                    f"Source: {row.origin or 'unknown'}\n"
                    f"Type: {row.msg_type or 'unknown'}"
                )

    def _load_projected_content(self, msg: ProjectedMessagePayload) -> None:
        with perf_span(
            "messages.load_projected_content",
            settings=self.settings,
            meta={"source_family": msg.source_family},
            min_ms=2.0,
        ):
            source_label = message_row_source_label(
                SimpleNamespace(
                    origin=msg.source_family,
                    display_type=msg.display_type,
                    payload=msg,
                    summary=None,
                )
            )
            kind_label = message_row_kind_label(
                SimpleNamespace(
                    origin=msg.source_family,
                    display_type=msg.display_type,
                    msg_type=msg.message_type,
                    title=msg.summary or msg.subject,
                    payload=msg,
                    summary=None,
                )
            )
            receipt = commstat_status_receipt(msg.body_preview, msg.summary, msg.subject)
            message_text = (
                status_receipt_summary(sender=msg.from_call, receipt=receipt)
                if receipt is not None
                else (msg.body_preview or msg.summary or msg.subject or "--")
            )
            destination = msg.to_call or msg.report_group or msg.group
            route = " -> ".join(part for part in (msg.from_call, destination) if part) or "Message"
            event_ts = float(msg.event_ts or msg.received_ts or 0.0)
            age = relative_age_label(event_ts)
            lines = [
                route,
            ]
            self._append_text_body(lines, "Message", message_text)
            self._append_detail_section(
                lines,
                "Key Fields",
                (
                    ("Source", source_label),
                    ("Kind", kind_label),
                    ("Status", msg.status),
                    ("Age", age),
                    ("From", msg.from_call),
                    ("To", destination),
                    ("Group", msg.report_group or msg.group),
                    ("Severity", msg.severity),
                    ("State/Grid", " / ".join(part for part in (msg.state_code, msg.grid) if part)),
                    ("Event time", msg.event_utc or msg.received_utc),
                ),
            )
            topics = ", ".join(msg.topics)
            if topics:
                self._append_detail_section(lines, "Intelligence", (("Topics", topics),))
            # Projection rows already carry their bounded reference snapshot.
            # Reader selection must not issue a detail query merely to expose
            # diagnostics; keep technical provenance secondary and cache-only.
            ref_lines = self._projected_ref_lines(msg.external_refs)
            provenance = dict(msg.provenance or {})
            provenance_lines = [
                f"{key}: {value}"
                for key, value in (
                    ("Message ID", msg.message_id),
                    ("Source record", msg.source_ref),
                    ("Adapter", provenance.get("app_instance_id", "")),
                    ("Radio", provenance.get("radio_id", "")),
                )
                if str(value or "").strip()
            ]
            if ref_lines:
                provenance_lines.extend(ref_lines)
            if provenance_lines:
                self._append_text_body(lines, "Technical provenance", "\n".join(provenance_lines))
            chips = " · ".join(part for part in (source_label, kind_label, msg.status, age) if part)
            self.info_label.setText(f"{route}  |  {chips}" if chips else route)
            self.viewer.setAcceptRichText(False)
            self.viewer.setPlainText("\n".join(lines))

    def _projected_message_detail(self, message_id: str) -> Dict[str, object]:
        db_path = self._db_path()
        if db_path is None or not message_id:
            return {}
        try:
            return load_projected_message_detail(db_path, message_id)
        except Exception as exc:
            log.debug("MessageViewer: failed to load projected detail for %s: %s", message_id, exc)
            return {}

    def _projected_file_record(
        self,
        msg: ProjectedMessagePayload,
        *,
        allow_detail_lookup: bool = True,
    ) -> FileRecord | None:
        record = self._file_record_from_projected_refs(msg.external_refs, origin=msg.source_family)
        if record is not None:
            return record
        if not allow_detail_lookup:
            return None
        detail = self._projected_message_detail(msg.message_id)
        refs = detail.get("refs", []) if isinstance(detail, dict) else []
        record = self._file_record_from_projected_refs(refs, origin=msg.source_family)
        if record is not None:
            return record
        artifacts = detail.get("artifacts", []) if isinstance(detail, dict) else []
        return self._file_record_from_projected_artifacts(artifacts, origin=msg.source_family)

    @staticmethod
    def _file_record_from_projected_refs(refs: object, *, origin: str) -> FileRecord | None:
        try:
            iterator = iter(refs or [])
        except TypeError:
            return None
        for ref in iterator:
            try:
                path_text = str(ref["external_path"] or "").strip()
                mtime = float(ref["external_mtime"] or 0.0)
                size = int(ref["external_size"] or 0)
                kind = str(ref["external_kind"] or "").strip().lower()
            except Exception:
                path_text = str(getattr(ref, "external_path", "") or "").strip()
                mtime = float(getattr(ref, "external_mtime", 0.0) or 0.0)
                size = int(getattr(ref, "external_size", 0) or 0)
                kind = str(getattr(ref, "external_kind", "") or "").strip().lower()
            if not path_text or not (kind.endswith("_file") or "file" in kind):
                continue
            return FileRecord(path=Path(path_text), origin=str(origin or "file"), mtime=mtime, size=size)
        return None

    @staticmethod
    def _file_record_from_projected_artifacts(artifacts: object, *, origin: str) -> FileRecord | None:
        try:
            iterator = iter(artifacts or [])
        except TypeError:
            return None
        for artifact in iterator:
            try:
                path_text = str(artifact["path"] or "").strip()
            except Exception:
                path_text = str(getattr(artifact, "path", "") or "").strip()
            if path_text:
                path = Path(path_text)
                try:
                    stat = path.stat()
                    mtime = float(stat.st_mtime)
                    size = int(stat.st_size)
                except Exception:
                    mtime = 0.0
                    size = 0
                return FileRecord(path=path, origin=str(origin or "file"), mtime=mtime, size=size)
        return None

    @staticmethod
    def _projected_ref_lines(refs: object) -> List[str]:
        lines: List[str] = []
        try:
            iterator = iter(refs or [])
        except TypeError:
            return lines
        for ref in iterator:
            try:
                source_id = str(ref["source_id"] or "").strip()
                source_label = str(ref["receipt_source_label"] or "").strip()
                radio_id = str(ref["receipt_radio_id"] or "").strip()
                app_instance_id = str(ref["receipt_app_instance_id"] or "").strip()
                kind = str(ref["external_kind"] or "").strip()
                key = str(ref["external_key"] or "").strip()
                path = str(ref["external_path"] or "").strip()
                delete_cap = str(ref["delete_capability"] or "").strip()
            except Exception:
                source_id = str(getattr(ref, "source_id", "") or "").strip()
                source_label = str(getattr(ref, "receipt_source_label", "") or "").strip()
                radio_id = str(getattr(ref, "receipt_radio_id", "") or "").strip()
                app_instance_id = str(getattr(ref, "receipt_app_instance_id", "") or "").strip()
                kind = str(getattr(ref, "external_kind", "") or "").strip()
                key = str(getattr(ref, "external_key", "") or "").strip()
                path = str(getattr(ref, "external_path", "") or "").strip()
                delete_cap = str(getattr(ref, "delete_capability", "") or "").strip()
            source = source_label or source_id
            source_context = " · ".join(
                part for part in (
                    source,
                    f"radio {radio_id}" if radio_id else "",
                    app_instance_id,
                ) if part
            )
            parts = [
                part for part in (
                    source_context,
                    kind,
                    key,
                    path,
                    f"delete={delete_cap}" if delete_cap else "",
                ) if part
            ]
            if parts:
                lines.append(" | ".join(parts))
        return lines

    @staticmethod
    def _projected_artifact_lines(artifacts: object) -> List[str]:
        lines: List[str] = []
        try:
            iterator = iter(artifacts or [])
        except TypeError:
            return lines
        for artifact in iterator:
            try:
                artifact_type = str(artifact["artifact_type"] or "").strip()
                q_id = str(artifact["q_id"] or "").strip()
                block_id = str(artifact["block_id"] or "").strip()
                state = str(artifact["transfer_state"] or "").strip()
                path = str(artifact["path"] or "").strip()
            except Exception:
                artifact_type = str(getattr(artifact, "artifact_type", "") or "").strip()
                q_id = str(getattr(artifact, "q_id", "") or "").strip()
                block_id = str(getattr(artifact, "block_id", "") or "").strip()
                state = str(getattr(artifact, "transfer_state", "") or "").strip()
                path = str(getattr(artifact, "path", "") or "").strip()
            q_part = " ".join(part for part in (q_id, f"block {block_id}" if block_id else "") if part)
            parts = [part for part in (artifact_type, q_part, state, path) if part]
            if parts:
                lines.append(" | ".join(parts))
        return lines

    def _mark_projected_read(self, msg: ProjectedMessagePayload, row_ref: Optional[UnifiedMessage] = None) -> None:
        if not msg or str(msg.read_state or "").strip().lower() == "read":
            return
        db_path = self._db_path()
        if db_path is None:
            return
        try:
            mark_projected_messages_read(db_path, [msg.message_id])
            rec = self._projected_file_record(msg, allow_detail_lookup=False)
            if rec is not None:
                self._set_read_state_bulk([rec], "READ", time.time())
            msg.read_state = "read"
            msg.status = "READ"
        except Exception as exc:
            log.debug("MessageViewer: failed to mark projected message read: %s", exc)
            return
        self._refresh_table_after_read(
            lambda row: isinstance(row.payload, ProjectedMessagePayload)
            and row.payload.message_id == msg.message_id,
            row_ref=row_ref,
        )

    def _read_file_head(self, path: Path, limit: int = 4096) -> str:
        try:
            with path.open("rb") as fh:
                raw = fh.read(limit)
            return raw.decode("utf-8", errors="replace")
        except Exception:
            return ""

    def _extract_sender_from_file(self, rec: FileRecord) -> str:
        cache_key = (
            str(rec.path),
            float(rec.mtime or 0.0),
            int(rec.size or 0),
        )
        cached = self._sender_cache.get(cache_key)
        if cached is not None:
            return cached
        text = self._read_file_head(rec.path)
        if not text:
            log.debug("MessageViewer: sender parse empty for %s", rec.path)
            return ""
        lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
        if not lines:
            log.debug("MessageViewer: sender parse no lines for %s", rec.path)
            return ""
        for marker in (":hdr_fm:", ":hdr_ed:"):
            for idx, line in enumerate(lines):
                if line.lower().startswith(marker):
                    for nxt in lines[idx + 1 :]:
                        match = re.search(r"\b[A-Z]{1,2}\d[A-Z0-9]{1,4}\b", nxt.upper())
                        if match:
                            sender = match.group(0)
                            log.debug(
                                "MessageViewer: sender parsed via %s for %s => %s",
                                marker,
                                rec.path.name,
                                sender,
                            )
                            self._sender_cache[cache_key] = sender
                            self._prune_cache(self._sender_cache, self._cache_max_sender_entries)
                            return sender
                    break
        tokens = re.split(r"[-_\\s]+", rec.path.stem)
        for tok in tokens:
            up = tok.strip().upper()
            if re.fullmatch(r"[A-Z]{1,2}\d[A-Z0-9]{1,4}", up):
                log.debug("MessageViewer: sender fallback from filename %s => %s", rec.path.name, up)
                self._sender_cache[cache_key] = up
                self._prune_cache(self._sender_cache, self._cache_max_sender_entries)
                return up
        log.debug("MessageViewer: sender not found for %s", rec.path.name)
        self._sender_cache[cache_key] = ""
        self._prune_cache(self._sender_cache, self._cache_max_sender_entries)
        return ""

    @staticmethod
    def _title_from_filename(path: Path) -> str:
        return _title_from_filename_path(path)

    def _resolve_custom_forms_path(self) -> Optional[Path]:
        override = (self.settings.get("nbems_custom_forms_path", "") or "").strip()
        if override:
            p = Path(override)
            if p.exists():
                log.debug("MessageViewer: using custom forms override %s", p)
                return p
        msg_paths = self.settings.get("message_paths", {}) or {}
        candidates: List[str] = []
        for origin in ("flmsg", "flamp"):
            base = (msg_paths.get(origin) or "").strip()
            if base:
                candidates.append(base)
        for entry in self._multi_radio_message_path_entries():
            if str(entry.get("origin", "") or "").strip().lower() in {"flmsg", "flamp"}:
                base = str(entry.get("path", "") or "").strip()
                if base:
                    candidates.append(base)
        seen: set[str] = set()
        for base in candidates:
            if not base:
                continue
            p = Path(base)
            norm = os.path.normcase(os.path.normpath(str(p)))
            if norm in seen:
                continue
            seen.add(norm)
            for parent in [p] + list(p.parents):
                name = parent.name.lower()
                if name in {"nbems.files", ".nbems"}:
                    cand = parent / "CUSTOM"
                    if cand.exists():
                        log.debug("MessageViewer: using custom forms path %s", cand)
                        return cand
        for root in _operator_nbems_roots():
            fallback = root / "CUSTOM"
            if fallback.is_dir():
                log.debug("MessageViewer: using current-operator custom forms path %s", fallback)
                return fallback
        return None

    def _resolve_custom_form_template_path(self, form_name: str) -> Optional[Path]:
        safe_name = Path(str(form_name or "").strip()).name
        if not safe_name:
            return None
        search_dirs: List[Path] = []
        primary = self._resolve_custom_forms_path()
        if primary is not None:
            search_dirs.append(primary)
        try:
            msg_paths = self.settings.get("message_paths", {}) or {}
        except Exception:
            msg_paths = {}
        roots: List[str] = []
        if isinstance(msg_paths, dict):
            roots.extend(str(msg_paths.get(origin, "") or "").strip() for origin in ("flmsg", "flamp"))
        roots.extend(
            str(entry.get("path", "") or "").strip()
            for entry in self._multi_radio_message_path_entries()
            if str(entry.get("origin", "") or "").strip().lower() in {"flmsg", "flamp"}
        )
        seen_dirs = {os.path.normcase(os.path.normpath(str(directory))) for directory in search_dirs}
        for base in roots:
            if not base:
                continue
            p = Path(base)
            for parent in [p] + list(p.parents):
                if parent.name.lower() not in {"nbems.files", ".nbems"}:
                    continue
                cand_dir = parent / "CUSTOM"
                norm = os.path.normcase(os.path.normpath(str(cand_dir)))
                if norm in seen_dirs:
                    continue
                seen_dirs.add(norm)
                search_dirs.append(cand_dir)
        for directory in search_dirs:
            try:
                candidate = directory / safe_name
            except Exception:
                continue
            if candidate.exists():
                return candidate
        return None

    @staticmethod
    def _extract_custom_form_name(text: str) -> str:
        return _extract_custom_form_name_text(text)

    @staticmethod
    def _parse_custom_form_fields(text: str) -> Dict[str, str]:
        return _parse_custom_form_fields_text(text)

    def _template_labels_for_custom_form(self, form_name: str) -> List[Tuple[str, str]]:
        template_path = self._resolve_custom_form_template_path(form_name)
        if template_path is None:
            return []
        try:
            template = template_path.read_text(encoding="utf-8", errors="replace")
        except Exception:
            return []
        return self._extract_template_labels(template)

    def _template_title_for_custom_form(self, form_name: str) -> str:
        template_path = self._resolve_custom_form_template_path(form_name)
        if template_path is None:
            return ""
        try:
            template = template_path.read_text(encoding="utf-8", errors="replace")
        except Exception:
            return ""
        return self._extract_title_from_template(template)

    def _extract_form_file_metadata(self, rec: FileRecord) -> Dict[str, str]:
        text = _read_text_head(rec.path, 131072)
        return _extract_form_metadata_from_text(
            text,
            rec.path,
            template_title_for_form=self._template_title_for_custom_form,
            template_labels_for_form=self._template_labels_for_custom_form,
        )

    @staticmethod
    def _apply_form_fields(template: str, fields: Dict[str, str]) -> str:
        if not template or not fields:
            return template
        out = template
        for key, raw_val in fields.items():
            val = html.escape(raw_val or "")
            input_re = re.compile(
                rf'(<input[^>]*\bname="{key}"[^>]*)(>)',
                re.IGNORECASE,
            )
            def repl_input(match):
                tag = match.group(1)
                if re.search(r"\bvalue=", tag, re.IGNORECASE):
                    tag = re.sub(r'\bvalue="[^"]*"', f'value="{val}"', tag, flags=re.IGNORECASE)
                    return tag + match.group(2)
                return tag + f' value="{val}"' + match.group(2)
            out = input_re.sub(repl_input, out)

            textarea_re = re.compile(
                rf'(<textarea[^>]*\bname="{key}"[^>]*>)(.*?)(</textarea>)',
                re.IGNORECASE | re.DOTALL,
            )
            out = textarea_re.sub(rf'\1{val}\3', out)

            select_re = re.compile(
                rf'(<select[^>]*\bname="{key}"[^>]*>)(.*?)(</select>)',
                re.IGNORECASE | re.DOTALL,
            )
            def repl_select(match):
                block = match.group(2)
                block = re.sub(r'\sselected="selected"', "", block, flags=re.IGNORECASE)
                opt_re = re.compile(
                    r'(<option[^>]*value="([^"]*)"[^>]*>)(.*?)</option>',
                    re.IGNORECASE | re.DOTALL,
                )
                def repl_opt(opt_match):
                    opt_val = opt_match.group(2)
                    label = re.sub(r"\s+", " ", opt_match.group(3)).strip()
                    if opt_val == raw_val or label == raw_val:
                        tag = opt_match.group(1)
                        if "selected" not in tag.lower():
                            tag = (
                                tag[:-1] + ' selected="selected">'
                                if tag.endswith(">")
                                else tag + ' selected="selected">'
                            )
                        return tag + opt_match.group(3) + "</option>"
                    return opt_match.group(0)
                block = opt_re.sub(repl_opt, block)
                return match.group(1) + block + match.group(3)
            out = select_re.sub(repl_select, out)
        return out

    @staticmethod
    def _strip_html(text: str) -> str:
        return _strip_html_text(text)

    @staticmethod
    def _extract_title_from_template(template: str) -> str:
        return _extract_template_title_text(template)

    @staticmethod
    def _is_image_file(path: Path) -> bool:
        return path.suffix.lower() in IMAGE_EXTS

    @staticmethod
    def _can_preview_image(path: Path) -> bool:
        return path.suffix.lower() in IMAGE_PREVIEW_EXTS

    def _set_open_external_path(self, path: Path | None, *, label: str = "Open Image") -> None:
        self._open_external_path = path
        if hasattr(self, "open_external_btn"):
            if path:
                self.open_external_btn.setText(label)
                self.open_external_btn.setVisible(True)
                self.open_external_btn.setEnabled(True)
            else:
                self.open_external_btn.setVisible(False)
                self.open_external_btn.setEnabled(False)

    def _open_external_file(self) -> None:
        path = self._open_external_path
        if not path:
            return
        try:
            if platform.system() == "Darwin":
                subprocess.Popen(["open", str(path)])
            elif os.name == "nt":
                os.startfile(str(path))  # type: ignore[attr-defined]
            else:
                subprocess.Popen(["xdg-open", str(path)])
        except Exception as e:
            QMessageBox.critical(self, "Open File", f"Could not open file:\n{e}")

    @staticmethod
    def _extract_template_labels(template: str) -> List[Tuple[str, str]]:
        return [(field.key, field.label) for field in parse_compose_template_fields(template)]

    @staticmethod
    def _render_custom_form_fields(
        fields: Dict[str, str],
        labels: Sequence[Tuple[str, str] | ComposeFieldDefinition],
        title: str = "",
    ) -> str:
        rows = []
        if labels:
            for entry in labels:
                if isinstance(entry, ComposeFieldDefinition):
                    key = entry.key
                    label = entry.label
                    description = entry.description
                else:
                    key, label = entry
                    description = ""
                value = MessageViewerTab._normalize_field_value(fields.get(key, ""))
                rows.append((label, description, value))
        else:
            for key in sorted(fields.keys()):
                rows.append((key, "", MessageViewerTab._normalize_field_value(fields.get(key, ""))))
        html_out = [
            "<style>",
            ".field-stack { width: 100%; }",
            ".field-block { padding: 8px 0; border-bottom: 1px solid; }",
            ".label { font-weight: bold; margin-bottom: 2px; }",
            # Rich-text previews inherit the viewer's active font and palette;
            # do not freeze a second, unscaled typography system in HTML.
            ".description { margin-bottom: 4px; }",
            ".value { white-space: pre-wrap; }",
            "</style>",
        ]
        if title:
            html_out.append(f"<div class='label' style='margin-bottom: 8px;'>{html.escape(title)}</div>")
        html_out.append("<div class='field-stack'>")
        for label, description, value in rows:
            html_out.append("<div class='field-block'>")
            html_out.append(f"<div class='label'>{html.escape(label)}</div>")
            if description:
                html_out.append(f"<div class='description'>{html.escape(description)}</div>")
            html_out.append(f"<div class='value'>{html.escape(value)}</div>")
            html_out.append("</div>")
        html_out.append("</div>")
        return "".join(html_out)

    @staticmethod
    def _normalize_field_value(value: str) -> str:
        if not value:
            return ""
        out = value.replace("\\r\\n", "\n").replace("\\n", "\n").replace("\\t", "\t")
        out = out.replace('\\"', '"').replace("\\'", "'")
        return out

    @staticmethod
    def _merge_template_with_raw(template: str, raw_text: str) -> str:
        safe_raw = '<pre>' + raw_text.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;') + '</pre>'
        for token in ('{{DATA}}', '{{RAW}}', '%%DATA%%', '%%RAW%%'):
            if token in template:
                return template.replace(token, safe_raw)
        return template + '\n' + safe_raw

    @staticmethod
    def _parse_form_fields(text: str, field_titles: Dict[str, str], value_mappings: Dict[str, Dict[str, str]] | None = None) -> Dict[str, str]:
        parsed = {title: "" for title in field_titles.values()}
        for line in text.splitlines():
            line = line.strip()
            if not line:
                continue
            for key, title in field_titles.items():
                if line.startswith(key):
                    value = line[len(key):].strip().strip(",")
                    if value_mappings and title in value_mappings:
                        mapped = value_mappings[title].get(value, value)
                        value = mapped
                    parsed[title] = value
                    break
        return parsed

    @staticmethod
    def _format_fields_table(parsed: Dict[str, str], last_field: str, status_fields: Optional[Dict[str, str]] = None) -> str:
        html_out = [
            "<style>",
            ".field-table { width: 100%; border-collapse: collapse; }",
            ".field-cell { width: 50%; padding: 4px; vertical-align: top; }",
            ".label { font-weight: bold; }",
            ".long-text { white-space: pre-wrap; }",
            "</style>",
            "<table class='field-table'>",
        ]
        items = list(parsed.items())
        if not items:
            return ""
        last_index = len(items) - 1
        for i in range(0, last_index, 2):
            html_out.append("<tr>")
            html_out.append(MessageViewerTab._render_field_cell(items[i], status_fields))
            if i + 1 < last_index:
                html_out.append(MessageViewerTab._render_field_cell(items[i + 1], status_fields))
            else:
                html_out.append("<td></td>")
            html_out.append("</tr>")
        html_out.append("<tr><td colspan='2' style='height:10px;'></td></tr>")
        title, value = items[last_index]
        html_out.append("<tr><td colspan='2'>")
        html_out.append(f"<div class='label'>{html.escape(title)}:</div>")
        html_out.append(f"<div class='long-text'>{html.escape(value)}</div>")
        html_out.append("</td></tr></table>")
        return "".join(html_out)

    @staticmethod
    def _render_field_cell(item: Tuple[str, str], status_fields: Optional[Dict[str, str]] = None) -> str:
        title, value = item
        display_value = value if value.strip() else "Unknown"
        label = html.escape(title)
        display = html.escape(display_value)
        return f"<td class='field-cell'><span class='label'>{label}:</span> {display}</td>"

    @staticmethod
    def _parse_blank_form_content(text: str) -> str:
        field_titles = {
            "L01": "To",
            "L02": "From",
            "L03": "Prec",
            "L04": "DTG",
            "L05": "Subject",
            "L06": "Message",
        }
        prec_mapping = {"R": "Routine", "P": "Priority", "I": "Immediate", "F": "Flash"}
        parsed = MessageViewerTab._parse_form_fields(text, field_titles, {"Prec": prec_mapping})
        if not any(v.strip() for v in parsed.values()):
            msg = MessageViewerTab._match_field(text, r":mg:\s*(.*)$")
            if msg:
                msg = msg.replace("\\n\\n", "\n\n").replace("\\n", "\n")
            from_call = MessageViewerTab._extract_hdr_call(text, ":hdr_fm:")
            fallback = {"From": from_call, "Message": msg or ""}
            return MessageViewerTab._format_fields_table(fallback, "Message")
        if "Message" in parsed:
            parsed["Message"] = parsed["Message"].replace("\\n\\n", "\n\n").replace("\\n", "\n")
        return MessageViewerTab._format_fields_table(parsed, "Message")

    @staticmethod
    def _parse_sitrep_content(text: str) -> str:
        field_titles = {
            "L01": "To",
            "L02": "From",
            "L03": "Prec",
            "L04": "State",
            "L05": "Grid",
            "L06": "Scope",
            "L07": "DTG",
            "L08": "Expires",
            "L09": "Status",
            "L10": "Narrative",
        }
        mappings = {
            "Prec": {"R": "Routine", "P": "Priority", "I": "Immediate", "F": "Flash"},
            "Scope": {"L": "Local", "R": "Regional", "N": "National", "U": "Unknown"},
            "Status": {"N": "New", "O": "On Going", "R": "Resolved", "U": "Unknown"},
        }
        parsed = MessageViewerTab._parse_form_fields(text, field_titles, mappings)
        if "Narrative" in parsed:
            parsed["Narrative"] = parsed["Narrative"].replace("\\n\\n", "\n\n").replace("\\n", "\n")
        return MessageViewerTab._format_fields_table(parsed, "Narrative")

    @staticmethod
    def _parse_statrep_content(text: str) -> str:
        field_titles = {
            "L01a": "To",
            "L01b": "From",
            "L02": "Scope",
            "L03": "DTG",
            "L04": "State",
            "L05": "Grid",
            "L06": "Map Pin",
            "L07": "Power",
            "L08": "Pub Water",
            "L09": "Medical",
            "L10": "Ovr Air Comms",
            "L11": "Travl Cndtns",
            "L12": "Internet",
            "L13": "Fuel",
            "L14": "Food",
            "L15": "Criminal Act",
            "L16": "Civil",
            "L17": "Political",
            "L18": "Remarks or Narrative",
        }
        status_mapping = {"G": "Green", "Y": "Yellow", "R": "Red", "U": "Unknown"}
        mappings = {
            "Scope": {"C": "My Community", "N": "My County", "R": "My Region", "O": "Other Location"},
            "Map Pin": status_mapping,
            "Power": status_mapping,
            "Pub Water": status_mapping,
            "Medical": status_mapping,
            "Ovr Air Comms": status_mapping,
            "Travl Cndtns": status_mapping,
            "Internet": status_mapping,
            "Fuel": status_mapping,
            "Food": status_mapping,
            "Criminal Act": status_mapping,
            "Civil": status_mapping,
            "Political": status_mapping,
        }
        parsed = MessageViewerTab._parse_form_fields(text, field_titles, mappings)
        if not parsed.get("Scope", "").strip():
            parsed["Scope"] = "My Location"
        return MessageViewerTab._format_fields_table(parsed, "Remarks or Narrative")

    @staticmethod
    def _parse_b2s_form_content(text: str) -> str:
        parsed = {
            "From": MessageViewerTab._match_field(text, r":hdr_fm:\s*(.*?)\s*(?=:)"),
            "DTG": MessageViewerTab._match_field(text, r":hdr_ed:\s*(.*?)\s*(?=:)"),
            "Prec": MessageViewerTab._match_field(text, r":prec:\s*(.*?)\s*(?=:)"),
            "Subject": MessageViewerTab._match_field(text, r":sub:\s*(.*?)\s*(?=:)"),
            "Message": MessageViewerTab._match_field(text, r":mg:\s*(.*)$"),
        }
        prec_mapping = {"R": "Routine", "P": "Priority", "I": "Immediate", "F": "Flash"}
        parsed["Prec"] = prec_mapping.get(parsed["Prec"].upper(), parsed["Prec"])
        return MessageViewerTab._format_fields_table(parsed, "Message")

    @staticmethod
    def _is_transport_form_ext(ext: str) -> bool:
        return str(ext or "").strip().lower() in {".b2s", ".k2s"}

    @staticmethod
    def _match_field(text: str, pattern: str) -> str:
        return _match_field_text(text, pattern)

    @staticmethod
    def _extract_hdr_call(text: str, marker: str) -> str:
        return _extract_hdr_call_text(text, marker)

    def _delete_file_record(self, rec: FileRecord) -> None:
        if not rec or not rec.path.exists():
            return
        audit_row = self._delete_audit_row_for_payload(rec)
        bbs_context = self._bbs_file_management_context_for_record(rec)
        if bbs_context:
            title = "Delete BBS File"
            label = str(bbs_context.get("label", "") or "CommsPlan-managed BBS area").strip()
            prompt = (
                f"Delete this file from {label}?\n\n"
                f"{rec.path}\n\n"
                "Use Archive instead when the file may be needed later."
            )
            if not self._confirm_single_delete(audit_row, prompt):
                return
            result = delete_bbs_file(rec.path)
            if not result.success:
                self._record_message_delete_audit(audit_row, result="failed", detail=result.detail, batch_id="single")
                QMessageBox.warning(self, title, f"Failed to delete file:\n{result.detail}")
                return
            self._record_message_delete_audit(audit_row, result="deleted", detail=result.detail, batch_id="single")
            self._remember_locally_deleted_row(audit_row)
            self._unfreeze_table()
            self._populate_messages_table(force=True)
            return
        title = "Delete File"
        if not self._confirm_single_delete(audit_row, "Delete this file-backed message?"):
            return
        outcome = self._execute_message_delete(audit_row)
        if outcome.result != "deleted":
            self._record_message_delete_audit(audit_row, result=outcome.result, detail=message_delete_result_detail(rec, outcome.detail_key), batch_id="single")
            if outcome.result == "failed":
                QMessageBox.warning(self, title, outcome.warning or "Failed to move file to the Recycle Bin.")
            return
        self._record_message_delete_audit(audit_row, result="deleted", detail=message_delete_result_detail(rec, outcome.detail_key), batch_id="single")
        self._remember_locally_deleted_row(audit_row)
        self._unfreeze_table()
        self._populate_messages_table(force=True)

    def _archive_file_record(self, rec: FileRecord) -> None:
        if not rec:
            return
        bbs_context = self._bbs_file_management_context_for_record(rec)
        if not bbs_context:
            return
        if self._is_bbs_archive_record(rec):
            QMessageBox.information(self, "Archive BBS File", "This file is already in the BBS Archive.")
            return
        if not rec.path.exists():
            QMessageBox.warning(self, "Archive BBS File", "The selected file no longer exists.")
            return
        archive_dir_txt = (self.settings.get("varac_bbs_archive_dir", "") or "").strip()
        if not archive_dir_txt:
            QMessageBox.warning(
                self,
                "Archive BBS File",
                "Set VarAC BBS Archive in Configuration before archiving files.",
            )
            return
        archive_dir = Path(archive_dir_txt)
        if not archive_dir.exists() or not archive_dir.is_dir():
            QMessageBox.warning(
                self,
                "Archive BBS File",
                "Configured BBS Archive is not a valid directory.",
            )
            return
        source_label = str(bbs_context.get("label", "") or "BBS file area").strip()
        source_root = str(bbs_context.get("path", "") or "").strip()
        archive_context = str(bbs_context.get("archive_context", "") or "live").strip() or "live"
        archive_target_dir = archive_dir / archive_context
        details = (
            f"Archive this BBS file?\n\n"
            f"{rec.path}\n"
            f"Source: {source_label}\n"
            f"Destination: {archive_target_dir}"
        )
        resp = QMessageBox.question(self, "Archive BBS File", details, QMessageBox.Yes | QMessageBox.No)
        if resp != QMessageBox.Yes:
            return
        result = archive_bbs_file(
            rec.path,
            archive_dir=archive_dir,
            source_root=source_root,
            archive_context=archive_context,
        )
        if not result.success:
            QMessageBox.warning(self, "Archive BBS File", f"Failed to archive file:\n{result.detail}")
            return
        dst = Path(result.target_path)
        old_key = self._read_state_key(rec.origin, rec)
        prior_state = self._read_state_map.get(old_key)
        try:
            moved_stat = dst.stat()
            moved_rec = FileRecord(
                path=Path(dst),
                origin="bbs",
                size=int(moved_stat.st_size or 0),
                mtime=float(moved_stat.st_mtime or 0.0),
            )
        except Exception:
            moved_rec = FileRecord(path=Path(dst), origin="bbs", size=int(rec.size or 0), mtime=float(rec.mtime or 0.0))
        log.info("MessageViewer: archived BBS file %s -> %s", rec.path, dst)
        self._remove_file_record(rec)
        if prior_state:
            status, read_ts, flag_state = prior_state
            moved_key = self._read_state_key(moved_rec.origin, moved_rec)
            self._read_state_map[moved_key] = (
                str(status or "").upper(),
                float(read_ts or 0.0),
                int(flag_state or 0),
            )
            self._persist_file_read_state(
                moved_rec.origin,
                str(moved_rec.path),
                float(moved_rec.mtime),
                int(moved_rec.size),
                str(status or "").upper(),
                float(read_ts or 0.0),
                int(flag_state or 0),
            )
        self._unfreeze_table()
        self._populate_messages_table(force=True)

    def _delete_projected_file_message(self, row: UnifiedMessage) -> None:
        payload = getattr(row, "payload", None)
        if not isinstance(payload, ProjectedMessagePayload):
            return
        rec = self._projected_file_record(payload)
        if rec is None:
            self._delete_projected_message(row)
            return
        before_exists = rec.path.exists()
        self._delete_file_record(rec)
        if before_exists and not rec.path.exists():
            self._mark_projection_rows_deleted([row], source_scope="projected_file")

    def _archive_projected_file_message(self, row: UnifiedMessage) -> None:
        payload = getattr(row, "payload", None)
        if not isinstance(payload, ProjectedMessagePayload):
            return
        rec = self._projected_file_record(payload)
        if rec is None:
            QMessageBox.warning(self, "Archive BBS File", "The projected file reference is no longer available.")
            return
        before_exists = rec.path.exists()
        self._archive_file_record(rec)
        if before_exists and not rec.path.exists():
            self._mark_projection_rows_deleted([row], source_scope="projected_file_archive")

    def _file_record_for_message_row(
        self,
        row: UnifiedMessage | None,
        *,
        allow_detail_lookup: bool = False,
    ) -> FileRecord | None:
        payload = getattr(row, "payload", None) if row is not None else None
        if isinstance(payload, FileRecord):
            return payload
        if isinstance(payload, ProjectedMessagePayload):
            return self._projected_file_record(payload, allow_detail_lookup=allow_detail_lookup)
        return None

    def _row_supports_managed_bbs_publication(self, row: UnifiedMessage | None) -> bool:
        """Return eligibility from already-loaded row data without BBS I/O."""

        rec = self._file_record_for_message_row(row, allow_detail_lookup=False)
        return isinstance(rec, FileRecord) and str(rec.origin or "").strip().lower() in {
            "flmsg",
            "flamp",
            "varac",
        }

    def _eligible_bbs_publication_rows(
        self,
        rows: Sequence[UnifiedMessage],
    ) -> List[UnifiedMessage]:
        eligible: List[UnifiedMessage] = []
        seen_paths: set[str] = set()
        for row in list(rows)[:200]:
            if not MessageViewerTab._row_supports_managed_bbs_publication(self, row):
                continue
            rec = self._file_record_for_message_row(row, allow_detail_lookup=False)
            key = self._bbs_copy_session_key_for_record(rec)
            if key is None or key[0] in seen_paths:
                continue
            seen_paths.add(key[0])
            eligible.append(row)
        return eligible

    def _can_copy_row_to_varac_bbs(self, row: UnifiedMessage | None) -> bool:
        if not MessageViewerTab._row_supports_managed_bbs_publication(self, row):
            return False
        if not self._varac_bbs_copy_targets():
            return False
        return True

    @staticmethod
    def _bbs_copy_session_key_for_record(rec: FileRecord | None) -> tuple[str, float, int] | None:
        if not isinstance(rec, FileRecord):
            return None
        # This key is also used by the paint-time action snapshot.  Keep it
        # lexical: Path.resolve() may touch the filesystem on some platforms.
        path_txt = os.path.abspath(os.fspath(rec.path))
        path_key = os.path.normcase(os.path.normpath(path_txt))
        try:
            mtime_key = round(float(rec.mtime or 0.0), 6)
        except Exception:
            mtime_key = 0.0
        try:
            size_key = int(rec.size or 0)
        except Exception:
            size_key = 0
        return (path_key, mtime_key, size_key)

    def _cached_row_in_varac_bbs(self, row: UnifiedMessage | None) -> bool:
        """Return only already-loaded BBS publication state for row painting."""

        key = self._bbs_copy_session_key_for_row(row)
        if key is None:
            return False
        known = getattr(self, "_reader_bbs_known_counts", {})
        if key in known:
            return int(known.get(key, 0) or 0) > 0
        if any(tuple(marker[:3]) == key for marker in self._bbs_copied_session_keys):
            return True
        published = getattr(self, "_bbs_published_index_cache", {})
        return bool(set(published.get(key[0], set()))) if isinstance(published, dict) else False

    def _bbs_copy_session_key_for_row(self, row: UnifiedMessage | None) -> tuple[str, float, int] | None:
        return MessageViewerTab._bbs_copy_session_key_for_record(
            self._file_record_for_message_row(row, allow_detail_lookup=False)
        )

    def _bbs_copy_session_marker(self, row: UnifiedMessage | None, target_id: str) -> tuple[str, float, int, str] | None:
        key = self._bbs_copy_session_key_for_row(row)
        if key is None:
            return None
        return (*key, str(target_id or "live"))

    @staticmethod
    def _split_varac_bbs_safe_suffix(name: str) -> tuple[str, str]:
        return split_varac_bbs_safe_suffix(name)

    @staticmethod
    def _safe_varac_bbs_filename(name: str, *, max_len: int = 180) -> str:
        return safe_varac_bbs_filename(name, max_len=max_len)

    @staticmethod
    def _unique_varac_bbs_destination(dst: Path) -> Path | None:
        return unique_destination(dst)

    @staticmethod
    def _file_record_matches_path(rec: FileRecord, path_obj: Path) -> bool:
        try:
            st = path_obj.stat()
        except Exception:
            return False
        try:
            if int(st.st_size) != int(rec.size or 0):
                return False
        except Exception:
            return False
        try:
            return abs(float(st.st_mtime) - float(rec.mtime or 0.0)) <= 1e-6
        except Exception:
            return False

    def _bbs_location_inventory_by_id(self) -> Dict[str, object]:
        inventory = build_bbs_inventory(self.settings, allowed_exts=ORIGIN_EXTS.get("bbs", set(SUPPORTED_EXT)))
        return {loc.id: loc for loc in inventory.locations}

    def _varac_bbs_copy_targets(self) -> List[Dict[str, object]]:
        now = time.monotonic()
        cached = getattr(self, "_bbs_copy_targets_cache", [])
        cached_ts = float(getattr(self, "_bbs_copy_targets_cache_ts", 0.0) or 0.0)
        if cached and (now - cached_ts) < 5.0:
            return list(cached)
        targets: List[Dict[str, object]] = []
        try:
            db_path = bbs_library_db_path_from_settings(self.settings)
            with connect_sqlite(db_path) as conn:
                locations = list_bbs_locations(conn, include_disabled=True)
                default_row = conn.execute(
                    "SELECT value FROM bbs_library_meta WHERE key='station_default_location_id' LIMIT 1"
                ).fetchone()
            default_id = str(default_row[0] or "") if default_row else ""
            for location in locations:
                targets.append(
                    {
                        "id": f"location:{location.location_id}",
                        "kind": "location",
                        "label": location.name,
                        "bbs_label": location.name,
                        "location_id": location.location_id,
                        "location_name": location.name,
                        "detail": (
                            f"Access: {location.access_rule}; retention: {location.retention_mode}; "
                            f"source: {location.source_dir or 'catalog artifact'}"
                        ),
                        "path": Path(location.source_dir).expanduser() if location.source_dir else None,
                        "valid": bool(location.enabled),
                        "is_default": location.location_id == default_id,
                    }
                )
        except Exception as exc:
            log.debug("MessageViewer: station BBS targets unavailable: %s", exc)
        self._bbs_copy_targets_cache = list(targets)
        self._bbs_copy_targets_cache_ts = now
        return targets

    def _invalidate_bbs_action_cache(self) -> None:
        self._bbs_copy_targets_cache = []
        self._bbs_copy_targets_cache_ts = 0.0
        self._bbs_published_index_cache = {}
        self._bbs_published_index_cache_ts = 0.0

    def _managed_bbs_published_target_ids_for_record(self, rec: FileRecord | None) -> Set[str]:
        if not isinstance(rec, FileRecord):
            return set()
        managed_targets = [
            target
            for target in self._varac_bbs_copy_targets()
            if str(target.get("kind", "") or "") == "location"
            and str(target.get("location_id", "") or "").strip()
        ]
        if not managed_targets:
            return set()
        try:
            resolved = str(rec.path.resolve())
        except Exception:
            resolved = str(rec.path)
        norm_resolved = os.path.normcase(os.path.normpath(resolved))
        now = time.monotonic()
        cache_ts = float(getattr(self, "_bbs_published_index_cache_ts", 0.0) or 0.0)
        if (now - cache_ts) < 5.0:
            return set(getattr(self, "_bbs_published_index_cache", {}).get(norm_resolved, set()))
        published_index: Dict[str, Set[str]] = {}
        try:
            db_path = bbs_library_db_path_from_settings(self.settings)
            with connect_sqlite(db_path) as conn:
                ensure_bbs_library_schema(conn)
                rows = conn.execute(
                    """
                    SELECT a.source_path, la.location_id
                    FROM bbs_artifacts a
                    JOIN bbs_location_artifacts la ON la.artifact_id=a.artifact_id
                    WHERE la.publish_enabled=1
                    """
                ).fetchall()
                for row_path_raw, location_id_raw in rows:
                    try:
                        row_path = str(Path(str(row_path_raw or "")).resolve())
                    except Exception:
                        row_path = str(row_path_raw or "")
                    path_key = os.path.normcase(os.path.normpath(row_path))
                    published_index.setdefault(path_key, set()).add(f"location:{str(location_id_raw or '')}")
        except Exception:
            return set()
        self._bbs_published_index_cache = published_index
        self._bbs_published_index_cache_ts = now
        return set(published_index.get(norm_resolved, set()))

    def _select_varac_bbs_publish_targets(self, row: UnifiedMessage | None) -> Optional[List[Dict[str, object]]]:
        targets = [target for target in self._varac_bbs_copy_targets() if bool(target.get("valid", False))]
        if not targets:
            return None
        rec = self._file_record_for_message_row(row, allow_detail_lookup=False)
        published_ids = self._managed_bbs_published_target_ids_for_record(rec)
        preferred_id = self._bbs_copy_target_session_id
        if not preferred_id:
            preferred = next((target for target in targets if bool(target.get("is_default", False))), None)
            if preferred is not None:
                preferred_id = str(preferred.get("id", "") or "")
        dialog = QDialog(self)
        dialog.setWindowTitle("Manage BBS Locations")
        layout = QVBoxLayout(dialog)
        intro = QLabel("Select every BBS location where this file should be available.")
        intro.setWordWrap(True)
        layout.addWidget(intro)

        list_widget = QListWidget(dialog)
        list_widget.setMinimumHeight(220)
        for target in targets:
            label = str(target.get("label", "") or target.get("bbs_label", "") or "BBS")
            detail = str(target.get("detail", "") or "")
            item = QListWidgetItem(f"{label}\n{detail}")
            item.setData(Qt.UserRole, target)
            item.setFlags(item.flags() | Qt.ItemIsUserCheckable)
            target_id = str(target.get("id", "") or "")
            checked = target_id in published_ids or (not published_ids and preferred_id and target_id == preferred_id)
            item.setCheckState(Qt.Checked if checked else Qt.Unchecked)
            list_widget.addItem(item)
        layout.addWidget(list_widget)

        note = QLabel(
            "These checkboxes update the one station Managed BBS catalog. Each enabled radio publishes the same selections "
            "to its own live BBS folder; the received source file is never moved or deleted."
        )
        note.setWordWrap(True)
        layout.addWidget(note)
        buttons = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel, dialog)
        apply_button = buttons.button(QDialogButtonBox.Ok)
        if apply_button is not None:
            apply_button.setText("Apply")
        buttons.accepted.connect(dialog.accept)
        buttons.rejected.connect(dialog.reject)
        layout.addWidget(buttons)
        if dialog.exec() != QDialog.Accepted:
            return None
        selected: List[Dict[str, object]] = []
        for index in range(list_widget.count()):
            item = list_widget.item(index)
            if item.checkState() != Qt.Checked:
                continue
            target = item.data(Qt.UserRole)
            if isinstance(target, dict):
                selected.append(target)
        if selected:
            self._bbs_copy_target_session_id = str(selected[0].get("id", "") or "")
        return selected

    def _select_varac_bbs_copy_target(self) -> Optional[Dict[str, object]]:
        targets = self._select_varac_bbs_publish_targets(None) or []
        return targets[0] if targets else None

    def _varac_bbs_destination_for_row(
        self,
        row: UnifiedMessage | None,
        *,
        unique: bool = False,
        target: Optional[Dict[str, object]] = None,
    ) -> Path | None:
        if not self._can_copy_row_to_varac_bbs(row):
            return None
        rec = self._file_record_for_message_row(row, allow_detail_lookup=False)
        if not isinstance(rec, FileRecord):
            return None
        if target is None:
            bbs_dir_txt = (self.settings.get("varac_bbs_dir", "") or "").strip()
            target_dir = Path(bbs_dir_txt) if bbs_dir_txt else None
        else:
            target_dir_obj = target.get("path")
            target_dir = Path(target_dir_obj) if target_dir_obj else None
        if target_dir is None:
            return None
        if not target_dir.exists() or not target_dir.is_dir():
            return None
        safe_name = MessageViewerTab._safe_varac_bbs_filename(rec.path.name)
        dst = target_dir / safe_name
        if not unique:
            return dst
        return MessageViewerTab._unique_varac_bbs_destination(dst)

    def _is_row_already_in_varac_bbs(
        self,
        row: UnifiedMessage | None,
        *,
        target: Optional[Dict[str, object]] = None,
    ) -> bool:
        rec = self._file_record_for_message_row(row, allow_detail_lookup=False)
        if not isinstance(rec, FileRecord):
            return False
        target_id = str((target or {}).get("id", "") or "live")
        if str((target or {}).get("kind", "") or "") == "location":
            return target_id in self._managed_bbs_published_target_ids_for_record(rec)
        dst = self._varac_bbs_destination_for_row(row, target=target)
        if dst is None:
            return False
        marker = self._bbs_copy_session_marker(row, target_id)
        if marker is not None and marker in self._bbs_copied_session_keys:
            return True
        try:
            if rec.path.resolve() == dst.resolve():
                return True
        except Exception:
            pass
        if not dst.exists():
            return False
        if dst.name == rec.path.name:
            return True
        return MessageViewerTab._file_record_matches_path(rec, dst)

    def _is_row_bbs_copy_action_enabled(self, row: UnifiedMessage | None) -> bool:
        if not self._can_copy_row_to_varac_bbs(row):
            return False
        return any(bool(target.get("valid", False)) for target in self._varac_bbs_copy_targets())

    def _mark_row_copied_to_varac_bbs_session(self, row: UnifiedMessage | None, target_id: str) -> None:
        marker = self._bbs_copy_session_marker(row, target_id)
        if marker is None:
            return
        self._bbs_copied_session_keys.add(marker)

    def _publish_row_to_managed_bbs_target(
        self,
        row: UnifiedMessage,
        rec: FileRecord,
        target: Dict[str, object],
    ) -> tuple[bool, str]:
        location_id = str(target.get("location_id", "") or "").strip()
        if not location_id:
            return False, "Managed BBS target is missing a location id."
        location_name = str(target.get("location_name", "") or target.get("bbs_label", "") or location_id).strip() or location_id
        try:
            db_path = bbs_library_db_path_from_settings(self.settings)
            with connect_sqlite(db_path) as conn:
                ensure_bbs_library_schema(conn)
                with conn:
                    if not conn.execute(
                        "SELECT 1 FROM bbs_locations WHERE location_id=? LIMIT 1",
                        (location_id,),
                    ).fetchone():
                        return False, f"{location_name}: managed location no longer exists"
                    artifact_id = upsert_bbs_artifact_path(
                        conn,
                        source_path=rec.path,
                        source_kind="message_file",
                        source_id=str(getattr(row, "id", "") or getattr(row, "source_id", "") or ""),
                        display_name=rec.path.name,
                        metadata={
                            "msg_type": str(getattr(row, "msg_type", "") or ""),
                            "subject": str(getattr(row, "subject", "") or ""),
                            "origin": str(getattr(rec, "origin", "") or ""),
                        },
                    )
                    current = set(list_bbs_artifact_location_ids(conn, artifact_id))
                    current.add(location_id)
                    set_bbs_artifact_locations(
                        conn,
                        artifact_id=artifact_id,
                        location_ids=current,
                    )
            self._mark_row_copied_to_varac_bbs_session(row, str(target.get("id", "") or location_id))
            return True, f"{location_name}: published by DB mapping"
        except Exception as exc:
            return False, f"{location_name}: {exc}"

    def _varac_bbs_existing_copy_targets(self, row: UnifiedMessage | None) -> List[Dict[str, object]]:
        if not self._can_copy_row_to_varac_bbs(row):
            return []
        rec = self._file_record_for_message_row(row, allow_detail_lookup=False)
        if not isinstance(rec, FileRecord):
            return []
        existing: List[Dict[str, object]] = []
        managed_published_ids = self._managed_bbs_published_target_ids_for_record(rec)
        for target in self._varac_bbs_copy_targets():
            target_id = str(target.get("id", "") or "")
            if str(target.get("kind", "") or "") == "location" and target_id in managed_published_ids:
                candidate = dict(target)
                candidate["copied_path"] = Path(str(target.get("path", "") or ""))
                candidate["managed_membership"] = True
                existing.append(candidate)
                continue
            if not bool(target.get("valid", False)):
                continue
            dst = self._varac_bbs_destination_for_row(row, target=target)
            if dst is None:
                continue
            try:
                same_source = rec.path.resolve() == dst.resolve()
            except Exception:
                same_source = False
            if same_source:
                continue
            if not dst.exists() or not dst.is_file():
                continue
            if dst.name == rec.path.name or MessageViewerTab._file_record_matches_path(rec, dst):
                candidate = dict(target)
                candidate["copied_path"] = dst
                existing.append(candidate)
        return existing

    def _remove_row_from_varac_bbs(self, row: UnifiedMessage | None, *, confirm: bool = True) -> None:
        rec = self._file_record_for_message_row(row, allow_detail_lookup=False)
        existing = self._varac_bbs_existing_copy_targets(row)
        if not existing:
            return
        if confirm:
            removal_lines: List[str] = []
            for target in existing[:5]:
                if bool(target.get("managed_membership", False)):
                    label = str(
                        target.get("location_name", "")
                        or target.get("label", "")
                        or "Managed BBS"
                    )
                    removal_lines.append(f"Managed BBS: {label}")
                else:
                    removal_lines.append(str(target.get("copied_path", "") or ""))
            file_list = "\n".join(removal_lines)
            more = f"\n...and {len(existing) - 5} more" if len(existing) > 5 else ""
            resp = QMessageBox.question(
                self,
                "Remove From BBS",
                "Remove BBS published mapping/copy for this message?\n\n"
                "The original received file/message will not be deleted.\n\n"
                f"{file_list}{more}",
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No,
            )
            if resp != QMessageBox.Yes:
                return
        removed = 0
        errors: List[str] = []
        for target in existing:
            if bool(target.get("managed_membership", False)):
                location_id = str(target.get("location_id", "") or "").strip()
                try:
                    db_path = bbs_library_db_path_from_settings(self.settings)
                    with connect_sqlite(db_path) as conn:
                        with conn:
                            removed += unpublish_bbs_artifact_path_from_location(
                                conn,
                                source_path=rec.path if isinstance(rec, FileRecord) else "",
                                location_id=location_id,
                            )
                except Exception as e:
                    errors.append(f"{target.get('label', 'Managed BBS')}: {e}")
                continue
            copied_path = target.get("copied_path")
            path = copied_path if isinstance(copied_path, Path) else Path(str(copied_path or ""))
            try:
                if path.exists() and path.is_file():
                    path.unlink()
                    removed += 1
            except Exception as e:
                errors.append(f"{path}: {e}")
            target_id = str(target.get("id", "") or "live")
            marker = self._bbs_copy_session_marker(row, target_id)
            if marker is not None:
                self._bbs_copied_session_keys.discard(marker)
        if errors:
            QMessageBox.warning(self, "Remove From BBS", "Some BBS artifacts could not be removed:\n" + "\n".join(errors[:5]))
        elif confirm:
            QMessageBox.information(
                self,
                "Remove From BBS",
                f"Removed {removed} copied BBS artifact(s). The original message/file was left in place.",
            )
        key = self._bbs_copy_session_key_for_row(row)
        if key is not None:
            self._reader_bbs_known_counts[key] = 0
        self._invalidate_bbs_action_cache()
        self._unfreeze_table()
        self._populate_messages_table(force=True)

    def _copy_row_to_varac_bbs(
        self,
        row: UnifiedMessage | None,
        *,
        show_confirmation: bool = True,
    ) -> int | None:
        if row is None or not MessageViewerTab._row_supports_managed_bbs_publication(self, row):
            return None
        if not self._is_row_bbs_copy_action_enabled(row):
            QMessageBox.information(
                self,
                "Managed BBS",
                "No enabled Managed BBS locations are available. Add or enable a location in the BBS service first.",
            )
            return None
        rec = self._file_record_for_message_row(row, allow_detail_lookup=False)
        if not isinstance(rec, FileRecord):
            return None
        src = rec.path
        if not src.exists() or not src.is_file():
            QMessageBox.warning(self, "Copy to VarAC BBS", "The selected source file no longer exists.")
            return None
        targets = self._select_varac_bbs_publish_targets(row)
        if targets is None:
            return None
        selected_location_ids = [
            str(target.get("location_id", "") or "").strip()
            for target in targets
            if str(target.get("location_id", "") or "").strip()
        ]
        try:
            db_path = bbs_library_db_path_from_settings(self.settings)
            with connect_sqlite(db_path) as conn:
                with conn:
                    artifact_id = upsert_bbs_artifact_path(
                        conn,
                        source_path=rec.path,
                        source_kind="message_file",
                        source_id=str(getattr(row, "id", "") or getattr(row, "source_id", "") or ""),
                        display_name=rec.path.name,
                        metadata={
                            "msg_type": str(getattr(row, "msg_type", "") or ""),
                            "subject": str(getattr(row, "subject", "") or ""),
                            "origin": str(getattr(rec, "origin", "") or ""),
                        },
                    )
                    set_bbs_artifact_locations(
                        conn,
                        artifact_id=artifact_id,
                        location_ids=selected_location_ids,
                    )
        except Exception as exc:
            QMessageBox.warning(self, "Publish to BBS", f"Managed BBS update failed:\n{exc}")
            return None
        selected_names = [str(target.get("label", "") or "Managed BBS") for target in targets]
        if selected_names:
            message = "Published through the station Managed BBS catalog:\n" + "\n".join(
                f"- {name}" for name in selected_names[:10]
            )
        else:
            message = "Publication was removed from all Managed BBS locations. The source file remains unchanged."
        if show_confirmation:
            QMessageBox.information(
                self,
                "Managed BBS Updated",
                message,
            )
        key = self._bbs_copy_session_key_for_row(row)
        if key is not None:
            self._reader_bbs_known_counts[key] = len(selected_location_ids)
        self._invalidate_bbs_action_cache()
        self._unfreeze_table()
        self._populate_messages_table(force=True)
        return len(selected_location_ids)

    def _publish_selected_messages_to_bbs(self) -> None:
        selected_rows = self._messages_model.selected_rows() if hasattr(self, "_messages_model") else []
        eligible_rows = self._eligible_bbs_publication_rows(selected_rows)
        if not eligible_rows:
            QMessageBox.information(
                self,
                "Publish Selected to BBS",
                "Select at least one FLMsg, FLAmp, or VarAC message file.",
            )
            return
        targets = self._select_varac_bbs_publish_targets(None)
        if targets is None:
            return
        location_ids = {
            str(target.get("location_id", "") or "").strip()
            for target in targets
            if str(target.get("location_id", "") or "").strip()
        }
        if not location_ids:
            QMessageBox.information(
                self,
                "Publish Selected to BBS",
                "No BBS locations were selected. Existing publication memberships were unchanged.",
            )
            return
        published = 0
        missing = 0
        try:
            db_path = bbs_library_db_path_from_settings(self.settings)
            with connect_sqlite(db_path) as conn:
                with conn:
                    for row in eligible_rows:
                        rec = self._file_record_for_message_row(row, allow_detail_lookup=False)
                        if not isinstance(rec, FileRecord) or not rec.path.exists() or not rec.path.is_file():
                            missing += 1
                            continue
                        try:
                            artifact_id = upsert_bbs_artifact_path(
                                conn,
                                source_path=rec.path,
                                source_kind="message_file",
                                source_id=str(
                                    getattr(row, "id", "")
                                    or getattr(row, "source_id", "")
                                    or ""
                                ),
                                display_name=rec.path.name,
                                metadata={
                                    "msg_type": str(getattr(row, "msg_type", "") or ""),
                                    "subject": str(getattr(row, "subject", "") or ""),
                                    "origin": str(getattr(rec, "origin", "") or ""),
                                },
                            )
                        except FileNotFoundError:
                            missing += 1
                            continue
                        current = set(list_bbs_artifact_location_ids(conn, artifact_id))
                        current.update(location_ids)
                        set_bbs_artifact_locations(
                            conn,
                            artifact_id=artifact_id,
                            location_ids=current,
                        )
                        published += 1
        except Exception as exc:
            QMessageBox.warning(
                self,
                "Publish Selected to BBS",
                f"No bulk publication changes were applied:\n{exc}",
            )
            return
        ineligible = max(0, len(selected_rows) - len(eligible_rows))
        details = [
            f"Published {published} message file{'s' if published != 1 else ''} to "
            f"{len(location_ids)} BBS location{'s' if len(location_ids) != 1 else ''}."
        ]
        if missing:
            details.append(f"Skipped {missing} missing source file{'s' if missing != 1 else ''}.")
        if ineligible:
            details.append(
                f"Skipped {ineligible} selected item{'s' if ineligible != 1 else ''} "
                "not eligible for Managed BBS publication."
            )
        details.append("Existing memberships in other locations and all source files were preserved.")
        QMessageBox.information(self, "Managed BBS Updated", "\n".join(details))
        self._invalidate_bbs_action_cache()
        self._unfreeze_table()
        self._populate_messages_table(force=True)

    @staticmethod
    def _is_flamp_relay_payload_name(name: object) -> bool:
        return Path(str(name or "")).suffix.lower() in {".b2s", ".k2s"}

    @staticmethod
    def _flamp_relay_validation_key(rec: FileRecord) -> tuple[str, float, int]:
        try:
            path_txt = str(rec.path.resolve())
        except Exception:
            path_txt = str(rec.path)
        try:
            mtime_key = round(float(rec.mtime or 0.0), 6)
        except Exception:
            mtime_key = 0.0
        try:
            size_key = int(rec.size or 0)
        except Exception:
            size_key = 0
        return (os.path.normcase(os.path.normpath(path_txt)), mtime_key, size_key)

    def _parsed_flamp_relay_file(self, rec: FileRecord | None) -> Optional[Dict[str, object]]:
        if not isinstance(rec, FileRecord):
            return None
        if not self._is_flamp_relay_payload_name(rec.path.name):
            return None
        if not rec.path.exists() or not rec.path.is_file():
            return None
        key = self._flamp_relay_validation_key(rec)
        if key in self._flamp_relay_parse_cache:
            return self._flamp_relay_parse_cache.get(key)
        parsed: Optional[Dict[str, object]]
        try:
            parsed = FlampRelayStore(rec.path.parent).parse_file(rec.path)
        except Exception:
            parsed = None
        if not parsed or not parsed.get("blocks"):
            parsed = None
        self._flamp_relay_parse_cache[key] = parsed
        self._flamp_relay_validation_cache[key] = bool(parsed)
        return parsed

    def _is_valid_flamp_relay_file(self, rec: FileRecord | None) -> bool:
        if not isinstance(rec, FileRecord):
            return False
        key = self._flamp_relay_validation_key(rec)
        cached = self._flamp_relay_validation_cache.get(key)
        if cached is not None:
            return bool(cached)
        return bool(self._parsed_flamp_relay_file(rec))

    def _flamp_relay_internal_queue_id(self, rec: FileRecord) -> str:
        parsed = self._parsed_flamp_relay_file(rec)
        file_id = str((parsed or {}).get("file_id") or "").strip().upper()
        if FlampRelayStore.VALID_Q_RE.match(file_id):
            return file_id
        return ""

    @staticmethod
    def _flamp_relay_has_queue_id(name: object) -> bool:
        return bool(re.match(r"^[A-Fa-f0-9]{4}", Path(str(name or "")).name))

    @staticmethod
    def _safe_flamp_relay_filename(name: object) -> str:
        text = unicodedata.normalize("NFKC", Path(str(name or "")).name)
        cleaned_chars: List[str] = []
        for ch in text:
            if ch.isspace():
                cleaned_chars.append(" ")
            elif ord(ch) < 32 or ord(ch) == 127 or ch in '/\\:*?"<>|':
                cleaned_chars.append("_")
            else:
                cleaned_chars.append(ch)
        cleaned = re.sub(r"\s+", " ", "".join(cleaned_chars)).strip().rstrip(".")
        return cleaned or "relay-file.k2s"

    def _flamp_relay_source_file_for_row(self, row: UnifiedMessage | None) -> FileRecord | None:
        payload = getattr(row, "payload", None) if row is not None else None
        cached_record = self._file_record_for_message_row(row, allow_detail_lookup=False)
        if isinstance(cached_record, FileRecord) and self._is_flamp_relay_payload_name(cached_record.path.name):
            return cached_record
        if isinstance(payload, VarACMessage):
            matched, _terms, reason = self._find_varac_received_file_for_message(payload)
            if matched is not None and self._is_flamp_relay_payload_name(matched.path.name):
                return matched
            if reason in {"not_found", "low_confidence"} and payload.msg_id not in self._varac_attachment_scan_requested:
                self._varac_attachment_scan_requested.add(payload.msg_id)
                self._refresh_files(force=True)
        return None

    def _flamp_relay_dir(self) -> Path | None:
        raw = str(self.settings.get("varac_bbs_vault_flamp_relay_dir", "") or "").strip()
        if not raw:
            return None
        try:
            return Path(raw).expanduser()
        except Exception:
            return None

    @staticmethod
    def _existing_flamp_relay_queue_ids(relay_dir: Path) -> set[str]:
        ids: set[str] = set()
        try:
            children = list(relay_dir.iterdir())
        except Exception:
            return ids
        for path in children:
            if not path.is_file():
                continue
            match = re.match(r"^([A-Fa-f0-9]{4})", path.name)
            if match:
                ids.add(match.group(1).upper())
        return ids

    @classmethod
    def _strip_flamp_relay_queue_prefix(cls, name: object) -> str:
        safe = cls._safe_flamp_relay_filename(name)
        match = re.match(r"^[A-Fa-f0-9]{4}[_ -]+(.+)$", safe)
        if match and len(match.group(1).strip()) >= 4:
            return match.group(1).strip()
        return safe

    def _flamp_relay_destination_for_record(self, rec: FileRecord) -> tuple[Path | None, str, str]:
        relay_dir = self._flamp_relay_dir()
        if relay_dir is None or not relay_dir.exists() or not relay_dir.is_dir():
            return None, "missing_dir", ""
        if not self._is_valid_flamp_relay_file(rec):
            return None, "not_flamp_payload", ""
        safe_name = self._safe_flamp_relay_filename(rec.path.name)
        if self._flamp_relay_has_queue_id(safe_name):
            queue_id = safe_name[:4].upper()
            existing_ids = self._existing_flamp_relay_queue_ids(relay_dir)
            dst = relay_dir / safe_name
            if queue_id not in existing_ids or dst.exists():
                return dst, "preserved", queue_id
        payload_name = self._strip_flamp_relay_queue_prefix(safe_name)
        internal_queue_id = self._flamp_relay_internal_queue_id(rec)
        if internal_queue_id:
            existing_ids = self._existing_flamp_relay_queue_ids(relay_dir)
            dst = relay_dir / f"{internal_queue_id}_{payload_name}"
            if internal_queue_id not in existing_ids or dst.exists():
                return dst, "extracted", internal_queue_id
            return None, "queue_id_collision", internal_queue_id
        return None, "queue_id_missing", ""

    def _can_copy_row_to_flamp_relay(self, row: UnifiedMessage | None) -> bool:
        if row is None:
            return False
        rec = self._flamp_relay_source_file_for_row(row)
        if rec is None:
            return False
        dst, _mode, _queue_id = self._flamp_relay_destination_for_record(rec)
        return dst is not None

    def _cached_row_in_flamp_relay(self, row: UnifiedMessage | None) -> bool:
        """Return session-known Relay state without parsing or path probing."""

        rec = self._file_record_for_message_row(row, allow_detail_lookup=False)
        if not isinstance(rec, FileRecord) or not self._is_flamp_relay_payload_name(rec.path.name):
            return False
        key = MessageViewerTab._bbs_copy_session_key_for_record(rec)
        return key is not None and key in self._relay_copied_session_keys

    def _relay_copy_session_key_for_row(self, row: UnifiedMessage | None) -> tuple[str, float, int] | None:
        rec = self._flamp_relay_source_file_for_row(row)
        return MessageViewerTab._bbs_copy_session_key_for_record(rec)

    def _is_row_already_in_flamp_relay(self, row: UnifiedMessage | None) -> bool:
        rec = self._flamp_relay_source_file_for_row(row)
        if rec is None:
            return False
        key = self._relay_copy_session_key_for_row(row)
        if key is not None and key in self._relay_copied_session_keys:
            return True
        dst, _mode, _queue_id = self._flamp_relay_destination_for_record(rec)
        if dst is None:
            return False
        try:
            if rec.path.resolve() == dst.resolve():
                return True
        except Exception:
            pass
        if dst.exists() and MessageViewerTab._file_record_matches_path(rec, dst):
            return True
        return False

    def _is_row_relay_copy_action_enabled(self, row: UnifiedMessage | None) -> bool:
        if not self._can_copy_row_to_flamp_relay(row):
            return False
        if self._is_row_already_in_flamp_relay(row):
            return False
        key = self._relay_copy_session_key_for_row(row)
        if key is None:
            return True
        return key not in self._relay_copied_session_keys

    def _mark_row_copied_to_flamp_relay_session(self, row: UnifiedMessage | None) -> None:
        key = self._relay_copy_session_key_for_row(row)
        if key is not None:
            self._relay_copied_session_keys.add(key)

    def _copy_row_to_flamp_relay(self, row: UnifiedMessage | None) -> None:
        if row is None or not self._can_copy_row_to_flamp_relay(row):
            return
        if not self._is_row_relay_copy_action_enabled(row):
            return
        rec = self._flamp_relay_source_file_for_row(row)
        if rec is None:
            QMessageBox.warning(self, "Copy to FLAMP Relay", "CommsPlan could not find the source FLAMP file.")
            return
        if not self._is_valid_flamp_relay_file(rec):
            QMessageBox.warning(
                self,
                "Copy to FLAMP Relay",
                "This .b2s/.k2s file is not a FLAMP relay/block file. It can be viewed, but it cannot be added to FLAMP Relay.",
            )
            return
        src = rec.path
        if not src.exists() or not src.is_file():
            QMessageBox.warning(self, "Copy to FLAMP Relay", "The selected source file no longer exists.")
            return
        dst, mode, queue_id = self._flamp_relay_destination_for_record(rec)
        if dst is None:
            if mode == "missing_dir":
                QMessageBox.warning(
                    self,
                    "Copy to FLAMP Relay",
                    "Set a valid FLAMP Relay folder in Configuration before using +Relay.",
                )
            else:
                QMessageBox.warning(
                    self,
                    "Copy to FLAMP Relay",
                    "CommsPlan could not create a queue-safe FLAMP Relay filename.",
                )
            return
        try:
            if src.resolve() == dst.resolve():
                return
        except Exception:
            pass
        if dst.exists() and MessageViewerTab._file_record_matches_path(rec, dst):
            self._mark_row_copied_to_flamp_relay_session(row)
            self._populate_messages_table(force=True)
            return
        if dst.exists():
            QMessageBox.warning(self, "Copy to FLAMP Relay", f"Destination already exists:\n{dst}")
            return
        try:
            shutil.copy2(str(src), str(dst))
        except Exception as e:
            QMessageBox.warning(self, "Copy to FLAMP Relay", f"Copy failed:\n{e}")
            return
        self._mark_row_copied_to_flamp_relay_session(row)
        if mode == "preserved":
            note = f"Preserved relay queue ID {queue_id}."
        elif mode == "extracted":
            note = f"Used FLAMP file ID {queue_id} as the relay queue ID."
        else:
            note = f"Added relay queue ID {queue_id} so FLAMP Relay can list the file."
        QMessageBox.information(
            self,
            "Copy to FLAMP Relay",
            f"Copied file to FLAMP Relay:\n{dst}\n\n{note}",
        )
        self._unfreeze_table()
        self._populate_messages_table(force=True)

    def _remove_row_from_flamp_relay(self, row: UnifiedMessage | None) -> None:
        """Remove only CommsPlan's Relay copy; never remove the received source."""

        rec = self._file_record_for_message_row(row, allow_detail_lookup=False)
        if not isinstance(rec, FileRecord):
            return
        dst, _mode, _queue_id = self._flamp_relay_destination_for_record(rec)
        if dst is None:
            return
        try:
            same_source = rec.path.resolve() == dst.resolve()
        except Exception:
            same_source = False
        if same_source:
            return
        response = QMessageBox.question(
            self,
            "Remove From FLAMP Relay",
            "Remove the FLAMP Relay copy for this message?\n\n"
            "The original received file will not be deleted.\n\n"
            f"{dst}",
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No,
        )
        if response != QMessageBox.Yes:
            return
        try:
            if dst.exists() and dst.is_file():
                dst.unlink()
        except Exception as exc:
            QMessageBox.warning(self, "Remove From FLAMP Relay", f"Relay copy could not be removed:\n{exc}")
            return
        key = MessageViewerTab._bbs_copy_session_key_for_record(rec)
        if key is not None:
            self._relay_copied_session_keys.discard(key)
        self._unfreeze_table()
        self._populate_messages_table(force=True)

    def _remove_file_record(self, rec: FileRecord) -> None:
        origin = str(rec.origin or "").strip().lower()
        self.files = remove_file_record_from_groups(self.files, rec)
        key = self._read_state_key(origin, rec)
        self._read_state_map.pop(key, None)
        db_path = self._db_path()
        if db_path and db_path.exists():
            delete_file_cache_entries(db_path, rec)
            try:
                delete_observations_by_source_refs(db_path, [f"file:{rec.path}"], source_family=origin)
            except Exception as exc:
                log.debug("MessageViewer: failed to delete file observation projection for %s: %s", rec.path, exc)
        if self.current_record and self.current_record.path == rec.path:
            self.current_record = None
            self._clear_message_detail_view("No file selected")

    @staticmethod
    def _sitrep_message_key(msg: SitrepMessage | None) -> tuple[str, int | str] | None:
        return _core_sitrep_message_key(msg) if isinstance(msg, SitrepMessage) else None

    @staticmethod
    def _commstat_message_key(msg: CommStatArtifact | None) -> tuple[str, str] | None:
        if not isinstance(msg, CommStatArtifact):
            return None
        artifact_key = normalize_commstat_artifact_key(getattr(msg, "artifact_key", ""))
        return ("commstat", artifact_key) if artifact_key else None

    @staticmethod
    def _commstat_tombstone_key(msg: CommStatArtifact | None) -> str:
        if not isinstance(msg, CommStatArtifact):
            return ""
        return commstat_artifact_key(msg)

    def _delete_sitrep_row(self, msg: SitrepMessage) -> bool:
        return _core_delete_sitrep_store_row(self._db_path(), msg)

    def _delete_sitrep_message(self, msg: SitrepMessage) -> None:
        if not msg:
            return
        audit_row = self._delete_audit_row_for_payload(msg)
        label = str(getattr(msg, "report_key", "") or "").strip() or f"event {int(getattr(msg, 'event_id', 0) or 0)}"
        if not self._confirm_single_delete(audit_row, f"Delete SitRep {label}?"):
            return
        outcome = self._execute_message_delete(audit_row)
        if outcome.result != "deleted":
            self._record_message_delete_audit(audit_row, result=outcome.result, detail=message_delete_result_detail(msg, outcome.detail_key), batch_id="single")
            QMessageBox.warning(
                self,
                "Delete Message",
                single_delete_failure_warning(msg, outcome, fallback=f"Failed to delete SitRep {label}."),
            )
            return
        self._finalize_single_delete_success(audit_row, outcome)

    def _delete_commstat_row(self, msg: CommStatArtifact) -> str:
        db_path = self._db_path()
        if not db_path or not db_path.exists():
            return "failed"
        result = delete_commstat_artifact(db_path, msg)
        if not result.artifact_key:
            log.warning(
                "MessageViewer: cannot hide CommStat artifact without artifact_key id=%s title=%s",
                getattr(msg, "artifact_id", 0),
                getattr(msg, "title", ""),
            )
            return "skipped"
        return result.result

